#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum SourceFindingSeverity {
    Blocker,
    Warning,
    Info,
}

impl SourceFindingSeverity {
    fn as_str(self) -> &'static str {
        match self {
            Self::Blocker => "blocker",
            Self::Warning => "warning",
            Self::Info => "info",
        }
    }
}

