fn capability_workflow(
    id: &str,
    title: &str,
    when_to_use: &str,
    first_command: &str,
    follow_up_commands: Vec<String>,
    proof_artifacts: Vec<String>,
    safety_boundary: &str,
) -> CapabilityWorkflow {
    CapabilityWorkflow {
        id: id.into(),
        title: title.into(),
        when_to_use: when_to_use.into(),
        first_command: first_command.into(),
        follow_up_commands,
        proof_artifacts,
        safety_boundary: safety_boundary.into(),
    }
}

