fn capability_next_actions(atlas_path: &Path, root: &Path, limit: usize) -> Vec<CoachAction> {
    let root_arg = root.to_string_lossy();
    vec![
        CoachAction {
            priority: 1,
            title: "Read capability atlas".into(),
            command: Some(format!(
                "rs autopilot capabilities --root {root_arg} --limit {limit} --out {} --format json",
                atlas_path.to_string_lossy()
            )),
            reason: "Refresh verified commands, recipes, and boundaries before deciding the next move.".into(),
            requires_live_studio: false,
            mutates_studio: false,
        },
        CoachAction {
            priority: 2,
            title: "Load project operating rules".into(),
            command: Some(format!(
                "rs autopilot playbook --root {root_arg} --limit {limit} --format json"
            )),
            reason: "Pair tool capabilities with project-specific memory, preferences, canon, and lessons.".into(),
            requires_live_studio: false,
            mutates_studio: false,
        },
        CoachAction {
            priority: 3,
            title: "Start or resume from agenda".into(),
            command: Some(format!(
                "rs autopilot agenda --root {root_arg} --limit {limit} --format json"
            )),
            reason: "Turn the current project state into concrete, bounded AI work items.".into(),
            requires_live_studio: false,
            mutates_studio: false,
        },
    ]
}

pub fn compose(options: ComposeOptions) -> AppResult<()> {
    let (run_dir, plan, preview) = write_compose_artifacts(&options)?;
    if options.json {
        println!(
            "{}",
            serde_json::to_string_pretty(&json!({
                "runDir": run_dir,
                "plan": plan,
                "preview": preview
            }))?
        );
    } else {
        print_plan_summary(&run_dir, &plan, &preview);
    }
    Ok(())
}

pub fn tune(options: TuneOptions) -> AppResult<()> {
    let report = build_tune_report(&options)?;
    write_json(PathBuf::from(&report.manifest_path), &report.manifest)?;
    if !options.no_markdown {
        if let Some(markdown_path) = report.markdown_path.as_ref() {
            write_tune_markdown(PathBuf::from(markdown_path), &report)?;
        }
    }
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_tune_summary(&report);
    }
    Ok(())
}

fn build_tune_report(options: &TuneOptions) -> AppResult<TuneReport> {
    let prompt = options
        .prompt
        .clone()
        .filter(|prompt| !prompt.trim().is_empty())
        .unwrap_or_else(|| {
            options
                .preset
                .as_ref()
                .map(|preset| format!("Tune {preset} Autopilot feature stack"))
                .unwrap_or_else(|| "Tune Autopilot feature stack".into())
        });
    let recipe_names = resolve_tune_recipes(options, &prompt)?;
    let tuned_recipes = recipe_names
        .iter()
        .map(|recipe| tune_recipe(recipe, &prompt))
        .collect::<AppResult<Vec<_>>>()?;
    let recipe_manifests = tuned_recipes
        .iter()
        .map(|recipe| recipe.manifest.clone())
        .collect::<Vec<_>>();
    let manifest = json!({
        "kind": "autopilotCompose",
        "prompt": prompt.clone(),
        "preset": options.preset.clone(),
        "recipes": recipe_manifests,
        "smoke": options.smoke.clone()
    });
    let manifest_path = options
        .out
        .clone()
        .unwrap_or_else(|| default_tune_manifest_path(&prompt));
    let markdown_path = if options.no_markdown {
        None
    } else {
        Some(
            options
                .markdown
                .clone()
                .unwrap_or_else(|| manifest_path.with_extension("md")),
        )
    };
    let compose_command = format!(
        "rs autopilot compose --from-manifest {} --format json",
        manifest_path.display()
    );
    let mut warnings = Vec::new();
    if options.prompt.is_none() {
        warnings.push("No prompt was provided; tuning used preset and recipe defaults.".into());
    }
    let next_actions = vec![
        coach_action(
            1,
            "Review tuned manifest",
            None,
            "Confirm the generated recipe names, currency, prices, rewards, and smoke suite match the creator intent before composing.",
            false,
            false,
        ),
        coach_action(
            2,
            "Compose tuned run",
            Some(compose_command.clone()),
            "Generate a reviewable run from the explicit tuning manifest.",
            false,
            false,
        ),
    ];
    Ok(TuneReport {
        schema_version: "rs.autopilot.tune.v1".into(),
        generated_at: now_stamp(),
        prompt: manifest
            .get("prompt")
            .and_then(Value::as_str)
            .unwrap_or_default()
            .to_string(),
        preset: options.preset.clone(),
        smoke: options.smoke.clone(),
        manifest_path: manifest_path.display().to_string(),
        markdown_path: markdown_path.map(|path| path.display().to_string()),
        compose_command,
        recipes: tuned_recipes,
        manifest,
        assumptions: vec![
            "Tuning is deterministic and offline-only; it does not inspect or mutate Studio.".into(),
            "Recipe-specific objects in the manifest override default generated names and economy values.".into(),
        ],
        warnings,
        next_actions,
    })
}

fn write_compose_artifacts(
    options: &ComposeOptions,
) -> AppResult<(PathBuf, AutopilotPlan, PreviewReport)> {
    let manifest_value = match &options.from_manifest {
        Some(path) => Some(read_json_file(path)?),
        None => None,
    };
    let manifest = manifest_value
        .clone()
        .map(serde_json::from_value::<ComposeManifest>)
        .transpose()?;
    let prompt = compose_prompt(&options, manifest.as_ref())?;
    let recipe_entries = resolve_compose_recipe_entries(
        &options,
        manifest.as_ref(),
        manifest_value.as_ref(),
        &prompt,
    )?;
    let recipes = recipe_entries
        .iter()
        .map(|entry| entry.recipe.clone())
        .collect::<Vec<_>>();
    let smoke = options.smoke.clone().or_else(|| {
        manifest
            .as_ref()
            .and_then(|manifest| manifest.smoke.clone())
    });
    let run_dir = options.out.clone().unwrap_or_else(|| {
        default_run_dir("compose", &format!("{} {}", prompt, recipes.join("-")))
    });
    let generated_dir = run_dir.join("generated");
    std::fs::create_dir_all(&generated_dir)?;

    let plan =
        build_composite_plan_from_entries(&options, &prompt, &recipe_entries, smoke.as_deref())?;
    validate_plan(&plan)?;
    write_generated_files(&plan, &run_dir)?;
    let plan = strip_generated_sources(plan);
    let mut preview = build_preview(&plan);
    attach_preview_integrity(&mut preview, &plan, &run_dir)?;

    let requested_preset = options.preset.clone().or_else(|| {
        manifest
            .as_ref()
            .and_then(|manifest| manifest.preset.clone())
    });
    let request_value = redact_json(&json!({
        "prompt": prompt,
        "studio": options.studio.clone(),
        "scope": options.scope.clone(),
        "port": options.port,
        "preset": requested_preset,
        "recipes": recipe_entries.clone(),
        "fromManifest": options.from_manifest.clone(),
        "smoke": smoke.clone()
    }));
    write_json(run_dir.join("request.json"), &request_value)?;
    write_json(
        run_dir.join("context.json"),
        &RunContext {
            mode: "offline-composition".into(),
            studio: plan.request.studio.clone(),
            scope: plan.request.scope.clone(),
            max_read_depth: 3,
            include_scripts: false,
            include_assets: false,
            collected_at: now_stamp(),
            notes: vec![
                "Autopilot composition combines deterministic recipes into one reviewable plan."
                    .into(),
                "Generated source paths are namespaced by recipe to avoid artifact collisions."
                    .into(),
            ],
        },
    )?;
    write_json(
        run_dir.join("preflight.json"),
        &json!({
            "mode": "offline",
            "checks": [
                {"name": "plan schema", "status": "pass"},
                {"name": "composition recipes", "status": "pass", "value": recipes}
            ]
        }),
    )?;
    write_json(run_dir.join("plan.json"), &plan)?;
    write_json(run_dir.join("preview.json"), &preview)?;
    write_report(&run_dir, &plan, Some(&preview), None)?;

    Ok((run_dir, plan, preview))
}

pub fn run(options: RunOptions) -> AppResult<()> {
    if !options.yes {
        return Err(AppError::Other(
            "autopilot run includes apply; pass --yes after reviewing the generated plan".into(),
        ));
    }
    let manifest_value = match &options.from_manifest {
        Some(path) => Some(read_json_file(path)?),
        None => None,
    };
    let probe_options = PlanOptions {
        port: options.port,
        prompt: options.prompt.clone(),
        studio: options.studio.clone(),
        scope: options.scope.clone(),
        out: options.out.clone(),
        max_read_depth: 3,
        include_scripts: false,
        include_assets: false,
        recipe: options.recipe.clone(),
        from_manifest: options.from_manifest.clone(),
        json: false,
    };
    let prompt = prompt_from_options(&probe_options, manifest_value.as_ref())?;
    let recipe = resolve_recipe(&probe_options, manifest_value.as_ref(), &prompt)?;
    let run_dir = options
        .out
        .clone()
        .unwrap_or_else(|| default_run_dir(&recipe, &prompt));

    plan(PlanOptions {
        out: Some(run_dir.clone()),
        json: false,
        ..probe_options
    })?;
    let plan_path = run_dir.join("plan.json");
    apply(ApplyOptions {
        port: options.port,
        studio: options.studio,
        plan: plan_path,
        out: Some(run_dir.clone()),
        yes: true,
        validate: options.validate,
        rollback_on_error: options.rollback_on_error,
        force: options.force,
        only: options.only,
        exclude: options.exclude,
        smoke: options.smoke,
        json: false,
    })?;
    println!("Autopilot run complete: {}", run_dir.display());
    Ok(())
}

