pub fn inbox(options: InboxOptions) -> AppResult<()> {
    let (selected_run, mut selection_warnings) = select_inbox_run(&options)?;
    let default_out = selected_run
        .as_ref()
        .map(|run| PathBuf::from(&run.run_dir).join("inbox.json"))
        .unwrap_or_else(|| default_inbox_path(&options.root));
    let out = options.out.clone().unwrap_or(default_out);
    let markdown_path = if options.no_markdown {
        None
    } else {
        Some(
            options
                .markdown
                .clone()
                .unwrap_or_else(|| out.with_extension("md")),
        )
    };
    let report = build_inbox_report(
        &options,
        selected_run,
        &out,
        markdown_path.as_deref(),
        &mut selection_warnings,
    )?;
    write_json(out.clone(), &report)?;
    if let Some(markdown_path) = markdown_path {
        write_inbox_markdown(markdown_path, &report)?;
    }
    if let Some(run) = &report.selected_run {
        let run_dir = PathBuf::from(&run.run_dir);
        let plan_path = run_dir.join("plan.json");
        let bundle_path = run_dir.join("bundle.json");
        if bundle_path.exists() && plan_path.exists() {
            let plan = read_plan(&plan_path)?;
            let bundle = build_bundle_report(&run_dir, &bundle_path, &plan_path, &plan)?;
            write_json(bundle_path, &bundle)?;
        }
    }
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_inbox_summary(&report);
    }
    if !report.blockers.is_empty() {
        return Err(AppError::Other(
            "autopilot inbox found blockers; inspect inbox.json".into(),
        ));
    }
    Ok(())
}

