pub fn remember(options: RememberOptions) -> AppResult<()> {
    let out = options
        .out
        .clone()
        .unwrap_or_else(|| options.run_dir.join("remember.json"));
    let markdown_path = if options.no_markdown {
        None
    } else {
        Some(
            options
                .markdown
                .clone()
                .unwrap_or_else(|| options.run_dir.join("remember.md")),
        )
    };
    let mut report = build_remember_report(&options, &out, markdown_path.as_deref())?;
    if options.best_friend {
        let best_friend_path = options.run_dir.join("best-friend.json");
        let best_friend_markdown_path =
            (!options.no_markdown).then(|| options.run_dir.join("best-friend.md"));
        let best_friend_options = BestFriendOptions {
            prompt: None,
            run_dir: options.run_dir.clone(),
            root: options.root.clone(),
            limit: options.limit,
            opportunity: options.opportunity.clone(),
            max_chars: options.max_chars,
            out: Some(best_friend_path.clone()),
            markdown: best_friend_markdown_path.clone(),
            no_markdown: options.no_markdown,
            json: false,
        };
        let best_friend = build_best_friend_report_with_remember(
            &best_friend_options,
            &best_friend_path,
            best_friend_markdown_path.as_deref(),
            Some(report.clone()),
        )?;
        write_json(best_friend_path.clone(), &best_friend)?;
        if let Some(path) = best_friend_markdown_path.clone() {
            write_best_friend_markdown(path, &best_friend)?;
        }
        report.best_friend_status = Some(best_friend.status.clone());
        report.best_friend_path = Some(best_friend.best_friend_path.clone());
        report.best_friend_markdown_path = best_friend.markdown_path.clone();
        report
            .artifacts
            .insert("bestFriend".into(), best_friend.best_friend_path.clone());
        if let Some(path) = &best_friend.markdown_path {
            report
                .artifacts
                .insert("bestFriendMarkdown".into(), path.clone());
        }
        report.consolidated_artifacts.push(remember_artifact(
            "bestFriend",
            "Best-Friend Launch Packet",
            &best_friend.best_friend_path,
            best_friend.markdown_path.as_deref(),
            &best_friend.status,
            "Checked fresh-AI launch packet built from the refreshed memory context.",
        ));
        report.safe_to_say.push(
            "Remember also wrote best-friend.json so the next AI has a checked launch packet."
                .into(),
        );
        report.do_not_say.push(
            "Do not claim remember --best-friend executed the best-friend first action; it only prepared the launch packet."
                .into(),
        );
        report.warnings.extend(
            best_friend
                .warnings
                .iter()
                .map(|warning| format!("best-friend: {warning}")),
        );
        if !best_friend.blockers.is_empty() {
            report.blockers.extend(
                best_friend
                    .blockers
                    .iter()
                    .map(|blocker| format!("best-friend: {blocker}")),
            );
            report.status = "blocked".into();
        }
        if let Some(mut action) = best_friend.next_actions.first().cloned() {
            action.priority = 0;
            report.next_actions.push(action);
        }
        report.safe_to_say.sort();
        report.safe_to_say.dedup();
        report.do_not_say.sort();
        report.do_not_say.dedup();
        report.warnings.sort();
        report.warnings.dedup();
        report.blockers.sort();
        report.blockers.dedup();
        dedup_next_actions(&mut report.next_actions);
    }
    write_json(out.clone(), &report)?;
    if let Some(markdown_path) = markdown_path {
        write_remember_markdown(markdown_path, &report)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_remember_summary(&report);
    }
    Ok(())
}

