pub fn publish_review(options: PublishReviewOptions) -> AppResult<()> {
    let out = options
        .out
        .clone()
        .unwrap_or_else(|| options.run_dir.join("studio-review.json"));
    let markdown_path = if options.no_markdown {
        None
    } else {
        Some(
            options
                .markdown
                .clone()
                .unwrap_or_else(|| out.with_extension("md")),
        )
    };
    let mut report = build_publish_review_report(&options, &out, markdown_path.as_deref())?;
    match crate::cli::request::post::<_, Value>(
        options.port,
        "autopilot review panel",
        "/autopilot-review",
        &AutopilotReviewRequest {
            studio: options.studio.clone(),
            action: "set".into(),
            run: Some(report.panel_payload.clone()),
        },
        30,
    ) {
        Ok(response) => {
            report.status = "published".into();
            report.panel_response = Some(response);
            report.safe_to_say.push(
                "The Autopilot review packet was published to the Studio review panel.".into(),
            );
            report.agent_brief =
                "Studio review panel was updated with the latest non-mutating Autopilot packet."
                    .into();
        }
        Err(err) => {
            report.status = "blocked".into();
            report.blockers.push(format!(
                "could not publish Studio review panel state: {err}"
            ));
            report.agent_brief = "Studio review publish is blocked. The local artifact is still written, but Studio has not received this review packet.".into();
        }
    }
    report.blockers.sort();
    report.blockers.dedup();
    report.safe_to_say.sort();
    report.safe_to_say.dedup();
    write_json(out.clone(), &report)?;
    if let Some(markdown_path) = markdown_path {
        write_publish_review_markdown(markdown_path, &report)?;
    }
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_publish_review_summary(&report);
    }
    if !report.blockers.is_empty() {
        return Err(AppError::Other(
            "autopilot review publish found blockers; inspect studio-review.json".into(),
        ));
    }
    Ok(())
}

