fn write_self_check_child_artifacts(
    report: &SelfCheckReport,
    write_markdown: bool,
) -> AppResult<()> {
    if let Some(claim_check) = &report.claim_check {
        if let Some(path) = report.claim_check_path.as_ref() {
            write_json(PathBuf::from(path), claim_check)?;
        }
        if write_markdown {
            if let Some(path) = report.claim_check_markdown_path.as_ref() {
                write_claim_check_markdown(PathBuf::from(path), claim_check)?;
            }
        }
    }
    if let Some(command_guard) = &report.command_guard {
        if let Some(path) = report.command_guard_path.as_ref() {
            write_json(PathBuf::from(path), command_guard)?;
        }
        if write_markdown {
            if let Some(path) = report.command_guard_markdown_path.as_ref() {
                write_command_guard_markdown(PathBuf::from(path), command_guard)?;
            }
        }
    }
    Ok(())
}

