pub fn improve(options: ImproveOptions) -> AppResult<()> {
    if options.max_recipes == 0 {
        return Err(AppError::Other(
            "autopilot improve requires --max-recipes to be at least 1".into(),
        ));
    }
    let (source_run_dir, source_plan_path) = resolve_improve_paths(&options)?;
    let source_plan = read_plan(&source_plan_path)?;
    let source_critique_path = source_run_dir.join("gameplay-critique.json");
    let source_critique_markdown_path = source_run_dir.join("gameplay-critique.md");
    let source_critique = build_gameplay_critique_report(
        &source_run_dir,
        &source_plan_path,
        &source_plan,
        &source_critique_path,
        Some(&source_critique_markdown_path),
    )?;
    write_json(source_critique_path.clone(), &source_critique)?;
    write_gameplay_critique_markdown(source_critique_markdown_path, &source_critique)?;
    let source_recipes = recipes_for_run(&source_run_dir, &source_plan)?;
    let (selected_recipes, skipped_gaps) = select_improvement_recipes(
        &source_recipes,
        &source_critique.gaps,
        &options.recipes,
        options.max_recipes,
    )?;
    let planned_run_dir = if selected_recipes.is_empty() {
        options.out.clone()
    } else {
        Some(
            options
                .out
                .clone()
                .unwrap_or_else(|| default_improvement_run_dir(&source_run_dir, &selected_recipes)),
        )
    };
    let report_path = planned_run_dir
        .clone()
        .unwrap_or_else(|| source_run_dir.clone())
        .join("improve.json");
    let markdown_path = if options.no_markdown {
        None
    } else {
        Some(
            options
                .markdown
                .clone()
                .unwrap_or_else(|| report_path.with_file_name("improve.md")),
        )
    };

    let report = if selected_recipes.is_empty() {
        build_noop_improve_report(
            &report_path,
            markdown_path.as_deref(),
            &source_run_dir,
            &source_plan_path,
            &source_plan,
            &source_critique,
            skipped_gaps,
        )
    } else {
        let improved_run_dir = planned_run_dir.expect("selected recipes always create a run dir");
        std::fs::create_dir_all(&improved_run_dir)?;
        let patch_prompt = format!(
            "{}; improve gameplay with {}",
            source_plan.request.prompt,
            selected_recipes
                .iter()
                .map(|patch| patch.recipe.as_str())
                .collect::<Vec<_>>()
                .join(", ")
        );
        let compose_options = ComposeOptions {
            port: options.port,
            prompt: Some(patch_prompt),
            studio: source_plan.request.studio.clone(),
            scope: source_plan.request.scope.clone(),
            out: Some(improved_run_dir.clone()),
            preset: None,
            recipes: selected_recipes
                .iter()
                .map(|patch| patch.recipe.clone())
                .collect(),
            from_manifest: None,
            smoke: options.smoke.clone(),
            json: false,
        };
        let (improved_run_dir, improved_plan, _preview) =
            write_compose_artifacts(&compose_options)?;
        let improved_plan_path = improved_run_dir.join("plan.json");
        let improved_critique =
            write_full_offline_run_packet(&improved_run_dir, &improved_plan_path, &improved_plan)?;
        build_patched_improve_report(
            &report_path,
            markdown_path.as_deref(),
            &source_run_dir,
            &source_plan_path,
            &source_plan,
            &source_critique,
            &improved_run_dir,
            &improved_plan_path,
            &improved_plan,
            &improved_critique,
            selected_recipes,
            skipped_gaps,
        )
    };

    if let Some(parent) = report_path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    write_json(report_path, &report)?;
    if let Some(markdown_path) = markdown_path {
        write_improve_markdown(markdown_path, &report)?;
    }
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_improve_summary(&report);
    }
    Ok(())
}

