pub fn audit_sources(options: AuditSourcesOptions) -> AppResult<()> {
    let plan_path = options
        .plan
        .clone()
        .unwrap_or_else(|| options.run_dir.join("plan.json"));
    let plan = read_plan(&plan_path)?;
    let out = options
        .out
        .unwrap_or_else(|| options.run_dir.join("source-audit.json"));
    let markdown_path = if options.no_markdown {
        None
    } else {
        Some(
            options
                .markdown
                .unwrap_or_else(|| options.run_dir.join("source-audit.md")),
        )
    };
    let report = build_source_audit_report(&options.run_dir, &plan_path, &plan)?;
    write_json(out, &report)?;
    if let Some(markdown_path) = markdown_path {
        write_source_audit_markdown(markdown_path, &report)?;
    }
    let bundle_path = options.run_dir.join("bundle.json");
    if bundle_path.exists() {
        let bundle = build_bundle_report(&options.run_dir, &bundle_path, &plan_path, &plan)?;
        write_json(bundle_path, &bundle)?;
    }
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_source_audit_summary(&report);
    }
    if report.ok {
        Ok(())
    } else if options.json {
        Err(AppError::Silent {
            exit_code: 1,
            message: "autopilot source audit found blockers".into(),
        })
    } else {
        Err(AppError::Other(
            "autopilot source audit found blockers".into(),
        ))
    }
}

