pub fn adopt_plan(options: AdoptPlanOptions) -> AppResult<()> {
    let raw_plan = read_json_file(&options.plan)?;
    let strict_warnings = strict_validate_ai_plan_value(&raw_plan)?;
    let plan: AutopilotPlan = serde_json::from_value(raw_plan)?;
    validate_plan(&plan)?;
    validate_adopted_model_plan(&plan)?;

    let run_dir = options
        .out
        .clone()
        .unwrap_or_else(|| default_run_dir("adopted", &plan.request.prompt));
    std::fs::create_dir_all(&run_dir)?;

    let source_root = options
        .source_root
        .clone()
        .or_else(|| options.plan.parent().map(Path::to_path_buf));
    let copied_sources = copy_adopted_generated_sources(&plan, source_root.as_deref(), &run_dir)?;
    let plan_path = run_dir.join("plan.json");
    let preview_path = run_dir.join("preview.json");
    let source_audit_path = run_dir.join("source-audit.json");
    let source_audit_markdown_path = run_dir.join("source-audit.md");
    let bundle_path = run_dir.join("bundle.json");
    let handoff_path = run_dir.join("handoff.json");
    let handoff_markdown_path = run_dir.join("handoff.md");
    let certification_path = run_dir.join("certification.json");
    let certification_markdown_path = run_dir.join("certification.md");
    let planner_pack_path = run_dir.join("planner-pack.json");
    let planner_pack_markdown_path = run_dir.join("planner-pack.md");
    let report_path = run_dir.join("adopt-plan.json");

    write_json(
        run_dir.join("request.json"),
        &redact_json(&json!({
            "mode": "adopted-model-plan",
            "sourcePlan": options.plan,
            "sourceRoot": source_root,
            "context": options.context,
            "prompt": plan.request.prompt,
            "scope": plan.request.scope,
            "studio": plan.request.studio,
        })),
    )?;
    write_adopted_context(&run_dir, options.context.as_deref())?;
    write_json(
        run_dir.join("preflight.json"),
        &json!({
            "mode": "adopted-model-plan",
            "checks": [
                {"name": "strict model plan contract", "status": "pass"},
                {"name": "plan schema", "status": "pass"},
                {"name": "generated sources", "status": "pass", "value": copied_sources.len()}
            ],
            "warnings": strict_warnings,
        }),
    )?;
    write_json(plan_path.clone(), &plan)?;

    let mut preview = build_preview(&plan);
    attach_preview_integrity(&mut preview, &plan, &run_dir)?;
    write_json(preview_path.clone(), &preview)?;
    write_report(&run_dir, &plan, Some(&preview), None)?;

    let source_audit = build_source_audit_report(&run_dir, &plan_path, &plan)?;
    write_json(source_audit_path.clone(), &source_audit)?;
    write_source_audit_markdown(source_audit_markdown_path, &source_audit)?;

    let bundle = build_bundle_report(&run_dir, &bundle_path, &plan_path, &plan)?;
    write_json(bundle_path.clone(), &bundle)?;

    let handoff_report = build_handoff_report(
        &run_dir,
        &plan_path,
        &plan,
        &handoff_path,
        Some(&handoff_markdown_path),
    )?;
    write_json(handoff_path.clone(), &handoff_report)?;
    write_handoff_markdown(handoff_markdown_path, &handoff_report)?;

    let certification_report = build_certification_report(
        &run_dir,
        &plan_path,
        &plan,
        &certification_path,
        Some(&certification_markdown_path),
    )?;
    write_json(certification_path.clone(), &certification_report)?;
    write_certification_markdown(certification_markdown_path, &certification_report)?;

    let planner_pack_report = build_planner_pack_report(
        Some(&plan.request.prompt),
        Some(&run_dir),
        None,
        &planner_pack_path,
        Some(&planner_pack_markdown_path),
    )?;
    write_json(planner_pack_path.clone(), &planner_pack_report)?;
    write_planner_pack_markdown(planner_pack_markdown_path, &planner_pack_report)?;

    let report = AdoptPlanReport {
        schema_version: "rs.autopilot.adopt-plan.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        source_plan_path: options.plan.to_string_lossy().to_string(),
        adopted_plan_path: plan_path.to_string_lossy().to_string(),
        preview_path: preview_path.to_string_lossy().to_string(),
        source_audit_path: source_audit_path.to_string_lossy().to_string(),
        handoff_path: handoff_path.to_string_lossy().to_string(),
        bundle_path: bundle_path.to_string_lossy().to_string(),
        certification_path: certification_path.to_string_lossy().to_string(),
        planner_pack_path: planner_pack_path.to_string_lossy().to_string(),
        ready_to_apply: certification_report.ready_to_apply,
        safe_to_handoff: certification_report.safe_to_handoff,
        generated_source_count: copied_sources.len(),
        copied_sources,
        warnings: certification_report.warnings.clone(),
        blockers: certification_report.blockers.clone(),
        next_actions: certification_report.next_actions.clone(),
    };
    write_json(report_path, &report)?;
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_adopt_plan_summary(&report);
    }
    if report.blockers.is_empty() {
        Ok(())
    } else if options.json {
        Err(AppError::Silent {
            exit_code: 1,
            message: "adopted autopilot plan has blockers".into(),
        })
    } else {
        Err(AppError::Other(
            "adopted autopilot plan has blockers".into(),
        ))
    }
}

