pub fn setup(options: SetupOptions) -> AppResult<()> {
    let out = options
        .out
        .clone()
        .unwrap_or_else(|| PathBuf::from(".rs").join("autopilot").join("setup.json"));
    let markdown_path = if options.no_markdown {
        None
    } else {
        Some(
            options
                .markdown
                .clone()
                .unwrap_or_else(|| out.with_extension("md")),
        )
    };
    let required_capabilities = if options.required_capabilities.is_empty() {
        autopilot_required_capabilities()
    } else {
        options.required_capabilities.clone()
    };
    let fix_attempt = if options.fix {
        Some(run_setup_fix(options.port))
    } else {
        None
    };
    let ready = build_ready_report_with_autostart(
        options.port,
        options.studio.as_deref(),
        options.timeout_secs,
        options.poll_ms,
        &required_capabilities,
    );
    let report = build_setup_report(&options, &out, markdown_path.as_deref(), ready, fix_attempt);
    write_json(out.clone(), &report)?;
    if let Some(markdown_path) = markdown_path {
        write_setup_markdown(markdown_path, &report)?;
    }
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_setup_summary(&report);
    }
    std::io::stdout().flush()?;

    if report.ready_ok {
        Ok(())
    } else if options.json {
        Err(AppError::Silent {
            exit_code: 1,
            message: "autopilot setup found blockers".into(),
        })
    } else {
        Err(AppError::Other(
            "autopilot setup found blockers; see next actions above".into(),
        ))
    }
}

