pub fn live_gate(options: LiveGateOptions) -> AppResult<()> {
    let run_dir = resolve_live_gate_run_dir(&options)?;
    let out = options
        .out
        .clone()
        .unwrap_or_else(|| run_dir.join("live-gate.json"));
    let markdown_path = if options.no_markdown {
        None
    } else {
        Some(
            options
                .markdown
                .clone()
                .unwrap_or_else(|| out.with_extension("md")),
        )
    };
    let report = build_live_gate_report(&options, &run_dir, &out, markdown_path.as_deref())?;
    write_json(out.clone(), &report)?;
    if let Some(markdown_path) = markdown_path {
        write_live_gate_markdown(markdown_path, &report)?;
    }
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_live_gate_summary(&report);
    }
    if report.status == "blocked" && options.json {
        Err(AppError::Silent {
            exit_code: 1,
            message: "autopilot live-gate found blockers".into(),
        })
    } else if report.status == "blocked" {
        Err(AppError::Other(
            "autopilot live-gate found blockers; inspect live-gate.json".into(),
        ))
    } else {
        Ok(())
    }
}

fn resolve_live_gate_run_dir(options: &LiveGateOptions) -> AppResult<PathBuf> {
    if let Some(run_dir) = &options.run_dir {
        return Ok(run_dir.clone());
    }
    if let Some(session_path) = &options.session {
        let value = read_json_file(session_path)?;
        if let Some(run_dir) = string_field(&value, "runDir") {
            return Ok(PathBuf::from(run_dir));
        }
        return Err(AppError::Other(format!(
            "session has no runDir: {}",
            session_path.display()
        )));
    }
    Err(AppError::Other(
        "live-gate requires --run-dir or --session".into(),
    ))
}

fn build_live_gate_report(
    options: &LiveGateOptions,
    run_dir: &Path,
    gate_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<LiveGateReport> {
    let plan_path = run_dir.join("plan.json");
    let plan = read_plan(&plan_path)?;
    let studio = options
        .studio
        .clone()
        .or_else(|| plan.request.studio.clone());
    let mut artifacts =
        BTreeMap::from([("liveGate".into(), gate_path.to_string_lossy().to_string())]);
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "liveGateMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    let review_path = run_dir.join("review-pack.json");
    let review_markdown_path = run_dir.join("review-pack.md");
    let review = build_review_pack_report(
        &ReviewPackOptions {
            run_dir: run_dir.to_path_buf(),
            out: Some(review_path.clone()),
            markdown: Some(review_markdown_path.clone()),
            no_markdown: false,
            create_evidence_dirs: true,
            json: false,
        },
        &review_path,
        Some(&review_markdown_path),
    )?;
    write_json(review_path.clone(), &review)?;
    write_review_pack_markdown(review_markdown_path.clone(), &review)?;
    artifacts.extend(review.artifacts.clone());

    let approval_path = run_dir.join("approval.json");
    let approval_markdown_path = run_dir.join("approval.md");
    let approval = build_approval_report(run_dir, &approval_path, Some(&approval_markdown_path))?;
    write_json(approval_path.clone(), &approval)?;
    write_approval_markdown(approval_markdown_path.clone(), &approval)?;
    artifacts.extend(approval.artifacts.clone());

    let privacy_path = run_dir.join("privacy.json");
    let privacy_markdown_path = run_dir.join("privacy.md");
    let privacy = build_privacy_report(run_dir, &privacy_path, Some(&privacy_markdown_path))?;
    write_json(privacy_path.clone(), &privacy)?;
    write_privacy_markdown(privacy_markdown_path.clone(), &privacy)?;
    artifacts.insert("privacy".into(), privacy.privacy_path.clone());

    let rollback_path = run_dir.join("rollback.json");
    let rollback_markdown_path = run_dir.join("rollback.md");
    let rollback = build_rollback_report(run_dir, &rollback_path, Some(&rollback_markdown_path))?;
    write_json(rollback_path.clone(), &rollback)?;
    write_rollback_markdown(rollback_markdown_path.clone(), &rollback)?;
    artifacts.insert("rollback".into(), rollback.rollback_path.clone());

    let bundle_path = run_dir.join("bundle.json");
    if !bundle_path.exists() {
        let bundle = build_bundle_report(run_dir, &bundle_path, &plan_path, &plan)?;
        write_json(bundle_path.clone(), &bundle)?;
    }
    let bundle = verify_bundle_report(&bundle_path, Some(run_dir))?;
    artifacts.insert("bundle".into(), bundle_path.to_string_lossy().to_string());

    let ready = if options.skip_ready {
        None
    } else {
        Some(build_live_gate_ready_report(options, studio.as_deref()))
    };

    let mut checks = Vec::new();
    checks.push(live_gate_check(
        "review-pack",
        "Review Pack",
        if review.safe_to_present {
            "pass"
        } else {
            "fail"
        },
        true,
        format!(
            "review status: {}, verdict: {}",
            review.status, review.verdict
        ),
        vec![review.review_path.clone()],
        Some(format!(
            "rs autopilot review-pack {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
    ));
    checks.push(live_gate_check(
        "privacy",
        "Privacy",
        if privacy.ok { "pass" } else { "fail" },
        true,
        format!("privacy scan status: {}", privacy.status),
        vec![privacy.privacy_path.clone()],
        privacy
            .next_actions
            .first()
            .and_then(|action| action.command.clone()),
    ));
    checks.push(live_gate_check(
        "bundle",
        "Bundle Verification",
        if bundle.ok { "pass" } else { "fail" },
        true,
        format!(
            "verified {}/{} artifact(s)",
            bundle.verified, bundle.artifact_count
        ),
        vec![bundle.bundle_path.clone()],
        Some(format!(
            "rs autopilot verify-bundle --run-dir {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
    ));
    checks.push(live_gate_check(
        "approval-packet",
        "Approval Packet",
        if approval.status == "readyForApproval" {
            "pass"
        } else {
            "fail"
        },
        true,
        format!("approval status: {}", approval.status),
        vec![approval.approval_path.clone()],
        Some(format!(
            "rs autopilot approval {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
    ));
    checks.push(live_gate_check(
        "creator-approval",
        "Creator Approval Observed",
        if options.approved { "pass" } else { "pending" },
        true,
        if options.approved {
            "caller asserted explicit creator approval for the apply command".into()
        } else {
            "pass --approved only after the creator approves the exact apply command".into()
        },
        approval
            .apply_command
            .clone()
            .map(|command| vec![command])
            .unwrap_or_default(),
        approval
            .next_actions
            .first()
            .and_then(|action| action.command.clone()),
    ));
    checks.push(live_gate_check(
        "rollback",
        "Rollback Readiness",
        if rollback.status == "readyToRestore" || !rollback.apply_exists {
            "pass"
        } else if rollback.status == "needsApply" {
            "pending"
        } else {
            "review"
        },
        false,
        format!("rollback status: {}", rollback.status),
        rollback.claim_ready.clone(),
        Some(format!(
            "rs autopilot rollback {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
    ));
    if let Some(ready) = &ready {
        checks.push(live_gate_check(
            "live-readiness",
            "Live Studio Readiness",
            if ready.ok { "pass" } else { "fail" },
            true,
            format!("ready status: {}", ready.status),
            ready
                .selected_studio
                .as_ref()
                .map(|studio| vec![format!("{} ({})", studio.name, studio.id)])
                .unwrap_or_else(|| ready.blockers.clone()),
            Some(format!(
                "rs autopilot ready{} --timeout {} --format json",
                studio
                    .as_ref()
                    .map(|studio| format!(" --studio {}", command_arg(studio)))
                    .unwrap_or_default(),
                options.timeout_secs
            )),
        ));
        artifacts.insert("readyStatus".into(), ready.status.clone());
    } else {
        checks.push(live_gate_check(
            "live-readiness",
            "Live Studio Readiness",
            "skipped",
            true,
            "live readiness was skipped by --skip-ready".into(),
            Vec::new(),
            Some(format!(
                "rs autopilot ready{} --timeout {} --format json",
                studio
                    .as_ref()
                    .map(|studio| format!(" --studio {}", command_arg(studio)))
                    .unwrap_or_default(),
                options.timeout_secs
            )),
        ));
    }

    let mut blockers = Vec::new();
    blockers.extend(review.blockers.clone());
    blockers.extend(approval.blockers.clone());
    blockers.extend(privacy.blockers.clone());
    blockers.extend(bundle.blockers.clone());
    if !review.safe_to_present {
        blockers.push("review pack is not safe to present".into());
    }
    if !privacy.ok {
        blockers.push("privacy scan is not pass".into());
    }
    if !bundle.ok {
        blockers.push("bundle verification failed".into());
    }
    if approval.status != "readyForApproval" {
        blockers.push(format!("approval packet is {}", approval.status));
    }
    if let Some(ready) = &ready {
        if !ready.ok {
            blockers.extend(ready.blockers.clone());
        }
    }
    blockers.sort();
    blockers.dedup();

    let mut warnings = Vec::new();
    warnings.extend(review.warnings.clone());
    warnings.extend(approval.warnings.clone());
    warnings.extend(privacy.warnings.clone());
    warnings.extend(rollback.warnings.clone());
    if options.skip_ready {
        warnings.push("live readiness was skipped; this gate cannot authorize apply yet".into());
    }
    if !options.approved {
        warnings.push("explicit creator approval has not been asserted with --approved".into());
    }
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else if !options.approved {
        "needsApproval"
    } else if ready.as_ref().is_none_or(|ready| !ready.ok) {
        "needsLiveReadiness"
    } else {
        "readyToApply"
    }
    .to_string();
    let verdict = match status.as_str() {
        "readyToApply" => "go",
        "needsApproval" => "approvalRequired",
        "needsLiveReadiness" => "readyCheckRequired",
        _ => "noGo",
    }
    .to_string();

    let mut next_actions = Vec::new();
    if status == "readyToApply" {
        next_actions.push(coach_action(
            1,
            "Apply approved run",
            approval.apply_command.clone(),
            "All live gate checks passed and explicit approval was asserted.",
            true,
            true,
        ));
    } else {
        if !options.approved {
            next_actions.push(coach_action(
                1,
                "Ask for creator approval",
                Some(format!(
                    "rs autopilot approval {} --format json",
                    command_arg(run_dir.to_string_lossy().as_ref())
                )),
                "Use approvalPrompt and pass --approved only after the creator approves the exact apply command.",
                false,
                false,
            ));
        }
        if options.skip_ready || ready.as_ref().is_none_or(|ready| !ready.ok) {
            next_actions.push(coach_action(
                2,
                "Check live Studio readiness",
                Some(format!(
                    "rs autopilot ready{} --timeout {} --format json",
                    studio
                        .as_ref()
                        .map(|studio| format!(" --studio {}", command_arg(studio)))
                        .unwrap_or_default(),
                    options.timeout_secs
                )),
                "The bridge, Studio session, protocol, and plugin capabilities must pass before apply.",
                true,
                false,
            ));
        }
        next_actions.push(coach_action(
            3,
            "Refresh live gate",
            Some(format!(
                "rs autopilot live-gate --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Regenerate the go/no-go packet after approval, ready, privacy, bundle, or review changes.",
            false,
            false,
        ));
    }
    dedup_next_actions(&mut next_actions);

    let mut do_not_claim = merge_many_sorted(vec![
        review.do_not_say.clone(),
        approval.do_not_claim.clone(),
        privacy.do_not_claim.clone(),
        rollback.do_not_claim.clone(),
    ]);
    do_not_claim.push(
        "Do not claim the run is approved, applied, playtested, rollback-proven, demo-ready, or production-ready unless this gate and proof artifacts say so."
            .into(),
    );
    do_not_claim.sort();
    do_not_claim.dedup();
    let agent_brief = match status.as_str() {
        "readyToApply" => {
            "Live gate is GO. Run only the approved apply command, then refresh apply, rollback, validation, evidence, proof, and review artifacts.".into()
        }
        "needsApproval" => {
            "Live gate is waiting for explicit creator approval. Present approvalPrompt and do not mutate Studio yet.".into()
        }
        "needsLiveReadiness" => {
            "Live gate needs a passing Studio readiness check before any approved apply command is actionable.".into()
        }
        _ => "Live gate is NO-GO. Resolve blockers before approval or apply.".into(),
    };

    Ok(LiveGateReport {
        schema_version: "rs.autopilot.live-gate.v1".into(),
        generated_at: now_stamp(),
        gate_path: gate_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict,
        run_dir: run_dir.to_string_lossy().to_string(),
        studio,
        approved: options.approved,
        skip_ready: options.skip_ready,
        ready_ok: ready.as_ref().map(|ready| ready.ok),
        review_status: review.status,
        approval_status: approval.status,
        privacy_status: privacy.status,
        rollback_status: rollback.status,
        bundle_ok: bundle.ok,
        apply_command: approval.apply_command,
        checks,
        artifacts,
        blockers,
        warnings,
        do_not_claim,
        next_actions,
        agent_brief,
    })
}

fn build_live_gate_ready_report(options: &LiveGateOptions, studio: Option<&str>) -> ReadyReport {
    let required_capabilities = if options.required_capabilities.is_empty() {
        autopilot_required_capabilities()
    } else {
        options.required_capabilities.clone()
    };
    build_ready_report_with_autostart(
        options.port,
        studio,
        options.timeout_secs,
        options.poll_ms,
        &required_capabilities,
    )
}

fn live_gate_check(
    id: &str,
    title: &str,
    status: &str,
    required: bool,
    summary: String,
    evidence: Vec<String>,
    next_command: Option<String>,
) -> LiveGateCheck {
    LiveGateCheck {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        required,
        summary,
        evidence,
        next_command,
    }
}

fn write_live_gate_markdown(path: PathBuf, report: &LiveGateReport) -> AppResult<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, render_live_gate_markdown(report))?;
    Ok(())
}

fn render_live_gate_markdown(report: &LiveGateReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Live Gate\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Verdict: `{}`\n", report.verdict));
    out.push_str(&format!("- Run: `{}`\n", report.run_dir));
    out.push_str(&format!("- Approved: `{}`\n", report.approved));
    out.push_str(&format!("- Ready OK: `{:?}`\n", report.ready_ok));
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push_str("\n\n## Checks\n\n");
    for check in &report.checks {
        out.push_str(&format!(
            "- {}: `{}` - {}\n",
            check.title, check.status, check.summary
        ));
        if let Some(command) = &check.next_command {
            out.push_str(&format!("  - Next: `{command}`\n"));
        }
    }
    out.push_str("\n## Do Not Claim\n\n");
    for claim in &report.do_not_claim {
        out.push_str(&format!("- {claim}\n"));
    }
    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n", action.priority, action.title));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push_str(&format!("   {}\n", action.reason));
    }
    out
}

fn print_live_gate_summary(report: &LiveGateReport) {
    println!("Autopilot live gate: {}", report.status);
    println!("Verdict: {}", report.verdict);
    println!("Run: {}", report.run_dir);
    println!("JSON: {}", report.gate_path);
    if let Some(markdown) = &report.markdown_path {
        println!("Markdown: {markdown}");
    }
    if !report.blockers.is_empty() {
        println!("\nBlockers:");
        for blocker in report.blockers.iter().take(10) {
            println!("  - {blocker}");
        }
    }
    if !report.warnings.is_empty() {
        println!("\nWarnings:");
        for warning in report.warnings.iter().take(10) {
            println!("  - {warning}");
        }
    }
    println!("\nChecks:");
    for check in &report.checks {
        println!("  - {} [{}]", check.title, check.status);
    }
    if let Some(action) = report.next_actions.first() {
        println!("\nNext: {}", action.title);
        if let Some(command) = &action.command {
            println!("{command}");
        }
    }
}

pub fn rehearsal(options: RehearsalOptions) -> AppResult<()> {
    let out = options
        .out
        .clone()
        .unwrap_or_else(|| options.run_dir.join("rehearsal.json"));
    let markdown_path = if options.no_markdown {
        None
    } else {
        Some(
            options
                .markdown
                .clone()
                .unwrap_or_else(|| out.with_extension("md")),
        )
    };
    let report = build_rehearsal_report(&options, &out, markdown_path.as_deref())?;
    write_json(out.clone(), &report)?;
    if let Some(markdown_path) = markdown_path {
        write_rehearsal_markdown(markdown_path, &report)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_rehearsal_summary(&report);
    }
    Ok(())
}

fn build_rehearsal_report(
    options: &RehearsalOptions,
    rehearsal_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<RehearsalReport> {
    let run_dir = &options.run_dir;
    let plan_path = run_dir.join("plan.json");
    let plan = read_plan(&plan_path)?;

    let showcase_path = run_dir.join("showcase.json");
    let showcase_markdown_path = run_dir.join("showcase.md");
    let showcase = build_showcase_report(
        run_dir,
        &plan_path,
        &plan,
        &showcase_path,
        Some(&showcase_markdown_path),
    )?;
    write_json(showcase_path.clone(), &showcase)?;
    write_showcase_markdown(showcase_markdown_path.clone(), &showcase)?;

    let evidence_path = run_dir.join("evidence-kit.json");
    let evidence_markdown_path = run_dir.join("evidence-kit.md");
    let evidence_root = run_dir.join("evidence");
    let evidence = build_evidence_kit_report(
        run_dir,
        &evidence_path,
        Some(&evidence_markdown_path),
        &evidence_root,
        false,
    )?;
    write_json(evidence_path.clone(), &evidence)?;
    write_evidence_kit_markdown(evidence_markdown_path.clone(), &evidence)?;
    refresh_run_bundle_if_possible(run_dir)?;

    let live_gate_path = run_dir.join("live-gate.json");
    let live_gate_markdown_path = run_dir.join("live-gate.md");
    let live_gate_options = LiveGateOptions {
        port: 7878,
        run_dir: Some(run_dir.to_path_buf()),
        session: None,
        studio: None,
        approved: false,
        skip_ready: true,
        timeout_secs: 90,
        poll_ms: 1000,
        required_capabilities: Vec::new(),
        out: Some(live_gate_path.clone()),
        markdown: Some(live_gate_markdown_path.clone()),
        no_markdown: false,
        json: false,
    };
    let live_gate = build_live_gate_report(
        &live_gate_options,
        run_dir,
        &live_gate_path,
        Some(&live_gate_markdown_path),
    )?;
    write_json(live_gate_path.clone(), &live_gate)?;
    write_live_gate_markdown(live_gate_markdown_path.clone(), &live_gate)?;

    let closeout_path = run_dir.join("closeout.json");
    let closeout_markdown_path = run_dir.join("closeout.md");
    let closeout = build_closeout_report(run_dir, &closeout_path, Some(&closeout_markdown_path))?;
    write_json(closeout_path.clone(), &closeout)?;
    write_closeout_markdown(closeout_markdown_path.clone(), &closeout)?;

    let mut artifacts = BTreeMap::from([
        (
            "rehearsal".into(),
            rehearsal_path.to_string_lossy().to_string(),
        ),
        ("plan".into(), plan_path.to_string_lossy().to_string()),
        ("showcase".into(), showcase.showcase_path.clone()),
        (
            "showcaseMarkdown".into(),
            showcase.markdown_path.clone().unwrap_or_default(),
        ),
        ("evidenceKit".into(), evidence.kit_path.clone()),
        (
            "evidenceKitMarkdown".into(),
            evidence.markdown_path.clone().unwrap_or_default(),
        ),
        ("liveGate".into(), live_gate.gate_path.clone()),
        (
            "liveGateMarkdown".into(),
            live_gate.markdown_path.clone().unwrap_or_default(),
        ),
        ("closeout".into(), closeout.closeout_path.clone()),
        (
            "closeoutMarkdown".into(),
            closeout.markdown_path.clone().unwrap_or_default(),
        ),
    ]);
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "rehearsalMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.extend(live_gate.artifacts.clone());
    artifacts.extend(closeout.artifacts.clone());

    let mut blockers = merge_many_sorted(vec![
        live_gate.blockers.clone(),
        closeout.blockers.clone(),
        showcase.blockers.clone(),
        evidence.blockers.clone(),
    ]);
    blockers.sort();
    blockers.dedup();
    let mut warnings = merge_many_sorted(vec![
        live_gate.warnings.clone(),
        closeout.warnings.clone(),
        showcase.warnings.clone(),
        evidence.warnings.clone(),
    ]);
    warnings.push(
        "rehearsal is local-only; it does not assert creator approval, live apply, or playtest success"
            .into(),
    );
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else if closeout.status == "complete" {
        "readyToPresent"
    } else if live_gate.status == "needsApproval" {
        "readyForApproval"
    } else if closeout.status == "needsLiveProof" {
        "needsLiveProof"
    } else {
        "needsWork"
    }
    .to_string();
    let verdict = match status.as_str() {
        "readyToPresent" => "demoCanBePresented",
        "readyForApproval" => "approvalRehearsalReady",
        "needsLiveProof" => "liveProofRunbookReady",
        "blocked" => "noGo",
        _ => "needsWork",
    }
    .to_string();

    let readiness = build_rehearsal_checks(run_dir, &showcase, &evidence, &live_gate, &closeout);
    let runbook_steps = build_rehearsal_steps(run_dir, &plan, &evidence, &live_gate, &closeout);
    let creator_script = build_rehearsal_creator_script(&plan, &status, &live_gate, &closeout);
    let evidence_to_collect = evidence
        .requirements
        .iter()
        .take(12)
        .map(|requirement| {
            format!(
                "{}: {} -> {}",
                requirement.title, requirement.expected, requirement.suggested_path
            )
        })
        .collect::<Vec<_>>();
    let stop_conditions = build_rehearsal_stop_conditions(&live_gate, &closeout);
    let mut safe_to_say = closeout.safe_to_say.clone();
    safe_to_say.push(
        "A non-mutating rehearsal runbook exists for approval, live readiness, apply, proof, and closeout.".into(),
    );
    if status == "readyForApproval" {
        safe_to_say.push(
            "The offline packet can be presented for creator approval, but Studio has not been mutated by rehearsal."
                .into(),
        );
    }
    safe_to_say.sort();
    safe_to_say.dedup();
    let mut do_not_say = merge_many_sorted(vec![
        live_gate.do_not_claim.clone(),
        closeout.do_not_say.clone(),
    ]);
    do_not_say.push(
        "Do not say rehearsal applied, published, playtested, or proved the run in Studio.".into(),
    );
    do_not_say.push(
        "Do not run the apply command unless the creator approved the exact approval packet and live-gate is GO.".into(),
    );
    do_not_say.sort();
    do_not_say.dedup();

    let next_actions = build_rehearsal_next_actions(run_dir, &status);
    let agent_brief = format!(
        "Rehearsal for '{}' is {}. Follow the runbook in order: present review, collect explicit approval, check live readiness, run the approved apply command only if live-gate is GO, collect playtest evidence, then close out honestly.",
        plan.request.prompt, status
    );

    Ok(RehearsalReport {
        schema_version: "rs.autopilot.rehearsal.v1".into(),
        generated_at: now_stamp(),
        rehearsal_path: rehearsal_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_id: plan.id,
        prompt: plan.request.prompt,
        status,
        verdict,
        mutates_studio: false,
        approval_status: live_gate.approval_status.clone(),
        live_gate_status: live_gate.status.clone(),
        closeout_status: closeout.status.clone(),
        showcase_status: showcase.status.clone(),
        playtest_status: if evidence.scenario_count > 0 {
            "planned".into()
        } else {
            "missingScenarios".into()
        },
        evidence_status: evidence.status.clone(),
        readiness,
        runbook_steps,
        creator_script,
        evidence_to_collect,
        stop_conditions,
        safe_to_say,
        do_not_say,
        artifacts,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn build_rehearsal_checks(
    run_dir: &Path,
    showcase: &ShowcaseReport,
    evidence: &EvidenceKitReport,
    live_gate: &LiveGateReport,
    closeout: &CloseoutReport,
) -> Vec<RehearsalCheck> {
    vec![
        rehearsal_check(
            "showcase",
            "Showcase Plan",
            if showcase.status == "showcaseReady" {
                "pass"
            } else {
                "review"
            },
            format!(
                "showcase status: {}, {} shot(s), {} clip(s)",
                showcase.status, showcase.shot_count, showcase.clip_count
            ),
            Some(showcase.showcase_path.clone()),
            Some(format!(
                "rs autopilot showcase {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
        rehearsal_check(
            "approval",
            "Creator Approval Packet",
            if live_gate.approval_status == "readyForApproval" {
                "pass"
            } else {
                "fail"
            },
            format!("approval status: {}", live_gate.approval_status),
            live_gate.artifacts.get("approval").cloned(),
            Some(format!(
                "rs autopilot approval {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
        rehearsal_check(
            "live-gate",
            "Live Mutation Gate",
            if live_gate.status == "needsApproval" || live_gate.status == "readyToApply" {
                "pass"
            } else if live_gate.status == "needsLiveReadiness" {
                "pending"
            } else {
                "fail"
            },
            format!("live-gate status: {}", live_gate.status),
            Some(live_gate.gate_path.clone()),
            Some(format!(
                "rs autopilot live-gate --run-dir {} --approved --timeout 90 --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
        rehearsal_check(
            "evidence-kit",
            "Live Evidence Kit",
            if evidence.scenario_count > 0 {
                "pass"
            } else {
                "review"
            },
            format!(
                "evidence status: {}, {} scenario(s)",
                evidence.status, evidence.scenario_count
            ),
            Some(evidence.kit_path.clone()),
            Some(format!(
                "rs autopilot evidence {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
        rehearsal_check(
            "closeout",
            "Honest Closeout",
            if closeout.status == "complete" {
                "pass"
            } else if closeout.status == "needsLiveProof" {
                "pending"
            } else {
                "review"
            },
            format!(
                "closeout status: {}, verdict: {}",
                closeout.status, closeout.verdict
            ),
            Some(closeout.closeout_path.clone()),
            Some(format!(
                "rs autopilot closeout {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
    ]
}

fn rehearsal_check(
    id: &str,
    title: &str,
    status: &str,
    summary: String,
    artifact: Option<String>,
    next_command: Option<String>,
) -> RehearsalCheck {
    RehearsalCheck {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        summary,
        artifact,
        next_command,
    }
}

fn build_rehearsal_steps(
    run_dir: &Path,
    plan: &AutopilotPlan,
    evidence: &EvidenceKitReport,
    live_gate: &LiveGateReport,
    closeout: &CloseoutReport,
) -> Vec<RehearsalStep> {
    let run_arg = command_arg(run_dir.to_string_lossy().as_ref());
    let ready_command = plan
        .request
        .studio
        .as_ref()
        .map(|studio| {
            format!(
                "rs autopilot ready --studio {} --timeout 90 --format json",
                command_arg(studio)
            )
        })
        .unwrap_or_else(|| "rs autopilot ready --timeout 90 --format json".into());
    let record_command = evidence.record_commands.first().cloned();
    vec![
        rehearsal_step(
            1,
            "review",
            "Refresh creator review packet",
            Some(format!("rs autopilot review-pack {run_arg} --format json")),
            "Make the risk, artifacts, blockers, safe claims, and approval prompt current before talking to the creator.",
            Some("review-pack.json".into()),
            false,
            false,
            vec!["review-pack is not safe to present".into()],
        ),
        rehearsal_step(
            2,
            "demo",
            "Present showcase and player promise",
            Some(format!("rs autopilot showcase {run_arg} --format json")),
            "Use the generated shots, trailer beats, and talking points to explain what the slice is meant to prove.",
            Some("showcase.json".into()),
            false,
            false,
            vec!["showcase is missing proof checks or visible player beats".into()],
        ),
        rehearsal_step(
            3,
            "approval",
            "Ask for exact creator approval",
            Some(format!("rs autopilot approval {run_arg} --format json")),
            "Ask the creator to approve the exact apply command; do not treat chat wording as approval.",
            Some("approval.json".into()),
            false,
            false,
            vec!["creator does not approve the exact apply command".into()],
        ),
        rehearsal_step(
            4,
            "readiness",
            "Check live Studio readiness",
            Some(ready_command),
            "Verify bridge, Studio, protocol, and plugin capabilities before any live gate can authorize apply.",
            Some("ready.json output".into()),
            true,
            false,
            vec!["Studio is unavailable or plugin capabilities are missing".into()],
        ),
        rehearsal_step(
            5,
            "gate",
            "Run approved live gate",
            Some(format!(
                "rs autopilot live-gate --run-dir {run_arg} --approved --timeout 90 --format json"
            )),
            "Regenerate the final go/no-go packet after explicit approval and live readiness.",
            Some("live-gate.json".into()),
            true,
            false,
            vec!["live-gate status is not readyToApply".into()],
        ),
        rehearsal_step(
            6,
            "apply",
            "Apply only the approved command",
            live_gate.apply_command.clone(),
            "Mutate Studio only if live-gate is GO and the command matches the approval packet.",
            Some("apply.json".into()),
            true,
            true,
            vec![
                "approval packet changed after creator approval".into(),
                "live-gate is not GO".into(),
                "apply command differs from approval.json".into(),
            ],
        ),
        rehearsal_step(
            7,
            "proof",
            "Collect and record live proof",
            record_command,
            "Run the Play Solo checklist, capture evidence paths, and record the observed result.",
            Some("playtest-result.json".into()),
            true,
            false,
            vec!["any playtest scenario fails, blocks, or lacks evidence".into()],
        ),
        rehearsal_step(
            8,
            "closeout",
            "Close out with evidence boundaries",
            Some(format!("rs autopilot closeout {run_arg} --format json")),
            "Say done only if closeout reports complete; otherwise report the exact missing proof.",
            Some("closeout.json".into()),
            false,
            false,
            vec![format!("closeout status is {}", closeout.status)],
        ),
    ]
}

fn rehearsal_step(
    order: u8,
    phase: &str,
    title: &str,
    command: Option<String>,
    purpose: &str,
    expected_artifact: Option<String>,
    requires_live_studio: bool,
    mutates_studio: bool,
    stop_if: Vec<String>,
) -> RehearsalStep {
    RehearsalStep {
        order,
        phase: phase.into(),
        title: title.into(),
        command,
        purpose: purpose.into(),
        expected_artifact,
        requires_live_studio,
        mutates_studio,
        stop_if,
    }
}

fn build_rehearsal_creator_script(
    plan: &AutopilotPlan,
    status: &str,
    live_gate: &LiveGateReport,
    closeout: &CloseoutReport,
) -> Vec<String> {
    let mut script = vec![
        format!("I prepared a non-mutating rehearsal for `{}`.", plan.request.prompt),
        "I can show the review packet, risk, expected player loop, and exact proof checklist before changing Studio.".into(),
    ];
    if status == "readyForApproval" {
        script.push(
            "The next decision is your explicit approval of the exact apply command; I will not apply it from chat wording alone.".into(),
        );
    }
    if closeout.status == "complete" {
        script.push(
            "Closeout already has complete proof; I can present the supported demo claims and cite the artifacts.".into(),
        );
    } else {
        script.push(format!(
            "Closeout is `{}`, so any done/demo-ready claim still depends on the runbook proof steps.",
            closeout.status
        ));
    }
    script.push(format!(
        "Live gate is `{}`; the rehearsal itself did not approve or apply anything.",
        live_gate.status
    ));
    script
}

fn build_rehearsal_stop_conditions(
    live_gate: &LiveGateReport,
    closeout: &CloseoutReport,
) -> Vec<String> {
    let mut stops = vec![
        "Stop before apply if the creator has not approved the exact approval.json apply command.".into(),
        "Stop before apply if `rs autopilot ready` fails or cannot find a compatible Studio session.".into(),
        "Stop before apply if `rs autopilot live-gate --approved` is not `readyToApply`.".into(),
        "Stop proof collection if Play Solo evidence is missing, failed, blocked, or inconclusive; record it and run repair-plan.".into(),
        "Stop creator-facing done claims unless closeout.status is `complete`.".into(),
    ];
    stops.extend(
        live_gate
            .blockers
            .iter()
            .map(|item| format!("Live gate blocker: {item}")),
    );
    stops.extend(
        closeout
            .blockers
            .iter()
            .map(|item| format!("Closeout blocker: {item}")),
    );
    stops.sort();
    stops.dedup();
    stops
}

fn build_rehearsal_next_actions(run_dir: &Path, status: &str) -> Vec<CoachAction> {
    let run_arg = command_arg(run_dir.to_string_lossy().as_ref());
    let mut actions = Vec::new();
    if status == "blocked" || status == "needsWork" {
        actions.push(coach_action(
            1,
            "Inspect blockers before rehearsal",
            Some(format!("rs autopilot closeout {run_arg} --format json")),
            "Resolve closeout, privacy, review, or bundle blockers before asking for live approval.",
            false,
            false,
        ));
    } else {
        actions.push(coach_action(
            1,
            "Present approval packet",
            Some(format!("rs autopilot approval {run_arg} --format json")),
            "Use the approval prompt and exact apply command before crossing the Studio mutation boundary.",
            false,
            false,
        ));
        actions.push(coach_action(
            2,
            "Check live readiness",
            Some("rs autopilot ready --timeout 90 --format json".into()),
            "Confirm bridge, Studio, protocol, and plugin readiness after creator approval.",
            true,
            false,
        ));
        actions.push(coach_action(
            3,
            "Run approved live gate",
            Some(format!(
                "rs autopilot live-gate --run-dir {run_arg} --approved --timeout 90 --format json"
            )),
            "Only a GO live gate should lead to the mutating apply step.",
            true,
            false,
        ));
    }
    actions.push(coach_action(
        8,
        "Refresh rehearsal",
        Some(format!("rs autopilot rehearsal {run_arg} --format json")),
        "Regenerate the runbook after any artifact, approval, apply, playtest, or closeout change.",
        false,
        false,
    ));
    dedup_next_actions(&mut actions);
    actions
}

fn write_rehearsal_markdown(path: PathBuf, report: &RehearsalReport) -> AppResult<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, render_rehearsal_markdown(report))?;
    Ok(())
}

fn render_rehearsal_markdown(report: &RehearsalReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Rehearsal\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Verdict: `{}`\n", report.verdict));
    out.push_str(&format!("- Run: `{}`\n", report.run_dir));
    out.push_str(&format!("- Mutates Studio: `{}`\n", report.mutates_studio));
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push_str("\n\n## Runbook\n\n");
    for step in &report.runbook_steps {
        out.push_str(&format!(
            "{}. {} (`{}`)\n\n",
            step.order, step.title, step.phase
        ));
        out.push_str(&format!("   {}\n", step.purpose));
        if let Some(command) = &step.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        if !step.stop_if.is_empty() {
            out.push_str("   Stop if:\n");
            for stop in &step.stop_if {
                out.push_str(&format!("   - {stop}\n"));
            }
        }
        out.push('\n');
    }
    out.push_str("\n## Readiness\n\n");
    for check in &report.readiness {
        out.push_str(&format!(
            "- {}: `{}` - {}\n",
            check.title, check.status, check.summary
        ));
        if let Some(command) = &check.next_command {
            out.push_str(&format!("  - Next: `{command}`\n"));
        }
    }
    out.push_str("\n## Creator Script\n\n");
    for line in &report.creator_script {
        out.push_str(&format!("- {line}\n"));
    }
    out.push_str("\n## Evidence To Collect\n\n");
    for item in &report.evidence_to_collect {
        out.push_str(&format!("- {item}\n"));
    }
    out.push_str("\n## Stop Conditions\n\n");
    for stop in &report.stop_conditions {
        out.push_str(&format!("- {stop}\n"));
    }
    out.push_str("\n## Do Not Say\n\n");
    for claim in &report.do_not_say {
        out.push_str(&format!("- {claim}\n"));
    }
    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n", action.priority, action.title));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push_str(&format!("   {}\n", action.reason));
    }
    out
}

fn print_rehearsal_summary(report: &RehearsalReport) {
    println!("Autopilot rehearsal: {}", report.status);
    println!("Verdict: {}", report.verdict);
    println!("Run: {}", report.run_dir);
    println!("JSON: {}", report.rehearsal_path);
    if let Some(markdown) = &report.markdown_path {
        println!("Markdown: {markdown}");
    }
    println!("\nReadiness:");
    for check in &report.readiness {
        println!("  - {} [{}]", check.title, check.status);
    }
    if !report.blockers.is_empty() {
        println!("\nBlockers:");
        for blocker in report.blockers.iter().take(10) {
            println!("  - {blocker}");
        }
    }
    if let Some(action) = report.next_actions.first() {
        println!("\nNext: {}", action.title);
        if let Some(command) = &action.command {
            println!("{command}");
        }
    }
}

pub fn closeout(options: CloseoutOptions) -> AppResult<()> {
    let out = options
        .out
        .clone()
        .unwrap_or_else(|| options.run_dir.join("closeout.json"));
    let markdown_path = if options.no_markdown {
        None
    } else {
        Some(
            options
                .markdown
                .clone()
                .unwrap_or_else(|| out.with_extension("md")),
        )
    };
    let report = build_closeout_report(&options.run_dir, &out, markdown_path.as_deref())?;
    write_json(out.clone(), &report)?;
    if let Some(markdown_path) = markdown_path {
        write_closeout_markdown(markdown_path, &report)?;
    }
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_closeout_summary(&report);
    }
    Ok(())
}

fn build_closeout_report(
    run_dir: &Path,
    closeout_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<CloseoutReport> {
    let proof_path = run_dir.join("proof.json");
    let proof_markdown_path = run_dir.join("proof.md");
    let proof = build_proof_report(run_dir, &proof_path, Some(&proof_markdown_path))?;
    write_json(proof_path.clone(), &proof)?;
    write_proof_markdown(proof_markdown_path.clone(), &proof)?;

    let acceptance_path = run_dir.join("acceptance.json");
    let acceptance_markdown_path = run_dir.join("acceptance.md");
    let acceptance = build_acceptance_report(
        run_dir,
        None,
        &acceptance_path,
        Some(&acceptance_markdown_path),
    )?;
    write_json(acceptance_path.clone(), &acceptance)?;
    write_acceptance_markdown(acceptance_markdown_path.clone(), &acceptance)?;

    let judgment_path = run_dir.join("judgment.json");
    let judgment_markdown_path = run_dir.join("judgment.md");
    let judgment = build_judgment_report(run_dir, &judgment_path, Some(&judgment_markdown_path))?;
    write_json(judgment_path.clone(), &judgment)?;
    write_judgment_markdown(judgment_markdown_path.clone(), &judgment)?;

    let review_path = run_dir.join("review-pack.json");
    let review_markdown_path = run_dir.join("review-pack.md");
    let review = build_review_pack_report(
        &ReviewPackOptions {
            run_dir: run_dir.to_path_buf(),
            out: Some(review_path.clone()),
            markdown: Some(review_markdown_path.clone()),
            no_markdown: false,
            create_evidence_dirs: true,
            json: false,
        },
        &review_path,
        Some(&review_markdown_path),
    )?;
    write_json(review_path.clone(), &review)?;
    write_review_pack_markdown(review_markdown_path.clone(), &review)?;

    let privacy_path = run_dir.join("privacy.json");
    let privacy_markdown_path = run_dir.join("privacy.md");
    let privacy = build_privacy_report(run_dir, &privacy_path, Some(&privacy_markdown_path))?;
    write_json(privacy_path.clone(), &privacy)?;
    write_privacy_markdown(privacy_markdown_path.clone(), &privacy)?;

    let rollback_path = run_dir.join("rollback.json");
    let rollback_markdown_path = run_dir.join("rollback.md");
    let rollback = build_rollback_report(run_dir, &rollback_path, Some(&rollback_markdown_path))?;
    write_json(rollback_path.clone(), &rollback)?;
    write_rollback_markdown(rollback_markdown_path.clone(), &rollback)?;

    let production_ready =
        judgment.production_ready && proof.production_ready && acceptance.final_satisfied;
    let offline_satisfied = acceptance.offline_satisfied;
    let final_satisfied = acceptance.final_satisfied;
    let mut blockers = merge_many_sorted(vec![
        judgment.blockers.clone(),
        proof.blockers.clone(),
        acceptance.blockers.clone(),
        review.blockers.clone(),
        privacy.blockers.clone(),
    ]);
    if !privacy.ok {
        blockers.push("privacy scan is not pass".into());
    }
    blockers.sort();
    blockers.dedup();
    let mut warnings = merge_many_sorted(vec![
        judgment.warnings.clone(),
        proof.warnings.clone(),
        acceptance.warnings.clone(),
        review.warnings.clone(),
        privacy.warnings.clone(),
        rollback.warnings.clone(),
    ]);
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else if production_ready {
        "complete"
    } else if offline_satisfied {
        "needsLiveProof"
    } else {
        "needsWork"
    }
    .to_string();
    let verdict = match status.as_str() {
        "complete" => "done",
        "needsLiveProof" => "notDoneNeedsLiveProof",
        "blocked" => "notDoneBlocked",
        _ => "notDoneNeedsWork",
    }
    .to_string();

    let checks = vec![
        closeout_check(
            "judgment",
            "Run Judgment",
            if judgment.production_ready {
                "pass"
            } else if judgment.status == "blocked" {
                "fail"
            } else {
                "pending"
            },
            format!(
                "judgment status: {}, verdict: {}",
                judgment.status, judgment.verdict
            ),
            vec![judgment.judgment_path.clone()],
            Some(format!(
                "rs autopilot judge {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
        closeout_check(
            "proof",
            "Proof Ledger",
            if proof.production_ready {
                "pass"
            } else {
                "pending"
            },
            format!(
                "proof status: {}, missing {}",
                proof.status,
                proof.missing_proof.len()
            ),
            vec![proof.proof_path.clone()],
            Some(format!(
                "rs autopilot proof {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
        closeout_check(
            "acceptance",
            "Creator Acceptance",
            if acceptance.final_satisfied {
                "pass"
            } else if acceptance.offline_satisfied {
                "pending"
            } else {
                "fail"
            },
            format!(
                "acceptance status: {}, score: {}",
                acceptance.status, acceptance.score
            ),
            vec![acceptance.acceptance_path.clone()],
            Some(format!(
                "rs autopilot acceptance {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
        closeout_check(
            "review-pack",
            "Review Pack",
            if review.safe_to_present {
                "pass"
            } else {
                "fail"
            },
            format!(
                "review status: {}, verdict: {}",
                review.status, review.verdict
            ),
            vec![review.review_path.clone()],
            Some(format!(
                "rs autopilot review-pack {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
        closeout_check(
            "privacy",
            "Privacy",
            if privacy.ok { "pass" } else { "fail" },
            format!("privacy status: {}", privacy.status),
            vec![privacy.privacy_path.clone()],
            privacy
                .next_actions
                .first()
                .and_then(|action| action.command.clone()),
        ),
        closeout_check(
            "rollback",
            "Rollback Evidence",
            if judgment.rollback_verified {
                "pass"
            } else if judgment.live_apply_verified {
                "fail"
            } else {
                "pending"
            },
            format!("rollback status: {}", rollback.status),
            vec![rollback.rollback_path.clone()],
            Some(format!(
                "rs autopilot rollback {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
    ];

    let mut safe_to_say = merge_many_sorted(vec![
        proof.claim_ready.clone(),
        acceptance.claim_ready.clone(),
        privacy.claim_ready.clone(),
        review.safe_to_say.clone(),
    ]);
    if production_ready {
        safe_to_say.push(
            "This run satisfies the creator request with live apply, rollback, and playtest proof."
                .into(),
        );
    } else if offline_satisfied {
        safe_to_say.push("The run is offline-ready, but live apply, rollback, and playtest proof are still required before calling it done.".into());
    }
    safe_to_say.sort();
    safe_to_say.dedup();
    let mut do_not_say = merge_many_sorted(vec![
        proof.do_not_claim.clone(),
        acceptance.do_not_claim.clone(),
        review.do_not_say.clone(),
        privacy.do_not_claim.clone(),
        rollback.do_not_claim.clone(),
    ]);
    do_not_say.push(
        "Do not tell the creator the task is done unless closeout.status is complete.".into(),
    );
    do_not_say.sort();
    do_not_say.dedup();

    let mut next_actions = Vec::new();
    if production_ready {
        next_actions.push(coach_action(
            1,
            "Share completion summary",
            Some(format!(
                "rs autopilot closeout {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Use safeToSay and artifacts when reporting completion.",
            false,
            false,
        ));
    } else {
        next_actions.extend(judgment.next_actions.clone());
        next_actions.extend(proof.next_actions.clone());
        next_actions.extend(acceptance.next_actions.clone());
        next_actions.push(coach_action(
            2,
            "Refresh closeout",
            Some(format!(
                "rs autopilot closeout {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Regenerate the done/not-done verdict after apply, rollback, playtest, or proof changes.",
            false,
            false,
        ));
    }
    dedup_next_actions(&mut next_actions);

    let mut artifacts = BTreeMap::from([
        (
            "closeout".into(),
            closeout_path.to_string_lossy().to_string(),
        ),
        ("judgment".into(), judgment.judgment_path.clone()),
        ("proof".into(), proof.proof_path.clone()),
        ("acceptance".into(), acceptance.acceptance_path.clone()),
        ("reviewPack".into(), review.review_path.clone()),
        ("privacy".into(), privacy.privacy_path.clone()),
        ("rollback".into(), rollback.rollback_path.clone()),
    ]);
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "closeoutMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.extend(review.artifacts.clone());
    let agent_brief = match status.as_str() {
        "complete" => {
            "Closeout is complete. Report only safeToSay claims and cite proof, acceptance, judgment, rollback, and playtest artifacts.".into()
        }
        "needsLiveProof" => {
            "Closeout is not done. The run is offline-ready, but live apply, rollback, and playtest proof are still required.".into()
        }
        "blocked" => {
            "Closeout is blocked. Resolve blockers before telling the creator the request is handled.".into()
        }
        _ => "Closeout needs more work before the request can be called handled.".into(),
    };

    Ok(CloseoutReport {
        schema_version: "rs.autopilot.closeout.v1".into(),
        generated_at: now_stamp(),
        closeout_path: closeout_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        run_dir: run_dir.to_string_lossy().to_string(),
        status,
        verdict,
        production_ready,
        final_satisfied,
        offline_satisfied,
        judgment_status: judgment.status,
        proof_status: proof.status,
        acceptance_status: acceptance.status,
        review_status: review.status,
        privacy_status: privacy.status,
        rollback_status: rollback.status,
        checks,
        safe_to_say,
        do_not_say,
        artifacts,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn closeout_check(
    id: &str,
    title: &str,
    status: &str,
    summary: String,
    evidence: Vec<String>,
    next_command: Option<String>,
) -> CloseoutCheck {
    CloseoutCheck {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        summary,
        evidence,
        next_command,
    }
}

fn write_closeout_markdown(path: PathBuf, report: &CloseoutReport) -> AppResult<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, render_closeout_markdown(report))?;
    Ok(())
}

fn render_closeout_markdown(report: &CloseoutReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Closeout\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Verdict: `{}`\n", report.verdict));
    out.push_str(&format!("- Run: `{}`\n", report.run_dir));
    out.push_str(&format!(
        "- Production ready: `{}`\n",
        report.production_ready
    ));
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push_str("\n\n## Checks\n\n");
    for check in &report.checks {
        out.push_str(&format!(
            "- {}: `{}` - {}\n",
            check.title, check.status, check.summary
        ));
    }
    out.push_str("\n## Safe To Say\n\n");
    for claim in &report.safe_to_say {
        out.push_str(&format!("- {claim}\n"));
    }
    out.push_str("\n## Do Not Say\n\n");
    for claim in &report.do_not_say {
        out.push_str(&format!("- {claim}\n"));
    }
    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n", action.priority, action.title));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push_str(&format!("   {}\n", action.reason));
    }
    out
}

fn print_closeout_summary(report: &CloseoutReport) {
    println!("Autopilot closeout: {}", report.status);
    println!("Verdict: {}", report.verdict);
    println!("Run: {}", report.run_dir);
    println!("JSON: {}", report.closeout_path);
    if let Some(markdown) = &report.markdown_path {
        println!("Markdown: {markdown}");
    }
    println!("Production ready: {}", report.production_ready);
    if !report.blockers.is_empty() {
        println!("\nBlockers:");
        for blocker in report.blockers.iter().take(10) {
            println!("  - {blocker}");
        }
    }
    if !report.warnings.is_empty() {
        println!("\nWarnings:");
        for warning in report.warnings.iter().take(10) {
            println!("  - {warning}");
        }
    }
    if let Some(action) = report.next_actions.first() {
        println!("\nNext: {}", action.title);
        if let Some(command) = &action.command {
            println!("{command}");
        }
    }
}

pub fn timeline(options: TimelineOptions) -> AppResult<()> {
    let out = options
        .out
        .clone()
        .unwrap_or_else(|| options.run_dir.join("timeline.json"));
    let markdown_path = if options.no_markdown {
        None
    } else {
        Some(
            options
                .markdown
                .clone()
                .unwrap_or_else(|| out.with_extension("md")),
        )
    };
    let report = build_timeline_report(&options.run_dir, &out, markdown_path.as_deref())?;
    write_json(out.clone(), &report)?;
    if let Some(markdown_path) = markdown_path {
        write_timeline_markdown(markdown_path, &report)?;
    }
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_timeline_summary(&report);
    }
    Ok(())
}

