fn load_survey_context(path: &Path) -> AppResult<SurveyContext> {
    let value = read_json_file(path)?;
    let snapshot_value = value
        .get("snapshot")
        .cloned()
        .ok_or_else(|| AppError::Other("context JSON is missing snapshot".into()))?;
    let validation_value = value
        .get("validation")
        .cloned()
        .ok_or_else(|| AppError::Other("context JSON is missing validation".into()))?;
    let deps_value = value
        .get("deps")
        .cloned()
        .ok_or_else(|| AppError::Other("context JSON is missing deps".into()))?;
    let snapshot: SnapshotResponse = serde_json::from_value(snapshot_value)?;
    let validation: ValidateResponse = serde_json::from_value(validation_value)?;
    let deps: DepsResponse = serde_json::from_value(deps_value)?;
    let read = value.get("read").cloned().filter(|value| !value.is_null());
    let studio = string_field(&value, "studio");
    let path_text = string_field(&value, "path")
        .unwrap_or_else(|| snapshot.root_path.clone())
        .trim()
        .to_string();
    Ok(SurveyContext {
        source: path.to_string_lossy().to_string(),
        studio,
        path: path_text,
        snapshot,
        validation,
        deps,
        read,
    })
}

fn build_survey_report(
    context: SurveyContext,
    survey_path: &Path,
    markdown_path: Option<&Path>,
) -> SurveyReport {
    let summary = build_survey_summary(&context);
    let terms = survey_terms(&context);
    let system_signals = build_survey_signals(&context, &terms);
    let risk_findings = build_survey_findings(&context);
    let mut blockers: Vec<String> = risk_findings
        .iter()
        .filter(|finding| finding.severity == "blocker")
        .map(|finding| finding.message.clone())
        .collect();
    let mut warnings: Vec<String> = risk_findings
        .iter()
        .filter(|finding| finding.severity == "warning")
        .map(|finding| finding.message.clone())
        .collect();
    warnings.extend(context.snapshot.warnings.clone());
    warnings.extend(context.validation.warnings.clone());
    warnings.extend(context.deps.warnings.clone());
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    let status = if !blockers.is_empty() {
        "blocked"
    } else if !warnings.is_empty() {
        "needsReview"
    } else {
        "readyForPlanning"
    }
    .to_string();
    let safe_zones = build_survey_safe_zones(&context.path);
    let suggested_recipes = build_survey_recipe_suggestions(&context, &system_signals);
    let next_actions = build_survey_next_actions(&context, survey_path, &status);
    let mut artifacts =
        BTreeMap::from([("survey".into(), survey_path.to_string_lossy().to_string())]);
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "surveyMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    if context.source != "liveStudio" {
        artifacts.insert("sourceContext".into(), context.source.clone());
    }
    let agent_brief = if status == "blocked" {
        "Place survey found blockers. Fix validation failures before planning or applying new Autopilot work.".into()
    } else if status == "needsReview" {
        "Place survey is usable for planning, but warnings should shape the next plan and safe mutation zone.".into()
    } else {
        "Place survey is ready for AI planning. Use suggestedRecipes and safeZones before proposing mutations.".into()
    };

    SurveyReport {
        schema_version: "rs.autopilot.survey.v1".into(),
        generated_at: now_stamp(),
        source: context.source,
        studio: context.studio,
        path: context.path,
        survey_path: survey_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        summary,
        system_signals,
        risk_findings,
        safe_zones,
        suggested_recipes,
        blockers,
        warnings,
        next_actions,
        artifacts,
        agent_brief,
    }
}

fn build_survey_summary(context: &SurveyContext) -> SurveySummary {
    let script_count = context
        .snapshot
        .script_counts
        .values()
        .sum::<usize>()
        .max(context.deps.scripts.len());
    SurveySummary {
        root_path: context.snapshot.root_path.clone(),
        total_instances: context.snapshot.total_instances,
        max_depth: context.snapshot.max_depth,
        script_count,
        remote_count: context
            .snapshot
            .remote_count
            .max(context.deps.remotes.len()),
        ui_count: context.snapshot.ui_count,
        tool_count: context.snapshot.tool_count,
        mesh_part_count: context.snapshot.mesh_part_count,
        asset_reference_count: context
            .snapshot
            .asset_references
            .len()
            .max(context.deps.dependencies.len()),
        validation_fail: context.validation.summary.fail,
        validation_warn: context.validation.summary.warn,
        top_classes: top_survey_counts(&context.snapshot.class_counts, 8),
        top_subtrees: context
            .snapshot
            .top_subtrees
            .iter()
            .take(8)
            .cloned()
            .collect(),
    }
}

fn top_survey_counts(counts: &BTreeMap<String, usize>, limit: usize) -> Vec<SurveyCount> {
    let mut rows: Vec<_> = counts
        .iter()
        .map(|(name, count)| SurveyCount {
            name: name.clone(),
            count: *count,
        })
        .collect();
    rows.sort_by(|left, right| {
        right
            .count
            .cmp(&left.count)
            .then_with(|| left.name.cmp(&right.name))
    });
    rows.truncate(limit);
    rows
}

fn survey_terms(context: &SurveyContext) -> Vec<String> {
    let mut terms = Vec::new();
    terms.extend(context.snapshot.paths.clone());
    terms.extend(context.deps.scripts.clone());
    terms.extend(context.deps.remotes.clone());
    terms.extend(context.deps.unowned_instances.clone());
    terms.extend(
        context
            .snapshot
            .top_subtrees
            .iter()
            .map(|subtree| subtree.path.clone()),
    );
    terms.extend(
        context
            .snapshot
            .asset_references
            .iter()
            .map(|asset| format!("{} {} {}", asset.path, asset.property, asset.asset_kind)),
    );
    terms.extend(context.deps.dependencies.iter().map(|dependency| {
        format!(
            "{} {} {} {}",
            dependency.path, dependency.property, dependency.kind, dependency.value
        )
    }));
    if let Some(read) = &context.read {
        terms.push(read.to_string());
    }
    terms
}

fn build_survey_signals(context: &SurveyContext, terms: &[String]) -> Vec<SurveySignal> {
    let script_count = context
        .snapshot
        .script_counts
        .values()
        .sum::<usize>()
        .max(context.deps.scripts.len());
    let has_server_script = context
        .snapshot
        .script_counts
        .get("Script")
        .copied()
        .unwrap_or(0)
        > 0
        || contains_any(terms, &["serverscriptservice", ".server.lua", "server"]);
    let has_ui = context.snapshot.ui_count > 0 || contains_any(terms, &["startergui", "screengui"]);
    let has_remotes = context.snapshot.remote_count > 0 || !context.deps.remotes.is_empty();
    let has_loop = contains_any(
        terms,
        &[
            "shop",
            "coin",
            "cash",
            "quest",
            "tycoon",
            "checkpoint",
            "enemy",
            "weapon",
            "tool",
            "inventory",
            "round",
            "npc",
            "reward",
        ],
    );
    let has_persistence = contains_any(
        terms,
        &[
            "datastore",
            "profile",
            "save",
            "leaderstats",
            "cash",
            "currency",
        ],
    );
    let has_assets = !context.snapshot.asset_references.is_empty()
        || !context.deps.dependencies.is_empty()
        || context.snapshot.mesh_part_count > 0;
    vec![
        survey_signal(
            "server-authority",
            "Server Authority",
            if has_server_script {
                "present"
            } else if script_count > 0 {
                "review"
            } else {
                "gap"
            },
            evidence_for(terms, &["serverscriptservice", ".server.lua", "server"], 3),
            if has_server_script {
                "Keep gameplay-critical checks on the server and review generated scripts before apply."
            } else {
                "Add server-owned scripts before trusting economy, combat, purchase, or save behavior."
            },
        ),
        survey_signal(
            "client-ui",
            "Player UI",
            if has_ui { "present" } else { "gap" },
            evidence_for(
                terms,
                &["startergui", "screengui", "frame", "textbutton"],
                3,
            ),
            if has_ui {
                "Reuse or namespace UI under StarterGui so the creator can review changes clearly."
            } else {
                "Plan visible UI affordances for onboarding, feedback, currency, or progression."
            },
        ),
        survey_signal(
            "remote-contracts",
            "Remote Contracts",
            if has_remotes { "present" } else { "gap" },
            context.deps.remotes.iter().take(3).cloned().collect(),
            if has_remotes {
                "Map remote ownership before adding client actions."
            } else {
                "Create explicit RemoteEvent/RemoteFunction contracts for client-to-server interactions."
            },
        ),
        survey_signal(
            "gameplay-loop",
            "Playable Loop",
            if has_loop { "present" } else { "gap" },
            evidence_for(
                terms,
                &[
                    "shop",
                    "coin",
                    "quest",
                    "tycoon",
                    "checkpoint",
                    "enemy",
                    "inventory",
                ],
                4,
            ),
            if has_loop {
                "Extend the existing loop rather than adding unrelated isolated systems."
            } else {
                "Start with a small loop: objective, interaction, reward, feedback, and next goal."
            },
        ),
        survey_signal(
            "persistence",
            "Persistence",
            if has_persistence { "present" } else { "gap" },
            evidence_for(
                terms,
                &[
                    "datastore",
                    "profile",
                    "save",
                    "leaderstats",
                    "cash",
                    "currency",
                ],
                3,
            ),
            if has_persistence {
                "Treat save data as high-risk and keep migration/rollback notes explicit."
            } else {
                "Add persistence only after the loop is clear, with server-owned validation."
            },
        ),
        survey_signal(
            "asset-surface",
            "Asset Surface",
            if has_assets { "present" } else { "absent" },
            context
                .snapshot
                .asset_references
                .iter()
                .take(3)
                .map(|asset| format!("{}.{} -> {}", asset.path, asset.property, asset.asset_uri))
                .collect(),
            if has_assets {
                "Track imported asset IDs and validate ownership before publishing."
            } else {
                "No asset-heavy surface was detected; recipes can start with scripts, UI, and simple parts."
            },
        ),
        survey_signal(
            "ownership",
            "Ownership Boundaries",
            if context.deps.unowned_instances.is_empty() {
                "present"
            } else {
                "review"
            },
            context
                .deps
                .unowned_instances
                .iter()
                .take(4)
                .cloned()
                .collect(),
            if context.deps.unowned_instances.is_empty() {
                "Prefer namespaced, rs-owned folders for new Autopilot work."
            } else {
                "Avoid overwriting unowned content; create namespaced additions or require explicit approval."
            },
        ),
    ]
}

fn survey_signal(
    id: &str,
    title: &str,
    status: &str,
    evidence: Vec<String>,
    recommendation: &str,
) -> SurveySignal {
    SurveySignal {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        evidence,
        recommendation: recommendation.into(),
    }
}

fn build_survey_findings(context: &SurveyContext) -> Vec<SurveyFinding> {
    let mut findings = Vec::new();
    for diagnostic in &context.validation.diagnostics {
        let severity = if diagnostic.severity == "fail" {
            "blocker"
        } else if diagnostic.severity == "warn" {
            "warning"
        } else {
            "info"
        };
        findings.push(SurveyFinding {
            severity: severity.into(),
            category: format!("validation:{}", diagnostic.rule),
            path: Some(diagnostic.path.clone()),
            message: diagnostic.message.clone(),
            evidence: vec![format!(
                "{} {}{}",
                diagnostic.severity,
                diagnostic.rule,
                diagnostic
                    .property
                    .as_ref()
                    .map(|property| format!(".{property}"))
                    .unwrap_or_default()
            )],
        });
    }
    for duplicate in &context.snapshot.duplicate_sibling_names {
        findings.push(SurveyFinding {
            severity: "warning".into(),
            category: "duplicate-sibling-name".into(),
            path: Some(duplicate.parent_path.clone()),
            message: format!(
                "{} has {} children named {}",
                duplicate.parent_path, duplicate.count, duplicate.name
            ),
            evidence: vec![duplicate.name.clone()],
        });
    }
    for path in context.deps.unowned_instances.iter().take(25) {
        findings.push(SurveyFinding {
            severity: "warning".into(),
            category: "unowned-instance".into(),
            path: Some(path.clone()),
            message: format!("unowned instance may need explicit review before mutation: {path}"),
            evidence: vec![path.clone()],
        });
    }
    for asset in context.snapshot.asset_references.iter().take(25) {
        findings.push(SurveyFinding {
            severity: "info".into(),
            category: "asset-reference".into(),
            path: Some(asset.path.clone()),
            message: format!(
                "{}.{} references {}",
                asset.path, asset.property, asset.asset_uri
            ),
            evidence: vec![asset.asset_kind.clone()],
        });
    }
    findings
}

fn build_survey_safe_zones(path: &str) -> Vec<SurveySafeZone> {
    let path = path.trim();
    if path.eq_ignore_ascii_case("game") {
        return vec![
            survey_safe_zone("game.Workspace.RSAutopilot", "Namespaced world geometry and gameplay folders stay separate from existing Workspace content."),
            survey_safe_zone("game.ReplicatedStorage.RSAutopilot", "Shared remotes and module contracts are visible without overwriting existing services."),
            survey_safe_zone("game.ServerScriptService.RSAutopilot", "Server-owned gameplay logic can be reviewed and rolled back as one namespace."),
            survey_safe_zone("game.StarterGui.RSAutopilot", "Generated player UI stays isolated from hand-authored screens."),
        ];
    }
    vec![survey_safe_zone(
        &format!("{}.RSAutopilot", path.trim_end_matches('.')),
        "Namespaced additions reduce overwrite risk inside the surveyed scope.",
    )]
}

fn survey_safe_zone(path: &str, reason: &str) -> SurveySafeZone {
    SurveySafeZone {
        path: path.into(),
        reason: reason.into(),
        command_hint: format!(
            "Use Autopilot plans that create or update children under {}.",
            command_arg(path)
        ),
    }
}

fn build_survey_recipe_suggestions(
    context: &SurveyContext,
    signals: &[SurveySignal],
) -> Vec<SurveyRecipeSuggestion> {
    let has_signal = |id: &str, status: &str| {
        signals
            .iter()
            .any(|signal| signal.id == id && signal.status == status)
    };
    let mut suggestions = Vec::new();
    if has_signal("gameplay-loop", "gap") {
        suggestions.push(survey_recipe_suggestion(
            "collectibleCoin",
            10,
            "Create the smallest objective -> touch interaction -> reward loop.",
            &context.path,
        ));
    }
    if has_signal("client-ui", "gap") {
        suggestions.push(survey_recipe_suggestion(
            "starterShop",
            20,
            "Add visible player feedback and a reviewable purchase UI.",
            &context.path,
        ));
    }
    if has_signal("persistence", "gap") {
        suggestions.push(survey_recipe_suggestion(
            "saveDataScaffold",
            30,
            "Prepare server-owned save structure after the first loop is reviewable.",
            &context.path,
        ));
    }
    if context.snapshot.tool_count == 0
        && !contains_any(&survey_terms(context), &["weapon", "tool", "equip"])
    {
        suggestions.push(survey_recipe_suggestion(
            "toolSystem",
            40,
            "Give players a tangible action surface if the creator request needs hands-on interaction.",
            &context.path,
        ));
    }
    suggestions.truncate(4);
    suggestions
}

fn survey_recipe_suggestion(
    recipe: &str,
    priority: u8,
    reason: &str,
    scope: &str,
) -> SurveyRecipeSuggestion {
    SurveyRecipeSuggestion {
        recipe: recipe.into(),
        priority,
        reason: reason.into(),
        command: format!(
            "rs autopilot compose \"<creator request>\" --scope {} --recipe {} --format json",
            command_arg(scope),
            recipe
        ),
    }
}

fn build_survey_next_actions(
    context: &SurveyContext,
    survey_path: &Path,
    status: &str,
) -> Vec<CoachAction> {
    let mut actions = Vec::new();
    if status == "blocked" {
        actions.push(coach_action(
            1,
            "Fix validation blockers",
            Some(format!(
                "rs validate --path {} --format json",
                command_arg(&context.path)
            )),
            "Validation failures should be understood before generating or applying new plans.",
            true,
            false,
        ));
    }
    actions.push(coach_action(
        2,
        "Create a survey-aware planner pack",
        Some(format!(
            "rs autopilot planner-pack \"<creator request>\" --context {} --format json",
            command_arg(survey_path.to_string_lossy().as_ref())
        )),
        "Pass the current place map into the next AI planning step.",
        false,
        false,
    ));
    actions.push(coach_action(
        3,
        "Start a reviewable run",
        Some(format!(
            "rs autopilot start \"<creator request>\" --scope {} --format json",
            command_arg(&context.path)
        )),
        "Create the full offline run packet after choosing the creator request.",
        false,
        false,
    ));
    actions.push(coach_action(
        4,
        "Refresh live context",
        Some(format!(
            "rs autopilot context --path {} --out .rs\\autopilot\\context --include-paths --format json",
            command_arg(&context.path)
        )),
        "Capture raw snapshot, validation, deps, and optional read data when the place changes.",
        true,
        false,
    ));
    dedup_next_actions(&mut actions);
    actions
}

fn contains_any(terms: &[String], needles: &[&str]) -> bool {
    terms.iter().any(|term| {
        let lower = term.to_ascii_lowercase();
        needles
            .iter()
            .any(|needle| lower.contains(&needle.to_ascii_lowercase()))
    })
}

fn evidence_for(terms: &[String], needles: &[&str], limit: usize) -> Vec<String> {
    let mut evidence = Vec::new();
    for term in terms {
        let lower = term.to_ascii_lowercase();
        if needles
            .iter()
            .any(|needle| lower.contains(&needle.to_ascii_lowercase()))
            && !evidence.contains(term)
        {
            evidence.push(term.clone());
        }
        if evidence.len() >= limit {
            break;
        }
    }
    evidence
}

fn write_survey_markdown(path: PathBuf, report: &SurveyReport) -> AppResult<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, render_survey_markdown(report))?;
    Ok(())
}

fn render_survey_markdown(report: &SurveyReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Place Survey\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Path: `{}`\n", report.path));
    out.push_str(&format!("- Source: `{}`\n", report.source));
    out.push_str(&format!(
        "- Instances: {} total, depth {}, scripts {}, remotes {}, UI {}\n",
        report.summary.total_instances,
        report.summary.max_depth,
        report.summary.script_count,
        report.summary.remote_count,
        report.summary.ui_count
    ));
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push_str("\n\n## System Signals\n\n");
    for signal in &report.system_signals {
        out.push_str(&format!(
            "- {}: `{}` - {}\n",
            signal.title, signal.status, signal.recommendation
        ));
        for evidence in signal.evidence.iter().take(3) {
            out.push_str(&format!("  - Evidence: `{evidence}`\n"));
        }
    }
    out.push_str("\n## Safe Zones\n\n");
    for zone in &report.safe_zones {
        out.push_str(&format!("- `{}` - {}\n", zone.path, zone.reason));
    }
    out.push_str("\n## Suggested Recipes\n\n");
    if report.suggested_recipes.is_empty() {
        out.push_str("- No deterministic recipe gap was detected from the survey alone.\n");
    } else {
        for recipe in &report.suggested_recipes {
            out.push_str(&format!(
                "- `{}` - {} (`{}`)\n",
                recipe.recipe, recipe.reason, recipe.command
            ));
        }
    }
    out.push_str("\n## Findings\n\n");
    if report.risk_findings.is_empty() {
        out.push_str(
            "- No validation, ownership, duplicate-name, or asset findings were detected.\n",
        );
    } else {
        for finding in report.risk_findings.iter().take(30) {
            let path = finding
                .path
                .as_ref()
                .map(|path| format!(" `{path}`"))
                .unwrap_or_default();
            out.push_str(&format!(
                "- `{}` {}{} - {}\n",
                finding.severity, finding.category, path, finding.message
            ));
        }
    }
    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n", action.priority, action.title));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push_str(&format!("   {}\n", action.reason));
    }
    out
}

fn print_survey_summary(report: &SurveyReport) {
    println!("Autopilot survey: {}", report.status);
    println!("Path: {}", report.path);
    println!("JSON: {}", report.survey_path);
    if let Some(markdown) = &report.markdown_path {
        println!("Markdown: {markdown}");
    }
    println!(
        "Instances: {}  Scripts: {}  Remotes: {}  UI: {}",
        report.summary.total_instances,
        report.summary.script_count,
        report.summary.remote_count,
        report.summary.ui_count
    );
    if !report.blockers.is_empty() {
        println!("\nBlockers:");
        for blocker in report.blockers.iter().take(10) {
            println!("  - {blocker}");
        }
    }
    if !report.warnings.is_empty() {
        println!("\nWarnings:");
        for warning in report.warnings.iter().take(10) {
            println!("  - {warning}");
        }
    }
    println!("\nSignals:");
    for signal in &report.system_signals {
        println!("  - {} [{}]", signal.title, signal.status);
    }
    if let Some(action) = report.next_actions.first() {
        println!("\nNext: {}", action.title);
        if let Some(command) = &action.command {
            println!("{command}");
        }
    }
}

fn build_reconcile_report(
    options: &ReconcileOptions,
    reconcile_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<ReconcileReport> {
    let plan_path = options.run_dir.join("plan.json");
    let plan = read_plan(&plan_path)?;
    validate_plan(&plan)?;
    let planned_paths = created_paths_for_plan(&plan);
    let evidence = load_reconcile_evidence(options)?;
    let matched_paths = planned_paths
        .iter()
        .filter(|planned| {
            evidence
                .observed_paths
                .iter()
                .any(|observed| studio_paths_match(planned, observed))
        })
        .cloned()
        .collect::<Vec<_>>();
    let matched_set = matched_paths.iter().cloned().collect::<BTreeSet<_>>();
    let missing_paths = planned_paths
        .iter()
        .filter(|path| !matched_set.contains(*path))
        .cloned()
        .collect::<Vec<_>>();
    let apply = read_json_if_exists(&options.run_dir.join("apply.json"))?;
    let applied = apply
        .as_ref()
        .and_then(|value| value.get("status"))
        .and_then(Value::as_str)
        == Some("applied");
    let mut findings = evidence.findings;
    let mut blockers = evidence.blockers;
    let mut warnings = evidence.warnings;
    if planned_paths.is_empty() {
        warnings.push("plan.json does not create or update any Studio paths to reconcile".into());
    }
    if evidence.observed_paths.is_empty() {
        blockers.push(
            "no observed Studio paths were available; capture context or survey with paths before reconciling"
                .into(),
        );
        findings.push(ReconcileFinding {
            id: "missing-observed-paths".into(),
            severity: "blocker".into(),
            category: "evidence".into(),
            path: None,
            message: "No context or survey path evidence was available.".into(),
            evidence: vec![
                "expected context snapshot.paths or survey summary.topSubtrees path evidence"
                    .into(),
            ],
            next_command: Some(format!(
                "rs autopilot context --path {} --out {} --include-paths --format json",
                command_arg(&plan.request.scope),
                command_arg(options.run_dir.join("context").to_string_lossy().as_ref())
            )),
        });
    }
    for path in &missing_paths {
        let severity = if applied { "blocker" } else { "warning" };
        let message = if applied {
            format!("planned path is missing from live evidence after apply: {path}")
        } else {
            format!("planned path is not present in live evidence yet: {path}")
        };
        if applied {
            blockers.push(message.clone());
        } else {
            warnings.push(message.clone());
        }
        findings.push(ReconcileFinding {
            id: format!("missing-{}", slug(path)),
            severity: severity.into(),
            category: "path-reconciliation".into(),
            path: Some(path.clone()),
            message,
            evidence: evidence.observed_paths.iter().take(6).cloned().collect(),
            next_command: Some(reconcile_refresh_context_command(&plan, options)),
        });
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    findings.sort_by(|left, right| left.id.cmp(&right.id));
    findings.dedup_by(|left, right| left.id == right.id);
    let status = reconcile_status(
        evidence.observed_paths.is_empty(),
        applied,
        missing_paths.is_empty(),
        &blockers,
    );
    let next_actions = build_reconcile_next_actions(&plan, options, &status, applied);
    let agent_brief = build_reconcile_agent_brief(&status, applied, &missing_paths, &blockers);

    Ok(ReconcileReport {
        schema_version: "rs.autopilot.reconcile.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        survey_path: evidence
            .survey_path
            .as_ref()
            .map(|path| path.to_string_lossy().to_string()),
        context_path: evidence
            .context_path
            .as_ref()
            .map(|path| path.to_string_lossy().to_string()),
        reconcile_path: reconcile_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id,
        prompt: plan.request.prompt,
        status,
        planned_path_count: planned_paths.len(),
        observed_path_count: evidence.observed_paths.len(),
        matched_path_count: matched_paths.len(),
        missing_paths,
        matched_paths,
        findings,
        safe_zones: evidence.safe_zones,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn load_reconcile_evidence(options: &ReconcileOptions) -> AppResult<ReconcileEvidence> {
    let survey_path = resolve_reconcile_survey_path(options);
    let mut context_path = resolve_reconcile_context_path(options);
    let mut evidence = ReconcileEvidence::default();
    if let Some(path) = survey_path {
        let value = read_json_file(&path)?;
        evidence.survey_path = Some(path);
        evidence
            .observed_paths
            .extend(reconcile_paths_from_survey(&value));
        evidence
            .safe_zones
            .extend(reconcile_safe_zones_from_survey(&value));
        evidence
            .findings
            .extend(reconcile_findings_from_survey(&value));
        if context_path.is_none() {
            context_path = reconcile_context_path_from_survey(&value);
        }
    }
    if let Some(path) = context_path {
        let value = read_json_file(&path)?;
        evidence.context_path = Some(path);
        evidence
            .observed_paths
            .extend(reconcile_paths_from_context(&value));
    }
    evidence.observed_paths = dedup_sorted(evidence.observed_paths);
    evidence
        .safe_zones
        .sort_by(|left, right| left.path.cmp(&right.path));
    evidence
        .safe_zones
        .dedup_by(|left, right| left.path == right.path);
    for finding in &evidence.findings {
        if finding.severity == "blocker" {
            evidence.blockers.push(finding.message.clone());
        } else if finding.severity == "warning" {
            evidence.warnings.push(finding.message.clone());
        }
    }
    Ok(evidence)
}

fn resolve_reconcile_survey_path(options: &ReconcileOptions) -> Option<PathBuf> {
    options.survey.clone().or_else(|| {
        [
            options.run_dir.join("survey.json"),
            options.run_dir.join("survey").join("survey.json"),
        ]
        .into_iter()
        .find(|path| path.exists())
    })
}

fn resolve_reconcile_context_path(options: &ReconcileOptions) -> Option<PathBuf> {
    options.context.clone().or_else(|| {
        [
            options.run_dir.join("context.json"),
            options.run_dir.join("context").join("context.json"),
        ]
        .into_iter()
        .find(|path| path.exists())
    })
}

fn reconcile_context_path_from_survey(value: &Value) -> Option<PathBuf> {
    value
        .get("artifacts")
        .and_then(|artifacts| artifacts.get("sourceContext"))
        .and_then(Value::as_str)
        .map(PathBuf::from)
        .filter(|path| path.exists())
}

fn reconcile_paths_from_context(value: &Value) -> Vec<String> {
    let mut paths = Vec::new();
    if let Some(snapshot) = value.get("snapshot") {
        paths.extend(string_array_field(snapshot, "paths"));
        if let Some(root) = string_field(snapshot, "rootPath") {
            paths.push(root);
        }
        paths.extend(paths_from_array_objects(
            snapshot.get("topSubtrees"),
            "path",
        ));
        paths.extend(paths_from_array_objects(
            snapshot.get("assetReferences"),
            "path",
        ));
        paths.extend(paths_from_array_objects(
            snapshot.get("duplicateSiblingNames"),
            "parentPath",
        ));
    }
    if let Some(deps) = value.get("deps") {
        paths.extend(string_array_field(deps, "scripts"));
        paths.extend(string_array_field(deps, "remotes"));
        paths.extend(string_array_field(deps, "unownedInstances"));
        paths.extend(paths_from_array_objects(deps.get("dependencies"), "path"));
    }
    if let Some(validation) = value.get("validation") {
        paths.extend(paths_from_array_objects(
            validation.get("diagnostics"),
            "path",
        ));
    }
    if let Some(read) = value.get("read") {
        collect_value_paths(read, &mut paths);
    }
    dedup_sorted(paths)
}

fn reconcile_paths_from_survey(value: &Value) -> Vec<String> {
    let mut paths = Vec::new();
    if let Some(path) = string_field(value, "path") {
        paths.push(path);
    }
    if let Some(summary) = value.get("summary") {
        if let Some(root) = string_field(summary, "rootPath") {
            paths.push(root);
        }
        paths.extend(paths_from_array_objects(summary.get("topSubtrees"), "path"));
    }
    paths.extend(paths_from_array_objects(value.get("riskFindings"), "path"));
    dedup_sorted(paths)
}

fn reconcile_safe_zones_from_survey(value: &Value) -> Vec<ReconcileSafeZone> {
    value
        .get("safeZones")
        .and_then(Value::as_array)
        .map(|zones| {
            zones
                .iter()
                .filter_map(|zone| {
                    let path = string_field(zone, "path")?;
                    let reason = string_field(zone, "reason").unwrap_or_else(|| {
                        "Survey identified this as a safer mutation zone.".into()
                    });
                    Some(ReconcileSafeZone { path, reason })
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default()
}

fn reconcile_findings_from_survey(value: &Value) -> Vec<ReconcileFinding> {
    value
        .get("riskFindings")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .enumerate()
                .filter_map(|(index, item)| {
                    let severity = string_field(item, "severity")?;
                    let category =
                        string_field(item, "category").unwrap_or_else(|| "survey".into());
                    let message = string_field(item, "message")
                        .unwrap_or_else(|| "Survey finding requires review.".into());
                    let path = string_field(item, "path");
                    Some(ReconcileFinding {
                        id: format!("survey-{}-{}", index + 1, slug(&category)),
                        severity,
                        category,
                        path,
                        message,
                        evidence: string_array_field(item, "evidence"),
                        next_command: None,
                    })
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default()
}

fn paths_from_array_objects(value: Option<&Value>, field: &str) -> Vec<String> {
    value
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(|item| string_field(item, field))
                .collect::<Vec<_>>()
        })
        .unwrap_or_default()
}

fn collect_value_paths(value: &Value, paths: &mut Vec<String>) {
    match value {
        Value::Object(map) => {
            for (key, child) in map {
                if key == "path" || key.ends_with("Path") {
                    if let Some(path) = child.as_str().filter(|text| looks_like_studio_path(text)) {
                        paths.push(path.to_string());
                    }
                }
                collect_value_paths(child, paths);
            }
        }
        Value::Array(items) => {
            for item in items {
                collect_value_paths(item, paths);
            }
        }
        _ => {}
    }
}

fn looks_like_studio_path(value: &str) -> bool {
    let value = value.trim();
    value == "game"
        || value.starts_with("game.")
        || value.starts_with("Workspace.")
        || value.starts_with("ServerScriptService.")
        || value.starts_with("ReplicatedStorage.")
        || value.starts_with("StarterGui.")
        || value.starts_with("StarterPack.")
}

fn dedup_sorted(mut values: Vec<String>) -> Vec<String> {
    values.retain(|value| !value.trim().is_empty());
    values.sort();
    values.dedup();
    values
}

fn studio_paths_match(planned: &str, observed: &str) -> bool {
    let planned = normalize_studio_path(planned);
    let observed = normalize_studio_path(observed);
    if planned.is_empty() || observed.is_empty() {
        return false;
    }
    if planned == observed {
        return true;
    }
    if observed == "game" {
        return false;
    }
    observed.starts_with(&format!("{planned}."))
}

fn normalize_studio_path(path: &str) -> String {
    let mut normalized = path
        .trim()
        .replace('\\', ".")
        .replace('/', ".")
        .replace("..", ".")
        .trim_matches('.')
        .to_ascii_lowercase();
    for prefix in ["datamodel.", "game."] {
        if let Some(stripped) = normalized.strip_prefix(prefix) {
            normalized = stripped.to_string();
        }
    }
    normalized
}

fn reconcile_status(
    no_observed_paths: bool,
    applied: bool,
    all_matched: bool,
    blockers: &[String],
) -> String {
    if no_observed_paths {
        "needsSurvey"
    } else if applied && !all_matched {
        "driftDetected"
    } else if !blockers.is_empty() {
        "needsReview"
    } else if all_matched {
        "aligned"
    } else {
        "plannedNotApplied"
    }
    .into()
}

fn build_reconcile_next_actions(
    plan: &AutopilotPlan,
    options: &ReconcileOptions,
    status: &str,
    applied: bool,
) -> Vec<CoachAction> {
    let mut actions = Vec::new();
    let context_command = reconcile_refresh_context_command(plan, options);
    let survey_command = format!(
        "rs autopilot survey --context {} --out {} --format json",
        command_arg(
            options
                .run_dir
                .join("context")
                .join("context.json")
                .to_string_lossy()
                .as_ref()
        ),
        command_arg(
            options
                .run_dir
                .join("survey.json")
                .to_string_lossy()
                .as_ref()
        )
    );
    match status {
        "needsSurvey" => {
            actions.push(coach_action(
                1,
                "Capture live context with paths",
                Some(context_command),
                "Reconciliation needs observed Studio paths before it can compare the plan to the place.",
                true,
                false,
            ));
            actions.push(coach_action(
                2,
                "Summarize the refreshed context",
                Some(survey_command),
                "A survey adds risk findings and safe zones for the next AI move.",
                false,
                false,
            ));
        }
        "driftDetected" => {
            actions.push(coach_action(
                1,
                "Refresh the live place map",
                Some(context_command),
                "Confirm whether missing applied paths are true drift or stale evidence.",
                true,
                false,
            ));
            actions.push(coach_action(
                2,
                "Plan a repair",
                Some(format!(
                    "rs autopilot repair-plan {} --format json",
                    command_arg(options.run_dir.to_string_lossy().as_ref())
                )),
                "Applied paths missing from live evidence should be repaired or explicitly explained before more mutation.",
                false,
                false,
            ));
        }
        "plannedNotApplied" => {
            actions.push(coach_action(
                1,
                "Run live readiness",
                Some("rs autopilot ready --format json".into()),
                "The plan has not been observed in Studio yet; check the bridge before applying.",
                true,
                false,
            ));
            actions.push(coach_action(
                2,
                "Apply after approval",
                Some(format!(
                    "rs autopilot apply --plan {} --yes --rollback-on-error --validate",
                    command_arg(options.run_dir.join("plan.json").to_string_lossy().as_ref())
                )),
                "Only mutate Studio after creator approval and readiness pass.",
                true,
                true,
            ));
        }
        "aligned" => {
            actions.push(coach_action(
                1,
                "Collect playtest evidence",
                Some(format!(
                    "rs autopilot evidence {} --format json",
                    command_arg(options.run_dir.to_string_lossy().as_ref())
                )),
                "Path reconciliation is aligned; move to player-visible proof.",
                false,
                false,
            ));
            if applied {
                actions.push(coach_action(
                    2,
                    "Close out the run",
                    Some(format!(
                        "rs autopilot closeout {} --format json",
                        command_arg(options.run_dir.to_string_lossy().as_ref())
                    )),
                    "Summarize what is proven, missing, and safe to say.",
                    false,
                    false,
                ));
            }
        }
        _ => {
            actions.push(coach_action(
                1,
                "Review reconciliation findings",
                Some(format!(
                    "rs autopilot handoff {} --format json",
                    command_arg(options.run_dir.to_string_lossy().as_ref())
                )),
                "Review findings and blockers before selecting the next command.",
                false,
                false,
            ));
            actions.push(coach_action(
                2,
                "Refresh live context",
                Some(context_command),
                "Fresh observed paths can separate real drift from stale artifacts.",
                true,
                false,
            ));
        }
    }
    dedup_next_actions(&mut actions);
    actions
}

fn reconcile_refresh_context_command(plan: &AutopilotPlan, options: &ReconcileOptions) -> String {
    format!(
        "rs autopilot context --path {} --out {} --include-paths --format json",
        command_arg(&plan.request.scope),
        command_arg(options.run_dir.join("context").to_string_lossy().as_ref())
    )
}

fn build_reconcile_agent_brief(
    status: &str,
    applied: bool,
    missing_paths: &[String],
    blockers: &[String],
) -> String {
    match status {
        "needsSurvey" => "Reconciliation is blocked until the AI captures live Studio path evidence. Do not claim the plan exists in the place yet.".into(),
        "driftDetected" => format!(
            "The run was applied, but {} planned path(s) are missing from live evidence. Treat this as drift until a fresh survey proves otherwise.",
            missing_paths.len()
        ),
        "plannedNotApplied" => format!(
            "{} planned path(s) are not visible in the supplied evidence. This is expected before apply, but the AI should not claim live completion.",
            missing_paths.len()
        ),
        "aligned" if applied => "The applied run's planned paths are visible in supplied Studio evidence. Continue to gameplay proof, closeout, or creator review.".into(),
        "aligned" => "The planned paths are visible in supplied Studio evidence. Continue to proof collection before making player-facing claims.".into(),
        _ if !blockers.is_empty() => "Reconciliation found review blockers. The AI should resolve or refresh evidence before further mutation.".into(),
        _ => "Reconciliation produced warnings. Review the findings and refresh evidence if the next step would mutate Studio.".into(),
    }
}

fn write_reconcile_markdown(path: PathBuf, report: &ReconcileReport) -> AppResult<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, render_reconcile_markdown(report))?;
    Ok(())
}

fn render_reconcile_markdown(report: &ReconcileReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Reconciliation\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Run: `{}`\n", report.run_dir));
    out.push_str(&format!("- Plan: `{}`\n", report.plan_path));
    if let Some(path) = &report.context_path {
        out.push_str(&format!("- Context: `{path}`\n"));
    }
    if let Some(path) = &report.survey_path {
        out.push_str(&format!("- Survey: `{path}`\n"));
    }
    out.push_str(&format!(
        "- Paths: `{}` planned, `{}` observed, `{}` matched\n",
        report.planned_path_count, report.observed_path_count, report.matched_path_count
    ));
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push('\n');
    if !report.blockers.is_empty() {
        out.push_str("\n## Blockers\n\n");
        for blocker in &report.blockers {
            out.push_str(&format!("- {blocker}\n"));
        }
    }
    if !report.warnings.is_empty() {
        out.push_str("\n## Warnings\n\n");
        for warning in &report.warnings {
            out.push_str(&format!("- {warning}\n"));
        }
    }
    out.push_str("\n## Path Match\n\n");
    if report.matched_paths.is_empty() {
        out.push_str("- No planned paths matched the supplied evidence.\n");
    } else {
        for path in &report.matched_paths {
            out.push_str(&format!("- Matched `{path}`\n"));
        }
    }
    if !report.missing_paths.is_empty() {
        out.push_str("\nMissing:\n");
        for path in &report.missing_paths {
            out.push_str(&format!("- `{path}`\n"));
        }
    }
    if !report.safe_zones.is_empty() {
        out.push_str("\n## Safe Zones\n\n");
        for zone in &report.safe_zones {
            out.push_str(&format!("- `{}` - {}\n", zone.path, zone.reason));
        }
    }
    if !report.findings.is_empty() {
        out.push_str("\n## Findings\n\n");
        for finding in &report.findings {
            let path = finding
                .path
                .as_ref()
                .map(|path| format!(" `{path}`"))
                .unwrap_or_default();
            out.push_str(&format!(
                "- `{}` `{}`{} - {}\n",
                finding.severity, finding.category, path, finding.message
            ));
            if let Some(command) = &finding.next_command {
                out.push_str(&format!("  - Next: `{command}`\n"));
            }
        }
    }
    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n\n", action.priority, action.title));
        out.push_str(&format!("   {}\n", action.reason));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push('\n');
    }
    out
}

fn print_reconcile_summary(report: &ReconcileReport) {
    println!("Autopilot reconcile: {}", report.status);
    println!("Run: {}", report.run_dir);
    println!("Plan: {}", report.plan_path);
    println!("JSON: {}", report.reconcile_path);
    if let Some(markdown_path) = &report.markdown_path {
        println!("Markdown: {markdown_path}");
    }
    println!(
        "Paths: {} planned  {} observed  {} matched  {} missing",
        report.planned_path_count,
        report.observed_path_count,
        report.matched_path_count,
        report.missing_paths.len()
    );
    if !report.blockers.is_empty() {
        println!();
        println!("Blockers:");
        for blocker in report.blockers.iter().take(10) {
            println!("  - {blocker}");
        }
    }
    if !report.warnings.is_empty() {
        println!();
        println!("Warnings:");
        for warning in report.warnings.iter().take(10) {
            println!("  - {warning}");
        }
    }
    if let Some(action) = report.next_actions.first() {
        println!();
        println!("Next: {}", action.title);
        if let Some(command) = &action.command {
            println!("{command}");
        }
    }
}

pub fn scout(options: ScoutOptions) -> AppResult<()> {
    let out = options
        .out
        .clone()
        .unwrap_or_else(|| PathBuf::from(".rs").join("autopilot").join("scout.json"));
    let markdown_path = if options.no_markdown {
        None
    } else {
        Some(
            options
                .markdown
                .clone()
                .unwrap_or_else(|| out.with_extension("md")),
        )
    };
    let report = build_scout_report(&options, &out, markdown_path.as_deref())?;
    write_json(out.clone(), &report)?;
    if let Some(markdown_path) = markdown_path {
        write_scout_markdown(markdown_path, &report)?;
    }
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_scout_summary(&report);
    }
    Ok(())
}

fn build_scout_report(
    options: &ScoutOptions,
    scout_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<ScoutReport> {
    let prompt = options
        .prompt
        .as_deref()
        .map(str::trim)
        .filter(|prompt| !prompt.is_empty())
        .map(str::to_string);
    let survey = load_scout_survey(options)?;
    let selected_scope = options
        .scope
        .clone()
        .or_else(|| survey.as_ref().map(|survey| survey.path.clone()))
        .unwrap_or_else(|| "game".into());
    let intake_path = scout_path.with_file_name("scout-intake.json");
    let intake = build_intake_report(
        prompt.as_deref(),
        &options.root,
        options.limit,
        &intake_path,
        None,
    )?;
    let mut blockers = intake.blockers.clone();
    let mut warnings = intake.warnings.clone();
    if survey.is_none() {
        warnings.push(
            "no place survey was provided; run `rs autopilot survey` before planning against an existing place"
                .into(),
        );
    }
    if let Some(survey) = &survey {
        blockers.extend(survey.blockers.clone());
        warnings.extend(survey.warnings.clone());
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let selected_recipes = build_scout_recipes(prompt.as_deref(), survey.as_ref(), &selected_scope);
    let system_signals = survey
        .as_ref()
        .map(|survey| survey.system_signals.clone())
        .unwrap_or_default();
    let safe_zones = survey
        .as_ref()
        .map(|survey| survey.safe_zones.clone())
        .unwrap_or_else(|| build_survey_safe_zones(&selected_scope));
    let mut do_not_do = vec![
        "Do not mutate Studio until `ready` passes and the creator explicitly approves apply.".into(),
        "Do not claim live playtest, rollback, demo-ready, or production-ready proof from scout alone."
            .into(),
        "Do not overwrite unowned or hand-authored content; prefer namespaced additions unless approval is explicit."
            .into(),
    ];
    if intake.status == "needsClarification" {
        do_not_do.push(
            "Do not silently guess through blocking clarification; ask or rerun start with explicit assumptions."
                .into(),
        );
    }
    if survey.is_none() {
        do_not_do.push(
            "Do not assume the current place is empty; capture context or survey first.".into(),
        );
    }
    do_not_do.sort();
    do_not_do.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else if intake.status == "needsClarification" {
        "needsClarification"
    } else if survey.is_none() {
        "needsSurvey"
    } else {
        "readyToStart"
    }
    .to_string();
    let next_actions = build_scout_next_actions(
        prompt.as_deref(),
        &selected_scope,
        &options.root,
        scout_path,
        &selected_recipes,
        &status,
        survey.as_ref(),
    );
    let mut artifacts =
        BTreeMap::from([("scout".into(), scout_path.to_string_lossy().to_string())]);
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "scoutMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    if let Some(survey) = &survey {
        artifacts.insert("survey".into(), survey.survey_path.clone());
        if let Some(path) = &survey.markdown_path {
            artifacts.insert("surveyMarkdown".into(), path.clone());
        }
    }

    let agent_brief = match status.as_str() {
        "readyToStart" => format!(
            "Scout is ready. Use the selected recipes [{}] under scope '{}' and keep mutation behind review-pack, approval, ready, apply, validation, and live evidence.",
            selected_recipes
                .iter()
                .map(|recipe| recipe.recipe.as_str())
                .collect::<Vec<_>>()
                .join(", "),
            selected_scope
        ),
        "needsSurvey" => {
            "Scout needs a place survey before planning against existing Studio content.".into()
        }
        "needsClarification" => {
            "Scout needs a clearer creator request or explicit assumptions before choosing a build path."
                .into()
        }
        _ => "Scout is blocked by prompt or place findings; resolve blockers before planning or applying."
            .into(),
    };

    Ok(ScoutReport {
        schema_version: "rs.autopilot.scout.v1".into(),
        generated_at: now_stamp(),
        prompt,
        status,
        selected_scope,
        survey_status: survey.as_ref().map(|survey| survey.status.clone()),
        survey_path: survey.as_ref().map(|survey| survey.survey_path.clone()),
        intake_status: intake.status,
        intent: ScoutIntent {
            confidence: intake.confidence,
            assumptions: intake.assumptions,
            clarifying_questions: intake.clarifying_questions,
            acceptance_criteria: intake.acceptance_criteria,
        },
        place_summary: survey.as_ref().map(|survey| survey.summary.clone()),
        system_signals,
        selected_recipes,
        safe_zones,
        do_not_do,
        blockers,
        warnings,
        next_actions,
        artifacts,
        scout_path: scout_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        agent_brief,
    })
}

fn load_scout_survey(options: &ScoutOptions) -> AppResult<Option<SurveyReport>> {
    if let Some(path) = &options.survey {
        let report: SurveyReport = serde_json::from_value(read_json_file(path)?)?;
        return Ok(Some(report));
    }
    if let Some(path) = &options.context {
        let context = load_survey_context(path)?;
        let survey_path = path.with_file_name("survey.json");
        let mut report = build_survey_report(context, &survey_path, None);
        report
            .artifacts
            .insert("sourceContext".into(), path.to_string_lossy().to_string());
        return Ok(Some(report));
    }
    Ok(None)
}

fn build_scout_recipes(
    prompt: Option<&str>,
    survey: Option<&SurveyReport>,
    scope: &str,
) -> Vec<ScoutRecipe> {
    let mut recipes = Vec::new();
    if let Some(prompt) = prompt {
        for (index, recipe) in compose_prompt_recipes(prompt)
            .unwrap_or_default()
            .into_iter()
            .enumerate()
        {
            recipes.push(ScoutRecipe {
                recipe: recipe.clone(),
                source: "prompt".into(),
                priority: 10 + index as u8,
                reason: format!("Creator request maps to deterministic recipe `{recipe}`."),
                command: format!(
                    "rs autopilot compose \"{}\" --scope {} --recipe {} --format json",
                    shell_display_arg(prompt),
                    command_arg(scope),
                    recipe
                ),
            });
        }
    }
    if let Some(survey) = survey {
        for suggestion in &survey.suggested_recipes {
            if recipes
                .iter()
                .any(|recipe| recipe.recipe == suggestion.recipe)
            {
                continue;
            }
            recipes.push(ScoutRecipe {
                recipe: suggestion.recipe.clone(),
                source: "survey".into(),
                priority: 50 + suggestion.priority.min(49),
                reason: suggestion.reason.clone(),
                command: format!(
                    "rs autopilot compose \"{}\" --scope {} --recipe {} --format json",
                    prompt
                        .map(shell_display_arg)
                        .unwrap_or_else(|| "<creator request>".into()),
                    command_arg(scope),
                    suggestion.recipe
                ),
            });
        }
    }
    recipes.sort_by(|left, right| {
        left.priority
            .cmp(&right.priority)
            .then_with(|| left.recipe.cmp(&right.recipe))
    });
    recipes.truncate(8);
    recipes
}

fn build_scout_next_actions(
    prompt: Option<&str>,
    scope: &str,
    root: &Path,
    scout_path: &Path,
    recipes: &[ScoutRecipe],
    status: &str,
    survey: Option<&SurveyReport>,
) -> Vec<CoachAction> {
    let mut actions = Vec::new();
    if survey.is_none() {
        actions.push(coach_action(
            1,
            "Survey the place",
            Some(format!(
                "rs autopilot survey --path {} --out .rs\\autopilot\\survey.json --format json",
                command_arg(scope)
            )),
            "Ground the next plan in live Studio snapshot, validation, deps, ownership, and asset evidence.",
            true,
            false,
        ));
    }
    if status != "blocked" {
        if let Some(prompt) = prompt {
            if !recipes.is_empty() {
                actions.push(coach_action(
                    2,
                    "Start the reviewed build",
                    Some(format!(
                        "rs autopilot start \"{}\" --scope {} --root {} --format json",
                        shell_display_arg(prompt),
                        command_arg(scope),
                        command_arg(root.to_string_lossy().as_ref())
                    )),
                    "Create the offline run packet, review pack, approval packet, evidence kit, and capsule.",
                    false,
                    false,
                ));
                actions.push(coach_action(
                    3,
                    "Compose selected recipes",
                    Some(format!(
                        "rs autopilot compose \"{}\" --scope {} --recipe {} --out {} --format json",
                        shell_display_arg(prompt),
                        command_arg(scope),
                        recipes
                            .iter()
                            .map(|recipe| recipe.recipe.as_str())
                            .collect::<Vec<_>>()
                            .join(","),
                        command_arg(root.join(slug(prompt)).to_string_lossy().as_ref())
                    )),
                    "Generate a deterministic plan from the scout-selected recipe stack.",
                    false,
                    false,
                ));
            }
            actions.push(coach_action(
                4,
                "Create scout-aware planner pack",
                Some(format!(
                    "rs autopilot planner-pack \"{}\" --context {} --format json",
                    shell_display_arg(prompt),
                    command_arg(scout_path.to_string_lossy().as_ref())
                )),
                "Use the scout packet as model context for requests beyond deterministic recipes.",
                false,
                false,
            ));
        } else {
            actions.push(coach_action(
                0,
                "Ask for creator request",
                Some("rs autopilot scout \"<creator request>\" --survey .rs\\autopilot\\survey.json --format json".into()),
                "Scout needs a concrete Roblox feature request before selecting the build path.",
                false,
                false,
            ));
        }
    }
    if let Some(survey) = survey {
        actions.push(coach_action(
            8,
            "Refresh survey",
            Some(format!(
                "rs autopilot survey --path {} --out {} --format json",
                command_arg(scope),
                command_arg(&survey.survey_path)
            )),
            "Refresh place evidence after Studio changes.",
            true,
            false,
        ));
    }
    dedup_next_actions(&mut actions);
    actions
}

fn write_scout_markdown(path: PathBuf, report: &ScoutReport) -> AppResult<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, render_scout_markdown(report))?;
    Ok(())
}

fn render_scout_markdown(report: &ScoutReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Scout\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Scope: `{}`\n", report.selected_scope));
    if let Some(prompt) = &report.prompt {
        out.push_str(&format!("- Prompt: {}\n", prompt));
    }
    if let Some(survey_status) = &report.survey_status {
        out.push_str(&format!("- Survey: `{}`\n", survey_status));
    }
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push_str("\n\n## Selected Recipes\n\n");
    if report.selected_recipes.is_empty() {
        out.push_str("- No deterministic recipes were selected; use planner-pack for a strict custom plan.\n");
    } else {
        for recipe in &report.selected_recipes {
            out.push_str(&format!(
                "- `{}` ({}) - {}\n",
                recipe.recipe, recipe.source, recipe.reason
            ));
        }
    }
    out.push_str("\n## Place Signals\n\n");
    if report.system_signals.is_empty() {
        out.push_str("- No survey signals are available yet.\n");
    } else {
        for signal in &report.system_signals {
            out.push_str(&format!(
                "- {}: `{}` - {}\n",
                signal.title, signal.status, signal.recommendation
            ));
        }
    }
    out.push_str("\n## Safe Zones\n\n");
    for zone in &report.safe_zones {
        out.push_str(&format!("- `{}` - {}\n", zone.path, zone.reason));
    }
    out.push_str("\n## Do Not Do\n\n");
    for item in &report.do_not_do {
        out.push_str(&format!("- {item}\n"));
    }
    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n", action.priority, action.title));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push_str(&format!("   {}\n", action.reason));
    }
    out
}

fn print_scout_summary(report: &ScoutReport) {
    println!("Autopilot scout: {}", report.status);
    println!("Scope: {}", report.selected_scope);
    println!("JSON: {}", report.scout_path);
    if let Some(markdown) = &report.markdown_path {
        println!("Markdown: {markdown}");
    }
    if let Some(prompt) = &report.prompt {
        println!("Prompt: {prompt}");
    }
    if !report.selected_recipes.is_empty() {
        println!(
            "Recipes: {}",
            report
                .selected_recipes
                .iter()
                .map(|recipe| recipe.recipe.as_str())
                .collect::<Vec<_>>()
                .join(", ")
        );
    }
    if !report.blockers.is_empty() {
        println!("\nBlockers:");
        for blocker in report.blockers.iter().take(10) {
            println!("  - {blocker}");
        }
    }
    if !report.warnings.is_empty() {
        println!("\nWarnings:");
        for warning in report.warnings.iter().take(10) {
            println!("  - {warning}");
        }
    }
    if let Some(action) = report.next_actions.first() {
        println!("\nNext: {}", action.title);
        if let Some(command) = &action.command {
            println!("{command}");
        }
    }
}

pub fn session(options: SessionOptions) -> AppResult<()> {
    let out = options
        .out
        .clone()
        .unwrap_or_else(|| PathBuf::from(".rs").join("autopilot").join("session.json"));
    let markdown_path = if options.no_markdown {
        None
    } else {
        Some(
            options
                .markdown
                .clone()
                .unwrap_or_else(|| out.with_extension("md")),
        )
    };
    let report = build_session_report(&options, &out, markdown_path.as_deref())?;
    write_json(out.clone(), &report)?;
    if let Some(markdown_path) = markdown_path {
        write_session_markdown(markdown_path, &report)?;
    }
    if options.json {
        println!("{}", serde_json::to_string_pretty(&report)?);
    } else {
        print_session_summary(&report);
    }
    Ok(())
}

fn build_session_report(
    options: &SessionOptions,
    session_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<SessionReport> {
    let base_dir = session_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let mut scout = if let Some(path) = &options.scout {
        let mut report: ScoutReport = serde_json::from_value(read_json_file(path)?)?;
        report
            .artifacts
            .insert("sourceScout".into(), path.to_string_lossy().to_string());
        report
    } else {
        let scout_path = base_dir.join("scout.json");
        let scout_markdown_path = if options.no_markdown {
            None
        } else {
            Some(base_dir.join("scout.md"))
        };
        let scout_options = ScoutOptions {
            prompt: options.prompt.clone(),
            survey: options.survey.clone(),
            context: options.context.clone(),
            root: options.root.clone(),
            limit: options.limit,
            scope: options.scope.clone(),
            out: Some(scout_path.clone()),
            markdown: scout_markdown_path.clone(),
            no_markdown: options.no_markdown,
            json: false,
        };
        let report =
            build_scout_report(&scout_options, &scout_path, scout_markdown_path.as_deref())?;
        write_json(scout_path, &report)?;
        if let Some(path) = scout_markdown_path {
            write_scout_markdown(path, &report)?;
        }
        report
    };

    if let Some(prompt) = options
        .prompt
        .as_ref()
        .map(|prompt| prompt.trim())
        .filter(|prompt| !prompt.is_empty())
    {
        scout.prompt = Some(prompt.to_string());
    }
    if let Some(scope) = options
        .scope
        .as_ref()
        .map(|scope| scope.trim())
        .filter(|scope| !scope.is_empty())
    {
        scout.selected_scope = scope.to_string();
    }

    let mut artifacts =
        BTreeMap::from([("session".into(), session_path.to_string_lossy().to_string())]);
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "sessionMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.extend(scout.artifacts.clone());
    artifacts.insert("scout".into(), scout.scout_path.clone());

    let mut blockers = scout.blockers.clone();
    let mut warnings = scout.warnings.clone();
    let mut next_actions = scout.next_actions.clone();
    let mut run_dir_text = None;
    let mut start_status = None;
    let mut status = if scout.status == "readyToStart" {
        "readyToBootstrap"
    } else {
        scout.status.as_str()
    }
    .to_string();

    if scout.status == "readyToStart" {
        if let Some(prompt) = scout.prompt.clone() {
            let run_dir = options
                .run_dir
                .clone()
                .unwrap_or_else(|| options.root.join(slug(&prompt)));
            let start_path = run_dir.join("start.json");
            let start_markdown_path = if options.no_markdown {
                None
            } else {
                Some(run_dir.join("start.md"))
            };
            let start_options = StartOptions {
                port: options.port,
                prompt: Some(prompt),
                studio: None,
                scope: scout.selected_scope.clone(),
                root: options.root.clone(),
                run_dir: Some(run_dir.clone()),
                limit: options.limit,
                assume: options.assume,
                smoke: options.smoke.clone(),
                out: Some(start_path.clone()),
                markdown: start_markdown_path.clone(),
                no_markdown: options.no_markdown,
                json: false,
            };
            let start =
                build_start_report(&start_options, &start_path, start_markdown_path.as_deref())?;
            write_json(start_path.clone(), &start)?;
            if let Some(path) = start_markdown_path.clone() {
                write_start_markdown(path, &start)?;
            }
            run_dir_text = start.run_dir.clone();
            start_status = Some(start.status.clone());
            artifacts.insert("start".into(), start.start_path.clone());
            if let Some(path) = &start.markdown_path {
                artifacts.insert("startMarkdown".into(), path.clone());
            }
            artifacts.extend(start.artifacts.clone());
            blockers.extend(start.blockers.clone());
            warnings.extend(start.warnings.clone());
            next_actions.extend(start.next_actions.clone());
            status = if !blockers.is_empty() {
                "blocked"
            } else if start.status == "readyToReview" {
                "readyForLiveGate"
            } else {
                start.status.as_str()
            }
            .to_string();
        } else {
            blockers.push(
                "scout is ready but no creator prompt was available for start bootstrap".into(),
            );
            status = "blocked".into();
        }
    }

    if status == "readyForLiveGate" {
        next_actions.insert(
            0,
            coach_action(
                0,
                "Review session packet",
                Some(format!(
                    "rs autopilot review-pack {} --format json",
                    command_arg(run_dir_text.as_deref().unwrap_or(&scout.selected_scope))
                )),
                "Confirm approval, proof, privacy, evidence, and capsule state before live readiness.",
                false,
                false,
            ),
        );
    }
    dedup_next_actions(&mut next_actions);
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    let mut do_not_do = scout.do_not_do.clone();
    do_not_do.push(
        "Do not run mutating apply commands from session output until review-pack, approval, ready, and rollback gates are satisfied."
            .into(),
    );
    do_not_do.sort();
    do_not_do.dedup();

    let agent_brief = match status.as_str() {
        "readyForLiveGate" => {
            "Session packet is ready: scout chose the build path and start produced the offline review surface. Review artifacts, ask for approval, then run live readiness before apply.".into()
        }
        "needsSurvey" => {
            "Session needs a survey before bootstrapping a build against existing Studio content.".into()
        }
        "needsClarification" => {
            "Session needs creator clarification before bootstrapping an offline run packet.".into()
        }
        "blocked" => "Session is blocked; resolve blockers before planning or mutating Studio.".into(),
        _ => "Session is prepared but not ready for live gates yet; follow next actions in priority order.".into(),
    };

    Ok(SessionReport {
        schema_version: "rs.autopilot.session.v1".into(),
        generated_at: now_stamp(),
        session_path: session_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        prompt: scout.prompt.clone(),
        root: options.root.to_string_lossy().to_string(),
        run_dir: run_dir_text,
        scout_status: scout.status,
        start_status,
        selected_scope: scout.selected_scope,
        selected_recipes: scout.selected_recipes,
        artifacts,
        blockers,
        warnings,
        do_not_do,
        next_actions,
        agent_brief,
    })
}

fn write_session_markdown(path: PathBuf, report: &SessionReport) -> AppResult<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, render_session_markdown(report))?;
    Ok(())
}

fn render_session_markdown(report: &SessionReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Session\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Scope: `{}`\n", report.selected_scope));
    if let Some(prompt) = &report.prompt {
        out.push_str(&format!("- Prompt: {}\n", prompt));
    }
    if let Some(run_dir) = &report.run_dir {
        out.push_str(&format!("- Run: `{run_dir}`\n"));
    }
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push_str("\n\n## Selected Recipes\n\n");
    if report.selected_recipes.is_empty() {
        out.push_str("- No deterministic recipes were selected.\n");
    } else {
        for recipe in &report.selected_recipes {
            out.push_str(&format!(
                "- `{}` ({}) - {}\n",
                recipe.recipe, recipe.source, recipe.reason
            ));
        }
    }
    out.push_str("\n## Do Not Do\n\n");
    for item in &report.do_not_do {
        out.push_str(&format!("- {item}\n"));
    }
    out.push_str("\n## Artifacts\n\n");
    for (name, path) in &report.artifacts {
        out.push_str(&format!("- {name}: `{path}`\n"));
    }
    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n", action.priority, action.title));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push_str(&format!("   {}\n", action.reason));
    }
    out
}

fn print_session_summary(report: &SessionReport) {
    println!("Autopilot session: {}", report.status);
    println!("Scope: {}", report.selected_scope);
    println!("JSON: {}", report.session_path);
    if let Some(markdown) = &report.markdown_path {
        println!("Markdown: {markdown}");
    }
    if let Some(run_dir) = &report.run_dir {
        println!("Run: {run_dir}");
    }
    if !report.selected_recipes.is_empty() {
        println!(
            "Recipes: {}",
            report
                .selected_recipes
                .iter()
                .map(|recipe| recipe.recipe.as_str())
                .collect::<Vec<_>>()
                .join(", ")
        );
    }
    if !report.blockers.is_empty() {
        println!("\nBlockers:");
        for blocker in report.blockers.iter().take(10) {
            println!("  - {blocker}");
        }
    }
    if !report.warnings.is_empty() {
        println!("\nWarnings:");
        for warning in report.warnings.iter().take(10) {
            println!("  - {warning}");
        }
    }
    if let Some(action) = report.next_actions.first() {
        println!("\nNext: {}", action.title);
        if let Some(command) = &action.command {
            println!("{command}");
        }
    }
}

fn check_preconditions(
    port: u16,
    studio: Option<String>,
    plan: &AutopilotPlan,
    run_dir: &Path,
    artifact_stem: &str,
) -> AppResult<Vec<PreconditionCheck>> {
    let mut checks = Vec::new();
    for precondition in &plan.preconditions {
        let result = match precondition.kind.as_str() {
            "pathExists" => {
                let response = crate::cli::request::post::<_, SnapshotResponse>(
                    port,
                    "autopilot precondition pathExists",
                    "/snapshot",
                    &SnapshotRequest {
                        studio: studio.clone(),
                        path: precondition.path.clone(),
                        include_paths: false,
                    },
                    45,
                );
                match response {
                    Ok(snapshot) => PreconditionCheck {
                        kind: precondition.kind.clone(),
                        path: precondition.path.clone(),
                        status: "pass".into(),
                        message: format!(
                            "resolved {} with {} instance(s)",
                            snapshot.root_path, snapshot.total_instances
                        ),
                    },
                    Err(err) => PreconditionCheck {
                        kind: precondition.kind.clone(),
                        path: precondition.path.clone(),
                        status: "fail".into(),
                        message: err.to_string(),
                    },
                }
            }
            other => PreconditionCheck {
                kind: precondition.kind.clone(),
                path: precondition.path.clone(),
                status: "fail".into(),
                message: format!("unsupported precondition type '{other}'"),
            },
        };
        checks.push(result);
    }
    write_json(run_dir.join(format!("{artifact_stem}.json")), &checks)?;
    Ok(checks)
}

fn publish_check_value(port: u16, studio: Option<String>, path: String) -> AppResult<Value> {
    let validation: ValidateResponse = crate::cli::request::post(
        port,
        "autopilot publish-check validate",
        "/validate",
        &ValidateRequest {
            studio: studio.clone(),
            path: path.clone(),
            rules: vec![
                "refs".into(),
                "welds".into(),
                "tool".into(),
                "assets".into(),
                "paths".into(),
            ],
        },
        120,
    )?;
    let deps: DepsResponse = crate::cli::request::post(
        port,
        "autopilot publish-check deps",
        "/deps",
        &DepsRequest {
            studio,
            path: path.clone(),
        },
        120,
    )?;
    let mut blockers = Vec::<String>::new();
    let mut warnings = Vec::<String>::new();
    for diagnostic in &validation.diagnostics {
        let line = format!(
            "{} {}{}: {}",
            diagnostic.rule,
            diagnostic.path,
            diagnostic
                .property
                .as_ref()
                .map(|property| format!(".{property}"))
                .unwrap_or_default(),
            diagnostic.message
        );
        if diagnostic.severity == "fail" {
            blockers.push(line);
        } else if diagnostic.severity == "warn" {
            warnings.push(line);
        }
    }
    for dep in &deps.dependencies {
        if dep
            .flags
            .iter()
            .any(|flag| flag == "missing" || flag == "empty")
        {
            blockers.push(format!("missing asset {}.{}", dep.path, dep.property));
        }
        if dep.flags.iter().any(|flag| flag == "privateRisk") {
            warnings.push(format!(
                "asset may be private or inaccessible {}.{} = {}",
                dep.path, dep.property, dep.value
            ));
        }
        if dep.flags.iter().any(|flag| flag == "largeEditableRisk") {
            warnings.push(format!(
                "large editable asset risk {}.{} = {}",
                dep.path, dep.property, dep.value
            ));
        }
    }
    if !deps.unowned_instances.is_empty() {
        warnings.push(format!(
            "{} unowned/manual instance(s) found under managed check path",
            deps.unowned_instances.len()
        ));
    }
    warnings.extend(deps.warnings.clone());
    Ok(json!({
        "ok": blockers.is_empty(),
        "path": path,
        "protocolChecked": true,
        "validation": validation,
        "deps": deps,
        "blockers": blockers,
        "warnings": warnings
    }))
}

fn read_package_manifest(file: &Path) -> AppResult<Value> {
    serde_json::from_str(&std::fs::read_to_string(file.join("manifest.json"))?)
        .map_err(AppError::from)
}

fn upload_kind(operation: &AutopilotOperation) -> AppResult<crate::cli::upload::UploadKind> {
    match operation.asset_kind.as_deref().unwrap_or("image") {
        "image" => Ok(crate::cli::upload::UploadKind::Image),
        "audio" => Ok(crate::cli::upload::UploadKind::Audio),
        "model" => Ok(crate::cli::upload::UploadKind::Model),
        "mesh" => Ok(crate::cli::upload::UploadKind::Mesh),
        other => Err(AppError::Other(format!(
            "{} uploadAsset has unsupported assetKind '{other}'",
            operation.id
        ))),
    }
}

struct RunPlanOptions<'a> {
    port: u16,
    studio: Option<String>,
    plan: &'a AutopilotPlan,
    artifact_dir: &'a Path,
    source_dir: &'a Path,
    dry_run: bool,
    force: bool,
    only: &'a [String],
    exclude: &'a [String],
}

fn run_plan_operations(options: RunPlanOptions<'_>) -> AppResult<OperationRunSummary> {
    let plan = options.plan;
    let only = to_lower_set(options.only);
    let exclude = to_lower_set(options.exclude);
    let mut applied = 0;
    let mut skipped = 0;
    let mut refused = 0;
    let mut changed_paths = Vec::new();
    let mut warnings = Vec::new();

    let fix_plan = build_fix_plan_for_apply(plan, &only, &exclude, options.force)?;
    if !fix_plan.changes.is_empty() {
        let response: ApplyPlanResponse = crate::cli::request::post(
            options.port,
            "autopilot apply-plan",
            "/apply-plan",
            &ApplyPlanRequest {
                studio: options.studio.clone(),
                root_path: plan.request.scope.clone(),
                plan: serde_json::to_value(&fix_plan)?,
                dry_run: options.dry_run,
                approved: !options.dry_run,
                force: options.force,
                only: Vec::new(),
                exclude: options.exclude.to_vec(),
            },
            210,
        )?;
        applied += response.applied;
        skipped += response.skipped;
        refused += response.refused;
        changed_paths.extend(response.changed_paths);
    }

    for operation in &plan.operations {
        if !operation_allowed(operation, &only, &exclude) {
            skipped += 1;
            continue;
        }
        match operation.kind.as_str() {
            "upsertScript" => {
                let response = apply_upsert_script(
                    options.port,
                    options.studio.clone(),
                    operation,
                    options.source_dir,
                    plan,
                    options.dry_run,
                )?;
                applied += response.created + response.updated;
                skipped += response.unchanged;
                changed_paths.extend(response.changed_paths);
            }
            "validate" => {
                let response: ValidateResponse = crate::cli::request::post(
                    options.port,
                    "autopilot validate",
                    "/validate",
                    &ValidateRequest {
                        studio: options.studio.clone(),
                        path: operation
                            .path
                            .clone()
                            .unwrap_or_else(|| plan.request.scope.clone()),
                        rules: operation.rules.clone(),
                    },
                    75,
                )?;
                write_json(
                    options
                        .artifact_dir
                        .join(format!("validation-{}.json", operation.id)),
                    &response,
                )?;
                applied += 1;
            }
            "snapshot" => {
                let response: SnapshotResponse = crate::cli::request::post(
                    options.port,
                    "autopilot snapshot",
                    "/snapshot",
                    &SnapshotRequest {
                        studio: options.studio.clone(),
                        path: operation
                            .path
                            .clone()
                            .unwrap_or_else(|| plan.request.scope.clone()),
                        include_paths: false,
                    },
                    75,
                )?;
                write_json(
                    options
                        .artifact_dir
                        .join(format!("snapshot-{}.json", operation.id)),
                    &response,
                )?;
                applied += 1;
            }
            "deps" => {
                let response: DepsResponse = crate::cli::request::post(
                    options.port,
                    "autopilot deps",
                    "/deps",
                    &DepsRequest {
                        studio: options.studio.clone(),
                        path: operation
                            .path
                            .clone()
                            .unwrap_or_else(|| plan.request.scope.clone()),
                    },
                    120,
                )?;
                write_json(
                    options
                        .artifact_dir
                        .join(format!("deps-{}.json", operation.id)),
                    &response,
                )?;
                applied += 1;
            }
            "publishCheck" => {
                let report = publish_check_value(
                    options.port,
                    options.studio.clone(),
                    operation
                        .path
                        .clone()
                        .unwrap_or_else(|| plan.request.scope.clone()),
                )?;
                if report["ok"].as_bool().unwrap_or(false) {
                    applied += 1;
                } else {
                    refused += 1;
                    warnings.push(format!("publishCheck {} reported blockers", operation.id));
                }
                write_json(
                    options
                        .artifact_dir
                        .join(format!("publish-check-{}.json", operation.id)),
                    &report,
                )?;
            }
            "importImage" => {
                let file = operation.file.clone().ok_or_else(|| {
                    AppError::Other(format!("{} importImage missing file", operation.id))
                })?;
                let parent_path = operation
                    .parent_path
                    .clone()
                    .unwrap_or_else(|| "StarterGui".into());
                if options.dry_run {
                    let image = crate::cli::import_image::load_png(&file)?;
                    let kind = operation.ui_kind.clone().unwrap_or_else(|| "image".into());
                    let (ui_width, ui_height) = match &operation.size {
                        Some(size) => crate::cli::import_image::parse_size(size)?,
                        None if kind == "icon" => (64, 64),
                        None => (image.width, image.height),
                    };
                    let position = operation.position.as_deref().unwrap_or("0,0");
                    let _ = crate::cli::import_image::parse_position(position)?;
                    warnings.push(format!(
                        "dry-run decoded image {} as {}x{} UI under {}",
                        file.display(),
                        ui_width,
                        ui_height,
                        parent_path
                    ));
                    applied += 1;
                } else {
                    crate::cli::import_image::run(
                        options.port,
                        options.studio.clone(),
                        file.clone(),
                        parent_path.clone(),
                        operation.name.clone(),
                        operation.ui_kind.clone().unwrap_or_else(|| "image".into()),
                        operation.size.clone(),
                        operation.position.clone().unwrap_or_else(|| "0,0".into()),
                    )?;
                    let import_name = operation
                        .name
                        .clone()
                        .unwrap_or_else(|| crate::cli::import_image::file_stem(&file));
                    changed_paths.push(join_studio_path(&parent_path, &import_name));
                    applied += 1;
                }
            }
            "importAsset" => {
                let file = operation.file.clone().ok_or_else(|| {
                    AppError::Other(format!("{} importAsset missing file", operation.id))
                })?;
                if options.dry_run {
                    let metadata = std::fs::metadata(&file)?;
                    warnings.push(format!(
                        "dry-run found mesh asset {} ({} bytes)",
                        file.display(),
                        metadata.len()
                    ));
                    applied += 1;
                } else {
                    let parent_path = operation
                        .parent_path
                        .clone()
                        .unwrap_or_else(|| "Workspace".into());
                    crate::cli::import_asset::run(
                        options.port,
                        options.studio.clone(),
                        file.clone(),
                        parent_path.clone(),
                        operation.name.clone(),
                        operation.scale.unwrap_or(1.0),
                        operation.anchored.unwrap_or(false),
                        operation.weld.unwrap_or(true),
                        None,
                    )?;
                    changed_paths.push(join_studio_path(
                        &parent_path,
                        operation.name.as_deref().unwrap_or("ImportedAsset"),
                    ));
                    applied += 1;
                }
            }
            "importUploaded" => {
                let asset_id = operation.asset_id.as_ref().ok_or_else(|| {
                    AppError::Other(format!("{} importUploaded missing assetId", operation.id))
                })?;
                let kind = operation
                    .asset_kind
                    .clone()
                    .unwrap_or_else(|| "image".into());
                let normalized_asset_id =
                    crate::cli::import_uploaded::normalize_asset_id(asset_id)?;
                let parent_path = operation.parent_path.clone().unwrap_or_else(|| {
                    if kind == "audio" {
                        "SoundService".into()
                    } else {
                        "StarterGui".into()
                    }
                });
                let name = operation
                    .name
                    .clone()
                    .unwrap_or_else(|| format!("AutopilotAsset_{}", operation.id));
                if options.dry_run {
                    warnings.push(format!(
                        "dry-run validated uploaded {} asset {} for {}",
                        kind, normalized_asset_id, parent_path
                    ));
                    changed_paths.push(join_studio_path(&parent_path, &name));
                    applied += 1;
                } else {
                    let (ui_width, ui_height) = match &operation.size {
                        Some(size) if kind == "image" => {
                            let (w, h) = crate::cli::import_image::parse_size(size)?;
                            (Some(w), Some(h))
                        }
                        None if kind == "image" => (Some(128), Some(128)),
                        _ => (None, None),
                    };
                    let (position_x, position_y) = match &operation.position {
                        Some(position) if kind == "image" => {
                            let (x, y) = crate::cli::import_image::parse_position(position)?;
                            (Some(x), Some(y))
                        }
                        None if kind == "image" => (Some(0), Some(0)),
                        _ => (None, None),
                    };
                    let response: ImportUploadedResponse = crate::cli::request::post(
                        options.port,
                        "autopilot import-uploaded",
                        "/import-uploaded",
                        &ImportUploadedRequest {
                            studio: options.studio.clone(),
                            parent_path,
                            kind,
                            name,
                            asset_id: normalized_asset_id,
                            ui_kind: operation.ui_kind.clone(),
                            ui_width,
                            ui_height,
                            position_x,
                            position_y,
                            volume: None,
                            playback_speed: None,
                            looped: false,
                            source_id: Some(format!("autopilot:{}", plan.id)),
                        },
                        75,
                    )?;
                    changed_paths.push(response.instance_path);
                    warnings.extend(response.warnings);
                    applied += 1;
                }
            }
            "packageImport" => {
                let file = operation.file.clone().ok_or_else(|| {
                    AppError::Other(format!("{} packageImport missing file", operation.id))
                })?;
                let parent_path = operation
                    .parent_path
                    .clone()
                    .unwrap_or_else(|| "Workspace".into());
                let manifest = read_package_manifest(&file).ok();
                let blob: Value = serde_json::from_str(&std::fs::read_to_string(
                    file.join("transfer_blob.json"),
                )?)?;
                let response: Value = crate::cli::request::post(
                    options.port,
                    "autopilot package-import",
                    "/deserialize",
                    &DeserializeRequest {
                        studio: options.studio.clone(),
                        parent_path,
                        blob,
                        conflict_mode: Some(
                            operation
                                .conflict_mode
                                .clone()
                                .unwrap_or_else(|| "fail".into()),
                        ),
                        dry_run: options.dry_run,
                        rollback_on_error: operation.rollback_on_error.unwrap_or(!options.dry_run),
                        package_id: manifest
                            .as_ref()
                            .and_then(|value| value.get("packageId"))
                            .and_then(Value::as_str)
                            .map(str::to_string),
                        validate_rules: Vec::new(),
                        fail_on_validation_failure: false,
                        fail_on_external_refs: false,
                    },
                    210,
                )?;
                write_json(
                    options
                        .artifact_dir
                        .join(format!("package-import-{}.json", operation.id)),
                    &response,
                )?;
                if let Some(root_path) = response.get("rootPath").and_then(Value::as_str) {
                    changed_paths.push(root_path.to_string());
                }
                applied += 1;
            }
            "uploadAsset" => {
                let file = operation.file.clone().ok_or_else(|| {
                    AppError::Other(format!("{} uploadAsset missing file", operation.id))
                })?;
                let kind = upload_kind(operation)?;
                if options.dry_run {
                    let metadata = std::fs::metadata(&file)?;
                    warnings.push(format!(
                        "dry-run validated Open Cloud {:?} upload candidate {} ({} bytes)",
                        kind,
                        file.display(),
                        metadata.len()
                    ));
                    if operation.profile.is_none()
                        && operation.creator_id.is_none()
                        && std::env::var("ROBLOX_API_KEY").is_err()
                    {
                        warnings.push(format!(
                            "uploadAsset {} has no profile/creatorId and ROBLOX_API_KEY is not set",
                            operation.id
                        ));
                    }
                    applied += 1;
                } else {
                    crate::cli::upload::run(crate::cli::upload::UploadOptions {
                        port: options.port,
                        studio: options.studio.clone(),
                        kind,
                        file,
                        creator_id: operation.creator_id,
                        creator_type: operation.creator_type.clone(),
                        profile: operation.profile.clone(),
                        name: operation.name.clone(),
                        description: operation.description.clone(),
                        api_key: None,
                        wait: operation.wait.unwrap_or(false) || operation.import_to.is_some(),
                        wait_timeout_secs: operation.wait_timeout_secs.unwrap_or(180),
                        import_to: operation.import_to.clone(),
                        json_output: true,
                    })?;
                    changed_paths.push(format!("uploadAsset:{}", operation.id));
                    applied += 1;
                }
            }
            "smoke" => {
                let suite = operation.suite.as_deref().unwrap_or("all");
                if options.dry_run {
                    warnings.push(format!("dry-run would run smoke suite '{suite}'"));
                    applied += 1;
                } else if suite == "regression" {
                    let out = options
                        .artifact_dir
                        .join(format!("smoke-regression-{}.json", operation.id));
                    crate::cli::smoke::regression(
                        options.port,
                        options.studio.clone(),
                        Some(out.clone()),
                        operation.upload_mock.unwrap_or(false),
                    )?;
                    changed_paths.push(out.to_string_lossy().to_string());
                    applied += 1;
                } else {
                    crate::cli::smoke::run(options.port, options.studio.clone(), suite)?;
                    write_json(
                        options
                            .artifact_dir
                            .join(format!("smoke-{}.json", operation.id)),
                        &json!({"ok": true, "suite": suite}),
                    )?;
                    applied += 1;
                }
            }
            "repairTool" => {
                let path = operation.path.clone().ok_or_else(|| {
                    AppError::Other(format!(
                        "{} repairTool operation missing path",
                        operation.id
                    ))
                })?;
                let response: RepairToolResponse = crate::cli::request::post(
                    options.port,
                    "autopilot repair-tool",
                    "/repair-tool",
                    &RepairToolRequest {
                        studio: options.studio.clone(),
                        path,
                        handle: None,
                        dry_run: options.dry_run,
                        replace_broken: true,
                        physics_fix: true,
                        collision: Some(false),
                        massless: None,
                    },
                    75,
                )?;
                changed_paths.push(response.path.clone());
                applied += 1;
            }
            "createInstance" | "setProperty" | "setAttribute" | "setTags" => {}
            other => {
                return Err(AppError::Other(format!(
                    "operation kind '{other}' is valid but has no apply lowering yet"
                )));
            }
        }
    }
    Ok(OperationRunSummary {
        applied,
        skipped,
        refused,
        changed_paths,
        warnings,
    })
}

fn apply_upsert_script(
    port: u16,
    studio: Option<String>,
    operation: &AutopilotOperation,
    source_dir: &Path,
    plan: &AutopilotPlan,
    dry_run: bool,
) -> AppResult<UpsertFilesResponse> {
    let path = operation.path.as_ref().ok_or_else(|| {
        AppError::Other(format!(
            "{} upsertScript operation missing path",
            operation.id
        ))
    })?;
    let source_path = operation.source_path.as_ref().ok_or_else(|| {
        AppError::Other(format!(
            "{} upsertScript operation missing sourcePath",
            operation.id
        ))
    })?;
    let class_name = operation.class_name.clone().ok_or_else(|| {
        AppError::Other(format!(
            "{} upsertScript operation missing className",
            operation.id
        ))
    })?;
    let (parent_path, name) = split_parent_name(path)?;
    let source_file = safe_join(source_dir, source_path)?;
    let source = std::fs::read_to_string(source_file)?;
    crate::cli::request::post(
        port,
        "autopilot upsert-script",
        "/upsert-files",
        &UpsertFilesRequest {
            studio,
            parent_path,
            dry_run,
            delete: false,
            force: false,
            items: vec![UpsertFileItem {
                path: script_file_name(&name, &class_name),
                class_name,
                name,
                source: Some(source),
                attributes: BTreeMap::from([
                    (
                        "rsAutopilotPlanId".to_string(),
                        Value::String(plan.id.clone()),
                    ),
                    (
                        "rsAutopilotOperationId".to_string(),
                        Value::String(operation.id.clone()),
                    ),
                ]),
            }],
            source_id: Some(format!("autopilot:{}", plan.id)),
        },
        150,
    )
}

fn build_fix_plan_for_apply(
    plan: &AutopilotPlan,
    only: &BTreeSet<String>,
    exclude: &BTreeSet<String>,
    force: bool,
) -> AppResult<FixPlan> {
    let mut changes = Vec::new();
    let mut operations = Vec::new();
    let mut conflicts = Vec::new();
    for operation in &plan.operations {
        if !operation_allowed(operation, only, exclude) {
            continue;
        }
        match operation.kind.as_str() {
            "createInstance" => {
                let parent = operation.parent_path.as_ref().ok_or_else(|| {
                    AppError::Other(format!(
                        "{} createInstance missing parentPath",
                        operation.id
                    ))
                })?;
                let name = operation.name.as_ref().ok_or_else(|| {
                    AppError::Other(format!("{} createInstance missing name", operation.id))
                })?;
                let class_name = operation.class_name.as_ref().ok_or_else(|| {
                    AppError::Other(format!("{} createInstance missing className", operation.id))
                })?;
                let full_path = join_studio_path(parent, name);
                let relative = relative_to_scope(&plan.request.scope, &full_path);
                changes.push(json!({
                    "kind": "added",
                    "path": relative,
                    "after": class_name
                }));
                operations.push(json!({
                    "action": "create",
                    "path": full_path,
                    "reason": "autopilot createInstance operation"
                }));
                for (key, value) in &operation.properties {
                    changes.push(json!({
                        "kind": "modified",
                        "path": relative,
                        "property": format!("properties.{key}"),
                        "after": value
                    }));
                }
                for (key, value) in &operation.attributes {
                    changes.push(json!({
                        "kind": "modified",
                        "path": relative,
                        "property": format!("attributes.{key}"),
                        "after": value
                    }));
                }
                if !operation.tags.is_empty() {
                    changes.push(json!({
                        "kind": "modified",
                        "path": relative,
                        "property": "tags",
                        "after": operation.tags
                    }));
                }
            }
            "setProperty" => {
                let path = operation.path.as_ref().ok_or_else(|| {
                    AppError::Other(format!("{} setProperty missing path", operation.id))
                })?;
                for (key, value) in &operation.properties {
                    changes.push(json!({
                        "kind": "modified",
                        "path": relative_to_scope(&plan.request.scope, path),
                        "property": format!("properties.{key}"),
                        "after": value
                    }));
                    operations.push(json!({
                        "action": "set-property",
                        "path": path,
                        "property": key,
                        "reason": "autopilot setProperty operation"
                    }));
                }
            }
            "setAttribute" => {
                let path = operation.path.as_ref().ok_or_else(|| {
                    AppError::Other(format!("{} setAttribute missing path", operation.id))
                })?;
                for (key, value) in &operation.attributes {
                    changes.push(json!({
                        "kind": "modified",
                        "path": relative_to_scope(&plan.request.scope, path),
                        "property": format!("attributes.{key}"),
                        "after": value
                    }));
                }
            }
            "setTags" => {
                let path = operation.path.as_ref().ok_or_else(|| {
                    AppError::Other(format!("{} setTags missing path", operation.id))
                })?;
                changes.push(json!({
                    "kind": "modified",
                    "path": relative_to_scope(&plan.request.scope, path),
                    "property": "tags",
                    "after": operation.tags
                }));
            }
            "deleteInstance" if !force => {
                conflicts.push(format!(
                    "{} deleteInstance requires --force and rollback evidence",
                    operation.id
                ));
            }
            "deleteInstance" => {
                let path = operation.path.as_ref().ok_or_else(|| {
                    AppError::Other(format!("{} deleteInstance missing path", operation.id))
                })?;
                changes.push(json!({
                    "kind": "deleted",
                    "path": relative_to_scope(&plan.request.scope, path),
                    "before": "Instance"
                }));
                operations.push(json!({
                    "action": "delete",
                    "path": path,
                    "reason": "autopilot deleteInstance operation"
                }));
            }
            _ => {}
        }
    }
    if !conflicts.is_empty() {
        return Err(AppError::Other(format!(
            "autopilot plan has unsafe conflicts: {}",
            conflicts.join("; ")
        )));
    }
    Ok(FixPlan {
        safe_to_apply: true,
        operations,
        conflicts,
        changes,
    })
}

fn create_rollback_artifact(
    port: u16,
    studio: Option<String>,
    scope: &str,
    run_dir: &Path,
) -> AppResult<PathBuf> {
    let rollback_dir = run_dir.join("rollback.rspkg");
    std::fs::create_dir_all(&rollback_dir)?;
    let blob: Value = crate::cli::request::post(
        port,
        "autopilot rollback snapshot",
        "/serialize",
        &SerializeRequest {
            studio,
            path: scope.to_string(),
        },
        180,
    )?;
    write_json(rollback_dir.join("transfer_blob.json"), &blob)?;
    write_json(
        rollback_dir.join("manifest.json"),
        &json!({
            "packageVersion": 1,
            "packageId": format!("autopilot-rollback-{}", now_unix_seconds()),
            "sourcePath": scope,
            "generatedUnixSeconds": now_unix_seconds(),
            "commandVersion": crate::protocol::messages::CLI_VERSION
        }),
    )?;
    Ok(rollback_dir)
}

fn restore_rollback_artifact(
    port: u16,
    studio: Option<String>,
    rollback_dir: &Path,
    scope: &str,
) -> RollbackRestoreReport {
    let artifact = rollback_dir.to_string_lossy().to_string();
    let parent_path = rollback_restore_parent_path(scope);
    let Some(parent_path) = parent_path else {
        return RollbackRestoreReport {
            attempted: false,
            status: "skipped".into(),
            artifact,
            parent_path: None,
            root_path: None,
            warnings: Vec::new(),
            error: Some(format!(
                "automatic rollback restore is only enabled for child scopes, got '{scope}'"
            )),
        };
    };

    match restore_rollback_artifact_inner(port, studio, rollback_dir, parent_path.clone()) {
        Ok((root_path, warnings)) => RollbackRestoreReport {
            attempted: true,
            status: "restored".into(),
            artifact,
            parent_path: Some(parent_path),
            root_path,
            warnings,
            error: None,
        },
        Err(err) => RollbackRestoreReport {
            attempted: true,
            status: "failed".into(),
            artifact,
            parent_path: Some(parent_path),
            root_path: None,
            warnings: Vec::new(),
            error: Some(err.to_string()),
        },
    }
}

fn restore_rollback_artifact_inner(
    port: u16,
    studio: Option<String>,
    rollback_dir: &Path,
    parent_path: String,
) -> AppResult<(Option<String>, Vec<String>)> {
    let manifest = read_package_manifest(rollback_dir).ok();
    let blob: Value = serde_json::from_str(&std::fs::read_to_string(
        rollback_dir.join("transfer_blob.json"),
    )?)?;
    let response: Value = crate::cli::request::post(
        port,
        "autopilot rollback restore",
        "/deserialize",
        &DeserializeRequest {
            studio,
            parent_path,
            blob,
            conflict_mode: Some("replace".into()),
            dry_run: false,
            rollback_on_error: false,
            package_id: manifest
                .as_ref()
                .and_then(|value| value.get("packageId"))
                .and_then(Value::as_str)
                .map(str::to_string),
            validate_rules: Vec::new(),
            fail_on_validation_failure: false,
            fail_on_external_refs: false,
        },
        210,
    )?;
    let root_path = response
        .get("rootPath")
        .and_then(Value::as_str)
        .map(str::to_string);
    let warnings = response
        .get("warnings")
        .and_then(Value::as_array)
        .map(|warnings| {
            warnings
                .iter()
                .filter_map(Value::as_str)
                .map(str::to_string)
                .collect()
        })
        .unwrap_or_default();
    Ok((root_path, warnings))
}

fn rollback_restore_parent_path(scope: &str) -> Option<String> {
    let trimmed = scope.trim();
    if trimmed.eq_ignore_ascii_case("game") || trimmed.eq_ignore_ascii_case("DataModel") {
        return None;
    }
    let normalized = trimmed.strip_prefix("game.").unwrap_or(trimmed);
    let (parent, child) = normalized.rsplit_once('.')?;
    if parent.trim().is_empty() || child.trim().is_empty() {
        return None;
    }
    Some(parent.to_string())
}

fn validate_after(
    port: u16,
    studio: Option<String>,
    plan: &AutopilotPlan,
) -> AppResult<ValidateResponse> {
    crate::cli::request::post(
        port,
        "autopilot validate after",
        "/validate",
        &ValidateRequest {
            studio,
            path: plan.request.scope.clone(),
            rules: Vec::new(),
        },
        75,
    )
}

fn run_smoke_after_apply(
    port: u16,
    studio: Option<String>,
    run_dir: &Path,
    suite: &str,
) -> SmokeRunReport {
    let normalized = suite.trim();
    if normalized.eq_ignore_ascii_case("regression") {
        let artifact = run_dir.join("smoke-regression.json");
        return match crate::cli::smoke::regression(port, studio, Some(artifact.clone()), false) {
            Ok(()) => SmokeRunReport {
                suite: "regression".into(),
                ok: true,
                artifact: Some(artifact.to_string_lossy().to_string()),
                error: None,
            },
            Err(err) => SmokeRunReport {
                suite: "regression".into(),
                ok: false,
                artifact: Some(artifact.to_string_lossy().to_string()),
                error: Some(err.to_string()),
            },
        };
    }

    match crate::cli::smoke::run(port, studio, normalized) {
        Ok(()) => SmokeRunReport {
            suite: normalized.to_string(),
            ok: true,
            artifact: None,
            error: None,
        },
        Err(err) => SmokeRunReport {
            suite: normalized.to_string(),
            ok: false,
            artifact: None,
            error: Some(err.to_string()),
        },
    }
}

fn publish_autopilot_review(
    port: u16,
    studio: Option<String>,
    run_dir: &Path,
    plan: &AutopilotPlan,
    preview: Option<&PreviewReport>,
    apply: Option<&ApplyReport>,
) -> AppResult<Value> {
    let run = autopilot_review_payload(run_dir, plan, preview, apply);
    crate::cli::request::post(
        port,
        "autopilot review panel",
        "/autopilot-review",
        &AutopilotReviewRequest {
            studio,
            action: "set".into(),
            run: Some(run),
        },
        30,
    )
}

fn build_explain_report(plan_path: &Path, plan: &AutopilotPlan) -> ExplainReport {
    let plan_dir = plan_path.parent().unwrap_or_else(|| Path::new("."));
    let mut operation_counts = BTreeMap::new();
    let mut operation_groups = BTreeMap::new();
    let mut generated_files = Vec::new();
    let mut referenced_files = Vec::new();
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let mut validation_errors = Vec::new();

    if let Err(err) = validate_plan(plan) {
        validation_errors.push(err.to_string());
        blockers.push(format!("plan validation failed: {err}"));
    }

    for operation in &plan.operations {
        *operation_counts.entry(operation.kind.clone()).or_insert(0) += 1;
        *operation_groups
            .entry(operation_group(&operation.kind.to_ascii_lowercase()).to_string())
            .or_insert(0) += 1;

        if let Some(source_path) = &operation.source_path {
            generated_files.push(source_path.clone());
            let source_file = safe_join(plan_dir, source_path);
            match source_file {
                Ok(path) if path.exists() => {
                    referenced_files.push(path.to_string_lossy().to_string())
                }
                Ok(path) => blockers.push(format!(
                    "{} references missing generated source {}",
                    operation.id,
                    path.display()
                )),
                Err(err) => blockers.push(format!("{} has unsafe sourcePath: {err}", operation.id)),
            }
        }
        if let Some(file) = &operation.file {
            referenced_files.push(file.to_string_lossy().to_string());
            if !file.exists() {
                warnings.push(format!(
                    "{} references file {} that was not found from current working directory",
                    operation.id,
                    file.display()
                ));
            }
        }
    }

    match plan.risk.level.as_str() {
        "refused" => blockers.push("plan risk is refused and cannot be applied".into()),
        "danger" => {
            warnings.push("plan risk is danger; apply requires --force and manual review".into())
        }
        "review" => {
            warnings.push("plan risk is review; inspect generated files before apply".into())
        }
        "safe" => {}
        other => blockers.push(format!("unknown risk level {other}")),
    }
    if plan.risk.touches_cloud_assets {
        warnings.push("plan touches cloud assets; verify Open Cloud profile, creator, moderation, and permissions".into());
    }
    if plan.risk.touches_scripts {
        warnings.push("plan writes scripts; review generated Luau source before approval".into());
    }
    if plan.risk.destructive {
        blockers.push("plan is destructive; require explicit force and rollback evidence".into());
    }

    generated_files.sort();
    generated_files.dedup();
    referenced_files.sort();
    referenced_files.dedup();
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let plan_display = plan_path.to_string_lossy().to_string();
    let mut recommended_next_commands = vec![format!("rs autopilot preview --plan {plan_display}")];
    if blockers.is_empty() && plan.risk.level != "refused" {
        let mut apply = format!(
            "rs autopilot apply --plan {plan_display} --yes --rollback-on-error --validate"
        );
        if plan.risk.level == "danger" {
            apply.push_str(" --force");
        }
        recommended_next_commands.push(apply);
    }
    recommended_next_commands.push(format!(
        "rs autopilot report {}",
        plan_dir.to_string_lossy()
    ));

    ExplainReport {
        schema_version: "rs.autopilot.explain.v1".into(),
        plan_id: plan.id.clone(),
        plan_path: plan_display,
        studio: plan.request.studio.clone(),
        scope: plan.request.scope.clone(),
        prompt: plan.request.prompt.clone(),
        valid: validation_errors.is_empty(),
        validation_errors,
        risk: plan.risk.clone(),
        requires_approval: plan.risk.requires_approval,
        operation_count: plan.operations.len(),
        operation_counts,
        operation_groups,
        preconditions: plan.preconditions.clone(),
        generated_files,
        referenced_files,
        blockers,
        warnings,
        recommended_next_commands,
    }
}

fn resolve_coach_paths(options: &CoachOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot coach requires --run-dir or --plan".into(),
        )),
    }
}

fn build_coach_report(run_dir: &Path, plan_path: &Path, plan: &AutopilotPlan) -> CoachReport {
    let explain = build_explain_report(plan_path, plan);
    let preview_path = run_dir.join("preview.json");
    let apply_path = run_dir.join("apply.json");
    let report_path = run_dir.join("report.md");
    let context_path = run_dir.join("context.json");
    let preflight_path = run_dir.join("preflight.json");
    let preview = read_json_file(&preview_path).ok();
    let apply = read_json_file(&apply_path).ok();

    let mut blockers = explain.blockers.clone();
    let mut warnings = explain.warnings.clone();
    let mut missing_artifacts = Vec::new();
    for (name, path) in [
        ("context", &context_path),
        ("preflight", &preflight_path),
        ("preview", &preview_path),
        ("report", &report_path),
    ] {
        if !path.exists() {
            missing_artifacts.push(format!("{name}: {}", path.display()));
        }
    }
    for generated_file in &explain.generated_files {
        match safe_join(run_dir, generated_file) {
            Ok(path) if path.exists() => {}
            Ok(path) => missing_artifacts.push(format!("generated: {}", path.display())),
            Err(err) => blockers.push(format!("generated artifact path is unsafe: {err}")),
        }
    }

    if preview.is_none() {
        warnings.push("preview.json is missing; run a preview before applying".into());
    } else if let Some(preview) = &preview {
        if preview
            .get("safeToPreview")
            .and_then(Value::as_bool)
            .is_some_and(|value| !value)
        {
            blockers.push("last preview was not safe to apply".into());
        }
        if let Some(preconditions) = preview.get("preconditions").and_then(Value::as_array) {
            for precondition in preconditions {
                if precondition
                    .get("status")
                    .and_then(Value::as_str)
                    .is_some_and(|status| status == "fail")
                {
                    let path = precondition
                        .get("path")
                        .and_then(Value::as_str)
                        .unwrap_or("<unknown>");
                    let message = precondition
                        .get("message")
                        .and_then(Value::as_str)
                        .unwrap_or("precondition failed");
                    blockers.push(format!("preview precondition failed for {path}: {message}"));
                }
            }
        }
    }
    if let Some(apply) = &apply {
        if let Some(error) = apply.get("error").and_then(Value::as_str) {
            blockers.push(format!("last apply failed: {error}"));
        }
        if apply
            .get("refused")
            .and_then(Value::as_u64)
            .is_some_and(|value| value > 0)
        {
            warnings.push("last apply reported refused operations".into());
        }
    }
    warnings.sort();
    warnings.dedup();
    blockers.sort();
    blockers.dedup();
    missing_artifacts.sort();
    missing_artifacts.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else if apply.is_some() {
        "applied"
    } else if preview.is_some() {
        "readyToApply"
    } else {
        "readyToPreview"
    }
    .to_string();

    let plan_display = plan_path.to_string_lossy().to_string();
    let mut next_actions = Vec::new();
    next_actions.push(CoachAction {
        priority: 1,
        title: "Check live readiness".into(),
        command: Some("rs doctor --format json".into()),
        reason: "Confirm the bridge, plugin protocol, and connected Studio before live preview or apply."
            .into(),
        requires_live_studio: false,
        mutates_studio: false,
    });
    if preview.is_none() {
        next_actions.push(CoachAction {
            priority: 2,
            title: "Preview the plan".into(),
            command: Some(format!("rs autopilot preview --plan {plan_display} --live")),
            reason: "Live preview rechecks preconditions and dry-runs supported operations without mutation."
                .into(),
            requires_live_studio: true,
            mutates_studio: false,
        });
    }
    if plan.risk.touches_scripts {
        next_actions.push(CoachAction {
            priority: 3,
            title: "Review generated Luau".into(),
            command: None,
            reason: "This plan writes scripts; inspect generated files before approval.".into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
    }
    if blockers.is_empty() && apply.is_none() {
        next_actions.push(CoachAction {
            priority: 4,
            title: "Apply with rollback and validation".into(),
            command: Some(format!(
                "rs autopilot apply --plan {plan_display} --yes --rollback-on-error --validate"
            )),
            reason: "Approval is explicit, rollback evidence is captured, and validation runs after mutation."
                .into(),
            requires_live_studio: true,
            mutates_studio: true,
        });
    }
    if has_operation(plan, "smoke") && apply.is_none() {
        next_actions.push(CoachAction {
            priority: 5,
            title: "Keep smoke verification attached".into(),
            command: None,
            reason:
                "The plan already includes a smoke operation; do not drop it from the apply path."
                    .into(),
            requires_live_studio: true,
            mutates_studio: false,
        });
    }
    next_actions.push(CoachAction {
        priority: 6,
        title: "Read the run report".into(),
        command: Some(format!(
            "rs autopilot report {}",
            run_dir.to_string_lossy()
        )),
        reason: "The report is the durable handoff for changed paths, warnings, rollback, and verification."
            .into(),
        requires_live_studio: false,
        mutates_studio: false,
    });

    let mut artifacts = BTreeMap::new();
    artifacts.insert("runDir".into(), run_dir.to_string_lossy().to_string());
    artifacts.insert("plan".into(), plan_path.to_string_lossy().to_string());
    artifacts.insert("context".into(), context_path.to_string_lossy().to_string());
    artifacts.insert(
        "preflight".into(),
        preflight_path.to_string_lossy().to_string(),
    );
    artifacts.insert("preview".into(), preview_path.to_string_lossy().to_string());
    artifacts.insert("apply".into(), apply_path.to_string_lossy().to_string());
    artifacts.insert("report".into(), report_path.to_string_lossy().to_string());

    CoachReport {
        schema_version: "rs.autopilot.coach.v1".into(),
        status,
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        risk: plan.risk.clone(),
        blockers,
        warnings,
        missing_artifacts,
        next_actions,
        artifacts,
    }
}

fn build_handoff_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    handoff_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<HandoffReport> {
    let explain = build_explain_report(plan_path, plan);
    let coach = build_coach_report(run_dir, plan_path, plan);
    let bundle_path = run_dir.join("bundle.json");
    let bundle_created = if bundle_path.exists() {
        false
    } else {
        let bundle = build_bundle_report(run_dir, &bundle_path, plan_path, plan)?;
        write_json(bundle_path.clone(), &bundle)?;
        true
    };
    let bundle_verification = verify_bundle_report(&bundle_path, Some(run_dir))?;
    let bundle_status = HandoffBundleStatus {
        path: bundle_path.to_string_lossy().to_string(),
        created: bundle_created,
        ok: bundle_verification.ok,
        verified: bundle_verification.verified,
        artifact_count: bundle_verification.artifact_count,
        missing: bundle_verification.missing.clone(),
        mismatched: bundle_verification.mismatched.clone(),
        extra: bundle_verification.extra.clone(),
        blockers: bundle_verification.blockers.clone(),
    };

    let mut blockers = coach.blockers.clone();
    if !bundle_status.ok {
        blockers.extend(
            bundle_status
                .blockers
                .iter()
                .map(|blocker| format!("bundle verification: {blocker}")),
        );
    }
    let mut warnings = coach.warnings.clone();
    if !bundle_status.extra.is_empty() {
        warnings.push(format!(
            "bundle verification found {} extra local artifact(s) not recorded in bundle.json",
            bundle_status.extra.len()
        ));
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else {
        coach.status.as_str()
    }
    .to_string();

    let mut artifacts = coach.artifacts.clone();
    artifacts.insert("bundle".into(), bundle_path.to_string_lossy().to_string());
    artifacts.insert(
        "handoffJson".into(),
        handoff_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "handoffMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    let mut next_actions = coach.next_actions.clone();
    next_actions.push(CoachAction {
        priority: 2,
        title: "Verify the handoff bundle".into(),
        command: Some(format!(
            "rs autopilot verify-bundle --run-dir {} --format json",
            run_dir.to_string_lossy()
        )),
        reason:
            "Proves the reviewed artifacts still match bundle.json before another agent resumes."
                .into(),
        requires_live_studio: false,
        mutates_studio: false,
    });
    next_actions.push(CoachAction {
        priority: 7,
        title: "Share the handoff packet".into(),
        command: Some(format!(
            "rs autopilot handoff {} --format json",
            run_dir.to_string_lossy()
        )),
        reason: "Refreshes handoff.json and handoff.md with the latest blockers, artifacts, and next commands."
            .into(),
        requires_live_studio: false,
        mutates_studio: false,
    });
    if !blockers.is_empty() {
        next_actions.retain(|action| !action.mutates_studio);
        next_actions.push(CoachAction {
            priority: 1,
            title: "Resolve handoff blockers".into(),
            command: None,
            reason: "The handoff is blocked; do not run mutating Studio commands until blockers are cleared."
                .into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
    }
    next_actions.sort_by(|left, right| {
        left.priority
            .cmp(&right.priority)
            .then_with(|| left.title.cmp(&right.title))
    });

    let agent_brief = build_handoff_agent_brief(&status, &coach, &bundle_status, &blockers);

    Ok(HandoffReport {
        schema_version: "rs.autopilot.handoff.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        handoff_path: handoff_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        risk: plan.risk.clone(),
        operation_count: explain.operation_count,
        operation_groups: explain.operation_groups,
        bundle: bundle_status,
        blockers,
        warnings,
        missing_artifacts: coach.missing_artifacts,
        artifacts,
        next_actions,
        agent_brief,
    })
}

fn build_handoff_agent_brief(
    status: &str,
    coach: &CoachReport,
    bundle: &HandoffBundleStatus,
    blockers: &[String],
) -> String {
    if blockers.is_empty() {
        format!(
            "Autopilot run '{}' is {}. The bundle verified {}/{} artifact(s). Use the next actions in priority order and require explicit user approval before any mutating apply.",
            coach.plan_id, status, bundle.verified, bundle.artifact_count
        )
    } else {
        format!(
            "Autopilot run '{}' is blocked. Do not mutate Studio yet. Resolve the listed blockers, then rerun `rs autopilot handoff {}`.",
            coach.plan_id, coach.run_dir
        )
    }
}

fn build_runs_report(root: &Path, limit: usize) -> AppResult<RunsReport> {
    let mut blockers = Vec::new();
    if !root.exists() {
        return Ok(RunsReport {
            schema_version: "rs.autopilot.runs.v1".into(),
            root: root.to_string_lossy().to_string(),
            run_count: 0,
            returned: 0,
            runs: Vec::new(),
            blockers: vec![format!("run root does not exist: {}", root.display())],
        });
    }
    if !root.is_dir() {
        return Ok(RunsReport {
            schema_version: "rs.autopilot.runs.v1".into(),
            root: root.to_string_lossy().to_string(),
            run_count: 0,
            returned: 0,
            runs: Vec::new(),
            blockers: vec![format!("run root is not a directory: {}", root.display())],
        });
    }

    let mut candidates = Vec::new();
    for entry in std::fs::read_dir(root)? {
        let entry = entry?;
        let path = entry.path();
        if path.is_dir() && path.join("plan.json").exists() {
            candidates.push((latest_run_modified_secs(&path).unwrap_or(0), path));
        }
    }
    candidates.sort_by(|left, right| right.0.cmp(&left.0).then_with(|| left.1.cmp(&right.1)));

    let run_count = candidates.len();
    let mut runs = Vec::new();
    for (_, run_dir) in candidates.into_iter().take(limit) {
        match build_run_index_entry(&run_dir) {
            Ok(entry) => runs.push(entry),
            Err(err) => blockers.push(format!("{}: {err}", run_dir.display())),
        }
    }

    Ok(RunsReport {
        schema_version: "rs.autopilot.runs.v1".into(),
        root: root.to_string_lossy().to_string(),
        run_count,
        returned: runs.len(),
        runs,
        blockers,
    })
}

fn build_run_index_entry(run_dir: &Path) -> AppResult<RunIndexEntry> {
    let plan_path = run_dir.join("plan.json");
    let plan = read_plan(&plan_path)?;
    let coach = build_coach_report(run_dir, &plan_path, &plan);
    let mut blockers = coach.blockers.clone();
    let mut warnings = coach.warnings.clone();
    let bundle_path = run_dir.join("bundle.json");
    let mut bundle_ok = None;
    let mut bundle_verified = None;
    let mut bundle_artifact_count = None;
    if bundle_path.exists() {
        let verification = verify_bundle_report(&bundle_path, Some(run_dir))?;
        bundle_ok = Some(verification.ok);
        bundle_verified = Some(verification.verified);
        bundle_artifact_count = Some(verification.artifact_count);
        if !verification.ok {
            blockers.extend(
                verification
                    .blockers
                    .iter()
                    .map(|blocker| format!("bundle verification: {blocker}")),
            );
        }
        if !verification.extra.is_empty() {
            warnings.push(format!(
                "bundle verification found {} extra local artifact(s)",
                verification.extra.len()
            ));
        }
    } else {
        warnings.push("bundle.json is missing; run `rs autopilot handoff` before resuming".into());
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() {
        "blocked".to_string()
    } else {
        coach.status.clone()
    };
    let next_command = if !blockers.is_empty() || bundle_ok.is_none() {
        Some(format!(
            "rs autopilot handoff {} --format json",
            run_dir.to_string_lossy()
        ))
    } else {
        coach
            .next_actions
            .iter()
            .find_map(|action| action.command.clone())
    };

    Ok(RunIndexEntry {
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_id: plan.id,
        prompt: plan.request.prompt,
        status,
        risk: plan.risk,
        operation_count: plan.operations.len(),
        bundle_ok,
        bundle_verified,
        bundle_artifact_count,
        blockers,
        warnings,
        next_command,
        updated_at: latest_run_modified_secs(run_dir).map(|secs| format!("unix:{secs}")),
    })
}

fn build_mission_report(
    prompt: Option<&str>,
    root: &Path,
    limit: usize,
    mission_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<MissionReport> {
    let runs_report = build_runs_report(root, limit)?;
    let active_run = select_active_run(&runs_report.runs).cloned();
    let mut blockers = runs_report.blockers.clone();
    let mut warnings = Vec::new();
    let mut next_actions = Vec::new();

    if let Some(active_run) = &active_run {
        if !active_run.blockers.is_empty() {
            blockers.extend(active_run.blockers.clone());
        }
        warnings.extend(active_run.warnings.clone());
        if let Some(command) = &active_run.next_command {
            next_actions.push(CoachAction {
                priority: 1,
                title: if active_run.status == "blocked" {
                    "Resolve active run"
                } else {
                    "Continue active run"
                }
                .into(),
                command: Some(command.clone()),
                reason: format!(
                    "Selected active run '{}' with status '{}'.",
                    active_run.plan_id, active_run.status
                ),
                requires_live_studio: command.contains(" preview")
                    || command.contains(" apply")
                    || command.contains("doctor"),
                mutates_studio: command.contains(" apply") || command.contains(" run "),
            });
        }
    } else {
        warnings.push("no prior Autopilot runs were found under the selected root".into());
    }

    let recommendations = build_mission_recommendations(prompt);
    if let Some(prompt) = prompt {
        if recommendations.is_empty() {
            blockers.push("prompt did not resolve to any Autopilot recipe recommendation".into());
        } else {
            let recipes = recommendations
                .iter()
                .map(|recommendation| recommendation.recipe.as_str())
                .collect::<Vec<_>>()
                .join(",");
            next_actions.push(CoachAction {
                priority: 2,
                title: "Plan the requested feature stack".into(),
                command: Some(format!(
                    "rs autopilot compose \"{}\" --recipe {} --out .rs\\autopilot\\runs\\{} --format json",
                    shell_display_arg(prompt),
                    recipes,
                    slug(prompt)
                )),
                reason: "Creates a reviewable plan from the mission prompt without mutating Studio."
                    .into(),
                requires_live_studio: false,
                mutates_studio: false,
            });
        }
    } else {
        next_actions.push(CoachAction {
            priority: 2,
            title: "Create a full starter-game mission".into(),
            command: Some(
                "rs autopilot compose --preset fullStarterGame --smoke regression --out .rs\\autopilot\\runs\\starter-game --format json"
                    .into(),
            ),
            reason: "No prompt was provided, so the safest ambitious default is a complete reviewable starter-game slice."
                .into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
    }

    next_actions.push(CoachAction {
        priority: 3,
        title: "Check live readiness before mutation".into(),
        command: Some("rs autopilot ready --timeout 90 --format json".into()),
        reason: "Confirms bridge, Studio selector, plugin protocol, and required capabilities before live preview or apply."
            .into(),
        requires_live_studio: true,
        mutates_studio: false,
    });
    next_actions.push(CoachAction {
        priority: 4,
        title: "Refresh mission packet".into(),
        command: Some(format!(
            "rs autopilot mission{} --root {} --format json",
            prompt
                .map(|text| format!(" \"{}\"", shell_display_arg(text)))
                .unwrap_or_default(),
            root.to_string_lossy()
        )),
        reason: "Regenerates mission.json and mission.md after planning, handoff, or live readiness changes."
            .into(),
        requires_live_studio: false,
        mutates_studio: false,
    });

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    next_actions.sort_by(|left, right| {
        left.priority
            .cmp(&right.priority)
            .then_with(|| left.title.cmp(&right.title))
    });

    let status = if !blockers.is_empty() {
        "blocked"
    } else if active_run.is_some() {
        "ready"
    } else {
        "needsPlan"
    }
    .to_string();
    let agent_brief = build_mission_agent_brief(&status, prompt, active_run.as_ref(), &blockers);

    Ok(MissionReport {
        schema_version: "rs.autopilot.mission.v1".into(),
        generated_at: now_stamp(),
        mission_path: mission_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: root.to_string_lossy().to_string(),
        prompt: prompt.map(str::to_string),
        status,
        agent_brief,
        active_run,
        runs: runs_report.runs,
        run_count: runs_report.run_count,
        blockers,
        warnings,
        recommendations,
        next_actions,
    })
}

fn build_memory_report(
    root: &Path,
    limit: usize,
    memory_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<MemoryReport> {
    let runs_report = build_runs_report(root, limit)?;
    let active_run = select_active_run(&runs_report.runs).cloned();
    let mut summaries = Vec::new();
    let mut created_paths = Vec::new();
    let mut generated_files = Vec::new();
    let mut recipes = Vec::new();
    let mut gameplay_verdicts = BTreeMap::new();
    let mut gameplay_gaps = Vec::new();
    let mut blockers = runs_report.blockers.clone();
    let mut warnings = Vec::new();

    for run in &runs_report.runs {
        let run_dir = PathBuf::from(&run.run_dir);
        let plan_path = run_dir.join("plan.json");
        let plan = read_plan(&plan_path)?;
        let operation_counts = operation_counts_for_plan(&plan);
        let run_created_paths = created_paths_for_plan(&plan);
        let run_generated_files = generated_files_for_plan(&plan);
        let run_recipes = recipes_for_run(&run_dir, &plan)?;
        let certification = read_memory_certification(&run_dir)?;
        let gameplay = read_memory_gameplay(&run_dir)?;

        created_paths.extend(run_created_paths.clone());
        generated_files.extend(run_generated_files.clone());
        recipes.extend(run_recipes.clone());
        if let Some(verdict) = &gameplay.verdict {
            *gameplay_verdicts.entry(verdict.clone()).or_insert(0) += 1;
        }
        gameplay_gaps.extend(gameplay.gaps.clone());
        blockers.extend(run.blockers.clone());
        blockers.extend(certification.blockers.clone());
        blockers.extend(
            gameplay
                .blockers
                .iter()
                .map(|blocker| format!("gameplay: {blocker}")),
        );
        warnings.extend(run.warnings.clone());
        warnings.extend(certification.warnings.clone());
        warnings.extend(
            gameplay
                .warnings
                .iter()
                .map(|warning| format!("gameplay: {warning}")),
        );

        summaries.push(MemoryRunSummary {
            run_dir: run.run_dir.clone(),
            plan_id: run.plan_id.clone(),
            prompt: run.prompt.clone(),
            status: run.status.clone(),
            risk: run.risk.clone(),
            operation_count: run.operation_count,
            operation_counts,
            created_paths: run_created_paths,
            generated_files: run_generated_files,
            recipes: run_recipes,
            ready_to_apply: certification.ready_to_apply,
            safe_to_handoff: certification.safe_to_handoff,
            applied: certification.applied,
            gameplay_verdict: gameplay.verdict,
            gameplay_score: gameplay.score,
            gameplay_gaps: gameplay.gaps,
            blockers: merge_many_sorted(vec![
                run.blockers.clone(),
                certification.blockers,
                gameplay
                    .blockers
                    .into_iter()
                    .map(|blocker| format!("gameplay: {blocker}"))
                    .collect(),
            ]),
            warnings: merge_many_sorted(vec![
                run.warnings.clone(),
                certification.warnings,
                gameplay
                    .warnings
                    .into_iter()
                    .map(|warning| format!("gameplay: {warning}"))
                    .collect(),
            ]),
            next_command: run.next_command.clone(),
            updated_at: run.updated_at.clone(),
        });
    }

    created_paths.sort();
    created_paths.dedup();
    generated_files.sort();
    generated_files.dedup();
    recipes.sort();
    recipes.dedup();
    gameplay_gaps.sort_by(|left, right| {
        critique_severity_rank(&left.severity)
            .cmp(&critique_severity_rank(&right.severity))
            .then(left.run_dir.cmp(&right.run_dir))
            .then(left.category.cmp(&right.category))
    });
    gameplay_gaps.dedup_by(|left, right| {
        left.run_dir == right.run_dir
            && left.severity == right.severity
            && left.category == right.category
            && left.message == right.message
    });
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let mut next_actions = Vec::new();
    if let Some(active_run) = &active_run {
        if let Some(command) = &active_run.next_command {
            next_actions.push(CoachAction {
                priority: 1,
                title: if active_run.status == "blocked" {
                    "Resolve active memory run"
                } else {
                    "Continue from project memory"
                }
                .into(),
                command: Some(command.clone()),
                reason: format!(
                    "Project memory selected '{}' with status '{}'.",
                    active_run.plan_id, active_run.status
                ),
                requires_live_studio: command.contains(" ready")
                    || command.contains(" preview")
                    || command.contains(" apply")
                    || command.contains("doctor"),
                mutates_studio: command.contains(" apply") || command.contains(" run "),
            });
        }
    }
    if let Some(active_run) = &active_run {
        if let Some(active_summary) = summaries
            .iter()
            .find(|summary| summary.run_dir == active_run.run_dir)
        {
            if let Some(gap) = active_summary
                .gameplay_gaps
                .iter()
                .find(|gap| gap.severity == "blocker" && gap.command.is_some())
                .or_else(|| {
                    active_summary
                        .gameplay_gaps
                        .iter()
                        .find(|gap| gap.severity == "warning" && gap.command.is_some())
                })
            {
                next_actions.push(CoachAction {
                    priority: 2,
                    title: "Patch active gameplay gap".into(),
                    command: gap.command.clone(),
                    reason: gap.message.clone(),
                    requires_live_studio: false,
                    mutates_studio: false,
                });
            } else if active_summary.gameplay_verdict.is_none() {
                next_actions.push(CoachAction {
                    priority: 2,
                    title: "Critique active gameplay slice".into(),
                    command: Some(format!(
                        "rs autopilot critique --run-dir {} --format json",
                        active_summary.run_dir
                    )),
                    reason: "No gameplay critique artifact exists for the active run.".into(),
                    requires_live_studio: false,
                    mutates_studio: false,
                });
            }
        }
    }
    next_actions.push(CoachAction {
        priority: 8,
        title: "Refresh project memory".into(),
        command: Some(format!(
            "rs autopilot memory --root {} --limit {} --format json",
            root.to_string_lossy(),
            limit
        )),
        reason:
            "Regenerate project-memory.json after any new plan, handoff, apply, or certification."
                .into(),
        requires_live_studio: false,
        mutates_studio: false,
    });

    let agent_brief = build_memory_agent_brief(
        active_run.as_ref(),
        summaries.len(),
        &created_paths,
        &blockers,
        &gameplay_verdicts,
        &gameplay_gaps,
    );

    Ok(MemoryReport {
        schema_version: "rs.autopilot.memory.v1".into(),
        generated_at: now_stamp(),
        memory_path: memory_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: root.to_string_lossy().to_string(),
        run_count: runs_report.run_count,
        returned: summaries.len(),
        active_run,
        run_summaries: summaries,
        created_paths,
        generated_files,
        recipes,
        gameplay_verdicts,
        gameplay_gaps,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn build_preferences_report(
    root: &Path,
    limit: usize,
    preferences_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<PreferencesReport> {
    let runs_report = build_runs_report(root, limit)?;
    let mut signals = Vec::new();
    let mut prompt_theme_counts: BTreeMap<String, (usize, BTreeSet<String>)> = BTreeMap::new();
    let mut recipe_counts: BTreeMap<String, (usize, BTreeSet<String>)> = BTreeMap::new();
    let mut feedback_counts: BTreeMap<String, (usize, BTreeSet<String>)> = BTreeMap::new();
    let mut blockers = runs_report.blockers.clone();
    let mut warnings = Vec::new();
    let mut artifacts = BTreeMap::from([(
        "creatorPreferences".into(),
        preferences_path.to_string_lossy().to_string(),
    )]);
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "creatorPreferencesMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    for run in &runs_report.runs {
        let run_dir = PathBuf::from(&run.run_dir);
        let plan_path = run_dir.join("plan.json");
        let evidence_run = run.run_dir.clone();
        for theme in prompt_themes_for_text(&run.prompt) {
            bump_preference_theme(&mut prompt_theme_counts, &theme, 1, evidence_run.clone());
        }
        match read_plan(&plan_path) {
            Ok(plan) => match recipes_for_run(&run_dir, &plan) {
                Ok(recipes) => {
                    for recipe in recipes {
                        bump_preference_theme(&mut recipe_counts, &recipe, 1, evidence_run.clone());
                    }
                }
                Err(err) => warnings.push(format!(
                    "{}: could not infer recipe affinities: {err}",
                    run.run_dir
                )),
            },
            Err(err) => warnings.push(format!("{}: could not read plan.json: {err}", run.run_dir)),
        }

        let decisions_path = run_dir.join("decisions.json");
        if decisions_path.exists() {
            match read_json_file(&decisions_path) {
                Ok(value) => {
                    artifacts.insert(
                        format!("decisions{}", signals.len() + 1),
                        decisions_path.to_string_lossy().to_string(),
                    );
                    for text in string_array_field(&value, "activeConstraints") {
                        push_preference_signal(
                            &mut signals,
                            "constraint",
                            &text,
                            &run.run_dir,
                            &decisions_path,
                            "high",
                        );
                    }
                    for text in string_array_field(&value, "rejectedDirections") {
                        push_preference_signal(
                            &mut signals,
                            "rejection",
                            &text,
                            &run.run_dir,
                            &decisions_path,
                            "high",
                        );
                    }
                    if let Some(entries) = value.get("entries").and_then(Value::as_array) {
                        for entry in entries {
                            let kind = entry
                                .get("kind")
                                .and_then(Value::as_str)
                                .unwrap_or("decision");
                            if matches!(kind, "constraint" | "rejection") {
                                continue;
                            }
                            if let Some(text) = entry.get("text").and_then(Value::as_str) {
                                push_preference_signal(
                                    &mut signals,
                                    kind,
                                    text,
                                    &run.run_dir,
                                    &decisions_path,
                                    "medium",
                                );
                            }
                        }
                    }
                }
                Err(err) => warnings.push(format!(
                    "{}: decisions.json could not be read: {err}",
                    run.run_dir
                )),
            }
        }

        let feedback_path = run_dir.join("feedback.json");
        if feedback_path.exists() {
            match read_json_file(&feedback_path) {
                Ok(value) => {
                    artifacts.insert(
                        format!("feedback{}", signals.len() + 1),
                        feedback_path.to_string_lossy().to_string(),
                    );
                    if let Some(themes) = value.get("themes").and_then(Value::as_array) {
                        for theme in themes {
                            if let Some(category) = theme.get("category").and_then(Value::as_str) {
                                let count = theme.get("count").and_then(Value::as_u64).unwrap_or(1)
                                    as usize;
                                bump_preference_theme(
                                    &mut feedback_counts,
                                    category,
                                    count.max(1),
                                    run.run_dir.clone(),
                                );
                            }
                        }
                    }
                    if let Some(items) = value.get("items").and_then(Value::as_array) {
                        for item in items {
                            if let Some(note) = item.get("note").and_then(Value::as_str) {
                                let category = item
                                    .get("category")
                                    .and_then(Value::as_str)
                                    .unwrap_or("feedback");
                                push_preference_signal(
                                    &mut signals,
                                    &format!("feedback:{category}"),
                                    note,
                                    &run.run_dir,
                                    &feedback_path,
                                    item.get("confidence")
                                        .and_then(Value::as_str)
                                        .unwrap_or("medium"),
                                );
                            }
                        }
                    }
                }
                Err(err) => warnings.push(format!(
                    "{}: feedback.json could not be read: {err}",
                    run.run_dir
                )),
            }
        }

        let selection_path = run_dir.join("selection.json");
        if selection_path.exists() {
            if let Ok(value) = read_json_file(&selection_path) {
                if let Some(candidate) = string_field(&value, "selectedCandidateId") {
                    push_preference_signal(
                        &mut signals,
                        "selection",
                        &format!("Selected proposal candidate {candidate}"),
                        &run.run_dir,
                        &selection_path,
                        "medium",
                    );
                }
            }
        }

        let demo_learn_path = run_dir.join("demo-learn.json");
        if demo_learn_path.exists() {
            match read_json_file(&demo_learn_path) {
                Ok(value) => {
                    artifacts.insert(
                        format!("demoLearn{}", signals.len() + 1),
                        demo_learn_path.to_string_lossy().to_string(),
                    );
                    for text in string_array_field(&value, "learnedPreferences") {
                        push_preference_signal(
                            &mut signals,
                            "demoPreference",
                            &text,
                            &run.run_dir,
                            &demo_learn_path,
                            "high",
                        );
                    }
                    for text in string_array_field(&value, "constraints") {
                        push_preference_signal(
                            &mut signals,
                            "constraint",
                            &text,
                            &run.run_dir,
                            &demo_learn_path,
                            "high",
                        );
                    }
                    for theme in string_array_field(&value, "followUpThemes") {
                        bump_preference_theme(&mut feedback_counts, &theme, 1, run.run_dir.clone());
                    }
                    if let Some(items) = value.get("creatorSignals").and_then(Value::as_array) {
                        for item in items {
                            let kind = item
                                .get("kind")
                                .and_then(Value::as_str)
                                .unwrap_or("demoSignal");
                            let confidence = item
                                .get("confidence")
                                .and_then(Value::as_f64)
                                .map(|value| {
                                    if value >= 0.8 {
                                        "high"
                                    } else if value >= 0.6 {
                                        "medium"
                                    } else {
                                        "low"
                                    }
                                })
                                .unwrap_or("medium");
                            let text = item
                                .get("summary")
                                .and_then(Value::as_str)
                                .or_else(|| item.get("title").and_then(Value::as_str));
                            if let Some(summary) = text {
                                push_preference_signal(
                                    &mut signals,
                                    kind,
                                    summary,
                                    &run.run_dir,
                                    &demo_learn_path,
                                    confidence,
                                );
                            }
                        }
                    }
                }
                Err(err) => warnings.push(format!(
                    "{}: demo-learn.json could not be read: {err}",
                    run.run_dir
                )),
            }
        }
    }

    dedup_preference_signals(&mut signals);
    let constraints = signals
        .iter()
        .filter(|signal| signal.kind == "constraint")
        .cloned()
        .collect::<Vec<_>>();
    let rejections = signals
        .iter()
        .filter(|signal| signal.kind == "rejection")
        .cloned()
        .collect::<Vec<_>>();
    let feedback_themes = preference_themes_from_counts(feedback_counts);
    let prompt_themes = preference_themes_from_counts(prompt_theme_counts);
    let recipe_affinities = preference_themes_from_counts(recipe_counts);
    let status = if runs_report.run_count == 0 {
        "needsRuns"
    } else if signals.is_empty() && prompt_themes.is_empty() && recipe_affinities.is_empty() {
        "learning"
    } else {
        "ready"
    }
    .to_string();
    if status == "needsRuns" {
        warnings.push("no Autopilot runs were available to learn creator preferences".into());
    }
    warnings.push(
        "creator preferences are planning guidance only; they are not live Studio approval".into(),
    );
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let planning_guidance = build_preferences_planning_guidance(
        &signals,
        &constraints,
        &rejections,
        &feedback_themes,
        &prompt_themes,
        &recipe_affinities,
    );
    let safe_to_say = if status == "ready" {
        vec![format!(
            "Creator preference profile learned {} signal(s) from {} returned run(s).",
            signals.len(),
            runs_report.runs.len()
        )]
    } else {
        vec!["Creator preference profile is still learning from available run artifacts.".into()]
    };
    let do_not_say = vec![
        "Do not treat creator preferences as approval to apply, publish, upload, or mutate Studio.".into(),
        "Do not claim a preference was implemented until plan, apply, and proof artifacts support it.".into(),
        "Do not expose secrets, credentials, or private profile data from source artifacts.".into(),
    ];
    let mut next_actions = Vec::new();
    next_actions.push(coach_action(
        1,
        "Use preferences in orientation",
        Some(format!(
            "rs autopilot orient --root {} --limit {} --format json",
            command_arg(root.to_string_lossy().as_ref()),
            limit
        )),
        "Refresh orientation so the next AI reads the creator profile before planning.",
        false,
        false,
    ));
    next_actions.push(coach_action(
        8,
        "Refresh creator preferences",
        Some(format!(
            "rs autopilot preferences --root {} --limit {} --format json",
            command_arg(root.to_string_lossy().as_ref()),
            limit
        )),
        "Regenerate after new decisions, feedback, proposal selections, or run prompts.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);
    let profile_summary = build_preferences_profile_summary(
        &status,
        runs_report.runs.len(),
        signals.len(),
        &constraints,
        &rejections,
        &recipe_affinities,
        &feedback_themes,
    );
    let agent_brief = format!(
        "Creator preferences are {status}: read planningGuidance before starting a new run, but keep approval/live-gate boundaries separate."
    );

    Ok(PreferencesReport {
        schema_version: "rs.autopilot.creator-preferences.v1".into(),
        generated_at: now_stamp(),
        preferences_path: preferences_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: root.to_string_lossy().to_string(),
        status,
        run_count: runs_report.run_count,
        returned: runs_report.runs.len(),
        profile_summary,
        signals,
        constraints,
        rejections,
        feedback_themes,
        prompt_themes,
        recipe_affinities,
        planning_guidance,
        safe_to_say,
        do_not_say,
        artifacts,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn push_preference_signal(
    signals: &mut Vec<PreferenceSignal>,
    kind: &str,
    text: &str,
    source_run: &str,
    evidence_path: &Path,
    confidence: &str,
) {
    let text = redact_text(text.trim());
    if text.is_empty() {
        return;
    }
    signals.push(PreferenceSignal {
        id: format!("pref-{:03}", signals.len() + 1),
        kind: kind.into(),
        text,
        source_run: source_run.into(),
        evidence_path: evidence_path.to_string_lossy().to_string(),
        confidence: confidence.into(),
    });
}

fn dedup_preference_signals(signals: &mut Vec<PreferenceSignal>) {
    let mut seen = BTreeSet::new();
    signals.retain(|signal| {
        seen.insert(format!(
            "{}\n{}\n{}",
            signal.kind, signal.text, signal.source_run
        ))
    });
    for (index, signal) in signals.iter_mut().enumerate() {
        signal.id = format!("pref-{:03}", index + 1);
    }
}

fn bump_preference_theme(
    themes: &mut BTreeMap<String, (usize, BTreeSet<String>)>,
    name: &str,
    count: usize,
    evidence: String,
) {
    let name = name.trim();
    if name.is_empty() {
        return;
    }
    let entry = themes.entry(name.into()).or_insert((0, BTreeSet::new()));
    entry.0 += count;
    entry.1.insert(evidence);
}

fn preference_themes_from_counts(
    counts: BTreeMap<String, (usize, BTreeSet<String>)>,
) -> Vec<PreferenceTheme> {
    let mut themes = counts
        .into_iter()
        .map(|(name, (count, evidence))| PreferenceTheme {
            name,
            count,
            evidence: evidence.into_iter().collect(),
        })
        .collect::<Vec<_>>();
    themes.sort_by(|left, right| {
        right
            .count
            .cmp(&left.count)
            .then(left.name.cmp(&right.name))
    });
    themes
}

fn prompt_themes_for_text(text: &str) -> Vec<String> {
    let lower = text.to_ascii_lowercase();
    let mut themes = Vec::new();
    for (theme, needles) in [
        ("tycoon", &["tycoon", "dropper", "upgrade"][..]),
        (
            "shop-economy",
            &["shop", "coin", "cash", "currency", "price"],
        ),
        ("quests", &["quest", "objective", "task"]),
        ("obby", &["obby", "checkpoint", "platformer"]),
        ("combat", &["combat", "enemy", "attack", "fighter"]),
        ("inventory", &["inventory", "item", "tool"]),
        ("social", &["lobby", "teleport", "party", "friend"]),
        ("persistence", &["save", "data", "profile", "datastore"]),
    ] {
        if needles.iter().any(|needle| lower.contains(needle)) {
            themes.push(theme.to_string());
        }
    }
    if themes.is_empty() {
        themes.push("custom-gameplay".into());
    }
    themes
}

fn build_preferences_planning_guidance(
    signals: &[PreferenceSignal],
    constraints: &[PreferenceSignal],
    rejections: &[PreferenceSignal],
    feedback_themes: &[PreferenceTheme],
    prompt_themes: &[PreferenceTheme],
    recipe_affinities: &[PreferenceTheme],
) -> Vec<String> {
    let mut guidance = Vec::new();
    for constraint in constraints.iter().take(4) {
        guidance.push(format!("Preserve creator constraint: {}", constraint.text));
    }
    for rejection in rejections.iter().take(4) {
        guidance.push(format!("Avoid rejected direction: {}", rejection.text));
    }
    for preference in signals
        .iter()
        .filter(|signal| signal.kind == "demoPreference")
        .take(3)
    {
        guidance.push(format!("Use learned demo preference: {}", preference.text));
    }
    if let Some(theme) = recipe_affinities.first() {
        guidance.push(format!(
            "Prefer recipe family `{}` when it fits the prompt; it appears in {} prior run(s).",
            theme.name, theme.count
        ));
    }
    if let Some(theme) = prompt_themes.first() {
        guidance.push(format!(
            "Recent creator prompts often lean toward `{}`; propose options that respect that pattern.",
            theme.name
        ));
    }
    if let Some(theme) = feedback_themes.first() {
        guidance.push(format!(
            "Watch `{}` feedback closely; it appears in {} feedback item(s).",
            theme.name, theme.count
        ));
    }
    guidance.push(
        "Use this profile as planning context only; approval, live apply, playtest, rollback, and completion still require their own artifacts.".into(),
    );
    guidance
}

fn build_preferences_profile_summary(
    status: &str,
    returned: usize,
    signal_count: usize,
    constraints: &[PreferenceSignal],
    rejections: &[PreferenceSignal],
    recipe_affinities: &[PreferenceTheme],
    feedback_themes: &[PreferenceTheme],
) -> String {
    let top_recipe = recipe_affinities
        .first()
        .map(|theme| theme.name.as_str())
        .unwrap_or("none yet");
    let top_feedback = feedback_themes
        .first()
        .map(|theme| theme.name.as_str())
        .unwrap_or("none yet");
    format!(
        "Status {status}; learned {signal_count} explicit signal(s) from {returned} run(s), with {} constraint(s), {} rejection(s), top recipe affinity `{top_recipe}`, and top feedback theme `{top_feedback}`.",
        constraints.len(),
        rejections.len()
    )
}

fn build_game_bible_report(
    root: &Path,
    limit: usize,
    game_bible_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<GameBibleReport> {
    let memory_path = game_bible_path.with_file_name("project-memory.json");
    let preferences_path = game_bible_path.with_file_name("creator-preferences.json");
    let memory = build_memory_report(root, limit, &memory_path, None)?;
    let preferences = build_preferences_report(root, limit, &preferences_path, None)?;
    write_json(memory_path.clone(), &memory)?;
    write_json(preferences_path.clone(), &preferences)?;
    let mut artifacts = BTreeMap::from([
        (
            "gameBible".into(),
            game_bible_path.to_string_lossy().to_string(),
        ),
        ("memory".into(), memory.memory_path.clone()),
        (
            "creatorPreferences".into(),
            preferences.preferences_path.clone(),
        ),
    ]);
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "gameBibleMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    let mut player_promise = None;
    let mut core_loop = None;
    let mut genre = None;
    let mut tone = None;
    let mut style_rules = Vec::new();
    let mut world_rules = Vec::new();
    let mut systems: BTreeMap<String, BTreeSet<String>> = BTreeMap::new();
    let mut source_runs = Vec::new();
    let mut warnings =
        merge_many_sorted(vec![memory.warnings.clone(), preferences.warnings.clone()]);
    let source_blockers =
        merge_many_sorted(vec![memory.blockers.clone(), preferences.blockers.clone()]);
    for blocker in source_blockers {
        warnings.push(format!(
            "source run blocker carried for implementation planning: {blocker}"
        ));
    }
    let mut blockers = Vec::new();

    for summary in &memory.run_summaries {
        let run_dir = PathBuf::from(&summary.run_dir);
        let mut run_artifacts = Vec::new();
        if run_dir.join("architect.json").exists() {
            run_artifacts.push("architect.json".into());
            match read_json_file(&run_dir.join("architect.json")) {
                Ok(value) => {
                    if let Some(intent) = value.get("intent") {
                        player_promise = player_promise.or_else(|| {
                            string_field(intent, "playerPromise")
                                .filter(|value| !value.trim().is_empty())
                        });
                        core_loop = core_loop.or_else(|| {
                            string_field(intent, "coreLoop")
                                .filter(|value| !value.trim().is_empty())
                        });
                        genre = genre.or_else(|| {
                            string_field(intent, "genre").filter(|value| !value.trim().is_empty())
                        });
                    }
                }
                Err(err) => warnings.push(format!(
                    "{}: architect.json unreadable: {err}",
                    summary.run_dir
                )),
            }
        }
        if run_dir.join("storyboard.json").exists() {
            run_artifacts.push("storyboard.json".into());
            if let Ok(value) = read_json_file(&run_dir.join("storyboard.json")) {
                player_promise = player_promise.or_else(|| {
                    string_field(&value, "playerPromise").filter(|value| !value.trim().is_empty())
                });
            }
        }
        if run_dir.join("style-guide.json").exists() {
            run_artifacts.push("style-guide.json".into());
            match read_json_file(&run_dir.join("style-guide.json")) {
                Ok(value) => {
                    genre = genre.or_else(|| string_field(&value, "genre"));
                    tone = tone.or_else(|| string_field(&value, "tone"));
                    for field in ["visualRules", "uiRules", "copyRules", "audioRules"] {
                        if let Some(items) = value.get(field).and_then(Value::as_array) {
                            for item in items.iter().take(4) {
                                if let Some(rule) = item.get("rule").and_then(Value::as_str) {
                                    style_rules.push(redact_text(rule));
                                }
                            }
                        }
                    }
                    artifacts.insert(
                        format!("styleGuide{}", source_runs.len() + 1),
                        run_dir
                            .join("style-guide.json")
                            .to_string_lossy()
                            .to_string(),
                    );
                }
                Err(err) => warnings.push(format!(
                    "{}: style-guide.json unreadable: {err}",
                    summary.run_dir
                )),
            }
        }
        if run_dir.join("world-blueprint.json").exists() {
            run_artifacts.push("world-blueprint.json".into());
            match read_json_file(&run_dir.join("world-blueprint.json")) {
                Ok(value) => {
                    world_rules.extend(string_array_field(&value, "buildRules"));
                    if let Some(zones) = value.get("zones").and_then(Value::as_array) {
                        for zone in zones.iter().take(4) {
                            if let Some(name) = zone.get("name").and_then(Value::as_str) {
                                world_rules.push(format!("Preserve zone: {name}"));
                            }
                        }
                    }
                    artifacts.insert(
                        format!("worldBlueprint{}", source_runs.len() + 1),
                        run_dir
                            .join("world-blueprint.json")
                            .to_string_lossy()
                            .to_string(),
                    );
                }
                Err(err) => warnings.push(format!(
                    "{}: world-blueprint.json unreadable: {err}",
                    summary.run_dir
                )),
            }
        }
        for recipe in &summary.recipes {
            systems
                .entry(recipe.clone())
                .or_default()
                .insert(summary.run_dir.clone());
        }
        source_runs.push(GameBibleRun {
            run_dir: summary.run_dir.clone(),
            prompt: summary.prompt.clone(),
            status: summary.status.clone(),
            recipes: summary.recipes.clone(),
            artifacts: run_artifacts,
        });
    }

    let title = game_bible_title(&memory, &preferences);
    let player_promise = player_promise
        .or_else(|| {
            preferences.prompt_themes.first().map(|theme| {
                format!(
                    "Deliver a Roblox gameplay loop centered on {}.",
                    theme.name.replace('-', " ")
                )
            })
        })
        .unwrap_or_else(|| "Deliver a safe, readable Roblox gameplay prototype.".into());
    let core_loop = core_loop.unwrap_or_else(|| {
        memory
            .recipes
            .first()
            .map(|recipe| format!("Spawn, learn the {recipe} loop, earn feedback, and repeat."))
            .unwrap_or_else(|| {
                "Spawn, understand the goal, interact, receive feedback, and improve.".into()
            })
    });
    let genre = genre
        .or_else(|| {
            preferences
                .prompt_themes
                .first()
                .map(|theme| theme.name.clone())
        })
        .unwrap_or_else(|| "starter-game".into());
    let tone = tone.unwrap_or_else(|| {
        preferences
            .planning_guidance
            .first()
            .cloned()
            .unwrap_or_else(|| "friendly, direct, and action-oriented".into())
    });
    style_rules.sort();
    style_rules.dedup();
    world_rules.sort();
    world_rules.dedup();
    let systems = game_bible_systems(systems);
    let canon_rules = build_game_bible_canon_rules(&preferences, &title, &player_promise);
    let continuity_rules = build_game_bible_continuity_rules(&preferences, &memory);
    let proof_contract = vec![
        "Do not claim the canon is implemented until plan, apply, proof, and acceptance artifacts support it.".into(),
        "Do not mutate Studio from the game bible; route live work through approval, live-gate, apply, rollback, and playtest proof.".into(),
        "When adding a feature, update or regenerate style-guide, world-blueprint, creator-preferences, orientation, and game-bible artifacts.".into(),
        "Treat conflicts between this bible and newer creator decisions as decision drift that needs alignment.".into(),
    ];
    warnings.push(
        "game bible is canon guidance only; it is not live apply approval or production proof"
            .into(),
    );
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    let status = if memory.returned == 0 {
        "needsRuns"
    } else if !blockers.is_empty() {
        "blocked"
    } else {
        "ready"
    }
    .to_string();
    let safe_to_say = vec![format!(
        "Game bible '{}' summarizes {} run(s) of project canon guidance.",
        title, memory.returned
    )];
    let do_not_say = vec![
        "Do not claim game-bible.json is live Studio proof.".into(),
        "Do not treat game-bible.json as creator approval to apply, publish, or upload.".into(),
        "Do not override newer creator decisions without recording alignment.".into(),
    ];
    let mut next_actions = vec![
        coach_action(
            1,
            "Refresh orientation with game bible",
            Some(format!(
                "rs autopilot orient --root {} --limit {} --format json",
                command_arg(root.to_string_lossy().as_ref()),
                limit
            )),
            "Put the game bible into the fresh-AI read order before planning continues.",
            false,
            false,
        ),
        coach_action(
            8,
            "Refresh game bible",
            Some(format!(
                "rs autopilot game-bible --root {} --limit {} --format json",
                command_arg(root.to_string_lossy().as_ref()),
                limit
            )),
            "Regenerate after style, world, feedback, preference, or canon changes.",
            false,
            false,
        ),
    ];
    dedup_next_actions(&mut next_actions);
    let agent_brief = format!(
        "Game bible is {status}: preserve '{title}', the player promise, canon rules, creator constraints, and proof contract before proposing new Roblox work."
    );

    Ok(GameBibleReport {
        schema_version: "rs.autopilot.game-bible.v1".into(),
        generated_at: now_stamp(),
        game_bible_path: game_bible_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: root.to_string_lossy().to_string(),
        status,
        run_count: memory.run_count,
        returned: memory.returned,
        title,
        player_promise,
        core_loop,
        genre,
        tone,
        canon_rules,
        style_rules,
        world_rules,
        systems,
        continuity_rules,
        proof_contract,
        source_runs,
        artifacts,
        blockers,
        warnings,
        safe_to_say,
        do_not_say,
        next_actions,
        agent_brief,
    })
}

fn build_playbook_report(
    root: &Path,
    limit: usize,
    playbook_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<PlaybookReport> {
    let base_dir = playbook_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let memory_path = base_dir.join("project-memory.json");
    let preferences_path = base_dir.join("creator-preferences.json");
    let game_bible_path = base_dir.join("game-bible.json");
    let memory = build_memory_report(root, limit, &memory_path, None)?;
    let preferences = build_preferences_report(root, limit, &preferences_path, None)?;
    let game_bible = build_game_bible_report(root, limit, &game_bible_path, None)?;
    write_json(memory_path.clone(), &memory)?;
    write_json(preferences_path.clone(), &preferences)?;
    write_json(game_bible_path.clone(), &game_bible)?;

    let mut artifacts = BTreeMap::from([
        (
            "aiPlaybook".into(),
            playbook_path.to_string_lossy().to_string(),
        ),
        ("memory".into(), memory.memory_path.clone()),
        (
            "creatorPreferences".into(),
            preferences.preferences_path.clone(),
        ),
        ("gameBible".into(), game_bible.game_bible_path.clone()),
    ]);
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "aiPlaybookMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    let mut source_runs = Vec::new();
    let mut learned_lessons = Vec::new();
    let mut retrospective_count = 0usize;
    for summary in &memory.run_summaries {
        let run_dir = PathBuf::from(&summary.run_dir);
        let retrospective_path = run_dir.join("retrospective.json");
        let mut lesson_count = 0usize;
        let mut retrospective_blockers = Vec::new();
        let retrospective_path_string = if retrospective_path.exists() {
            retrospective_count += 1;
            artifacts.insert(
                format!("retrospective{:02}", retrospective_count),
                retrospective_path.to_string_lossy().to_string(),
            );
            let value = read_json_file(&retrospective_path)?;
            retrospective_blockers = string_array_field(&value, "blockers");
            if let Some(lessons) = value.get("lessons").and_then(Value::as_array) {
                lesson_count = lessons.len();
                for lesson in lessons.iter().take(12) {
                    let theme = string_field(lesson, "theme").unwrap_or_else(|| "lesson".into());
                    let finding = string_field(lesson, "finding")
                        .unwrap_or_else(|| "Retrospective recorded a lesson.".into());
                    learned_lessons.push(PlaybookLesson {
                        id: format!("lesson-{:03}", learned_lessons.len() + 1),
                        theme,
                        finding,
                        source_run: summary.run_dir.clone(),
                        evidence: string_array_field(lesson, "evidence"),
                        next_command: string_field(lesson, "nextCommand"),
                    });
                }
            }
            Some(retrospective_path.to_string_lossy().to_string())
        } else {
            None
        };
        source_runs.push(PlaybookRun {
            run_dir: summary.run_dir.clone(),
            status: summary.status.clone(),
            prompt: summary.prompt.clone(),
            retrospective_path: retrospective_path_string,
            lesson_count,
            blockers: merge_many_sorted(vec![summary.blockers.clone(), retrospective_blockers]),
        });
    }
    dedup_playbook_lessons(&mut learned_lessons);

    let mut blockers = Vec::new();
    let mut warnings = merge_many_sorted(vec![
        preferences.warnings.clone(),
        game_bible.warnings.clone(),
    ]);
    if memory.returned == 0 {
        warnings.extend(memory.warnings.clone());
        blockers.extend(memory.blockers.clone());
    } else {
        warnings.extend(
            memory
                .blockers
                .iter()
                .map(|blocker| format!("source run blocker: {blocker}")),
        );
        warnings.extend(memory.warnings.clone());
    }
    if retrospective_count == 0 && memory.returned > 0 {
        warnings.push(
            "no retrospective artifacts found; run `rs autopilot retrospect` for active runs"
                .into(),
        );
    }
    warnings.push(
        "ai-playbook is operating guidance only; it is not live Studio proof or approval".into(),
    );
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let principles = build_playbook_principles(
        &memory,
        &preferences,
        &game_bible,
        retrospective_count,
        &learned_lessons,
    );
    let default_workflow = build_playbook_workflow(root, limit, memory.active_run.as_ref());
    let claim_guardrails = build_playbook_claim_guardrails(&game_bible, &learned_lessons);
    let anti_patterns = build_playbook_anti_patterns(&preferences, retrospective_count);
    let status = if !blockers.is_empty() {
        "blocked"
    } else if memory.returned == 0 {
        "needsRuns"
    } else if retrospective_count == 0 {
        "needsRetrospectives"
    } else {
        "ready"
    }
    .to_string();
    let safe_to_say = vec![format!(
        "AI playbook summarized {} run(s), {} retrospective(s), and {} lesson(s).",
        memory.returned,
        retrospective_count,
        learned_lessons.len()
    )];
    let do_not_say = vec![
        "Do not claim the playbook proves live Studio changes, playtest success, rollback readiness, publish readiness, or production readiness.".into(),
        "Do not treat the playbook as creator approval to apply, upload, publish, or mutate Studio.".into(),
        "Do not override newer creator decisions, preferences, or game-bible canon without recording alignment.".into(),
    ];
    let next_actions =
        build_playbook_next_actions(root, limit, memory.active_run.as_ref(), &status);
    let agent_brief = format!(
        "AI playbook status {status}: preserve '{}', follow {} principle(s), use the default workflow, and keep proof claims behind claim-check/live-gate evidence.",
        game_bible.title,
        principles.len()
    );

    Ok(PlaybookReport {
        schema_version: "rs.autopilot.ai-playbook.v1".into(),
        generated_at: now_stamp(),
        playbook_path: playbook_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: root.to_string_lossy().to_string(),
        status,
        run_count: memory.run_count,
        returned: memory.returned,
        retrospective_count,
        principles,
        default_workflow,
        learned_lessons,
        claim_guardrails,
        anti_patterns,
        source_runs,
        artifacts,
        blockers,
        warnings,
        safe_to_say,
        do_not_say,
        next_actions,
        agent_brief,
    })
}

fn dedup_playbook_lessons(lessons: &mut Vec<PlaybookLesson>) {
    let mut seen = BTreeSet::new();
    lessons.retain(|lesson| seen.insert(format!("{}\n{}", lesson.theme, lesson.finding)));
    for (index, lesson) in lessons.iter_mut().enumerate() {
        lesson.id = format!("lesson-{:03}", index + 1);
    }
}

fn build_playbook_principles(
    memory: &MemoryReport,
    preferences: &PreferencesReport,
    game_bible: &GameBibleReport,
    retrospective_count: usize,
    lessons: &[PlaybookLesson],
) -> Vec<PlaybookPrinciple> {
    let mut principles = vec![
        PlaybookPrinciple {
            id: "principle-001".into(),
            title: "Read canon before creating".into(),
            guidance: format!(
                "Preserve '{}' and its player promise before proposing new Roblox systems.",
                game_bible.title
            ),
            evidence: vec![game_bible.game_bible_path.clone()],
        },
        PlaybookPrinciple {
            id: "principle-002".into(),
            title: "Work through safe offline receipts".into(),
            guidance: "Prefer agenda, sprint, act, and retrospective receipts before asking for live mutation.".into(),
            evidence: lessons
                .iter()
                .flat_map(|lesson| lesson.evidence.iter().cloned())
                .take(6)
                .collect(),
        },
        PlaybookPrinciple {
            id: "principle-003".into(),
            title: "Honor creator taste".into(),
            guidance: preferences
                .planning_guidance
                .first()
                .cloned()
                .unwrap_or_else(|| "Read creator preferences before selecting a direction.".into()),
            evidence: vec![preferences.preferences_path.clone()],
        },
        PlaybookPrinciple {
            id: "principle-004".into(),
            title: "Prove claims before reporting".into(),
            guidance: "Use proof, claim-check, response, live-gate, rollback, health, and playtest evidence for creator-facing claims.".into(),
            evidence: vec![memory.memory_path.clone(), game_bible.game_bible_path.clone()],
        },
    ];
    if retrospective_count > 0 {
        principles.push(PlaybookPrinciple {
            id: "principle-005".into(),
            title: "Learn after each work pass".into(),
            guidance: format!(
                "Refresh retrospective after meaningful work; {} retrospective(s) already inform this playbook.",
                retrospective_count
            ),
            evidence: lessons
                .iter()
                .map(|lesson| lesson.source_run.clone())
                .take(6)
                .collect(),
        });
    }
    principles
}

fn build_playbook_workflow(
    root: &Path,
    limit: usize,
    active_run: Option<&RunIndexEntry>,
) -> Vec<PlaybookStep> {
    let root_arg = command_arg(root.to_string_lossy().as_ref());
    let mut steps = vec![
        PlaybookStep {
            id: "step-001".into(),
            title: "Load orientation".into(),
            command: Some(format!(
                "rs autopilot orient --root {root_arg} --limit {limit} --format json"
            )),
            why: "Start every fresh model with run context, read order, and guardrails.".into(),
            stop_if: vec!["orientation reports privacy, decision, or blocker gates".into()],
        },
        PlaybookStep {
            id: "step-002".into(),
            title: "Refresh agenda".into(),
            command: Some(format!(
                "rs autopilot agenda --root {root_arg} --limit {limit} --format json"
            )),
            why: "Convert cockpit state into a claim-safe work queue.".into(),
            stop_if: vec!["agenda requires live Studio or has no selected run".into()],
        },
    ];
    if let Some(run) = active_run {
        let run_arg = command_arg(&run.run_dir);
        steps.push(PlaybookStep {
            id: "step-003".into(),
            title: "Run bounded sprint".into(),
            command: Some(format!(
                "rs autopilot sprint --run-dir {run_arg} --root {root_arg} --limit {limit} --max-steps 3 --format json"
            )),
            why: "Execute only safe internal agenda actions and record receipts.".into(),
            stop_if: vec![
                "sprint reports blockers".into(),
                "sprint reaches live or mutating boundary".into(),
            ],
        });
        steps.push(PlaybookStep {
            id: "step-004".into(),
            title: "Capture retrospective".into(),
            command: Some(format!(
                "rs autopilot retrospect {run_arg} --root {root_arg} --limit {limit} --format json"
            )),
            why: "Turn the work pass into durable lessons for future AI sessions.".into(),
            stop_if: vec!["retrospective reports blockers that need diagnosis".into()],
        });
        steps.push(PlaybookStep {
            id: "step-005".into(),
            title: "Check claims before response".into(),
            command: Some(format!(
                "rs autopilot respond {run_arg} --claim \"Offline Autopilot work has updated evidence\" --format json"
            )),
            why: "Never report progress until claim-check supports the exact wording.".into(),
            stop_if: vec!["response or claim-check is blocked or needs rewrite".into()],
        });
    } else {
        steps.push(PlaybookStep {
            id: "step-003".into(),
            title: "Start a safe run".into(),
            command: Some(format!(
                "rs autopilot start \"describe the Roblox feature\" --root {root_arg} --format json"
            )),
            why: "Create the first offline run packet before any live mutation.".into(),
            stop_if: vec!["intake needs real creator clarification".into()],
        });
    }
    steps
}

fn build_playbook_claim_guardrails(
    game_bible: &GameBibleReport,
    lessons: &[PlaybookLesson],
) -> Vec<String> {
    let mut guardrails = game_bible.proof_contract.clone();
    guardrails.push("Run claim-check or respond before telling the creator work is done.".into());
    guardrails.push(
        "Offline packets can prove planning, review, and receipts; they cannot prove live gameplay."
            .into(),
    );
    if lessons
        .iter()
        .any(|lesson| lesson.theme.to_ascii_lowercase().contains("claim"))
    {
        guardrails.push(
            "Prior retrospectives explicitly recorded claim-boundary lessons; read them before reporting."
                .into(),
        );
    }
    guardrails.sort();
    guardrails.dedup();
    guardrails
}

fn build_playbook_anti_patterns(
    preferences: &PreferencesReport,
    retrospective_count: usize,
) -> Vec<String> {
    let mut anti_patterns = vec![
        "Do not shell arbitrary agenda text; route supported work through internal handlers.".into(),
        "Do not skip retrospective after a multi-step sprint or long session.".into(),
        "Do not cross live apply, upload, publish, smoke, or plugin repair boundaries without the matching gate artifact.".into(),
        "Do not claim rollback, playtest, health, or production readiness from offline artifacts alone.".into(),
    ];
    for rejection in preferences.rejections.iter().take(4) {
        anti_patterns.push(format!(
            "Do not revive rejected direction: {}",
            rejection.text
        ));
    }
    if retrospective_count == 0 {
        anti_patterns.push(
            "Do not assume prior AI lessons exist; create retrospective evidence first.".into(),
        );
    }
    anti_patterns.sort();
    anti_patterns.dedup();
    anti_patterns
}

fn build_playbook_next_actions(
    root: &Path,
    limit: usize,
    active_run: Option<&RunIndexEntry>,
    status: &str,
) -> Vec<CoachAction> {
    let root_arg = command_arg(root.to_string_lossy().as_ref());
    let mut actions = Vec::new();
    if status == "needsRetrospectives" {
        if let Some(run) = active_run {
            actions.push(coach_action(
                1,
                "Capture active run retrospective",
                Some(format!(
                    "rs autopilot retrospect {} --root {root_arg} --limit {limit} --format json",
                    command_arg(&run.run_dir)
                )),
                "Teach the playbook from the latest run evidence before continuing.",
                false,
                false,
            ));
        }
    }
    actions.push(coach_action(
        2,
        "Refresh orientation with playbook context",
        Some(format!(
            "rs autopilot orient --root {root_arg} --limit {limit} --format json"
        )),
        "Use the playbook alongside canon, memory, preferences, and guardrails.",
        false,
        false,
    ));
    actions.push(coach_action(
        8,
        "Refresh AI playbook",
        Some(format!(
            "rs autopilot playbook --root {root_arg} --limit {limit} --format json"
        )),
        "Regenerate after new retrospectives, preferences, decisions, or canon updates.",
        false,
        false,
    ));
    dedup_next_actions(&mut actions);
    actions
}

fn game_bible_title(memory: &MemoryReport, preferences: &PreferencesReport) -> String {
    if let Some(theme) = preferences.prompt_themes.first() {
        format!(
            "{} Roblox Project",
            title_case_words(&theme.name.replace('-', " "))
        )
    } else if let Some(recipe) = memory.recipes.first() {
        format!("{} Roblox Project", title_case_words(recipe))
    } else {
        "Roblox Game Project".into()
    }
}

fn game_bible_systems(systems: BTreeMap<String, BTreeSet<String>>) -> Vec<GameBibleSystem> {
    let mut systems = systems
        .into_iter()
        .map(|(name, evidence)| GameBibleSystem {
            role: recipe_role_for_bible(&name).into(),
            name,
            evidence: evidence.into_iter().collect(),
        })
        .collect::<Vec<_>>();
    systems.sort_by(|left, right| left.name.cmp(&right.name));
    systems
}

fn recipe_role_for_bible(recipe: &str) -> &'static str {
    match recipe {
        "starterShop" => "economy and purchase loop",
        "collectibleCoin" => "reward pickup loop",
        "questSystem" => "objective structure",
        "roundManager" => "session pacing",
        "inventorySystem" => "player item continuity",
        "adminPanel" => "creator operations",
        "lobbyTeleport" => "navigation and hub movement",
        "obbyCheckpoint" => "progression and respawn loop",
        "tycoonCore" => "earning and upgrade loop",
        "toolSystem" => "player ability surface",
        "enemyEncounter" => "challenge and reward loop",
        "npcInteraction" => "guidance and dialogue",
        "saveDataScaffold" => "player progress persistence",
        _ => "supporting gameplay system",
    }
}

fn build_game_bible_canon_rules(
    preferences: &PreferencesReport,
    title: &str,
    player_promise: &str,
) -> Vec<String> {
    let mut rules = vec![
        format!("Preserve project identity: {title}."),
        format!("Preserve player promise: {player_promise}"),
    ];
    for constraint in preferences.constraints.iter().take(4) {
        rules.push(format!("Respect creator constraint: {}", constraint.text));
    }
    for rejection in preferences.rejections.iter().take(4) {
        rules.push(format!("Avoid rejected direction: {}", rejection.text));
    }
    rules.sort();
    rules.dedup();
    rules
}

fn build_game_bible_continuity_rules(
    preferences: &PreferencesReport,
    memory: &MemoryReport,
) -> Vec<String> {
    let mut rules = Vec::new();
    if !memory.created_paths.is_empty() {
        rules.push(
            "Reuse known created Studio paths instead of duplicating systems with new names."
                .into(),
        );
    }
    if !memory.generated_files.is_empty() {
        rules.push("Patch existing generated files when extending a system; preserve source-audit and preview integrity.".into());
    }
    for guidance in preferences.planning_guidance.iter().take(4) {
        rules.push(guidance.clone());
    }
    rules.push(
        "Record new creator preferences in decisions or feedback before changing canon.".into(),
    );
    rules.sort();
    rules.dedup();
    rules
}

fn build_director_report(
    prompt: Option<&str>,
    root: &Path,
    limit: usize,
    director_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<DirectorReport> {
    let base_dir = director_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let write_markdown = markdown_path.is_some();

    let context_dir = base_dir.join("director-context");
    let game_bible_path = context_dir.join("game-bible.json");
    let game_bible_markdown_path = context_dir.join("game-bible.md");
    let game_bible_markdown = write_markdown.then_some(game_bible_markdown_path.as_path());
    let game_bible = build_game_bible_report(root, limit, &game_bible_path, game_bible_markdown)?;
    write_json(game_bible_path.clone(), &game_bible)?;
    if write_markdown {
        write_game_bible_markdown(game_bible_markdown_path.clone(), &game_bible)?;
    }

    let opportunities_path = context_dir.join("opportunities.json");
    let opportunities_markdown_path = context_dir.join("opportunities.md");
    let opportunities_markdown = write_markdown.then_some(opportunities_markdown_path.as_path());
    let opportunities_options = OpportunitiesOptions {
        prompt: prompt.map(str::to_string),
        run_dir: None,
        root: root.to_path_buf(),
        limit,
        out: Some(opportunities_path.clone()),
        markdown: write_markdown.then_some(opportunities_markdown_path.clone()),
        no_markdown: !write_markdown,
        json: false,
    };
    let opportunities = build_opportunities_report(
        &opportunities_options,
        &opportunities_path,
        opportunities_markdown,
    )?;
    write_json(opportunities_path.clone(), &opportunities)?;
    if write_markdown {
        write_opportunities_markdown(opportunities_markdown_path.clone(), &opportunities)?;
    }

    let strategic_themes = build_director_themes(&game_bible, &opportunities);
    let recommended_bets = build_director_bets(prompt, root, &game_bible, &opportunities);
    let constraints = game_bible.canon_rules.clone();
    let anti_goals = build_director_anti_goals(&game_bible);
    let proof_contract = build_director_proof_contract(&game_bible);
    let mut blockers = game_bible.blockers.clone();
    let mut warnings = merge_many_sorted(vec![
        game_bible.warnings.clone(),
        opportunities.warnings.clone(),
    ]);
    if opportunities.status == "blocked" {
        blockers.extend(opportunities.blockers.clone());
    } else {
        warnings.extend(opportunities.blockers.clone());
    }
    if game_bible.returned == 0 && prompt.is_none() {
        warnings.push(
            "director has no prior runs or prompt; bets are limited to safe starter-game direction"
                .into(),
        );
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    let status = if !blockers.is_empty() {
        "blocked"
    } else if game_bible.returned == 0 && prompt.is_none() {
        "needsPromptOrRuns"
    } else {
        "ready"
    }
    .to_string();
    let thesis = build_director_thesis(prompt, &game_bible, &recommended_bets);
    let mut artifacts = BTreeMap::from([
        (
            "director".into(),
            director_path.to_string_lossy().to_string(),
        ),
        ("gameBible".into(), game_bible.game_bible_path.clone()),
        (
            "opportunities".into(),
            opportunities.opportunities_path.clone(),
        ),
    ]);
    artifacts.extend(game_bible.artifacts.clone());
    artifacts.extend(opportunities.artifacts.clone());
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "directorMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
        artifacts.insert(
            "gameBibleMarkdown".into(),
            game_bible_markdown_path.to_string_lossy().to_string(),
        );
        artifacts.insert(
            "opportunitiesMarkdown".into(),
            opportunities_markdown_path.to_string_lossy().to_string(),
        );
    }

    let mut next_actions = recommended_bets
        .iter()
        .take(5)
        .enumerate()
        .map(|(index, bet)| {
            let command = if status == "ready" && root.is_dir() {
                director_next_action_command(bet, prompt, root, limit)
            } else {
                bet.command.clone()
            };
            coach_action(
                (index + 1) as u8,
                &bet.title,
                command,
                &bet.why,
                bet.requires_live_studio,
                bet.mutates_studio,
            )
        })
        .collect::<Vec<_>>();
    next_actions.push(coach_action(
        98,
        "Refresh creative director",
        Some(build_director_refresh_command(prompt, root, limit)),
        "Regenerate after new runs, creator decisions, feedback, canon changes, or proof artifacts.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);
    let safe_to_say = if status == "ready" {
        vec![format!(
            "Creative director ranked {} canon-aware build bet(s) for '{}'.",
            recommended_bets.len(),
            game_bible.title
        )]
    } else {
        vec![
            "Creative director needs more prompt or run evidence before the build slate is trustworthy."
                .into(),
        ]
    };
    let do_not_say = vec![
        "Do not claim a director bet has been implemented until its command runs and proof artifacts support it.".into(),
        "Do not treat director ranking as creator approval, live Studio readiness, or production proof.".into(),
        "Do not override game-bible canon, creator preferences, or recorded decisions without alignment evidence.".into(),
    ];
    let agent_brief = format!(
        "Creative director is {status}: use the first non-blocked bet as the strategic build lane, preserve canon, and keep live mutation behind approval and proof."
    );

    Ok(DirectorReport {
        schema_version: "rs.autopilot.director.v1".into(),
        generated_at: now_stamp(),
        director_path: director_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: root.to_string_lossy().to_string(),
        prompt: prompt.map(str::to_string),
        status,
        title: game_bible.title.clone(),
        thesis,
        strategic_themes,
        recommended_bets,
        constraints,
        anti_goals,
        proof_contract,
        artifacts,
        blockers,
        warnings,
        safe_to_say,
        do_not_say,
        next_actions,
        agent_brief,
    })
}

fn director_next_action_command(
    bet: &DirectorBet,
    prompt: Option<&str>,
    root: &Path,
    limit: usize,
) -> Option<String> {
    let command = bet.command.as_deref()?;
    if bet.requires_live_studio || bet.mutates_studio || pursuit_command_kind(command).is_none() {
        return bet.command.clone();
    }
    Some(build_pursue_bet_command(
        prompt, root, limit, &bet.id, false,
    ))
}

fn build_director_themes(
    game_bible: &GameBibleReport,
    opportunities: &OpportunitiesReport,
) -> Vec<DirectorTheme> {
    let mut themes = Vec::new();
    themes.push(DirectorTheme {
        id: "DT-001".into(),
        title: "Preserve the playable promise".into(),
        why: format!(
            "Every next build should strengthen '{}' rather than starting a new project direction.",
            game_bible.player_promise
        ),
        evidence: vec![game_bible.game_bible_path.clone()],
    });
    if !game_bible.systems.is_empty() {
        themes.push(DirectorTheme {
            id: "DT-002".into(),
            title: "Extend existing systems".into(),
            why: format!(
                "Known systems [{}] give the AI concrete surfaces to deepen before inventing unrelated mechanics.",
                game_bible
                    .systems
                    .iter()
                    .map(|system| system.name.as_str())
                    .collect::<Vec<_>>()
                    .join(", ")
            ),
            evidence: game_bible
                .systems
                .iter()
                .flat_map(|system| system.evidence.clone())
                .take(6)
                .collect(),
        });
    }
    if let Some(opportunity) = &opportunities.recommended_opportunity {
        themes.push(DirectorTheme {
            id: "DT-003".into(),
            title: "Respect the current safest move".into(),
            why: format!(
                "The opportunity map currently recommends '{}' before branching.",
                opportunity.title
            ),
            evidence: vec![opportunities.opportunities_path.clone()],
        });
    }
    themes.push(DirectorTheme {
        id: "DT-004".into(),
        title: "Keep proof ahead of claims".into(),
        why: "The director can propose ambition, but completion still depends on plan, preview, certification, live apply, playtest, rollback, and closeout evidence.".into(),
        evidence: game_bible.proof_contract.iter().take(4).cloned().collect(),
    });
    themes
}

fn build_director_bets(
    prompt: Option<&str>,
    root: &Path,
    game_bible: &GameBibleReport,
    opportunities: &OpportunitiesReport,
) -> Vec<DirectorBet> {
    let mut bets = Vec::new();
    if let Some(opportunity) = &opportunities.recommended_opportunity {
        bets.push(director_bet_from_opportunity(
            "BET-001",
            "Current safest evidence-backed move",
            "foundation",
            game_bible,
            opportunity,
        ));
    }
    let mut next_id = bets.len() + 1;
    for recipe in director_missing_expansion_recipes(prompt, game_bible)
        .into_iter()
        .take(4)
    {
        bets.push(director_recipe_bet(
            next_id, &recipe, root, prompt, game_bible,
        ));
        next_id += 1;
    }
    if bets.is_empty() {
        let prompt_text = prompt
            .map(str::to_string)
            .unwrap_or_else(|| format!("extend {}", game_bible.title));
        let command = format!(
            "rs autopilot proposal {} --format json",
            command_arg(&prompt_text)
        );
        bets.push(DirectorBet {
            id: "BET-001".into(),
            title: "Shape the next creator proposal".into(),
            ambition: "direction".into(),
            phase: "direction".into(),
            why: "No run-specific opportunity is selected yet, so a proposal is the safest first creative move.".into(),
            canon_fit: format!("Keeps the proposal anchored to '{}'.", game_bible.title),
            expected_artifacts: expected_artifacts_for_command(&command),
            command: Some(command),
            proof_needed: director_default_proof_needed(),
            risks: vec!["proposal is direction only; it is not implementation proof".into()],
            requires_live_studio: false,
            mutates_studio: false,
        });
    }
    dedup_director_bets(&mut bets);
    bets
}

fn director_bet_from_opportunity(
    id: &str,
    title: &str,
    ambition: &str,
    game_bible: &GameBibleReport,
    opportunity: &OpportunityItem,
) -> DirectorBet {
    DirectorBet {
        id: id.into(),
        title: title.into(),
        ambition: ambition.into(),
        phase: opportunity.phase.clone(),
        why: opportunity.why.clone(),
        canon_fit: format!(
            "Supports '{}' while preserving the current proof contract.",
            game_bible.player_promise
        ),
        command: opportunity.command.clone(),
        expected_artifacts: opportunity.expected_artifacts.clone(),
        proof_needed: director_default_proof_needed(),
        risks: opportunity.blocked_by.clone(),
        requires_live_studio: opportunity.requires_live_studio,
        mutates_studio: opportunity.mutates_studio,
    }
}

fn director_recipe_bet(
    index: usize,
    recipe: &str,
    root: &Path,
    prompt: Option<&str>,
    game_bible: &GameBibleReport,
) -> DirectorBet {
    let role = recipe_role_for_bible(recipe);
    let prompt_text = prompt.map(str::to_string).unwrap_or_else(|| {
        format!(
            "Extend {} with {} while preserving {}",
            game_bible.title, role, game_bible.core_loop
        )
    });
    let run_dir = root.join(format!(
        "director-{}-{}",
        slug(recipe),
        slug(&game_bible.title)
    ));
    let command = format!(
        "rs autopilot kickoff {} --out {} --format json",
        command_arg(&prompt_text),
        command_arg(run_dir.to_string_lossy().as_ref())
    );
    DirectorBet {
        id: format!("BET-{index:03}"),
        title: format!("Add {}", title_case_words(&recipe.replace('-', " "))),
        ambition: "canonExpansion".into(),
        phase: "build".into(),
        why: format!(
            "{} is a high-leverage next system because it deepens the project without discarding existing canon.",
            title_case_words(role)
        ),
        canon_fit: format!(
            "Extends '{}' with {} while preserving style, world, and continuity rules.",
            game_bible.title, role
        ),
        expected_artifacts: expected_artifacts_for_command(&command),
        command: Some(command),
        proof_needed: director_default_proof_needed(),
        risks: vec![
            "new feature must pass alignment against creator constraints".into(),
            "offline kickoff proof still needs live apply and playtest before completion claims".into(),
        ],
        requires_live_studio: false,
        mutates_studio: false,
    }
}

fn director_missing_expansion_recipes(
    prompt: Option<&str>,
    game_bible: &GameBibleReport,
) -> Vec<String> {
    let existing = game_bible
        .systems
        .iter()
        .map(|system| system.name.as_str())
        .collect::<BTreeSet<_>>();
    let mut candidates = Vec::new();
    if let Some(prompt) = prompt {
        candidates.extend(compose_prompt_recipes(prompt).unwrap_or_default());
    }
    candidates.extend(
        [
            "questSystem",
            "saveDataScaffold",
            "inventorySystem",
            "npcInteraction",
            "obbyCheckpoint",
            "lobbyTeleport",
            "roundManager",
            "tycoonCore",
            "adminPanel",
        ]
        .into_iter()
        .map(str::to_string),
    );
    let mut seen = BTreeSet::new();
    candidates
        .into_iter()
        .filter(|recipe| !existing.contains(recipe.as_str()) && seen.insert(recipe.clone()))
        .collect()
}

fn director_default_proof_needed() -> Vec<String> {
    vec![
        "plan.json and preview.json exist for the selected offline run".into(),
        "source-audit, certification, critique, simulation, feature graph, and bundle artifacts are current".into(),
        "creator decision alignment is refreshed before live apply".into(),
        "live-gate, approved apply, rollback, and accepted playtest proof exist before completion claims".into(),
    ]
}

fn build_director_anti_goals(game_bible: &GameBibleReport) -> Vec<String> {
    let mut anti_goals = game_bible
        .canon_rules
        .iter()
        .filter(|rule| rule.starts_with("Avoid "))
        .cloned()
        .collect::<Vec<_>>();
    anti_goals.extend(game_bible.do_not_say.clone());
    anti_goals.sort();
    anti_goals.dedup();
    anti_goals
}

fn build_director_proof_contract(game_bible: &GameBibleReport) -> Vec<String> {
    let mut proof = game_bible.proof_contract.clone();
    proof.push(
        "Treat each director bet as a hypothesis until its exact command writes artifacts and later proof gates pass."
            .into(),
    );
    proof.sort();
    proof.dedup();
    proof
}

fn build_director_thesis(
    prompt: Option<&str>,
    game_bible: &GameBibleReport,
    bets: &[DirectorBet],
) -> String {
    let focus = prompt
        .map(|value| format!(" with creator focus '{}'", value))
        .unwrap_or_default();
    let first_bet = bets
        .first()
        .map(|bet| bet.title.as_str())
        .unwrap_or("shape the next offline build lane");
    format!(
        "For '{}'{}: preserve the player promise, then pursue '{}'.",
        game_bible.title, focus, first_bet
    )
}

fn build_director_refresh_command(prompt: Option<&str>, root: &Path, limit: usize) -> String {
    if let Some(prompt) = prompt {
        format!(
            "rs autopilot director {} --root {} --limit {} --format json",
            command_arg(prompt),
            command_arg(root.to_string_lossy().as_ref()),
            limit
        )
    } else {
        format!(
            "rs autopilot director --root {} --limit {} --format json",
            command_arg(root.to_string_lossy().as_ref()),
            limit
        )
    }
}

fn dedup_director_bets(bets: &mut Vec<DirectorBet>) {
    let mut seen = BTreeSet::new();
    bets.retain(|bet| {
        seen.insert(format!(
            "{}\n{}",
            bet.title,
            bet.command.as_deref().unwrap_or("")
        ))
    });
    for (index, bet) in bets.iter_mut().enumerate() {
        bet.id = format!("BET-{:03}", index + 1);
    }
}

fn build_pursuit_report(
    options: &PursueOptions,
    pursuit_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<PursuitReport> {
    let base_dir = pursuit_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let director_path = base_dir.join("director.json");
    let director_markdown_path = base_dir.join("director.md");
    let director = build_director_report(
        options.prompt.as_deref(),
        &options.root,
        options.limit,
        &director_path,
        Some(&director_markdown_path),
    )?;
    write_json(director_path.clone(), &director)?;
    write_director_markdown(director_markdown_path.clone(), &director)?;

    let selected_bet = select_pursuit_bet(&director, options.bet.as_deref()).cloned();
    let mut artifacts = BTreeMap::from([
        ("pursuit".into(), pursuit_path.to_string_lossy().to_string()),
        ("director".into(), director.director_path.clone()),
        (
            "directorMarkdown".into(),
            director_markdown_path.to_string_lossy().to_string(),
        ),
    ]);
    artifacts.extend(director.artifacts.clone());
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "pursuitMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    let mut blockers = Vec::new();
    let mut warnings = director.warnings.clone();
    let mut steps = vec![pursuit_step(
        "PUR-010",
        "Refresh creative director",
        &director.status,
        "Refreshed director context before selecting a bet.",
        Some(build_director_refresh_command(
            options.prompt.as_deref(),
            &options.root,
            options.limit,
        )),
        vec![director.director_path.clone()],
        None,
    )];
    let mut executed = false;
    let mut command_kind = None;
    let mut selected_command = None;
    let mut created_run_dir = None;

    if director.status == "blocked" {
        blockers.extend(director.blockers.clone());
    }
    if let Some(requested) = options.bet.as_deref() {
        if selected_bet.is_none() {
            blockers.push(format!("director bet `{requested}` was not found"));
        }
    }

    if let Some(bet) = &selected_bet {
        selected_command = bet.command.clone();
        command_kind = selected_command
            .as_deref()
            .and_then(pursuit_command_kind)
            .map(str::to_string);
        steps.push(pursuit_step(
            "PUR-020",
            "Select director bet",
            "selected",
            format!("Selected {}: {}", bet.id, bet.title),
            selected_command.clone(),
            Vec::new(),
            None,
        ));
        if bet.requires_live_studio || bet.mutates_studio {
            blockers.push(format!(
                "{} requires live Studio or mutation and cannot be pursued offline",
                bet.id
            ));
        } else if command_kind.is_none() {
            blockers.push(format!(
                "{} has no supported safe offline command for pursuit",
                bet.id
            ));
        }
    } else if options.bet.is_none() {
        blockers
            .push("no supported director bet with an executable offline command was found".into());
    }

    if blockers.is_empty() {
        if let Some(bet) = &selected_bet {
            if options.dry_run {
                steps.push(pursuit_step(
                    "PUR-030",
                    "Dry-run selected bet",
                    "dryRun",
                    "Selected bet was not executed because --dry-run was set.",
                    selected_command.clone(),
                    bet.expected_artifacts.clone(),
                    None,
                ));
            } else if let Some(command) = selected_command.as_deref() {
                match execute_pursuit_command(command, &options.root, options.limit) {
                    Ok(execution) => {
                        executed = true;
                        created_run_dir = execution.created_run_dir;
                        artifacts.extend(execution.artifacts.clone());
                        warnings.extend(execution.warnings);
                        steps.extend(execution.steps);
                    }
                    Err(err) => {
                        blockers.push(format!("pursuit execution failed: {err}"));
                        steps.push(pursuit_step(
                            "PUR-030",
                            "Execute selected bet",
                            "failed",
                            "The selected offline command failed.",
                            selected_command.clone(),
                            Vec::new(),
                            Some(err.to_string()),
                        ));
                    }
                }
            }
        }
    }

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    let status = if !blockers.is_empty() {
        "blocked"
    } else if options.dry_run {
        "dryRun"
    } else if executed {
        "executed"
    } else {
        "ready"
    }
    .to_string();
    let safe_to_say = if executed {
        vec!["Director pursuit executed one safe offline bet and wrote evidence artifacts.".into()]
    } else {
        vec![
            "Director pursuit selected a safe offline bet but did not prove live Studio changes."
                .into(),
        ]
    };
    let do_not_say = vec![
        "Do not claim the pursued bet is implemented in Studio until apply and playtest proof exist.".into(),
        "Do not treat pursuit as creator approval, live readiness, publishing, or production proof.".into(),
        "Do not execute unsupported director commands through a shell fallback.".into(),
    ];
    let mut next_actions = Vec::new();
    if let Some(run_dir) = &created_run_dir {
        next_actions.push(coach_action(
            1,
            "Open pursued run cockpit",
            Some(format!(
                "rs autopilot cockpit --run-dir {} --format json",
                command_arg(run_dir)
            )),
            "Inspect the pursued run before reporting progress or asking for live approval.",
            false,
            false,
        ));
    }
    next_actions.push(coach_action(
        98,
        "Refresh pursuit",
        Some(build_pursuit_refresh_command(options)),
        "Regenerate after the director slate, creator focus, or selected bet changes.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);
    let agent_brief = format!(
        "Pursuit status {status}. Only supported offline director bets are executable; live Studio proof remains separate."
    );

    Ok(PursuitReport {
        schema_version: "rs.autopilot.pursuit.v1".into(),
        generated_at: now_stamp(),
        pursuit_path: pursuit_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        prompt: options.prompt.clone(),
        status,
        dry_run: options.dry_run,
        executed,
        selected_bet,
        command_kind,
        selected_command,
        created_run_dir,
        steps,
        artifacts,
        blockers,
        warnings,
        safe_to_say,
        do_not_say,
        next_actions,
        agent_brief,
    })
}

fn select_pursuit_bet<'a>(
    director: &'a DirectorReport,
    bet_id: Option<&str>,
) -> Option<&'a DirectorBet> {
    if let Some(bet_id) = bet_id {
        return director
            .recommended_bets
            .iter()
            .find(|bet| bet.id.eq_ignore_ascii_case(bet_id));
    }
    director.recommended_bets.iter().find(|bet| {
        !bet.requires_live_studio
            && !bet.mutates_studio
            && bet
                .command
                .as_deref()
                .and_then(pursuit_command_kind)
                .is_some()
    })
}

fn pursuit_command_kind(command: &str) -> Option<&'static str> {
    let tokens = split_act_command_words(command);
    tokens
        .windows(2)
        .find(|window| window[0] == "autopilot")
        .and_then(|window| match window[1].as_str() {
            "kickoff" => Some("kickoff"),
            _ => None,
        })
}

fn execute_pursuit_command(
    command: &str,
    root: &Path,
    limit: usize,
) -> AppResult<PursuitExecution> {
    match pursuit_command_kind(command) {
        Some("kickoff") => execute_pursuit_kickoff(command, root, limit),
        _ => Err(AppError::Other(
            "pursuit only supports safe offline kickoff commands".into(),
        )),
    }
}

fn execute_pursuit_kickoff(
    command: &str,
    root: &Path,
    limit: usize,
) -> AppResult<PursuitExecution> {
    let tokens = split_act_command_words(command);
    let kickoff_index = tokens
        .windows(2)
        .position(|window| window[0] == "autopilot" && window[1] == "kickoff")
        .map(|index| index + 2)
        .ok_or_else(|| AppError::Other("pursuit could not parse kickoff command".into()))?;
    let prompt = tokens
        .iter()
        .skip(kickoff_index)
        .take_while(|token| !token.starts_with("--"))
        .cloned()
        .collect::<Vec<_>>()
        .join(" ");
    if prompt.trim().is_empty() {
        return Err(AppError::Other(
            "pursuit kickoff command did not include a prompt".into(),
        ));
    }
    let report = write_kickoff_packet(&KickoffOptions {
        port: 7878,
        prompt: Some(prompt),
        studio: None,
        scope: "game".into(),
        root: root.to_path_buf(),
        limit,
        out: option_path(&tokens, "--out"),
        smoke: option_values(&tokens, "--smoke").into_iter().next(),
        json: false,
    })?;
    let mut artifacts = BTreeMap::new();
    artifacts.insert("pursuedRun".into(), report.run_dir.clone());
    artifacts.insert("pursuedPlan".into(), report.plan_path.clone());
    artifacts.insert("pursuedPreview".into(), report.preview_path.clone());
    artifacts.insert(
        "pursuedCertification".into(),
        report.certification_path.clone(),
    );
    artifacts.insert("pursuedHandoff".into(), report.handoff_path.clone());
    let steps = vec![pursuit_step(
        "PUR-030",
        "Execute kickoff bet",
        &report.status,
        format!(
            "Created offline run {} with {} safe next action(s).",
            report.run_dir,
            report.next_actions.len()
        ),
        Some(redact_text(command)),
        artifacts.values().cloned().collect(),
        None,
    )];
    Ok(PursuitExecution {
        created_run_dir: Some(report.run_dir),
        artifacts,
        steps,
        warnings: report.warnings,
    })
}

fn pursuit_step(
    id: &str,
    title: &str,
    status: &str,
    summary: impl Into<String>,
    command: Option<String>,
    artifacts: Vec<String>,
    error: Option<String>,
) -> PursuitStep {
    PursuitStep {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        summary: summary.into(),
        command,
        artifacts,
        error,
    }
}

fn build_pursue_bet_command(
    prompt: Option<&str>,
    root: &Path,
    limit: usize,
    bet: &str,
    dry_run: bool,
) -> String {
    let mut command = if let Some(prompt) = prompt {
        format!(
            "rs autopilot pursue {} --root {} --limit {}",
            command_arg(prompt),
            command_arg(root.to_string_lossy().as_ref()),
            limit
        )
    } else {
        format!(
            "rs autopilot pursue --root {} --limit {}",
            command_arg(root.to_string_lossy().as_ref()),
            limit
        )
    };
    command.push_str(&format!(" --bet {}", command_arg(bet)));
    if dry_run {
        command.push_str(" --dry-run");
    }
    command.push_str(" --format json");
    command
}

fn build_pursuit_refresh_command(options: &PursueOptions) -> String {
    let mut command = if let Some(prompt) = options.prompt.as_deref() {
        format!(
            "rs autopilot pursue {} --root {} --limit {}",
            command_arg(prompt),
            command_arg(options.root.to_string_lossy().as_ref()),
            options.limit
        )
    } else {
        format!(
            "rs autopilot pursue --root {} --limit {}",
            command_arg(options.root.to_string_lossy().as_ref()),
            options.limit
        )
    };
    if let Some(bet) = options.bet.as_deref() {
        command.push_str(&format!(" --bet {}", command_arg(bet)));
    }
    if options.dry_run {
        command.push_str(" --dry-run");
    }
    command.push_str(" --format json");
    command
}

fn build_agenda_report(
    options: &AgendaOptions,
    agenda_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<AgendaReport> {
    let base_dir = agenda_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let write_markdown = markdown_path.is_some();
    let context_dir = base_dir.join("agenda-context");
    let cockpit_path = context_dir.join("cockpit.json");
    let cockpit_markdown_path = context_dir.join("cockpit.md");
    let cockpit_markdown = write_markdown.then_some(cockpit_markdown_path.as_path());
    let cockpit_options = CockpitOptions {
        prompt: options.prompt.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        out: Some(cockpit_path.clone()),
        markdown: write_markdown.then_some(cockpit_markdown_path.clone()),
        no_markdown: !write_markdown,
        json: false,
    };
    let cockpit = build_cockpit_report(&cockpit_options, &cockpit_path, cockpit_markdown)?;
    write_json(cockpit_path.clone(), &cockpit)?;
    if write_markdown {
        write_cockpit_markdown(cockpit_markdown_path.clone(), &cockpit)?;
    }

    let mut agenda = cockpit
        .command_queue
        .iter()
        .take(10)
        .enumerate()
        .map(|(index, action)| agenda_item_from_action(index + 1, action))
        .collect::<Vec<_>>();
    dedup_agenda_items(&mut agenda);

    let mut artifacts = BTreeMap::from([
        ("agenda".into(), agenda_path.to_string_lossy().to_string()),
        ("cockpit".into(), cockpit.cockpit_path.clone()),
    ]);
    artifacts.extend(cockpit.artifacts.clone());
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "agendaMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
        artifacts.insert(
            "cockpitMarkdown".into(),
            cockpit_markdown_path.to_string_lossy().to_string(),
        );
    }

    let mut blockers = cockpit.blockers.clone();
    let mut warnings = cockpit.warnings.clone();
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let first_action = agenda.first();
    let status = if !blockers.is_empty() {
        "blocked"
    } else if agenda.is_empty() {
        "needsContext"
    } else if first_action.is_some_and(|item| item.mutates_studio || item.requires_live_studio) {
        "needsLiveGate"
    } else {
        "ready"
    }
    .to_string();
    let current_focus = first_action
        .map(|item| item.title.clone())
        .unwrap_or_else(|| "No actionable agenda item is available yet.".into());

    let mut safe_to_say = cockpit.safe_to_say.clone();
    safe_to_say.push(format!(
        "Autopilot agenda distilled {} current AI work item{} from cockpit evidence.",
        agenda.len(),
        if agenda.len() == 1 { "" } else { "s" }
    ));
    safe_to_say.sort();
    safe_to_say.dedup();
    let mut do_not_say = cockpit.do_not_say.clone();
    do_not_say.push(
        "Do not claim an agenda item is complete until its expected artifacts or proof gates exist."
            .into(),
    );
    do_not_say.push(
        "Do not treat the agenda as live Studio approval, publishing approval, or production proof."
            .into(),
    );
    do_not_say.sort();
    do_not_say.dedup();

    let mut next_actions = agenda
        .iter()
        .take(5)
        .map(agenda_item_to_action)
        .collect::<Vec<_>>();
    next_actions.push(coach_action(
        98,
        "Refresh AI agenda",
        Some(build_agenda_refresh_command(options)),
        "Regenerate after new runs, decisions, proof, playtest, pursuit, or live readiness artifacts.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);
    let agent_brief =
        build_agenda_agent_brief(&status, &current_focus, cockpit.selected_run.as_ref());

    Ok(AgendaReport {
        schema_version: "rs.autopilot.agenda.v1".into(),
        generated_at: now_stamp(),
        agenda_path: agenda_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        prompt: options.prompt.clone(),
        status,
        selected_run: cockpit.selected_run.clone(),
        current_focus,
        readiness: cockpit.readiness.clone(),
        primary_command: cockpit.primary_command.clone(),
        agenda,
        artifacts,
        blockers,
        warnings,
        safe_to_say,
        do_not_say,
        next_actions,
        agent_brief,
    })
}

fn agenda_item_from_action(index: usize, action: &CoachAction) -> AgendaItem {
    let expected_artifacts = action
        .command
        .as_deref()
        .map(expected_artifacts_for_command)
        .unwrap_or_default();
    let done_when = if expected_artifacts.is_empty() {
        vec!["The command has been run and its resulting JSON status is reviewed.".into()]
    } else {
        expected_artifacts
            .iter()
            .map(|artifact| {
                format!("Expected artifact exists or is deliberately reported missing: {artifact}")
            })
            .collect()
    };
    let mut stop_conditions = vec![
        "Stop before claiming completion if blockers or missing proof remain.".into(),
        "Stop if the selected command fails; record the failure instead of continuing silently."
            .into(),
    ];
    if action.requires_live_studio {
        stop_conditions.push("Stop until live Studio readiness is verified.".into());
    }
    if action.mutates_studio {
        stop_conditions.push("Stop until creator approval and live-gate evidence exist.".into());
    }
    AgendaItem {
        id: format!("AG-{:03}", index),
        title: action.title.clone(),
        source: agenda_source_for_command(action.command.as_deref()),
        phase: agenda_phase_for_command(action.command.as_deref()),
        priority: action.priority,
        command: action.command.clone(),
        reason: action.reason.clone(),
        expected_artifacts,
        done_when,
        stop_conditions,
        requires_live_studio: action.requires_live_studio,
        mutates_studio: action.mutates_studio,
    }
}

fn agenda_item_to_action(item: &AgendaItem) -> CoachAction {
    coach_action(
        item.priority,
        &item.title,
        item.command.clone(),
        &item.reason,
        item.requires_live_studio,
        item.mutates_studio,
    )
}

fn dedup_agenda_items(items: &mut Vec<AgendaItem>) {
    items.sort_by(|left, right| {
        left.priority
            .cmp(&right.priority)
            .then(left.title.cmp(&right.title))
            .then(left.command.cmp(&right.command))
    });
    let mut seen = BTreeSet::new();
    items.retain(|item| {
        let key = format!("{}\n{}", item.title, item.command.as_deref().unwrap_or(""));
        seen.insert(key)
    });
    for (index, item) in items.iter_mut().enumerate() {
        item.id = format!("AG-{:03}", index + 1);
    }
}

fn agenda_source_for_command(command: Option<&str>) -> String {
    let Some(command) = command else {
        return "manualReview".into();
    };
    if command.contains(" autopilot pursue ") || command.contains(" autopilot director ") {
        "creativeDirector".into()
    } else if command.contains(" autopilot roadmap ") {
        "roadmap".into()
    } else if command.contains(" autopilot control ") || command.contains(" autopilot cockpit ") {
        "missionControl".into()
    } else if command.contains(" autopilot brief ")
        || command.contains(" autopilot respond ")
        || command.contains(" autopilot claim-check ")
    {
        "creatorCommunication".into()
    } else if command.contains(" autopilot ready ")
        || command.contains(" autopilot rehearsal ")
        || command.contains(" autopilot live-gate ")
        || command.contains(" autopilot apply ")
    {
        "liveGate".into()
    } else {
        "cockpitQueue".into()
    }
}

fn agenda_phase_for_command(command: Option<&str>) -> String {
    let Some(command) = command else {
        return "review".into();
    };
    if command.contains(" autopilot kickoff ")
        || command.contains(" autopilot pursue ")
        || command.contains(" autopilot compose ")
        || command.contains(" autopilot satisfy ")
        || command.contains(" autopilot promise-loop ")
    {
        "build".into()
    } else if command.contains(" autopilot align ")
        || command.contains(" autopilot decision ")
        || command.contains(" autopilot journal ")
        || command.contains(" autopilot control ")
        || command.contains(" autopilot cockpit ")
        || command.contains(" autopilot capsule ")
        || command.contains(" autopilot orient ")
    {
        "coordination".into()
    } else if command.contains(" autopilot proof ")
        || command.contains(" autopilot acceptance ")
        || command.contains(" autopilot certify ")
        || command.contains(" autopilot work-check ")
    {
        "proof".into()
    } else if command.contains(" autopilot ready ")
        || command.contains(" autopilot rehearsal ")
        || command.contains(" autopilot live-gate ")
        || command.contains(" autopilot apply ")
    {
        "live".into()
    } else {
        "work".into()
    }
}

fn build_agenda_refresh_command(options: &AgendaOptions) -> String {
    let mut command = if let Some(prompt) = options.prompt.as_deref() {
        format!(
            "rs autopilot agenda {} --root {} --limit {}",
            command_arg(prompt),
            command_arg(options.root.to_string_lossy().as_ref()),
            options.limit
        )
    } else {
        format!(
            "rs autopilot agenda --root {} --limit {}",
            command_arg(options.root.to_string_lossy().as_ref()),
            options.limit
        )
    };
    if let Some(run_dir) = &options.run_dir {
        command.push_str(&format!(
            " --run-dir {}",
            command_arg(run_dir.to_string_lossy().as_ref())
        ));
    }
    command.push_str(" --format json");
    command
}

fn build_agenda_agent_brief(
    status: &str,
    current_focus: &str,
    selected_run: Option<&RunIndexEntry>,
) -> String {
    if let Some(run) = selected_run {
        format!(
            "Agenda status {status}. Continue '{}' from '{}' by doing '{}' first, then verify artifacts before making claims.",
            run.plan_id, run.run_dir, current_focus
        )
    } else {
        format!(
            "Agenda status {status}. No active run is selected; do '{}' first and keep all live mutation behind approval gates.",
            current_focus
        )
    }
}

fn build_sprint_report(
    options: &SprintOptions,
    sprint_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<SprintReport> {
    let base_dir = sprint_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let mut iterations = Vec::new();
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let mut artifacts =
        BTreeMap::from([("sprint".into(), sprint_path.to_string_lossy().to_string())]);
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "sprintMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    let mut seen_commands = BTreeSet::new();
    let max_steps = options.max_steps.max(1);
    let mut selected_run_dir = options.run_dir.clone();
    let mut status = "maxStepsReached".to_string();

    for index in 1..=max_steps {
        let agenda_path = base_dir.join(format!("sprint-agenda-{index:02}.json"));
        let agenda_markdown_path = base_dir.join(format!("sprint-agenda-{index:02}.md"));
        let agenda_options = AgendaOptions {
            prompt: options.prompt.clone(),
            run_dir: selected_run_dir.clone(),
            root: options.root.clone(),
            limit: options.limit,
            out: Some(agenda_path.clone()),
            markdown: Some(agenda_markdown_path.clone()),
            no_markdown: false,
            json: false,
        };
        let agenda =
            build_agenda_report(&agenda_options, &agenda_path, Some(&agenda_markdown_path))?;
        write_json(agenda_path.clone(), &agenda)?;
        write_agenda_markdown(agenda_markdown_path.clone(), &agenda)?;
        artifacts.insert(format!("agenda{index:02}"), agenda.agenda_path.clone());
        if let Some(markdown_path) = &agenda.markdown_path {
            artifacts.insert(format!("agenda{index:02}Markdown"), markdown_path.clone());
        }
        if selected_run_dir.is_none() {
            selected_run_dir = agenda
                .selected_run
                .as_ref()
                .map(|run| PathBuf::from(&run.run_dir));
        }
        warnings.extend(agenda.warnings.clone());
        if !agenda.blockers.is_empty() {
            blockers.extend(agenda.blockers.clone());
            iterations.push(sprint_iteration(
                index,
                &agenda,
                None,
                None,
                "Agenda reported blockers; sprint stopped before execution.",
                vec![agenda.agenda_path.clone()],
            ));
            status = "blocked".into();
            break;
        }
        let Some(run_dir) = selected_run_dir.clone() else {
            blockers.push("agenda sprint needs a selected run directory before it can act".into());
            iterations.push(sprint_iteration(
                index,
                &agenda,
                None,
                None,
                "No selected run was available for act execution.",
                vec![agenda.agenda_path.clone()],
            ));
            status = "blocked".into();
            break;
        };
        let Some(item) = select_sprint_agenda_item(&agenda, &seen_commands) else {
            iterations.push(sprint_iteration(
                index,
                &agenda,
                None,
                None,
                "No new safe agenda command remained for this sprint.",
                vec![agenda.agenda_path.clone()],
            ));
            status = if iterations
                .iter()
                .any(|iteration| iteration.act_status.as_deref() == Some("executed"))
            {
                "complete"
            } else {
                "noSafeAction"
            }
            .into();
            break;
        };
        if item.requires_live_studio || item.mutates_studio {
            blockers.push(format!(
                "{} requires live Studio or mutation and cannot run in an agenda sprint",
                item.id
            ));
            iterations.push(sprint_iteration(
                index,
                &agenda,
                Some(item),
                None,
                "Selected agenda item requires a guarded live boundary.",
                vec![agenda.agenda_path.clone()],
            ));
            status = "needsLiveGate".into();
            break;
        }
        let command = item.command.clone().unwrap_or_default();
        seen_commands.insert(command.clone());
        let act_path = run_dir.join(format!("sprint-act-{index:02}.json"));
        let act_markdown_path = run_dir.join(format!("sprint-act-{index:02}.md"));
        let act_options = ActOptions {
            run_dir: run_dir.clone(),
            command: Some(command),
            source: "agenda-sprint".into(),
            root: options.root.clone(),
            limit: options.limit,
            dry_run: options.dry_run,
            out: Some(act_path.clone()),
            markdown: Some(act_markdown_path.clone()),
            no_markdown: false,
            json: false,
        };
        let act = build_act_report(&act_options, &act_path, Some(&act_markdown_path))?;
        write_json(act_path.clone(), &act)?;
        write_act_markdown(act_markdown_path.clone(), &act)?;
        artifacts.insert(format!("act{index:02}"), act.act_path.clone());
        if let Some(markdown_path) = &act.markdown_path {
            artifacts.insert(format!("act{index:02}Markdown"), markdown_path.clone());
        }
        warnings.extend(act.warnings.clone());
        iterations.push(sprint_iteration(
            index,
            &agenda,
            Some(item),
            Some(&act),
            if options.dry_run {
                "Dry-run selected one safe agenda action and stopped."
            } else {
                "Executed one safe agenda action through act."
            },
            vec![agenda.agenda_path.clone(), act.act_path.clone()],
        ));
        if options.dry_run {
            status = "dryRun".into();
            break;
        }
        if act.status != "executed" {
            blockers.extend(act.blockers.clone());
            status = "blocked".into();
            break;
        }
        if index == max_steps {
            warnings.push(format!(
                "sprint reached max_steps={max_steps} before agenda was exhausted"
            ));
        }
    }

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    if !blockers.is_empty() && status == "maxStepsReached" {
        status = "blocked".into();
    }
    let verdict = match status.as_str() {
        "complete" => "agendaExhausted",
        "dryRun" => "selectedSafeAction",
        "noSafeAction" => "noSafeAgendaAction",
        "blocked" => "sprintBlocked",
        "needsLiveGate" => "liveBoundaryReached",
        _ => "stepLimitReached",
    }
    .to_string();
    let safe_to_say = match status.as_str() {
        "complete" => vec![
            "Autopilot sprint executed all new safe agenda actions available in this bounded pass."
                .into(),
        ],
        "dryRun" => vec![
            "Autopilot sprint selected the next safe agenda action without executing it.".into(),
        ],
        "noSafeAction" => vec![
            "Autopilot sprint found no agenda action with a supported safe internal handler."
                .into(),
        ],
        _ => vec!["Autopilot sprint stopped before exhausting the safe agenda.".into()],
    };
    let do_not_say = vec![
        "Do not claim live Studio mutation, apply success, playtest success, rollback readiness, publish readiness, or production readiness from sprint alone.".into(),
        "Do not claim repeated agenda commands were rerun; sprint skips commands it already executed in the same pass.".into(),
        "Do not report creator-facing completion unless response or claim-check artifacts support exact wording.".into(),
    ];
    let run_dir_string = selected_run_dir
        .as_ref()
        .map(|path| path.to_string_lossy().to_string());
    let next_actions = build_sprint_next_actions(options, selected_run_dir.as_deref(), &status);
    let agent_brief =
        build_sprint_agent_brief(&status, iterations.len(), run_dir_string.as_deref());

    Ok(SprintReport {
        schema_version: "rs.autopilot.sprint.v1".into(),
        generated_at: now_stamp(),
        sprint_path: sprint_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        prompt: options.prompt.clone(),
        run_dir: run_dir_string,
        status,
        verdict,
        max_steps,
        dry_run: options.dry_run,
        iteration_count: iterations.len(),
        iterations,
        artifacts,
        blockers,
        warnings,
        safe_to_say,
        do_not_say,
        next_actions,
        agent_brief,
    })
}

fn select_sprint_agenda_item<'a>(
    agenda: &'a AgendaReport,
    seen_commands: &BTreeSet<String>,
) -> Option<&'a AgendaItem> {
    agenda.agenda.iter().find(|item| {
        let Some(command) = item.command.as_deref() else {
            return false;
        };
        !seen_commands.contains(command) && act_command_kind(command).is_some()
    })
}

fn sprint_iteration(
    index: usize,
    agenda: &AgendaReport,
    item: Option<&AgendaItem>,
    act: Option<&ActReport>,
    summary: &str,
    artifacts: Vec<String>,
) -> SprintIteration {
    SprintIteration {
        id: format!("SPRINT-{index:03}"),
        agenda_status: agenda.status.clone(),
        selected_item_id: item.map(|item| item.id.clone()),
        selected_title: item.map(|item| item.title.clone()),
        selected_command: item.and_then(|item| item.command.clone()),
        command_kind: act.and_then(|act| act.command_kind.clone()).or_else(|| {
            item.and_then(|item| item.command.as_deref())
                .and_then(act_command_kind)
        }),
        act_status: act.map(|act| act.status.clone()),
        summary: summary.into(),
        artifacts,
    }
}

fn build_sprint_next_actions(
    options: &SprintOptions,
    run_dir: Option<&Path>,
    status: &str,
) -> Vec<CoachAction> {
    let mut actions = Vec::new();
    if matches!(status, "blocked" | "needsLiveGate") {
        if let Some(run_dir) = run_dir {
            actions.push(coach_action(
                1,
                "Diagnose sprint stop",
                Some(format!(
                    "rs autopilot diagnose {} --format json",
                    command_arg(run_dir.to_string_lossy().as_ref())
                )),
                "Classify the last blocked sprint action before continuing.",
                false,
                false,
            ));
        }
    }
    actions.push(coach_action(
        98,
        "Refresh agenda sprint",
        Some(build_sprint_refresh_command(options, run_dir)),
        "Run another bounded sprint after reviewing artifacts and blockers.",
        false,
        false,
    ));
    dedup_next_actions(&mut actions);
    actions
}

fn build_sprint_refresh_command(options: &SprintOptions, run_dir: Option<&Path>) -> String {
    let mut command = if let Some(prompt) = options.prompt.as_deref() {
        format!(
            "rs autopilot sprint {} --root {} --limit {} --max-steps {}",
            command_arg(prompt),
            command_arg(options.root.to_string_lossy().as_ref()),
            options.limit,
            options.max_steps
        )
    } else {
        format!(
            "rs autopilot sprint --root {} --limit {} --max-steps {}",
            command_arg(options.root.to_string_lossy().as_ref()),
            options.limit,
            options.max_steps
        )
    };
    if let Some(run_dir) = run_dir.or(options.run_dir.as_deref()) {
        command.push_str(&format!(
            " --run-dir {}",
            command_arg(run_dir.to_string_lossy().as_ref())
        ));
    }
    if options.dry_run {
        command.push_str(" --dry-run");
    }
    command.push_str(" --format json");
    command
}

fn build_sprint_agent_brief(status: &str, iteration_count: usize, run_dir: Option<&str>) -> String {
    let run = run_dir.unwrap_or("no selected run");
    match status {
        "complete" => format!(
            "Sprint completed {iteration_count} safe agenda iteration(s) for {run}. Review artifacts before making creator-facing claims."
        ),
        "dryRun" => format!(
            "Sprint dry-run selected the next safe agenda action for {run} and stopped before execution."
        ),
        "noSafeAction" => format!(
            "Sprint found no agenda action with a supported safe internal handler for {run}."
        ),
        "needsLiveGate" => format!(
            "Sprint reached a live or mutating boundary for {run}; use approval/live-gate proof before continuing."
        ),
        "blocked" => format!(
            "Sprint blocked after {iteration_count} iteration(s) for {run}; diagnose before another action."
        ),
        _ => format!(
            "Sprint reached its step limit after {iteration_count} iteration(s) for {run}."
        ),
    }
}

fn build_retrospect_report(
    options: &RetrospectOptions,
    retrospective_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<RetrospectReport> {
    if !options.run_dir.is_dir() {
        return Err(AppError::Other(format!(
            "autopilot retrospect run directory does not exist: {}",
            options.run_dir.display()
        )));
    }

    let mut artifacts = collect_planner_run_artifacts(Some(&options.run_dir));
    artifacts.insert(
        "retrospective".into(),
        retrospective_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "retrospectiveMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    let mut sources = Vec::new();
    let mut source_values = BTreeMap::new();
    for (kind, relative) in [
        ("sprint", "sprint.json"),
        ("agenda", "agenda.json"),
        ("act", "act.json"),
        ("loop", "loop.json"),
        ("cycle", "cycle.json"),
        ("diagnosis", "diagnosis.json"),
        ("workCheck", "work-check.json"),
        ("proof", "proof.json"),
        ("acceptance", "acceptance.json"),
        ("health", "health.json"),
        ("privacy", "privacy.json"),
        ("journal", "journal.json"),
        ("bundle", "bundle.json"),
    ] {
        let path = options.run_dir.join(relative);
        if path.exists() {
            let value = read_json_file(&path)?;
            sources.push(retrospect_source(kind, &path, &value));
            source_values.insert(kind.to_string(), value);
        }
    }

    let mut blockers = source_values
        .values()
        .flat_map(|value| string_array_field(value, "blockers"))
        .collect::<Vec<_>>();
    let mut warnings = source_values
        .values()
        .flat_map(|value| string_array_field(value, "warnings"))
        .collect::<Vec<_>>();
    if sources.is_empty() {
        warnings.push("Run directory has no recognized Autopilot review artifacts yet.".into());
    }

    let bundle_path = options.run_dir.join("bundle.json");
    let bundle_verified = if bundle_path.exists() {
        match verify_bundle_report(&bundle_path, Some(&options.run_dir)) {
            Ok(report) if report.ok => true,
            Ok(report) => {
                blockers.push(format!(
                    "bundle verification is not clean: {} missing, {} mismatched",
                    report.missing.len(),
                    report.mismatched.len()
                ));
                false
            }
            Err(err) => {
                blockers.push(format!("bundle verification failed: {err}"));
                false
            }
        }
    } else {
        false
    };

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let sprint_executed = source_values
        .get("sprint")
        .map(retrospect_sprint_executed_count)
        .unwrap_or_default();
    let has_sprint = source_values.contains_key("sprint");
    let has_live_gate = source_values.values().any(retrospect_mentions_live_gate);
    let sprint_status = source_values
        .get("sprint")
        .and_then(|value| string_field(value, "status"));
    let act_status = source_values
        .get("act")
        .and_then(|value| string_field(value, "status"));
    let act_kind = source_values
        .get("act")
        .and_then(|value| string_field(value, "commandKind"));

    let mut accomplishments = Vec::new();
    if options.run_dir.join("plan.json").exists() {
        accomplishments.push("Run has a structured plan artifact.".into());
    }
    if sprint_executed > 0 {
        accomplishments.push(format!(
            "Agenda sprint executed {sprint_executed} safe offline action(s)."
        ));
    }
    if act_status.as_deref() == Some("executed") {
        accomplishments.push(format!(
            "Last act receipt executed a `{}` handler.",
            act_kind.as_deref().unwrap_or("supported")
        ));
    }
    if source_values
        .get("loop")
        .and_then(|value| string_field(value, "status"))
        .as_deref()
        == Some("readyToReport")
    {
        accomplishments.push("Guarded offline loop reached ready-to-report state.".into());
    }
    if bundle_verified {
        accomplishments.push("Bundle verification was clean at retrospective time.".into());
    }
    if accomplishments.is_empty() {
        accomplishments.push("Retrospective captured current run evidence for the next AI.".into());
    }

    let mut lessons = Vec::new();
    if sprint_executed > 0 {
        lessons.push(retrospect_lesson(
            "LESSON-001",
            "bounded progress",
            format!(
                "Safe agenda work can advance through sprint; {sprint_executed} action(s) have receipts."
            ),
            vec![options.run_dir.join("sprint.json").to_string_lossy().to_string()],
            Some(format!(
                "rs autopilot sprint --run-dir {} --root {} --limit {} --max-steps 3 --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref()),
                command_arg(options.root.to_string_lossy().as_ref()),
                options.limit
            )),
        ));
    } else if !has_sprint {
        lessons.push(retrospect_lesson(
            "LESSON-001",
            "missing sprint",
            "No agenda sprint receipt exists yet, so the next AI should create a bounded work pass before claiming progress.",
            vec![options.run_dir.to_string_lossy().to_string()],
            Some(format!(
                "rs autopilot sprint --run-dir {} --root {} --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref()),
                command_arg(options.root.to_string_lossy().as_ref())
            )),
        ));
    }
    if !blockers.is_empty() {
        lessons.push(retrospect_lesson(
            "LESSON-002",
            "blocker discipline",
            "The next AI should classify blockers before running another action.",
            blockers.clone(),
            Some(format!(
                "rs autopilot diagnose {} --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref())
            )),
        ));
    }
    lessons.push(retrospect_lesson(
        "LESSON-003",
        "claim boundary",
        "Offline action receipts are not live Studio, playtest, publish, rollback, or production proof.",
        vec![
            options.run_dir.join("sprint.json").to_string_lossy().to_string(),
            options.run_dir.join("act.json").to_string_lossy().to_string(),
        ],
        Some(format!(
            "rs autopilot claim-check {} --claim \"Offline Autopilot work has evidence receipts\" --format json",
            command_arg(options.run_dir.to_string_lossy().as_ref())
        )),
    ));
    if source_values
        .get("privacy")
        .and_then(|value| string_field(value, "status"))
        .as_deref()
        != Some("passed")
    {
        lessons.push(retrospect_lesson(
            "LESSON-004",
            "handoff hygiene",
            "Run privacy before handing artifacts to another AI or claiming they are safe to share.",
            vec![options.run_dir.join("privacy.json").to_string_lossy().to_string()],
            Some(format!(
                "rs autopilot privacy {} --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref())
            )),
        ));
    }

    let status = if !blockers.is_empty() {
        "blocked"
    } else if has_live_gate {
        "needsLiveGate"
    } else if sprint_status.as_deref() == Some("dryRun") {
        "dryRun"
    } else if has_sprint || act_status.as_deref() == Some("executed") {
        "readyToContinue"
    } else {
        "needsSprint"
    }
    .to_string();
    let verdict = match status.as_str() {
        "blocked" => "needsDiagnosis",
        "needsLiveGate" => "liveBoundaryRecorded",
        "dryRun" => "safeActionSelected",
        "readyToContinue" => "lessonsCaptured",
        _ => "needsBoundedAction",
    }
    .to_string();

    let safe_to_say = vec![
        "Autopilot retrospective summarized existing run artifacts without mutating Studio.".into(),
        format!(
            "Retrospective found {} evidence source(s) and {} lesson(s).",
            sources.len(),
            lessons.len()
        ),
    ];
    let do_not_say = vec![
        "Do not claim live Studio mutation, apply success, playtest success, rollback readiness, publish readiness, or production readiness from retrospective alone.".into(),
        "Do not treat journal entries, agenda items, or sprint selection as proof that gameplay works in Studio.".into(),
        "Do not hand artifacts to another AI as privacy-safe unless privacy.json is passing.".into(),
    ];
    let next_actions = build_retrospect_next_actions(options, &status, has_sprint);
    let agent_brief = build_retrospect_agent_brief(
        &status,
        sources.len(),
        lessons.len(),
        sprint_executed,
        &options.run_dir,
    );

    Ok(RetrospectReport {
        schema_version: "rs.autopilot.retrospective.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        retrospective_path: retrospective_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        status,
        verdict,
        evidence_sources: sources,
        accomplishments,
        lessons,
        artifacts,
        blockers,
        warnings,
        safe_to_say,
        do_not_say,
        next_actions,
        agent_brief,
    })
}

fn retrospect_source(kind: &str, path: &Path, value: &Value) -> RetrospectSource {
    let status = string_field(value, "status")
        .or_else(|| string_field(value, "verdict"))
        .unwrap_or_else(|| "present".into());
    let verdict = string_field(value, "verdict")
        .or_else(|| string_field(value, "decision"))
        .or_else(|| string_field(value, "route"));
    let summary = string_field(value, "agentBrief")
        .or_else(|| string_field(value, "currentFocus"))
        .or_else(|| string_field(value, "userUpdate"))
        .or_else(|| string_field(value, "summary"))
        .or_else(|| string_field(value, "resumeCommand"))
        .or_else(|| verdict.clone())
        .unwrap_or_else(|| format!("{kind} artifact is present"));
    RetrospectSource {
        kind: kind.into(),
        path: path.to_string_lossy().to_string(),
        status,
        verdict,
        summary,
    }
}

fn retrospect_sprint_executed_count(value: &Value) -> usize {
    value
        .get("iterations")
        .and_then(Value::as_array)
        .map(|iterations| {
            iterations
                .iter()
                .filter(|iteration| {
                    iteration.get("actStatus").and_then(Value::as_str) == Some("executed")
                })
                .count()
        })
        .unwrap_or_default()
}

fn retrospect_mentions_live_gate(value: &Value) -> bool {
    string_field(value, "status")
        .is_some_and(|status| matches!(status.as_str(), "needsLiveGate" | "readyForLiveGate"))
        || value
            .get("nextActions")
            .and_then(Value::as_array)
            .is_some_and(|actions| {
                actions.iter().any(|action| {
                    action
                        .get("requiresLiveStudio")
                        .and_then(Value::as_bool)
                        .unwrap_or(false)
                        || action
                            .get("mutatesStudio")
                            .and_then(Value::as_bool)
                            .unwrap_or(false)
                })
            })
}

fn retrospect_lesson(
    id: &str,
    theme: &str,
    finding: impl Into<String>,
    evidence: Vec<String>,
    next_command: Option<String>,
) -> RetrospectLesson {
    RetrospectLesson {
        id: id.into(),
        theme: theme.into(),
        finding: finding.into(),
        evidence,
        next_command,
    }
}

fn build_retrospect_next_actions(
    options: &RetrospectOptions,
    status: &str,
    has_sprint: bool,
) -> Vec<CoachAction> {
    let run_arg = command_arg(options.run_dir.to_string_lossy().as_ref());
    let root_arg = command_arg(options.root.to_string_lossy().as_ref());
    let mut actions = Vec::new();
    if status == "blocked" {
        actions.push(coach_action(
            1,
            "Diagnose retrospective blockers",
            Some(format!("rs autopilot diagnose {run_arg} --format json")),
            "Classify blockers before running another offline action.",
            false,
            false,
        ));
    }
    if !has_sprint || status == "dryRun" {
        actions.push(coach_action(
            2,
            "Run agenda sprint",
            Some(format!(
                "rs autopilot sprint --run-dir {run_arg} --root {root_arg} --limit {} --max-steps 3 --format json",
                options.limit
            )),
            "Make bounded safe offline progress and record receipts.",
            false,
            false,
        ));
    } else {
        actions.push(coach_action(
            2,
            "Refresh next sprint",
            Some(format!(
                "rs autopilot sprint --run-dir {run_arg} --root {root_arg} --limit {} --max-steps 3 --format json",
                options.limit
            )),
            "Continue safe agenda work after reviewing the retrospective.",
            false,
            false,
        ));
    }
    actions.push(coach_action(
        3,
        "Record retrospective in journal",
        Some(format!(
            "rs autopilot journal {run_arg} --entry \"Reviewed retrospective and next evidence boundary\" --evidence {} --format json",
            command_arg(options.run_dir.join("retrospective.json").to_string_lossy().as_ref())
        )),
        "Preserve the lesson boundary for the next AI session.",
        false,
        false,
    ));
    actions.push(coach_action(
        4,
        "Prepare checked creator update",
        Some(format!(
            "rs autopilot respond {run_arg} --claim \"Autopilot retrospective summarized the latest offline evidence\" --format json"
        )),
        "Only report the retrospective after claim-check guards the wording.",
        false,
        false,
    ));
    dedup_next_actions(&mut actions);
    actions
}

fn build_retrospect_agent_brief(
    status: &str,
    source_count: usize,
    lesson_count: usize,
    sprint_executed: usize,
    run_dir: &Path,
) -> String {
    format!(
        "Retrospective status {status} for {}. It summarized {source_count} evidence source(s), captured {lesson_count} lesson(s), and found {sprint_executed} sprint-executed safe action(s). Continue only through listed next actions and keep live proof claims gated.",
        run_dir.to_string_lossy()
    )
}

fn build_control_report(
    prompt: Option<&str>,
    run_dir: Option<&Path>,
    root: &Path,
    limit: usize,
    control_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<ControlReport> {
    let memory_path = control_path.with_file_name("project-memory.json");
    let next_path = control_path.with_file_name("next.json");
    let roadmap_path = control_path.with_file_name("roadmap.json");
    let memory = build_memory_report(root, limit, &memory_path, None)?;
    let next = build_next_report(prompt, run_dir, root, limit, &next_path, None)?;
    let roadmap = build_roadmap_report(prompt, root, limit, &roadmap_path, None)?;
    let selected_run = run_dir
        .map(build_run_index_entry)
        .transpose()?
        .or_else(|| next.selected_run.clone())
        .or_else(|| memory.active_run.clone());

    let mut evidence = vec![
        ControlEvidence {
            kind: "memory".into(),
            status: if memory.active_run.is_some() {
                "activeRun".into()
            } else {
                "noActiveRun".into()
            },
            path: Some(memory.memory_path.clone()),
            summary: format!(
                "memory inspected {} returned run(s); active run: {}",
                memory.returned,
                memory
                    .active_run
                    .as_ref()
                    .map(|run| run.run_dir.as_str())
                    .unwrap_or("none")
            ),
        },
        ControlEvidence {
            kind: "next".into(),
            status: next.status.clone(),
            path: Some(next.next_path.clone()),
            summary: format!("{} -> {}", next.decision, next.recommendation.title),
        },
        ControlEvidence {
            kind: "roadmap".into(),
            status: roadmap.status.clone(),
            path: Some(roadmap.roadmap_path.clone()),
            summary: format!(
                "{} backlog item(s), {} milestone(s)",
                roadmap.backlog.len(),
                roadmap.milestones.len()
            ),
        },
    ];

    let mut artifacts = BTreeMap::from([
        ("memory".into(), memory.memory_path.clone()),
        ("next".into(), next.next_path.clone()),
        ("roadmap".into(), roadmap.roadmap_path.clone()),
    ]);
    let mut blockers = merge_many_sorted(vec![
        memory.blockers.clone(),
        next.blockers.clone(),
        roadmap.blockers.clone(),
    ]);
    let mut warnings = merge_many_sorted(vec![
        memory.warnings.clone(),
        next.warnings.clone(),
        roadmap.warnings.clone(),
    ]);
    let mut do_not_claim = vec![
        "Do not claim production-ready or demo-ready unless judgment.productionReady is true."
            .into(),
        "Do not mutate Studio until live readiness passes and the user explicitly approves apply."
            .into(),
    ];
    let mut status = next.status.clone();
    let mut recommendation = next.recommendation.clone();

    let mut downgraded_discovery_blockers = Vec::new();
    blockers.retain(|blocker| {
        if blocker.starts_with("run root does not exist:") {
            downgraded_discovery_blockers.push(blocker.clone());
            false
        } else {
            true
        }
    });
    warnings.extend(downgraded_discovery_blockers);

    if let Some(run) = &selected_run {
        let selected_run_dir = PathBuf::from(&run.run_dir);
        let alignment = read_next_alignment_state(&selected_run_dir)?;
        if alignment.decisions_exist {
            artifacts.insert(
                "decisions".into(),
                alignment.decisions_path.to_string_lossy().to_string(),
            );
            evidence.push(ControlEvidence {
                kind: "decisions".into(),
                status: "recorded".into(),
                path: Some(alignment.decisions_path.to_string_lossy().to_string()),
                summary: "creator decisions are recorded for this run".into(),
            });
        }
        if alignment.alignment_exists {
            artifacts.insert(
                "alignment".into(),
                alignment.alignment_path.to_string_lossy().to_string(),
            );
            evidence.push(ControlEvidence {
                kind: "alignment".into(),
                status: alignment.status.clone().unwrap_or_else(|| "unknown".into()),
                path: Some(alignment.alignment_path.to_string_lossy().to_string()),
                summary: format!(
                    "decision alignment matched {} rejected direction(s)",
                    alignment.matched_rejections
                ),
            });
        } else if alignment.decisions_exist {
            evidence.push(ControlEvidence {
                kind: "alignment".into(),
                status: "missing".into(),
                path: Some(alignment.decisions_path.to_string_lossy().to_string()),
                summary: "decisions.json exists, but alignment.json has not been written".into(),
            });
        }

        let journal_path = selected_run_dir.join("journal.json");
        if journal_path.exists() {
            let journal_value = read_json_file(&journal_path)?;
            let journal_status =
                string_field(&journal_value, "status").unwrap_or_else(|| "present".into());
            let entry_count = journal_value
                .get("entryCount")
                .and_then(Value::as_u64)
                .unwrap_or(0);
            let artifact_count = journal_value
                .get("artifactCount")
                .and_then(Value::as_u64)
                .unwrap_or(0);
            artifacts.insert("journal".into(), journal_path.to_string_lossy().to_string());
            evidence.push(ControlEvidence {
                kind: "journal".into(),
                status: journal_status,
                path: Some(journal_path.to_string_lossy().to_string()),
                summary: format!(
                    "AI journal has {entry_count} continuation entr{} and {artifact_count} summarized artifact{}",
                    if entry_count == 1 { "y" } else { "ies" },
                    if artifact_count == 1 { "" } else { "s" }
                ),
            });
        }

        let judgment_path = selected_run_dir.join("judgment.json");
        if let Ok(judgment) = build_judgment_report(&selected_run_dir, &judgment_path, None) {
            artifacts.insert("judgment".into(), judgment.judgment_path.clone());
            evidence.push(ControlEvidence {
                kind: "judgment".into(),
                status: judgment.status.clone(),
                path: Some(judgment.judgment_path.clone()),
                summary: format!(
                    "{} score {}; productionReady={}",
                    judgment.verdict, judgment.score, judgment.production_ready
                ),
            });
            blockers.extend(judgment.blockers.clone());
            warnings.extend(judgment.warnings.clone());
            if judgment.production_ready {
                status = "productionReady".into();
            } else {
                do_not_claim.push(format!(
                    "Selected run is not production-ready: judgment status {} ({})",
                    judgment.status, judgment.verdict
                ));
            }
        }

        let playtest_result = read_memory_playtest_result(&selected_run_dir)?;
        if playtest_result.exists
            && (playtest_result.accepted != Some(true)
                || playtest_result.result.as_deref() != Some("passed"))
        {
            let repair_path = selected_run_dir.join("repair-plan.json");
            if let Ok(repair) = build_repair_plan_report(&selected_run_dir, &repair_path, None) {
                artifacts.insert("repairPlan".into(), repair.repair_plan_path.clone());
                evidence.push(ControlEvidence {
                    kind: "repairPlan".into(),
                    status: repair.status.clone(),
                    path: Some(repair.repair_plan_path.clone()),
                    summary: format!("{} repair incident(s)", repair.incident_count),
                });
                blockers.extend(repair.blockers.clone());
                warnings.extend(repair.warnings.clone());
                if repair.status == "needsRepair" {
                    status = "needsRepair".into();
                    if let Some(action) = repair.next_actions.first() {
                        recommendation = action.clone();
                    }
                }
            }
        }
    }

    let mut command_queue = vec![recommendation.clone()];
    command_queue.extend(next.alternatives.clone());
    command_queue.extend(roadmap.backlog.iter().take(5).map(|item| {
        coach_action(
            item.priority,
            &item.title,
            item.command.clone(),
            &item.reason,
            item.requires_live_studio,
            item.mutates_studio,
        )
    }));
    command_queue.push(coach_action(
        99,
        "Refresh mission control",
        Some(format!(
            "rs autopilot control --root {} --limit {} --format json",
            root.to_string_lossy(),
            limit
        )),
        "Regenerate the control packet after any new artifact, live readiness change, or repair run.",
        false,
        false,
    ));
    dedup_next_actions(&mut command_queue);

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    do_not_claim.sort();
    do_not_claim.dedup();
    if !blockers.is_empty() && status != "needsRepair" {
        status = "blocked".into();
    }
    let agent_brief = build_control_agent_brief(&status, selected_run.as_ref(), &recommendation);

    Ok(ControlReport {
        schema_version: "rs.autopilot.control.v1".into(),
        generated_at: now_stamp(),
        control_path: control_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: root.to_string_lossy().to_string(),
        prompt: prompt.map(str::to_string),
        status,
        selected_run,
        recommendation,
        command_queue,
        evidence,
        blockers,
        warnings,
        do_not_claim,
        artifacts,
        agent_brief,
    })
}

fn build_control_agent_brief(
    status: &str,
    selected_run: Option<&RunIndexEntry>,
    recommendation: &CoachAction,
) -> String {
    if let Some(run) = selected_run {
        format!(
            "Control status {status}. Continue from '{}' with next action '{}'. Respect doNotClaim before reporting success.",
            run.plan_id, recommendation.title
        )
    } else {
        format!(
            "Control status {status}. No active run is selected; next action is '{}'. Start offline before live Studio mutation.",
            recommendation.title
        )
    }
}

fn build_user_brief_report(
    prompt: Option<&str>,
    run_dir: Option<&Path>,
    root: &Path,
    limit: usize,
    brief_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<UserBriefReport> {
    let control_path = brief_path.with_file_name("control.json");
    let control = build_control_report(prompt, run_dir, root, limit, &control_path, None)?;
    let mut safe_to_say = Vec::new();
    let mut do_not_say = control.do_not_claim.clone();

    safe_to_say.push(format!(
        "Autopilot status is `{}` based on local run artifacts.",
        control.status
    ));

    let selected_run_label = control
        .selected_run
        .as_ref()
        .map(|run| format!("`{}` at `{}`", run.plan_id, run.run_dir));
    if let Some(run) = &control.selected_run {
        safe_to_say.push(format!(
            "The selected run is `{}` at `{}` with run status `{}`.",
            run.plan_id, run.run_dir, run.status
        ));
    } else {
        safe_to_say.push("No active Autopilot run was selected yet.".into());
        do_not_say
            .push("A Roblox Studio place has already been changed by this Autopilot run.".into());
    }

    match control.status.as_str() {
        "productionReady" => {
            safe_to_say.push(
                "The selected run has recorded production-ready proof in Autopilot judgment."
                    .into(),
            );
        }
        "needsRepair" => {
            safe_to_say.push(
                "A non-passing playtest result is recorded; the safe next step is repair planning."
                    .into(),
            );
            do_not_say.push("The latest recorded playtest passed.".into());
            do_not_say.push("The current run is ready to demo without repairs.".into());
        }
        "needsPlan" => {
            safe_to_say
                .push("The safe next step is to create an offline Autopilot run packet.".into());
        }
        "blocked" => {
            safe_to_say
                .push("Autopilot has blockers that must be resolved before continuing.".into());
            do_not_say.push("The blockers are resolved.".into());
        }
        _ => {
            safe_to_say.push(format!(
                "The recommended next action is `{}`.",
                control.recommendation.title
            ));
        }
    }

    if control.status != "productionReady" {
        do_not_say.push("The run is production-ready or demo-ready.".into());
        do_not_say.push("Live Studio apply, rollback, and playtest proof are complete.".into());
    }
    if !control
        .evidence
        .iter()
        .any(|item| item.kind == "repairPlan" && item.status == "needsRepair")
    {
        do_not_say.push("A repair plan exists for the latest failed playtest.".into());
    }

    let evidence = control
        .evidence
        .iter()
        .map(|item| UserBriefEvidence {
            kind: item.kind.clone(),
            status: item.status.clone(),
            source: item.path.clone(),
            supports: item.summary.clone(),
        })
        .collect::<Vec<_>>();

    let mut next_actions = vec![control.recommendation.clone()];
    next_actions.extend(control.command_queue.iter().skip(1).take(4).cloned());
    dedup_next_actions(&mut next_actions);

    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();

    let needs_live_studio = next_actions
        .iter()
        .any(|action| action.requires_live_studio);
    let needs_user_action = !control.blockers.is_empty()
        || next_actions
            .iter()
            .any(|action| action.requires_live_studio || action.mutates_studio);
    let user_update = build_user_brief_update(&control, selected_run_label.as_deref());
    let agent_brief = format!(
        "Use this brief for user-facing status. Say only items under safeToSay, avoid doNotSay, then run '{}'.",
        control.recommendation.title
    );

    Ok(UserBriefReport {
        schema_version: "rs.autopilot.user-brief.v1".into(),
        generated_at: now_stamp(),
        brief_path: brief_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: root.to_string_lossy().to_string(),
        prompt: prompt.map(str::to_string),
        status: control.status,
        selected_run: control.selected_run,
        user_update,
        safe_to_say,
        do_not_say,
        evidence,
        next_actions,
        blockers: control.blockers,
        warnings: control.warnings,
        needs_user_action,
        needs_live_studio,
        artifacts: control.artifacts,
        agent_brief,
    })
}

fn build_user_brief_update(control: &ControlReport, selected_run_label: Option<&str>) -> String {
    let command = control
        .recommendation
        .command
        .as_deref()
        .unwrap_or("no command available");
    match control.status.as_str() {
        "needsPlan" => format!(
            "I do not have an Autopilot run to continue yet. The safe next step is to create an offline run packet with `{command}`."
        ),
        "needsRepair" => format!(
            "The current run{} has recorded playtest evidence that did not pass. The safe next step is `{}` with `{command}`.",
            selected_run_label
                .map(|label| format!(" {label}"))
                .unwrap_or_default(),
            control.recommendation.title
        ),
        "productionReady" => format!(
            "The selected run{} has recorded production-ready proof. The next step is `{}`.",
            selected_run_label
                .map(|label| format!(" {label}"))
                .unwrap_or_default(),
            control.recommendation.title
        ),
        "blocked" => format!(
            "Autopilot is blocked{}; I should resolve the listed blockers before claiming progress. The next recommended action is `{}`.",
            selected_run_label
                .map(|label| format!(" on {label}"))
                .unwrap_or_default(),
            control.recommendation.title
        ),
        _ => format!(
            "Autopilot selected{} and recommends `{}` next.",
            selected_run_label
                .map(|label| format!(" {label}"))
                .unwrap_or_else(|| " no run".into()),
            control.recommendation.title
        ),
    }
}

fn select_inbox_run(options: &InboxOptions) -> AppResult<(Option<RunIndexEntry>, Vec<String>)> {
    let mut warnings = Vec::new();
    if let Some(run_dir) = &options.run_dir {
        if !run_dir.join("plan.json").exists() {
            warnings.push(format!(
                "run context has no plan.json: {}",
                run_dir.to_string_lossy()
            ));
            return Ok((None, warnings));
        }
        return match build_run_index_entry(run_dir) {
            Ok(run) => Ok((Some(run), warnings)),
            Err(err) => {
                warnings.push(format!(
                    "could not index run context {}: {err}",
                    run_dir.to_string_lossy()
                ));
                Ok((None, warnings))
            }
        };
    }

    let runs = build_runs_report(&options.root, options.limit)?;
    warnings.extend(
        runs.blockers
            .iter()
            .map(|blocker| format!("runs: {blocker}")),
    );
    Ok((select_active_run(&runs.runs).cloned(), warnings))
}

fn default_inbox_path(root: &Path) -> PathBuf {
    root.parent()
        .map(|parent| parent.join("inbox.json"))
        .unwrap_or_else(|| PathBuf::from("inbox.json"))
}

fn build_inbox_report(
    options: &InboxOptions,
    selected_run: Option<RunIndexEntry>,
    inbox_path: &Path,
    markdown_path: Option<&Path>,
    selection_warnings: &mut Vec<String>,
) -> AppResult<InboxReport> {
    let message = options
        .message
        .as_deref()
        .map(str::trim)
        .filter(|message| !message.is_empty());
    let redacted_message = message.map(redact_text);
    let intent = message
        .map(inbox_intent_for_message)
        .unwrap_or("missingMessage")
        .to_string();
    let confidence = inbox_confidence(message, &intent).to_string();
    let mut blockers = Vec::new();
    let mut warnings = std::mem::take(selection_warnings);
    let mut safe_to_say = vec![
        "The creator message has been classified without mutating Roblox Studio.".into(),
        "The next command must still produce artifacts before any implementation claim.".into(),
    ];
    let mut do_not_say = vec![
        "The requested change has been implemented.".into(),
        "The live Studio place was changed.".into(),
        "The game is published, production-ready, or playtested.".into(),
    ];
    if message.is_none() {
        blockers.push("creator message is required".into());
    }
    if intent == "liveApprovalBoundary" {
        safe_to_say.push(
            "The message was routed to approval/readiness gates; it was not treated as permission to mutate Studio."
                .into(),
        );
        do_not_say.push("The creator message approved live Studio mutation.".into());
    }
    if intent == "rollbackRequest" {
        do_not_say.push("Rollback has already been executed.".into());
    }
    if selected_run.is_none()
        && matches!(
            intent.as_str(),
            "feedback" | "creatorDecision" | "rollbackRequest" | "statusRequest"
        )
    {
        warnings.push(
            "no active run context was found; route starts with mission/startup context instead"
                .into(),
        );
    }

    let routes = message
        .map(|message| build_inbox_routes(message, &intent, selected_run.as_ref(), options))
        .unwrap_or_default();
    let mut next_actions = routes
        .iter()
        .map(|route| {
            coach_action(
                route.priority,
                &route.title,
                route.command.clone(),
                &route.rationale,
                route.requires_live_studio,
                route.mutates_studio,
            )
        })
        .collect::<Vec<_>>();
    if next_actions.is_empty() {
        next_actions.push(coach_action(
            90,
            "Refresh project mission",
            Some(format!(
                "rs autopilot mission --root {} --limit {} --format json",
                command_arg(options.root.to_string_lossy().as_ref()),
                options.limit
            )),
            "Rebuild project context before routing another creator message.",
            false,
            false,
        ));
    }
    dedup_next_actions(&mut next_actions);

    let mut artifacts = selected_run
        .as_ref()
        .map(|run| collect_planner_run_artifacts(Some(Path::new(&run.run_dir))))
        .unwrap_or_default();
    artifacts.insert("inbox".into(), inbox_path.to_string_lossy().to_string());
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "inboxMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else if intent == "liveApprovalBoundary" {
        "approvalGateRequired"
    } else if selected_run.is_none()
        && matches!(
            intent.as_str(),
            "feedback" | "creatorDecision" | "rollbackRequest" | "statusRequest"
        )
    {
        "needsRunContext"
    } else if intent == "buildRequest" && selected_run.is_none() {
        "readyToStart"
    } else {
        "routed"
    };
    let agent_brief = build_inbox_agent_brief(status, &intent, selected_run.as_ref());

    Ok(InboxReport {
        schema_version: "rs.autopilot.inbox.v1".into(),
        generated_at: now_stamp(),
        inbox_path: inbox_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        source: options.source.clone(),
        message: redacted_message,
        status: status.into(),
        intent,
        confidence,
        selected_run,
        routes,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
    })
}

fn inbox_intent_for_message(message: &str) -> &'static str {
    let lower = message.to_ascii_lowercase();
    if inbox_has_any(
        &lower,
        &[
            "rollback",
            "roll back",
            "undo",
            "revert",
            "restore previous",
        ],
    ) {
        return "rollbackRequest";
    }
    if inbox_has_any(
        &lower,
        &[
            "apply",
            "go live",
            "publish",
            "upload",
            "release",
            "ship it",
            "production",
            "push it",
            "make it live",
        ],
    ) {
        return "liveApprovalBoundary";
    }
    if inbox_has_any(
        &lower,
        &[
            "status",
            "progress",
            "what changed",
            "where are we",
            "report",
            "update me",
            "is it done",
        ],
    ) {
        return "statusRequest";
    }
    if inbox_has_any(
        &lower,
        &[
            "bug",
            "broken",
            "confusing",
            "too hard",
            "too easy",
            "too high",
            "too low",
            "slow",
            "lag",
            "fix",
            "change",
            "button",
            "price",
            "thumbnail",
            "doesn't work",
            "does not work",
        ],
    ) {
        return "feedback";
    }
    if inbox_has_any(
        &lower,
        &[
            "do not",
            "don't",
            "avoid",
            "without",
            "must",
            "keep",
            "prefer",
            "constraint",
            "reject",
            "no combat",
            "no gacha",
        ],
    ) {
        return "creatorDecision";
    }
    if inbox_has_any(
        &lower,
        &[
            "add",
            "build",
            "make",
            "create",
            "generate",
            "implement",
            "game",
            "shop",
            "tycoon",
            "obby",
            "quest",
            "enemy",
            "save",
            "inventory",
        ],
    ) {
        return "buildRequest";
    }
    "generalMessage"
}

fn inbox_confidence(message: Option<&str>, intent: &str) -> &'static str {
    let Some(message) = message else {
        return "none";
    };
    let words = message.split_whitespace().count();
    if matches!(intent, "generalMessage" | "missingMessage") {
        "low"
    } else if words >= 4 {
        "high"
    } else {
        "medium"
    }
}

fn inbox_has_any(lower: &str, needles: &[&str]) -> bool {
    needles.iter().any(|needle| lower.contains(needle))
}

fn build_inbox_routes(
    message: &str,
    intent: &str,
    selected_run: Option<&RunIndexEntry>,
    options: &InboxOptions,
) -> Vec<InboxRoute> {
    let mut routes = Vec::new();
    let message_arg = command_arg(message);
    let source_arg = command_arg(&options.source);
    if let Some(run) = selected_run {
        let run_arg = command_arg(&run.run_dir);
        match intent {
            "feedback" => routes.push(inbox_route(
                1,
                "feedback",
                "Triage creator feedback",
                Some(format!(
                    "rs autopilot feedback {run_arg} --source {source_arg} --note {message_arg} --format json"
                )),
                "Convert the message into categorized feedback lanes, clarification questions, and patch commands.",
                false,
                false,
            )),
            "creatorDecision" => routes.push(inbox_route(
                1,
                "decision",
                "Record creator decision",
                Some(format!(
                    "rs autopilot decision {run_arg} --source {source_arg} {} {message_arg} --format json",
                    inbox_decision_flag(message)
                )),
                "Preserve the creator's preference, constraint, or rejection before another AI continues the run.",
                false,
                false,
            )),
            "rollbackRequest" => routes.push(inbox_route(
                1,
                "rollback",
                "Prepare rollback readiness",
                Some(format!("rs autopilot rollback {run_arg} --format json")),
                "Build the rollback packet before claiming undo is possible or complete.",
                false,
                false,
            )),
            "statusRequest" => {
                routes.push(inbox_route(
                    1,
                    "cycle",
                    "Refresh AI cycle",
                    Some(format!("rs autopilot cycle {run_arg} --format json")),
                    "Refresh evidence before composing a status update.",
                    false,
                    false,
                ));
                routes.push(inbox_route(
                    2,
                    "respond",
                    "Compose evidence-gated response",
                    Some(format!("rs autopilot respond {run_arg} --format json")),
                    "Send a creator update only after claim-check supports the wording.",
                    false,
                    false,
                ));
            }
            "liveApprovalBoundary" => {
                routes.push(inbox_route(
                    1,
                    "approval",
                    "Refresh approval packet",
                    Some(format!("rs autopilot approval {run_arg} --format json")),
                    "Show the exact live mutation boundary without treating chat as apply permission.",
                    false,
                    false,
                ));
                routes.push(inbox_route(
                    2,
                    "liveGate",
                    "Check live gate",
                    Some(format!("rs autopilot live-gate {run_arg} --format json")),
                    "Require live readiness, approval evidence, proof, privacy, rollback, and bundle checks before apply.",
                    true,
                    false,
                ));
                routes.push(inbox_route(
                    3,
                    "ready",
                    "Check Studio readiness",
                    Some("rs autopilot ready --timeout 90 --format json".into()),
                    "Verify bridge and plugin readiness before any future mutation command.",
                    true,
                    false,
                ));
            }
            "buildRequest" | "generalMessage" => {
                routes.push(inbox_route(
                    1,
                    "feedback",
                    "Treat as run feedback or extension request",
                    Some(format!(
                        "rs autopilot feedback {run_arg} --source {source_arg} --note {message_arg} --format json"
                    )),
                    "For an existing run, convert the creator's new request into a patch lane instead of mutating immediately.",
                    false,
                    false,
                ));
                routes.push(inbox_route(
                    2,
                    "plannerPack",
                    "Prepare custom planner context",
                    Some(format!(
                        "rs autopilot planner-pack {message_arg} --run-dir {run_arg} --format json"
                    )),
                    "Give an external model a redacted, strict planning packet if deterministic patch lanes are not enough.",
                    false,
                    false,
                ));
            }
            _ => {}
        }
    } else {
        match intent {
            "buildRequest" | "generalMessage" => routes.push(inbox_route(
                1,
                "start",
                "Start safe offline run",
                Some(format!(
                    "rs autopilot start {message_arg} --root {} --format json",
                    command_arg(options.root.to_string_lossy().as_ref())
                )),
                "Bootstrap the request through intake, kickoff, proof, privacy, and review artifacts without mutating Studio.",
                false,
                false,
            )),
            "liveApprovalBoundary" | "rollbackRequest" | "statusRequest" | "feedback"
            | "creatorDecision" => routes.push(inbox_route(
                1,
                "mission",
                "Find a run before routing",
                Some(format!(
                    "rs autopilot mission {message_arg} --root {} --limit {} --format json",
                    command_arg(options.root.to_string_lossy().as_ref()),
                    options.limit
                )),
                "Locate the active run or ask for context before treating the message as feedback, approval, rollback, or status work.",
                false,
                false,
            )),
            _ => {}
        }
    }
    routes
}

fn inbox_decision_flag(message: &str) -> &'static str {
    let lower = message.to_ascii_lowercase();
    if inbox_has_any(
        &lower,
        &["do not", "don't", "avoid", "without", "reject", "no gacha"],
    ) {
        "--rejection"
    } else if inbox_has_any(&lower, &["must", "keep", "constraint", "no combat"]) {
        "--constraint"
    } else {
        "--decision"
    }
}

fn inbox_route(
    priority: u8,
    kind: &str,
    title: &str,
    command: Option<String>,
    rationale: &str,
    requires_live_studio: bool,
    mutates_studio: bool,
) -> InboxRoute {
    let expected_artifacts = command
        .as_deref()
        .map(expected_artifacts_for_command)
        .unwrap_or_default();
    InboxRoute {
        priority,
        kind: kind.into(),
        title: title.into(),
        command,
        rationale: rationale.into(),
        expected_artifacts,
        requires_live_studio,
        mutates_studio,
    }
}

fn build_inbox_agent_brief(
    status: &str,
    intent: &str,
    selected_run: Option<&RunIndexEntry>,
) -> String {
    if let Some(run) = selected_run {
        format!(
            "Inbox routed a creator message as {intent} for run '{}' with status {status}. Use the first non-mutating route and keep live apply behind approval/live-gate evidence.",
            run.plan_id
        )
    } else {
        format!(
            "Inbox routed a creator message as {intent} with status {status}. Establish or select a run before claiming feedback, rollback, status, or approval work is complete."
        )
    }
}

fn select_handle_run(options: &HandleOptions) -> AppResult<(Option<RunIndexEntry>, Vec<String>)> {
    select_inbox_run(&InboxOptions {
        message: options.message.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        source: options.source.clone(),
        out: None,
        markdown: None,
        no_markdown: options.no_markdown,
        json: false,
    })
}

fn default_handle_path(root: &Path) -> PathBuf {
    root.parent()
        .map(|parent| parent.join("handle.json"))
        .unwrap_or_else(|| PathBuf::from("handle.json"))
}

fn build_handle_report(
    options: &HandleOptions,
    selected_run: Option<RunIndexEntry>,
    handle_path: &Path,
    markdown_path: Option<&Path>,
    selection_warnings: &mut Vec<String>,
) -> AppResult<HandleReport> {
    let inbox_path = selected_run
        .as_ref()
        .map(|run| PathBuf::from(&run.run_dir).join("inbox.json"))
        .unwrap_or_else(|| handle_path.with_file_name("inbox.json"));
    let inbox_markdown_path = (!options.no_markdown).then(|| inbox_path.with_extension("md"));
    let inbox_options = InboxOptions {
        message: options.message.clone(),
        run_dir: selected_run.as_ref().map(|run| PathBuf::from(&run.run_dir)),
        root: options.root.clone(),
        limit: options.limit,
        source: options.source.clone(),
        out: Some(inbox_path.clone()),
        markdown: inbox_markdown_path.clone(),
        no_markdown: options.no_markdown,
        json: false,
    };
    let inbox = build_inbox_report(
        &inbox_options,
        selected_run,
        &inbox_path,
        inbox_markdown_path.as_deref(),
        selection_warnings,
    )?;
    write_json(inbox_path.clone(), &inbox)?;
    if let Some(path) = inbox_markdown_path.clone() {
        write_inbox_markdown(path, &inbox)?;
    }

    let selected_route = inbox.routes.first().cloned();
    let mut safe_to_say = inbox.safe_to_say.clone();
    let mut do_not_say = inbox.do_not_say.clone();
    let mut blockers = inbox.blockers.clone();
    let mut warnings = inbox.warnings.clone();
    let mut artifacts = inbox.artifacts.clone();
    artifacts.insert("handle".into(), handle_path.to_string_lossy().to_string());
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "handleMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    let mut next_actions = inbox.next_actions.clone();
    let mut selected_run = inbox.selected_run.clone();
    let mut execution = None;

    if blockers.is_empty() {
        if let Some(route) = &selected_route {
            let outcome = execute_handle_route(options, route, selected_run.as_ref())?;
            selected_run = outcome.selected_run.or(selected_run);
            safe_to_say.extend(outcome.safe_to_say);
            do_not_say.extend(outcome.do_not_say);
            blockers.extend(outcome.blockers);
            warnings.extend(outcome.warnings);
            artifacts.extend(outcome.artifacts);
            next_actions = outcome.next_actions;
            execution = Some(outcome.execution);
        } else {
            blockers.push("inbox did not produce a route to handle".into());
        }
    }

    if let Some(run) = &selected_run {
        artifacts.extend(collect_planner_run_artifacts(Some(Path::new(&run.run_dir))));
    }
    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    dedup_next_actions(&mut next_actions);

    let status = handle_status(
        options.dry_run,
        &blockers,
        selected_route.as_ref(),
        execution.as_ref(),
    );
    let verdict = handle_verdict(&status);
    let agent_brief = build_handle_agent_brief(
        &status,
        &inbox.intent,
        selected_route.as_ref(),
        execution.as_ref(),
        selected_run.as_ref(),
    );

    Ok(HandleReport {
        schema_version: "rs.autopilot.handle.v1".into(),
        generated_at: now_stamp(),
        handle_path: handle_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        source: options.source.clone(),
        message: inbox.message.clone(),
        status,
        verdict,
        inbox_status: inbox.status,
        inbox_intent: inbox.intent,
        selected_run,
        selected_route,
        execution,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
    })
}

fn execute_handle_route(
    options: &HandleOptions,
    route: &InboxRoute,
    selected_run: Option<&RunIndexEntry>,
) -> AppResult<HandleRouteOutcome> {
    if options.dry_run {
        return Ok(handle_outcome(
            route,
            "dryRun",
            "routeSelected",
            "Selected the safest route without executing it.",
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            Vec::new(),
            route_next_actions(route),
            selected_run.cloned(),
        ));
    }
    if route.kind == "approval" || route.requires_live_studio || route.mutates_studio {
        return Ok(handle_outcome(
            route,
            "skippedLiveGate",
            "liveGateRequired",
            "Skipped execution because the selected route requires live Studio or a mutation boundary.",
            Vec::new(),
            vec!["The message was routed to a live-readiness or approval gate.".into()],
            vec![
                "The selected live or approval route has already run.".into(),
                "The live Studio place was changed.".into(),
            ],
            Vec::new(),
            Vec::new(),
            route_next_actions(route),
            selected_run.cloned(),
        ));
    }

    match route.kind.as_str() {
        "feedback" => execute_handle_feedback(options, route, selected_run),
        "decision" => execute_handle_decision(options, route, selected_run),
        "rollback" => execute_handle_rollback(route, selected_run),
        "cycle" => execute_handle_cycle(options, route, selected_run),
        "respond" => execute_handle_respond(options, route, selected_run),
        "start" => execute_handle_start(options, route),
        "mission" => execute_handle_mission(options, route),
        _ => Ok(handle_outcome(
            route,
            "unsupportedRoute",
            "manualRouteRequired",
            "The inbox route is safe to inspect, but handle does not execute this route kind yet.",
            Vec::new(),
            Vec::new(),
            Vec::new(),
            vec![format!(
                "handle does not execute route kind `{}` automatically",
                route.kind
            )],
            Vec::new(),
            route_next_actions(route),
            selected_run.cloned(),
        )),
    }
}

fn execute_handle_feedback(
    options: &HandleOptions,
    route: &InboxRoute,
    selected_run: Option<&RunIndexEntry>,
) -> AppResult<HandleRouteOutcome> {
    let run_dir = handle_selected_run_dir(selected_run)?;
    let feedback_path = run_dir.join("feedback.json");
    let markdown_path = (!options.no_markdown).then(|| run_dir.join("feedback.md"));
    let report = build_feedback_report(
        &FeedbackOptions {
            run_dir: run_dir.clone(),
            notes: options.message.iter().cloned().collect(),
            source: options.source.clone(),
            out: Some(feedback_path.clone()),
            markdown: markdown_path.clone(),
            no_markdown: options.no_markdown,
            json: false,
        },
        &feedback_path,
        markdown_path.as_deref(),
    )?;
    write_json(feedback_path.clone(), &report)?;
    if let Some(path) = markdown_path.clone() {
        write_feedback_markdown(path, &report)?;
    }
    refresh_run_bundle_if_possible(&run_dir)?;
    Ok(handle_outcome_from_report(
        route,
        &report.status,
        "feedbackTriaged",
        "Executed feedback triage for the creator message.",
        report.artifacts,
        report.safe_to_say,
        report.do_not_say,
        report.blockers,
        report.warnings,
        report.next_actions,
        selected_run.cloned(),
    ))
}

fn execute_handle_decision(
    options: &HandleOptions,
    route: &InboxRoute,
    selected_run: Option<&RunIndexEntry>,
) -> AppResult<HandleRouteOutcome> {
    let run_dir = handle_selected_run_dir(selected_run)?;
    let message = options.message.clone().unwrap_or_default();
    let mut decisions = Vec::new();
    let mut constraints = Vec::new();
    let mut rejections = Vec::new();
    match inbox_decision_flag(&message) {
        "--constraint" => constraints.push(message),
        "--rejection" => rejections.push(message),
        _ => decisions.push(message),
    }
    let decision_path = run_dir.join("decisions.json");
    let markdown_path = (!options.no_markdown).then(|| run_dir.join("decisions.md"));
    let report = build_decision_report(
        &DecisionOptions {
            run_dir: run_dir.clone(),
            source: options.source.clone(),
            decisions,
            constraints,
            rejections,
            notes: Vec::new(),
            out: Some(decision_path.clone()),
            markdown: markdown_path.clone(),
            no_markdown: options.no_markdown,
            json: false,
        },
        &decision_path,
        markdown_path.as_deref(),
    )?;
    write_json(decision_path.clone(), &report)?;
    if let Some(path) = markdown_path.clone() {
        write_decision_markdown(path, &report)?;
    }
    refresh_run_bundle_if_possible(&run_dir)?;
    Ok(handle_outcome_from_report(
        route,
        &report.status,
        "decisionRecorded",
        "Recorded the creator message in the decision ledger.",
        report.artifacts,
        report.safe_to_say,
        report.do_not_say,
        report.blockers,
        report.warnings,
        report.next_actions,
        selected_run.cloned(),
    ))
}

fn execute_handle_rollback(
    route: &InboxRoute,
    selected_run: Option<&RunIndexEntry>,
) -> AppResult<HandleRouteOutcome> {
    let run_dir = handle_selected_run_dir(selected_run)?;
    let rollback_path = run_dir.join("rollback.json");
    let markdown_path = run_dir.join("rollback.md");
    let report = build_rollback_report(&run_dir, &rollback_path, Some(&markdown_path))?;
    write_json(rollback_path.clone(), &report)?;
    write_rollback_markdown(markdown_path.clone(), &report)?;
    refresh_run_bundle_if_possible(&run_dir)?;
    let mut artifacts = collect_planner_run_artifacts(Some(&run_dir));
    artifacts.insert(
        "rollback".into(),
        rollback_path.to_string_lossy().to_string(),
    );
    artifacts.insert(
        "rollbackMarkdown".into(),
        markdown_path.to_string_lossy().to_string(),
    );
    Ok(handle_outcome_from_report(
        route,
        &report.status,
        "rollbackPacketWritten",
        "Prepared rollback readiness evidence for the creator request.",
        artifacts,
        report.claim_ready,
        report.do_not_claim,
        report.blockers,
        report.warnings,
        report.next_actions,
        selected_run.cloned(),
    ))
}

fn execute_handle_cycle(
    options: &HandleOptions,
    route: &InboxRoute,
    selected_run: Option<&RunIndexEntry>,
) -> AppResult<HandleRouteOutcome> {
    let run_dir = handle_selected_run_dir(selected_run)?;
    let cycle_path = run_dir.join("cycle.json");
    let markdown_path = (!options.no_markdown).then(|| run_dir.join("cycle.md"));
    let cycle_options = CycleOptions {
        run_dir: run_dir.clone(),
        prompt: options.message.clone(),
        root: options.root.clone(),
        limit: options.limit,
        out: Some(cycle_path.clone()),
        markdown: markdown_path.clone(),
        no_markdown: options.no_markdown,
        json: false,
    };
    let cycle = build_cycle_report(&cycle_options, &cycle_path, markdown_path.as_deref())?;
    write_json(cycle_path.clone(), &cycle)?;
    if let Some(path) = markdown_path.clone() {
        write_cycle_markdown(path, &cycle)?;
    }
    let mut artifacts = cycle.artifacts.clone();
    let mut safe_to_say = cycle.safe_to_say.clone();
    let mut do_not_say = cycle.do_not_say.clone();
    let mut blockers = cycle.blockers.clone();
    let mut warnings = cycle.warnings.clone();
    let mut next_actions = cycle.next_actions.clone();
    let mut status = cycle.status.clone();
    let mut summary = "Refreshed the AI cycle for the creator status request.".to_string();
    if cycle.status == "readyToReport" {
        let response_path = run_dir.join("response.json");
        let response_markdown_path = (!options.no_markdown).then(|| run_dir.join("response.md"));
        let response = build_creator_response_report(
            &RespondOptions {
                run_dir: run_dir.clone(),
                claims: Vec::new(),
                out: Some(response_path.clone()),
                markdown: response_markdown_path.clone(),
                no_markdown: options.no_markdown,
                json: false,
            },
            &response_path,
            response_markdown_path.as_deref(),
        )?;
        write_json(response_path.clone(), &response)?;
        if let Some(path) = response_markdown_path {
            write_creator_response_markdown(path, &response)?;
        }
        artifacts.extend(response.artifacts.clone());
        safe_to_say.extend(response.safe_to_say.clone());
        do_not_say.extend(response.do_not_say.clone());
        blockers.extend(response.blockers.clone());
        warnings.extend(response.warnings.clone());
        next_actions = response.next_actions.clone();
        status = response.status.clone();
        summary =
            "Refreshed cycle evidence and composed an evidence-gated creator response.".into();
    }
    refresh_run_bundle_if_possible(&run_dir)?;
    Ok(handle_outcome_from_report(
        route,
        &status,
        "cycleHandled",
        &summary,
        artifacts,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        next_actions,
        selected_run.cloned(),
    ))
}

