fn execute_handle_start(
    options: &HandleOptions,
    route: &InboxRoute,
) -> AppResult<HandleRouteOutcome> {
    let start_path = default_handle_path(&options.root).with_file_name("start.json");
    let markdown_path = (!options.no_markdown).then(|| start_path.with_extension("md"));
    let report = build_start_report(
        &StartOptions {
            port: options.port,
            prompt: options.message.clone(),
            studio: options.studio.clone(),
            scope: options.scope.clone(),
            root: options.root.clone(),
            run_dir: None,
            limit: options.limit,
            assume: options.assume,
            smoke: options.smoke.clone(),
            out: Some(start_path.clone()),
            markdown: markdown_path.clone(),
            no_markdown: options.no_markdown,
            json: false,
        },
        &start_path,
        markdown_path.as_deref(),
    )?;
    write_json(start_path.clone(), &report)?;
    if let Some(path) = markdown_path {
        write_start_markdown(path, &report)?;
    }
    let selected_run = report.run_dir.as_ref().and_then(|run| {
        let run_dir = PathBuf::from(run);
        build_run_index_entry(&run_dir).ok()
    });
    if let Some(run) = &selected_run {
        refresh_run_bundle_if_possible(Path::new(&run.run_dir))?;
    }
    Ok(handle_outcome_from_report(
        route,
        &report.status,
        "startHandled",
        "Started the safe offline Autopilot build path for the creator message.",
        report.artifacts,
        vec!["The creator request has been converted into offline Autopilot artifacts.".into()],
        vec![
            "The live Studio place was changed.".into(),
            "The generated run has been playtested or published.".into(),
        ],
        report.blockers,
        report.warnings,
        report.next_actions,
        selected_run,
    ))
}

