fn flight_recorder_spec(
    relative_path: &'static str,
    title: &'static str,
    phase: &'static str,
) -> FlightRecorderSpec {
    FlightRecorderSpec {
        relative_path,
        title,
        phase,
    }
}

fn flight_event_from_value(
    order: usize,
    spec: &FlightRecorderSpec,
    path: &Path,
    value: &Value,
) -> FlightEvent {
    let status = string_field(value, "status").unwrap_or_else(|| "present".into());
    let verdict = string_field(value, "verdict");
    let summary = string_field(value, "agentBrief")
        .or_else(|| string_field(value, "summary"))
        .or_else(|| verdict.clone())
        .unwrap_or_else(|| format!("{} artifact is present", spec.title));
    FlightEvent {
        order,
        artifact: spec.relative_path.into(),
        title: spec.title.into(),
        phase: spec.phase.into(),
        status,
        verdict,
        summary,
        modified_unix_seconds: file_modified_unix_seconds(path),
    }
}

fn flight_evidence_from_value(
    spec: &FlightRecorderSpec,
    path: &Path,
    value: &Value,
) -> FlightEvidence {
    FlightEvidence {
        artifact: spec.relative_path.into(),
        path: path.to_string_lossy().to_string(),
        status: string_field(value, "status").unwrap_or_else(|| "present".into()),
        verdict: string_field(value, "verdict"),
        safe_claim_count: value
            .get("safeToSay")
            .and_then(Value::as_array)
            .map_or(0, Vec::len),
        forbidden_claim_count: value
            .get("doNotSay")
            .or_else(|| value.get("doNotClaim"))
            .and_then(Value::as_array)
            .map_or(0, Vec::len),
        blocker_count: value
            .get("blockers")
            .and_then(Value::as_array)
            .map_or(0, Vec::len),
    }
}

fn collect_flight_commands(
    source_artifact: &str,
    value: &Value,
    commands: &mut Vec<FlightCommand>,
) {
    let mut discovered = Vec::new();
    collect_command_guard_value_commands(value, &mut discovered);
    collect_runbook_step_commands(value, &mut discovered);
    for command in discovered {
        let item = command_guard_item(commands.len() + 1, &command);
        commands.push(FlightCommand {
            order: commands.len() + 1,
            source_artifact: source_artifact.into(),
            command: item.command,
            command_kind: item.command_kind,
            verdict: item.verdict,
            act_supported: item.act_supported,
            requires_live_studio: item.requires_live_studio,
            mutates_studio: item.mutates_studio,
            expected_artifacts: item.expected_artifacts,
        });
    }
}

fn collect_runbook_step_commands(value: &Value, commands: &mut Vec<String>) {
    for field in ["safePrefix", "gatedSuffix", "runbookSteps", "steps"] {
        if let Some(items) = value.get(field).and_then(Value::as_array) {
            for command in items
                .iter()
                .filter_map(|item| {
                    item.get("command")
                        .or_else(|| item.get("sourceCommand"))
                        .and_then(Value::as_str)
                })
                .map(str::trim)
                .filter(|command| !command.is_empty())
            {
                commands.push(command.to_string());
            }
        }
    }
}

fn dedup_flight_commands(commands: &mut Vec<FlightCommand>) {
    let mut seen = BTreeSet::new();
    commands.retain(|command| {
        let key = format!("{}\n{}", command.source_artifact, command.command);
        seen.insert(key)
    });
}

fn build_flight_recorder_next_actions(
    run_dir: &Path,
    status: &str,
    commands: &[FlightCommand],
    evidence: &[FlightEvidence],
) -> Vec<CoachAction> {
    let has_runbook = evidence.iter().any(|item| item.artifact == "runbook.json");
    let mut actions = Vec::new();
    if !has_runbook {
        actions.push(coach_action(
            1,
            "Write execution runbook",
            Some(format!(
                "rs autopilot runbook --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Split the recorded command queue into a reviewed safe prefix and gated suffix before acting.",
            false,
            false,
        ));
    }
    if let Some(command) = commands.iter().find(|command| {
        command.act_supported && !command.requires_live_studio && !command.mutates_studio
    }) {
        actions.push(coach_action(
            2,
            "Execute first safe recorded command through act",
            Some(format!(
                "rs autopilot act {} --command {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref()),
                command_arg(&command.command)
            )),
            "Use the internal handler path for one reviewed offline command, then refresh the recorder.",
            false,
            false,
        ));
    }
    if status == "needsAttention" {
        actions.push(coach_action(
            3,
            "Diagnose recorded blockers",
            Some(format!(
                "rs autopilot diagnose {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Convert blocker evidence into a concrete recovery command.",
            false,
            false,
        ));
    }
    actions.push(coach_action(
        9,
        "Refresh proof before reporting",
        Some(format!(
            "rs autopilot proof {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Make creator-facing claims from proof, not from recorder summaries.",
        false,
        false,
    ));
    actions
}

fn build_flight_recorder_agent_brief(
    status: &str,
    event_count: usize,
    command_count: usize,
    blocker_count: usize,
    live_or_mutating_count: usize,
) -> String {
    match status {
        "ready" => format!(
            "Flight recorder captured {event_count} evidence event(s) and {command_count} recorded command(s). No live or mutating command is required before the next offline step."
        ),
        "hasGates" => format!(
            "Flight recorder captured {event_count} evidence event(s), including {live_or_mutating_count} live or mutating command(s). Stop at runbook, approval, rehearsal, ready/live-gate, rollback, and proof before crossing that boundary."
        ),
        "empty" => "Flight recorder found no readable run artifacts. Start or orient the run before relying on this folder.".into(),
        _ => format!(
            "Flight recorder captured {event_count} evidence event(s) with {blocker_count} blocker source(s). Diagnose and refresh guarded commands before reporting progress."
        ),
    }
}

fn build_navigator_report(
    options: &NavigatorOptions,
    navigator_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<NavigatorReport> {
    let base_dir = navigator_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let orientation_path = options
        .run_dir
        .as_ref()
        .map(|run_dir| run_dir.join("orientation.json"))
        .unwrap_or_else(|| base_dir.join("orientation.json"));
    let orientation_markdown_path =
        (!options.no_markdown).then(|| orientation_path.with_extension("md"));
    let orient_options = OrientOptions {
        prompt: options.prompt.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        out: Some(orientation_path.clone()),
        markdown: orientation_markdown_path.clone(),
        no_markdown: options.no_markdown,
        json: false,
    };
    let orientation = build_orient_report(
        &orient_options,
        &orientation_path,
        orientation_markdown_path.as_deref(),
    )?;
    write_json(orientation_path.clone(), &orientation)?;
    if let Some(path) = orientation_markdown_path.clone() {
        write_orient_markdown(path, &orientation)?;
    }

    let mut artifacts = orientation.artifacts.clone();
    artifacts.insert(
        "navigator".into(),
        navigator_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "navigatorMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert(
        "orientation".into(),
        orientation_path.to_string_lossy().to_string(),
    );
    if let Some(path) = orientation_markdown_path {
        artifacts.insert(
            "orientationMarkdown".into(),
            path.to_string_lossy().to_string(),
        );
    }

    let runbook_value = artifacts
        .get("runbook")
        .and_then(|path| read_json_if_exists(Path::new(path)).ok().flatten());
    let flight_value = artifacts
        .get("flightRecorder")
        .and_then(|path| read_json_if_exists(Path::new(path)).ok().flatten());
    let first_safe_action = build_navigator_first_safe_action(
        options.run_dir.as_deref(),
        runbook_value.as_ref(),
        orientation.command_queue.first(),
    );
    let next_command = first_safe_action
        .as_ref()
        .and_then(|action| action.command.clone())
        .or_else(|| orientation.next_command.clone());
    let situation = build_navigator_situation(
        &artifacts,
        &orientation,
        runbook_value.as_ref(),
        flight_value.as_ref(),
    );
    let stop_conditions = build_navigator_stop_conditions(runbook_value.as_ref());

    let mut warnings = orientation.warnings.clone();
    if first_safe_action.is_none() && orientation.selected_run.is_some() {
        warnings.push("navigator could not find a safe first action; inspect runbook and flight-recorder before acting".into());
    }
    warnings.sort();
    warnings.dedup();
    let mut blockers = orientation.blockers.clone();
    let unsupported = flight_value
        .as_ref()
        .and_then(|value| value.get("commands"))
        .and_then(Value::as_array)
        .map(|commands| {
            commands
                .iter()
                .filter(|command| {
                    command.get("commandKind").map_or(true, Value::is_null)
                        || command
                            .get("verdict")
                            .and_then(Value::as_str)
                            .is_some_and(|verdict| verdict.contains("Unknown"))
                })
                .count()
        })
        .unwrap_or(0);
    if unsupported > 0 {
        warnings.push(format!(
            "{unsupported} recorded command(s) are unsupported; follow runbook safePrefix before considering recorder history"
        ));
    }
    blockers.sort();
    blockers.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else if orientation.selected_run.is_none() {
        "needsRun"
    } else if first_safe_action.is_some() {
        "readyToAct"
    } else if next_command.is_some() {
        "readyWithGates"
    } else {
        "readyForHandoff"
    }
    .to_string();
    let mode = match status.as_str() {
        "blocked" => "repair",
        "needsRun" => "start",
        "readyToAct" => "operate",
        "readyWithGates" => "approval",
        _ => "handoff",
    }
    .to_string();
    let safe_to_say = orientation.safe_to_say.clone();
    let mut do_not_say = orientation.do_not_say.clone();
    do_not_say.push(
        "Do not claim the navigator executed work; it only prepared the next operating card."
            .into(),
    );
    do_not_say.sort();
    do_not_say.dedup();
    let agent_brief = build_navigator_agent_brief(
        &status,
        next_command.as_deref(),
        first_safe_action.as_ref(),
        &situation,
    );

    Ok(NavigatorReport {
        schema_version: "rs.autopilot.navigator.v1".into(),
        generated_at: now_stamp(),
        navigator_path: navigator_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        prompt: options.prompt.clone(),
        selected_run: orientation.selected_run.clone(),
        status,
        mode,
        orientation_path: orientation.orientation_path.clone(),
        next_command,
        first_safe_action,
        read_order: orientation.read_order.clone(),
        situation,
        stop_conditions,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        agent_brief,
    })
}

fn build_model_pack_report(
    options: &ModelPackOptions,
    model_pack_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<ModelPackReport> {
    let write_markdown = markdown_path.is_some();
    let navigator_path = options.run_dir.join("navigator.json");
    let navigator_markdown_path = write_markdown.then(|| options.run_dir.join("navigator.md"));
    let navigator_options = NavigatorOptions {
        prompt: options.prompt.clone(),
        run_dir: Some(options.run_dir.clone()),
        root: options.root.clone(),
        limit: options.limit,
        out: Some(navigator_path.clone()),
        markdown: navigator_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let navigator = build_navigator_report(
        &navigator_options,
        &navigator_path,
        navigator_markdown_path.as_deref(),
    )?;
    write_json(navigator_path.clone(), &navigator)?;
    if let Some(path) = navigator_markdown_path {
        write_navigator_markdown(path, &navigator)?;
    }

    let delivery_path = options.run_dir.join("delivery.json");
    let delivery_markdown_path = write_markdown.then(|| options.run_dir.join("delivery.md"));
    let delivery_options = DeliverOptions {
        run_dir: options.run_dir.clone(),
        prompt: options.prompt.clone(),
        out: Some(delivery_path.clone()),
        markdown: delivery_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let delivery = build_delivery_report(
        &delivery_options,
        &delivery_path,
        delivery_markdown_path.as_deref(),
    )?;
    write_json(delivery_path.clone(), &delivery)?;
    if let Some(path) = delivery_markdown_path {
        write_delivery_markdown(path, &delivery)?;
    }

    let mut artifacts = navigator.artifacts.clone();
    artifacts.extend(delivery.artifacts.clone());
    artifacts.extend(collect_planner_run_artifacts(Some(&options.run_dir)));
    artifacts.insert(
        "modelPack".into(),
        model_pack_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "modelPackMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert("navigator".into(), navigator.navigator_path.clone());
    artifacts.insert("delivery".into(), delivery.delivery_path.clone());

    let mut blockers =
        merge_many_sorted(vec![navigator.blockers.clone(), delivery.blockers.clone()]);
    let mut warnings =
        merge_many_sorted(vec![navigator.warnings.clone(), delivery.warnings.clone()]);
    let mut safe_to_say = merge_many_sorted(vec![
        navigator.safe_to_say.clone(),
        delivery.safe_to_say.clone(),
    ]);
    safe_to_say.push(
        "Model pack contains redacted, bounded context snippets for AI resume; source artifacts remain the evidence of record.".into(),
    );
    safe_to_say.sort();
    safe_to_say.dedup();
    let mut do_not_say = merge_many_sorted(vec![
        navigator.do_not_say.clone(),
        delivery.do_not_say.clone(),
    ]);
    do_not_say.push(
        "Do not treat model-pack snippets as proof that a command ran; verify source artifacts and completion-audit before making claims.".into(),
    );
    do_not_say.sort();
    do_not_say.dedup();

    let mut embedded_context = build_model_pack_context(&artifacts, options.max_chars)?;
    if embedded_context.is_empty() {
        blockers.push("model pack found no readable Autopilot context artifacts".into());
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    embedded_context.sort_by_key(|item| model_pack_context_rank(&item.id));

    let used_chars = embedded_context.iter().map(|item| item.chars).sum();
    let included_items = embedded_context.iter().filter(|item| item.included).count();
    let omitted_items = embedded_context.len().saturating_sub(included_items);
    let budget = ModelPackBudget {
        max_chars: options.max_chars,
        used_chars,
        included_items,
        omitted_items,
    };

    let mut next_actions = Vec::new();
    if let Some(action) = navigator.first_safe_action.clone() {
        next_actions.push(action);
    }
    next_actions.extend(delivery.next_actions.clone());
    next_actions.push(coach_action(
        8,
        "Refresh model pack",
        Some(format!(
            "rs autopilot model-pack {} --format json",
            command_arg(options.run_dir.to_string_lossy().as_ref())
        )),
        "Regenerate the compact AI context after any artifact changes.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);

    let status = if !blockers.is_empty() {
        "blocked"
    } else if delivery.complete {
        "readyForFinalReply"
    } else if navigator.first_safe_action.is_some() {
        "readyForNextSafeAction"
    } else {
        "readyForReview"
    }
    .to_string();
    let resume_prompt = build_model_pack_resume_prompt(
        &status,
        &options.run_dir,
        options.prompt.as_deref(),
        &navigator,
        &delivery,
        &embedded_context,
        &next_actions,
        &safe_to_say,
        &do_not_say,
    );
    let agent_brief = format!(
        "Model pack is {status}: embedded {included_items}/{} context item(s), used {used_chars}/{} chars, and selected {} next action(s).",
        embedded_context.len(),
        options.max_chars,
        next_actions.len()
    );

    Ok(ModelPackReport {
        schema_version: "rs.autopilot.model-pack.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        model_pack_path: model_pack_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        prompt: options.prompt.clone(),
        status,
        resume_prompt,
        required_read_order: navigator.read_order.clone(),
        embedded_context,
        budget,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
    })
}

fn build_model_pack_context(
    artifacts: &BTreeMap<String, String>,
    max_chars: usize,
) -> AppResult<Vec<ModelPackContextItem>> {
    let mut remaining = max_chars;
    let mut items = Vec::new();
    for (id, title) in model_pack_context_specs() {
        let Some(path) = artifacts.get(id) else {
            continue;
        };
        let value = match read_json_if_exists(Path::new(path))? {
            Some(value) => redact_json(&value),
            None => continue,
        };
        let serialized = serde_json::to_string_pretty(&value)?;
        let allowance = remaining.min(model_pack_item_limit(id));
        let (snippet, chars) = if allowance > 0 {
            let snippet = truncate_chars(&serialized, allowance);
            let chars = snippet.chars().count();
            remaining = remaining.saturating_sub(chars);
            (Some(snippet), chars)
        } else {
            (None, 0)
        };
        items.push(ModelPackContextItem {
            id: id.into(),
            title: title.into(),
            path: path.clone(),
            status: model_pack_string_field(&value, &["status"]),
            verdict: model_pack_string_field(&value, &["verdict", "sessionMode", "mode"]),
            summary: model_pack_summary(id, &value),
            next_command: model_pack_next_command(&value),
            included: snippet.is_some(),
            chars,
            snippet,
        });
    }
    Ok(items)
}

fn model_pack_context_specs() -> Vec<(&'static str, &'static str)> {
    vec![
        ("bestFriend", "AI Best-Friend Packet"),
        ("remember", "Remembered Creator Context"),
        ("orientation", "Cold-Start Orientation"),
        ("navigator", "AI Navigator"),
        ("delivery", "Creator Delivery"),
        ("completionAudit", "Completion Audit"),
        ("fulfillment", "Fulfillment Checklist"),
        ("closeout", "Closeout"),
        ("runbook", "Execution Runbook"),
        ("flightRecorder", "Flight Recorder"),
        ("capabilityAtlas", "Capability Atlas"),
        ("aiPlaybook", "AI Playbook"),
        ("cockpit", "AI Cockpit"),
        ("capsule", "Agent Capsule"),
        ("proof", "Proof Ledger"),
        ("acceptance", "Acceptance Scorecard"),
        ("privacy", "Privacy Scan"),
        ("decisions", "Creator Decisions"),
        ("alignment", "Decision Alignment"),
        ("journal", "AI Work Journal"),
        ("workOrder", "Work Order"),
        ("cycle", "AI Cycle"),
        ("diagnosis", "Diagnosis"),
        ("act", "Act Receipt"),
        ("loop", "Offline Loop"),
        ("conversation", "Conversation State"),
        ("feedback", "Feedback Triage"),
        ("feedbackPatch", "Feedback Patch"),
        ("plan", "Autopilot Plan"),
        ("bundle", "Bundle Manifest"),
        ("reviewPack", "Review Pack"),
        ("playtestPlan", "Playtest Plan"),
        ("evidenceReview", "Evidence Review"),
        ("repairPlan", "Repair Plan"),
    ]
}

fn model_pack_context_rank(id: &str) -> usize {
    model_pack_context_specs()
        .iter()
        .position(|(spec_id, _)| *spec_id == id)
        .unwrap_or(usize::MAX)
}

fn model_pack_item_limit(id: &str) -> usize {
    match id {
        "bestFriend" => 2800,
        "remember" => 2200,
        "orientation" | "navigator" | "delivery" => 2400,
        "completionAudit" | "runbook" | "flightRecorder" | "plan" => 2200,
        "capabilityAtlas" | "aiPlaybook" | "cockpit" => 1800,
        _ => 1400,
    }
}

fn model_pack_string_field(value: &Value, fields: &[&str]) -> Option<String> {
    fields.iter().find_map(|field| {
        value
            .get(*field)
            .and_then(Value::as_str)
            .map(str::to_string)
    })
}

fn model_pack_summary(id: &str, value: &Value) -> String {
    if let Some(summary) = model_pack_string_field(
        value,
        &[
            "agentBrief",
            "headline",
            "message",
            "resumePrompt",
            "modelPrompt",
            "modelTask",
        ],
    ) {
        return summarize_one_line(&summary, 240);
    }
    if id == "plan" {
        let prompt = value
            .get("request")
            .and_then(|request| request.get("prompt"))
            .and_then(Value::as_str)
            .unwrap_or("unknown prompt");
        let op_count = value
            .get("operations")
            .and_then(Value::as_array)
            .map_or(0, Vec::len);
        return format!("Plan for `{prompt}` with {op_count} operation(s).");
    }
    match value {
        Value::Object(map) => format!(
            "Readable JSON artifact with {} top-level field(s).",
            map.len()
        ),
        Value::Array(items) => format!("Readable JSON array with {} item(s).", items.len()),
        _ => "Readable JSON artifact.".into(),
    }
}

fn model_pack_next_command(value: &Value) -> Option<String> {
    value
        .get("nextCommand")
        .and_then(Value::as_str)
        .map(str::to_string)
        .or_else(|| {
            value
                .get("firstSafeAction")
                .and_then(|action| action.get("command"))
                .and_then(Value::as_str)
                .map(str::to_string)
        })
        .or_else(|| {
            value
                .get("nextActions")
                .and_then(Value::as_array)
                .and_then(|actions| actions.first())
                .and_then(|action| action.get("command"))
                .and_then(Value::as_str)
                .map(str::to_string)
        })
}

fn build_model_pack_resume_prompt(
    status: &str,
    run_dir: &Path,
    prompt: Option<&str>,
    navigator: &NavigatorReport,
    delivery: &DeliveryReport,
    context: &[ModelPackContextItem],
    next_actions: &[CoachAction],
    safe_to_say: &[String],
    do_not_say: &[String],
) -> String {
    let mut lines = Vec::new();
    lines.push("You are resuming Roblox Autopilot work from a model-pack artifact.".into());
    lines.push(format!("Run directory: {}", run_dir.to_string_lossy()));
    if let Some(prompt) = prompt {
        lines.push(format!("Creator objective: {prompt}"));
    }
    lines.push(format!("Model-pack status: {status}"));
    lines.push(format!("Navigator status: {}", navigator.status));
    lines.push(format!("Delivery status: {}", delivery.status));
    lines.push("Read embeddedContext first, then open source artifacts when a claim or command depends on exact evidence.".into());
    if let Some(action) = next_actions.first() {
        if let Some(command) = &action.command {
            lines.push(format!("First safe command: {command}"));
        }
    }
    if !safe_to_say.is_empty() {
        lines.push(format!("Safe claim to preserve: {}", safe_to_say[0]));
    }
    if !do_not_say.is_empty() {
        lines.push(format!("Forbidden claim to preserve: {}", do_not_say[0]));
    }
    lines.push(format!(
        "Embedded context items: {}. Snippets are redacted summaries; source JSON remains authoritative.",
        context.len()
    ));
    lines.join("\n")
}

fn summarize_one_line(text: &str, max_chars: usize) -> String {
    let normalized = text.split_whitespace().collect::<Vec<_>>().join(" ");
    truncate_chars(&normalized, max_chars)
}

fn truncate_chars(text: &str, max_chars: usize) -> String {
    if text.chars().count() <= max_chars {
        return text.to_string();
    }
    if max_chars == 0 {
        return String::new();
    }
    let suffix = "\n...<truncated>";
    let suffix_chars = suffix.chars().count();
    if max_chars <= suffix_chars {
        return suffix.chars().take(max_chars).collect();
    }
    let mut out = text
        .chars()
        .take(max_chars.saturating_sub(suffix_chars))
        .collect::<String>();
    out.push_str(suffix);
    out
}

fn build_task_pack_report(
    options: &TaskPackOptions,
    task_pack_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<TaskPackReport> {
    let write_markdown = markdown_path.is_some();
    let model_pack_path = options.run_dir.join("model-pack.json");
    let model_pack_markdown_path = write_markdown.then(|| options.run_dir.join("model-pack.md"));
    let model_options = ModelPackOptions {
        prompt: options.prompt.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        max_chars: options.max_chars,
        out: Some(model_pack_path.clone()),
        markdown: model_pack_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let model_pack = build_model_pack_report(
        &model_options,
        &model_pack_path,
        model_pack_markdown_path.as_deref(),
    )?;
    write_json(model_pack_path.clone(), &model_pack)?;
    if let Some(path) = model_pack_markdown_path {
        write_model_pack_markdown(path, &model_pack)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;

    let opportunities_path = options.run_dir.join("opportunities.json");
    let opportunities_markdown_path =
        write_markdown.then(|| options.run_dir.join("opportunities.md"));
    let opportunities_options = OpportunitiesOptions {
        prompt: options.prompt.clone(),
        run_dir: Some(options.run_dir.clone()),
        root: options.root.clone(),
        limit: options.limit,
        out: Some(opportunities_path.clone()),
        markdown: opportunities_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let opportunities = build_opportunities_report(
        &opportunities_options,
        &opportunities_path,
        opportunities_markdown_path.as_deref(),
    )?;
    write_json(opportunities_path.clone(), &opportunities)?;
    if let Some(path) = opportunities_markdown_path {
        write_opportunities_markdown(path, &opportunities)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;

    let work_order_path = options.run_dir.join("work-order.json");
    let work_order_markdown_path = write_markdown.then(|| options.run_dir.join("work-order.md"));
    let work_order_options = WorkOrderOptions {
        prompt: options.prompt.clone(),
        run_dir: Some(options.run_dir.clone()),
        opportunity: options.opportunity.clone(),
        root: options.root.clone(),
        limit: options.limit,
        out: Some(work_order_path.clone()),
        markdown: work_order_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let work_order = build_work_order_report(
        &work_order_options,
        &work_order_path,
        work_order_markdown_path.as_deref(),
        &opportunities,
    );
    write_json(work_order_path.clone(), &work_order)?;
    if let Some(path) = work_order_markdown_path {
        write_work_order_markdown(path, &work_order)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;

    let primary_step = work_order
        .execution_steps
        .iter()
        .find(|step| step.command.is_some());
    let primary_command = primary_step.and_then(|step| step.command.clone());
    let requires_live = primary_step.is_some_and(|step| step.requires_live_studio);
    let mutates_studio = primary_step.is_some_and(|step| step.mutates_studio);
    let task_title = work_order
        .opportunity
        .as_ref()
        .map(|opportunity| opportunity.title.clone())
        .or_else(|| primary_step.map(|step| step.title.clone()))
        .unwrap_or_else(|| "Select an executable Autopilot task".into());

    let mut blockers = work_order.blockers.clone();
    blockers.extend(
        model_pack
            .blockers
            .iter()
            .filter(|blocker| {
                let lower = blocker.to_ascii_lowercase();
                lower.contains("secret") || lower.contains("privacy")
            })
            .cloned(),
    );
    if primary_command.is_none() {
        blockers.push("task pack could not identify a primary executable command".into());
    }
    if mutates_studio {
        blockers.push("primary command mutates Studio; task pack cannot authorize mutation".into());
    }
    blockers.sort();
    blockers.dedup();

    let mut warnings = merge_many_sorted(vec![
        model_pack.warnings.clone(),
        work_order.warnings.clone(),
    ]);
    if requires_live {
        warnings.push(
            "primary command requires live Studio readiness; stop if setup/ready evidence is missing"
                .into(),
        );
    }
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else if requires_live {
        "gatedLiveTask"
    } else {
        "readyForAgentTask"
    }
    .to_string();
    let mut allowed_commands = primary_command.iter().cloned().collect::<Vec<_>>();
    allowed_commands.extend(work_order.validation_commands.clone());
    allowed_commands.push(format!(
        "rs autopilot task-pack {} --format json",
        command_arg(options.run_dir.to_string_lossy().as_ref())
    ));
    allowed_commands.sort();
    allowed_commands.dedup();

    let expected_artifacts = work_order.expected_artifacts.clone();
    let acceptance_checks = build_task_pack_acceptance_checks(&expected_artifacts, &work_order);
    let mut stop_conditions = work_order.stop_conditions.clone();
    stop_conditions.push(
        "stop if any command tries to apply, publish, upload, install plugins, or mutate Studio without explicit approval gates".into(),
    );
    stop_conditions.push(
        "stop before telling the creator the task is done unless task validation and claim-check both support the exact wording".into(),
    );
    stop_conditions.sort();
    stop_conditions.dedup();

    let mut safe_to_say = merge_many_sorted(vec![
        model_pack.safe_to_say.clone(),
        work_order.safe_to_say.clone(),
    ]);
    safe_to_say.push(
        "Task pack prepared an evidence-bound agent task; source artifacts remain authoritative."
            .into(),
    );
    safe_to_say.sort();
    safe_to_say.dedup();
    let mut do_not_say = merge_many_sorted(vec![
        model_pack.do_not_say.clone(),
        work_order.do_not_say.clone(),
    ]);
    do_not_say
        .push("Do not treat task-pack instructions as proof that the task was executed.".into());
    do_not_say.sort();
    do_not_say.dedup();

    let mut artifacts = model_pack.artifacts.clone();
    artifacts.extend(work_order.artifacts.clone());
    artifacts.insert(
        "taskPack".into(),
        task_pack_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "taskPackMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert("modelPack".into(), model_pack.model_pack_path.clone());
    artifacts.insert("workOrder".into(), work_order.work_order_path.clone());
    artifacts.insert("opportunities".into(), opportunities.opportunities_path);

    let mut next_actions = Vec::new();
    if let Some(command) = &primary_command {
        next_actions.push(coach_action(
            1,
            &task_title,
            Some(command.clone()),
            "Execute the primary command only if stop conditions are clear.",
            requires_live,
            mutates_studio,
        ));
    }
    for (index, command) in work_order.validation_commands.iter().take(4).enumerate() {
        next_actions.push(coach_action(
            (index + 20) as u8,
            "Validate task result",
            Some(command.clone()),
            "Validate artifacts before reporting progress.",
            false,
            false,
        ));
    }
    next_actions.push(coach_action(
        90,
        "Refresh task pack",
        Some(format!(
            "rs autopilot task-pack {} --format json",
            command_arg(options.run_dir.to_string_lossy().as_ref())
        )),
        "Regenerate the task prompt after running or validating the task.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);

    let objective = format!(
        "{} Use the model pack for context and the work order for proof requirements.",
        work_order.objective
    );
    let task_prompt = build_task_pack_prompt(
        &status,
        &task_title,
        &objective,
        &options.run_dir,
        &model_pack,
        &work_order,
        &allowed_commands,
        &acceptance_checks,
        &stop_conditions,
        &safe_to_say,
        &do_not_say,
    );
    let agent_brief = format!(
        "Task pack is {status}: primary command `{}`, {} validation command(s), {} expected artifact(s).",
        primary_command.as_deref().unwrap_or("<none>"),
        work_order.validation_commands.len(),
        expected_artifacts.len()
    );

    Ok(TaskPackReport {
        schema_version: "rs.autopilot.task-pack.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        task_pack_path: task_pack_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        prompt: options.prompt.clone(),
        status,
        task_title,
        objective,
        task_prompt,
        primary_command,
        allowed_commands,
        validation_commands: work_order.validation_commands.clone(),
        expected_artifacts,
        acceptance_checks,
        stop_conditions,
        required_context: model_pack.required_read_order.clone(),
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        model_pack,
        work_order,
    })
}

fn build_best_friend_report(
    options: &BestFriendOptions,
    best_friend_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<BestFriendReport> {
    build_best_friend_report_with_remember(options, best_friend_path, markdown_path, None)
}

fn build_best_friend_report_with_remember(
    options: &BestFriendOptions,
    best_friend_path: &Path,
    markdown_path: Option<&Path>,
    prebuilt_remember: Option<RememberReport>,
) -> AppResult<BestFriendReport> {
    let write_markdown = markdown_path.is_some();

    let remember_path = options.run_dir.join("remember.json");
    let remember_markdown_path = write_markdown.then(|| options.run_dir.join("remember.md"));
    let remember = if let Some(remember) = prebuilt_remember {
        remember
    } else {
        let remember_options = RememberOptions {
            run_dir: options.run_dir.clone(),
            root: options.root.clone(),
            limit: options.limit,
            best_friend: false,
            opportunity: None,
            max_chars: options.max_chars,
            out: Some(remember_path.clone()),
            markdown: remember_markdown_path.clone(),
            no_markdown: !write_markdown,
            json: false,
        };
        let remember = build_remember_report(
            &remember_options,
            &remember_path,
            remember_markdown_path.as_deref(),
        )?;
        write_json(remember_path.clone(), &remember)?;
        if let Some(path) = remember_markdown_path {
            write_remember_markdown(path, &remember)?;
        }
        remember
    };

    let task_pack_path = options.run_dir.join("task-pack.json");
    let task_pack_markdown_path = write_markdown.then(|| options.run_dir.join("task-pack.md"));
    let task_options = TaskPackOptions {
        prompt: options.prompt.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        opportunity: options.opportunity.clone(),
        max_chars: options.max_chars,
        out: Some(task_pack_path.clone()),
        markdown: task_pack_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let task_pack = build_task_pack_report(
        &task_options,
        &task_pack_path,
        task_pack_markdown_path.as_deref(),
    )?;
    write_json(task_pack_path.clone(), &task_pack)?;
    if let Some(path) = task_pack_markdown_path {
        write_task_pack_markdown(path, &task_pack)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;

    let mut artifacts = remember.artifacts.clone();
    artifacts.extend(task_pack.artifacts.clone());
    artifacts.insert(
        "bestFriend".into(),
        best_friend_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "bestFriendMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert("remember".into(), remember.remember_path.clone());
    artifacts.insert("taskPack".into(), task_pack.task_pack_path.clone());
    artifacts.insert(
        "modelPack".into(),
        task_pack.model_pack.model_pack_path.clone(),
    );

    let mut blockers =
        merge_many_sorted(vec![remember.blockers.clone(), task_pack.blockers.clone()]);
    let mut warnings =
        merge_many_sorted(vec![remember.warnings.clone(), task_pack.warnings.clone()]);
    warnings.push(
        "best-friend packet is AI operating context only; proof and live mutation gates remain separate"
            .into(),
    );
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let mut safe_to_say = merge_many_sorted(vec![
        remember.safe_to_say.clone(),
        task_pack.safe_to_say.clone(),
    ]);
    safe_to_say.push(
        "Best-friend packet refreshed remembered context and prepared one evidence-bound AI task surface."
            .into(),
    );
    safe_to_say.sort();
    safe_to_say.dedup();
    let mut do_not_say = merge_many_sorted(vec![
        remember.do_not_say.clone(),
        task_pack.do_not_say.clone(),
    ]);
    do_not_say.push(
        "Do not treat best-friend.json as proof that the next task was executed or that Studio changed."
            .into(),
    );
    do_not_say.push(
        "Do not skip source artifacts, validation commands, claim-check, approval, live-gate, or rollback proof because this packet exists."
            .into(),
    );
    do_not_say.sort();
    do_not_say.dedup();

    let first_safe_action = task_pack
        .next_actions
        .iter()
        .find(|action| !action.requires_live_studio && !action.mutates_studio)
        .cloned()
        .or_else(|| task_pack.model_pack.next_actions.first().cloned());
    let first_act_action = first_safe_action
        .as_ref()
        .and_then(|action| action.command.as_deref())
        .and_then(|command| {
            act_wrapper_action_for_command(
                &options.run_dir,
                command,
                1,
                "Execute first checked action through act",
                "Use the internal offline dispatcher for the first checked action, then refresh best-friend before continuing.",
            )
        });

    let launch_preflight_path = options.run_dir.join("best-friend-self-check.json");
    let launch_preflight_markdown_path =
        write_markdown.then(|| options.run_dir.join("best-friend-self-check.md"));
    let opening_reply_claim = build_best_friend_opening_reply_claim(&task_pack, &safe_to_say);
    let launch_preflight_claims = vec![opening_reply_claim.clone()];
    let launch_preflight_commands = first_safe_action
        .as_ref()
        .and_then(|action| action.command.clone())
        .into_iter()
        .collect::<Vec<_>>();
    let launch_preflight_options = SelfCheckOptions {
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        claims: launch_preflight_claims,
        messages: Vec::new(),
        commands: launch_preflight_commands,
        from_file: None,
        out: Some(launch_preflight_path.clone()),
        markdown: launch_preflight_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let launch_preflight = build_self_check_report(
        &launch_preflight_options,
        &launch_preflight_path,
        launch_preflight_markdown_path.as_deref(),
    )?;
    write_self_check_child_artifacts(&launch_preflight, write_markdown)?;
    write_json(launch_preflight_path.clone(), &launch_preflight)?;
    if let Some(path) = launch_preflight_markdown_path.clone() {
        write_self_check_markdown(path, &launch_preflight)?;
    }

    artifacts.insert(
        "bestFriendSelfCheck".into(),
        launch_preflight.self_check_path.clone(),
    );
    if let Some(path) = &launch_preflight.markdown_path {
        artifacts.insert("bestFriendSelfCheckMarkdown".into(), path.clone());
    }
    artifacts.extend(launch_preflight.artifacts.clone());

    if !launch_preflight.safe_to_proceed {
        blockers.push(format!(
            "best-friend launch preflight is {}",
            launch_preflight.status
        ));
        blockers.extend(launch_preflight.blockers.iter().cloned());
    }
    warnings.extend(launch_preflight.warnings.iter().cloned());
    safe_to_say.extend(launch_preflight.safe_to_say.iter().cloned());
    do_not_say.extend(launch_preflight.do_not_say.iter().cloned());
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();

    let relationship_mode = if blockers.is_empty() {
        "contextAwareBuildCompanion"
    } else {
        "blockedCompanion"
    }
    .to_string();
    let status = if !blockers.is_empty() {
        "blocked"
    } else if task_pack.status == "readyForAgentTask" {
        "readyForAgentTask"
    } else if task_pack.status == "gatedLiveTask" {
        "gatedLiveTask"
    } else {
        "readyForReview"
    }
    .to_string();

    let context_cards =
        build_best_friend_context_cards(&remember, &task_pack, &launch_preflight, &artifacts);
    let companion_contract = build_best_friend_contract(&options.run_dir, &task_pack);
    let mut next_actions = Vec::new();
    if let Some(action) = first_act_action.clone() {
        next_actions.push(action);
    } else if let Some(action) = first_safe_action.clone() {
        next_actions.push(action);
    }
    next_actions.push(coach_action(
        80,
        "Refresh best-friend packet",
        Some(format!(
            "rs autopilot best-friend {} --root {} --limit {} --format json",
            command_arg(options.run_dir.to_string_lossy().as_ref()),
            command_arg(options.root.to_string_lossy().as_ref()),
            options.limit
        )),
        "Regenerate the launch packet after any context, task, or evidence changes.",
        false,
        false,
    ));
    next_actions.push(coach_action(
        90,
        "Orient from refreshed context",
        Some(format!(
            "rs autopilot orient --run-dir {} --root {} --limit {} --format json",
            command_arg(options.run_dir.to_string_lossy().as_ref()),
            command_arg(options.root.to_string_lossy().as_ref()),
            options.limit
        )),
        "Load the refreshed read order before a new AI session starts work.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);

    let opening_prompt = build_best_friend_opening_prompt(
        &status,
        &options.run_dir,
        &remember,
        &task_pack,
        &context_cards,
        &companion_contract,
        &safe_to_say,
        &do_not_say,
        first_safe_action.as_ref(),
        first_act_action.as_ref(),
    );
    let opening_reply = build_best_friend_opening_reply(
        &opening_reply_claim,
        first_safe_action.as_ref(),
        first_act_action.as_ref(),
        &launch_preflight,
        &status,
    );
    let agent_brief = format!(
        "Best-friend packet is {status}: remembered context `{}`, model pack `{}`, task pack `{}`, launch preflight `{}`, and first safe action `{}`.",
        remember.status,
        task_pack.model_pack.status,
        task_pack.status,
        launch_preflight.status,
        first_safe_action
            .as_ref()
            .and_then(|action| action.command.as_deref())
            .unwrap_or("<none>")
    );

    Ok(BestFriendReport {
        schema_version: "rs.autopilot.best-friend.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        root: options.root.to_string_lossy().to_string(),
        best_friend_path: best_friend_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        relationship_mode,
        remembered_status: remember.status.clone(),
        model_pack_status: task_pack.model_pack.status.clone(),
        task_pack_status: task_pack.status.clone(),
        launch_preflight_status: launch_preflight.status.clone(),
        first_safe_action,
        first_act_action,
        opening_prompt,
        opening_reply,
        opening_reply_claim,
        companion_contract,
        required_read_order: task_pack.required_context.clone(),
        context_cards,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        remember,
        task_pack,
        launch_preflight,
    })
}

fn build_best_friend_check_report(
    options: &BestFriendCheckOptions,
    check_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<BestFriendCheckReport> {
    let write_markdown = markdown_path.is_some();
    let best_friend_path = options.run_dir.join("best-friend.json");
    let best_friend_markdown_path = write_markdown.then(|| options.run_dir.join("best-friend.md"));
    let best_friend_options = BestFriendOptions {
        prompt: options.prompt.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        opportunity: options.opportunity.clone(),
        max_chars: options.max_chars,
        out: Some(best_friend_path.clone()),
        markdown: best_friend_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let best_friend = build_best_friend_report(
        &best_friend_options,
        &best_friend_path,
        best_friend_markdown_path.as_deref(),
    )?;
    write_json(best_friend_path.clone(), &best_friend)?;
    if let Some(path) = best_friend_markdown_path {
        write_best_friend_markdown(path, &best_friend)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;

    let run_arg = command_arg(options.run_dir.to_string_lossy().as_ref());
    let root_arg = command_arg(options.root.to_string_lossy().as_ref());
    let best_friend_command = format!(
        "rs autopilot best-friend {run_arg} --root {root_arg} --limit {} --format json",
        options.limit
    );
    let remember_command =
        format!("rs autopilot remember {run_arg} --root {root_arg} --best-friend --format json");
    let publish_review_command = format!(
        "rs autopilot publish-review {run_arg} --best-friend {} --format json",
        command_arg(best_friend_path.to_string_lossy().as_ref())
    );

    let studio_review_path = options.run_dir.join("studio-review.json");
    let studio_review_value = read_json_if_exists(&studio_review_path)?;
    let studio_review_best_friend_visible = studio_review_value
        .as_ref()
        .and_then(|value| value.get("panelPayload"))
        .and_then(|payload| string_field(payload, "bestFriendStatus"))
        .is_some();

    let first_safe_action_ready = best_friend
        .first_safe_action
        .as_ref()
        .is_some_and(|action| !action.requires_live_studio && !action.mutates_studio);
    let protected_action_ready = best_friend
        .first_act_action
        .as_ref()
        .and_then(|action| action.command.as_deref())
        .is_some();
    let launch_preflight_ready = best_friend.launch_preflight.safe_to_proceed
        && best_friend.launch_preflight.commands_safe_offline
        && best_friend.launch_preflight.speak_ready;
    let read_order_ready = !best_friend.required_read_order.is_empty()
        && best_friend
            .required_read_order
            .iter()
            .filter(|item| item.required)
            .all(|item| item.exists);
    let memory_artifact_ids = ["memory", "creatorPreferences", "gameBible", "aiPlaybook"];
    let memory_ready = memory_artifact_ids.iter().all(|id| {
        best_friend
            .remember
            .consolidated_artifacts
            .iter()
            .find(|artifact| artifact.id == *id)
            .is_some_and(|artifact| {
                artifact.status != "blocked" && PathBuf::from(&artifact.path).exists()
            })
    });
    let source_artifacts_ready = [
        "bestFriend",
        "remember",
        "taskPack",
        "modelPack",
        "bestFriendSelfCheck",
    ]
    .iter()
    .all(|key| best_friend.artifacts.contains_key(*key));
    let opening_reply_ready = !best_friend.opening_reply.trim().is_empty();

    let mut checklist = vec![
        best_friend_check_item(
            "runDir",
            "Run Directory Exists",
            options.run_dir.is_dir(),
            "required",
            vec![options.run_dir.to_string_lossy().to_string()],
            Some(best_friend_command.clone()),
        ),
        best_friend_check_item(
            "bestFriend",
            "Best-Friend Packet Ready",
            best_friend.blockers.is_empty() && best_friend.status != "blocked",
            "required",
            vec![
                format!("status={}", best_friend.status),
                best_friend.best_friend_path.clone(),
            ],
            Some(best_friend_command.clone()),
        ),
        best_friend_check_item(
            "launchPreflight",
            "Launch Preflight Safe",
            launch_preflight_ready,
            "required",
            vec![
                format!("status={}", best_friend.launch_preflight.status),
                format!(
                    "safeToProceed={}",
                    best_friend.launch_preflight.safe_to_proceed
                ),
                format!("speakReady={}", best_friend.launch_preflight.speak_ready),
                format!(
                    "commandsSafeOffline={}",
                    best_friend.launch_preflight.commands_safe_offline
                ),
            ],
            Some(best_friend_command.clone()),
        ),
        best_friend_check_item(
            "protectedAction",
            "Protected First Action Available",
            protected_action_ready,
            "required",
            best_friend
                .first_act_action
                .as_ref()
                .and_then(|action| action.command.clone())
                .into_iter()
                .collect(),
            Some(best_friend_command.clone()),
        ),
        best_friend_check_item(
            "firstActionBoundary",
            "First Action Is Offline And Non-Mutating",
            first_safe_action_ready,
            "required",
            best_friend
                .first_safe_action
                .as_ref()
                .map(|action| {
                    vec![
                        format!("requiresLiveStudio={}", action.requires_live_studio),
                        format!("mutatesStudio={}", action.mutates_studio),
                    ]
                })
                .unwrap_or_else(|| vec!["no first safe action".into()]),
            Some(best_friend_command.clone()),
        ),
        best_friend_check_item(
            "memory",
            "Durable Memory Context Loaded",
            memory_ready,
            "required",
            best_friend
                .remember
                .consolidated_artifacts
                .iter()
                .map(|artifact| format!("{}={}", artifact.id, artifact.status))
                .collect(),
            Some(remember_command.clone()),
        ),
        best_friend_check_item(
            "readOrder",
            "Required Read Order Exists",
            read_order_ready,
            "required",
            best_friend
                .required_read_order
                .iter()
                .map(|item| format!("{} exists={}", item.path, item.exists))
                .collect(),
            Some(best_friend_command.clone()),
        ),
        best_friend_check_item(
            "sourceArtifacts",
            "Source Artifacts Linked",
            source_artifacts_ready,
            "required",
            best_friend.artifacts.keys().cloned().collect(),
            Some(best_friend_command.clone()),
        ),
        best_friend_check_item(
            "openingReply",
            "Opening Reply Is Checked",
            opening_reply_ready && launch_preflight_ready,
            "required",
            vec![best_friend.opening_reply_claim.clone()],
            Some(best_friend_command.clone()),
        ),
        best_friend_check_item(
            "studioReview",
            "Studio Panel Can Show Best-Friend Context",
            studio_review_best_friend_visible,
            "recommended",
            vec![studio_review_path.to_string_lossy().to_string()],
            Some(publish_review_command.clone()),
        ),
    ];

    let mut blockers = best_friend
        .blockers
        .iter()
        .map(|blocker| format!("best-friend: {blocker}"))
        .collect::<Vec<_>>();
    let mut warnings = best_friend.warnings.clone();
    for item in &checklist {
        if item.status == "blocked" {
            blockers.push(format!("{} is not ready", item.title));
        } else if item.status == "warning" {
            warnings.push(format!("{} is not visible yet", item.title));
        }
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let mut safe_to_say = best_friend.safe_to_say.clone();
    safe_to_say.push(
        "Best-friend launch control checked the packet, preflight, read order, memory, and protected first action."
            .into(),
    );
    safe_to_say.sort();
    safe_to_say.dedup();
    let mut do_not_say = best_friend.do_not_say.clone();
    do_not_say.push(
        "Do not claim best-friend-check executed the first action; it only audited launch readiness."
            .into(),
    );
    do_not_say.push(
        "Do not claim the Studio panel shows best-friend context unless studioReview is ready or publish-review succeeded."
            .into(),
    );
    do_not_say.sort();
    do_not_say.dedup();

    let ready_to_operate = blockers.is_empty();
    let status = if !ready_to_operate {
        "blocked"
    } else if warnings.is_empty() {
        "readyToOperate"
    } else {
        "readyWithWarnings"
    }
    .to_string();
    let verdict = if ready_to_operate {
        "freshAiCanStart"
    } else {
        "repairLaunchBeforeActing"
    }
    .to_string();

    let mut artifacts = best_friend.artifacts.clone();
    artifacts.insert(
        "bestFriendCheck".into(),
        check_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "bestFriendCheckMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert("bestFriend".into(), best_friend.best_friend_path.clone());
    if studio_review_path.exists() {
        artifacts.insert(
            "studioReview".into(),
            studio_review_path.to_string_lossy().to_string(),
        );
    }

    let mut next_actions = Vec::new();
    if ready_to_operate {
        if let Some(action) = best_friend.first_act_action.clone() {
            next_actions.push(coach_action(
                1,
                "Execute protected best-friend action",
                action.command,
                "Launch control is ready; run the protected action only through act, then refresh the check.",
                false,
                false,
            ));
        }
    } else {
        next_actions.push(coach_action(
            1,
            "Repair best-friend launch packet",
            Some(best_friend_command.clone()),
            "Refresh the source launch packet and embedded preflight before any AI action.",
            false,
            false,
        ));
    }
    if !memory_ready {
        next_actions.push(coach_action(
            5,
            "Refresh remembered context and launch packet",
            Some(remember_command),
            "Regenerate durable memory and the best-friend packet in one non-mutating receipt.",
            false,
            false,
        ));
    }
    if !studio_review_best_friend_visible {
        next_actions.push(coach_action(
            70,
            "Publish best-friend context to Studio panel",
            Some(publish_review_command),
            "Show the same launch context in Studio when a connected panel is available.",
            true,
            false,
        ));
    }
    next_actions.push(coach_action(
        90,
        "Refresh best-friend launch control",
        Some(format!(
            "rs autopilot best-friend-check {run_arg} --root {root_arg} --limit {} --format json",
            options.limit
        )),
        "Rerun launch control after any memory, packet, or Studio review change.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);

    let launch_control_prompt = build_best_friend_check_prompt(
        &status,
        &verdict,
        &best_friend,
        &checklist,
        &safe_to_say,
        &do_not_say,
        &blockers,
    );
    let agent_brief = format!(
        "Best-friend launch control is {status}: {} checklist item(s), {} blocker(s), {} warning(s), protected action ready={}, Studio panel visible={}.",
        checklist.len(),
        blockers.len(),
        warnings.len(),
        protected_action_ready,
        studio_review_best_friend_visible
    );
    checklist.sort_by(|left, right| left.id.cmp(&right.id));

    Ok(BestFriendCheckReport {
        schema_version: "rs.autopilot.best-friend-check.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        root: options.root.to_string_lossy().to_string(),
        check_path: check_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict,
        ready_to_operate,
        best_friend_status: best_friend.status.clone(),
        launch_preflight_status: best_friend.launch_preflight_status.clone(),
        protected_action_ready,
        studio_review_best_friend_visible,
        studio_review_path: studio_review_path
            .exists()
            .then(|| studio_review_path.to_string_lossy().to_string()),
        launch_control_prompt,
        opening_reply: best_friend.opening_reply.clone(),
        first_safe_action: best_friend.first_safe_action.clone(),
        first_act_action: best_friend.first_act_action.clone(),
        required_read_order: best_friend.required_read_order.clone(),
        checklist,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        best_friend,
    })
}

fn best_friend_check_item(
    id: &str,
    title: &str,
    ready: bool,
    severity: &str,
    evidence: Vec<String>,
    repair_command: Option<String>,
) -> BestFriendCheckItem {
    let status = if ready {
        "ready"
    } else if severity == "recommended" {
        "warning"
    } else {
        "blocked"
    };
    BestFriendCheckItem {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        severity: severity.into(),
        ready,
        evidence,
        repair_command,
    }
}

fn build_best_friend_check_prompt(
    status: &str,
    verdict: &str,
    best_friend: &BestFriendReport,
    checklist: &[BestFriendCheckItem],
    safe_to_say: &[String],
    do_not_say: &[String],
    blockers: &[String],
) -> String {
    let mut lines = vec![
        "You are the AI build companion for this Roblox project.".into(),
        format!("Launch-control status: {status}; verdict: {verdict}."),
        format!("Run directory: {}", best_friend.run_dir),
        "Read the required read order before acting; source artifacts are authoritative over this prompt.".into(),
    ];
    if blockers.is_empty() {
        lines.push("You may start with the protected first action below, then refresh best-friend-check before reporting progress.".into());
    } else {
        lines.push(
            "Do not run the first action yet. Repair the blocked checklist items first.".into(),
        );
    }
    if let Some(action) = &best_friend.first_act_action {
        if let Some(command) = &action.command {
            lines.push(format!("Protected first action: {command}"));
        }
    }
    if !best_friend.opening_reply.trim().is_empty() {
        lines.push(format!(
            "Checked opening reply: {}",
            best_friend.opening_reply
        ));
    }
    lines.push("Checklist:".into());
    for item in checklist {
        lines.push(format!(
            "- {}: {} ({})",
            item.title, item.status, item.severity
        ));
    }
    if let Some(claim) = safe_to_say.first() {
        lines.push(format!("Safe claim: {claim}"));
    }
    if let Some(claim) = do_not_say.first() {
        lines.push(format!("Forbidden claim: {claim}"));
    }
    lines.join("\n")
}

fn build_best_friend_rescue_report(
    options: &BestFriendRescueOptions,
    rescue_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<BestFriendRescueReport> {
    let write_markdown = markdown_path.is_some();
    let check_path = options.run_dir.join("best-friend-check.json");
    let check_markdown_path = write_markdown.then(|| options.run_dir.join("best-friend-check.md"));
    let check_options = BestFriendCheckOptions {
        prompt: options.prompt.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        opportunity: options.opportunity.clone(),
        max_chars: options.max_chars,
        out: Some(check_path.clone()),
        markdown: check_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let best_friend_check = build_best_friend_check_report(
        &check_options,
        &check_path,
        check_markdown_path.as_deref(),
    )?;
    write_json(check_path.clone(), &best_friend_check)?;
    if let Some(path) = check_markdown_path {
        write_best_friend_check_markdown(path, &best_friend_check)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;

    let has_failure_input = options
        .command
        .as_deref()
        .is_some_and(|value| !value.trim().is_empty())
        || options
            .result
            .as_deref()
            .is_some_and(|value| !value.trim().is_empty())
        || options.errors.iter().any(|value| !value.trim().is_empty())
        || options
            .evidence
            .iter()
            .any(|value| !value.trim().is_empty());
    let diagnosis = if has_failure_input {
        let diagnosis_path = options.run_dir.join("best-friend-rescue-diagnosis.json");
        let diagnosis_markdown_path =
            write_markdown.then(|| options.run_dir.join("best-friend-rescue-diagnosis.md"));
        let diagnosis_options = DiagnoseOptions {
            run_dir: options.run_dir.clone(),
            command: options.command.clone(),
            result: options.result.clone(),
            errors: options.errors.clone(),
            evidence: options.evidence.clone(),
            out: Some(diagnosis_path.clone()),
            markdown: diagnosis_markdown_path.clone(),
            no_markdown: !write_markdown,
            json: false,
        };
        let report = build_diagnosis_report(
            &diagnosis_options,
            &diagnosis_path,
            diagnosis_markdown_path.as_deref(),
        )?;
        write_json(diagnosis_path.clone(), &report)?;
        if let Some(path) = diagnosis_markdown_path {
            write_diagnosis_markdown(path, &report)?;
        }
        Some(report)
    } else {
        None
    };

    let diagnosis_status = diagnosis.as_ref().map(|report| report.status.clone());
    let mut blockers = best_friend_check
        .blockers
        .iter()
        .map(|blocker| format!("launch-control: {blocker}"))
        .collect::<Vec<_>>();
    let mut warnings = best_friend_check.warnings.clone();
    if let Some(diagnosis) = &diagnosis {
        blockers.extend(
            diagnosis
                .blockers
                .iter()
                .map(|blocker| format!("diagnosis: {blocker}")),
        );
        warnings.extend(
            diagnosis
                .warnings
                .iter()
                .map(|warning| format!("diagnosis: {warning}")),
        );
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let selected_repair = diagnosis
        .as_ref()
        .and_then(|report| report.next_actions.first().cloned())
        .or_else(|| {
            if !best_friend_check.ready_to_operate {
                best_friend_check.next_actions.first().cloned()
            } else {
                best_friend_check
                    .next_actions
                    .iter()
                    .find(|action| !action.requires_live_studio && !action.mutates_studio)
                    .cloned()
            }
        });
    let rescue_mode = if diagnosis
        .as_ref()
        .is_some_and(|report| report.status != "clear")
    {
        "failureRecovery"
    } else if !best_friend_check.ready_to_operate {
        "launchRepair"
    } else {
        "continueSafely"
    }
    .to_string();
    let status = if !blockers.is_empty() {
        "repairRequired"
    } else if !warnings.is_empty() {
        "readyWithWarnings"
    } else {
        "readyToResume"
    }
    .to_string();

    let checked_message = build_best_friend_rescue_message(
        &status,
        &rescue_mode,
        &best_friend_check,
        diagnosis.as_ref(),
        selected_repair.as_ref(),
    );
    let self_check_path = options.run_dir.join("best-friend-rescue-self-check.json");
    let self_check_markdown_path =
        write_markdown.then(|| options.run_dir.join("best-friend-rescue-self-check.md"));
    let self_check_options = SelfCheckOptions {
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        claims: vec![checked_message.clone()],
        messages: Vec::new(),
        commands: Vec::new(),
        from_file: None,
        out: Some(self_check_path.clone()),
        markdown: self_check_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let message_self_check = build_self_check_report(
        &self_check_options,
        &self_check_path,
        self_check_markdown_path.as_deref(),
    )?;
    write_self_check_child_artifacts(&message_self_check, write_markdown)?;
    write_json(self_check_path.clone(), &message_self_check)?;
    if let Some(path) = self_check_markdown_path {
        write_self_check_markdown(path, &message_self_check)?;
    }

    let mut safe_to_say = merge_many_sorted(vec![
        best_friend_check.safe_to_say.clone(),
        diagnosis
            .as_ref()
            .map(|report| report.safe_to_say.clone())
            .unwrap_or_default(),
        message_self_check.safe_to_say.clone(),
    ]);
    safe_to_say.push(
        "Best-friend rescue selected a recovery route without executing the repair command.".into(),
    );
    safe_to_say.sort();
    safe_to_say.dedup();
    let mut do_not_say = merge_many_sorted(vec![
        best_friend_check.do_not_say.clone(),
        diagnosis
            .as_ref()
            .map(|report| report.do_not_say.clone())
            .unwrap_or_default(),
        message_self_check.do_not_say.clone(),
    ]);
    do_not_say.push(
        "Do not claim best-friend-rescue fixed the blocker; it only diagnosed and prepared the next recovery route.".into(),
    );
    do_not_say.sort();
    do_not_say.dedup();

    let mut artifacts = best_friend_check.artifacts.clone();
    artifacts.insert(
        "bestFriendRescue".into(),
        rescue_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "bestFriendRescueMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert(
        "bestFriendCheck".into(),
        best_friend_check.check_path.clone(),
    );
    artifacts.insert(
        "bestFriendRescueSelfCheck".into(),
        message_self_check.self_check_path.clone(),
    );
    if let Some(path) = &message_self_check.markdown_path {
        artifacts.insert("bestFriendRescueSelfCheckMarkdown".into(), path.clone());
    }
    artifacts.extend(message_self_check.artifacts.clone());
    if let Some(diagnosis) = &diagnosis {
        artifacts.insert(
            "bestFriendRescueDiagnosis".into(),
            diagnosis.diagnosis_path.clone(),
        );
        artifacts.extend(diagnosis.artifacts.clone());
    }

    if !message_self_check.safe_to_proceed {
        blockers.push(format!(
            "rescue message self-check is {}",
            message_self_check.status
        ));
        blockers.extend(message_self_check.blockers.iter().cloned());
        blockers.sort();
        blockers.dedup();
    }
    warnings.extend(message_self_check.warnings.iter().cloned());
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() {
        "repairRequired"
    } else if !warnings.is_empty() {
        "readyWithWarnings"
    } else {
        "readyToResume"
    }
    .to_string();
    let verdict = match status.as_str() {
        "readyToResume" | "readyWithWarnings" => "resumeWithSelectedRepair",
        _ => "repairBeforeReporting",
    }
    .to_string();

    let mut next_actions = Vec::new();
    if let Some(action) = selected_repair.clone() {
        next_actions.push(action);
    }
    next_actions.push(coach_action(
        80,
        "Refresh best-friend rescue",
        Some(format!(
            "rs autopilot best-friend-rescue {} --root {} --limit {} --format json",
            command_arg(options.run_dir.to_string_lossy().as_ref()),
            command_arg(options.root.to_string_lossy().as_ref()),
            options.limit
        )),
        "Rerun rescue after attempting the selected recovery route or collecting new evidence.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);

    let rescue_prompt = build_best_friend_rescue_prompt(
        &status,
        &verdict,
        &rescue_mode,
        selected_repair.as_ref(),
        &blockers,
        &warnings,
        &checked_message,
    );
    let agent_brief = format!(
        "Best-friend rescue is {status}: mode={rescue_mode}, launch-control={}, diagnosis={}, self-check={}, selected repair `{}`.",
        best_friend_check.status,
        diagnosis_status.as_deref().unwrap_or("notRequested"),
        message_self_check.status,
        selected_repair
            .as_ref()
            .and_then(|action| action.command.as_deref())
            .unwrap_or("<none>")
    );

    Ok(BestFriendRescueReport {
        schema_version: "rs.autopilot.best-friend-rescue.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        root: options.root.to_string_lossy().to_string(),
        rescue_path: rescue_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict,
        rescue_mode,
        best_friend_check_status: best_friend_check.status.clone(),
        diagnosis_status,
        selected_repair,
        rescue_prompt,
        checked_message,
        message_self_check_status: message_self_check.status.clone(),
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        best_friend_check,
        diagnosis,
        message_self_check,
    })
}

fn build_best_friend_rescue_message(
    _status: &str,
    _rescue_mode: &str,
    check: &BestFriendCheckReport,
    diagnosis: Option<&DiagnosisReport>,
    _selected_repair: Option<&CoachAction>,
) -> String {
    diagnosis
        .and_then(|report| report.safe_to_say.first().cloned())
        .or_else(|| check.safe_to_say.first().cloned())
        .unwrap_or_else(|| {
            "Self-check reviewed proposed AI output without executing commands or mutating Studio."
                .into()
        })
}

fn build_best_friend_rescue_prompt(
    status: &str,
    verdict: &str,
    rescue_mode: &str,
    selected_repair: Option<&CoachAction>,
    blockers: &[String],
    warnings: &[String],
    checked_message: &str,
) -> String {
    let mut lines = vec![
        "You are recovering an AI Roblox build companion session.".into(),
        format!("Rescue status: {status}; verdict: {verdict}; mode: {rescue_mode}."),
        "Use source artifacts over chat memory, and do not claim the recovery command already ran."
            .into(),
    ];
    if let Some(action) = selected_repair {
        lines.push(format!("Selected recovery action: {}", action.title));
        if let Some(command) = &action.command {
            lines.push(format!("Command: {command}"));
        }
        lines.push(format!("Reason: {}", action.reason));
    } else {
        lines.push("No recovery command was selected; inspect blockers before acting.".into());
    }
    if !blockers.is_empty() {
        lines.push("Blockers:".into());
        for blocker in blockers.iter().take(5) {
            lines.push(format!("- {blocker}"));
        }
    }
    if !warnings.is_empty() {
        lines.push("Warnings:".into());
        for warning in warnings.iter().take(5) {
            lines.push(format!("- {warning}"));
        }
    }
    lines.push("Checked creator-facing recovery message:".into());
    lines.push(checked_message.into());
    lines.join("\n")
}

fn build_best_friend_mentor_report(
    options: &BestFriendMentorOptions,
    mentor_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<BestFriendMentorReport> {
    let write_markdown = markdown_path.is_some();
    let check_path = options.run_dir.join("best-friend-check.json");
    let check_markdown_path = write_markdown.then(|| options.run_dir.join("best-friend-check.md"));
    let check_options = BestFriendCheckOptions {
        prompt: options.prompt.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        opportunity: options.opportunity.clone(),
        max_chars: options.max_chars,
        out: Some(check_path.clone()),
        markdown: check_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let best_friend_check = build_best_friend_check_report(
        &check_options,
        &check_path,
        check_markdown_path.as_deref(),
    )?;
    write_json(check_path.clone(), &best_friend_check)?;
    if let Some(path) = check_markdown_path {
        write_best_friend_check_markdown(path, &best_friend_check)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;

    let protected_action_ready = best_friend_check.protected_action_ready;
    let mentor_mode = if best_friend_check.ready_to_operate {
        if protected_action_ready {
            "protectedAction"
        } else {
            "readAndPlan"
        }
    } else {
        "rescueFirst"
    }
    .to_string();
    let status = if best_friend_check.ready_to_operate {
        "readyToGuide"
    } else if !best_friend_check.next_actions.is_empty() {
        "needsRescue"
    } else {
        "blocked"
    }
    .to_string();
    let verdict = match status.as_str() {
        "readyToGuide" => "mentorCanGuideProtectedCompanionTurn",
        "needsRescue" => "recoverLaunchPacketBeforeActing",
        _ => "mentorBlockedByLaunchControl",
    }
    .to_string();
    let current_focus = options
        .prompt
        .clone()
        .or_else(|| best_friend_check.best_friend.task_pack.prompt.clone())
        .unwrap_or_else(|| best_friend_check.best_friend.task_pack.task_title.clone());

    let mut coaching_cards = build_best_friend_mentor_cards(
        &options.run_dir,
        &options.root,
        &best_friend_check,
        &mentor_mode,
    );
    coaching_cards.sort_by(|left, right| left.id.cmp(&right.id));
    let mistake_traps = build_best_friend_mentor_mistake_traps(&best_friend_check, &mentor_mode);

    let mut safe_to_say = best_friend_check.safe_to_say.clone();
    safe_to_say.push(
        "Best-friend mentor prepared coaching guidance from launch-control artifacts without executing work.".into(),
    );
    safe_to_say.sort();
    safe_to_say.dedup();
    let mut do_not_say = best_friend_check.do_not_say.clone();
    do_not_say.push(
        "Do not treat mentor cards as proof that any protected action, live apply, publish, upload, or playtest already ran.".into(),
    );
    do_not_say.sort();
    do_not_say.dedup();

    let mut blockers = best_friend_check
        .blockers
        .iter()
        .map(|blocker| format!("launch-control: {blocker}"))
        .collect::<Vec<_>>();
    blockers.sort();
    blockers.dedup();
    let mut warnings = best_friend_check.warnings.clone();
    warnings.sort();
    warnings.dedup();

    let mut artifacts = best_friend_check.artifacts.clone();
    artifacts.insert(
        "bestFriendMentor".into(),
        mentor_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "bestFriendMentorMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert(
        "bestFriendCheck".into(),
        best_friend_check.check_path.clone(),
    );

    let mut next_actions = Vec::new();
    if best_friend_check.ready_to_operate {
        if let Some(action) = best_friend_check.first_act_action.clone() {
            next_actions.push(action);
        } else if let Some(action) = best_friend_check.first_safe_action.clone() {
            next_actions.push(action);
        }
    } else {
        next_actions.push(coach_action(
            1,
            "Run best-friend rescue before acting",
            Some(format!(
                "rs autopilot best-friend-rescue {} --root {} --limit {} --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref()),
                command_arg(options.root.to_string_lossy().as_ref()),
                options.limit
            )),
            "Launch control is not ready, so recover the session before speaking or executing the next action.",
            false,
            false,
        ));
    }
    next_actions.push(coach_action(
        90,
        "Refresh best-friend mentor",
        Some(format!(
            "rs autopilot best-friend-mentor {} --root {} --limit {} --format json",
            command_arg(options.run_dir.to_string_lossy().as_ref()),
            command_arg(options.root.to_string_lossy().as_ref()),
            options.limit
        )),
        "Refresh coaching after one protected action, a creator reply, or a rescue attempt.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);

    let mentor_prompt = build_best_friend_mentor_prompt(
        &status,
        &verdict,
        &mentor_mode,
        &current_focus,
        &coaching_cards,
        &mistake_traps,
    );
    let agent_brief = format!(
        "Best-friend mentor is {status}: mode={mentor_mode}, launch-control={}, protected-action-ready={}, cards={}, next `{}`.",
        best_friend_check.status,
        protected_action_ready,
        coaching_cards.len(),
        next_actions
            .first()
            .and_then(|action| action.command.as_deref())
            .unwrap_or("<none>")
    );

    Ok(BestFriendMentorReport {
        schema_version: "rs.autopilot.best-friend-mentor.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        root: options.root.to_string_lossy().to_string(),
        mentor_path: mentor_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict,
        mentor_mode,
        best_friend_check_status: best_friend_check.status.clone(),
        protected_action_ready,
        mentor_prompt,
        current_focus,
        read_order: best_friend_check.required_read_order.clone(),
        coaching_cards,
        mistake_traps,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        best_friend_check,
    })
}

fn build_best_friend_mentor_cards(
    run_dir: &Path,
    root: &Path,
    check: &BestFriendCheckReport,
    mentor_mode: &str,
) -> Vec<BestFriendMentorCard> {
    let read_evidence = check
        .required_read_order
        .iter()
        .take(6)
        .map(|item| format!("{}: {}", item.title, item.path))
        .collect::<Vec<_>>();
    let mut cards = vec![
        best_friend_mentor_card(
            "01-read-order",
            "Read the source artifacts first",
            "The AI should inherit state from durable artifacts, not from chat memory or assumptions.",
            read_evidence,
            None,
            vec![
                "The model has inspected the listed read-order artifacts before speaking or acting."
                    .into(),
            ],
            vec![
                "Stop if a required artifact is missing or contradicts the next action.".into(),
            ],
        ),
        best_friend_mentor_card(
            "02-launch-control",
            "Trust launch control over confidence",
            "The best-friend-check receipt verifies preflight, read order, protected action, and Studio review visibility.",
            vec![
                format!("check status: {}", check.status),
                format!("launch preflight: {}", check.launch_preflight_status),
                format!("protected action ready: {}", check.protected_action_ready),
            ],
            Some(format!(
                "rs autopilot best-friend-check {} --root {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref()),
                command_arg(root.to_string_lossy().as_ref())
            )),
            vec!["`best-friend-check.json` is current for this run.".into()],
            vec![
                "Stop if launch control reports blockers or the protected action is not act-supported."
                    .into(),
            ],
        ),
        best_friend_mentor_card(
            "04-creator-claim-boundary",
            "Speak only from checked claims",
            "The companion can be warm and useful without claiming unrun work, live proof, publish, upload, or playtest success.",
            check.safe_to_say
                .iter()
                .take(3)
                .cloned()
                .collect::<Vec<_>>(),
            None,
            vec!["Any creator-facing update uses `safeToSay` or a self-checked rewrite.".into()],
            vec![
                "Stop if the proposed message says the game is done, applied, published, uploaded, or playtested without matching proof.".into(),
            ],
        ),
    ];
    if mentor_mode == "rescueFirst" {
        cards.push(best_friend_mentor_card(
            "03-rescue-before-action",
            "Recover before acting",
            "A blocked launch packet needs a recovery receipt so the AI does not retry arbitrary commands or invent progress.",
            check.blockers.iter().take(6).cloned().collect::<Vec<_>>(),
            Some(format!(
                "rs autopilot best-friend-rescue {} --root {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref()),
                command_arg(root.to_string_lossy().as_ref())
            )),
            vec!["`best-friend-rescue.json` selects a repair route and checked wording.".into()],
            vec!["Stop if rescue itself reports blocked message self-check or no selected repair.".into()],
        ));
    } else {
        cards.push(best_friend_mentor_card(
            "03-protected-next-action",
            "Use the protected next action",
            "The fastest safe path is the command launch control already wrapped for the AI; do not hand-copy a riskier variant.",
            check
                .first_act_action
                .as_ref()
                .and_then(|action| action.command.clone())
                .or_else(|| check.first_safe_action.as_ref().and_then(|action| action.command.clone()))
                .into_iter()
                .collect::<Vec<_>>(),
            check
                .first_act_action
                .as_ref()
                .and_then(|action| action.command.clone()),
            vec!["Exactly one protected action has a receipt before the mentor packet is refreshed.".into()],
            vec![
                "Stop at live Studio, apply, publish, upload, destructive, or unknown-command gates."
                    .into(),
            ],
        ));
    }
    cards
}

fn best_friend_mentor_card(
    id: &str,
    title: &str,
    why: &str,
    evidence: Vec<String>,
    command: Option<String>,
    done_when: Vec<String>,
    stop_if: Vec<String>,
) -> BestFriendMentorCard {
    BestFriendMentorCard {
        id: id.into(),
        title: title.into(),
        why: why.into(),
        evidence,
        command,
        done_when,
        stop_if,
    }
}

fn build_best_friend_mentor_mistake_traps(
    check: &BestFriendCheckReport,
    mentor_mode: &str,
) -> Vec<String> {
    let mut traps = vec![
        "Do not skip the read order because the chat history sounds familiar.".into(),
        "Do not rewrite the protected action by hand; use the act-supported wrapper when present."
            .into(),
        "Do not claim live Studio mutation, publish, upload, rollback, or playtest proof unless the matching artifact exists.".into(),
        "Do not keep acting after one protected action without refreshing launch control or mentor guidance.".into(),
    ];
    if mentor_mode == "rescueFirst" {
        traps.insert(
            0,
            "Do not speak or act from a blocked launch packet; run best-friend-rescue first."
                .into(),
        );
    }
    traps.extend(check.do_not_say.iter().take(6).cloned());
    traps.sort();
    traps.dedup();
    traps
}

fn build_best_friend_mentor_prompt(
    status: &str,
    verdict: &str,
    mentor_mode: &str,
    current_focus: &str,
    cards: &[BestFriendMentorCard],
    traps: &[String],
) -> String {
    let mut lines = vec![
        "You are preparing to help a creator build a Roblox game through the rs Autopilot CLI."
            .into(),
        format!("Mentor status: {status}; verdict: {verdict}; mode: {mentor_mode}."),
        format!("Current focus: {current_focus}."),
        "Use artifact-backed commands only. If launch control is blocked, recover before acting."
            .into(),
    ];
    for card in cards.iter().take(6) {
        lines.push(format!("Card {}: {} - {}", card.id, card.title, card.why));
        if let Some(command) = &card.command {
            lines.push(format!("Command: {command}"));
        }
    }
    if let Some(trap) = traps.first() {
        lines.push(format!("Highest-risk mistake to avoid: {trap}"));
    }
    lines.join("\n")
}

fn build_best_friend_pilot_report(
    options: &BestFriendPilotOptions,
    pilot_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<BestFriendPilotReport> {
    if !options.run_dir.is_dir() {
        return Err(AppError::Other(format!(
            "autopilot best-friend-pilot run directory does not exist: {}",
            options.run_dir.display()
        )));
    }

    let write_markdown = markdown_path.is_some();
    let mentor_path = options.run_dir.join("best-friend-mentor.json");
    let mentor_markdown_path =
        write_markdown.then(|| options.run_dir.join("best-friend-mentor.md"));
    let mentor_options = BestFriendMentorOptions {
        prompt: options.prompt.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        opportunity: options.opportunity.clone(),
        max_chars: options.max_chars,
        out: Some(mentor_path.clone()),
        markdown: mentor_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let mentor = build_best_friend_mentor_report(
        &mentor_options,
        &mentor_path,
        mentor_markdown_path.as_deref(),
    )?;
    write_json(mentor_path.clone(), &mentor)?;
    if let Some(path) = mentor_markdown_path {
        write_best_friend_mentor_markdown(path, &mentor)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;

    let mut safe_to_say = mentor.safe_to_say.clone();
    let mut do_not_say = mentor.do_not_say.clone();
    let mut blockers = mentor.blockers.clone();
    let mut warnings = mentor.warnings.clone();
    let mut artifacts = mentor.artifacts.clone();
    artifacts.insert(
        "bestFriendPilot".into(),
        pilot_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "bestFriendPilotMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    let mut first_turn = None;
    let mut rescue = None;
    let mut reply = None;
    let mut selected_command = None;
    let mut companion_message = None;
    let mut pilot_mode = if mentor.status == "readyToGuide" && mentor.protected_action_ready {
        "actThenReply"
    } else {
        "rescueFirst"
    }
    .to_string();

    if pilot_mode == "actThenReply" {
        let first_turn_path = options.run_dir.join("first-turn.json");
        let first_turn_markdown_path =
            write_markdown.then(|| options.run_dir.join("first-turn.md"));
        let first_turn_options = FirstTurnOptions {
            prompt: options.prompt.clone(),
            run_dir: options.run_dir.clone(),
            root: options.root.clone(),
            limit: options.limit,
            opportunity: options.opportunity.clone(),
            max_chars: options.max_chars,
            dry_run: options.dry_run,
            artifact_prefix: Some("best-friend-pilot".into()),
            out: Some(first_turn_path.clone()),
            markdown: first_turn_markdown_path.clone(),
            no_markdown: !write_markdown,
            json: false,
        };
        let report = build_first_turn_report(
            &first_turn_options,
            &first_turn_path,
            first_turn_markdown_path.as_deref(),
        )?;
        write_json(first_turn_path.clone(), &report)?;
        if let Some(path) = first_turn_markdown_path {
            write_first_turn_markdown(path, &report)?;
        }
        selected_command = report
            .protected_command
            .clone()
            .or_else(|| report.selected_inner_command.clone())
            .or_else(|| report.selected_command.clone());
        safe_to_say.extend(report.safe_to_say.clone());
        do_not_say.extend(report.do_not_say.clone());
        blockers.extend(
            report
                .blockers
                .iter()
                .map(|blocker| format!("first-turn: {blocker}")),
        );
        warnings.extend(report.warnings.clone());
        artifacts.extend(report.artifacts.clone());
        let should_reply = matches!(report.status.as_str(), "advanced" | "dryRun");
        first_turn = Some(report);

        if should_reply {
            let reply_path = options.run_dir.join("best-friend-reply.json");
            let reply_markdown_path =
                write_markdown.then(|| options.run_dir.join("best-friend-reply.md"));
            let reply_options = BestFriendReplyOptions {
                run_dir: options.run_dir.clone(),
                root: options.root.clone(),
                limit: options.limit,
                out: Some(reply_path.clone()),
                markdown: reply_markdown_path.clone(),
                no_markdown: !write_markdown,
                json: false,
            };
            let report = build_best_friend_reply_report(
                &reply_options,
                &reply_path,
                reply_markdown_path.as_deref(),
            )?;
            write_json(reply_path.clone(), &report)?;
            if let Some(path) = reply_markdown_path {
                write_best_friend_reply_markdown(path, &report)?;
            }
            if report.status == "readyToSend" {
                companion_message = Some(report.message.clone());
            }
            safe_to_say.extend(report.safe_to_say.clone());
            do_not_say.extend(report.do_not_say.clone());
            blockers.extend(
                report
                    .blockers
                    .iter()
                    .map(|blocker| format!("reply: {blocker}")),
            );
            warnings.extend(report.warnings.clone());
            artifacts.extend(report.artifacts.clone());
            reply = Some(report);
        }
    } else {
        let rescue_path = options.run_dir.join("best-friend-rescue.json");
        let rescue_markdown_path =
            write_markdown.then(|| options.run_dir.join("best-friend-rescue.md"));
        let rescue_options = BestFriendRescueOptions {
            prompt: options.prompt.clone(),
            run_dir: options.run_dir.clone(),
            root: options.root.clone(),
            limit: options.limit,
            opportunity: options.opportunity.clone(),
            max_chars: options.max_chars,
            command: None,
            result: Some("best-friend-pilot launch control was not ready".into()),
            errors: mentor.blockers.clone(),
            evidence: vec![
                mentor.mentor_path.clone(),
                mentor.best_friend_check.check_path.clone(),
            ],
            out: Some(rescue_path.clone()),
            markdown: rescue_markdown_path.clone(),
            no_markdown: !write_markdown,
            json: false,
        };
        let report = build_best_friend_rescue_report(
            &rescue_options,
            &rescue_path,
            rescue_markdown_path.as_deref(),
        )?;
        write_json(rescue_path.clone(), &report)?;
        if let Some(path) = rescue_markdown_path {
            write_best_friend_rescue_markdown(path, &report)?;
        }
        if report.message_self_check_status == "readyToProceed" {
            companion_message = Some(report.checked_message.clone());
        }
        safe_to_say.extend(report.safe_to_say.clone());
        do_not_say.extend(report.do_not_say.clone());
        blockers.extend(
            report
                .blockers
                .iter()
                .map(|blocker| format!("rescue: {blocker}")),
        );
        warnings.extend(report.warnings.clone());
        artifacts.extend(report.artifacts.clone());
        rescue = Some(report);
    }

    safe_to_say.push(
        "Best-friend pilot refreshed mentor guidance before selecting action or rescue flow."
            .into(),
    );
    do_not_say.push(
        "Do not claim best-friend-pilot crossed live Studio, apply, publish, upload, rollback, or playtest boundaries.".into(),
    );
    do_not_say.push(
        "Do not run a second companion action from the pilot receipt without refreshing mentor or best-friend state.".into(),
    );
    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let first_turn_status = first_turn.as_ref().map(|report| report.status.clone());
    let rescue_status = rescue.as_ref().map(|report| report.status.clone());
    let reply_status = reply.as_ref().map(|report| report.status.clone());
    let status = best_friend_pilot_status(
        options.dry_run,
        first_turn_status.as_deref(),
        rescue.as_ref(),
        reply_status.as_deref(),
        &blockers,
    );
    let verdict = best_friend_pilot_verdict(&status);
    let mut next_actions = best_friend_pilot_next_actions(
        &options.run_dir,
        &options.root,
        options.limit,
        &status,
        first_turn.as_ref(),
        rescue.as_ref(),
        reply.as_ref(),
    );
    dedup_next_actions(&mut next_actions);
    if pilot_mode == "actThenReply" && matches!(status.as_str(), "blocked" | "failed") {
        pilot_mode = "actionBlocked".into();
    }
    let agent_brief = format!(
        "Best-friend pilot is {status}: mode={pilot_mode}, mentor={}, first-turn={}, rescue={}, reply={}, next `{}`.",
        mentor.status,
        first_turn_status.as_deref().unwrap_or("skipped"),
        rescue_status.as_deref().unwrap_or("skipped"),
        reply_status.as_deref().unwrap_or("skipped"),
        next_actions
            .first()
            .and_then(|action| action.command.as_deref())
            .unwrap_or("<none>")
    );

    Ok(BestFriendPilotReport {
        schema_version: "rs.autopilot.best-friend-pilot.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        root: options.root.to_string_lossy().to_string(),
        pilot_path: pilot_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict,
        pilot_mode,
        dry_run: options.dry_run,
        mentor_status: mentor.status.clone(),
        first_turn_status,
        rescue_status,
        reply_status,
        protected_action_ready: mentor.protected_action_ready,
        selected_command,
        companion_message,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        mentor,
        first_turn,
        rescue,
        reply,
    })
}

fn best_friend_pilot_status(
    dry_run: bool,
    first_turn_status: Option<&str>,
    rescue: Option<&BestFriendRescueReport>,
    reply_status: Option<&str>,
    blockers: &[String],
) -> String {
    if let Some(rescue) = rescue {
        return if rescue.message_self_check_status == "readyToProceed" {
            "rescuePrepared"
        } else {
            "blocked"
        }
        .into();
    }
    if dry_run || first_turn_status == Some("dryRun") {
        return "dryRun".into();
    }
    if reply_status == Some("readyToSend") && blockers.is_empty() {
        return "readyToSend".into();
    }
    match first_turn_status {
        Some("advanced") => "advancedNeedsReply".into(),
        Some("failed") => "failed".into(),
        Some("blocked") => "blocked".into(),
        _ if !blockers.is_empty() => "blocked".into(),
        _ => "blocked".into(),
    }
}

fn best_friend_pilot_verdict(status: &str) -> String {
    match status {
        "readyToSend" => "protectedActionExecutedAndReplyChecked",
        "dryRun" => "protectedActionSelectedWithoutExecution",
        "rescuePrepared" => "rescueRoutePreparedBeforeAction",
        "advancedNeedsReply" => "protectedActionExecutedButReplyNeedsReview",
        "failed" => "protectedActionFailed",
        _ => "pilotBlocked",
    }
    .into()
}

fn best_friend_pilot_next_actions(
    run_dir: &Path,
    root: &Path,
    limit: usize,
    status: &str,
    first_turn: Option<&FirstTurnReport>,
    rescue: Option<&BestFriendRescueReport>,
    reply: Option<&BestFriendReplyReport>,
) -> Vec<CoachAction> {
    let run_arg = command_arg(run_dir.to_string_lossy().as_ref());
    let root_arg = command_arg(root.to_string_lossy().as_ref());
    let mut actions = Vec::new();
    match status {
        "readyToSend" => actions.push(coach_action(
            1,
            "Use checked companion message",
            Some(format!(
                "rs autopilot best-friend-reply {run_arg} --root {root_arg} --format json"
            )),
            "Read companionMessage exactly; refresh pilot before any second action.",
            false,
            false,
        )),
        "rescuePrepared" => {
            if let Some(action) = rescue.and_then(|report| report.next_actions.first()).cloned() {
                actions.push(action);
            }
        }
        "dryRun" => actions.push(coach_action(
            1,
            "Run pilot without dry-run",
            Some(format!(
                "rs autopilot best-friend-pilot {run_arg} --root {root_arg} --limit {limit} --format json"
            )),
            "Execute the protected first action after reviewing the dry-run receipt.",
            false,
            false,
        )),
        _ => {
            if let Some(action) = reply
                .and_then(|report| report.next_actions.first())
                .or_else(|| first_turn.and_then(|report| report.next_actions.first()))
                .cloned()
            {
                actions.push(action);
            }
        }
    }
    actions.push(coach_action(
        90,
        "Refresh best-friend pilot",
        Some(format!(
            "rs autopilot best-friend-pilot {run_arg} --root {root_arg} --limit {limit} --format json"
        )),
        "Refresh the co-pilot after one action, rescue attempt, or creator reply.",
        false,
        false,
    ));
    actions
}

fn build_best_friend_control_report(
    options: &BestFriendControlOptions,
    control_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<BestFriendControlReport> {
    let write_markdown = markdown_path.is_some();
    let check_path = options.run_dir.join("best-friend-check.json");
    let check_markdown_path = write_markdown.then(|| options.run_dir.join("best-friend-check.md"));
    let check_options = BestFriendCheckOptions {
        prompt: options.prompt.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        opportunity: options.opportunity.clone(),
        max_chars: options.max_chars,
        out: Some(check_path.clone()),
        markdown: check_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let best_friend_check = build_best_friend_check_report(
        &check_options,
        &check_path,
        check_markdown_path.as_deref(),
    )?;
    write_json(check_path.clone(), &best_friend_check)?;
    if let Some(path) = check_markdown_path {
        write_best_friend_check_markdown(path, &best_friend_check)?;
    }

    let run_arg = command_arg(options.run_dir.to_string_lossy().as_ref());
    let root_arg = command_arg(options.root.to_string_lossy().as_ref());
    let pilot_path = options.run_dir.join("best-friend-pilot.json");
    let pilot_value = read_json_if_exists(&pilot_path)?;
    let pilot_status = pilot_value
        .as_ref()
        .and_then(|value| string_field(value, "status"));
    let companion_message = pilot_value
        .as_ref()
        .and_then(|value| string_field(value, "companionMessage"));
    let studio_review_path = options.run_dir.join("studio-review.json");
    let studio_review_value = read_json_if_exists(&studio_review_path)?;
    let studio_review_best_friend_pilot_visible = studio_review_value
        .as_ref()
        .and_then(|value| value.get("panelPayload"))
        .and_then(|payload| string_field(payload, "bestFriendPilotStatus"))
        .is_some();

    let pilot_command = format!(
        "rs autopilot best-friend-pilot {run_arg} --root {root_arg} --limit {} --format json",
        options.limit
    );
    let rescue_command = format!(
        "rs autopilot best-friend-rescue {run_arg} --root {root_arg} --limit {} --format json",
        options.limit
    );
    let reply_command =
        format!("rs autopilot best-friend-reply {run_arg} --root {root_arg} --format json");
    let publish_pilot_command = format!(
        "rs autopilot publish-review {run_arg} --best-friend-pilot {} --format json",
        command_arg(pilot_path.to_string_lossy().as_ref())
    );

    let mut blockers = Vec::new();
    let mut warnings = best_friend_check.warnings.clone();
    warnings.push(
        "best-friend-control routes the next AI move; it does not execute the selected branch"
            .into(),
    );
    let (status, verdict, selected_branch, selected_command, primary_reason) = if !best_friend_check
        .ready_to_operate
    {
        blockers.extend(best_friend_check.blockers.clone());
        (
            "rescueRequired".to_string(),
            "repairLaunchBeforePilotOrReply".to_string(),
            "rescue".to_string(),
            Some(rescue_command.clone()),
            "Launch control is blocked, so recover before speaking or acting.".to_string(),
        )
    } else {
        match pilot_status.as_deref() {
                Some("readyToSend") if studio_review_best_friend_pilot_visible => (
                    "readyToSpeak".to_string(),
                    "sendCheckedCompanionMessage".to_string(),
                    "speak".to_string(),
                    None,
                    "The pilot receipt is checked and visible in Studio; send companionMessage exactly.".to_string(),
                ),
                Some("readyToSend") => (
                    "readyToPublishPilot".to_string(),
                    "publishPilotBeforeSpeaking".to_string(),
                    "publishPilot".to_string(),
                    Some(publish_pilot_command.clone()),
                    "The pilot has checked wording, but Studio does not show the co-pilot receipt yet.".to_string(),
                ),
                Some("dryRun") => (
                    "readyToExecutePilot".to_string(),
                    "executeReviewedPilot".to_string(),
                    "pilot".to_string(),
                    Some(pilot_command.clone()),
                    "The pilot selected a protected move without execution; rerun without dry-run when ready.".to_string(),
                ),
                Some("advancedNeedsReply") => (
                    "replyRequired".to_string(),
                    "refreshCheckedReply".to_string(),
                    "reply".to_string(),
                    Some(reply_command.clone()),
                    "A protected action advanced, but the creator-facing reply still needs checking.".to_string(),
                ),
                Some("rescuePrepared") => (
                    "rescuePrepared".to_string(),
                    "followPreparedRescue".to_string(),
                    "rescue".to_string(),
                    Some(rescue_command.clone()),
                    "The pilot prepared a rescue route; follow it before attempting another action.".to_string(),
                ),
                Some("blocked" | "failed") => {
                    blockers.push(format!(
                        "best-friend-pilot status is {}",
                        pilot_status.as_deref().unwrap_or("blocked")
                    ));
                    (
                        "rescueRequired".to_string(),
                        "repairPilotBeforeContinuing".to_string(),
                        "rescue".to_string(),
                        Some(rescue_command.clone()),
                        "The latest pilot is blocked or failed, so recover before speaking or acting.".to_string(),
                    )
                }
                Some(other) => (
                    "readyToPilot".to_string(),
                    "refreshPilotFromCurrentEvidence".to_string(),
                    "pilot".to_string(),
                    Some(pilot_command.clone()),
                    format!("The latest pilot status `{other}` is not a final checked reply."),
                ),
                None => (
                    "readyToPilot".to_string(),
                    "runFirstPilotReceipt".to_string(),
                    "pilot".to_string(),
                    Some(pilot_command.clone()),
                    "Launch control is ready and no pilot receipt exists yet.".to_string(),
                ),
            }
    };

    let mut artifacts = best_friend_check.artifacts.clone();
    artifacts.insert(
        "bestFriendControl".into(),
        control_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "bestFriendControlMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert(
        "bestFriendCheck".into(),
        best_friend_check.check_path.clone(),
    );
    if pilot_path.exists() {
        artifacts.insert(
            "bestFriendPilot".into(),
            pilot_path.to_string_lossy().to_string(),
        );
    }
    if studio_review_path.exists() {
        artifacts.insert(
            "studioReview".into(),
            studio_review_path.to_string_lossy().to_string(),
        );
    }

    let mut safe_to_say = best_friend_check.safe_to_say.clone();
    safe_to_say.push(
        "Best-friend control selected the next branch from launch-control, pilot, and Studio-review evidence."
            .into(),
    );
    if status == "readyToSpeak" {
        safe_to_say
            .push("The checked companion message is ready to send exactly as written.".into());
    }
    if let Some(pilot) = &pilot_value {
        safe_to_say.extend(string_array_field(pilot, "safeToSay"));
        warnings.extend(string_array_field(pilot, "warnings"));
    }
    let mut do_not_say = best_friend_check.do_not_say.clone();
    do_not_say.push(
        "Do not claim best-friend-control executed the pilot, rescue, publish, or reply branch."
            .into(),
    );
    do_not_say.push(
        "Do not claim the co-pilot receipt is visible in Studio unless studioReviewBestFriendPilotVisible is true."
            .into(),
    );
    if let Some(pilot) = &pilot_value {
        do_not_say.extend(string_array_field(pilot, "doNotSay"));
    }

    let mut next_actions = Vec::new();
    if let Some(command) = selected_command.clone() {
        next_actions.push(coach_action(
            1,
            "Run selected best-friend control branch",
            Some(command),
            &primary_reason,
            selected_branch == "publishPilot",
            false,
        ));
    }
    next_actions.push(coach_action(
        80,
        "Refresh best-friend control",
        Some(format!(
            "rs autopilot best-friend-control {run_arg} --root {root_arg} --limit {} --format json",
            options.limit
        )),
        "Rerun control after the selected branch changes any pilot, rescue, reply, or Studio review artifact.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();

    let operator_steps = build_best_friend_control_steps(
        &selected_branch,
        selected_command.as_deref(),
        companion_message.as_deref(),
        &primary_reason,
    );
    let control_prompt = build_best_friend_control_prompt(
        &status,
        &verdict,
        &selected_branch,
        &primary_reason,
        companion_message.as_deref(),
        &safe_to_say,
        &do_not_say,
    );
    let agent_brief = format!(
        "Best-friend control is {status}: branch={selected_branch}, launchControl={}, pilot={}, Studio pilot visible={}, next={}.",
        best_friend_check.status,
        pilot_status.as_deref().unwrap_or("missing"),
        studio_review_best_friend_pilot_visible,
        selected_command.as_deref().unwrap_or("send checked companionMessage")
    );

    Ok(BestFriendControlReport {
        schema_version: "rs.autopilot.best-friend-control.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        root: options.root.to_string_lossy().to_string(),
        control_path: control_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict,
        selected_branch,
        launch_control_status: best_friend_check.status.clone(),
        ready_to_operate: best_friend_check.ready_to_operate,
        pilot_status,
        studio_review_best_friend_pilot_visible,
        studio_review_path: studio_review_path
            .exists()
            .then(|| studio_review_path.to_string_lossy().to_string()),
        selected_command,
        companion_message,
        control_prompt,
        operator_steps,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        best_friend_check,
        pilot: pilot_value,
    })
}

fn build_best_friend_control_steps(
    selected_branch: &str,
    selected_command: Option<&str>,
    companion_message: Option<&str>,
    primary_reason: &str,
) -> Vec<String> {
    let mut steps = vec![
        "Read best-friend-control.json and best-friend-control.md before acting.".into(),
        primary_reason.into(),
    ];
    match selected_branch {
        "speak" => {
            steps.push(format!(
                "Send this checked message exactly: {}",
                companion_message.unwrap_or("missing companionMessage; rerun best-friend-reply")
            ));
            steps.push("Stop after speaking; refresh control before any second action.".into());
        }
        "publishPilot" => {
            steps.push(format!(
                "Run `{}` so Studio shows the co-pilot receipt before the AI speaks.",
                selected_command.unwrap_or("rs autopilot publish-review")
            ));
            steps.push("After publish-review succeeds, rerun best-friend-control.".into());
        }
        "pilot" => {
            steps.push(format!(
                "Run `{}` to create or refresh the one-move pilot receipt.",
                selected_command.unwrap_or("rs autopilot best-friend-pilot")
            ));
            steps.push("Do not run a second action until control is refreshed.".into());
        }
        "reply" => {
            steps.push(format!(
                "Run `{}` to turn the action receipt into checked creator-facing wording.",
                selected_command.unwrap_or("rs autopilot best-friend-reply")
            ));
        }
        "rescue" => {
            steps.push(format!(
                "Run `{}` before speaking or acting again.",
                selected_command.unwrap_or("rs autopilot best-friend-rescue")
            ));
        }
        _ => {}
    }
    steps
}

fn build_best_friend_control_prompt(
    status: &str,
    verdict: &str,
    selected_branch: &str,
    primary_reason: &str,
    companion_message: Option<&str>,
    safe_to_say: &[String],
    do_not_say: &[String],
) -> String {
    let mut prompt = String::new();
    prompt.push_str("You are the AI best-friend operator for this Roblox build.\n");
    prompt.push_str(&format!(
        "Status: {status}; verdict: {verdict}; branch: {selected_branch}.\n"
    ));
    prompt.push_str(primary_reason);
    prompt.push('\n');
    if let Some(message) = companion_message {
        prompt.push_str("Checked companion message:\n");
        prompt.push_str(message);
        prompt.push('\n');
    }
    prompt.push_str("Safe claims:\n");
    for claim in safe_to_say.iter().take(5) {
        prompt.push_str("- ");
        prompt.push_str(claim);
        prompt.push('\n');
    }
    prompt.push_str("Forbidden claims:\n");
    for claim in do_not_say.iter().take(5) {
        prompt.push_str("- ");
        prompt.push_str(claim);
        prompt.push('\n');
    }
    prompt.push_str("Run only the selected branch, then refresh best-friend-control.");
    prompt
}

fn build_best_friend_operate_report(
    options: &BestFriendOperateOptions,
    operate_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<BestFriendOperateReport> {
    let write_markdown = markdown_path.is_some();
    let artifact_prefix = options
        .artifact_prefix
        .as_deref()
        .map(slug)
        .unwrap_or_else(|| "best-friend-operate".into());
    let before_control_path = options
        .run_dir
        .join(format!("{artifact_prefix}-control-before.json"));
    let before_control_markdown_path = write_markdown.then(|| {
        options
            .run_dir
            .join(format!("{artifact_prefix}-control-before.md"))
    });
    let before_control_options = BestFriendControlOptions {
        prompt: options.prompt.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        opportunity: options.opportunity.clone(),
        max_chars: options.max_chars,
        out: Some(before_control_path.clone()),
        markdown: before_control_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let before_control = build_best_friend_control_report(
        &before_control_options,
        &before_control_path,
        before_control_markdown_path.as_deref(),
    )?;
    write_json(before_control_path.clone(), &before_control)?;
    if let Some(path) = before_control_markdown_path {
        write_best_friend_control_markdown(path, &before_control)?;
    }

    let mut artifacts = before_control.artifacts.clone();
    artifacts.insert(
        "bestFriendOperate".into(),
        operate_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "bestFriendOperateMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert(
        "bestFriendOperateControlBefore".into(),
        before_control_path.to_string_lossy().to_string(),
    );

    let selected_branch = before_control.selected_branch.clone();
    let selected_command = before_control.selected_command.clone();
    let mut executed = false;
    let mut executed_command = None;
    let mut branch_status = None;
    let mut branch_report = None;
    let mut companion_message = before_control.companion_message.clone();
    let mut blockers = before_control.blockers.clone();
    let mut warnings = before_control.warnings.clone();
    let mut safe_to_say = before_control.safe_to_say.clone();
    let mut do_not_say = before_control.do_not_say.clone();

    if options.dry_run {
        warnings
            .push("best-friend-operate dry-run selected the branch without executing it".into());
    } else {
        match selected_branch.as_str() {
            "pilot" => {
                let pilot_path = options.run_dir.join("best-friend-pilot.json");
                let pilot_markdown_path =
                    write_markdown.then(|| options.run_dir.join("best-friend-pilot.md"));
                let pilot_options = BestFriendPilotOptions {
                    prompt: options.prompt.clone(),
                    run_dir: options.run_dir.clone(),
                    root: options.root.clone(),
                    limit: options.limit,
                    opportunity: options.opportunity.clone(),
                    max_chars: options.max_chars,
                    dry_run: false,
                    out: Some(pilot_path.clone()),
                    markdown: pilot_markdown_path.clone(),
                    no_markdown: !write_markdown,
                    json: false,
                };
                let report = build_best_friend_pilot_report(
                    &pilot_options,
                    &pilot_path,
                    pilot_markdown_path.as_deref(),
                )?;
                write_json(pilot_path.clone(), &report)?;
                if let Some(path) = pilot_markdown_path {
                    write_best_friend_pilot_markdown(path, &report)?;
                }
                executed = true;
                executed_command = selected_command.clone();
                branch_status = Some(report.status.clone());
                companion_message = report.companion_message.clone().or(companion_message);
                safe_to_say.extend(report.safe_to_say.clone());
                do_not_say.extend(report.do_not_say.clone());
                warnings.extend(report.warnings.clone());
                blockers.extend(report.blockers.clone());
                artifacts.extend(report.artifacts.clone());
                branch_report = Some(serde_json::to_value(&report)?);
            }
            "rescue" => {
                let rescue_path = options.run_dir.join("best-friend-rescue.json");
                let rescue_markdown_path =
                    write_markdown.then(|| options.run_dir.join("best-friend-rescue.md"));
                let rescue_options = BestFriendRescueOptions {
                    prompt: options.prompt.clone(),
                    run_dir: options.run_dir.clone(),
                    root: options.root.clone(),
                    limit: options.limit,
                    opportunity: options.opportunity.clone(),
                    max_chars: options.max_chars,
                    command: selected_command.clone(),
                    result: Some("best-friend-operate selected rescue branch".into()),
                    errors: Vec::new(),
                    evidence: vec![before_control.control_path.clone()],
                    out: Some(rescue_path.clone()),
                    markdown: rescue_markdown_path.clone(),
                    no_markdown: !write_markdown,
                    json: false,
                };
                let report = build_best_friend_rescue_report(
                    &rescue_options,
                    &rescue_path,
                    rescue_markdown_path.as_deref(),
                )?;
                write_json(rescue_path.clone(), &report)?;
                if let Some(path) = rescue_markdown_path {
                    write_best_friend_rescue_markdown(path, &report)?;
                }
                executed = true;
                executed_command = selected_command.clone();
                branch_status = Some(report.status.clone());
                safe_to_say.extend(report.safe_to_say.clone());
                do_not_say.extend(report.do_not_say.clone());
                warnings.extend(report.warnings.clone());
                blockers.extend(report.blockers.clone());
                artifacts.extend(report.artifacts.clone());
                branch_report = Some(serde_json::to_value(&report)?);
            }
            "reply" => {
                let reply_path = options.run_dir.join("best-friend-reply.json");
                let reply_markdown_path =
                    write_markdown.then(|| options.run_dir.join("best-friend-reply.md"));
                let reply_options = BestFriendReplyOptions {
                    run_dir: options.run_dir.clone(),
                    root: options.root.clone(),
                    limit: options.limit,
                    out: Some(reply_path.clone()),
                    markdown: reply_markdown_path.clone(),
                    no_markdown: !write_markdown,
                    json: false,
                };
                let report = build_best_friend_reply_report(
                    &reply_options,
                    &reply_path,
                    reply_markdown_path.as_deref(),
                )?;
                write_json(reply_path.clone(), &report)?;
                if let Some(path) = reply_markdown_path {
                    write_best_friend_reply_markdown(path, &report)?;
                }
                executed = true;
                executed_command = selected_command.clone();
                branch_status = Some(report.status.clone());
                companion_message = Some(report.message.clone());
                safe_to_say.extend(report.safe_to_say.clone());
                do_not_say.extend(report.do_not_say.clone());
                warnings.extend(report.warnings.clone());
                blockers.extend(report.blockers.clone());
                artifacts.extend(report.artifacts.clone());
                branch_report = Some(serde_json::to_value(&report)?);
            }
            "speak" => {
                safe_to_say.push(
                    "Best-friend operate found a checked companion message ready to send.".into(),
                );
            }
            "publishPilot" => {
                warnings.push(
                    "best-friend-operate stopped before Studio publish; run publish-review explicitly when Studio is connected"
                        .into(),
                );
            }
            _ => blockers.push(format!(
                "best-friend-operate does not know how to execute branch `{selected_branch}`"
            )),
        }
    }

    let after_control = if executed {
        let after_control_path = options
            .run_dir
            .join(format!("{artifact_prefix}-control-after.json"));
        let after_control_markdown_path = write_markdown.then(|| {
            options
                .run_dir
                .join(format!("{artifact_prefix}-control-after.md"))
        });
        let after_control_options = BestFriendControlOptions {
            prompt: options.prompt.clone(),
            run_dir: options.run_dir.clone(),
            root: options.root.clone(),
            limit: options.limit,
            opportunity: options.opportunity.clone(),
            max_chars: options.max_chars,
            out: Some(after_control_path.clone()),
            markdown: after_control_markdown_path.clone(),
            no_markdown: !write_markdown,
            json: false,
        };
        let report = build_best_friend_control_report(
            &after_control_options,
            &after_control_path,
            after_control_markdown_path.as_deref(),
        )?;
        write_json(after_control_path.clone(), &report)?;
        if let Some(path) = after_control_markdown_path {
            write_best_friend_control_markdown(path, &report)?;
        }
        artifacts.insert(
            "bestFriendOperateControlAfter".into(),
            after_control_path.to_string_lossy().to_string(),
        );
        artifacts.extend(report.artifacts.clone());
        Some(report)
    } else {
        None
    };

    let active_control = after_control.as_ref().unwrap_or(&before_control);
    let status = best_friend_operate_status(
        options.dry_run,
        &selected_branch,
        executed,
        active_control,
        &blockers,
    );
    let verdict = best_friend_operate_verdict(&status);
    let mut next_actions = best_friend_operate_next_actions(
        &options.run_dir,
        &options.root,
        options.limit,
        &status,
        &selected_branch,
        selected_command.clone(),
        companion_message.as_deref(),
        active_control,
    );
    dedup_next_actions(&mut next_actions);

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();

    let operator_steps = build_best_friend_operate_steps(
        &status,
        &selected_branch,
        executed,
        selected_command.as_deref(),
        companion_message.as_deref(),
    );
    let agent_brief = format!(
        "Best-friend operate is {status}: selected branch `{selected_branch}`, before control `{}`, after control `{}`, executed={}, next `{}`.",
        before_control.status,
        after_control
            .as_ref()
            .map(|report| report.status.as_str())
            .unwrap_or("skipped"),
        executed,
        next_actions
            .first()
            .and_then(|action| action.command.as_deref())
            .unwrap_or("send checked companionMessage")
    );

    Ok(BestFriendOperateReport {
        schema_version: "rs.autopilot.best-friend-operate.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        root: options.root.to_string_lossy().to_string(),
        operate_path: operate_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict,
        dry_run: options.dry_run,
        selected_branch,
        before_control_status: before_control.status.clone(),
        after_control_status: after_control.as_ref().map(|report| report.status.clone()),
        executed,
        selected_command,
        executed_command,
        branch_status,
        companion_message,
        operator_steps,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        before_control,
        after_control,
        branch_report,
    })
}

fn best_friend_operate_status(
    dry_run: bool,
    selected_branch: &str,
    executed: bool,
    active_control: &BestFriendControlReport,
    blockers: &[String],
) -> String {
    if !blockers.is_empty() {
        return "blocked".into();
    }
    if dry_run {
        return "dryRun".into();
    }
    if selected_branch == "speak" || active_control.selected_branch == "speak" {
        return "readyToSend".into();
    }
    if selected_branch == "publishPilot" || active_control.selected_branch == "publishPilot" {
        return "studioPublishRequired".into();
    }
    if executed {
        return "branchExecuted".into();
    }
    "blocked".into()
}

fn best_friend_operate_verdict(status: &str) -> String {
    match status {
        "readyToSend" => "checkedMessageReadyAfterOperate",
        "studioPublishRequired" => "publishPilotBeforeSpeaking",
        "branchExecuted" => "refreshControlBeforeNextMove",
        "dryRun" => "selectedBranchNotExecuted",
        _ => "operateBlocked",
    }
    .into()
}

fn best_friend_operate_next_actions(
    run_dir: &Path,
    root: &Path,
    limit: usize,
    status: &str,
    selected_branch: &str,
    selected_command: Option<String>,
    companion_message: Option<&str>,
    active_control: &BestFriendControlReport,
) -> Vec<CoachAction> {
    let run_arg = command_arg(run_dir.to_string_lossy().as_ref());
    let root_arg = command_arg(root.to_string_lossy().as_ref());
    let mut actions = Vec::new();
    match status {
        "readyToSend" => actions.push(coach_action(
            1,
            "Send checked companion message",
            None,
            companion_message.unwrap_or("Send companionMessage exactly; refresh operate before any next action."),
            false,
            false,
        )),
        "studioPublishRequired" => {
            if let Some(action) = active_control.next_actions.first().cloned() {
                actions.push(action);
            }
        }
        "dryRun" => actions.push(coach_action(
            1,
            "Run selected operate branch for real",
            Some(format!(
                "rs autopilot best-friend-operate {run_arg} --root {root_arg} --limit {limit} --format json"
            )),
            "Execute the selected branch after reviewing the dry-run receipt.",
            false,
            false,
        )),
        _ => {
            if let Some(action) = active_control.next_actions.first().cloned() {
                actions.push(action);
            } else if let Some(command) = selected_command {
                actions.push(coach_action(
                    1,
                    "Run selected branch manually",
                    Some(command),
                    "best-friend-operate could not complete the branch automatically; inspect the receipt before continuing.",
                    selected_branch == "publishPilot",
                    false,
                ));
            }
        }
    }
    actions.push(coach_action(
        90,
        "Refresh best-friend operate",
        Some(format!(
            "rs autopilot best-friend-operate {run_arg} --root {root_arg} --limit {limit} --format json"
        )),
        "Rerun operate after any branch, Studio publish, or creator message.",
        false,
        false,
    ));
    actions
}

fn build_best_friend_operate_steps(
    status: &str,
    selected_branch: &str,
    executed: bool,
    selected_command: Option<&str>,
    companion_message: Option<&str>,
) -> Vec<String> {
    let mut steps = vec![format!(
        "Selected branch `{selected_branch}` from best-friend-control."
    )];
    if executed {
        steps.push("Executed exactly one selected offline branch and refreshed control.".into());
    } else if status == "readyToSend" {
        steps.push(format!(
            "Send this checked message exactly: {}",
            companion_message.unwrap_or("missing companionMessage; rerun best-friend-control")
        ));
    } else if status == "studioPublishRequired" {
        steps.push(format!(
            "Run `{}` with a connected Studio panel before speaking.",
            selected_command.unwrap_or("rs autopilot publish-review")
        ));
    } else {
        steps.push("No branch was executed; inspect blockers and nextActions.".into());
    }
    steps.push(
        "Stop after this receipt; refresh best-friend-operate before any second move.".into(),
    );
    steps
}

fn build_best_friend_runner_report(
    options: &BestFriendRunnerOptions,
    runner_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<BestFriendRunnerReport> {
    if !options.run_dir.is_dir() {
        return Err(AppError::Other(format!(
            "autopilot best-friend-runner run directory does not exist: {}",
            options.run_dir.display()
        )));
    }

    let write_markdown = markdown_path.is_some();
    let mut artifacts = BTreeMap::new();
    artifacts.insert(
        "bestFriendRunner".into(),
        runner_path.to_string_lossy().to_string(),
    );
    if let Some(path) = markdown_path {
        artifacts.insert(
            "bestFriendRunnerMarkdown".into(),
            path.to_string_lossy().to_string(),
        );
    }

    let mut steps = Vec::new();
    let mut safe_to_say = Vec::new();
    let mut do_not_say = Vec::new();
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let mut next_actions = Vec::new();
    let mut companion_message = None;
    let mut last_branch = None;
    let mut executed_steps = 0;
    let mut status = "maxStepsReached".to_string();
    let mut stopped_reason = "step limit reached".to_string();
    let mut executed_signatures = BTreeSet::new();

    if options.max_steps == 0 {
        status = "blocked".into();
        stopped_reason = "maxSteps must be greater than zero".into();
        blockers.push("best-friend-runner requires --max-steps greater than zero".into());
    } else {
        for step_index in 1..=options.max_steps {
            let prefix = format!("best-friend-runner-step-{step_index:02}");
            let operate_path = options.run_dir.join(format!("{prefix}.json"));
            let operate_markdown_path =
                write_markdown.then(|| options.run_dir.join(format!("{prefix}.md")));
            let operate_options = BestFriendOperateOptions {
                prompt: options.prompt.clone(),
                run_dir: options.run_dir.clone(),
                root: options.root.clone(),
                limit: options.limit,
                opportunity: options.opportunity.clone(),
                max_chars: options.max_chars,
                dry_run: options.dry_run,
                artifact_prefix: Some(prefix.clone()),
                out: Some(operate_path.clone()),
                markdown: operate_markdown_path.clone(),
                no_markdown: !write_markdown,
                json: false,
            };
            let operate = build_best_friend_operate_report(
                &operate_options,
                &operate_path,
                operate_markdown_path.as_deref(),
            )?;
            write_json(operate_path.clone(), &operate)?;
            if let Some(path) = operate_markdown_path.clone() {
                write_best_friend_operate_markdown(path, &operate)?;
            }

            let step_key = format!("bestFriendRunnerStep{step_index:02}");
            artifacts.insert(step_key.clone(), operate_path.to_string_lossy().to_string());
            if let Some(path) = &operate_markdown_path {
                artifacts.insert(
                    format!("{step_key}Markdown"),
                    path.to_string_lossy().to_string(),
                );
            }
            for (key, path) in &operate.artifacts {
                artifacts.insert(format!("{step_key}{key}"), path.clone());
            }

            if operate.executed {
                executed_steps += 1;
                executed_signatures.insert(best_friend_runner_branch_signature(
                    &operate.selected_branch,
                    operate.selected_command.as_deref(),
                ));
            }
            last_branch = Some(operate.selected_branch.clone());
            if operate.companion_message.is_some() {
                companion_message = operate.companion_message.clone();
            }
            safe_to_say.extend(operate.safe_to_say.clone());
            do_not_say.extend(operate.do_not_say.clone());
            blockers.extend(operate.blockers.clone());
            warnings.extend(operate.warnings.clone());
            next_actions = operate.next_actions.clone();

            let step = BestFriendRunnerStep {
                step_index,
                operate_path: operate_path.to_string_lossy().to_string(),
                markdown_path: operate_markdown_path
                    .as_ref()
                    .map(|path| path.to_string_lossy().to_string()),
                status: operate.status.clone(),
                verdict: operate.verdict.clone(),
                selected_branch: operate.selected_branch.clone(),
                executed: operate.executed,
                branch_status: operate.branch_status.clone(),
                before_control_status: operate.before_control_status.clone(),
                after_control_status: operate.after_control_status.clone(),
                selected_command: operate.selected_command.clone(),
                executed_command: operate.executed_command.clone(),
                companion_message: operate.companion_message.clone(),
                blockers: operate.blockers.clone(),
                warnings: operate.warnings.clone(),
                next_actions: operate.next_actions.clone(),
                operate,
            };

            let step_status = step.status.clone();
            let active_signature = best_friend_runner_active_signature(&step.operate);
            steps.push(step);

            match step_status.as_str() {
                "readyToSend" => {
                    status = "readyToSend".into();
                    stopped_reason = "checked companion message is ready".into();
                    break;
                }
                "studioPublishRequired" => {
                    status = "studioPublishRequired".into();
                    stopped_reason = "Studio publish is required before speaking".into();
                    break;
                }
                "blocked" => {
                    status = "blocked".into();
                    stopped_reason = "operator step reported blockers".into();
                    break;
                }
                "dryRun" => {
                    status = "dryRun".into();
                    stopped_reason =
                        "dry-run selected the first branch without executing it".into();
                    break;
                }
                _ => {}
            }

            if let Some(signature) = active_signature {
                if executed_signatures.contains(&signature) {
                    status = "repeatBoundary".into();
                    stopped_reason =
                        "next control branch would repeat an already executed branch".into();
                    break;
                }
            }
        }
    }

    if steps.is_empty() && blockers.is_empty() {
        status = "blocked".into();
        stopped_reason = "no operator steps were produced".into();
        blockers.push("best-friend-runner did not produce any operator receipts".into());
    }

    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    dedup_next_actions(&mut next_actions);

    if next_actions.is_empty() {
        next_actions = best_friend_runner_next_actions(
            &options.run_dir,
            &options.root,
            options.limit,
            &status,
            companion_message.as_deref(),
        );
    }
    if status == "repeatBoundary" || status == "maxStepsReached" {
        next_actions = best_friend_runner_next_actions(
            &options.run_dir,
            &options.root,
            options.limit,
            &status,
            companion_message.as_deref(),
        );
    }

    let verdict = best_friend_runner_verdict(&status);
    let agent_brief = format!(
        "Best-friend runner is {status}: {} step(s), {} executed, stopped because {stopped_reason}. Next `{}`.",
        steps.len(),
        executed_steps,
        next_actions
            .first()
            .and_then(|action| action.command.as_deref())
            .unwrap_or("send checked companionMessage")
    );

    Ok(BestFriendRunnerReport {
        schema_version: "rs.autopilot.best-friend-runner.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        root: options.root.to_string_lossy().to_string(),
        runner_path: runner_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict,
        dry_run: options.dry_run,
        max_steps: options.max_steps,
        executed_steps,
        stopped_reason,
        last_branch,
        companion_message,
        steps,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
    })
}

fn best_friend_runner_branch_signature(branch: &str, command: Option<&str>) -> String {
    format!("{}::{}", branch, command.unwrap_or(""))
}

fn best_friend_runner_active_signature(report: &BestFriendOperateReport) -> Option<String> {
    let control = report
        .after_control
        .as_ref()
        .unwrap_or(&report.before_control);
    if matches!(control.selected_branch.as_str(), "speak" | "publishPilot") {
        return None;
    }
    Some(best_friend_runner_branch_signature(
        &control.selected_branch,
        control.selected_command.as_deref(),
    ))
}

fn best_friend_runner_verdict(status: &str) -> String {
    match status {
        "readyToSend" => "checkedMessageReadyAfterRunner",
        "studioPublishRequired" => "publishPilotBeforeSpeaking",
        "repeatBoundary" => "stoppedBeforeRepeatedBranch",
        "maxStepsReached" => "operatorStepLimitReached",
        "dryRun" => "firstOperatorStepSelected",
        _ => "runnerBlocked",
    }
    .into()
}

fn best_friend_runner_next_actions(
    run_dir: &Path,
    root: &Path,
    limit: usize,
    status: &str,
    companion_message: Option<&str>,
) -> Vec<CoachAction> {
    let run_arg = command_arg(run_dir.to_string_lossy().as_ref());
    let root_arg = command_arg(root.to_string_lossy().as_ref());
    match status {
        "readyToSend" => vec![coach_action(
            1,
            "Send checked companion message",
            None,
            companion_message.unwrap_or("Send companionMessage exactly; rerun runner before any next action."),
            false,
            false,
        )],
        "dryRun" => vec![coach_action(
            1,
            "Run best-friend runner for real",
            Some(format!(
                "rs autopilot best-friend-runner {run_arg} --root {root_arg} --limit {limit} --format json"
            )),
            "Execute bounded operator steps after reviewing the dry-run receipt.",
            false,
            false,
        )],
        "repeatBoundary" => vec![coach_action(
            1,
            "Refresh control before repeating work",
            Some(format!(
                "rs autopilot best-friend-control {run_arg} --root {root_arg} --limit {limit} --format json"
            )),
            "Runner stopped before repeating an already executed branch; inspect control or rescue before continuing.",
            false,
            false,
        )],
        "maxStepsReached" => vec![coach_action(
            1,
            "Inspect next operator boundary",
            Some(format!(
                "rs autopilot best-friend-operate {run_arg} --root {root_arg} --limit {limit} --dry-run --format json"
            )),
            "The bounded runner hit its step limit; dry-run the next operate step before allowing more work.",
            false,
            false,
        )],
        _ => vec![coach_action(
            1,
            "Recover best-friend runner",
            Some(format!(
                "rs autopilot best-friend-rescue {run_arg} --root {root_arg} --limit {limit} --result failed --format json"
            )),
            "Runner is blocked; recover the companion session before speaking or acting again.",
            false,
            false,
        )],
    }
}

fn build_first_turn_report(
    options: &FirstTurnOptions,
    first_turn_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<FirstTurnReport> {
    if !options.run_dir.is_dir() {
        return Err(AppError::Other(format!(
            "autopilot first-turn run directory does not exist: {}",
            options.run_dir.display()
        )));
    }

    let write_markdown = markdown_path.is_some();
    let artifact_prefix = options
        .artifact_prefix
        .as_deref()
        .map(slug)
        .unwrap_or_else(|| "first-turn".into());
    let before_path = options
        .run_dir
        .join(format!("{artifact_prefix}-best-friend-before.json"));
    let before_markdown_path = write_markdown.then(|| {
        options
            .run_dir
            .join(format!("{artifact_prefix}-best-friend-before.md"))
    });
    let before_options = BestFriendOptions {
        prompt: options.prompt.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        opportunity: options.opportunity.clone(),
        max_chars: options.max_chars,
        out: Some(before_path.clone()),
        markdown: before_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let before_best_friend = build_best_friend_report(
        &before_options,
        &before_path,
        before_markdown_path.as_deref(),
    )?;
    write_json(before_path.clone(), &before_best_friend)?;
    if let Some(path) = before_markdown_path {
        write_best_friend_markdown(path, &before_best_friend)?;
    }

    let selected_action = before_best_friend.first_safe_action.clone();
    let selected_command = selected_action
        .as_ref()
        .and_then(|action| action.command.clone());
    let protected_action = before_best_friend.first_act_action.clone();
    let protected_command = protected_action
        .as_ref()
        .and_then(|action| action.command.clone());
    let selected_inner_command = protected_command
        .as_deref()
        .and_then(extract_act_wrapper_inner_command)
        .or_else(|| selected_command.clone());
    let mut blockers = before_best_friend
        .blockers
        .iter()
        .map(|blocker| format!("best-friend: {blocker}"))
        .collect::<Vec<_>>();
    let mut warnings = before_best_friend.warnings.clone();
    let mut act_report = None;
    let mut executed = false;

    if selected_inner_command.is_none() {
        blockers.push("best-friend did not provide a protected or safe first command".into());
    }
    if protected_command.is_none() && selected_command.is_some() {
        warnings.push(
            "first-turn found a raw first command but no protected act wrapper; it will only run if act accepts the raw command"
                .into(),
        );
    }
    if let Some(inner) = selected_inner_command.clone() {
        if let Some(reason) = act_refusal_reason(&inner) {
            blockers.push(format!("first action refused by act: {reason}"));
        } else if options.dry_run {
            warnings.push(
                "first-turn dry-run selected the protected first action without executing it"
                    .into(),
            );
        } else if blockers.is_empty() {
            let act_path = options.run_dir.join(format!("{artifact_prefix}-act.json"));
            let act_markdown_path =
                write_markdown.then(|| options.run_dir.join(format!("{artifact_prefix}-act.md")));
            let act_options = ActOptions {
                run_dir: options.run_dir.clone(),
                command: Some(inner),
                source: "best-friend".into(),
                root: options.root.clone(),
                limit: options.limit,
                dry_run: false,
                out: Some(act_path.clone()),
                markdown: act_markdown_path.clone(),
                no_markdown: !write_markdown,
                json: false,
            };
            let report = build_act_report(&act_options, &act_path, act_markdown_path.as_deref())?;
            write_json(act_path.clone(), &report)?;
            if let Some(path) = act_markdown_path {
                write_act_markdown(path, &report)?;
            }
            executed = report.executed && report.status == "executed";
            if !executed {
                blockers.extend(
                    report
                        .blockers
                        .iter()
                        .map(|blocker| format!("act: {blocker}")),
                );
            }
            act_report = Some(report);
        }
    }

    let after_path = options.run_dir.join("best-friend.json");
    let after_markdown_path = write_markdown.then(|| options.run_dir.join("best-friend.md"));
    let after_options = BestFriendOptions {
        prompt: options.prompt.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        opportunity: options.opportunity.clone(),
        max_chars: options.max_chars,
        out: Some(after_path.clone()),
        markdown: after_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let after_best_friend =
        build_best_friend_report(&after_options, &after_path, after_markdown_path.as_deref())?;
    write_json(after_path.clone(), &after_best_friend)?;
    if let Some(path) = after_markdown_path {
        write_best_friend_markdown(path, &after_best_friend)?;
    }

    let status = if !blockers.is_empty() {
        if act_report.as_ref().is_some_and(|report| report.executed) {
            "failed"
        } else {
            "blocked"
        }
    } else if options.dry_run {
        "dryRun"
    } else if executed {
        "advanced"
    } else {
        "blocked"
    }
    .to_string();
    let verdict = match status.as_str() {
        "advanced" => "bestFriendFirstActionExecuted",
        "dryRun" => "bestFriendFirstActionSelected",
        "blocked" => "bestFriendFirstActionBlocked",
        _ => "bestFriendFirstActionFailed",
    }
    .to_string();

    warnings.sort();
    warnings.dedup();
    blockers.sort();
    blockers.dedup();
    let mut artifacts = collect_planner_run_artifacts(Some(&options.run_dir));
    artifacts.insert(
        "firstTurn".into(),
        first_turn_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "firstTurnMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert(
        "beforeBestFriend".into(),
        before_path.to_string_lossy().to_string(),
    );
    artifacts.insert(
        "bestFriend".into(),
        after_path.to_string_lossy().to_string(),
    );
    let act_status = act_report.as_ref().map(|report| report.status.clone());
    let act_path = act_report.as_ref().map(|report| report.act_path.clone());
    if let Some(path) = &act_path {
        artifacts.insert("firstTurnAct".into(), path.clone());
    }

    let safe_to_say = if executed {
        vec![
            "First-turn executed one best-friend checked offline action through act.".into(),
            "First-turn refreshed the best-friend launch packet after the action.".into(),
        ]
    } else if options.dry_run {
        vec![
            "First-turn selected the protected best-friend first action without executing it."
                .into(),
        ]
    } else {
        vec!["First-turn did not execute a protected first action.".into()]
    };
    let do_not_say = vec![
        "Do not claim first-turn applied, published, uploaded, playtested, or mutated Studio.".into(),
        "Do not claim the creator request is complete from first-turn alone.".into(),
        "Do not execute another action from this receipt without refreshing best-friend or navigator.".into(),
    ];
    let next_actions = build_first_turn_next_actions(&options.run_dir, &status);
    let agent_brief = build_first_turn_agent_brief(&status, selected_inner_command.as_deref());

    Ok(FirstTurnReport {
        schema_version: "rs.autopilot.first-turn.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        root: options.root.to_string_lossy().to_string(),
        first_turn_path: first_turn_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict,
        dry_run: options.dry_run,
        before_best_friend_path: before_path.to_string_lossy().to_string(),
        after_best_friend_path: after_path.to_string_lossy().to_string(),
        before_best_friend_status: before_best_friend.status,
        after_best_friend_status: after_best_friend.status,
        launch_preflight_status: after_best_friend.launch_preflight_status,
        opening_reply: after_best_friend.opening_reply,
        selected_action,
        selected_command,
        protected_action,
        protected_command,
        selected_inner_command,
        act_status,
        act_path,
        executed,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
    })
}

fn build_first_turn_next_actions(run_dir: &Path, status: &str) -> Vec<CoachAction> {
    let run_arg = command_arg(run_dir.to_string_lossy().as_ref());
    match status {
        "advanced" => vec![
            coach_action(
                1,
                "Read refreshed best-friend packet",
                Some(format!("rs autopilot best-friend {run_arg} --format json")),
                "Use the refreshed launch packet before speaking again or taking another action.",
                false,
                false,
            ),
            coach_action(
                2,
                "Refresh proof before stronger claims",
                Some(format!("rs autopilot proof {run_arg} --format json")),
                "Make any stronger creator-facing claims from proof after the first action.",
                false,
                false,
            ),
        ],
        "dryRun" => vec![coach_action(
            1,
            "Run first-turn for real",
            Some(format!("rs autopilot first-turn {run_arg} --format json")),
            "Execute exactly one protected best-friend first action.",
            false,
            false,
        )],
        _ => vec![coach_action(
            1,
            "Refresh best-friend packet",
            Some(format!("rs autopilot best-friend {run_arg} --format json")),
            "Rebuild the launch packet and inspect blockers before trying first-turn again.",
            false,
            false,
        )],
    }
}

fn build_first_turn_agent_brief(status: &str, selected_inner_command: Option<&str>) -> String {
    match status {
        "advanced" => format!(
            "First-turn executed one protected best-friend action through act: `{}`. Read the refreshed best-friend packet before doing anything else.",
            selected_inner_command.unwrap_or("<unknown>")
        ),
        "dryRun" => format!(
            "First-turn dry-run selected `{}` but did not execute it.",
            selected_inner_command.unwrap_or("<unknown>")
        ),
        "blocked" => {
            "First-turn did not execute because best-friend lacked a protected first action or a safety gate blocked it.".into()
        }
        _ => "First-turn attempted the protected action but it failed; inspect first-turn and act receipts.".into(),
    }
}

fn build_best_friend_loop_report(
    options: &BestFriendLoopOptions,
    loop_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<BestFriendLoopReport> {
    if !options.run_dir.is_dir() {
        return Err(AppError::Other(format!(
            "autopilot best-friend-loop run directory does not exist: {}",
            options.run_dir.display()
        )));
    }

    let write_markdown = markdown_path.is_some();
    let max_steps = options.max_steps.max(1);
    let mut attempted_commands = BTreeSet::new();
    let mut steps = Vec::new();
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let mut executed_steps = 0usize;
    let mut stopped_reason = "maxStepsReached".to_string();

    for order in 1..=max_steps {
        let prefix = format!("best-friend-loop-turn-{order:02}");
        let preview_path = options.run_dir.join(format!("{prefix}-preview.json"));
        let preview_markdown_path =
            write_markdown.then(|| options.run_dir.join(format!("{prefix}-preview.md")));
        let preview_options = BestFriendOptions {
            prompt: options.prompt.clone(),
            run_dir: options.run_dir.clone(),
            root: options.root.clone(),
            limit: options.limit,
            opportunity: options.opportunity.clone(),
            max_chars: options.max_chars,
            out: Some(preview_path.clone()),
            markdown: preview_markdown_path.clone(),
            no_markdown: !write_markdown,
            json: false,
        };
        let preview = build_best_friend_report(
            &preview_options,
            &preview_path,
            preview_markdown_path.as_deref(),
        )?;
        write_json(preview_path.clone(), &preview)?;
        if let Some(path) = preview_markdown_path {
            write_best_friend_markdown(path, &preview)?;
        }

        let protected_command = preview
            .first_act_action
            .as_ref()
            .and_then(|action| action.command.clone());
        let selected_inner_command = protected_command
            .as_deref()
            .and_then(extract_act_wrapper_inner_command)
            .or_else(|| {
                preview
                    .first_safe_action
                    .as_ref()
                    .and_then(|action| action.command.clone())
            });
        let mut step_blockers = preview
            .blockers
            .iter()
            .map(|blocker| format!("best-friend: {blocker}"))
            .collect::<Vec<_>>();
        let mut step_warnings = preview.warnings.clone();

        if selected_inner_command.is_none() {
            step_blockers.push("best-friend-loop found no safe first command".into());
        }
        if let Some(command) = selected_inner_command.as_deref() {
            if attempted_commands.contains(command) {
                stopped_reason = "repeatedCommand".into();
                step_warnings.push(format!(
                    "best-friend-loop stopped before repeating `{command}`"
                ));
                steps.push(BestFriendLoopStep {
                    order,
                    status: "repeatedCommand".into(),
                    verdict: "stoppedBeforeDuplicateAction".into(),
                    preview_path: preview_path.to_string_lossy().to_string(),
                    first_turn_path: None,
                    act_path: None,
                    selected_inner_command: Some(command.to_string()),
                    protected_command,
                    executed: false,
                    blockers: Vec::new(),
                    warnings: step_warnings,
                });
                break;
            }
            if let Some(reason) = act_refusal_reason(command) {
                step_blockers.push(format!("first action refused by act: {reason}"));
            }
        }

        if !step_blockers.is_empty() {
            stopped_reason = "blocked".into();
            blockers.extend(step_blockers.clone());
            warnings.extend(step_warnings.clone());
            steps.push(BestFriendLoopStep {
                order,
                status: "blocked".into(),
                verdict: "bestFriendLoopBlocked".into(),
                preview_path: preview_path.to_string_lossy().to_string(),
                first_turn_path: None,
                act_path: None,
                selected_inner_command,
                protected_command,
                executed: false,
                blockers: step_blockers,
                warnings: step_warnings,
            });
            break;
        }

        if let Some(command) = selected_inner_command.clone() {
            attempted_commands.insert(command);
        }

        let turn_path = options.run_dir.join(format!("{prefix}.json"));
        let turn_markdown_path =
            write_markdown.then(|| options.run_dir.join(format!("{prefix}.md")));
        let turn_options = FirstTurnOptions {
            prompt: options.prompt.clone(),
            run_dir: options.run_dir.clone(),
            root: options.root.clone(),
            limit: options.limit,
            opportunity: options.opportunity.clone(),
            max_chars: options.max_chars,
            dry_run: options.dry_run,
            artifact_prefix: Some(prefix.clone()),
            out: Some(turn_path.clone()),
            markdown: turn_markdown_path.clone(),
            no_markdown: !write_markdown,
            json: false,
        };
        let turn =
            build_first_turn_report(&turn_options, &turn_path, turn_markdown_path.as_deref())?;
        write_json(turn_path.clone(), &turn)?;
        if let Some(path) = turn_markdown_path {
            write_first_turn_markdown(path, &turn)?;
        }
        if turn.executed {
            executed_steps += 1;
        }
        if !turn.blockers.is_empty() {
            blockers.extend(turn.blockers.clone());
        }
        warnings.extend(turn.warnings.clone());

        let status = turn.status.clone();
        let executed = turn.executed;
        let act_path = turn.act_path.clone();
        steps.push(BestFriendLoopStep {
            order,
            status: status.clone(),
            verdict: turn.verdict,
            preview_path: preview_path.to_string_lossy().to_string(),
            first_turn_path: Some(turn_path.to_string_lossy().to_string()),
            act_path,
            selected_inner_command: turn.selected_inner_command,
            protected_command: turn.protected_command,
            executed,
            blockers: turn.blockers,
            warnings: turn.warnings,
        });

        if options.dry_run {
            stopped_reason = "dryRun".into();
            break;
        }
        if status != "advanced" {
            stopped_reason = status;
            break;
        }
    }

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    let status = if options.dry_run {
        "dryRun"
    } else if executed_steps == 0 && !blockers.is_empty() {
        "blocked"
    } else if executed_steps > 0 && !blockers.is_empty() {
        "advancedWithBlocker"
    } else if executed_steps > 0 {
        "advanced"
    } else {
        "stopped"
    }
    .to_string();
    let verdict = match status.as_str() {
        "advanced" => "bestFriendLoopAdvanced",
        "advancedWithBlocker" => "bestFriendLoopAdvancedThenBlocked",
        "dryRun" => "bestFriendLoopDryRun",
        "blocked" => "bestFriendLoopBlocked",
        _ => "bestFriendLoopStopped",
    }
    .to_string();
    let mut artifacts = collect_planner_run_artifacts(Some(&options.run_dir));
    artifacts.insert(
        "bestFriendLoop".into(),
        loop_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "bestFriendLoopMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    for step in &steps {
        artifacts.insert(
            format!("bestFriendLoopTurn{:02}Preview", step.order),
            step.preview_path.clone(),
        );
        if let Some(path) = &step.first_turn_path {
            artifacts.insert(format!("bestFriendLoopTurn{:02}", step.order), path.clone());
        }
        if let Some(path) = &step.act_path {
            artifacts.insert(
                format!("bestFriendLoopTurn{:02}Act", step.order),
                path.clone(),
            );
        }
    }
    let current_best_friend_path = options.run_dir.join("best-friend.json");
    artifacts.insert(
        "bestFriend".into(),
        current_best_friend_path.to_string_lossy().to_string(),
    );

    let safe_to_say = if executed_steps > 0 {
        vec![
            format!(
                "Best-friend loop executed {executed_steps} protected offline turn(s) through act and refreshed best-friend context."
            ),
            format!("Best-friend loop stopped because {stopped_reason}."),
        ]
    } else if options.dry_run {
        vec![
            "Best-friend loop dry-run selected the next protected action without executing it."
                .into(),
        ]
    } else {
        vec!["Best-friend loop did not execute a protected action.".into()]
    };
    let do_not_say = vec![
        "Do not claim best-friend-loop applied, published, uploaded, playtested, or mutated Studio."
            .into(),
        "Do not claim the creator request is complete from best-friend-loop alone.".into(),
        "Do not continue after a repeated command, blocker, or live gate without refreshing evidence."
            .into(),
    ];
    let next_actions = build_best_friend_loop_next_actions(&options.run_dir, &status);
    let agent_brief = format!(
        "Best-friend loop is {status}: executed {executed_steps}/{max_steps} protected turn(s), stopped because `{stopped_reason}`, and refreshed `{}`.",
        current_best_friend_path.to_string_lossy()
    );

    Ok(BestFriendLoopReport {
        schema_version: "rs.autopilot.best-friend-loop.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        root: options.root.to_string_lossy().to_string(),
        loop_path: loop_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict,
        dry_run: options.dry_run,
        max_steps,
        executed_steps,
        stopped_reason,
        current_best_friend_path: current_best_friend_path.to_string_lossy().to_string(),
        steps,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
    })
}

fn build_best_friend_loop_next_actions(run_dir: &Path, status: &str) -> Vec<CoachAction> {
    let run_arg = command_arg(run_dir.to_string_lossy().as_ref());
    match status {
        "advanced" | "advancedWithBlocker" => vec![
            coach_action(
                1,
                "Read refreshed best-friend packet",
                Some(format!("rs autopilot best-friend {run_arg} --format json")),
                "Use the refreshed packet and receipts before reporting or taking more action.",
                false,
                false,
            ),
            coach_action(
                2,
                "Run self-check before speaking",
                Some(format!("rs autopilot self-check {run_arg} --format json")),
                "Preflight the next creator-facing wording or command queue.",
                false,
                false,
            ),
        ],
        "dryRun" => vec![coach_action(
            1,
            "Run best-friend-loop for real",
            Some(format!(
                "rs autopilot best-friend-loop {run_arg} --format json"
            )),
            "Execute bounded protected turns after reviewing the dry-run selection.",
            false,
            false,
        )],
        _ => vec![coach_action(
            1,
            "Refresh best-friend packet",
            Some(format!("rs autopilot best-friend {run_arg} --format json")),
            "Inspect blockers and refresh the launch packet before trying the loop again.",
            false,
            false,
        )],
    }
}

fn build_best_friend_reply_report(
    options: &BestFriendReplyOptions,
    reply_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<BestFriendReplyReport> {
    if !options.run_dir.is_dir() {
        return Err(AppError::Other(format!(
            "autopilot best-friend-reply run directory does not exist: {}",
            options.run_dir.display()
        )));
    }

    let loop_path = options.run_dir.join("best-friend-loop.json");
    let first_turn_path = options.run_dir.join("first-turn.json");
    let best_friend_path = options.run_dir.join("best-friend.json");
    let (source_artifact, checked_claim, mut message) = if loop_path.exists() {
        let value = read_json_file(&loop_path)?;
        let executed_steps = value
            .get("executedSteps")
            .and_then(Value::as_u64)
            .unwrap_or(0);
        (
            Some(loop_path.to_string_lossy().to_string()),
            format!(
                "Best-friend loop executed {executed_steps} protected offline turn(s) through act and refreshed best-friend context."
            ),
            String::new(),
        )
    } else if first_turn_path.exists() {
        let value = read_json_file(&first_turn_path)?;
        let status = string_field(&value, "status").unwrap_or_else(|| "unknown".into());
        let checked_claim = value
            .get("safeToSay")
            .and_then(Value::as_array)
            .and_then(|items| {
                items.iter().find_map(|item| {
                    let text = item.as_str()?;
                    (!text.to_ascii_lowercase().contains("executed")).then(|| text.to_string())
                })
            })
            .unwrap_or_else(|| format!("First-turn receipt is present with status {status}."));
        (
            Some(first_turn_path.to_string_lossy().to_string()),
            checked_claim,
            String::new(),
        )
    } else if best_friend_path.exists() {
        let value = read_json_file(&best_friend_path)?;
        let status = string_field(&value, "status").unwrap_or_else(|| "unknown".into());
        (
            Some(best_friend_path.to_string_lossy().to_string()),
            format!("Best-friend packet status is {status}."),
            format!(
                "I prepared the best-friend packet with status `{status}`. I have not used its protected first action yet, and I will use the protected command path before making claims about progress."
            ),
        )
    } else {
        (
            None,
            "No best-friend, first-turn, or best-friend-loop receipt exists yet.".into(),
            "I do not have a best-friend receipt yet, so I need to create one before claiming progress or taking the next action.".into(),
        )
    };
    if message.is_empty() {
        message = checked_claim.clone();
    }

    let self_check_path = options.run_dir.join("best-friend-reply-self-check.json");
    let self_check_markdown_path = markdown_path
        .is_some()
        .then(|| options.run_dir.join("best-friend-reply-self-check.md"));
    let command = format!(
        "rs autopilot best-friend {} --root {} --format json",
        command_arg(options.run_dir.to_string_lossy().as_ref()),
        command_arg(options.root.to_string_lossy().as_ref())
    );
    let self_check_options = SelfCheckOptions {
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        claims: vec![checked_claim.clone()],
        messages: vec![message.clone()],
        commands: vec![command],
        from_file: None,
        out: Some(self_check_path.clone()),
        markdown: self_check_markdown_path.clone(),
        no_markdown: markdown_path.is_none(),
        json: false,
    };
    let self_check = build_self_check_report(
        &self_check_options,
        &self_check_path,
        self_check_markdown_path.as_deref(),
    )?;
    write_self_check_child_artifacts(&self_check, markdown_path.is_some())?;
    write_json(self_check_path.clone(), &self_check)?;
    if let Some(path) = self_check_markdown_path.clone() {
        write_self_check_markdown(path, &self_check)?;
    }

    let mut blockers = self_check.blockers.clone();
    if source_artifact.is_none() {
        blockers.push(
            "best-friend-reply needs best-friend, first-turn, or best-friend-loop evidence".into(),
        );
    }
    blockers.sort();
    blockers.dedup();
    let mut warnings = self_check.warnings.clone();
    warnings.sort();
    warnings.dedup();
    let status = if !blockers.is_empty() || !self_check.safe_to_proceed {
        "blocked"
    } else if self_check.speak_ready {
        "readyToSend"
    } else {
        "needsRewrite"
    }
    .to_string();
    let verdict = match status.as_str() {
        "readyToSend" => "checkedCreatorReplyReady",
        "needsRewrite" => "rewriteBeforeSpeaking",
        _ => "replyBlocked",
    }
    .to_string();
    let mut artifacts = collect_planner_run_artifacts(Some(&options.run_dir));
    artifacts.insert(
        "bestFriendReply".into(),
        reply_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "bestFriendReplyMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert(
        "bestFriendReplySelfCheck".into(),
        self_check.self_check_path.clone(),
    );
    if let Some(path) = &self_check.markdown_path {
        artifacts.insert("bestFriendReplySelfCheckMarkdown".into(), path.clone());
    }
    artifacts.extend(self_check.artifacts.clone());
    let mut do_not_say = self_check.do_not_say.clone();
    do_not_say
        .push("Do not claim best-friend-reply executed work; it only checked the wording.".into());
    do_not_say.sort();
    do_not_say.dedup();
    let next_actions = build_best_friend_reply_next_actions(&options.run_dir, &status);
    let agent_brief = format!(
        "Best-friend reply is {status}: source `{}`, self-check `{}`.",
        source_artifact.as_deref().unwrap_or("<missing>"),
        self_check.status
    );

    Ok(BestFriendReplyReport {
        schema_version: "rs.autopilot.best-friend-reply.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        reply_path: reply_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict,
        source_artifact,
        message,
        checked_claim,
        self_check_path: self_check.self_check_path.clone(),
        self_check_markdown_path: self_check.markdown_path.clone(),
        safe_to_say: self_check.safe_to_say.clone(),
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        self_check,
    })
}

fn build_best_friend_reply_next_actions(run_dir: &Path, status: &str) -> Vec<CoachAction> {
    let run_arg = command_arg(run_dir.to_string_lossy().as_ref());
    match status {
        "readyToSend" => vec![coach_action(
            1,
            "Read checked reply",
            Some(format!(
                "rs autopilot best-friend-reply {run_arg} --format json"
            )),
            "Use the checked message exactly, then refresh best-friend before another action.",
            false,
            false,
        )],
        _ => vec![coach_action(
            1,
            "Refresh best-friend evidence",
            Some(format!("rs autopilot best-friend {run_arg} --format json")),
            "Create or refresh the launch evidence before drafting another reply.",
            false,
            false,
        )],
    }
}

fn build_best_friend_turn_report(
    options: &BestFriendTurnOptions,
    turn_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<BestFriendTurnReport> {
    if !options.run_dir.is_dir() {
        return Err(AppError::Other(format!(
            "autopilot best-friend-turn run directory does not exist: {}",
            options.run_dir.display()
        )));
    }

    let write_markdown = markdown_path.is_some();
    let mut steps = Vec::new();
    let mut safe_to_say = Vec::new();
    let mut do_not_say = Vec::new();
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let mut artifacts = collect_planner_run_artifacts(Some(&options.run_dir));
    artifacts.insert(
        "bestFriendTurn".into(),
        turn_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "bestFriendTurnMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    let mut chat_report = None;
    if let Some(message) = options
        .message
        .as_deref()
        .map(str::trim)
        .filter(|text| !text.is_empty())
    {
        let chat_path = options.run_dir.join("chat.json");
        let chat_markdown_path = write_markdown.then(|| options.run_dir.join("chat.md"));
        let chat_options = ChatOptions {
            port: options.port,
            message: Some(message.to_string()),
            run_dir: Some(options.run_dir.clone()),
            studio: None,
            scope: "Workspace".into(),
            root: options.root.clone(),
            limit: options.limit,
            source: options.source.clone(),
            assume: false,
            smoke: None,
            max_steps: 0,
            dry_run: options.dry_run,
            out: Some(chat_path.clone()),
            markdown: chat_markdown_path.clone(),
            no_markdown: !write_markdown,
            json: false,
        };
        let (selected_run, mut selection_warnings) = select_chat_run(&chat_options)?;
        let report = build_chat_report(
            &chat_options,
            selected_run,
            &chat_path,
            chat_markdown_path.as_deref(),
            &mut selection_warnings,
        )?;
        write_json(chat_path.clone(), &report)?;
        if let Some(path) = chat_markdown_path {
            write_chat_markdown(path, &report)?;
        }
        steps.push(best_friend_turn_step(
            "BFT-001",
            "Route creator message",
            &report.status,
            &report.agent_brief,
            best_friend_turn_artifacts(
                &report.artifacts,
                &["chat", "handle", "conversation", "response"],
            ),
        ));
        safe_to_say.extend(report.safe_to_say.clone());
        do_not_say.extend(report.do_not_say.clone());
        blockers.extend(report.blockers.clone());
        warnings.extend(report.warnings.clone());
        artifacts.extend(report.artifacts.clone());
        chat_report = Some(report);
    }

    let chat_status = chat_report.as_ref().map(|report| report.status.clone());
    let live_gate_required = chat_status.as_deref() == Some("approvalGateRequired");
    let mut loop_report = None;
    if blockers.is_empty() && !live_gate_required {
        let loop_path = options.run_dir.join("best-friend-loop.json");
        let loop_markdown_path =
            write_markdown.then(|| options.run_dir.join("best-friend-loop.md"));
        let report = build_best_friend_loop_report(
            &BestFriendLoopOptions {
                prompt: options.prompt.clone(),
                run_dir: options.run_dir.clone(),
                root: options.root.clone(),
                limit: options.limit,
                opportunity: options.opportunity.clone(),
                max_chars: options.max_chars,
                max_steps: options.max_steps,
                dry_run: options.dry_run,
                out: Some(loop_path.clone()),
                markdown: loop_markdown_path.clone(),
                no_markdown: !write_markdown,
                json: false,
            },
            &loop_path,
            loop_markdown_path.as_deref(),
        )?;
        write_json(loop_path.clone(), &report)?;
        if let Some(path) = loop_markdown_path {
            write_best_friend_loop_markdown(path, &report)?;
        }
        steps.push(best_friend_turn_step(
            "BFT-002",
            "Run protected best-friend loop",
            &report.status,
            &report.agent_brief,
            best_friend_turn_artifacts(
                &report.artifacts,
                &[
                    "bestFriendLoop",
                    "bestFriend",
                    "bestFriendLoopTurn01",
                    "bestFriendLoopTurn01Act",
                ],
            ),
        ));
        safe_to_say.extend(report.safe_to_say.clone());
        do_not_say.extend(report.do_not_say.clone());
        blockers.extend(report.blockers.clone());
        warnings.extend(report.warnings.clone());
        artifacts.extend(report.artifacts.clone());
        loop_report = Some(report);
    } else if live_gate_required {
        warnings.push(
            "best-friend-turn skipped protected work because chat preserved an approval/live gate"
                .into(),
        );
    }

    let mut reply_report = None;
    if !options.dry_run
        && loop_report
            .as_ref()
            .is_some_and(|report| report.status != "blocked")
    {
        let reply_path = options.run_dir.join("best-friend-reply.json");
        let reply_markdown_path =
            write_markdown.then(|| options.run_dir.join("best-friend-reply.md"));
        let report = build_best_friend_reply_report(
            &BestFriendReplyOptions {
                run_dir: options.run_dir.clone(),
                root: options.root.clone(),
                limit: options.limit,
                out: Some(reply_path.clone()),
                markdown: reply_markdown_path.clone(),
                no_markdown: !write_markdown,
                json: false,
            },
            &reply_path,
            reply_markdown_path.as_deref(),
        )?;
        write_json(reply_path.clone(), &report)?;
        if let Some(path) = reply_markdown_path {
            write_best_friend_reply_markdown(path, &report)?;
        }
        steps.push(best_friend_turn_step(
            "BFT-003",
            "Draft checked best-friend reply",
            &report.status,
            &report.agent_brief,
            best_friend_turn_artifacts(
                &report.artifacts,
                &["bestFriendReply", "bestFriendReplySelfCheck"],
            ),
        ));
        safe_to_say.extend(report.safe_to_say.clone());
        do_not_say.extend(report.do_not_say.clone());
        blockers.extend(report.blockers.clone());
        warnings.extend(report.warnings.clone());
        artifacts.extend(report.artifacts.clone());
        reply_report = Some(report);
    } else if options.dry_run {
        warnings.push("best-friend-turn dry-run skipped the final checked reply".into());
    }

    safe_to_say.push(
        "Best-friend turn used local offline artifacts for routing, protected work, and checked reply preparation."
            .into(),
    );
    do_not_say.push(
        "Do not claim best-friend-turn applied, published, uploaded, playtested, or mutated Studio."
            .into(),
    );
    do_not_say.push(
        "Do not treat best-friend-turn as creator approval for live apply or publish.".into(),
    );
    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let loop_status = loop_report.as_ref().map(|report| report.status.clone());
    let reply_status = reply_report.as_ref().map(|report| report.status.clone());
    let response_message = chat_report
        .as_ref()
        .and_then(|report| report.response_message.clone());
    let best_friend_message = reply_report.as_ref().map(|report| report.message.clone());
    let status = best_friend_turn_status(
        options.dry_run,
        &blockers,
        chat_status.as_deref(),
        loop_status.as_deref(),
        reply_status.as_deref(),
    );
    let verdict = best_friend_turn_verdict(&status);
    let next_actions = build_best_friend_turn_next_actions(&options.run_dir, &status);
    let agent_brief = format!(
        "Best-friend turn is {status}: chat={}, loop={}, reply={}. Use bestFriendMessage only when status is readyToSend.",
        chat_status.as_deref().unwrap_or("skipped"),
        loop_status.as_deref().unwrap_or("skipped"),
        reply_status.as_deref().unwrap_or("skipped")
    );

    Ok(BestFriendTurnReport {
        schema_version: "rs.autopilot.best-friend-turn.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        root: options.root.to_string_lossy().to_string(),
        turn_path: turn_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        prompt: options.prompt.as_deref().map(redact_text),
        message: options.message.as_deref().map(redact_text),
        status,
        verdict,
        dry_run: options.dry_run,
        max_steps: options.max_steps,
        steps,
        chat_status,
        loop_status,
        reply_status,
        response_message,
        best_friend_message,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        chat: chat_report,
        best_friend_loop: loop_report,
        best_friend_reply: reply_report,
    })
}

fn best_friend_turn_step(
    id: &str,
    title: &str,
    status: &str,
    summary: &str,
    artifacts: Vec<String>,
) -> BestFriendTurnStep {
    BestFriendTurnStep {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        summary: summary.into(),
        artifacts,
    }
}

fn best_friend_turn_artifacts(artifacts: &BTreeMap<String, String>, keys: &[&str]) -> Vec<String> {
    keys.iter()
        .filter_map(|key| artifacts.get(*key).cloned())
        .collect()
}

fn best_friend_turn_status(
    dry_run: bool,
    blockers: &[String],
    chat_status: Option<&str>,
    loop_status: Option<&str>,
    reply_status: Option<&str>,
) -> String {
    if chat_status == Some("approvalGateRequired") {
        "approvalGateRequired"
    } else if !blockers.is_empty() {
        "blocked"
    } else if dry_run {
        "dryRun"
    } else if reply_status == Some("readyToSend") {
        "readyToSend"
    } else if reply_status.is_some() {
        "needsRewrite"
    } else if loop_status.is_some() {
        "actedNeedsReply"
    } else {
        "handled"
    }
    .into()
}

fn best_friend_turn_verdict(status: &str) -> String {
    match status {
        "readyToSend" => "bestFriendTurnReadyToSend",
        "needsRewrite" => "bestFriendTurnNeedsRewrite",
        "actedNeedsReply" => "bestFriendTurnNeedsReply",
        "dryRun" => "bestFriendTurnDryRun",
        "approvalGateRequired" => "bestFriendTurnLiveGatePreserved",
        "handled" => "bestFriendTurnHandled",
        _ => "bestFriendTurnBlocked",
    }
    .into()
}

fn build_best_friend_turn_next_actions(run_dir: &Path, status: &str) -> Vec<CoachAction> {
    let run_arg = command_arg(run_dir.to_string_lossy().as_ref());
    match status {
        "readyToSend" => vec![
            coach_action(
                1,
                "Send checked best-friend reply",
                None,
                "Use bestFriendMessage exactly; change the wording only after another self-check.",
                false,
                false,
            ),
            coach_action(
                2,
                "Refresh best-friend packet",
                Some(format!("rs autopilot best-friend {run_arg} --format json")),
                "Refresh the launch context before taking another protected action.",
                false,
                false,
            ),
        ],
        "dryRun" => vec![coach_action(
            1,
            "Run best-friend-turn for real",
            Some(format!(
                "rs autopilot best-friend-turn {run_arg} --format json"
            )),
            "Execute the protected loop and checked reply after reviewing the dry-run.",
            false,
            false,
        )],
        "approvalGateRequired" => vec![coach_action(
            1,
            "Review live gate",
            Some(format!(
                "rs autopilot live-gate --run-dir {run_arg} --format json"
            )),
            "Keep live apply, publish, and upload behind explicit gate artifacts.",
            true,
            false,
        )],
        "needsRewrite" | "actedNeedsReply" => vec![coach_action(
            1,
            "Draft checked reply",
            Some(format!(
                "rs autopilot best-friend-reply {run_arg} --format json"
            )),
            "Create or repair the checked reply before speaking to the creator.",
            false,
            false,
        )],
        _ => vec![coach_action(
            1,
            "Inspect best-friend-turn receipt",
            Some(format!(
                "rs autopilot best-friend-turn {run_arg} --dry-run --format json"
            )),
            "Review the route, blockers, and protected-action selection before trying again.",
            false,
            false,
        )],
    }
}

fn build_best_friend_session_report(
    options: &BestFriendSessionOptions,
    session_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<BestFriendSessionReport> {
    let write_markdown = markdown_path.is_some();
    let base_dir = session_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let prompt = options
        .prompt
        .as_deref()
        .map(str::trim)
        .filter(|text| !text.is_empty())
        .map(str::to_string);
    let message = options
        .message
        .as_deref()
        .map(str::trim)
        .filter(|text| !text.is_empty())
        .map(str::to_string);
    let mut artifacts = BTreeMap::from([(
        "bestFriendSession".into(),
        session_path.to_string_lossy().to_string(),
    )]);
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "bestFriendSessionMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let mut safe_to_say = Vec::new();
    let mut do_not_say = Vec::new();
    let mut next_actions = Vec::new();
    let mut bootstrap_session = None;
    let mut bootstrap_start = None;
    let mut mode = "resume".to_string();

    let mut run_dir = options
        .run_dir
        .as_ref()
        .filter(|path| path.is_dir())
        .cloned();
    if run_dir.is_none() {
        mode = "bootstrap".into();
        let bootstrap_prompt = prompt.clone().or_else(|| message.clone());
        if options.scout.is_some() || options.survey.is_some() || options.context.is_some() {
            let bootstrap_path = base_dir.join("session.json");
            let bootstrap_markdown_path = write_markdown.then(|| base_dir.join("session.md"));
            let bootstrap_options = SessionOptions {
                port: options.port,
                prompt: bootstrap_prompt,
                scout: options.scout.clone(),
                survey: options.survey.clone(),
                context: options.context.clone(),
                root: options.root.clone(),
                run_dir: options.run_dir.clone(),
                scope: options.scope.clone(),
                limit: options.limit,
                assume: options.assume,
                smoke: options.smoke.clone(),
                out: Some(bootstrap_path.clone()),
                markdown: bootstrap_markdown_path.clone(),
                no_markdown: !write_markdown,
                json: false,
            };
            let report = build_session_report(
                &bootstrap_options,
                &bootstrap_path,
                bootstrap_markdown_path.as_deref(),
            )?;
            write_json(bootstrap_path.clone(), &report)?;
            if let Some(path) = bootstrap_markdown_path {
                write_session_markdown(path, &report)?;
            }
            run_dir = report.run_dir.as_ref().map(PathBuf::from);
            artifacts.insert("session".into(), report.session_path.clone());
            if let Some(path) = &report.markdown_path {
                artifacts.insert("sessionMarkdown".into(), path.clone());
            }
            artifacts.extend(report.artifacts.clone());
            blockers.extend(report.blockers.clone());
            warnings.extend(report.warnings.clone());
            do_not_say.extend(report.do_not_do.clone());
            next_actions.extend(report.next_actions.clone());
            bootstrap_session = Some(report);
        } else if let Some(prompt_text) = bootstrap_prompt {
            let planned_run_dir = options
                .run_dir
                .clone()
                .unwrap_or_else(|| options.root.join(slug(&prompt_text)));
            let start_path = planned_run_dir.join("start.json");
            let start_markdown_path = write_markdown.then(|| planned_run_dir.join("start.md"));
            let start_options = StartOptions {
                port: options.port,
                prompt: Some(prompt_text),
                studio: None,
                scope: options.scope.clone().unwrap_or_else(|| "Workspace".into()),
                root: options.root.clone(),
                run_dir: Some(planned_run_dir.clone()),
                limit: options.limit,
                assume: options.assume,
                smoke: options.smoke.clone(),
                out: Some(start_path.clone()),
                markdown: start_markdown_path.clone(),
                no_markdown: !write_markdown,
                json: false,
            };
            let report =
                build_start_report(&start_options, &start_path, start_markdown_path.as_deref())?;
            write_json(start_path.clone(), &report)?;
            if let Some(path) = start_markdown_path {
                write_start_markdown(path, &report)?;
            }
            run_dir = report.run_dir.as_ref().map(PathBuf::from);
            artifacts.insert("start".into(), report.start_path.clone());
            if let Some(path) = &report.markdown_path {
                artifacts.insert("startMarkdown".into(), path.clone());
            }
            artifacts.extend(report.artifacts.clone());
            blockers.extend(report.blockers.clone());
            warnings.extend(report.warnings.clone());
            next_actions.extend(report.next_actions.clone());
            bootstrap_start = Some(report);
        }
    }

    if run_dir.is_none() && blockers.is_empty() {
        blockers.push(
            "best-friend-session needs an existing --run-dir or a prompt/session that bootstraps one"
                .into(),
        );
    }

    let mut best_friend_turn = None;
    if blockers.is_empty() {
        if let Some(run_dir_path) = run_dir.clone() {
            let turn_path = run_dir_path.join("best-friend-turn.json");
            let turn_markdown_path =
                write_markdown.then(|| run_dir_path.join("best-friend-turn.md"));
            let turn_message = message
                .clone()
                .or_else(|| (mode == "resume").then(|| prompt.clone()).flatten());
            let turn = build_best_friend_turn_report(
                &BestFriendTurnOptions {
                    port: options.port,
                    prompt: prompt.clone(),
                    message: turn_message,
                    source: options.source.clone(),
                    run_dir: run_dir_path.clone(),
                    root: options.root.clone(),
                    limit: options.limit,
                    opportunity: options.opportunity.clone(),
                    max_chars: options.max_chars,
                    max_steps: options.max_steps,
                    dry_run: options.dry_run,
                    out: Some(turn_path.clone()),
                    markdown: turn_markdown_path.clone(),
                    no_markdown: !write_markdown,
                    json: false,
                },
                &turn_path,
                turn_markdown_path.as_deref(),
            )?;
            write_json(turn_path.clone(), &turn)?;
            if let Some(path) = turn_markdown_path {
                write_best_friend_turn_markdown(path, &turn)?;
            }
            artifacts.insert("bestFriendTurn".into(), turn.turn_path.clone());
            if let Some(path) = &turn.markdown_path {
                artifacts.insert("bestFriendTurnMarkdown".into(), path.clone());
            }
            artifacts.extend(turn.artifacts.clone());
            safe_to_say.extend(turn.safe_to_say.clone());
            do_not_say.extend(turn.do_not_say.clone());
            blockers.extend(turn.blockers.clone());
            warnings.extend(turn.warnings.clone());
            next_actions = turn.next_actions.clone();
            best_friend_turn = Some(turn);
        }
    }

    safe_to_say.push(
        "Best-friend session used local offline artifacts to bootstrap or resume a Roblox build companion turn."
            .into(),
    );
    do_not_say.push(
        "Do not claim best-friend-session applied, published, uploaded, playtested, or mutated Studio."
            .into(),
    );
    do_not_say.push(
        "Do not treat best-friend-session as live apply approval or production completion proof."
            .into(),
    );
    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    dedup_next_actions(&mut next_actions);

    let bootstrap_status = bootstrap_session
        .as_ref()
        .map(|report| report.status.clone())
        .or_else(|| bootstrap_start.as_ref().map(|report| report.status.clone()));
    let best_friend_turn_status = best_friend_turn
        .as_ref()
        .map(|report| report.status.clone());
    let response_message = best_friend_turn
        .as_ref()
        .and_then(|report| report.response_message.clone());
    let best_friend_message = best_friend_turn
        .as_ref()
        .and_then(|report| report.best_friend_message.clone());
    let status = best_friend_session_status(
        options.dry_run,
        &blockers,
        bootstrap_status.as_deref(),
        best_friend_turn_status.as_deref(),
    );
    let verdict = best_friend_session_verdict(&status);
    if next_actions.is_empty() {
        next_actions = build_best_friend_session_next_actions(run_dir.as_deref(), &status);
    } else if status == "readyToSend" {
        next_actions.insert(
            0,
            coach_action(
                1,
                "Send checked best-friend message",
                None,
                "Use bestFriendMessage exactly; rerun self-check before changing it.",
                false,
                false,
            ),
        );
        dedup_next_actions(&mut next_actions);
    }
    let agent_brief = format!(
        "Best-friend session is {status}: mode={mode}, bootstrap={}, turn={}. Use bestFriendMessage only when status is readyToSend.",
        bootstrap_status.as_deref().unwrap_or("skipped"),
        best_friend_turn_status.as_deref().unwrap_or("skipped")
    );

    Ok(BestFriendSessionReport {
        schema_version: "rs.autopilot.best-friend-session.v1".into(),
        generated_at: now_stamp(),
        session_path: session_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        run_dir: run_dir.map(|path| path.to_string_lossy().to_string()),
        prompt: prompt.as_deref().map(redact_text),
        message: message.as_deref().map(redact_text),
        status,
        verdict,
        mode,
        dry_run: options.dry_run,
        bootstrap_status,
        best_friend_turn_status,
        response_message,
        best_friend_message,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        bootstrap_session,
        bootstrap_start,
        best_friend_turn,
    })
}

fn best_friend_session_status(
    dry_run: bool,
    blockers: &[String],
    bootstrap_status: Option<&str>,
    turn_status: Option<&str>,
) -> String {
    if !blockers.is_empty() {
        "blocked"
    } else if turn_status == Some("approvalGateRequired") {
        "approvalGateRequired"
    } else if dry_run || turn_status == Some("dryRun") {
        "dryRun"
    } else if turn_status == Some("readyToSend") {
        "readyToSend"
    } else if turn_status.is_some() {
        turn_status.unwrap_or("handled")
    } else if bootstrap_status == Some("needsClarification") {
        "needsClarification"
    } else if bootstrap_status.is_some() {
        "bootstrapped"
    } else {
        "handled"
    }
    .into()
}

fn best_friend_session_verdict(status: &str) -> String {
    match status {
        "readyToSend" => "bestFriendSessionReadyToSend",
        "approvalGateRequired" => "bestFriendSessionLiveGatePreserved",
        "dryRun" => "bestFriendSessionDryRun",
        "needsClarification" => "bestFriendSessionNeedsClarification",
        "bootstrapped" => "bestFriendSessionBootstrapped",
        "handled" => "bestFriendSessionHandled",
        _ => "bestFriendSessionBlocked",
    }
    .into()
}

fn build_best_friend_session_next_actions(
    run_dir: Option<&Path>,
    status: &str,
) -> Vec<CoachAction> {
    let Some(run_dir) = run_dir else {
        return vec![coach_action(
            1,
            "Provide creator prompt",
            Some("rs autopilot best-friend-session \"make a tycoon with shop and saves\" --format json".into()),
            "A prompt or existing run is required before the companion can bootstrap work.",
            false,
            false,
        )];
    };
    let run_arg = command_arg(run_dir.to_string_lossy().as_ref());
    match status {
        "readyToSend" => vec![coach_action(
            1,
            "Refresh best-friend session",
            Some(format!(
                "rs autopilot best-friend-session --run-dir {run_arg} --format json"
            )),
            "Use this after sending the checked message or receiving another creator turn.",
            false,
            false,
        )],
        "dryRun" => vec![coach_action(
            1,
            "Run best-friend session for real",
            Some(format!(
                "rs autopilot best-friend-session --run-dir {run_arg} --format json"
            )),
            "Execute the protected companion turn after reviewing the dry-run.",
            false,
            false,
        )],
        _ => vec![coach_action(
            1,
            "Inspect best-friend turn",
            Some(format!(
                "rs autopilot best-friend-turn {run_arg} --format json"
            )),
            "Inspect the lower-level turn receipt and blockers.",
            false,
            false,
        )],
    }
}

fn build_wow_session_report(
    options: &WowSessionOptions,
    wow_session_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<WowSessionReport> {
    let child_markdown = markdown_path.is_some();
    let base_dir = wow_session_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let prompt = options
        .prompt
        .as_deref()
        .map(str::trim)
        .filter(|text| !text.is_empty())
        .map(str::to_string);
    let message = options
        .message
        .as_deref()
        .map(str::trim)
        .filter(|text| !text.is_empty())
        .map(str::to_string);
    let mut artifacts = BTreeMap::from([(
        "wowSession".into(),
        wow_session_path.to_string_lossy().to_string(),
    )]);
    if let Some(path) = markdown_path {
        artifacts.insert(
            "wowSessionMarkdown".into(),
            path.to_string_lossy().to_string(),
        );
    }
    let mode = if options.run_dir.as_ref().is_some_and(|path| path.is_dir()) {
        "resume".to_string()
    } else {
        "bootstrap".to_string()
    };

    let session_base_dir = options.run_dir.clone().unwrap_or_else(|| base_dir.clone());
    let session_path = session_base_dir.join("best-friend-session.json");
    let session_markdown = child_markdown.then(|| base_dir.join("best-friend-session.md"));
    let session_options = BestFriendSessionOptions {
        port: options.port,
        prompt: prompt.clone(),
        message: message.clone(),
        source: options.source.clone(),
        scout: options.scout.clone(),
        survey: options.survey.clone(),
        context: options.context.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        scope: options.scope.clone(),
        limit: options.limit,
        assume: options.assume,
        smoke: options.smoke.clone(),
        opportunity: options.opportunity.clone(),
        max_chars: options.max_chars,
        max_steps: options.max_steps,
        dry_run: options.dry_run,
        out: Some(session_path.clone()),
        markdown: session_markdown.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let best_friend_session = build_best_friend_session_report(
        &session_options,
        &session_path,
        session_markdown.as_deref(),
    )?;
    write_json(session_path.clone(), &best_friend_session)?;
    if let Some(path) = session_markdown {
        write_best_friend_session_markdown(path, &best_friend_session)?;
    }
    artifacts.insert(
        "bestFriendSession".into(),
        best_friend_session.session_path.clone(),
    );
    if let Some(path) = &best_friend_session.markdown_path {
        artifacts.insert("bestFriendSessionMarkdown".into(), path.clone());
    }
    artifacts.extend(best_friend_session.artifacts.clone());

    let mut safe_to_say = best_friend_session.safe_to_say.clone();
    let mut do_not_say = best_friend_session.do_not_say.clone();
    let mut blockers = best_friend_session.blockers.clone();
    let mut warnings = best_friend_session.warnings.clone();
    let mut next_actions = best_friend_session.next_actions.clone();
    let mut creator_demo = None;

    let run_dir = best_friend_session.run_dir.as_deref().map(PathBuf::from);
    let bootstrap_status = Some(best_friend_session.status.clone());
    if blockers.is_empty() && best_friend_session.status != "approvalGateRequired" {
        if let Some(run_dir_path) = run_dir.as_ref() {
            let demo_path = run_dir_path.join("creator-demo.json");
            let demo_markdown = child_markdown.then(|| run_dir_path.join("creator-demo.md"));
            let demo_options = CreatorDemoOptions {
                prompt: prompt.clone(),
                idea: options.idea.clone(),
                run_dir: run_dir_path.clone(),
                root: options.root.clone(),
                limit: options.limit,
                max_ideas: options.max_ideas,
                max_chars: options.max_chars,
                dry_run: options.dry_run,
                out: Some(demo_path.clone()),
                markdown: demo_markdown.clone(),
                no_markdown: !child_markdown,
                json: false,
            };
            let demo =
                build_creator_demo_report(&demo_options, &demo_path, demo_markdown.as_deref())?;
            write_json(demo_path.clone(), &demo)?;
            if let Some(path) = demo_markdown {
                write_creator_demo_markdown(path, &demo)?;
            }
            artifacts.insert("creatorDemo".into(), demo.creator_demo_path.clone());
            if let Some(path) = &demo.markdown_path {
                artifacts.insert("creatorDemoMarkdown".into(), path.clone());
            }
            artifacts.extend(demo.artifacts.clone());
            safe_to_say.extend(demo.safe_to_say.clone());
            do_not_say.extend(demo.do_not_say.clone());
            blockers.extend(demo.blockers.clone());
            warnings.extend(demo.warnings.clone());
            next_actions = demo.next_actions.clone();
            creator_demo = Some(demo);
        }
    }

    if best_friend_session.status == "approvalGateRequired" {
        warnings.push(
            "wow-session preserved the approval/live gate from the companion turn and did not advance the demo loop."
                .into(),
        );
    }
    if run_dir.is_none() && blockers.is_empty() {
        blockers
            .push("wow-session needs a prompt or existing run before it can prepare a demo".into());
    }
    safe_to_say.push(
        "Wow session used local offline artifacts to bootstrap or resume the build, select a player moment, and prepare a proof-bound creator demo."
            .into(),
    );
    do_not_say.extend([
        "Do not claim wow-session applied, published, uploaded, live playtested, or mutated Studio."
            .into(),
        "Do not treat a wow-session demo packet as creator approval or production completion proof."
            .into(),
    ]);
    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let demo_status = creator_demo.as_ref().map(|report| report.status.clone());
    let status = wow_session_status(
        options.dry_run,
        &blockers,
        bootstrap_status.as_deref(),
        demo_status.as_deref(),
    );
    let verdict = wow_session_verdict(&status);
    if next_actions.is_empty() {
        next_actions = build_wow_session_next_actions(run_dir.as_deref(), &status);
    } else if status == "demoReady" {
        next_actions.insert(
            0,
            coach_action(
                1,
                "Show proof-bound creator demo",
                None,
                "Use creatorDemo talk track and proof table; do not imply live apply or approval.",
                false,
                false,
            ),
        );
        if let Some(run_dir_path) = run_dir.as_ref() {
            next_actions.push(coach_action(
                2,
                "Route creator reaction",
                Some(format!(
                    "rs autopilot demo-loop {} --message \"<creator reaction>\" --format json",
                    command_arg(run_dir_path.to_string_lossy().as_ref())
                )),
                "Turn the creator's demo reaction into feedback, approval prep, redirection, or a checked reply.",
                false,
                false,
            ));
        }
    }
    dedup_next_actions(&mut next_actions);

    let selected_idea = creator_demo
        .as_ref()
        .and_then(|report| report.selected_idea.clone());
    let recommended_run_dir = creator_demo
        .as_ref()
        .and_then(|report| report.recommended_run_dir.clone());
    let demo_title = creator_demo
        .as_ref()
        .map(|report| report.demo_title.clone());
    let creator_message = creator_demo
        .as_ref()
        .and_then(|report| report.creator_message.clone());
    let agent_brief = build_wow_session_agent_brief(
        &status,
        best_friend_session.status.as_str(),
        demo_status.as_deref(),
        selected_idea.as_ref(),
        recommended_run_dir.as_deref(),
    );

    Ok(WowSessionReport {
        schema_version: "rs.autopilot.wow-session.v1".into(),
        generated_at: now_stamp(),
        wow_session_path: wow_session_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        run_dir: run_dir.map(|path| path.to_string_lossy().to_string()),
        prompt: prompt.as_deref().map(redact_text),
        message: message.as_deref().map(redact_text),
        status,
        verdict,
        mode,
        dry_run: options.dry_run,
        bootstrap_status,
        demo_status,
        selected_idea,
        recommended_run_dir,
        demo_title,
        creator_message,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        best_friend_session: Some(best_friend_session),
        creator_demo,
    })
}

fn wow_session_status(
    dry_run: bool,
    blockers: &[String],
    bootstrap_status: Option<&str>,
    demo_status: Option<&str>,
) -> String {
    if !blockers.is_empty() {
        "blocked"
    } else if bootstrap_status == Some("approvalGateRequired") {
        "approvalGateRequired"
    } else if dry_run || demo_status == Some("dryRun") {
        "dryRun"
    } else if demo_status == Some("demoPacketReady") {
        "demoReady"
    } else if demo_status.is_some() {
        demo_status.unwrap_or("handled")
    } else if bootstrap_status.is_some() {
        "bootstrapped"
    } else {
        "handled"
    }
    .into()
}

fn wow_session_verdict(status: &str) -> String {
    match status {
        "demoReady" => "wowSessionDemoReady",
        "approvalGateRequired" => "wowSessionLiveGatePreserved",
        "dryRun" => "wowSessionDryRun",
        "bootstrapped" => "wowSessionBootstrapped",
        "handled" => "wowSessionHandled",
        _ => "wowSessionBlocked",
    }
    .into()
}

fn build_best_friend_arc_report(
    options: &BestFriendArcOptions,
    arc_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<BestFriendArcReport> {
    let child_markdown = markdown_path.is_some();
    let base_dir = arc_path
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from("."));
    let prompt = options
        .prompt
        .as_deref()
        .map(str::trim)
        .filter(|text| !text.is_empty())
        .map(str::to_string);
    let message = options
        .message
        .as_deref()
        .map(str::trim)
        .filter(|text| !text.is_empty())
        .map(str::to_string);
    let wow_base_dir = options.run_dir.clone().unwrap_or_else(|| base_dir.clone());
    let wow_path = wow_base_dir.join("wow-session.json");
    let wow_markdown = child_markdown.then(|| wow_base_dir.join("wow-session.md"));
    let wow_options = WowSessionOptions {
        port: options.port,
        prompt: prompt.clone(),
        message: None,
        source: options.source.clone(),
        scout: options.scout.clone(),
        survey: options.survey.clone(),
        context: options.context.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        scope: options.scope.clone(),
        limit: options.limit,
        assume: options.assume,
        smoke: options.smoke.clone(),
        idea: options.idea.clone(),
        opportunity: options.opportunity.clone(),
        max_ideas: options.max_ideas,
        max_chars: options.max_chars,
        max_steps: options.max_steps,
        dry_run: options.dry_run,
        out: Some(wow_path.clone()),
        markdown: wow_markdown.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let wow_session = build_wow_session_report(&wow_options, &wow_path, wow_markdown.as_deref())?;
    write_json(wow_path.clone(), &wow_session)?;
    if let Some(path) = wow_markdown {
        write_wow_session_markdown(path, &wow_session)?;
    }

    let run_dir = wow_session.run_dir.as_deref().map(PathBuf::from);
    if let Some(run_dir_path) = run_dir.as_ref() {
        refresh_run_bundle_if_possible(run_dir_path)?;
    }
    if let Some(recommended) = wow_session.recommended_run_dir.as_deref() {
        refresh_run_bundle_if_possible(Path::new(recommended))?;
    }
    let mut demo_session = None;
    if let (Some(message_text), Some(run_dir_path)) = (message.as_ref(), run_dir.as_ref()) {
        let demo_path = run_dir_path.join("demo-session.json");
        let demo_markdown = child_markdown.then(|| run_dir_path.join("demo-session.md"));
        let demo_options = DemoSessionOptions {
            messages: vec![message_text.clone()],
            idea: options.idea.clone(),
            run_dir: run_dir_path.clone(),
            root: options.root.clone(),
            limit: options.limit,
            max_ideas: options.max_ideas,
            max_chars: options.max_chars,
            dry_run: options.dry_run,
            out: Some(demo_path.clone()),
            markdown: demo_markdown.clone(),
            no_markdown: !child_markdown,
            json: false,
        };
        let report =
            build_demo_session_report(&demo_options, &demo_path, demo_markdown.as_deref())?;
        write_json(demo_path.clone(), &report)?;
        if let Some(path) = demo_markdown {
            write_demo_session_markdown(path, &report)?;
        }
        demo_session = Some(report);
    }

    let mut artifacts = BTreeMap::from([(
        "bestFriendArc".into(),
        arc_path.to_string_lossy().to_string(),
    )]);
    if let Some(path) = markdown_path {
        artifacts.insert(
            "bestFriendArcMarkdown".into(),
            path.to_string_lossy().to_string(),
        );
    }
    artifacts.extend(wow_session.artifacts.clone());
    if let Some(report) = &demo_session {
        artifacts.extend(report.artifacts.clone());
    }

    let mut blockers = wow_session.blockers.clone();
    let mut warnings = wow_session.warnings.clone();
    let mut safe_to_say = wow_session.safe_to_say.clone();
    let mut do_not_say = wow_session.do_not_say.clone();
    let mut next_actions = Vec::new();
    if let Some(report) = &demo_session {
        blockers.extend(report.blockers.clone());
        warnings.extend(report.warnings.clone());
        safe_to_say.extend(report.safe_to_say.clone());
        do_not_say.extend(report.do_not_say.clone());
        next_actions.extend(report.next_actions.clone());
    }

    if message.is_some() && run_dir.is_none() {
        blockers.push(
            "best-friend-arc needs a bootstrapped or existing run before it can handle a post-demo response"
                .into(),
        );
    }
    safe_to_say.push(
        "Best-friend arc prepared the creator demo journey and, when a reaction was provided, routed the post-demo response through checked learning and memory artifacts."
            .into(),
    );
    do_not_say.extend([
        "Do not claim best-friend-arc applied, published, uploaded, live playtested, or mutated Studio."
            .into(),
        "Do not treat best-friend-arc as creator approval, live apply, rollback readiness, or production completion proof."
            .into(),
    ]);
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();

    let status = best_friend_arc_status(&blockers, &wow_session, demo_session.as_ref());
    let verdict = best_friend_arc_verdict(&status);
    let phase = if demo_session.is_some() {
        "postDemoReaction"
    } else {
        "creatorDemo"
    }
    .to_string();

    if status == "demoReady" {
        next_actions.push(coach_action(
            1,
            "Show proof-bound creator demo",
            None,
            "Use creatorMessage and the proof table from wowSession; do not imply live apply or production readiness.",
            false,
            false,
        ));
        if let Some(run_dir_path) = run_dir.as_ref() {
            next_actions.push(coach_action(
                2,
                "Route creator reaction through best-friend arc",
                Some(format!(
                    "rs autopilot best-friend-arc --run-dir {} --message \"<creator reaction>\" --format json",
                    command_arg(run_dir_path.to_string_lossy().as_ref())
                )),
                "Return to the same one-command arc after the creator reacts to the demo.",
                false,
                false,
            ));
        }
    } else if status == "replyReady" {
        next_actions.insert(
            0,
            coach_action(
                1,
                "Send checked post-demo reply",
                None,
                "Use replyMessage exactly; rerun best-friend-arc if the creator wording changes.",
                false,
                false,
            ),
        );
    } else if next_actions.is_empty() {
        next_actions.extend(wow_session.next_actions.clone());
    }
    dedup_next_actions(&mut next_actions);

    let selected_idea = wow_session.selected_idea.clone();
    let recommended_run_dir = demo_session
        .as_ref()
        .and_then(|report| report.recommended_run_dir.clone())
        .or_else(|| wow_session.recommended_run_dir.clone());
    let demo_title = wow_session.demo_title.clone();
    let creator_message = wow_session.creator_message.clone();
    let reply_message = demo_session
        .as_ref()
        .and_then(|report| report.reply_message.clone());
    let ready_for_creator_demo = status == "demoReady" || demo_session.is_some();
    let ready_for_post_demo_reply = status == "replyReady";
    let agent_brief = format!(
        "Best-friend arc is {status}: phase `{phase}` used wow-session `{}` and demo-session `{}`. Show creatorMessage when demoReady; send replyMessage only when replyReady.",
        wow_session.status,
        demo_session
            .as_ref()
            .map(|report| report.status.as_str())
            .unwrap_or("skipped")
    );

    Ok(BestFriendArcReport {
        schema_version: "rs.autopilot.best-friend-arc.v1".into(),
        generated_at: now_stamp(),
        arc_path: arc_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        run_dir: run_dir.map(|path| path.to_string_lossy().to_string()),
        prompt: prompt.as_deref().map(redact_text),
        message: message.as_deref().map(redact_text),
        status,
        verdict,
        mode: wow_session.mode.clone(),
        phase,
        dry_run: options.dry_run,
        wow_session_status: wow_session.status.clone(),
        demo_session_status: demo_session.as_ref().map(|report| report.status.clone()),
        selected_idea,
        recommended_run_dir,
        demo_title,
        creator_message,
        reply_message,
        ready_for_creator_demo,
        ready_for_post_demo_reply,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        wow_session,
        demo_session,
    })
}

fn best_friend_arc_status(
    blockers: &[String],
    wow_session: &WowSessionReport,
    demo_session: Option<&DemoSessionReport>,
) -> String {
    if !blockers.is_empty() {
        "blocked"
    } else if let Some(demo) = demo_session {
        match demo.status.as_str() {
            "readyToSend" => "replyReady",
            "readyToReply" => "replyReadyWithMemoryWarning",
            "needsCreatorResponse" => "needsCreatorResponse",
            "needsFollowup" => "needsFollowup",
            status => status,
        }
    } else {
        match wow_session.status.as_str() {
            "demoReady" => "demoReady",
            "approvalGateRequired" => "approvalGateRequired",
            "dryRun" => "dryRun",
            "bootstrapped" => "bootstrapped",
            status => status,
        }
    }
    .into()
}

fn best_friend_arc_verdict(status: &str) -> String {
    match status {
        "demoReady" => "bestFriendArcDemoReady",
        "replyReady" => "bestFriendArcReplyReady",
        "replyReadyWithMemoryWarning" => "bestFriendArcReplyReadyMemoryNeedsReview",
        "needsCreatorResponse" => "bestFriendArcNeedsCreatorResponse",
        "needsFollowup" => "bestFriendArcNeedsFollowup",
        "approvalGateRequired" => "bestFriendArcLiveGatePreserved",
        "dryRun" => "bestFriendArcDryRun",
        "bootstrapped" => "bestFriendArcBootstrapped",
        _ => "bestFriendArcBlocked",
    }
    .into()
}

fn build_wow_session_next_actions(run_dir: Option<&Path>, status: &str) -> Vec<CoachAction> {
    let Some(run_dir) = run_dir else {
        return vec![coach_action(
            1,
            "Provide creator prompt",
            Some("rs autopilot wow-session \"make a tycoon with shop and saves\" --assume --format json".into()),
            "A prompt or existing run is required before the wow session can prepare a demo.",
            false,
            false,
        )];
    };
    let run_arg = command_arg(run_dir.to_string_lossy().as_ref());
    match status {
        "demoReady" => vec![
            coach_action(
                1,
                "Show creator demo packet",
                Some(format!("rs autopilot creator-demo {run_arg} --format json")),
                "Use the demo packet as the proof-bound creator review surface.",
                false,
                false,
            ),
            coach_action(
                2,
                "Route creator reaction",
                Some(format!(
                    "rs autopilot demo-loop {run_arg} --message \"<creator reaction>\" --format json"
                )),
                "Preserve the creator reaction before continuing.",
                false,
                false,
            ),
        ],
        "dryRun" => vec![coach_action(
            1,
            "Run wow session for real",
            Some(format!("rs autopilot wow-session --run-dir {run_arg} --format json")),
            "Execute the offline wow candidate and demo packet after reviewing the dry-run.",
            false,
            false,
        )],
        "approvalGateRequired" => vec![coach_action(
            1,
            "Review live gate",
            Some(format!("rs autopilot live-gate --run-dir {run_arg} --format json")),
            "Keep approval-like creator language behind the live gate.",
            true,
            false,
        )],
        _ => vec![coach_action(
            1,
            "Inspect creator demo",
            Some(format!("rs autopilot creator-demo {run_arg} --format json")),
            "Review the lower-level demo packet and blockers.",
            false,
            false,
        )],
    }
}

fn build_wow_session_agent_brief(
    status: &str,
    bootstrap_status: &str,
    demo_status: Option<&str>,
    idea: Option<&WowIdea>,
    recommended_run: Option<&str>,
) -> String {
    let idea_title = idea
        .map(|idea| idea.title.as_str())
        .unwrap_or("<no selected wow idea>");
    let recommended = recommended_run.unwrap_or("<no recommended run>");
    format!(
        "Wow session is {status}: best-friend-session={bootstrap_status}, creator-demo={}, selected idea `{idea_title}`, recommended run `{recommended}`. Use creator demo evidence only; live apply, playtest, publish, and approval remain gated.",
        demo_status.unwrap_or("skipped")
    )
}

fn build_best_friend_context_cards(
    remember: &RememberReport,
    task_pack: &TaskPackReport,
    launch_preflight: &SelfCheckReport,
    artifacts: &BTreeMap<String, String>,
) -> Vec<BestFriendContextCard> {
    let mut cards = Vec::new();
    for (id, title, status, reason) in [
        (
            "remember",
            "Remembered Creator Context",
            remember.status.as_str(),
            "Consolidated demo learning into project memory, preferences, canon, and playbook.",
        ),
        (
            "modelPack",
            "Model Resume Context",
            task_pack.model_pack.status.as_str(),
            "Bounded redacted snippets and source links for context-compacted AI resume.",
        ),
        (
            "taskPack",
            "Agent Task Surface",
            task_pack.status.as_str(),
            "One evidence-bound task, validation list, stop conditions, and claim guardrails.",
        ),
        (
            "bestFriendSelfCheck",
            "Launch Self Check",
            launch_preflight.status.as_str(),
            "Preflighted the launch claim and first safe action before the handoff.",
        ),
    ] {
        if let Some(path) = artifacts.get(id) {
            cards.push(BestFriendContextCard {
                id: id.into(),
                title: title.into(),
                path: path.clone(),
                status: status.into(),
                reason: reason.into(),
            });
        }
    }
    for item in task_pack.required_context.iter().take(8) {
        cards.push(BestFriendContextCard {
            id: item.id.clone(),
            title: item.title.clone(),
            path: item.path.clone(),
            status: if item.exists { "available" } else { "missing" }.into(),
            reason: item.reason.clone(),
        });
    }
    cards.sort_by(|left, right| left.id.cmp(&right.id));
    cards.dedup_by(|left, right| left.id == right.id && left.path == right.path);
    cards
}

fn build_best_friend_contract(run_dir: &Path, task_pack: &TaskPackReport) -> Vec<String> {
    let mut contract = vec![
        format!("Read AGENTS.md, then read best-friend context for `{}` before acting.", run_dir.to_string_lossy()),
        "Use source artifacts as authoritative evidence; this packet is an index and launch prompt.".into(),
        "Make one safe offline move at a time, then refresh navigator, task-pack, or best-friend before continuing.".into(),
        "Never apply, publish, upload, install plugins, or mutate Studio from this packet alone.".into(),
        "Read the launch self-check before running the first action or sending the opening update.".into(),
        "Before creator-facing claims, refresh completion-audit, delivery, and claim-check for the exact wording.".into(),
    ];
    if let Some(command) = &task_pack.primary_command {
        contract.push(format!(
            "First candidate command is `{command}` unless blockers or stop conditions apply."
        ));
    }
    contract.sort();
    contract.dedup();
    contract
}

fn build_best_friend_opening_prompt(
    status: &str,
    run_dir: &Path,
    remember: &RememberReport,
    task_pack: &TaskPackReport,
    context_cards: &[BestFriendContextCard],
    companion_contract: &[String],
    safe_to_say: &[String],
    do_not_say: &[String],
    first_safe_action: Option<&CoachAction>,
    first_act_action: Option<&CoachAction>,
) -> String {
    let mut lines = Vec::new();
    lines.push("You are the AI build companion for this Roblox game project.".into());
    lines.push("Your job is to help the creator make real progress while preserving evidence, consent, rollback, and claim boundaries.".into());
    lines.push(format!("Run directory: {}", run_dir.to_string_lossy()));
    lines.push(format!("Best-friend status: {status}"));
    lines.push(format!("Remembered context status: {}", remember.status));
    lines.push(format!("Task status: {}", task_pack.status));
    lines.push("\nRead these context cards first:".into());
    for card in context_cards.iter().take(10) {
        lines.push(format!(
            "- {} [{}]: {} ({})",
            card.title, card.status, card.path, card.reason
        ));
    }
    lines.push("\nCompanion contract:".into());
    for rule in companion_contract {
        lines.push(format!("- {rule}"));
    }
    if let Some(action) = first_safe_action {
        lines.push("\nFirst safe action:".into());
        lines.push(format!("- {}", action.title));
        if let Some(command) = &action.command {
            lines.push(format!("- Command: {command}"));
        }
        lines.push(format!("- Why: {}", action.reason));
    }
    if let Some(action) = first_act_action {
        lines.push("\nPreferred protected execution:".into());
        lines.push(format!("- {}", action.title));
        if let Some(command) = &action.command {
            lines.push(format!("- Command: {command}"));
        }
        lines.push(format!("- Why: {}", action.reason));
    }
    lines.push("\nSafe to say:".into());
    for item in safe_to_say.iter().take(8) {
        lines.push(format!("- {item}"));
    }
    lines.push("\nDo not say:".into());
    for item in do_not_say.iter().take(8) {
        lines.push(format!("- {item}"));
    }
    lines.join("\n")
}

fn build_best_friend_opening_reply_claim(
    task_pack: &TaskPackReport,
    safe_to_say: &[String],
) -> String {
    task_pack
        .safe_to_say
        .iter()
        .find(|claim| claim.contains("Task pack prepared"))
        .cloned()
        .or_else(|| safe_to_say.first().cloned())
        .unwrap_or_else(|| {
            "Best-friend packet prepared a local AI handoff, but the exact next claim needs review."
                .into()
        })
}

fn build_best_friend_opening_reply(
    opening_reply_claim: &str,
    first_safe_action: Option<&CoachAction>,
    first_act_action: Option<&CoachAction>,
    launch_preflight: &SelfCheckReport,
    status: &str,
) -> String {
    let mut lines = Vec::new();
    lines.push(opening_reply_claim.to_string());
    if launch_preflight.safe_to_proceed {
        lines.push(
            "I checked the launch claim and first command before continuing, and the preflight is ready to proceed."
                .into(),
        );
    } else {
        lines.push(format!(
            "The launch preflight is `{}`; I need to resolve that before acting or making a stronger claim.",
            launch_preflight.status
        ));
    }
    if let Some(action) = first_safe_action {
        lines.push(format!("Next checked offline move: {}.", action.title));
        if let Some(command) = &action.command {
            lines.push(format!("Command: `{command}`"));
        }
    } else {
        lines.push(
            "I do not have a checked offline first action yet, so I will refresh the launch packet before doing work."
                .into(),
        );
    }
    if let Some(action) = first_act_action {
        if let Some(command) = &action.command {
            lines.push(format!("Preferred protected command: `{command}`"));
        }
    }
    lines.push(format!(
        "Best-friend packet status is `{status}`; I will stop before live Studio mutation, apply, publish, upload, playtest, or done claims without their own evidence."
    ));
    lines.join("\n")
}

fn build_task_pack_acceptance_checks(
    expected_artifacts: &[String],
    work_order: &WorkOrderReport,
) -> Vec<String> {
    let mut checks = Vec::new();
    if expected_artifacts.is_empty() {
        checks.push(
            "Work order must identify expected artifacts before success can be reported.".into(),
        );
    } else {
        for artifact in expected_artifacts.iter().take(10) {
            checks.push(format!(
                "Expected artifact is present or explicitly explained: {artifact}"
            ));
        }
    }
    checks.push("Run every validation command listed in task-pack validationCommands.".into());
    checks.push("Refresh work-check and claim-check before creator-facing status updates.".into());
    if work_order
        .opportunity
        .as_ref()
        .is_some_and(|opportunity| opportunity.requires_live_studio)
    {
        checks.push(
            "If live Studio is required, setup/ready evidence must pass before continuing.".into(),
        );
    }
    checks
}

fn build_task_pack_prompt(
    status: &str,
    task_title: &str,
    objective: &str,
    run_dir: &Path,
    model_pack: &ModelPackReport,
    work_order: &WorkOrderReport,
    allowed_commands: &[String],
    acceptance_checks: &[String],
    stop_conditions: &[String],
    safe_to_say: &[String],
    do_not_say: &[String],
) -> String {
    let mut lines = Vec::new();
    lines.push("You are an AI agent helping build a Roblox game with the rs Autopilot CLI.".into());
    lines.push("Read AGENTS.md first and follow the repository rules.".into());
    lines.push(format!("Run directory: {}", run_dir.to_string_lossy()));
    lines.push(format!("Task status: {status}"));
    lines.push(format!("Task title: {task_title}"));
    lines.push(format!("Objective: {objective}"));
    lines.push(format!("Context source: {}", model_pack.model_pack_path));
    lines.push(format!("Work order source: {}", work_order.work_order_path));
    if let Some(command) = &work_order
        .opportunity
        .as_ref()
        .and_then(|item| item.command.clone())
    {
        lines.push(format!("Primary command: {command}"));
    }
    lines.push("Allowed commands:".into());
    for command in allowed_commands {
        lines.push(format!("- {command}"));
    }
    lines.push("Acceptance checks:".into());
    for check in acceptance_checks {
        lines.push(format!("- {check}"));
    }
    lines.push("Stop conditions:".into());
    for condition in stop_conditions {
        lines.push(format!("- {condition}"));
    }
    if !safe_to_say.is_empty() {
        lines.push("Safe claims:".into());
        for claim in safe_to_say.iter().take(6) {
            lines.push(format!("- {claim}"));
        }
    }
    if !do_not_say.is_empty() {
        lines.push("Forbidden claims:".into());
        for claim in do_not_say.iter().take(8) {
            lines.push(format!("- {claim}"));
        }
    }
    lines.push("When finished, report exact commands run, exact results, artifacts written, and unresolved blockers. Do not claim live apply, playtest, rollback, publish, or production readiness unless the cited source artifacts prove it.".into());
    lines.join("\n")
}

fn build_squad_pack_report(
    options: &SquadPackOptions,
    squad_pack_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<SquadPackReport> {
    let write_markdown = markdown_path.is_some();
    let model_pack_path = options.run_dir.join("model-pack.json");
    let model_pack_markdown_path = write_markdown.then(|| options.run_dir.join("model-pack.md"));
    let model_options = ModelPackOptions {
        prompt: options.prompt.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        max_chars: options.max_chars,
        out: Some(model_pack_path.clone()),
        markdown: model_pack_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let model_pack = build_model_pack_report(
        &model_options,
        &model_pack_path,
        model_pack_markdown_path.as_deref(),
    )?;
    write_json(model_pack_path.clone(), &model_pack)?;
    if let Some(path) = model_pack_markdown_path {
        write_model_pack_markdown(path, &model_pack)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;

    let opportunities_path = options.run_dir.join("opportunities.json");
    let opportunities_markdown_path =
        write_markdown.then(|| options.run_dir.join("opportunities.md"));
    let opportunities_options = OpportunitiesOptions {
        prompt: options.prompt.clone(),
        run_dir: Some(options.run_dir.clone()),
        root: options.root.clone(),
        limit: options.limit,
        out: Some(opportunities_path.clone()),
        markdown: opportunities_markdown_path.clone(),
        no_markdown: !write_markdown,
        json: false,
    };
    let opportunities = build_opportunities_report(
        &opportunities_options,
        &opportunities_path,
        opportunities_markdown_path.as_deref(),
    )?;
    write_json(opportunities_path.clone(), &opportunities)?;
    if let Some(path) = opportunities_markdown_path {
        write_opportunities_markdown(path, &opportunities)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;

    let assignments = opportunities
        .opportunities
        .iter()
        .take(options.max_tasks)
        .enumerate()
        .map(|(index, opportunity)| build_squad_assignment(options, index, opportunity))
        .collect::<Vec<_>>();

    let mut blockers = opportunities.blockers.clone();
    blockers.extend(
        model_pack
            .blockers
            .iter()
            .filter(|blocker| {
                let lower = blocker.to_ascii_lowercase();
                lower.contains("secret") || lower.contains("privacy")
            })
            .cloned(),
    );
    if options.max_tasks == 0 {
        blockers.push("squad pack max-tasks must be greater than zero".into());
    }
    if assignments.is_empty() {
        blockers.push("no opportunities were available to assign to the AI squad".into());
    } else if assignments
        .iter()
        .all(|assignment| assignment.status == "blocked")
    {
        blockers.push("all squad assignments are blocked".into());
    }
    blockers.sort();
    blockers.dedup();

    let mut warnings = merge_many_sorted(vec![
        model_pack.warnings.clone(),
        opportunities.warnings.clone(),
        assignments
            .iter()
            .flat_map(|assignment| assignment.warnings.clone())
            .collect(),
    ]);
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else if assignments
        .iter()
        .any(|assignment| assignment.status == "readyForAgentTask")
    {
        "readyForSquad"
    } else if assignments
        .iter()
        .any(|assignment| assignment.status == "gatedLiveTask")
    {
        "gatedSquad"
    } else {
        "blocked"
    }
    .to_string();

    let mut safe_to_say = merge_many_sorted(vec![
        model_pack.safe_to_say.clone(),
        opportunities.safe_to_say.clone(),
    ]);
    safe_to_say.push(format!(
        "Squad pack prepared {} evidence-bound agent assignment{}.",
        assignments.len(),
        if assignments.len() == 1 { "" } else { "s" }
    ));
    safe_to_say.sort();
    safe_to_say.dedup();
    let mut do_not_say = merge_many_sorted(vec![
        model_pack.do_not_say.clone(),
        opportunities.do_not_say.clone(),
    ]);
    do_not_say.extend([
        "Do not treat squad-pack assignments as proof that any task was executed.".into(),
        "Do not let parallel agents mutate Studio, publish, upload, install plugins, or claim live proof without the normal approval gates.".into(),
        "Do not let agents edit outside their assignment ownership unless a refreshed task pack explicitly expands scope.".into(),
    ]);
    do_not_say.sort();
    do_not_say.dedup();

    let mut artifacts = model_pack.artifacts.clone();
    artifacts.extend(opportunities.artifacts.clone());
    artifacts.insert(
        "squadPack".into(),
        squad_pack_path.to_string_lossy().to_string(),
    );
    if let Some(path) = markdown_path {
        artifacts.insert(
            "squadPackMarkdown".into(),
            path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert("modelPack".into(), model_pack.model_pack_path.clone());
    artifacts.insert(
        "opportunities".into(),
        opportunities.opportunities_path.clone(),
    );

    let mut next_actions = assignments
        .iter()
        .take(6)
        .map(|assignment| {
            coach_action(
                assignment.priority,
                &assignment.title,
                assignment.primary_command.clone(),
                "Give this assignment to one AI agent and require its validation commands before reporting progress.",
                assignment.requires_live_studio,
                assignment.mutates_studio,
            )
        })
        .collect::<Vec<_>>();
    next_actions.push(coach_action(
        90,
        "Refresh squad pack",
        Some(format!(
            "rs autopilot squad-pack {} --format json",
            command_arg(options.run_dir.to_string_lossy().as_ref())
        )),
        "Regenerate assignments after any agent writes evidence or blockers.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);

    let coordination_prompt = build_squad_coordination_prompt(
        &status,
        &options.run_dir,
        &assignments,
        &safe_to_say,
        &do_not_say,
    );
    let ready_count = assignments
        .iter()
        .filter(|assignment| assignment.status == "readyForAgentTask")
        .count();
    let agent_brief = format!(
        "Squad pack is {status}: {} assignment(s), {} ready, {} blocked.",
        assignments.len(),
        ready_count,
        assignments
            .iter()
            .filter(|assignment| assignment.status == "blocked")
            .count()
    );

    Ok(SquadPackReport {
        schema_version: "rs.autopilot.squad-pack.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        squad_pack_path: squad_pack_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        prompt: options.prompt.clone(),
        status,
        max_tasks: options.max_tasks,
        task_count: assignments.len(),
        coordination_prompt,
        assignments,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        model_pack,
        opportunities,
    })
}

fn build_squad_assignment(
    options: &SquadPackOptions,
    index: usize,
    opportunity: &OpportunityItem,
) -> SquadAssignment {
    let work_order_options = WorkOrderOptions {
        prompt: options.prompt.clone(),
        run_dir: Some(options.run_dir.clone()),
        opportunity: Some(opportunity.title.clone()),
        root: options.root.clone(),
        limit: options.limit,
        out: Some(options.run_dir.join("work-order.json")),
        markdown: None,
        no_markdown: true,
        json: false,
    };
    let validation_commands =
        build_work_order_validation_commands(&work_order_options, Some(opportunity));
    let mut blockers = opportunity.blocked_by.clone();
    if opportunity.command.is_none() {
        blockers.push(format!(
            "assignment `{}` has no executable primary command",
            opportunity.title
        ));
    }
    if opportunity.mutates_studio {
        blockers
            .push("assignment mutates Studio; route through approval and live-gate instead".into());
    }
    blockers.sort();
    blockers.dedup();

    let mut warnings = Vec::new();
    if opportunity.requires_live_studio {
        warnings.push("assignment requires live Studio readiness evidence before execution".into());
    }
    let status = if !blockers.is_empty() {
        "blocked"
    } else if opportunity.requires_live_studio {
        "gatedLiveTask"
    } else {
        "readyForAgentTask"
    }
    .to_string();
    let mut allowed_commands = opportunity.command.iter().cloned().collect::<Vec<_>>();
    allowed_commands.extend(validation_commands.clone());
    allowed_commands.push(format!(
        "rs autopilot task-pack {} --opportunity \"{}\" --format json",
        command_arg(options.run_dir.to_string_lossy().as_ref()),
        shell_display_arg(&opportunity.title)
    ));
    allowed_commands.push(format!(
        "rs autopilot squad-pack {} --format json",
        command_arg(options.run_dir.to_string_lossy().as_ref())
    ));
    allowed_commands.sort();
    allowed_commands.dedup();

    let mut stop_conditions = build_work_order_stop_conditions(Some(opportunity), &blockers);
    stop_conditions.push(
        "stop if another agent has already produced, changed, or blocked the same expected artifact".into(),
    );
    stop_conditions.push(
        "stop before reporting success unless validation commands and source artifacts support the exact claim".into(),
    );
    stop_conditions.push(
        "stop at any command that applies, publishes, uploads, installs plugins, repairs live setup, or mutates Studio".into(),
    );
    stop_conditions.sort();
    stop_conditions.dedup();

    let id = format!("AG-{:03}", index + 1);
    let role = squad_role_for_phase(&opportunity.phase, index);
    let objective = format!(
        "Execute `{}` as an isolated agent lane, then verify expected artifacts before making claims.",
        opportunity.title
    );
    let ownership = squad_assignment_ownership(opportunity);
    let task_prompt = build_squad_assignment_prompt(
        &id,
        &role,
        &status,
        &objective,
        opportunity,
        &ownership,
        &allowed_commands,
        &validation_commands,
        &stop_conditions,
        &options.run_dir,
    );

    SquadAssignment {
        id,
        title: opportunity.title.clone(),
        role,
        phase: opportunity.phase.clone(),
        priority: (index + 1).min(u8::MAX as usize) as u8,
        status,
        objective,
        primary_command: opportunity.command.clone(),
        allowed_commands,
        validation_commands,
        expected_artifacts: opportunity.expected_artifacts.clone(),
        ownership,
        stop_conditions,
        task_prompt,
        blockers,
        warnings,
        requires_live_studio: opportunity.requires_live_studio,
        mutates_studio: opportunity.mutates_studio,
    }
}

fn squad_role_for_phase(phase: &str, index: usize) -> String {
    match phase {
        "proof" | "verification" => "Evidence verifier".into(),
        "handoff" | "continuity" => "Continuity keeper".into(),
        "coordination" => "Loop coordinator".into(),
        "repair" | "fulfillment" => "Repair planner".into(),
        "approval" => "Gate reviewer".into(),
        _ => format!("Autopilot agent {}", index + 1),
    }
}

fn squad_assignment_ownership(opportunity: &OpportunityItem) -> Vec<String> {
    let mut ownership = Vec::new();
    if opportunity.expected_artifacts.is_empty() {
        ownership.push(
            "Own only the selected command result and newly written evidence artifacts.".into(),
        );
    } else {
        ownership.push(format!(
            "Own producing or verifying: {}.",
            opportunity.expected_artifacts.join(", ")
        ));
    }
    ownership.push(
        "Do not edit unrelated run folders, generated source, plugin files, or live Studio state."
            .into(),
    );
    ownership.push("Refresh the squad pack if ownership conflicts with another assignment.".into());
    ownership
}

fn build_squad_assignment_prompt(
    id: &str,
    role: &str,
    status: &str,
    objective: &str,
    opportunity: &OpportunityItem,
    ownership: &[String],
    allowed_commands: &[String],
    validation_commands: &[String],
    stop_conditions: &[String],
    run_dir: &Path,
) -> String {
    let mut lines = Vec::new();
    lines.push(format!(
        "You are {id}, the {role} for this Roblox Autopilot squad."
    ));
    lines.push(
        "Read AGENTS.md first, then read squad-pack.json and model-pack.json before acting.".into(),
    );
    lines.push(format!("Run directory: {}", run_dir.to_string_lossy()));
    lines.push(format!("Assignment status: {status}"));
    lines.push(format!("Objective: {objective}"));
    lines.push(format!("Opportunity: {}", opportunity.title));
    if let Some(command) = &opportunity.command {
        lines.push(format!("Primary command: {command}"));
    }
    lines.push("Ownership:".into());
    for item in ownership {
        lines.push(format!("- {item}"));
    }
    lines.push("Allowed commands:".into());
    for command in allowed_commands {
        lines.push(format!("- {command}"));
    }
    if !validation_commands.is_empty() {
        lines.push("Validation commands:".into());
        for command in validation_commands {
            lines.push(format!("- {command}"));
        }
    }
    lines.push("Stop conditions:".into());
    for condition in stop_conditions {
        lines.push(format!("- {condition}"));
    }
    lines.push("Report only exact commands run, exact results, artifacts written, and blockers. Do not claim live apply, playtest, rollback, publish, or production readiness from this assignment alone.".into());
    lines.join("\n")
}

fn build_squad_coordination_prompt(
    status: &str,
    run_dir: &Path,
    assignments: &[SquadAssignment],
    safe_to_say: &[String],
    do_not_say: &[String],
) -> String {
    let mut lines = Vec::new();
    lines.push("You are coordinating multiple AI agents for a Roblox Autopilot run.".into());
    lines.push("Read AGENTS.md first. Keep each agent inside its assignment ownership and stop at live or mutating gates.".into());
    lines.push(format!("Run directory: {}", run_dir.to_string_lossy()));
    lines.push(format!("Squad status: {status}"));
    lines.push("Assignments:".into());
    for assignment in assignments {
        lines.push(format!(
            "- {} [{}]: {}",
            assignment.id, assignment.status, assignment.title
        ));
        if let Some(command) = &assignment.primary_command {
            lines.push(format!("  Command: {command}"));
        }
    }
    if !safe_to_say.is_empty() {
        lines.push("Safe claims:".into());
        for claim in safe_to_say.iter().take(5) {
            lines.push(format!("- {claim}"));
        }
    }
    if !do_not_say.is_empty() {
        lines.push("Forbidden claims:".into());
        for claim in do_not_say.iter().take(6) {
            lines.push(format!("- {claim}"));
        }
    }
    lines.push("After agents finish, refresh squad-pack, work-check, claim-check, and delivery before speaking to the creator.".into());
    lines.join("\n")
}

fn build_squad_review_report(
    options: &SquadReviewOptions,
    squad_review_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<SquadReviewReport> {
    let child_markdown = markdown_path.is_some();
    let squad_pack_path = options.run_dir.join("squad-pack.json");
    let squad_pack_markdown_path = child_markdown.then(|| options.run_dir.join("squad-pack.md"));
    let squad_options = SquadPackOptions {
        prompt: None,
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        max_tasks: options.max_tasks,
        max_chars: options.max_chars,
        out: Some(squad_pack_path.clone()),
        markdown: squad_pack_markdown_path.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let squad_pack = build_squad_pack_report(
        &squad_options,
        &squad_pack_path,
        squad_pack_markdown_path.as_deref(),
    )?;
    write_json(squad_pack_path.clone(), &squad_pack)?;
    if let Some(path) = squad_pack_markdown_path {
        write_squad_pack_markdown(path, &squad_pack)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;

    let assignments = squad_pack
        .assignments
        .iter()
        .map(|assignment| build_squad_review_assignment(&options.run_dir, assignment))
        .collect::<AppResult<Vec<_>>>()?;
    let conflicts = detect_squad_review_conflicts(&assignments);
    let mut blockers = squad_pack.blockers.clone();
    if assignments.is_empty() {
        blockers.push("squad-review has no assignments to reconcile".into());
    }
    for assignment in &assignments {
        blockers.extend(assignment.blockers.clone());
    }
    if !conflicts.is_empty() {
        blockers.push(format!(
            "{} assignment ownership conflict(s) need coordination before parallel work continues",
            conflicts.len()
        ));
    }
    blockers.sort();
    blockers.dedup();

    let mut warnings = merge_many_sorted(vec![
        squad_pack.warnings.clone(),
        assignments
            .iter()
            .flat_map(|assignment| assignment.warnings.clone())
            .collect(),
    ]);
    warnings.sort();
    warnings.dedup();

    let complete_assignments = assignments
        .iter()
        .filter(|assignment| assignment.review_status == "complete")
        .count();
    let blocked_assignments = assignments
        .iter()
        .filter(|assignment| assignment.review_status == "blocked")
        .count();
    let status = if !blockers.is_empty() {
        "blocked"
    } else if !conflicts.is_empty() {
        "needsCoordination"
    } else if complete_assignments == assignments.len() && !assignments.is_empty() {
        "readyForIntegrationClaim"
    } else if assignments
        .iter()
        .any(|assignment| assignment.review_status == "needsEvidence")
    {
        "needsAgentEvidence"
    } else {
        "readyForAgents"
    }
    .to_string();
    let verdict = match status.as_str() {
        "readyForIntegrationClaim" => "allAssignmentsReviewed",
        "needsAgentEvidence" => "assignmentEvidenceMissing",
        "needsCoordination" => "ownershipConflict",
        "readyForAgents" => "assignmentsReady",
        _ => "squadReviewBlocked",
    }
    .to_string();

    let mut safe_to_say = squad_pack.safe_to_say.clone();
    if blockers.is_empty() {
        safe_to_say.push(format!(
            "Squad review inspected {} assignment{} and found {} complete.",
            assignments.len(),
            if assignments.len() == 1 { "" } else { "s" },
            complete_assignments
        ));
    }
    safe_to_say.sort();
    safe_to_say.dedup();
    let mut do_not_say = squad_pack.do_not_say.clone();
    do_not_say.extend([
        "Do not claim parallel agent assignments are complete until squad-review is readyForIntegrationClaim.".into(),
        "Do not treat journal entries as proof that validation passed.".into(),
        "Do not merge or report assignments with ownership conflicts until a refreshed squad-review is clean.".into(),
    ]);
    do_not_say.sort();
    do_not_say.dedup();

    let mut artifacts = squad_pack.artifacts.clone();
    artifacts.insert(
        "squadReview".into(),
        squad_review_path.to_string_lossy().to_string(),
    );
    if let Some(path) = markdown_path {
        artifacts.insert(
            "squadReviewMarkdown".into(),
            path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert("squadPack".into(), squad_pack.squad_pack_path.clone());

    let next_actions = build_squad_review_next_actions(&options.run_dir, &status, &assignments);
    let integration_prompt = build_squad_review_integration_prompt(
        &status,
        &options.run_dir,
        &assignments,
        &conflicts,
        &safe_to_say,
        &do_not_say,
    );
    let agent_brief = format!(
        "Squad review is {status}: {} assignment(s), {} complete, {} blocked, {} conflict(s).",
        assignments.len(),
        complete_assignments,
        blocked_assignments,
        conflicts.len()
    );

    Ok(SquadReviewReport {
        schema_version: "rs.autopilot.squad-review.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        squad_review_path: squad_review_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        status,
        verdict,
        squad_pack_path: squad_pack.squad_pack_path.clone(),
        assignment_count: assignments.len(),
        complete_assignments,
        blocked_assignments,
        conflict_count: conflicts.len(),
        integration_prompt,
        assignments,
        conflicts,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        squad_pack,
    })
}

fn build_squad_review_assignment(
    run_dir: &Path,
    assignment: &SquadAssignment,
) -> AppResult<SquadReviewAssignment> {
    let (present_artifacts, missing_artifacts, manual_evidence) =
        classify_work_check_expected_artifacts(run_dir, &assignment.expected_artifacts)?;
    let journal_recorded = assignment
        .primary_command
        .as_deref()
        .map(|command| work_check_journal_command_state(run_dir, command))
        .transpose()?
        .flatten();
    let mut blockers = assignment.blockers.clone();
    if assignment.status == "blocked" && blockers.is_empty() {
        blockers.push(format!("assignment `{}` is blocked", assignment.title));
    }
    if assignment.mutates_studio {
        blockers.push(format!(
            "assignment `{}` mutates Studio and cannot be integrated from squad-review",
            assignment.title
        ));
    }
    blockers.sort();
    blockers.dedup();

    let mut warnings = assignment.warnings.clone();
    if !missing_artifacts.is_empty() {
        warnings.push(format!(
            "{} expected artifact(s) are missing: {}",
            missing_artifacts.len(),
            missing_artifacts.join(", ")
        ));
    }
    if !manual_evidence.is_empty() {
        warnings.push(format!(
            "{} expected artifact(s) need manual evidence review: {}",
            manual_evidence.len(),
            manual_evidence.join(", ")
        ));
    }
    if journal_recorded == Some(false) {
        warnings.push("journal exists but does not record the assignment command".into());
    } else if journal_recorded.is_none() {
        warnings.push("journal evidence is missing for this assignment".into());
    }
    warnings.sort();
    warnings.dedup();

    let review_status = if !blockers.is_empty() {
        "blocked"
    } else if assignment.requires_live_studio {
        "gatedLiveTask"
    } else if !assignment.expected_artifacts.is_empty()
        && missing_artifacts.is_empty()
        && manual_evidence.is_empty()
        && journal_recorded == Some(true)
    {
        "complete"
    } else {
        "needsEvidence"
    }
    .to_string();
    let next_command = match review_status.as_str() {
        "complete" => Some(format!(
            "rs autopilot claim-check {} --claim \"Assignment {} evidence is ready\" --format json",
            command_arg(run_dir.to_string_lossy().as_ref()),
            shell_display_arg(&assignment.title)
        )),
        "needsEvidence" => assignment.primary_command.clone().or_else(|| {
            Some(format!(
                "rs autopilot task-pack {} --opportunity \"{}\" --format json",
                command_arg(run_dir.to_string_lossy().as_ref()),
                shell_display_arg(&assignment.title)
            ))
        }),
        "gatedLiveTask" => Some(format!("rs autopilot ready --timeout 90 --format json")),
        _ => Some(format!(
            "rs autopilot task-pack {} --opportunity \"{}\" --format json",
            command_arg(run_dir.to_string_lossy().as_ref()),
            shell_display_arg(&assignment.title)
        )),
    };

    Ok(SquadReviewAssignment {
        id: assignment.id.clone(),
        title: assignment.title.clone(),
        role: assignment.role.clone(),
        status: assignment.status.clone(),
        review_status,
        primary_command: assignment.primary_command.clone(),
        expected_artifacts: assignment.expected_artifacts.clone(),
        present_artifacts,
        missing_artifacts,
        manual_evidence,
        journal_recorded,
        validation_commands: assignment.validation_commands.clone(),
        ownership: assignment.ownership.clone(),
        blockers,
        warnings,
        next_command,
    })
}

fn detect_squad_review_conflicts(
    assignments: &[SquadReviewAssignment],
) -> Vec<SquadReviewConflict> {
    let mut by_artifact: BTreeMap<String, Vec<String>> = BTreeMap::new();
    for assignment in assignments {
        for artifact in &assignment.expected_artifacts {
            if work_check_requires_manual_evidence(artifact) {
                continue;
            }
            by_artifact
                .entry(artifact.to_ascii_lowercase())
                .or_default()
                .push(assignment.id.clone());
        }
    }
    let mut conflicts = Vec::new();
    for (index, (artifact, mut owners)) in by_artifact.into_iter().enumerate() {
        owners.sort();
        owners.dedup();
        if owners.len() > 1 {
            conflicts.push(SquadReviewConflict {
                id: format!("SQ-CONFLICT-{:03}", index + 1),
                kind: "artifactOwnership".into(),
                severity: "blocker".into(),
                artifact: artifact.clone(),
                assignments: owners.clone(),
                summary: format!(
                    "{} assignment(s) own expected artifact `{artifact}`",
                    owners.len()
                ),
            });
        }
    }
    conflicts
}

fn build_squad_review_next_actions(
    run_dir: &Path,
    status: &str,
    assignments: &[SquadReviewAssignment],
) -> Vec<CoachAction> {
    let mut actions = Vec::new();
    let run = command_arg(run_dir.to_string_lossy().as_ref());
    match status {
        "readyForIntegrationClaim" => actions.push(coach_action(
            1,
            "Check integration claim",
            Some(format!(
                "rs autopilot claim-check {run} --claim \"Squad assignments have reviewed evidence\" --format json"
            )),
            "Verify the exact summary claim before telling the creator the squad work is integrated.",
            false,
            false,
        )),
        "needsAgentEvidence" => {
            for (index, assignment) in assignments
                .iter()
                .filter(|assignment| assignment.review_status == "needsEvidence")
                .take(4)
                .enumerate()
            {
                actions.push(coach_action(
                    (index + 1) as u8,
                    &format!("Collect evidence for {}", assignment.title),
                    assignment.next_command.clone(),
                    "Run or reassign the lane, then refresh squad-review.",
                    false,
                    false,
                ));
            }
        }
        "blocked" | "needsCoordination" => actions.push(coach_action(
            1,
            "Refresh squad assignments",
            Some(format!("rs autopilot squad-pack {run} --format json")),
            "Resolve blockers or ownership conflicts before continuing parallel work.",
            false,
            false,
        )),
        _ => actions.push(coach_action(
            1,
            "Start first squad assignment",
            assignments.first().and_then(|assignment| assignment.primary_command.clone()),
            "Begin with the first ready assignment and preserve exact evidence.",
            false,
            false,
        )),
    }
    actions.push(coach_action(
        90,
        "Refresh squad review",
        Some(format!("rs autopilot squad-review {run} --format json")),
        "Regenerate the integration review after agent work, journal updates, or artifact changes.",
        false,
        false,
    ));
    dedup_next_actions(&mut actions);
    actions
}

fn build_squad_review_integration_prompt(
    status: &str,
    run_dir: &Path,
    assignments: &[SquadReviewAssignment],
    conflicts: &[SquadReviewConflict],
    safe_to_say: &[String],
    do_not_say: &[String],
) -> String {
    let mut lines = Vec::new();
    lines.push("You are the lead AI integrating parallel Roblox Autopilot squad work.".into());
    lines.push("Read AGENTS.md first, then read squad-review.json and squad-pack.json before assigning or reporting anything.".into());
    lines.push(format!("Run directory: {}", run_dir.to_string_lossy()));
    lines.push(format!("Review status: {status}"));
    lines.push("Assignments:".into());
    for assignment in assignments {
        lines.push(format!(
            "- {} [{}]: {}",
            assignment.id, assignment.review_status, assignment.title
        ));
        if let Some(command) = &assignment.next_command {
            lines.push(format!("  Next: {command}"));
        }
    }
    if !conflicts.is_empty() {
        lines.push("Ownership conflicts:".into());
        for conflict in conflicts {
            lines.push(format!(
                "- {} `{}` owned by {}",
                conflict.id,
                conflict.artifact,
                conflict.assignments.join(", ")
            ));
        }
    }
    if !safe_to_say.is_empty() {
        lines.push("Safe claims:".into());
        for claim in safe_to_say.iter().take(5) {
            lines.push(format!("- {claim}"));
        }
    }
    if !do_not_say.is_empty() {
        lines.push("Forbidden claims:".into());
        for claim in do_not_say.iter().take(6) {
            lines.push(format!("- {claim}"));
        }
    }
    lines.push("Before a creator-facing update, run claim-check on the exact wording and cite source artifacts. Do not claim live apply, playtest, rollback, publish, or production readiness from squad-review alone.".into());
    lines.join("\n")
}

fn build_wow_plan_report(
    options: &WowPlanOptions,
    wow_plan_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<WowPlanReport> {
    let prompt = resolve_planner_prompt(options.prompt.as_deref(), Some(&options.run_dir))?;
    let mut artifacts = collect_planner_run_artifacts(Some(&options.run_dir));
    artifacts.insert(
        "wowPlan".into(),
        wow_plan_path.to_string_lossy().to_string(),
    );
    if let Some(path) = markdown_path {
        artifacts.insert("wowPlanMarkdown".into(), path.to_string_lossy().to_string());
    }
    let artifact_context = collect_planner_artifact_context(Some(&options.run_dir))?;
    let current_signals = collect_wow_signals(&prompt, &artifacts, &artifact_context);
    let mut ideas = build_wow_ideas(
        &prompt,
        &options.run_dir,
        &current_signals,
        options.max_ideas,
    );
    let selected_idea = ideas.first().cloned();

    let mut blockers = Vec::new();
    if !options.run_dir.is_dir() {
        blockers.push(format!(
            "wow-plan run directory does not exist: {}",
            options.run_dir.display()
        ));
    }
    if ideas.is_empty() {
        blockers.push("wow-plan could not derive any safe wow candidates".into());
    }

    let mut warnings = Vec::new();
    if artifact_context.is_empty() {
        warnings.push(
            "No recognized JSON artifacts were available; wow-plan is using prompt-only heuristics."
                .into(),
        );
    }
    if options.max_ideas == 0 {
        warnings.push("Requested --max-ideas 0; one candidate was retained for usefulness.".into());
    }
    if options.limit == 0 {
        warnings.push("Requested --limit 0; cross-run context was not considered.".into());
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else {
        "readyForWowPlanning"
    }
    .to_string();
    let verdict = if status == "readyForWowPlanning" {
        "safeWowCandidateReady"
    } else {
        "needsRunContext"
    }
    .to_string();
    let theme = wow_theme(&prompt, &current_signals);
    let player_promise = wow_player_promise(&prompt, &theme, selected_idea.as_ref());
    let mut safe_to_say = vec![format!(
        "Wow-plan prepared {} non-mutating candidate{} for the current Roblox Autopilot run.",
        ideas.len(),
        if ideas.len() == 1 { "" } else { "s" }
    )];
    if let Some(idea) = &selected_idea {
        safe_to_say.push(format!(
            "The top candidate is `{}` and its next command is safe/offline.",
            idea.title
        ));
    }
    let do_not_say = vec![
        "Do not claim the wow feature exists until the selected safe command writes reviewable artifacts.".into(),
        "Do not claim live Studio apply, live playtest, publish readiness, or production readiness from wow-plan alone.".into(),
        "Do not invent commands or mutate Studio while following wow-plan; use only listed safe commands and proof requirements.".into(),
    ];
    let mut next_actions = build_wow_plan_next_actions(&options.run_dir, selected_idea.as_ref());
    dedup_next_actions(&mut next_actions);
    let agent_brief =
        build_wow_plan_agent_brief(&status, &theme, selected_idea.as_ref(), ideas.len());

    Ok(WowPlanReport {
        schema_version: "rs.autopilot.wow-plan.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        wow_plan_path: wow_plan_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        prompt,
        status,
        verdict,
        theme,
        player_promise,
        idea_count: ideas.len(),
        selected_idea,
        current_signals,
        wow_ideas: std::mem::take(&mut ideas),
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
    })
}

fn collect_wow_signals(
    prompt: &str,
    artifacts: &BTreeMap<String, String>,
    artifact_context: &BTreeMap<String, Value>,
) -> Vec<WowSignal> {
    let mut signals = Vec::new();
    let mut seen = BTreeSet::new();
    push_wow_signal(
        &mut signals,
        &mut seen,
        "prompt",
        "creatorIntent",
        format!("Resolved prompt: {prompt}"),
    );
    for (key, label) in [
        ("storyboard", "Storyboard exists, so player-facing beats can anchor the wow moment."),
        ("gameplayCritique", "Gameplay critique exists, so wow-plan can respond to playability gaps."),
        ("simulation", "Static simulation exists, so the candidate can preserve simulated loop assumptions."),
        ("featureGraph", "Feature graph exists, so the candidate can connect to named systems."),
        ("worldBlueprint", "World blueprint exists, so the candidate can reference spatial composition."),
        ("showcase", "Showcase exists, so the candidate can improve the demoable hero moment."),
        ("styleGuide", "Style guide exists, so the candidate can match the current visual language."),
        ("onboarding", "Onboarding exists, so the candidate can improve the first-session reveal."),
        ("assetBrief", "Asset brief exists, so the candidate can specify concrete props and presentation assets."),
        ("persistence", "Persistence exists, so the candidate can respect long-term progress promises."),
        ("social", "Social design exists, so the candidate can consider shared player moments."),
        ("monetization", "Monetization design exists, so the candidate can avoid unsafe economy claims."),
        ("liveops", "Liveops design exists, so the candidate can support recurring beats."),
    ] {
        if artifacts.contains_key(key) {
            push_wow_signal(&mut signals, &mut seen, key, "artifact", label);
        }
    }
    for (key, value) in artifact_context {
        if let Some(status) = value.get("status").and_then(Value::as_str) {
            push_wow_signal(
                &mut signals,
                &mut seen,
                key,
                "status",
                format!("{key} status is `{status}`"),
            );
        }
        if let Some(verdict) = value.get("verdict").and_then(Value::as_str) {
            push_wow_signal(
                &mut signals,
                &mut seen,
                key,
                "verdict",
                format!("{key} verdict is `{verdict}`"),
            );
        }
    }
    signals
}

fn push_wow_signal(
    signals: &mut Vec<WowSignal>,
    seen: &mut BTreeSet<String>,
    source: &str,
    kind: &str,
    detail: impl Into<String>,
) {
    let detail = detail.into();
    let key = format!("{source}\n{kind}\n{detail}");
    if seen.insert(key) {
        signals.push(WowSignal {
            source: source.into(),
            kind: kind.into(),
            detail,
        });
    }
}

fn build_wow_ideas(
    prompt: &str,
    run_dir: &Path,
    signals: &[WowSignal],
    max_ideas: usize,
) -> Vec<WowIdea> {
    let context = wow_context_text(prompt, signals);
    let mut ideas = Vec::new();
    let mut seen = BTreeSet::new();
    let mut push = |title: &str,
                    category: &str,
                    impact: u8,
                    confidence: u8,
                    player_moment: &str,
                    why: &str,
                    proof_needed: Vec<&str>,
                    risks: Vec<&str>| {
        if seen.insert(title.to_ascii_lowercase()) {
            ideas.push(wow_idea(
                run_dir,
                prompt,
                title,
                category,
                impact,
                confidence,
                player_moment,
                why,
                proof_needed,
                risks,
            ));
        }
    };

    if wow_contains_any(
        &context,
        &["tycoon", "shop", "cash", "coin", "upgrade", "save"],
    ) {
        push(
            "First Upgrade Ceremony",
            "progression",
            96,
            92,
            "The first purchase transforms a quiet plot into a visibly upgraded, animated earning machine with a clear before/after reveal.",
            "Tycoon and shop prompts need an early emotional payoff, not just counters and buttons.",
            vec!["plan.json includes the upgrade reveal", "preview.json names changed surfaces", "showcase.json scripts the before/after moment"],
            vec!["Balance the reward without implying paid advantages or unverified persistence."],
        );
        push(
            "Shopfront Showcase Moment",
            "presentation",
            91,
            88,
            "The shop physically lights up as the player approaches, highlights one affordable item, and previews the next aspirational purchase.",
            "A readable storefront gives the creator an instantly inspectable hero scene and makes the economy legible.",
            vec!["world-blueprint.json places the storefront", "asset-brief.json lists props and signs", "copy-deck.json includes item labels"],
            vec!["Keep copy short enough for Roblox UI and avoid purchase-pressure language."],
        );
    }
    if wow_contains_any(
        &context,
        &["obby", "checkpoint", "platform", "parkour", "jump"],
    ) {
        push(
            "Checkpoint Celebration Chain",
            "skill",
            92,
            86,
            "Each checkpoint triggers a compact burst of color, sound-ready copy, and a visible path preview to the next challenge.",
            "Obstacle courses feel alive when success is acknowledged and the next goal is immediately clear.",
            vec!["plan.json includes checkpoint feedback", "playtest-plan.json covers checkpoint recovery", "accessibility.json checks readable cues"],
            vec!["Avoid visual noise that hides platforms or creates motion-sickness risk."],
        );
    }
    if wow_contains_any(&context, &["quest", "npc", "story", "dialog", "mission"]) {
        push(
            "Living Quest Giver",
            "narrative",
            90,
            84,
            "A memorable NPC reacts to the player's first action, points at the next objective, and rewards completion with a visible world change.",
            "Quest prompts need a characterful first contact so objectives feel authored instead of generic.",
            vec!["storyboard.json names the NPC beat", "copy-deck.json includes dialog", "feature-graph.json links objective and reward"],
            vec!["Keep dialog deterministic and do not imply AI-generated live NPC behavior."],
        );
    }
    if wow_contains_any(
        &context,
        &["friend", "social", "party", "coop", "co-op", "team"],
    ) {
        push(
            "Shared Flex Plaza",
            "social",
            88,
            80,
            "Players can stand in a central plaza that displays recent progress milestones and gives friends a reason to gather before playing.",
            "Social games need an obvious shared focal point before deeper multiplayer systems exist.",
            vec!["social.json describes the shared beat", "world-blueprint.json places the plaza", "policy.json checks safe display copy"],
            vec!["Do not expose private player data or claim live multiplayer proof without Studio evidence."],
        );
    }
    if wow_contains_any(
        &context,
        &["pet", "collect", "companion", "hatch", "creature"],
    ) {
        push(
            "Companion Reveal Moment",
            "collection",
            89,
            82,
            "The first collectible companion appears through a staged reveal with clear rarity-safe copy and an immediate small interaction.",
            "Collection loops become memorable when the first reward feels like an event.",
            vec!["asset-brief.json specifies the companion", "copy-deck.json avoids gambling-coded claims", "showcase.json scripts the reveal"],
            vec!["Avoid randomized monetization language and unverified animation claims."],
        );
    }
    push(
        "Showcase-Ready Hero Loop",
        "demo",
        87,
        78,
        "Within sixty seconds, the player sees the core loop, receives one visible reward, and can explain what makes this game distinct.",
        "Every Autopilot run benefits from one tight, creator-inspectable moment that turns scattered systems into a product demo.",
        vec!["showcase.json includes a 60-second route", "gameplay-critique.json evaluates friction", "completion-audit.json checks claim support"],
        vec!["This is a planning artifact until compose/showcase/proof artifacts are refreshed."],
    );
    push(
        "Guided First-Minute Spark",
        "onboarding",
        84,
        76,
        "The first minute uses one glowing objective, one short UI line, and one visible reward so a new player never wonders what to do.",
        "A strong onboarding spark makes even a simple Roblox slice feel intentional.",
        vec!["onboarding.json describes the first-minute route", "ux.json checks surface clarity", "copy-deck.json contains the short UI line"],
        vec!["Do not overload the first screen or hide core controls behind narration."],
    );

    ideas.sort_by(|left, right| {
        right
            .impact
            .cmp(&left.impact)
            .then(right.confidence.cmp(&left.confidence))
            .then(left.title.cmp(&right.title))
    });
    ideas.truncate(max_ideas.clamp(1, 8));
    for (index, idea) in ideas.iter_mut().enumerate() {
        idea.id = format!("WOW-{:03}", index + 1);
    }
    ideas
}

fn wow_context_text(prompt: &str, signals: &[WowSignal]) -> String {
    let mut text = prompt.to_ascii_lowercase();
    for signal in signals {
        text.push(' ');
        text.push_str(&signal.source.to_ascii_lowercase());
        text.push(' ');
        text.push_str(&signal.kind.to_ascii_lowercase());
        text.push(' ');
        text.push_str(&signal.detail.to_ascii_lowercase());
    }
    text
}

fn wow_contains_any(text: &str, needles: &[&str]) -> bool {
    needles.iter().any(|needle| text.contains(needle))
}

fn wow_idea(
    run_dir: &Path,
    prompt: &str,
    title: &str,
    category: &str,
    impact: u8,
    confidence: u8,
    player_moment: &str,
    why: &str,
    proof_needed: Vec<&str>,
    risks: Vec<&str>,
) -> WowIdea {
    let out_dir = default_wow_candidate_dir(run_dir, title);
    let command_prompt = format!("{prompt}. Add this wow factor: {title}. {player_moment}");
    let safe_command = format!(
        "rs autopilot compose {} --out {} --format json",
        command_arg(&command_prompt),
        command_arg(out_dir.to_string_lossy().as_ref())
    );
    let expected_artifacts = expected_artifacts_for_command(&safe_command);
    WowIdea {
        id: "WOW-000".into(),
        title: title.into(),
        category: category.into(),
        impact,
        confidence,
        player_moment: player_moment.into(),
        why: why.into(),
        expected_artifacts,
        proof_needed: proof_needed.into_iter().map(str::to_string).collect(),
        risks: risks.into_iter().map(str::to_string).collect(),
        safe_command,
        requires_live_studio: false,
        mutates_studio: false,
    }
}

fn default_wow_candidate_dir(run_dir: &Path, title: &str) -> PathBuf {
    let base = run_dir
        .file_name()
        .and_then(|name| name.to_str())
        .map(str::to_string)
        .unwrap_or_else(|| "run".into());
    run_dir.with_file_name(format!("{}-wow-{}", base, slug(title)))
}

fn wow_theme(prompt: &str, signals: &[WowSignal]) -> String {
    let context = wow_context_text(prompt, signals);
    if wow_contains_any(
        &context,
        &["tycoon", "shop", "cash", "coin", "upgrade", "save"],
    ) {
        "progression and visible reward".into()
    } else if wow_contains_any(
        &context,
        &["obby", "checkpoint", "platform", "parkour", "jump"],
    ) {
        "skill challenge and celebration".into()
    } else if wow_contains_any(&context, &["quest", "npc", "story", "dialog", "mission"]) {
        "character-led objective clarity".into()
    } else if wow_contains_any(
        &context,
        &["friend", "social", "party", "coop", "co-op", "team"],
    ) {
        "shared social arrival".into()
    } else if wow_contains_any(
        &context,
        &["pet", "collect", "companion", "hatch", "creature"],
    ) {
        "collection reveal and attachment".into()
    } else {
        "showcase-ready first minute".into()
    }
}

fn wow_player_promise(prompt: &str, theme: &str, selected_idea: Option<&WowIdea>) -> String {
    match selected_idea {
        Some(idea) => format!(
            "For `{prompt}`, the wow factor should make `{theme}` tangible through `{}`: {}",
            idea.title, idea.player_moment
        ),
        None => format!("For `{prompt}`, the wow factor should focus on `{theme}`."),
    }
}

fn build_wow_plan_next_actions(
    run_dir: &Path,
    selected_idea: Option<&WowIdea>,
) -> Vec<CoachAction> {
    let run = command_arg(run_dir.to_string_lossy().as_ref());
    let mut actions = Vec::new();
    if let Some(idea) = selected_idea {
        actions.push(coach_action(
            1,
            &format!("Build candidate: {}", idea.title),
            Some(idea.safe_command.clone()),
            "Generate a separate offline candidate run for the selected wow moment before claiming it exists.",
            false,
            false,
        ));
        actions.push(coach_action(
            2,
            "Prepare implementation task",
            Some(format!(
                "rs autopilot task-pack {run} --opportunity {} --format json",
                command_arg(&idea.title)
            )),
            "Hand a coding agent the selected wow moment with proof requirements and stop conditions.",
            false,
            false,
        ));
    }
    actions.push(coach_action(
        90,
        "Refresh wow plan",
        Some(format!("rs autopilot wow-plan {run} --format json")),
        "Regenerate creative candidates after new artifacts, critique, or creator decisions change the run.",
        false,
        false,
    ));
    actions.push(coach_action(
        95,
        "Check creator-facing claim",
        Some(format!(
            "rs autopilot claim-check {run} --claim \"A safe wow candidate is ready to build\" --format json"
        )),
        "Verify any summary wording before telling the creator what is ready.",
        false,
        false,
    ));
    actions
}

fn build_wow_plan_agent_brief(
    status: &str,
    theme: &str,
    selected_idea: Option<&WowIdea>,
    idea_count: usize,
) -> String {
    match selected_idea {
        Some(idea) => format!(
            "Wow-plan is {status}: {idea_count} safe candidate(s), theme `{theme}`, top idea `{}`. Run the listed safe command before claiming the feature exists.",
            idea.title
        ),
        None => format!(
            "Wow-plan is {status}: no safe candidate was selected for theme `{theme}`. Refresh run artifacts or provide a sharper prompt."
        ),
    }
}

fn build_moment_pack_report(
    options: &MomentPackOptions,
    moment_pack_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<MomentPackReport> {
    let child_markdown = markdown_path.is_some();
    let wow_plan_path = options.run_dir.join("wow-plan.json");
    let wow_plan_markdown_path = child_markdown.then(|| options.run_dir.join("wow-plan.md"));
    let wow_options = WowPlanOptions {
        prompt: options.prompt.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        max_ideas: options.max_ideas,
        out: Some(wow_plan_path.clone()),
        markdown: wow_plan_markdown_path.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let wow_plan = build_wow_plan_report(
        &wow_options,
        &wow_plan_path,
        wow_plan_markdown_path.as_deref(),
    )?;
    write_json(wow_plan_path.clone(), &wow_plan)?;
    if let Some(path) = wow_plan_markdown_path {
        write_wow_plan_markdown(path, &wow_plan)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;

    let (selected_idea, selected_idea_source, mut selection_blockers) =
        select_moment_pack_idea(&wow_plan, options.idea.as_deref());
    let candidate_run_dir = selected_idea
        .as_ref()
        .map(|idea| default_wow_candidate_dir(&options.run_dir, &idea.title));
    let build_lanes = selected_idea
        .as_ref()
        .map(|idea| build_moment_pack_lanes(&options.run_dir, candidate_run_dir.as_deref(), idea))
        .unwrap_or_default();
    let proof_checklist = build_moment_pack_proof_checklist(selected_idea.as_ref(), &build_lanes);
    let validation_commands = build_moment_pack_validation_commands(candidate_run_dir.as_deref());

    let mut blockers = wow_plan.blockers.clone();
    blockers.append(&mut selection_blockers);
    if selected_idea.is_none() {
        blockers.push("moment-pack could not select a wow idea to implement".into());
    }
    blockers.sort();
    blockers.dedup();

    let mut warnings = wow_plan.warnings.clone();
    if options.max_chars < 2_000 {
        warnings
            .push("Requested --max-chars below 2000; task prompt may omit useful context.".into());
    }
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else {
        "readyForMomentAgent"
    }
    .to_string();
    let verdict = if status == "readyForMomentAgent" {
        "implementationPromptReady"
    } else {
        "needsSelectedWowIdea"
    }
    .to_string();

    let mut artifacts = wow_plan.artifacts.clone();
    artifacts.insert(
        "momentPack".into(),
        moment_pack_path.to_string_lossy().to_string(),
    );
    if let Some(path) = markdown_path {
        artifacts.insert(
            "momentPackMarkdown".into(),
            path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert("wowPlan".into(), wow_plan.wow_plan_path.clone());

    let implementation_brief =
        build_moment_pack_implementation_brief(&wow_plan, selected_idea.as_ref(), &build_lanes);
    let mut safe_to_say = wow_plan.safe_to_say.clone();
    if let Some(idea) = &selected_idea {
        safe_to_say.push(format!(
            "Moment pack prepared an implementation brief for `{}` without mutating Studio.",
            idea.title
        ));
    }
    safe_to_say.sort();
    safe_to_say.dedup();
    let mut do_not_say = wow_plan.do_not_say.clone();
    do_not_say.extend([
        "Do not claim moment-pack built the wow moment; it only prepared the agent brief and proof checklist.".into(),
        "Do not skip the candidate compose run, validation commands, proof refresh, or claim-check before reporting implementation.".into(),
    ]);
    do_not_say.sort();
    do_not_say.dedup();

    let mut next_actions = build_moment_pack_next_actions(
        &options.run_dir,
        candidate_run_dir.as_deref(),
        selected_idea.as_ref(),
    );
    dedup_next_actions(&mut next_actions);
    let task_prompt = truncate_chars(
        &build_moment_pack_task_prompt(
            &status,
            &options.run_dir,
            candidate_run_dir.as_deref(),
            selected_idea.as_ref(),
            &build_lanes,
            &proof_checklist,
            &validation_commands,
            &safe_to_say,
            &do_not_say,
        ),
        options.max_chars.max(1),
    );
    let agent_brief = build_moment_pack_agent_brief(&status, selected_idea.as_ref(), &build_lanes);

    Ok(MomentPackReport {
        schema_version: "rs.autopilot.moment-pack.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        moment_pack_path: moment_pack_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        prompt: wow_plan.prompt.clone(),
        status,
        verdict,
        selected_idea_source,
        selected_idea,
        candidate_run_dir: candidate_run_dir.map(|path| path.to_string_lossy().to_string()),
        implementation_brief,
        task_prompt,
        build_lanes,
        proof_checklist,
        validation_commands,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        wow_plan,
    })
}

fn select_moment_pack_idea(
    wow_plan: &WowPlanReport,
    requested: Option<&str>,
) -> (Option<WowIdea>, String, Vec<String>) {
    let Some(requested) = requested.map(str::trim).filter(|value| !value.is_empty()) else {
        return (
            wow_plan.selected_idea.clone(),
            "wow-plan selectedIdea".into(),
            Vec::new(),
        );
    };
    let requested_lower = requested.to_ascii_lowercase();
    if let Some(idea) = wow_plan.wow_ideas.iter().find(|idea| {
        idea.id.eq_ignore_ascii_case(requested)
            || idea.title.to_ascii_lowercase() == requested_lower
    }) {
        return (
            Some(idea.clone()),
            format!("requested idea `{requested}`"),
            Vec::new(),
        );
    }
    (
        wow_plan.selected_idea.clone(),
        format!("fallback after missing requested idea `{requested}`"),
        vec![format!(
            "requested moment-pack idea `{requested}` was not found in wow-plan"
        )],
    )
}

fn build_moment_pack_lanes(
    run_dir: &Path,
    candidate_run_dir: Option<&Path>,
    idea: &WowIdea,
) -> Vec<MomentBuildLane> {
    let candidate = candidate_run_dir.unwrap_or(run_dir);
    let candidate_arg = command_arg(candidate.to_string_lossy().as_ref());
    let source_arg = command_arg(run_dir.to_string_lossy().as_ref());
    vec![
        MomentBuildLane {
            id: "MOMENT-001".into(),
            title: "Generate offline candidate".into(),
            objective: format!(
                "Create a separate candidate run for `{}` so the source run stays inspectable.",
                idea.title
            ),
            ownership: vec![
                format!("Own the candidate run folder `{}`.", candidate.to_string_lossy()),
                "Do not mutate Studio, publish, upload assets, or overwrite the source run.".into(),
            ],
            commands: vec![idea.safe_command.clone()],
            expected_artifacts: idea.expected_artifacts.clone(),
            proof_needed: idea.proof_needed.clone(),
            stop_conditions: vec![
                "Stop if compose fails or writes outside the candidate run folder.".into(),
                "Stop if generated artifacts do not mention the selected player moment.".into(),
            ],
            requires_live_studio: false,
            mutates_studio: false,
        },
        MomentBuildLane {
            id: "MOMENT-002".into(),
            title: "Refresh experience proof".into(),
            objective: "Turn the candidate into reviewable player-facing evidence.".into(),
            ownership: vec![
                "Own showcase, critique, and completion artifacts for the candidate run.".into(),
                "Do not claim live playtest success without separate live evidence.".into(),
            ],
            commands: vec![
                format!("rs autopilot showcase {candidate_arg} --format json"),
                format!("rs autopilot critique {candidate_arg} --format json"),
                format!("rs autopilot completion-audit {candidate_arg} --format json"),
            ],
            expected_artifacts: vec![
                "showcase.json".into(),
                "showcase.md".into(),
                "gameplay-critique.json".into(),
                "gameplay-critique.md".into(),
                "completion-audit.json".into(),
                "completion-audit.md".into(),
            ],
            proof_needed: vec![
                "showcase route includes the selected moment".into(),
                "gameplay critique does not flag the moment as disconnected".into(),
                "completion audit separates offline readiness from live proof".into(),
            ],
            stop_conditions: vec![
                "Stop if critique finds the candidate unplayable or disconnected.".into(),
                "Stop before applying the candidate to Studio.".into(),
            ],
            requires_live_studio: false,
            mutates_studio: false,
        },
        MomentBuildLane {
            id: "MOMENT-003".into(),
            title: "Package claim-safe handoff".into(),
            objective: "Prepare exact language and follow-up work only after artifacts exist.".into(),
            ownership: vec![
                "Own claim-check, task-pack refresh, and source-to-candidate handoff notes.".into(),
                "Do not report implementation until candidate artifacts and claim-check support it.".into(),
            ],
            commands: vec![
                format!(
                    "rs autopilot claim-check {candidate_arg} --claim {} --format json",
                    command_arg(&format!(
                        "{} has a reviewable offline candidate",
                        idea.title
                    ))
                ),
                format!(
                    "rs autopilot task-pack {source_arg} --opportunity {} --format json",
                    command_arg(&idea.title)
                ),
                format!("rs autopilot moment-pack {source_arg} --format json"),
            ],
            expected_artifacts: vec![
                "claim-check.json".into(),
                "claim-check.md".into(),
                "task-pack.json".into(),
                "task-pack.md".into(),
                "moment-pack.json".into(),
                "moment-pack.md".into(),
            ],
            proof_needed: vec![
                "claim-check passes the exact candidate summary".into(),
                "task-pack carries stop conditions for remaining implementation work".into(),
            ],
            stop_conditions: vec![
                "Stop if claim-check blocks or weakens the implementation claim.".into(),
                "Stop if task-pack selects a live or mutating primary command.".into(),
            ],
            requires_live_studio: false,
            mutates_studio: false,
        },
    ]
}

fn build_moment_pack_proof_checklist(
    idea: Option<&WowIdea>,
    lanes: &[MomentBuildLane],
) -> Vec<String> {
    let mut checks = Vec::new();
    if let Some(idea) = idea {
        checks.push(format!(
            "Selected idea `{}` appears in candidate plan, preview, and showcase artifacts.",
            idea.title
        ));
        checks.push(format!(
            "Player moment is inspectable: {}",
            idea.player_moment
        ));
    }
    for lane in lanes {
        for artifact in &lane.expected_artifacts {
            checks.push(format!(
                "{} expected artifact exists or is explicitly blocked: {}",
                lane.id, artifact
            ));
        }
    }
    checks.push(
        "Every validation command in moment-pack validationCommands has a recorded result.".into(),
    );
    checks.push("Creator-facing summary passes claim-check before reporting.".into());
    checks.sort();
    checks.dedup();
    checks
}

fn build_moment_pack_validation_commands(candidate_run_dir: Option<&Path>) -> Vec<String> {
    let Some(candidate) = candidate_run_dir else {
        return Vec::new();
    };
    let candidate = command_arg(candidate.to_string_lossy().as_ref());
    vec![
        format!("rs autopilot proof {candidate} --format json"),
        format!("rs autopilot acceptance {candidate} --format json"),
        format!("rs autopilot completion-audit {candidate} --format json"),
        format!("rs autopilot claim-check {candidate} --claim \"The wow candidate has reviewable offline evidence\" --format json"),
    ]
}

fn build_moment_pack_implementation_brief(
    wow_plan: &WowPlanReport,
    idea: Option<&WowIdea>,
    lanes: &[MomentBuildLane],
) -> String {
    let mut lines = Vec::new();
    lines.push("Moment pack converts a selected wow-plan idea into one executable offline implementation brief.".into());
    lines.push(format!("Run: {}", wow_plan.run_dir));
    lines.push(format!("Theme: {}", wow_plan.theme));
    if let Some(idea) = idea {
        lines.push(format!("Selected idea: {} ({})", idea.title, idea.category));
        lines.push(format!("Player moment: {}", idea.player_moment));
        lines.push(format!("Why it matters: {}", idea.why));
        lines.push(format!("First safe command: {}", idea.safe_command));
    }
    lines.push("Build lanes:".into());
    for lane in lanes {
        lines.push(format!("- {}: {}", lane.id, lane.title));
    }
    lines.push(
        "This packet does not build, apply, playtest live, publish, or prove completion by itself."
            .into(),
    );
    lines.join("\n")
}

fn build_moment_pack_next_actions(
    run_dir: &Path,
    candidate_run_dir: Option<&Path>,
    idea: Option<&WowIdea>,
) -> Vec<CoachAction> {
    let source = command_arg(run_dir.to_string_lossy().as_ref());
    let mut actions = Vec::new();
    if let Some(idea) = idea {
        actions.push(coach_action(
            1,
            &format!("Generate candidate for {}", idea.title),
            Some(idea.safe_command.clone()),
            "Create the separate offline candidate before reporting implementation progress.",
            false,
            false,
        ));
    }
    if let Some(candidate) = candidate_run_dir {
        let candidate = command_arg(candidate.to_string_lossy().as_ref());
        actions.push(coach_action(
            2,
            "Refresh candidate showcase",
            Some(format!("rs autopilot showcase {candidate} --format json")),
            "Make the player moment inspectable in the candidate run.",
            false,
            false,
        ));
        actions.push(coach_action(
            3,
            "Check candidate claim",
            Some(format!(
                "rs autopilot claim-check {candidate} --claim \"The wow candidate has reviewable offline evidence\" --format json"
            )),
            "Verify exact creator-facing wording after candidate artifacts exist.",
            false,
            false,
        ));
    }
    actions.push(coach_action(
        90,
        "Refresh moment pack",
        Some(format!("rs autopilot moment-pack {source} --format json")),
        "Regenerate the implementation packet after candidate artifacts or creator decisions change.",
        false,
        false,
    ));
    actions
}

fn build_moment_pack_task_prompt(
    status: &str,
    run_dir: &Path,
    candidate_run_dir: Option<&Path>,
    idea: Option<&WowIdea>,
    lanes: &[MomentBuildLane],
    proof_checklist: &[String],
    validation_commands: &[String],
    safe_to_say: &[String],
    do_not_say: &[String],
) -> String {
    let mut lines = Vec::new();
    lines.push(
        "You are an AI agent implementing a memorable Roblox player moment from moment-pack."
            .into(),
    );
    lines.push("Read AGENTS.md first, then read moment-pack.json and wow-plan.json before running commands.".into());
    lines.push(format!("Source run: {}", run_dir.to_string_lossy()));
    if let Some(candidate) = candidate_run_dir {
        lines.push(format!("Candidate run: {}", candidate.to_string_lossy()));
    }
    lines.push(format!("Moment-pack status: {status}"));
    if let Some(idea) = idea {
        lines.push(format!("Selected idea: {}", idea.title));
        lines.push(format!("Player moment: {}", idea.player_moment));
        lines.push(format!("Safe first command: {}", idea.safe_command));
    }
    lines.push("Build lanes:".into());
    for lane in lanes {
        lines.push(format!("- {} {}: {}", lane.id, lane.title, lane.objective));
        for command in &lane.commands {
            lines.push(format!("  Command: {command}"));
        }
        for condition in &lane.stop_conditions {
            lines.push(format!("  Stop: {condition}"));
        }
    }
    lines.push("Proof checklist:".into());
    for check in proof_checklist {
        lines.push(format!("- {check}"));
    }
    if !validation_commands.is_empty() {
        lines.push("Validation commands:".into());
        for command in validation_commands {
            lines.push(format!("- {command}"));
        }
    }
    if !safe_to_say.is_empty() {
        lines.push("Safe claims:".into());
        for claim in safe_to_say.iter().take(6) {
            lines.push(format!("- {claim}"));
        }
    }
    if !do_not_say.is_empty() {
        lines.push("Forbidden claims:".into());
        for claim in do_not_say.iter().take(8) {
            lines.push(format!("- {claim}"));
        }
    }
    lines.push("Report only exact commands run, exact results, artifacts written, and blockers. Do not claim live apply, live playtest, rollback, publish, or production readiness from this packet.".into());
    lines.join("\n")
}

fn build_moment_pack_agent_brief(
    status: &str,
    idea: Option<&WowIdea>,
    lanes: &[MomentBuildLane],
) -> String {
    match idea {
        Some(idea) => format!(
            "Moment pack is {status}: `{}` is ready for {} offline implementation lane(s). Start with the candidate compose command and prove the moment before reporting it.",
            idea.title,
            lanes.len()
        ),
        None => format!(
            "Moment pack is {status}: no wow idea was selected, so no implementation lane is safe to run."
        ),
    }
}

fn build_moment_sprint_report(
    options: &MomentSprintOptions,
    sprint_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<MomentSprintReport> {
    let child_markdown = markdown_path.is_some();
    let moment_pack_path = options.run_dir.join("moment-pack.json");
    let moment_pack_markdown_path = child_markdown.then(|| options.run_dir.join("moment-pack.md"));
    let pack_options = MomentPackOptions {
        prompt: options.prompt.clone(),
        idea: options.idea.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        max_ideas: options.max_ideas,
        max_chars: options.max_chars,
        out: Some(moment_pack_path.clone()),
        markdown: moment_pack_markdown_path.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let moment_pack = build_moment_pack_report(
        &pack_options,
        &moment_pack_path,
        moment_pack_markdown_path.as_deref(),
    )?;
    write_json(moment_pack_path.clone(), &moment_pack)?;
    if let Some(path) = moment_pack_markdown_path {
        write_moment_pack_markdown(path, &moment_pack)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;

    let selected_idea = moment_pack.selected_idea.clone();
    let candidate_run_dir = moment_pack
        .candidate_run_dir
        .as_deref()
        .map(PathBuf::from)
        .or_else(|| {
            selected_idea
                .as_ref()
                .map(|idea| default_wow_candidate_dir(&options.run_dir, &idea.title))
        });

    let mut artifacts = moment_pack.artifacts.clone();
    artifacts.insert(
        "momentSprint".into(),
        sprint_path.to_string_lossy().to_string(),
    );
    if let Some(path) = markdown_path {
        artifacts.insert(
            "momentSprintMarkdown".into(),
            path.to_string_lossy().to_string(),
        );
    }

    let mut blockers = moment_pack.blockers.clone();
    let mut warnings = moment_pack.warnings.clone();
    let mut steps = Vec::new();

    if options.dry_run {
        steps.extend(build_moment_sprint_dry_run_steps(&moment_pack));
    } else if let (Some(idea), Some(candidate)) =
        (selected_idea.as_ref(), candidate_run_dir.as_ref())
    {
        run_moment_sprint_candidate(
            options,
            idea,
            candidate,
            &mut steps,
            &mut artifacts,
            &mut blockers,
            &mut warnings,
        );
    } else {
        blockers.push("moment-sprint could not resolve a selected idea and candidate run".into());
    }

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    let failed_steps = steps.iter().filter(|step| step.status == "failed").count();
    let executed_steps = steps
        .iter()
        .filter(|step| step.status == "executed" || step.status == "warn")
        .count();
    let status = if options.dry_run {
        "dryRun"
    } else if failed_steps > 0 || !blockers.is_empty() {
        "candidateBlocked"
    } else {
        "candidateReviewReady"
    }
    .to_string();
    let verdict = match status.as_str() {
        "dryRun" => "safeOfflineCandidatePlanned",
        "candidateReviewReady" => "offlineCandidateBuiltAndReviewed",
        _ => "offlineCandidateNeedsAttention",
    }
    .to_string();
    let mut safe_to_say = moment_pack.safe_to_say.clone();
    if status == "candidateReviewReady" {
        if let Some(idea) = &selected_idea {
            safe_to_say.push(format!(
                "Moment sprint produced a reviewable offline candidate for `{}`.",
                idea.title
            ));
        }
    } else if options.dry_run {
        safe_to_say.push("Moment sprint dry-run listed the safe offline candidate steps.".into());
    }
    safe_to_say.sort();
    safe_to_say.dedup();
    let mut do_not_say = moment_pack.do_not_say.clone();
    do_not_say.extend([
        "Do not claim moment-sprint applied anything to Studio; it only writes offline candidate artifacts.".into(),
        "Do not claim live playtest, rollback, publish, or production readiness from moment-sprint alone.".into(),
    ]);
    do_not_say.sort();
    do_not_say.dedup();
    let mut next_actions = build_moment_sprint_next_actions(
        &options.run_dir,
        candidate_run_dir.as_deref(),
        selected_idea.as_ref(),
        &status,
    );
    dedup_next_actions(&mut next_actions);
    let agent_brief = build_moment_sprint_agent_brief(
        &status,
        selected_idea.as_ref(),
        candidate_run_dir.as_deref(),
        executed_steps,
        failed_steps,
    );

    Ok(MomentSprintReport {
        schema_version: "rs.autopilot.moment-sprint.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        moment_sprint_path: sprint_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        prompt: moment_pack.prompt.clone(),
        status,
        verdict,
        dry_run: options.dry_run,
        selected_idea,
        candidate_run_dir: candidate_run_dir.map(|path| path.to_string_lossy().to_string()),
        executed_steps: steps,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        moment_pack,
    })
}

fn build_moment_sprint_dry_run_steps(moment_pack: &MomentPackReport) -> Vec<MomentSprintStep> {
    let mut steps = Vec::new();
    for lane in &moment_pack.build_lanes {
        for (index, command) in lane.commands.iter().enumerate() {
            steps.push(moment_sprint_step(
                &format!("{}-{:02}", lane.id, index + 1),
                &lane.title,
                "dryRun",
                "Selected safe offline command without executing it.",
                Some(command.clone()),
                lane.expected_artifacts.clone(),
                None,
                lane.requires_live_studio,
                lane.mutates_studio,
            ));
        }
    }
    steps
}

fn run_moment_sprint_candidate(
    options: &MomentSprintOptions,
    idea: &WowIdea,
    candidate: &Path,
    steps: &mut Vec<MomentSprintStep>,
    artifacts: &mut BTreeMap<String, String>,
    blockers: &mut Vec<String>,
    warnings: &mut Vec<String>,
) {
    let prompt = moment_candidate_prompt(&options.prompt, &options.run_dir, idea);
    let compose_options = ComposeOptions {
        port: 7878,
        prompt: Some(prompt),
        studio: None,
        scope: "Workspace".into(),
        out: Some(candidate.to_path_buf()),
        preset: None,
        recipes: Vec::new(),
        from_manifest: None,
        smoke: None,
        json: false,
    };
    match write_compose_artifacts(&compose_options) {
        Ok((candidate_dir, plan, _preview)) => {
            let plan_path = candidate_dir.join("plan.json");
            let compose_artifacts = vec![
                candidate_dir.join("request.json"),
                candidate_dir.join("plan.json"),
                candidate_dir.join("preview.json"),
                candidate_dir.join("generated"),
            ];
            steps.push(moment_sprint_step(
                "MOMENT-SPRINT-001",
                "Generate offline candidate",
                "executed",
                "Created the candidate run from the selected wow moment.",
                Some(idea.safe_command.clone()),
                paths_to_strings(compose_artifacts),
                None,
                false,
                false,
            ));
            artifacts.insert(
                "candidateRun".into(),
                candidate_dir.to_string_lossy().to_string(),
            );
            artifacts.insert(
                "candidatePlan".into(),
                plan_path.to_string_lossy().to_string(),
            );
            run_moment_sprint_review_steps(
                &candidate_dir,
                &plan_path,
                &plan,
                idea,
                steps,
                artifacts,
                blockers,
                warnings,
            );
        }
        Err(err) => {
            blockers.push(format!("candidate compose failed: {err}"));
            steps.push(moment_sprint_step(
                "MOMENT-SPRINT-001",
                "Generate offline candidate",
                "failed",
                "The safe offline compose step failed.",
                Some(idea.safe_command.clone()),
                Vec::new(),
                Some(err.to_string()),
                false,
                false,
            ));
        }
    }
}

fn moment_candidate_prompt(
    prompt_override: &Option<String>,
    run_dir: &Path,
    idea: &WowIdea,
) -> String {
    let prompt = prompt_override
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_string)
        .or_else(|| resolve_planner_prompt(None, Some(run_dir)).ok())
        .unwrap_or_else(|| "Create a safe, reviewable Roblox gameplay feature plan".into());
    format!(
        "{prompt}. Add this wow factor: {}. {}",
        idea.title, idea.player_moment
    )
}

fn run_moment_sprint_review_steps(
    candidate_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    idea: &WowIdea,
    steps: &mut Vec<MomentSprintStep>,
    artifacts: &mut BTreeMap<String, String>,
    blockers: &mut Vec<String>,
    warnings: &mut Vec<String>,
) {
    let showcase_path = candidate_dir.join("showcase.json");
    let showcase_md = candidate_dir.join("showcase.md");
    match build_showcase_report(
        candidate_dir,
        plan_path,
        plan,
        &showcase_path,
        Some(&showcase_md),
    ) {
        Ok(report) => {
            if let Err(err) = write_json(showcase_path.clone(), &report)
                .and_then(|_| write_showcase_markdown(showcase_md.clone(), &report))
            {
                blockers.push(format!("showcase write failed: {err}"));
                steps.push(moment_sprint_step(
                    "MOMENT-SPRINT-002",
                    "Refresh showcase",
                    "failed",
                    "Showcase report could not be written.",
                    Some(format!(
                        "rs autopilot showcase {} --format json",
                        command_arg(candidate_dir.to_string_lossy().as_ref())
                    )),
                    Vec::new(),
                    Some(err.to_string()),
                    false,
                    false,
                ));
            } else {
                warnings.extend(report.warnings.clone());
                artifacts.insert("candidateShowcase".into(), report.showcase_path.clone());
                steps.push(moment_sprint_step(
                    "MOMENT-SPRINT-002",
                    "Refresh showcase",
                    "executed",
                    "Wrote candidate showcase guidance for the selected moment.",
                    Some(format!(
                        "rs autopilot showcase {} --format json",
                        command_arg(candidate_dir.to_string_lossy().as_ref())
                    )),
                    vec![
                        report.showcase_path,
                        report.markdown_path.unwrap_or_default(),
                    ],
                    None,
                    false,
                    false,
                ));
            }
        }
        Err(err) => push_moment_sprint_failed_step(
            steps,
            blockers,
            "MOMENT-SPRINT-002",
            "Refresh showcase",
            "showcase generation failed",
            err,
        ),
    }

    let critique_path = candidate_dir.join("gameplay-critique.json");
    let critique_md = candidate_dir.join("gameplay-critique.md");
    match build_gameplay_critique_report(
        candidate_dir,
        plan_path,
        plan,
        &critique_path,
        Some(&critique_md),
    ) {
        Ok(report) => {
            if let Err(err) = write_json(critique_path.clone(), &report)
                .and_then(|_| write_gameplay_critique_markdown(critique_md.clone(), &report))
            {
                blockers.push(format!("gameplay critique write failed: {err}"));
            }
            warnings.extend(
                report
                    .blockers
                    .iter()
                    .map(|blocker| format!("candidate gameplay critique blocker: {blocker}")),
            );
            warnings.extend(report.warnings.clone());
            artifacts.insert(
                "candidateGameplayCritique".into(),
                report.critique_path.clone(),
            );
            steps.push(moment_sprint_step(
                "MOMENT-SPRINT-003",
                "Refresh gameplay critique",
                if report.blockers.is_empty() {
                    "executed"
                } else {
                    "warn"
                },
                "Wrote candidate gameplay critique and captured any playability blockers.",
                Some(format!(
                    "rs autopilot critique {} --format json",
                    command_arg(candidate_dir.to_string_lossy().as_ref())
                )),
                vec![
                    report.critique_path,
                    report.markdown_path.unwrap_or_default(),
                ],
                None,
                false,
                false,
            ));
        }
        Err(err) => push_moment_sprint_failed_step(
            steps,
            blockers,
            "MOMENT-SPRINT-003",
            "Refresh gameplay critique",
            "gameplay critique failed",
            err,
        ),
    }

    let proof_path = candidate_dir.join("proof.json");
    let proof_md = candidate_dir.join("proof.md");
    match build_proof_report(candidate_dir, &proof_path, Some(&proof_md)) {
        Ok(report) => {
            if let Err(err) = write_json(proof_path.clone(), &report)
                .and_then(|_| write_proof_markdown(proof_md.clone(), &report))
            {
                blockers.push(format!("proof write failed: {err}"));
            }
            warnings.extend(report.warnings.clone());
            artifacts.insert("candidateProof".into(), report.proof_path.clone());
            steps.push(moment_sprint_step(
                "MOMENT-SPRINT-004",
                "Refresh proof",
                if report.blockers.is_empty() {
                    "executed"
                } else {
                    "warn"
                },
                "Wrote candidate proof ledger while preserving missing live-proof blockers.",
                Some(format!(
                    "rs autopilot proof {} --format json",
                    command_arg(candidate_dir.to_string_lossy().as_ref())
                )),
                vec![report.proof_path, report.markdown_path.unwrap_or_default()],
                None,
                false,
                false,
            ));
        }
        Err(err) => push_moment_sprint_failed_step(
            steps,
            blockers,
            "MOMENT-SPRINT-004",
            "Refresh proof",
            "proof generation failed",
            err,
        ),
    }

    let acceptance_path = candidate_dir.join("acceptance.json");
    let acceptance_md = candidate_dir.join("acceptance.md");
    match build_acceptance_report(
        candidate_dir,
        Some(&plan.request.prompt),
        &acceptance_path,
        Some(&acceptance_md),
    ) {
        Ok(report) => {
            if let Err(err) = write_json(acceptance_path.clone(), &report)
                .and_then(|_| write_acceptance_markdown(acceptance_md.clone(), &report))
            {
                blockers.push(format!("acceptance write failed: {err}"));
            }
            warnings.extend(
                report
                    .blockers
                    .iter()
                    .map(|blocker| format!("candidate acceptance blocker: {blocker}")),
            );
            warnings.extend(report.warnings.clone());
            artifacts.insert("candidateAcceptance".into(), report.acceptance_path.clone());
            steps.push(moment_sprint_step(
                "MOMENT-SPRINT-005",
                "Refresh acceptance",
                if report.blockers.is_empty() {
                    "executed"
                } else {
                    "warn"
                },
                "Wrote candidate acceptance scorecard.",
                Some(format!(
                    "rs autopilot acceptance {} --format json",
                    command_arg(candidate_dir.to_string_lossy().as_ref())
                )),
                vec![
                    report.acceptance_path,
                    report.markdown_path.unwrap_or_default(),
                ],
                None,
                false,
                false,
            ));
        }
        Err(err) => push_moment_sprint_failed_step(
            steps,
            blockers,
            "MOMENT-SPRINT-005",
            "Refresh acceptance",
            "acceptance generation failed",
            err,
        ),
    }

    let audit_path = candidate_dir.join("completion-audit.json");
    let audit_md = candidate_dir.join("completion-audit.md");
    let audit_options = CompletionAuditOptions {
        run_dir: candidate_dir.to_path_buf(),
        prompt: Some(plan.request.prompt.clone()),
        out: Some(audit_path.clone()),
        markdown: Some(audit_md.clone()),
        no_markdown: false,
        json: false,
    };
    match build_completion_audit_report(&audit_options, &audit_path, Some(&audit_md)) {
        Ok(report) => {
            if let Err(err) = write_json(audit_path.clone(), &report)
                .and_then(|_| write_completion_audit_markdown(audit_md.clone(), &report))
            {
                blockers.push(format!("completion audit write failed: {err}"));
            }
            warnings.extend(
                report
                    .blockers
                    .iter()
                    .map(|blocker| format!("candidate completion audit blocker: {blocker}")),
            );
            warnings.extend(report.warnings.clone());
            artifacts.insert("candidateCompletionAudit".into(), report.audit_path.clone());
            steps.push(moment_sprint_step(
                "MOMENT-SPRINT-006",
                "Refresh completion audit",
                if report.blockers.is_empty() {
                    "executed"
                } else {
                    "warn"
                },
                "Wrote candidate completion audit and remaining proof gaps.",
                Some(format!(
                    "rs autopilot completion-audit {} --format json",
                    command_arg(candidate_dir.to_string_lossy().as_ref())
                )),
                vec![report.audit_path, report.markdown_path.unwrap_or_default()],
                None,
                false,
                false,
            ));
        }
        Err(err) => push_moment_sprint_failed_step(
            steps,
            blockers,
            "MOMENT-SPRINT-006",
            "Refresh completion audit",
            "completion audit failed",
            err,
        ),
    }

    let claim_path = candidate_dir.join("claim-check.json");
    let claim_md = candidate_dir.join("claim-check.md");
    let claim = format!("{} has a reviewable offline candidate", idea.title);
    let claim_options = ClaimCheckOptions {
        run_dir: candidate_dir.to_path_buf(),
        claims: vec![claim.clone()],
        out: Some(claim_path.clone()),
        markdown: Some(claim_md.clone()),
        no_markdown: false,
        json: false,
    };
    match build_claim_check_report(&claim_options, &claim_path, Some(&claim_md)) {
        Ok(report) => {
            if let Err(err) = write_json(claim_path.clone(), &report)
                .and_then(|_| write_claim_check_markdown(claim_md.clone(), &report))
            {
                blockers.push(format!("claim-check write failed: {err}"));
            }
            warnings.extend(
                report
                    .blockers
                    .iter()
                    .map(|blocker| format!("candidate claim-check blocker: {blocker}")),
            );
            warnings.extend(report.warnings.clone());
            artifacts.insert(
                "candidateClaimCheck".into(),
                report.claim_check_path.clone(),
            );
            steps.push(moment_sprint_step(
                "MOMENT-SPRINT-007",
                "Check candidate claim",
                if report.blockers.is_empty() {
                    "executed"
                } else {
                    "warn"
                },
                format!("Checked claim: {claim}"),
                Some(format!(
                    "rs autopilot claim-check {} --claim {} --format json",
                    command_arg(candidate_dir.to_string_lossy().as_ref()),
                    command_arg(&claim)
                )),
                vec![
                    report.claim_check_path,
                    report.markdown_path.unwrap_or_default(),
                ],
                None,
                false,
                false,
            ));
        }
        Err(err) => push_moment_sprint_failed_step(
            steps,
            blockers,
            "MOMENT-SPRINT-007",
            "Check candidate claim",
            "claim-check failed",
            err,
        ),
    }
}

fn push_moment_sprint_failed_step(
    steps: &mut Vec<MomentSprintStep>,
    blockers: &mut Vec<String>,
    id: &str,
    title: &str,
    summary: &str,
    err: impl std::fmt::Display,
) {
    let message = err.to_string();
    blockers.push(format!("{summary}: {message}"));
    steps.push(moment_sprint_step(
        id,
        title,
        "failed",
        summary,
        None,
        Vec::new(),
        Some(message),
        false,
        false,
    ));
}

fn moment_sprint_step(
    id: &str,
    title: &str,
    status: &str,
    summary: impl Into<String>,
    command: Option<String>,
    artifacts: Vec<String>,
    error: Option<String>,
    requires_live_studio: bool,
    mutates_studio: bool,
) -> MomentSprintStep {
    MomentSprintStep {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        summary: summary.into(),
        command,
        artifacts: artifacts
            .into_iter()
            .filter(|artifact| !artifact.trim().is_empty())
            .collect(),
        error,
        requires_live_studio,
        mutates_studio,
    }
}

fn build_moment_sprint_next_actions(
    run_dir: &Path,
    candidate_run_dir: Option<&Path>,
    idea: Option<&WowIdea>,
    status: &str,
) -> Vec<CoachAction> {
    let source = command_arg(run_dir.to_string_lossy().as_ref());
    let mut actions = Vec::new();
    if status == "dryRun" {
        actions.push(coach_action(
            1,
            "Run moment sprint",
            Some(format!("rs autopilot moment-sprint {source} --format json")),
            "Execute the safe offline candidate build and review steps.",
            false,
            false,
        ));
    }
    if let Some(candidate) = candidate_run_dir {
        let candidate_arg = command_arg(candidate.to_string_lossy().as_ref());
        actions.push(coach_action(
            2,
            "Inspect candidate completion",
            Some(format!(
                "rs autopilot completion-audit {candidate_arg} --format json"
            )),
            "Review remaining proof gaps before telling the creator the moment is ready.",
            false,
            false,
        ));
        actions.push(coach_action(
            3,
            "Prepare candidate delivery",
            Some(format!(
                "rs autopilot deliver {candidate_arg} --format json"
            )),
            "Create an evidence-based candidate summary after completion checks.",
            false,
            false,
        ));
    }
    if let Some(idea) = idea {
        actions.push(coach_action(
            4,
            "Refresh moment pack",
            Some(format!(
                "rs autopilot moment-pack {source} --idea {} --format json",
                command_arg(&idea.title)
            )),
            "Regenerate implementation lanes after candidate artifacts change.",
            false,
            false,
        ));
    }
    actions
}

fn build_moment_sprint_agent_brief(
    status: &str,
    idea: Option<&WowIdea>,
    candidate_run_dir: Option<&Path>,
    executed_steps: usize,
    failed_steps: usize,
) -> String {
    let idea_title = idea
        .map(|idea| idea.title.as_str())
        .unwrap_or("<no selected idea>");
    let candidate = candidate_run_dir
        .map(|path| path.to_string_lossy().to_string())
        .unwrap_or_else(|| "<no candidate run>".into());
    format!(
        "Moment sprint is {status}: `{idea_title}` candidate `{candidate}`, {executed_steps} executed/warn step(s), {failed_steps} failed step(s). Offline candidate artifacts are not live Studio proof."
    )
}

fn build_moment_decision_report(
    options: &MomentDecisionOptions,
    decision_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<MomentDecisionReport> {
    let child_markdown = markdown_path.is_some();
    let sprint_path = options.run_dir.join("moment-sprint.json");
    let sprint_markdown_path = child_markdown.then(|| options.run_dir.join("moment-sprint.md"));
    let sprint_options = MomentSprintOptions {
        prompt: options.prompt.clone(),
        idea: options.idea.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        max_ideas: options.max_ideas,
        max_chars: options.max_chars,
        dry_run: options.dry_run,
        out: Some(sprint_path.clone()),
        markdown: sprint_markdown_path.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let moment_sprint = build_moment_sprint_report(
        &sprint_options,
        &sprint_path,
        sprint_markdown_path.as_deref(),
    )?;
    write_json(sprint_path.clone(), &moment_sprint)?;
    if let Some(path) = sprint_markdown_path {
        write_moment_sprint_markdown(path, &moment_sprint)?;
    }

    let mut artifacts = moment_sprint.artifacts.clone();
    artifacts.insert(
        "momentDecision".into(),
        decision_path.to_string_lossy().to_string(),
    );
    if let Some(path) = markdown_path {
        artifacts.insert(
            "momentDecisionMarkdown".into(),
            path.to_string_lossy().to_string(),
        );
    }

    let mut blockers = moment_sprint.blockers.clone();
    let mut warnings = moment_sprint.warnings.clone();
    let mut evidence = vec![moment_decision_evidence(
        "moment-sprint",
        "Moment Sprint",
        &moment_sprint.status,
        &moment_sprint.verdict,
        Some(moment_sprint.moment_sprint_path.clone()),
    )];
    let mut comparison = None;
    let mut comparison_path = None;
    let mut review_pack_path = None;
    let mut claim_check_path = None;
    let mut recommended_run_dir = None;
    let mut decision = "reviewMomentSprintFirst".to_string();

    if options.dry_run {
        decision = "plannedOnly".into();
    } else if moment_sprint.status != "candidateReviewReady" {
        blockers.push(
            "moment-decision requires moment-sprint status candidateReviewReady before comparison"
                .into(),
        );
    } else if let Some(candidate) = moment_sprint.candidate_run_dir.as_deref() {
        let candidate_run = PathBuf::from(candidate);
        let compare_path = candidate_run.join("comparison.json");
        let compare_markdown = child_markdown.then(|| candidate_run.join("comparison.md"));
        match build_compare_report(
            &options.run_dir,
            &candidate_run,
            &compare_path,
            compare_markdown.as_deref(),
        ) {
            Ok(report) => {
                write_json(compare_path.clone(), &report)?;
                if let Some(path) = compare_markdown {
                    write_compare_markdown(path, &report)?;
                }
                comparison_path = Some(report.comparison_path.clone());
                artifacts.insert("momentComparison".into(), report.comparison_path.clone());
                warnings.extend(
                    report
                        .blockers
                        .iter()
                        .map(|blocker| format!("comparison blocker: {blocker}")),
                );
                warnings.extend(report.warnings.clone());
                evidence.push(moment_decision_evidence(
                    "comparison",
                    "Source vs Wow Candidate",
                    &report.status,
                    &report.verdict,
                    Some(report.comparison_path.clone()),
                ));
                if report.status == "candidatePreferred" {
                    recommended_run_dir = Some(candidate_run.to_string_lossy().to_string());
                    decision = "carryForwardWowCandidate".into();
                } else if report.status == "basePreferred" {
                    recommended_run_dir = Some(options.run_dir.to_string_lossy().to_string());
                    decision = "keepSourceRun".into();
                } else {
                    decision = "manualReviewNeeded".into();
                }
                comparison = Some(report);
            }
            Err(err) => blockers.push(format!("moment-decision comparison failed: {err}")),
        }
    } else {
        blockers.push("moment-decision could not find a candidate run from moment-sprint".into());
    }

    if let Some(recommended) = recommended_run_dir.as_deref() {
        let recommended_path = PathBuf::from(recommended);
        let review_path = recommended_path.join("review-pack.json");
        let review_markdown = child_markdown.then(|| recommended_path.join("review-pack.md"));
        let review_options = ReviewPackOptions {
            run_dir: recommended_path.clone(),
            out: Some(review_path.clone()),
            markdown: review_markdown.clone(),
            no_markdown: !child_markdown,
            create_evidence_dirs: false,
            json: false,
        };
        match build_review_pack_report(&review_options, &review_path, review_markdown.as_deref()) {
            Ok(report) => {
                write_json(review_path.clone(), &report)?;
                if let Some(path) = review_markdown {
                    write_review_pack_markdown(path, &report)?;
                }
                review_pack_path = Some(report.review_path.clone());
                artifacts.insert("recommendedReviewPack".into(), report.review_path.clone());
                warnings.extend(
                    report
                        .blockers
                        .iter()
                        .map(|blocker| format!("recommended review blocker: {blocker}")),
                );
                warnings.extend(report.warnings.clone());
                evidence.push(moment_decision_evidence(
                    "review-pack",
                    "Recommended Run Review Pack",
                    &report.status,
                    &report.verdict,
                    Some(report.review_path.clone()),
                ));
            }
            Err(err) => blockers.push(format!("recommended review-pack failed: {err}")),
        }

        let claim_path = recommended_path.join("claim-check.json");
        let claim_markdown = child_markdown.then(|| recommended_path.join("claim-check.md"));
        let claim = moment_decision_claim(&decision, moment_sprint.selected_idea.as_ref());
        let claim_options = ClaimCheckOptions {
            run_dir: recommended_path,
            claims: vec![claim],
            out: Some(claim_path.clone()),
            markdown: claim_markdown.clone(),
            no_markdown: !child_markdown,
            json: false,
        };
        match build_claim_check_report(&claim_options, &claim_path, claim_markdown.as_deref()) {
            Ok(report) => {
                write_json(claim_path.clone(), &report)?;
                if let Some(path) = claim_markdown {
                    write_claim_check_markdown(path, &report)?;
                }
                claim_check_path = Some(report.claim_check_path.clone());
                artifacts.insert(
                    "recommendedClaimCheck".into(),
                    report.claim_check_path.clone(),
                );
                warnings.extend(
                    report
                        .blockers
                        .iter()
                        .map(|blocker| format!("recommended claim-check blocker: {blocker}")),
                );
                warnings.extend(report.warnings.clone());
                evidence.push(moment_decision_evidence(
                    "claim-check",
                    "Recommended Run Claim Check",
                    &report.status,
                    &report.verdict,
                    Some(report.claim_check_path.clone()),
                ));
            }
            Err(err) => blockers.push(format!("recommended claim-check failed: {err}")),
        }
    }

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let status = if options.dry_run {
        "dryRun"
    } else if !blockers.is_empty() {
        "blocked"
    } else if decision == "carryForwardWowCandidate" {
        "candidatePreferred"
    } else if decision == "keepSourceRun" {
        "sourcePreferred"
    } else {
        "reviewNeeded"
    }
    .to_string();
    let verdict = match status.as_str() {
        "dryRun" => "safeDecisionPlanned",
        "candidatePreferred" => "wowCandidateIsBestContinuation",
        "sourcePreferred" => "sourceRunRemainsBestContinuation",
        "reviewNeeded" => "humanTasteReviewNeeded",
        _ => "decisionBlocked",
    }
    .to_string();

    let mut safe_to_say = moment_sprint.safe_to_say.clone();
    match status.as_str() {
        "candidatePreferred" => {
            if let Some(idea) = &moment_sprint.selected_idea {
                safe_to_say.push(format!(
                    "`{}` is the recommended offline wow candidate to carry forward.",
                    idea.title
                ));
            } else {
                safe_to_say.push(
                    "The reviewed offline wow candidate is the recommended continuation.".into(),
                );
            }
        }
        "sourcePreferred" => safe_to_say
            .push("The source run remains the safer reviewed continuation for now.".into()),
        "dryRun" => {
            safe_to_say.push("Moment decision dry-run planned comparison and review steps.".into())
        }
        _ => {}
    }
    safe_to_say.sort();
    safe_to_say.dedup();

    let mut do_not_say = moment_sprint.do_not_say.clone();
    do_not_say.extend([
        "Do not claim moment-decision applied the selected run to Studio.".into(),
        "Do not claim the recommended run passed live playtest, rollback, publish, or production gates unless those artifacts exist.".into(),
        "Do not treat a candidate preference as creator approval to mutate Studio.".into(),
    ]);
    do_not_say.sort();
    do_not_say.dedup();

    let mut next_actions = build_moment_decision_next_actions(
        &options.run_dir,
        recommended_run_dir.as_deref(),
        moment_sprint.candidate_run_dir.as_deref(),
        &status,
    );
    dedup_next_actions(&mut next_actions);
    let agent_brief = build_moment_decision_agent_brief(
        &status,
        &decision,
        moment_sprint.selected_idea.as_ref(),
        recommended_run_dir.as_deref(),
        comparison.as_ref(),
    );

    Ok(MomentDecisionReport {
        schema_version: "rs.autopilot.moment-decision.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        moment_decision_path: decision_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        prompt: moment_sprint.prompt.clone(),
        status,
        verdict,
        dry_run: options.dry_run,
        decision,
        selected_idea: moment_sprint.selected_idea.clone(),
        source_run_dir: options.run_dir.to_string_lossy().to_string(),
        candidate_run_dir: moment_sprint.candidate_run_dir.clone(),
        recommended_run_dir,
        comparison_path,
        review_pack_path,
        claim_check_path,
        evidence,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        moment_sprint,
        comparison,
    })
}

fn moment_decision_evidence(
    id: &str,
    title: &str,
    status: &str,
    summary: &str,
    path: Option<String>,
) -> MomentDecisionEvidence {
    MomentDecisionEvidence {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        summary: summary.into(),
        path,
    }
}

fn moment_decision_claim(decision: &str, idea: Option<&WowIdea>) -> String {
    let idea_title = idea
        .map(|idea| idea.title.as_str())
        .unwrap_or("the selected wow moment");
    match decision {
        "carryForwardWowCandidate" => {
            format!("{idea_title} is the recommended offline wow candidate to review next")
        }
        "keepSourceRun" => {
            "The source run remains the safer offline continuation after wow comparison".into()
        }
        _ => "The wow candidate decision needs human review before creator-facing claims".into(),
    }
}

fn build_moment_decision_next_actions(
    source_run: &Path,
    recommended_run: Option<&str>,
    candidate_run: Option<&str>,
    status: &str,
) -> Vec<CoachAction> {
    let source_arg = command_arg(source_run.to_string_lossy().as_ref());
    let mut actions = Vec::new();
    if status == "dryRun" {
        actions.push(coach_action(
            1,
            "Run moment decision",
            Some(format!(
                "rs autopilot moment-decision {source_arg} --format json"
            )),
            "Execute the offline sprint, comparison, review-pack, and claim-check sequence.",
            false,
            false,
        ));
        return actions;
    }
    if let Some(recommended) = recommended_run {
        let recommended_arg = command_arg(recommended);
        actions.push(coach_action(
            1,
            "Review recommended run",
            Some(format!(
                "rs autopilot review-pack {recommended_arg} --format json"
            )),
            "Open the evidence packet for the run that should be carried forward.",
            false,
            false,
        ));
        actions.push(coach_action(
            2,
            "Verify recommended bundle",
            Some(format!(
                "rs autopilot verify-bundle --run-dir {recommended_arg} --format json"
            )),
            "Confirm the recommended run's artifact hashes still match before handoff or apply.",
            false,
            false,
        ));
        actions.push(coach_action(
            3,
            "Prepare creator-facing delivery",
            Some(format!(
                "rs autopilot deliver {recommended_arg} --format json"
            )),
            "Compose a proof-bound creator update after the decision packet is reviewed.",
            false,
            false,
        ));
        actions.push(coach_action(
            4,
            "Check live readiness",
            Some("rs autopilot ready --timeout 90 --format json".into()),
            "Studio mutation is still blocked until live readiness passes.",
            true,
            false,
        ));
    } else if let Some(candidate) = candidate_run {
        let candidate_arg = command_arg(candidate);
        actions.push(coach_action(
            1,
            "Manually compare candidate",
            Some(format!(
                "rs autopilot compare --base-run {source_arg} --candidate-run {candidate_arg} --format json"
            )),
            "Refresh comparison evidence before choosing a continuation.",
            false,
            false,
        ));
    } else {
        actions.push(coach_action(
            1,
            "Build wow candidate",
            Some(format!(
                "rs autopilot moment-sprint {source_arg} --format json"
            )),
            "Create the reviewed offline candidate before a decision can be made.",
            false,
            false,
        ));
    }
    actions.push(coach_action(
        9,
        "Refresh moment decision",
        Some(format!(
            "rs autopilot moment-decision {source_arg} --format json"
        )),
        "Regenerate this decision after candidate, proof, review, or creator feedback changes.",
        false,
        false,
    ));
    actions
}

fn build_moment_decision_agent_brief(
    status: &str,
    decision: &str,
    idea: Option<&WowIdea>,
    recommended_run: Option<&str>,
    comparison: Option<&CompareReport>,
) -> String {
    let idea_title = idea
        .map(|idea| idea.title.as_str())
        .unwrap_or("<no selected idea>");
    let recommended = recommended_run.unwrap_or("<no recommended run>");
    if let Some(comparison) = comparison {
        format!(
            "Moment decision is {status}: `{idea_title}` produced decision `{decision}` with comparison verdict `{}` and score delta {}. Recommended run: {recommended}. This is still offline evidence, not Studio apply proof.",
            comparison.verdict, comparison.score_delta
        )
    } else {
        format!(
            "Moment decision is {status}: `{idea_title}` produced decision `{decision}`. Recommended run: {recommended}. This is still offline evidence, not Studio apply proof."
        )
    }
}

fn build_creator_demo_report(
    options: &CreatorDemoOptions,
    demo_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<CreatorDemoReport> {
    let child_markdown = markdown_path.is_some();
    let decision_path = options.run_dir.join("moment-decision.json");
    let decision_markdown_path = child_markdown.then(|| options.run_dir.join("moment-decision.md"));
    let decision_options = MomentDecisionOptions {
        prompt: options.prompt.clone(),
        idea: options.idea.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        max_ideas: options.max_ideas,
        max_chars: options.max_chars,
        dry_run: options.dry_run,
        out: Some(decision_path.clone()),
        markdown: decision_markdown_path.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let moment_decision = build_moment_decision_report(
        &decision_options,
        &decision_path,
        decision_markdown_path.as_deref(),
    )?;
    write_json(decision_path.clone(), &moment_decision)?;
    if let Some(path) = decision_markdown_path {
        write_moment_decision_markdown(path, &moment_decision)?;
    }

    let mut artifacts = moment_decision.artifacts.clone();
    artifacts.insert(
        "creatorDemo".into(),
        demo_path.to_string_lossy().to_string(),
    );
    if let Some(path) = markdown_path {
        artifacts.insert(
            "creatorDemoMarkdown".into(),
            path.to_string_lossy().to_string(),
        );
    }

    let mut blockers = moment_decision.blockers.clone();
    let mut warnings = moment_decision.warnings.clone();
    let mut showcase = None;
    let mut review_pack = None;
    let mut delivery = None;
    let mut rehearsal = None;

    if options.dry_run {
        warnings.push("creator-demo dry-run did not refresh the recommended run artifacts".into());
    } else if let Some(recommended) = moment_decision.recommended_run_dir.as_deref() {
        let recommended_run = PathBuf::from(recommended);
        let plan_path = recommended_run.join("plan.json");
        let plan = match read_plan(&plan_path) {
            Ok(plan) => Some(plan),
            Err(err) => {
                blockers.push(format!("recommended run plan could not be read: {err}"));
                None
            }
        };
        if let Some(plan) = plan.as_ref() {
            let showcase_path = recommended_run.join("showcase.json");
            let showcase_markdown = child_markdown.then(|| recommended_run.join("showcase.md"));
            match build_showcase_report(
                &recommended_run,
                &plan_path,
                plan,
                &showcase_path,
                showcase_markdown.as_deref(),
            ) {
                Ok(report) => {
                    write_json(showcase_path.clone(), &report)?;
                    if let Some(path) = showcase_markdown {
                        write_showcase_markdown(path, &report)?;
                    }
                    artifacts.insert("demoShowcase".into(), report.showcase_path.clone());
                    warnings.extend(report.warnings.clone());
                    blockers.extend(report.blockers.clone());
                    showcase = Some(report);
                }
                Err(err) => blockers.push(format!("creator-demo showcase failed: {err}")),
            }
        }

        let review_path = recommended_run.join("review-pack.json");
        let review_markdown = child_markdown.then(|| recommended_run.join("review-pack.md"));
        let review_options = ReviewPackOptions {
            run_dir: recommended_run.clone(),
            out: Some(review_path.clone()),
            markdown: review_markdown.clone(),
            no_markdown: !child_markdown,
            create_evidence_dirs: false,
            json: false,
        };
        match build_review_pack_report(&review_options, &review_path, review_markdown.as_deref()) {
            Ok(report) => {
                write_json(review_path.clone(), &report)?;
                if let Some(path) = review_markdown {
                    write_review_pack_markdown(path, &report)?;
                }
                artifacts.insert("demoReviewPack".into(), report.review_path.clone());
                warnings.extend(
                    report
                        .blockers
                        .iter()
                        .map(|blocker| format!("demo review blocker: {blocker}")),
                );
                warnings.extend(report.warnings.clone());
                review_pack = Some(report);
            }
            Err(err) => blockers.push(format!("creator-demo review-pack failed: {err}")),
        }

        let delivery_path = recommended_run.join("delivery.json");
        let delivery_markdown = child_markdown.then(|| recommended_run.join("delivery.md"));
        let delivery_options = DeliverOptions {
            run_dir: recommended_run.clone(),
            prompt: Some(moment_decision.prompt.clone()),
            out: Some(delivery_path.clone()),
            markdown: delivery_markdown.clone(),
            no_markdown: !child_markdown,
            json: false,
        };
        match build_delivery_report(
            &delivery_options,
            &delivery_path,
            delivery_markdown.as_deref(),
        ) {
            Ok(report) => {
                write_json(delivery_path.clone(), &report)?;
                if let Some(path) = delivery_markdown {
                    write_delivery_markdown(path, &report)?;
                }
                artifacts.insert("demoDelivery".into(), report.delivery_path.clone());
                warnings.extend(report.warnings.clone());
                delivery = Some(report);
            }
            Err(err) => blockers.push(format!("creator-demo delivery failed: {err}")),
        }

        let rehearsal_path = recommended_run.join("rehearsal.json");
        let rehearsal_markdown = child_markdown.then(|| recommended_run.join("rehearsal.md"));
        let rehearsal_options = RehearsalOptions {
            run_dir: recommended_run.clone(),
            out: Some(rehearsal_path.clone()),
            markdown: rehearsal_markdown.clone(),
            no_markdown: !child_markdown,
            json: false,
        };
        match build_rehearsal_report(
            &rehearsal_options,
            &rehearsal_path,
            rehearsal_markdown.as_deref(),
        ) {
            Ok(report) => {
                write_json(rehearsal_path.clone(), &report)?;
                if let Some(path) = rehearsal_markdown {
                    write_rehearsal_markdown(path, &report)?;
                }
                artifacts.insert("demoRehearsal".into(), report.rehearsal_path.clone());
                warnings.extend(
                    report
                        .blockers
                        .iter()
                        .map(|blocker| format!("demo rehearsal blocker: {blocker}")),
                );
                warnings.extend(report.warnings.clone());
                rehearsal = Some(report);
            }
            Err(err) => blockers.push(format!("creator-demo rehearsal failed: {err}")),
        }
        refresh_run_bundle_if_possible(&recommended_run)?;
    } else {
        blockers.push("creator-demo requires a recommended run from moment-decision".into());
    }

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let status = if options.dry_run {
        "dryRun"
    } else if !blockers.is_empty() {
        "blocked"
    } else {
        "demoPacketReady"
    }
    .to_string();
    let verdict = match status.as_str() {
        "dryRun" => "creatorDemoPlanned",
        "demoPacketReady" => "creatorDemoReady",
        _ => "creatorDemoBlocked",
    }
    .to_string();
    let demo_title = creator_demo_title(moment_decision.selected_idea.as_ref(), showcase.as_ref());
    let creator_message = delivery.as_ref().map(|report| report.message.clone());
    let talk_track = build_creator_demo_talk_track(
        &moment_decision,
        showcase.as_ref(),
        delivery.as_ref(),
        rehearsal.as_ref(),
    );
    let proof_table = build_creator_demo_proof_table(
        &moment_decision,
        showcase.as_ref(),
        review_pack.as_ref(),
        delivery.as_ref(),
        rehearsal.as_ref(),
    );
    let approval_boundary = build_creator_demo_approval_boundary(
        moment_decision.recommended_run_dir.as_deref(),
        rehearsal.as_ref(),
    );

    let mut safe_to_say = moment_decision.safe_to_say.clone();
    if let Some(report) = &delivery {
        safe_to_say.extend(report.safe_to_say.clone());
    }
    if let Some(report) = &rehearsal {
        safe_to_say.extend(report.safe_to_say.clone());
    }
    if status == "demoPacketReady" {
        safe_to_say.push(
            "Creator demo packet is ready for review with evidence, talk track, and approval boundaries."
                .into(),
        );
    }
    safe_to_say.sort();
    safe_to_say.dedup();

    let mut do_not_say = moment_decision.do_not_say.clone();
    if let Some(report) = &delivery {
        do_not_say.extend(report.do_not_say.clone());
    }
    if let Some(report) = &rehearsal {
        do_not_say.extend(report.do_not_say.clone());
    }
    do_not_say.extend([
        "Do not say creator-demo applied, playtested, published, or approved the run.".into(),
        "Do not skip the live readiness, approval, apply, rollback, and playtest proof gates."
            .into(),
    ]);
    do_not_say.sort();
    do_not_say.dedup();

    let mut next_actions = build_creator_demo_next_actions(
        &options.run_dir,
        moment_decision.recommended_run_dir.as_deref(),
        &status,
    );
    dedup_next_actions(&mut next_actions);
    let agent_brief = build_creator_demo_agent_brief(
        &status,
        &demo_title,
        moment_decision.recommended_run_dir.as_deref(),
        talk_track.len(),
        proof_table.len(),
    );

    Ok(CreatorDemoReport {
        schema_version: "rs.autopilot.creator-demo.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        creator_demo_path: demo_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        prompt: moment_decision.prompt.clone(),
        status,
        verdict,
        dry_run: options.dry_run,
        selected_idea: moment_decision.selected_idea.clone(),
        recommended_run_dir: moment_decision.recommended_run_dir.clone(),
        demo_title,
        creator_message,
        talk_track,
        proof_table,
        approval_boundary,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        moment_decision,
        showcase,
        review_pack,
        delivery,
        rehearsal,
    })
}

fn creator_demo_title(idea: Option<&WowIdea>, showcase: Option<&ShowcaseReport>) -> String {
    if let Some(idea) = idea {
        format!("Creator Demo: {}", idea.title)
    } else if let Some(showcase) = showcase {
        format!("Creator Demo: {}", showcase.hero_pitch)
    } else {
        "Creator Demo Packet".into()
    }
}

fn build_creator_demo_talk_track(
    decision: &MomentDecisionReport,
    showcase: Option<&ShowcaseReport>,
    delivery: Option<&DeliveryReport>,
    rehearsal: Option<&RehearsalReport>,
) -> Vec<CreatorDemoBeat> {
    let mut beats = Vec::new();
    if let Some(showcase) = showcase {
        beats.push(creator_demo_beat(
            "hook",
            "Open With The Hook",
            &showcase.hero_pitch,
            "showcase",
            vec![showcase.showcase_path.clone()],
            false,
            false,
        ));
        for (index, point) in showcase.creator_talking_points.iter().take(3).enumerate() {
            beats.push(creator_demo_beat(
                &format!("talking-point-{}", index + 1),
                "Creator Talking Point",
                point,
                "showcase",
                vec![showcase.showcase_path.clone()],
                false,
                false,
            ));
        }
    }
    if let Some(idea) = &decision.selected_idea {
        beats.push(creator_demo_beat(
            "wow-moment",
            "Name The Wow Moment",
            &format!(
                "The standout player moment is `{}`: {}",
                idea.title, idea.player_moment
            ),
            "moment-decision",
            vec![decision.moment_decision_path.clone()],
            false,
            false,
        ));
    }
    if let Some(delivery) = delivery {
        beats.push(creator_demo_beat(
            "creator-message",
            "Use The Checked Creator Message",
            &delivery.message,
            "delivery",
            vec![delivery.delivery_path.clone()],
            false,
            false,
        ));
    }
    if let Some(rehearsal) = rehearsal {
        for (index, line) in rehearsal.creator_script.iter().take(4).enumerate() {
            beats.push(creator_demo_beat(
                &format!("rehearsal-{}", index + 1),
                "Live Demo Script",
                line,
                "rehearsal",
                vec![rehearsal.rehearsal_path.clone()],
                false,
                false,
            ));
        }
    }
    beats
}

fn creator_demo_beat(
    id: &str,
    title: &str,
    script: &str,
    source: &str,
    evidence: Vec<String>,
    requires_live_studio: bool,
    mutates_studio: bool,
) -> CreatorDemoBeat {
    CreatorDemoBeat {
        id: id.into(),
        title: title.into(),
        script: script.into(),
        source: source.into(),
        evidence,
        requires_live_studio,
        mutates_studio,
    }
}

fn build_creator_demo_proof_table(
    decision: &MomentDecisionReport,
    showcase: Option<&ShowcaseReport>,
    review_pack: Option<&ReviewPackReport>,
    delivery: Option<&DeliveryReport>,
    rehearsal: Option<&RehearsalReport>,
) -> Vec<CreatorDemoProof> {
    let mut proofs = vec![CreatorDemoProof {
        id: "moment-decision".into(),
        claim: "The recommended wow continuation was selected from offline comparison.".into(),
        status: decision.status.clone(),
        evidence: vec![decision.moment_decision_path.clone()],
        missing: Vec::new(),
        next_command: None,
    }];
    if let Some(showcase) = showcase {
        for check in showcase.proof_checks.iter().take(5) {
            proofs.push(CreatorDemoProof {
                id: check.id.clone(),
                claim: check.claim.clone(),
                status: "planned".into(),
                evidence: vec![check.evidence.clone(), showcase.showcase_path.clone()],
                missing: vec!["captured live screenshot or playtest evidence".into()],
                next_command: Some(check.suggested_command.clone()),
            });
        }
    }
    if let Some(review) = review_pack {
        proofs.push(CreatorDemoProof {
            id: "review-pack".into(),
            claim: "The recommended run has a creator review packet.".into(),
            status: review.status.clone(),
            evidence: vec![review.review_path.clone()],
            missing: review.blockers.clone(),
            next_command: review
                .next_actions
                .first()
                .and_then(|action| action.command.clone()),
        });
    }
    if let Some(delivery) = delivery {
        proofs.push(CreatorDemoProof {
            id: "delivery".into(),
            claim: "The creator-facing message is evidence-bound.".into(),
            status: delivery.status.clone(),
            evidence: vec![delivery.delivery_path.clone()],
            missing: delivery.blockers.clone(),
            next_command: delivery
                .next_actions
                .first()
                .and_then(|action| action.command.clone()),
        });
    }
    if let Some(rehearsal) = rehearsal {
        proofs.push(CreatorDemoProof {
            id: "rehearsal".into(),
            claim: "The live demo path has ordered gates and stop conditions.".into(),
            status: rehearsal.status.clone(),
            evidence: vec![rehearsal.rehearsal_path.clone()],
            missing: rehearsal.blockers.clone(),
            next_command: rehearsal
                .next_actions
                .first()
                .and_then(|action| action.command.clone()),
        });
    }
    proofs
}

fn build_creator_demo_approval_boundary(
    recommended_run: Option<&str>,
    rehearsal: Option<&RehearsalReport>,
) -> Vec<String> {
    let mut boundary = vec![
        "Show the creator the demo packet and review evidence before asking to mutate Studio."
            .into(),
        "Creator approval must be recorded separately; this packet is not approval.".into(),
        "Run `ready` and `live-gate --approved` before any apply command.".into(),
        "Apply remains mutating and must preserve rollback evidence.".into(),
        "After apply, collect live playtest evidence before final or production claims.".into(),
    ];
    if let Some(run) = recommended_run {
        boundary.push(format!("Recommended run for review: `{run}`"));
    }
    if let Some(rehearsal) = rehearsal {
        boundary.extend(rehearsal.stop_conditions.iter().cloned());
    }
    boundary.sort();
    boundary.dedup();
    boundary
}

fn build_creator_demo_next_actions(
    source_run: &Path,
    recommended_run: Option<&str>,
    status: &str,
) -> Vec<CoachAction> {
    let source_arg = command_arg(source_run.to_string_lossy().as_ref());
    let mut actions = Vec::new();
    if status == "dryRun" {
        actions.push(coach_action(
            1,
            "Run creator demo packet",
            Some(format!(
                "rs autopilot creator-demo {source_arg} --format json"
            )),
            "Refresh the recommended run and write the full proof-bound demo packet.",
            false,
            false,
        ));
        return actions;
    }
    if let Some(run) = recommended_run {
        let run_arg = command_arg(run);
        actions.push(coach_action(
            1,
            "Open recommended review packet",
            Some(format!("rs autopilot review-pack {run_arg} --format json")),
            "Review the selected run's evidence before presenting it to the creator.",
            false,
            false,
        ));
        actions.push(coach_action(
            2,
            "Publish Studio review panel",
            Some(format!(
                "rs autopilot publish-review {run_arg} --format json"
            )),
            "Show the same offline packet in Studio before any live preview or apply.",
            true,
            false,
        ));
        actions.push(coach_action(
            3,
            "Lead the live demo rehearsal",
            Some(format!("rs autopilot rehearsal {run_arg} --format json")),
            "Use the non-mutating runbook to ask for approval, check readiness, and stop at gates.",
            false,
            false,
        ));
        actions.push(coach_action(
            4,
            "Check live readiness",
            Some("rs autopilot ready --timeout 90 --format json".into()),
            "Live apply requires a connected Studio bridge and compatible plugin.",
            true,
            false,
        ));
    }
    actions.push(coach_action(
        9,
        "Refresh creator demo",
        Some(format!(
            "rs autopilot creator-demo {source_arg} --format json"
        )),
        "Regenerate after candidate, proof, review, or creator feedback changes.",
        false,
        false,
    ));
    actions
}

fn build_creator_demo_agent_brief(
    status: &str,
    title: &str,
    recommended_run: Option<&str>,
    beat_count: usize,
    proof_count: usize,
) -> String {
    let run = recommended_run.unwrap_or("<no recommended run>");
    format!(
        "Creator demo is {status}: `{title}` has {beat_count} talk-track beat(s), {proof_count} proof row(s), and recommended run `{run}`. It prepares presentation and approval gates, not Studio mutation or live proof."
    )
}

fn build_demo_response_report(
    options: &DemoResponseOptions,
    response_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<DemoResponseReport> {
    let child_markdown = markdown_path.is_some();
    let demo_path = options.run_dir.join("creator-demo.json");
    let demo_markdown = child_markdown.then(|| options.run_dir.join("creator-demo.md"));
    let prompt = read_plan(&options.run_dir.join("plan.json"))
        .ok()
        .map(|plan| plan.request.prompt);
    let demo_options = CreatorDemoOptions {
        prompt,
        idea: options.idea.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        max_ideas: options.max_ideas,
        max_chars: options.max_chars,
        dry_run: options.dry_run,
        out: Some(demo_path.clone()),
        markdown: demo_markdown.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let creator_demo =
        build_creator_demo_report(&demo_options, &demo_path, demo_markdown.as_deref())?;
    write_json(demo_path.clone(), &creator_demo)?;
    if let Some(path) = demo_markdown {
        write_creator_demo_markdown(path, &creator_demo)?;
    }

    let messages = normalize_demo_response_messages(&options.messages);
    let (route, route_reason) = classify_demo_response_route(&messages);
    let mut generated_artifacts = creator_demo.artifacts.clone();
    generated_artifacts.insert(
        "demoResponse".into(),
        response_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        generated_artifacts.insert(
            "demoResponseMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    let mut safe_to_say = creator_demo.safe_to_say.clone();
    let mut do_not_say = creator_demo.do_not_say.clone();
    let mut blockers = creator_demo.blockers.clone();
    let mut warnings = creator_demo.warnings.clone();
    let mut feedback = None;
    let mut feedback_patch = None;
    let mut decision = None;
    let mut approval = None;
    let mut claim_check = None;

    match route {
        "needsCreatorResponse" => {
            blockers.push(
                "demo-response needs the creator's actual post-demo message before routing".into(),
            );
            safe_to_say
                .push("The creator demo packet is ready to receive a concrete response.".into());
        }
        "feedbackPatch" => {
            if let Some(recommended_run) = creator_demo.recommended_run_dir.as_deref() {
                let recommended_run = PathBuf::from(recommended_run);
                match build_demo_response_feedback_patch(
                    &recommended_run,
                    &messages,
                    child_markdown,
                ) {
                    Ok((feedback_report, patch_report, artifacts)) => {
                        generated_artifacts.extend(artifacts);
                        safe_to_say.extend(feedback_report.safe_to_say.clone());
                        safe_to_say.extend(patch_report.safe_to_say.clone());
                        do_not_say.extend(feedback_report.do_not_say.clone());
                        do_not_say.extend(patch_report.do_not_say.clone());
                        blockers.extend(feedback_report.blockers.clone());
                        blockers.extend(patch_report.blockers.clone());
                        warnings.extend(feedback_report.warnings.clone());
                        warnings.extend(patch_report.warnings.clone());
                        feedback = Some(feedback_report);
                        feedback_patch = Some(patch_report);
                    }
                    Err(err) => {
                        blockers.push(format!("demo-response feedback route failed: {err}"))
                    }
                }
            } else {
                blockers.push(
                    "feedback route needs a recommended run from creator-demo before patch triage"
                        .into(),
                );
            }
        }
        "approvalGate" => {
            if let Some(recommended_run) = creator_demo.recommended_run_dir.as_deref() {
                let recommended_run = PathBuf::from(recommended_run);
                let approval_path = recommended_run.join("approval.json");
                let approval_markdown = child_markdown.then(|| recommended_run.join("approval.md"));
                match build_approval_report(
                    &recommended_run,
                    &approval_path,
                    approval_markdown.as_deref(),
                ) {
                    Ok(report) => {
                        write_json(approval_path.clone(), &report)?;
                        if let Some(path) = approval_markdown {
                            write_approval_markdown(path, &report)?;
                        }
                        generated_artifacts.extend(report.artifacts.clone());
                        warnings.extend(
                            report
                                .blockers
                                .iter()
                                .map(|blocker| format!("approval gate blocker: {blocker}")),
                        );
                        warnings.extend(report.warnings.clone());
                        do_not_say.extend(report.do_not_claim.clone());
                        safe_to_say.push(
                            "Creator approval-like wording has been routed to the approval gate; it is not live Studio apply approval.".into(),
                        );
                        approval = Some(report);
                    }
                    Err(err) => {
                        blockers.push(format!("demo-response approval route failed: {err}"))
                    }
                }
            } else {
                blockers.push(
                    "approval route needs a recommended run from creator-demo before live-gate review"
                        .into(),
                );
            }
        }
        "decisionOrNewWow" => {
            match build_demo_response_decision(&options.run_dir, &messages, child_markdown) {
                Ok(report) => {
                    generated_artifacts.extend(report.artifacts.clone());
                    blockers.extend(report.blockers.clone());
                    warnings.extend(report.warnings.clone());
                    safe_to_say.extend(report.safe_to_say.clone());
                    do_not_say.extend(report.do_not_say.clone());
                    decision = Some(report);
                }
                Err(err) => blockers.push(format!("demo-response decision route failed: {err}")),
            }
        }
        _ => {
            let checked_run = creator_demo
                .recommended_run_dir
                .as_deref()
                .map(PathBuf::from)
                .unwrap_or_else(|| options.run_dir.clone());
            let claim_path = checked_run.join("claim-check.json");
            let claim_markdown = child_markdown.then(|| checked_run.join("claim-check.md"));
            let claim_options = ClaimCheckOptions {
                run_dir: checked_run.clone(),
                claims: vec![
                    "The creator demo response has been recorded for safe offline routing.".into(),
                ],
                out: Some(claim_path.clone()),
                markdown: claim_markdown.clone(),
                no_markdown: !child_markdown,
                json: false,
            };
            match build_claim_check_report(&claim_options, &claim_path, claim_markdown.as_deref()) {
                Ok(report) => {
                    write_json(claim_path.clone(), &report)?;
                    if let Some(path) = claim_markdown {
                        write_claim_check_markdown(path, &report)?;
                    }
                    generated_artifacts.extend(report.artifacts.clone());
                    warnings.extend(
                        report.blockers.iter().map(|blocker| {
                            format!("checked-response claim needs rewrite: {blocker}")
                        }),
                    );
                    warnings.extend(report.warnings.clone());
                    safe_to_say.extend(report.safe_to_say.clone());
                    do_not_say.extend(report.do_not_say.clone());
                    claim_check = Some(report);
                }
                Err(err) => blockers.push(format!("demo-response claim-check route failed: {err}")),
            }
        }
    }

    safe_to_say.push(demo_response_safe_route_claim(route));
    do_not_say.extend([
        "Do not treat demo-response as live Studio apply approval.".into(),
        "Do not apply, publish, upload, or claim live playtest proof from a creator chat message alone."
            .into(),
        "Do not skip approval, live-gate, rollback, and evidence checks after an approval-like reply."
            .into(),
    ]);

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();

    let status = if blockers.is_empty() {
        "routed"
    } else {
        "blocked"
    };
    let mut next_actions = build_demo_response_next_actions(
        route,
        &options.run_dir,
        creator_demo.recommended_run_dir.as_deref(),
    );
    dedup_next_actions(&mut next_actions);
    let agent_brief = build_demo_response_agent_brief(
        status,
        route,
        &messages,
        creator_demo.recommended_run_dir.as_deref(),
    );

    Ok(DemoResponseReport {
        schema_version: "rs.autopilot.demo-response.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        response_path: response_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        status: status.into(),
        route: route.into(),
        route_reason,
        messages,
        recommended_run_dir: creator_demo.recommended_run_dir.clone(),
        creator_demo_path: creator_demo.creator_demo_path.clone(),
        generated_artifacts,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        next_actions,
        agent_brief,
        creator_demo,
        feedback,
        feedback_patch,
        decision,
        approval,
        claim_check,
    })
}

fn build_demo_response_feedback_patch(
    run_dir: &Path,
    messages: &[String],
    child_markdown: bool,
) -> AppResult<(
    FeedbackReport,
    FeedbackPatchReport,
    BTreeMap<String, String>,
)> {
    let feedback_path = run_dir.join("feedback.json");
    let feedback_markdown = child_markdown.then(|| run_dir.join("feedback.md"));
    let feedback_options = FeedbackOptions {
        run_dir: run_dir.to_path_buf(),
        notes: messages.to_vec(),
        source: "creator-demo-response".into(),
        out: Some(feedback_path.clone()),
        markdown: feedback_markdown.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let feedback_report = build_feedback_report(
        &feedback_options,
        &feedback_path,
        feedback_markdown.as_deref(),
    )?;
    write_json(feedback_path.clone(), &feedback_report)?;
    if let Some(path) = feedback_markdown {
        write_feedback_markdown(path, &feedback_report)?;
    }

    let patch_path = run_dir.join("feedback-patch.json");
    let patch_markdown = child_markdown.then(|| run_dir.join("feedback-patch.md"));
    let planner_pack_path = Some(run_dir.join("feedback-planner-pack.json"));
    let planner_pack_markdown = child_markdown.then(|| run_dir.join("feedback-planner-pack.md"));
    let patch_options = FeedbackPatchOptions {
        run_dir: run_dir.to_path_buf(),
        feedback: Some(feedback_path),
        out: Some(patch_path.clone()),
        markdown: patch_markdown.clone(),
        planner_pack: planner_pack_path.clone(),
        no_planner_pack: false,
        no_markdown: !child_markdown,
        json: false,
    };
    let patch_report = build_feedback_patch_report(
        &patch_options,
        &patch_path,
        patch_markdown.as_deref(),
        planner_pack_path.as_deref(),
        planner_pack_markdown.as_deref(),
    )?;
    let mut artifacts = patch_report.artifacts.clone();
    if patch_report.blockers.is_empty() {
        if let Some(path) = planner_pack_path {
            let planner_pack = build_planner_pack_report(
                Some(&patch_report.custom_planner_prompt),
                Some(run_dir),
                None,
                &path,
                planner_pack_markdown.as_deref(),
            )?;
            artifacts.insert(
                "feedbackPlannerPack".into(),
                planner_pack.planner_pack_path.clone(),
            );
            if let Some(markdown_path) = &planner_pack.markdown_path {
                artifacts.insert("feedbackPlannerPackMarkdown".into(), markdown_path.clone());
            }
            artifacts.extend(planner_pack.run_artifacts.clone());
            write_json(path, &planner_pack)?;
            if let Some(markdown_path) = planner_pack_markdown {
                write_planner_pack_markdown(markdown_path, &planner_pack)?;
            }
        }
    }
    write_json(patch_path.clone(), &patch_report)?;
    if let Some(path) = patch_markdown {
        write_feedback_patch_markdown(path, &patch_report)?;
    }
    artifacts.extend(feedback_report.artifacts.clone());
    Ok((feedback_report, patch_report, artifacts))
}

fn build_demo_response_decision(
    run_dir: &Path,
    messages: &[String],
    child_markdown: bool,
) -> AppResult<DecisionReport> {
    let decision_path = run_dir.join("decisions.json");
    let decision_markdown = child_markdown.then(|| run_dir.join("decisions.md"));
    let message_text = messages.join(" ");
    let lower = message_text.to_ascii_lowercase();
    let decision_options = DecisionOptions {
        run_dir: run_dir.to_path_buf(),
        source: "creator-demo-response".into(),
        decisions: if text_contains_any(
            &lower,
            &[
                "different direction",
                "new direction",
                "instead",
                "rather",
                "change direction",
            ],
        ) {
            vec![message_text.clone()]
        } else {
            Vec::new()
        },
        constraints: Vec::new(),
        rejections: if text_contains_any(
            &lower,
            &[
                "reject",
                "not this",
                "don't like",
                "dont like",
                "start over",
                "scrap",
                "no thanks",
            ],
        ) {
            vec![message_text.clone()]
        } else {
            Vec::new()
        },
        notes: if message_text.trim().is_empty() {
            Vec::new()
        } else {
            vec![message_text]
        },
        out: Some(decision_path.clone()),
        markdown: decision_markdown.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let report = build_decision_report(
        &decision_options,
        &decision_path,
        decision_markdown.as_deref(),
    )?;
    write_json(decision_path, &report)?;
    if let Some(path) = decision_markdown {
        write_decision_markdown(path, &report)?;
    }
    Ok(report)
}

fn normalize_demo_response_messages(messages: &[String]) -> Vec<String> {
    messages
        .iter()
        .map(|message| redact_text(message.trim()))
        .filter(|message| !message.is_empty())
        .collect::<Vec<_>>()
}

fn classify_demo_response_route(messages: &[String]) -> (&'static str, String) {
    if messages.is_empty() {
        return (
            "needsCreatorResponse",
            "no creator response text was provided".into(),
        );
    }
    let lower = messages.join(" ").to_ascii_lowercase();
    let feedback_like = text_contains_any(
        &lower,
        &[
            " but ",
            "change",
            "tweak",
            "fix",
            "confusing",
            "brighter",
            "darker",
            "more ",
            "less ",
            "add ",
            "remove",
            "should",
            "needs",
            "button",
            "thumbnail",
            "color",
            "reward",
            "price",
            "bug",
            "slow",
        ],
    );
    if feedback_like {
        return (
            "feedbackPatch",
            "creator response contains concrete tweak or repair language".into(),
        );
    }
    let rejection_like = text_contains_any(
        &lower,
        &[
            "reject",
            "not this",
            "don't like",
            "dont like",
            "start over",
            "scrap",
            "different direction",
            "new direction",
            "no thanks",
        ],
    );
    if rejection_like {
        return (
            "decisionOrNewWow",
            "creator response rejects or redirects the proposed wow continuation".into(),
        );
    }
    let approval_like = decision_is_approval_like(&lower)
        || text_contains_any(
            &lower,
            &[
                "yes",
                "go for it",
                "let's do it",
                "lets do it",
                "apply it",
                "looks great",
                "ship",
            ],
        );
    if approval_like {
        return (
            "approvalGate",
            "creator response is approval-like, so it must be routed to explicit approval gates"
                .into(),
        );
    }
    (
        "checkedResponse",
        "creator response is informational or question-like and should be answered through checked claims"
            .into(),
    )
}

fn demo_response_safe_route_claim(route: &str) -> String {
    match route {
        "feedbackPatch" => {
            "Creator feedback was routed into offline feedback and feedback-patch artifacts.".into()
        }
        "approvalGate" => {
            "Approval-like creator wording was routed to approval review, not treated as live apply permission.".into()
        }
        "decisionOrNewWow" => {
            "Creator redirection was recorded as offline decision context for the next wow selection.".into()
        }
        "checkedResponse" => {
            "Creator response was routed to checked-response handling before any creator-facing claim.".into()
        }
        _ => "Creator demo response routing needs more input before action.".into(),
    }
}

fn build_demo_response_next_actions(
    route: &str,
    source_run: &Path,
    recommended_run: Option<&str>,
) -> Vec<CoachAction> {
    let source_arg = command_arg(source_run.to_string_lossy().as_ref());
    let recommended_arg = recommended_run.map(command_arg);
    match route {
        "feedbackPatch" => {
            let run = recommended_arg.unwrap_or_else(|| source_arg.clone());
            vec![
                coach_action(
                    1,
                    "Review feedback patch work order",
                    Some(format!("rs autopilot feedback-patch {run} --format json")),
                    "Use the generated feedback patch packet before asking an AI for a strict patch plan.",
                    false,
                    false,
                ),
                coach_action(
                    2,
                    "Refresh creator demo after patch planning",
                    Some(format!("rs autopilot creator-demo {source_arg} --format json")),
                    "Regenerate the demo packet after the feedback patch run exists and is reviewed.",
                    false,
                    false,
                ),
            ]
        }
        "approvalGate" => {
            let run = recommended_arg.unwrap_or_else(|| source_arg.clone());
            vec![
                coach_action(
                    1,
                    "Prepare approval packet",
                    Some(format!("rs autopilot approval {run} --format json")),
                    "Approval-like wording must be converted into an explicit approval packet.",
                    false,
                    false,
                ),
                coach_action(
                    2,
                    "Check live readiness",
                    Some("rs autopilot ready --timeout 90 --format json".into()),
                    "Live apply needs bridge readiness before any mutating command.",
                    true,
                    false,
                ),
                coach_action(
                    3,
                    "Run live gate only after explicit approval",
                    Some(format!("rs autopilot live-gate {run} --approved --format json")),
                    "Live-gate turns separate approval plus readiness evidence into the next safe command.",
                    true,
                    false,
                ),
            ]
        }
        "decisionOrNewWow" => vec![
            coach_action(
                1,
                "Refresh wow plan from creator direction",
                Some(format!("rs autopilot wow-plan {source_arg} --format json")),
                "Use the recorded redirection before choosing another wow continuation.",
                false,
                false,
            ),
            coach_action(
                2,
                "Decide the next wow candidate",
                Some(format!(
                    "rs autopilot moment-decision {source_arg} --format json"
                )),
                "Compare the next candidate offline before presenting a new demo.",
                false,
                false,
            ),
        ],
        "checkedResponse" => {
            let run = recommended_arg.unwrap_or_else(|| source_arg.clone());
            vec![coach_action(
                1,
                "Prepare evidence-checked reply",
                Some(format!(
                    "rs autopilot respond {run} --claim \"<exact reply claim>\" --format json"
                )),
                "Respond only with claims that are supported by the current artifacts.",
                false,
                false,
            )]
        }
        _ => vec![coach_action(
            1,
            "Capture creator response",
            Some(format!(
                "rs autopilot demo-response {source_arg} --message \"<creator response>\" --format json"
            )),
            "Routing needs the exact creator message from after the demo.",
            false,
            false,
        )],
    }
}

fn build_demo_response_agent_brief(
    status: &str,
    route: &str,
    messages: &[String],
    recommended_run: Option<&str>,
) -> String {
    let run = recommended_run.unwrap_or("<no recommended run>");
    let message_count = messages.len();
    format!(
        "Demo response routing is {status}: {message_count} creator message(s) selected `{route}` for recommended run `{run}`. This command writes offline routing artifacts only and never treats chat wording as live Studio mutation approval."
    )
}

fn build_demo_loop_report(
    options: &DemoLoopOptions,
    loop_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<DemoLoopReport> {
    let child_markdown = markdown_path.is_some();
    let response_path = options.run_dir.join("demo-response.json");
    let response_markdown = child_markdown.then(|| options.run_dir.join("demo-response.md"));
    let response_options = DemoResponseOptions {
        messages: options.messages.clone(),
        idea: options.idea.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        max_ideas: options.max_ideas,
        max_chars: options.max_chars,
        dry_run: options.dry_run,
        out: Some(response_path.clone()),
        markdown: response_markdown.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let demo_response = build_demo_response_report(
        &response_options,
        &response_path,
        response_markdown.as_deref(),
    )?;
    write_json(response_path, &demo_response)?;
    if let Some(path) = response_markdown {
        write_demo_response_markdown(path, &demo_response)?;
    }

    let mut artifacts = demo_response.generated_artifacts.clone();
    artifacts.insert("demoLoop".into(), loop_path.to_string_lossy().to_string());
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "demoLoopMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    let mut blockers = demo_response.blockers.clone();
    let mut warnings = demo_response.warnings.clone();
    let command_queue = build_demo_loop_command_queue(&demo_response);
    let mut expected_artifacts = command_queue
        .iter()
        .filter_map(|action| action.command.as_deref())
        .flat_map(expected_artifacts_for_command)
        .collect::<Vec<_>>();
    expected_artifacts.extend(artifacts.values().cloned());
    expected_artifacts.sort();
    expected_artifacts.dedup();
    let stop_conditions = build_demo_loop_stop_conditions(&demo_response);
    let handoff_title = demo_loop_handoff_title(&demo_response).to_string();
    let handoff_prompt = build_demo_loop_handoff_prompt(&demo_response, &command_queue);
    let status = if !blockers.is_empty() {
        "blocked"
    } else if demo_response.route == "needsCreatorResponse" {
        "needsCreatorResponse"
    } else if demo_response.route == "approvalGate" {
        "readyForApprovalGate"
    } else {
        "readyForNextAgent"
    };
    let ready_for_next_agent = matches!(status, "readyForNextAgent" | "readyForApprovalGate");
    if !ready_for_next_agent && demo_response.route != "needsCreatorResponse" {
        warnings.push("demo loop is not ready for a next agent until blockers are resolved".into());
    }

    let mut safe_to_say = demo_response.safe_to_say.clone();
    if ready_for_next_agent {
        safe_to_say.push(format!(
            "Demo loop prepared a `{}` handoff without mutating Studio.",
            demo_response.route
        ));
    }
    let mut do_not_say = demo_response.do_not_say.clone();
    do_not_say.extend([
        "Do not claim demo-loop implemented feedback; it packages the next safe work packet."
            .into(),
        "Do not claim demo-loop crossed approval, live apply, publish, upload, or playtest gates."
            .into(),
    ]);
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();

    let mut next_actions = command_queue.clone();
    if next_actions.is_empty() {
        next_actions = demo_response.next_actions.clone();
    }
    dedup_next_actions(&mut next_actions);
    let agent_brief = build_demo_loop_agent_brief(
        status,
        &demo_response.route,
        ready_for_next_agent,
        command_queue.len(),
        demo_response.recommended_run_dir.as_deref(),
    );

    Ok(DemoLoopReport {
        schema_version: "rs.autopilot.demo-loop.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        loop_path: loop_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        status: status.into(),
        route: demo_response.route.clone(),
        route_reason: demo_response.route_reason.clone(),
        messages: demo_response.messages.clone(),
        recommended_run_dir: demo_response.recommended_run_dir.clone(),
        ready_for_next_agent,
        handoff_title,
        handoff_prompt,
        command_queue,
        expected_artifacts,
        stop_conditions,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        demo_response,
    })
}

fn demo_loop_handoff_title(response: &DemoResponseReport) -> &'static str {
    match response.route.as_str() {
        "feedbackPatch" => "Implement The Creator Feedback Offline",
        "approvalGate" => "Prepare Explicit Approval And Live Gate",
        "decisionOrNewWow" => "Choose A New Wow Direction",
        "checkedResponse" => "Answer With Evidence-Checked Claims",
        _ => "Collect A Concrete Post-Demo Response",
    }
}

fn build_demo_loop_command_queue(response: &DemoResponseReport) -> Vec<CoachAction> {
    let source_arg = command_arg(&response.run_dir);
    let recommended_arg = response.recommended_run_dir.as_deref().map(command_arg);
    match response.route.as_str() {
        "feedbackPatch" => {
            let run = recommended_arg.unwrap_or_else(|| source_arg.clone());
            let mut actions = vec![coach_action(
                1,
                "Review feedback patch packet",
                Some(format!("rs autopilot feedback-patch {run} --format json")),
                "Confirm the feedback-specific planner prompt, lanes, and adoption command before asking an AI to produce the strict patch plan.",
                false,
                false,
            )];
            if let Some(patch) = &response.feedback_patch {
                if let Some(command) = &patch.adopt_plan_command {
                    actions.push(coach_action(
                        2,
                        "Adopt returned strict patch plan",
                        Some(command.clone()),
                        "Use only after the next AI returns strict rs.autopilot.plan.v1 JSON for the feedback patch.",
                        false,
                        false,
                    ));
                }
                for command in patch.validation_commands.iter().take(3) {
                    actions.push(coach_action(
                        3,
                        "Validate feedback patch candidate",
                        Some(command.clone()),
                        "Verify the adopted patch run before presenting another demo.",
                        false,
                        false,
                    ));
                }
            }
            actions.push(coach_action(
                8,
                "Refresh creator demo after patch evidence",
                Some(format!("rs autopilot creator-demo {source_arg} --format json")),
                "Regenerate the proof-bound demo packet after the feedback patch candidate is reviewed.",
                false,
                false,
            ));
            actions
        }
        "approvalGate" => {
            let run = recommended_arg.unwrap_or_else(|| source_arg.clone());
            vec![
                coach_action(
                    1,
                    "Read approval packet aloud",
                    Some(format!("rs autopilot approval {run} --format json")),
                    "Use the approval artifact prompt rather than treating chat wording as permission.",
                    false,
                    false,
                ),
                coach_action(
                    2,
                    "Check live readiness",
                    Some("rs autopilot ready --timeout 90 --format json".into()),
                    "Only continue toward live-gate when Studio bridge readiness is confirmed.",
                    true,
                    false,
                ),
                coach_action(
                    3,
                    "Open live gate after explicit approval",
                    Some(format!("rs autopilot live-gate {run} --approved --format json")),
                    "Live-gate is still non-apply review; apply remains a separate mutating command.",
                    true,
                    false,
                ),
            ]
        }
        "decisionOrNewWow" => vec![
            coach_action(
                1,
                "Refresh wow plan from recorded direction",
                Some(format!("rs autopilot wow-plan {source_arg} --format json")),
                "Use recorded creator redirection before selecting another player moment.",
                false,
                false,
            ),
            coach_action(
                2,
                "Build or decide the next wow continuation",
                Some(format!(
                    "rs autopilot moment-decision {source_arg} --format json"
                )),
                "Compare the next candidate offline before showing a revised demo.",
                false,
                false,
            ),
            coach_action(
                3,
                "Prepare revised creator demo",
                Some(format!(
                    "rs autopilot creator-demo {source_arg} --format json"
                )),
                "Present the new continuation only after proof-bound demo artifacts refresh.",
                false,
                false,
            ),
        ],
        "checkedResponse" => {
            let run = recommended_arg.unwrap_or_else(|| source_arg.clone());
            vec![coach_action(
                1,
                "Write evidence-checked creator reply",
                Some(format!(
                    "rs autopilot respond {run} --claim \"<exact response claim>\" --format json"
                )),
                "Use only claims that claim-check can support from local artifacts.",
                false,
                false,
            )]
        }
        _ => vec![coach_action(
            1,
            "Capture the creator's post-demo response",
            Some(format!(
                "rs autopilot demo-loop {source_arg} --message \"<creator response>\" --format json"
            )),
            "Demo-loop needs the exact response before it can package the next safe handoff.",
            false,
            false,
        )],
    }
}

fn build_demo_loop_stop_conditions(response: &DemoResponseReport) -> Vec<String> {
    let mut stops = vec![
        "Stop before any `rs autopilot apply` command unless live-gate emits an approved apply command."
            .into(),
        "Stop before claiming Studio changed, playtest passed, rollback is ready, or production readiness unless matching artifacts exist.".into(),
        "Refresh demo-loop if the creator changes the wording or adds new feedback.".into(),
    ];
    match response.route.as_str() {
        "feedbackPatch" => stops.push(
            "Stop after generating/adopting a feedback patch until the patch run is certified, compared, and demo evidence refreshes."
                .into(),
        ),
        "approvalGate" => stops.push(
            "Stop at approval, ready, or live-gate blockers; approval-like chat is not enough for mutation."
                .into(),
        ),
        "decisionOrNewWow" => stops.push(
            "Stop before building a new direction if the decision ledger reports approval-like live mutation terms."
                .into(),
        ),
        "checkedResponse" => stops.push(
            "Stop before sending a response if claim-check marks any exact claim unsupported or risky."
                .into(),
        ),
        _ => stops.push("Stop and ask for a concrete creator response.".into()),
    }
    stops.sort();
    stops.dedup();
    stops
}

fn build_demo_loop_handoff_prompt(
    response: &DemoResponseReport,
    command_queue: &[CoachAction],
) -> String {
    let mut out = String::new();
    out.push_str("You are continuing a Roblox Autopilot creator-demo loop.\n");
    out.push_str(&format!("Route: {}\n", response.route));
    out.push_str(&format!("Reason: {}\n", response.route_reason));
    out.push_str(&format!("Source run: {}\n", response.run_dir));
    if let Some(run) = &response.recommended_run_dir {
        out.push_str(&format!("Recommended run: {run}\n"));
    }
    if !response.messages.is_empty() {
        out.push_str("\nCreator response:\n");
        for message in &response.messages {
            out.push_str(&format!("- {message}\n"));
        }
    }
    match response.route.as_str() {
        "feedbackPatch" => {
            out.push_str("\nTask: produce or hand off one strict feedback patch plan.\n");
            if let Some(patch) = &response.feedback_patch {
                out.push_str("\nFeedback planner prompt:\n```text\n");
                out.push_str(&patch.custom_planner_prompt);
                out.push_str("\n```\n");
                if let Some(command) = &patch.adopt_plan_command {
                    out.push_str(&format!(
                        "\nAfter a strict plan exists, adopt with:\n`{command}`\n"
                    ));
                }
            }
        }
        "approvalGate" => {
            out.push_str("\nTask: present the approval gate and stop before mutation.\n");
            if let Some(approval) = &response.approval {
                out.push_str(&format!(
                    "\nApproval prompt:\n{}\n",
                    approval.approval_prompt
                ));
            }
        }
        "decisionOrNewWow" => {
            out.push_str("\nTask: honor the creator redirection, refresh wow planning, and prepare a revised proof-bound demo.\n");
        }
        "checkedResponse" => {
            out.push_str("\nTask: answer only with exact claims supported by claim-check.\n");
        }
        _ => {
            out.push_str("\nTask: ask for a concrete post-demo response before acting.\n");
        }
    }
    if !command_queue.is_empty() {
        out.push_str("\nCommand queue:\n");
        for action in command_queue {
            if let Some(command) = &action.command {
                out.push_str(&format!("- {command}\n"));
            }
        }
    }
    out.push_str("\nSafety rules:\n");
    out.push_str("- Do not run live or mutating commands unless the route explicitly reaches live-gate and approval/readiness pass.\n");
    out.push_str("- Do not claim feedback is implemented until an adopted patch run is certified and reviewed.\n");
    out.push_str("- Do not claim publish, upload, live playtest, rollback, or production readiness from this packet alone.\n");
    out
}

fn build_demo_loop_agent_brief(
    status: &str,
    route: &str,
    ready_for_next_agent: bool,
    command_count: usize,
    recommended_run: Option<&str>,
) -> String {
    let run = recommended_run.unwrap_or("<no recommended run>");
    format!(
        "Demo loop is {status}: route `{route}` prepared {command_count} command(s) for recommended run `{run}`. readyForNextAgent={ready_for_next_agent}. It packages the next safe handoff and does not mutate Studio."
    )
}

fn build_demo_session_report(
    options: &DemoSessionOptions,
    session_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<DemoSessionReport> {
    let child_markdown = markdown_path.is_some();
    let demo_loop_path = options.run_dir.join("demo-loop.json");
    let demo_loop_markdown = child_markdown.then(|| options.run_dir.join("demo-loop.md"));
    let demo_loop_options = DemoLoopOptions {
        messages: options.messages.clone(),
        idea: options.idea.clone(),
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        max_ideas: options.max_ideas,
        max_chars: options.max_chars,
        dry_run: options.dry_run,
        out: Some(demo_loop_path.clone()),
        markdown: demo_loop_markdown.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let demo_loop = build_demo_loop_report(
        &demo_loop_options,
        &demo_loop_path,
        demo_loop_markdown.as_deref(),
    )?;
    write_json(demo_loop_path.clone(), &demo_loop)?;
    if let Some(path) = demo_loop_markdown {
        write_demo_loop_markdown(path, &demo_loop)?;
    }
    if let Some(recommended) = demo_loop.recommended_run_dir.as_deref() {
        refresh_run_bundle_if_possible(Path::new(recommended))?;
    }

    let demo_check_path = options.run_dir.join("demo-check.json");
    let demo_check_markdown = child_markdown.then(|| options.run_dir.join("demo-check.md"));
    let demo_check_options = DemoCheckOptions {
        run_dir: options.run_dir.clone(),
        out: Some(demo_check_path.clone()),
        markdown: demo_check_markdown.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let demo_check = build_demo_check_report(
        &demo_check_options,
        &demo_check_path,
        demo_check_markdown.as_deref(),
    )?;
    write_json(demo_check_path.clone(), &demo_check)?;
    if let Some(path) = demo_check_markdown {
        write_demo_check_markdown(path, &demo_check)?;
    }

    let demo_reply_path = options.run_dir.join("demo-reply.json");
    let demo_reply_markdown = child_markdown.then(|| options.run_dir.join("demo-reply.md"));
    let demo_reply_options = DemoReplyOptions {
        run_dir: options.run_dir.clone(),
        out: Some(demo_reply_path.clone()),
        markdown: demo_reply_markdown.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let demo_reply = build_demo_reply_report(
        &demo_reply_options,
        &demo_reply_path,
        demo_reply_markdown.as_deref(),
    )?;
    write_json(demo_reply_path.clone(), &demo_reply)?;
    if let Some(path) = demo_reply_markdown {
        write_demo_reply_markdown(path, &demo_reply)?;
    }

    let demo_learn_path = options.run_dir.join("demo-learn.json");
    let demo_learn_markdown = child_markdown.then(|| options.run_dir.join("demo-learn.md"));
    let demo_learn_options = DemoLearnOptions {
        run_dir: options.run_dir.clone(),
        out: Some(demo_learn_path.clone()),
        markdown: demo_learn_markdown.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let demo_learn = build_demo_learn_report(
        &demo_learn_options,
        &demo_learn_path,
        demo_learn_markdown.as_deref(),
    )?;
    write_json(demo_learn_path.clone(), &demo_learn)?;
    if let Some(path) = demo_learn_markdown {
        write_demo_learn_markdown(path, &demo_learn)?;
    }

    refresh_run_bundle_if_possible(&options.run_dir)?;
    if let Some(recommended) = demo_loop.recommended_run_dir.as_deref() {
        refresh_run_bundle_if_possible(Path::new(recommended))?;
    }

    let remember_path = options.run_dir.join("remember.json");
    let remember_markdown = child_markdown.then(|| options.run_dir.join("remember.md"));
    let remember_options = RememberOptions {
        run_dir: options.run_dir.clone(),
        root: options.root.clone(),
        limit: options.limit,
        best_friend: false,
        opportunity: None,
        max_chars: options.max_chars,
        out: Some(remember_path.clone()),
        markdown: remember_markdown.clone(),
        no_markdown: !child_markdown,
        json: false,
    };
    let remember = build_remember_report(
        &remember_options,
        &remember_path,
        remember_markdown.as_deref(),
    )?;
    write_json(remember_path.clone(), &remember)?;
    if let Some(path) = remember_markdown {
        write_remember_markdown(path, &remember)?;
    }

    let mut artifacts = demo_loop.artifacts.clone();
    artifacts.extend(demo_check.artifacts.clone());
    artifacts.extend(demo_reply.artifacts.clone());
    artifacts.extend(demo_learn.artifacts.clone());
    artifacts.extend(remember.artifacts.clone());
    artifacts.insert(
        "demoSession".into(),
        session_path.to_string_lossy().to_string(),
    );
    if let Some(path) = markdown_path {
        artifacts.insert(
            "demoSessionMarkdown".into(),
            path.to_string_lossy().to_string(),
        );
    }

    let mut blockers = demo_loop.blockers.clone();
    blockers.extend(demo_check.blockers.clone());
    blockers.extend(demo_reply.blockers.clone());
    blockers.extend(demo_learn.blockers.clone());
    blockers.extend(remember.blockers.clone());
    blockers.sort();
    blockers.dedup();

    let mut warnings = demo_loop.warnings.clone();
    warnings.extend(demo_check.warnings.clone());
    warnings.extend(demo_reply.warnings.clone());
    warnings.extend(demo_learn.warnings.clone());
    warnings.extend(remember.warnings.clone());
    warnings.sort();
    warnings.dedup();

    let mut safe_to_say = demo_loop.safe_to_say.clone();
    safe_to_say.extend(demo_check.safe_to_say.clone());
    safe_to_say.extend(demo_reply.safe_to_say.clone());
    safe_to_say.extend(demo_learn.safe_to_say.clone());
    safe_to_say.extend(remember.safe_to_say.clone());
    safe_to_say.push(
        "Demo session routed the creator's post-demo response, checked follow-through, drafted a safe reply, and refreshed remembered context from local artifacts."
            .into(),
    );
    safe_to_say.sort();
    safe_to_say.dedup();

    let mut do_not_say = demo_loop.do_not_say.clone();
    do_not_say.extend(demo_check.do_not_say.clone());
    do_not_say.extend(demo_reply.do_not_say.clone());
    do_not_say.extend(demo_learn.do_not_say.clone());
    do_not_say.extend(remember.do_not_say.clone());
    do_not_say.extend([
        "Do not claim demo-session implemented feedback unless a later patch run proves it.".into(),
        "Do not claim demo-session applied, published, uploaded, live playtested, or mutated Studio."
            .into(),
        "Do not treat demo-session as live apply approval or production completion proof.".into(),
    ]);
    do_not_say.sort();
    do_not_say.dedup();

    let status = demo_session_status(
        &blockers,
        &demo_loop.status,
        &demo_reply.status,
        &demo_learn.status,
        &remember.status,
    );
    let verdict = demo_session_verdict(&status);
    let mut next_actions = if status == "readyToSend" {
        vec![coach_action(
            1,
            "Send checked post-demo reply",
            None,
            "Use replyMessage exactly; rerun demo-session if the wording changes.",
            false,
            false,
        )]
    } else {
        Vec::new()
    };
    next_actions.extend(demo_reply.next_actions.clone());
    next_actions.extend(remember.next_actions.clone());
    next_actions.extend(demo_loop.command_queue.clone());
    dedup_next_actions(&mut next_actions);
    let reply_message = (demo_reply.status == "readyToSend").then(|| demo_reply.message.clone());
    let agent_brief = format!(
        "Demo session is {status}: route `{}` produced demo-loop `{}`, demo-check `{}`, demo-reply `{}`, demo-learn `{}`, remember `{}`. Send replyMessage only when status is readyToSend.",
        demo_loop.route,
        demo_loop.status,
        demo_check.status,
        demo_reply.status,
        demo_learn.status,
        remember.status
    );

    Ok(DemoSessionReport {
        schema_version: "rs.autopilot.demo-session.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        session_path: session_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: options.root.to_string_lossy().to_string(),
        status,
        verdict,
        route: demo_loop.route.clone(),
        route_reason: demo_loop.route_reason.clone(),
        messages: demo_loop.messages.clone(),
        recommended_run_dir: demo_loop.recommended_run_dir.clone(),
        ready_for_next_agent: demo_loop.ready_for_next_agent,
        demo_loop_status: demo_loop.status.clone(),
        demo_check_status: demo_check.status.clone(),
        demo_reply_status: demo_reply.status.clone(),
        demo_learn_status: demo_learn.status.clone(),
        remember_status: remember.status.clone(),
        reply_message,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
        demo_loop,
        demo_check,
        demo_reply,
        demo_learn,
        remember,
    })
}

fn demo_session_status(
    blockers: &[String],
    demo_loop_status: &str,
    demo_reply_status: &str,
    demo_learn_status: &str,
    remember_status: &str,
) -> String {
    if !blockers.is_empty() {
        "blocked"
    } else if demo_loop_status == "needsCreatorResponse" {
        "needsCreatorResponse"
    } else if demo_reply_status == "readyToSend"
        && matches!(demo_learn_status, "ready" | "needsReview")
        && matches!(remember_status, "ready" | "readyWithWarnings")
    {
        "readyToSend"
    } else if demo_reply_status == "readyToSend" {
        "readyToReply"
    } else {
        "needsFollowup"
    }
    .into()
}

fn demo_session_verdict(status: &str) -> String {
    match status {
        "readyToSend" => "demoSessionReplyReadyAndRemembered",
        "readyToReply" => "demoSessionReplyReady",
        "needsCreatorResponse" => "demoSessionNeedsCreatorResponse",
        "needsFollowup" => "demoSessionNeedsFollowup",
        _ => "demoSessionBlocked",
    }
    .into()
}

fn build_demo_check_report(
    options: &DemoCheckOptions,
    check_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<DemoCheckReport> {
    let demo_loop_path = options.run_dir.join("demo-loop.json");
    let demo_response_path = options.run_dir.join("demo-response.json");
    let loop_value = read_json_if_exists(&demo_loop_path)?;
    let response_value = read_json_if_exists(&demo_response_path)?;
    let route = loop_value
        .as_ref()
        .and_then(|value| string_field(value, "route"))
        .or_else(|| {
            response_value
                .as_ref()
                .and_then(|value| string_field(value, "route"))
        })
        .unwrap_or_else(|| "missing".into());
    let recommended_run_dir = loop_value
        .as_ref()
        .and_then(|value| string_field(value, "recommendedRunDir"))
        .or_else(|| {
            response_value
                .as_ref()
                .and_then(|value| string_field(value, "recommendedRunDir"))
        });

    let mut artifacts = collect_planner_run_artifacts(Some(&options.run_dir));
    artifacts.insert("demoCheck".into(), check_path.to_string_lossy().to_string());
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "demoCheckMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    let mut checks = Vec::new();
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if loop_value.is_none() {
        checks.push(demo_check_item(
            "demo-loop",
            "Demo loop packet",
            "missing",
            "demo-loop.json is missing; run demo-loop with the creator response before auditing follow-up.",
            Vec::new(),
            vec![demo_loop_path.to_string_lossy().to_string()],
            Some(format!(
                "rs autopilot demo-loop {} --message \"<creator response>\" --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref())
            )),
            false,
            false,
        ));
        blockers.push("demo-loop.json is missing".into());
    } else {
        checks.push(demo_check_item(
            "demo-loop",
            "Demo loop packet",
            "present",
            "demo-loop.json exists and can be audited.",
            vec![demo_loop_path.to_string_lossy().to_string()],
            Vec::new(),
            None,
            false,
            false,
        ));
    }
    if response_value.is_none() {
        checks.push(demo_check_item(
            "demo-response",
            "Demo response routing",
            "missing",
            "demo-response.json is missing; demo-check cannot verify which route was generated.",
            Vec::new(),
            vec![demo_response_path.to_string_lossy().to_string()],
            Some(format!(
                "rs autopilot demo-response {} --message \"<creator response>\" --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref())
            )),
            false,
            false,
        ));
        blockers.push("demo-response.json is missing".into());
    } else {
        checks.push(demo_check_item(
            "demo-response",
            "Demo response routing",
            "present",
            "demo-response.json exists and provides the routed creator reaction.",
            vec![demo_response_path.to_string_lossy().to_string()],
            Vec::new(),
            None,
            false,
            false,
        ));
    }

    match route.as_str() {
        "feedbackPatch" => {
            build_demo_check_feedback_route(
                options,
                recommended_run_dir.as_deref(),
                &mut checks,
                &mut warnings,
            )?;
        }
        "approvalGate" => {
            build_demo_check_approval_route(
                recommended_run_dir.as_deref(),
                &mut checks,
                &mut blockers,
                &mut warnings,
            )?;
        }
        "decisionOrNewWow" => {
            build_demo_check_decision_route(options, &mut checks, &mut warnings)?;
        }
        "checkedResponse" => {
            let response_run = recommended_run_dir
                .clone()
                .unwrap_or_else(|| options.run_dir.to_string_lossy().to_string());
            build_demo_check_response_route(&response_run, &mut checks, &mut warnings)?;
        }
        "needsCreatorResponse" | "missing" => {
            warnings.push("demo check needs a concrete post-demo creator response".into());
        }
        _ => warnings.push(format!(
            "unknown demo route `{route}`; inspect demo-loop.json"
        )),
    }

    let pending_count = checks
        .iter()
        .filter(|check| matches!(check.status.as_str(), "missing" | "pending" | "blocked"))
        .count();
    let status = if !blockers.is_empty() {
        "blocked"
    } else if pending_count > 0 {
        "needsFollowup"
    } else {
        match route.as_str() {
            "feedbackPatch" => "readyForNextDemo",
            "approvalGate" => "approvalPrepared",
            "decisionOrNewWow" => "directionRecorded",
            "checkedResponse" => "readyToReply",
            _ => "needsCreatorResponse",
        }
    };
    let mut safe_to_say = Vec::new();
    if status != "blocked" && status != "needsFollowup" {
        safe_to_say.push(format!(
            "Post-demo `{route}` follow-up has the required local artifacts for `{status}`."
        ));
    } else {
        safe_to_say.push(
            "Post-demo follow-up still has missing or pending local artifacts; use the listed next actions."
                .into(),
        );
    }
    let mut do_not_say = vec![
        "Do not claim post-demo feedback is implemented unless an adopted patch run is certified, compared, and demo evidence is refreshed.".into(),
        "Do not claim creator approval, live apply, publish, upload, playtest, rollback, or production readiness from demo-check alone.".into(),
    ];
    do_not_say.extend(
        loop_value
            .as_ref()
            .map(|value| string_array_field(value, "doNotSay"))
            .unwrap_or_default(),
    );
    let mut next_actions = demo_check_next_actions(&checks);
    if next_actions.is_empty() {
        next_actions = match route.as_str() {
            "feedbackPatch" => vec![coach_action(
                8,
                "Refresh creator demo",
                Some(format!(
                    "rs autopilot creator-demo {} --format json",
                    command_arg(options.run_dir.to_string_lossy().as_ref())
                )),
                "Regenerate demo evidence after the follow-up patch candidate is reviewed.",
                false,
                false,
            )],
            "approvalGate" => vec![coach_action(
                8,
                "Open approval packet",
                recommended_run_dir.as_deref().map(|run| {
                    format!("rs autopilot approval {} --format json", command_arg(run))
                }),
                "Continue through approval and live-gate without treating chat as apply permission.",
                false,
                false,
            )],
            _ => Vec::new(),
        };
    }
    dedup_next_actions(&mut next_actions);
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    safe_to_say.sort();
    safe_to_say.dedup();
    do_not_say.sort();
    do_not_say.dedup();
    let agent_brief = format!(
        "Demo check is {status}: route `{route}` has {} check(s), {} pending/missing, and {} blocker(s). Use this before claiming the post-demo reaction is handled.",
        checks.len(),
        pending_count,
        blockers.len()
    );

    Ok(DemoCheckReport {
        schema_version: "rs.autopilot.demo-check.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        check_path: check_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status: status.into(),
        route,
        recommended_run_dir,
        demo_loop_path: demo_loop_path.to_string_lossy().to_string(),
        demo_response_path: demo_response_path.to_string_lossy().to_string(),
        checks,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
    })
}

fn build_demo_check_feedback_route(
    options: &DemoCheckOptions,
    recommended_run: Option<&str>,
    checks: &mut Vec<DemoCheckItem>,
    warnings: &mut Vec<String>,
) -> AppResult<()> {
    let Some(recommended_run) = recommended_run else {
        checks.push(demo_check_item(
            "recommended-run",
            "Recommended run",
            "missing",
            "feedback route needs a recommended run from demo-response.",
            Vec::new(),
            vec!["recommendedRunDir".into()],
            Some(format!(
                "rs autopilot demo-loop {} --message \"<creator response>\" --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref())
            )),
            false,
            false,
        ));
        return Ok(());
    };
    let recommended_path = PathBuf::from(recommended_run);
    for (id, title, relative, next) in [
        (
            "feedback",
            "Feedback triage",
            "feedback.json",
            Some(format!(
                "rs autopilot feedback {} --note \"<creator note>\" --format json",
                command_arg(recommended_run)
            )),
        ),
        (
            "feedback-patch",
            "Feedback patch work order",
            "feedback-patch.json",
            Some(format!(
                "rs autopilot feedback-patch {} --format json",
                command_arg(recommended_run)
            )),
        ),
        (
            "feedback-planner-pack",
            "Feedback planner pack",
            "feedback-planner-pack.json",
            None,
        ),
    ] {
        let path = recommended_path.join(relative);
        checks.push(demo_path_check(id, title, &path, next, false, false));
    }
    let patch_run = default_feedback_patch_run_dir(&recommended_path);
    let patch_plan = patch_run.join("plan.json");
    if patch_plan.exists() {
        checks.push(demo_check_item(
            "adopted-patch-run",
            "Adopted feedback patch run",
            "present",
            "feedback patch run has a plan.json and can be certified before a revised demo.",
            vec![patch_plan.to_string_lossy().to_string()],
            Vec::new(),
            Some(format!(
                "rs autopilot certify {} --format json",
                command_arg(patch_run.to_string_lossy().as_ref())
            )),
            false,
            false,
        ));
        let certification = patch_run.join("certification.json");
        checks.push(demo_path_check(
            "patch-certification",
            "Feedback patch certification",
            &certification,
            Some(format!(
                "rs autopilot certify {} --format json",
                command_arg(patch_run.to_string_lossy().as_ref())
            )),
            false,
            false,
        ));
    } else {
        checks.push(demo_check_item(
            "adopted-patch-run",
            "Adopted feedback patch run",
            "pending",
            "feedback has a planner handoff, but no adopted patch run exists yet.",
            Vec::new(),
            vec![patch_plan.to_string_lossy().to_string()],
            read_json_if_exists(&recommended_path.join("feedback-patch.json"))?
                .and_then(|value| string_field(&value, "adoptPlanCommand")),
            false,
            false,
        ));
        warnings
            .push("feedback route is waiting on a strict AI patch plan and adopt-plan run".into());
    }
    Ok(())
}

fn build_demo_check_approval_route(
    recommended_run: Option<&str>,
    checks: &mut Vec<DemoCheckItem>,
    blockers: &mut Vec<String>,
    warnings: &mut Vec<String>,
) -> AppResult<()> {
    let Some(recommended_run) = recommended_run else {
        blockers.push("approval route has no recommended run".into());
        return Ok(());
    };
    let run = PathBuf::from(recommended_run);
    let approval_path = run.join("approval.json");
    let approval_value = read_json_if_exists(&approval_path)?;
    let approval_status = approval_value
        .as_ref()
        .and_then(|value| string_field(value, "status"))
        .unwrap_or_else(|| "missing".into());
    checks.push(demo_path_check(
        "approval",
        "Approval packet",
        &approval_path,
        Some(format!(
            "rs autopilot approval {} --format json",
            command_arg(recommended_run)
        )),
        false,
        false,
    ));
    if approval_status == "blocked" || approval_status == "missing" {
        warnings.push(format!("approval gate status is `{approval_status}`"));
    }
    let live_gate_path = run.join("live-gate.json");
    if live_gate_path.exists() {
        checks.push(demo_path_check(
            "live-gate",
            "Live gate packet",
            &live_gate_path,
            Some(format!(
                "rs autopilot live-gate {} --approved --format json",
                command_arg(recommended_run)
            )),
            true,
            false,
        ));
    } else {
        checks.push(demo_check_item(
            "live-gate",
            "Live gate packet",
            "notRun",
            "live-gate.json has not been generated; approval remains prepared but not crossed.",
            Vec::new(),
            vec![live_gate_path.to_string_lossy().to_string()],
            Some(format!(
                "rs autopilot live-gate {} --approved --format json",
                command_arg(recommended_run)
            )),
            true,
            false,
        ));
    }
    if run.join("apply.json").exists() {
        warnings.push(
            "apply.json exists; verify rollback, playtest, and proof before any completion claim"
                .into(),
        );
    }
    Ok(())
}

fn build_demo_check_decision_route(
    options: &DemoCheckOptions,
    checks: &mut Vec<DemoCheckItem>,
    warnings: &mut Vec<String>,
) -> AppResult<()> {
    for (id, title, relative, next) in [
        (
            "decisions",
            "Creator decision ledger",
            "decisions.json",
            Some(format!(
                "rs autopilot decision {} --decision \"<creator direction>\" --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref())
            )),
        ),
        (
            "wow-plan",
            "Refreshed wow plan",
            "wow-plan.json",
            Some(format!(
                "rs autopilot wow-plan {} --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref())
            )),
        ),
        (
            "moment-decision",
            "Revised moment decision",
            "moment-decision.json",
            Some(format!(
                "rs autopilot moment-decision {} --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref())
            )),
        ),
    ] {
        checks.push(demo_path_check(
            id,
            title,
            &options.run_dir.join(relative),
            next,
            false,
            false,
        ));
    }
    if !options.run_dir.join("moment-decision.json").exists() {
        warnings.push("creator redirection still needs a revised moment decision".into());
    }
    Ok(())
}

fn build_demo_check_response_route(
    response_run: &str,
    checks: &mut Vec<DemoCheckItem>,
    warnings: &mut Vec<String>,
) -> AppResult<()> {
    let run = PathBuf::from(response_run);
    for (id, title, relative, next) in [
        (
            "claim-check",
            "Claim check",
            "claim-check.json",
            Some(format!(
                "rs autopilot claim-check {} --claim \"<exact response claim>\" --format json",
                command_arg(response_run)
            )),
        ),
        (
            "response",
            "Creator response",
            "response.json",
            Some(format!(
                "rs autopilot respond {} --claim \"<exact response claim>\" --format json",
                command_arg(response_run)
            )),
        ),
    ] {
        checks.push(demo_path_check(
            id,
            title,
            &run.join(relative),
            next,
            false,
            false,
        ));
    }
    if !run.join("response.json").exists() {
        warnings.push("checked-response route still needs response.json before sending".into());
    }
    Ok(())
}

fn demo_path_check(
    id: &str,
    title: &str,
    path: &Path,
    next_command: Option<String>,
    requires_live_studio: bool,
    mutates_studio: bool,
) -> DemoCheckItem {
    if path.exists() {
        demo_check_item(
            id,
            title,
            "present",
            &format!("{} exists.", path.to_string_lossy()),
            vec![path.to_string_lossy().to_string()],
            Vec::new(),
            next_command,
            requires_live_studio,
            mutates_studio,
        )
    } else {
        demo_check_item(
            id,
            title,
            "missing",
            &format!("{} is missing.", path.to_string_lossy()),
            Vec::new(),
            vec![path.to_string_lossy().to_string()],
            next_command,
            requires_live_studio,
            mutates_studio,
        )
    }
}

fn demo_check_item(
    id: &str,
    title: &str,
    status: &str,
    summary: &str,
    evidence: Vec<String>,
    missing: Vec<String>,
    next_command: Option<String>,
    requires_live_studio: bool,
    mutates_studio: bool,
) -> DemoCheckItem {
    DemoCheckItem {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        summary: summary.into(),
        evidence,
        missing,
        next_command,
        requires_live_studio,
        mutates_studio,
    }
}

fn demo_check_next_actions(checks: &[DemoCheckItem]) -> Vec<CoachAction> {
    checks
        .iter()
        .filter(|check| matches!(check.status.as_str(), "missing" | "pending" | "blocked"))
        .filter_map(|check| {
            check.next_command.as_ref().map(|command| {
                coach_action(
                    1,
                    &format!("Resolve {}", check.title),
                    Some(command.clone()),
                    &check.summary,
                    check.requires_live_studio,
                    check.mutates_studio,
                )
            })
        })
        .collect()
}

fn build_demo_reply_report(
    options: &DemoReplyOptions,
    reply_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<DemoReplyReport> {
    let demo_check_path = options.run_dir.join("demo-check.json");
    let demo_check_markdown_path = if options.no_markdown {
        None
    } else {
        Some(options.run_dir.join("demo-check.md"))
    };
    let check_options = DemoCheckOptions {
        run_dir: options.run_dir.clone(),
        out: Some(demo_check_path.clone()),
        markdown: demo_check_markdown_path.clone(),
        no_markdown: options.no_markdown,
        json: false,
    };
    let demo_check = build_demo_check_report(
        &check_options,
        &demo_check_path,
        demo_check_markdown_path.as_deref(),
    )?;
    write_json(demo_check_path.clone(), &demo_check)?;
    if let Some(path) = demo_check_markdown_path.clone() {
        write_demo_check_markdown(path, &demo_check)?;
    }

    let checked_claims = build_demo_reply_claims(&demo_check);
    let claim_check_path = options.run_dir.join("demo-reply-claim-check.json");
    let claim_check_markdown_path =
        (!options.no_markdown).then(|| options.run_dir.join("demo-reply-claim-check.md"));
    let claim_options = ClaimCheckOptions {
        run_dir: options.run_dir.clone(),
        claims: checked_claims.clone(),
        out: Some(claim_check_path.clone()),
        markdown: claim_check_markdown_path.clone(),
        no_markdown: options.no_markdown,
        json: false,
    };
    let claim_check = build_claim_check_report(
        &claim_options,
        &claim_check_path,
        claim_check_markdown_path.as_deref(),
    )?;
    write_json(claim_check_path.clone(), &claim_check)?;
    if let Some(path) = claim_check_markdown_path.clone() {
        write_claim_check_markdown(path, &claim_check)?;
    }

    let status = if !demo_check.blockers.is_empty() || !claim_check.blockers.is_empty() {
        "blocked"
    } else if claim_check.status == "readyToSay" {
        "readyToSend"
    } else {
        "needsRewrite"
    };
    let verdict = match status {
        "readyToSend" => "creatorDemoReplyReady",
        "needsRewrite" => "rewriteBeforeSending",
        _ => "replyBlocked",
    };
    let mut blockers = demo_check.blockers.clone();
    blockers.extend(claim_check.blockers.clone());
    if status == "needsRewrite" {
        blockers.push(
            "demo-reply claim check reported risky claims; rewrite using safe-to-say wording"
                .into(),
        );
    }
    blockers.sort();
    blockers.dedup();
    let mut warnings = demo_check.warnings.clone();
    warnings.extend(claim_check.warnings.clone());
    warnings.sort();
    warnings.dedup();
    let mut safe_to_say = demo_check.safe_to_say.clone();
    safe_to_say.extend(claim_check.safe_to_say.clone());
    safe_to_say.sort();
    safe_to_say.dedup();
    let mut do_not_say = demo_check.do_not_say.clone();
    do_not_say.extend(claim_check.do_not_say.clone());
    do_not_say.sort();
    do_not_say.dedup();

    let mut artifacts = demo_check.artifacts.clone();
    artifacts.extend(claim_check.artifacts.clone());
    artifacts.insert("demoReply".into(), reply_path.to_string_lossy().to_string());
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "demoReplyMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert(
        "demoReplyClaimCheck".into(),
        claim_check_path.to_string_lossy().to_string(),
    );
    if let Some(path) = &claim_check_markdown_path {
        artifacts.insert(
            "demoReplyClaimCheckMarkdown".into(),
            path.to_string_lossy().to_string(),
        );
    }

    let mut next_actions = Vec::new();
    if status == "readyToSend" {
        next_actions.push(coach_action(
            8,
            "Refresh demo reply if wording changes",
            Some(format!(
                "rs autopilot demo-reply {} --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref())
            )),
            "The reply is safe only for the checked claims in this artifact.",
            false,
            false,
        ));
    } else if !demo_check.blockers.is_empty() {
        next_actions.extend(demo_check.next_actions.clone());
    } else {
        next_actions.extend(claim_check.next_actions.clone());
    }
    next_actions.extend(demo_check.next_actions.iter().take(4).cloned());
    dedup_next_actions(&mut next_actions);

    let message = build_demo_reply_message(&demo_check, &claim_check, status);
    let agent_brief = format!(
        "Demo reply is {status}: route `{}` with demo-check `{}` and claim-check `{}`. Send only when status is readyToSend.",
        demo_check.route, demo_check.status, claim_check.status
    );

    Ok(DemoReplyReport {
        schema_version: "rs.autopilot.demo-reply.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        reply_path: reply_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        demo_check_path: demo_check.check_path.clone(),
        claim_check_path: claim_check.claim_check_path.clone(),
        status: status.into(),
        verdict: verdict.into(),
        route: demo_check.route.clone(),
        demo_check_status: demo_check.status.clone(),
        message,
        checked_claims,
        safe_to_say,
        do_not_say,
        artifacts,
        blockers,
        warnings,
        next_actions,
        agent_brief,
        demo_check,
        claim_check,
    })
}

fn build_demo_reply_claims(demo_check: &DemoCheckReport) -> Vec<String> {
    let mut claims = demo_check
        .safe_to_say
        .iter()
        .take(2)
        .cloned()
        .collect::<Vec<_>>();
    if claims.is_empty() {
        claims.push("Post-demo follow-up was checked against local artifacts.".into());
    }
    claims.sort();
    claims.dedup();
    claims
}

fn build_demo_reply_message(
    demo_check: &DemoCheckReport,
    claim_check: &ClaimCheckReport,
    status: &str,
) -> String {
    if status != "readyToSend" {
        let mut lines = vec![
            "I cannot send a post-demo update yet because the checked artifacts do not support a safe reply.".to_string(),
        ];
        for blocker in demo_check
            .blockers
            .iter()
            .chain(claim_check.blockers.iter())
        {
            lines.push(format!("Blocker: {blocker}"));
        }
        if let Some(action) = demo_check.next_actions.first() {
            lines.push(format!("Next safe step: {}.", action.title));
            if let Some(command) = &action.command {
                lines.push(format!("Run `{command}`."));
            }
        }
        return lines.join("\n\n");
    }

    let safe_claim = demo_check
        .safe_to_say
        .first()
        .cloned()
        .unwrap_or_else(|| "I checked the local post-demo artifacts.".into());
    let mut lines = Vec::new();
    match demo_check.route.as_str() {
        "feedbackPatch" => {
            if demo_check.status == "readyForNextDemo" {
                lines.push("I checked the post-demo feedback follow-through. The local artifacts are ready for the next revised demo.".into());
            } else {
                lines.push("I routed your feedback into the next patch handoff. It is not implemented yet, so I will not claim the game changed until the patch run is adopted, certified, compared, and demo evidence is refreshed.".into());
            }
        }
        "approvalGate" => {
            lines.push("I prepared the approval gate from your demo response. I have not applied anything to Studio from that chat wording.".into());
        }
        "decisionOrNewWow" => {
            lines.push("I recorded the new direction from your demo response and will use it to revise the next wow plan. I am not treating that direction as live Studio approval.".into());
        }
        "checkedResponse" => {
            lines.push("I checked the evidence for the reply and can answer using the supported wording from the claim check.".into());
        }
        _ => {
            lines.push("I checked the post-demo state and found that the next safe reply still depends on the listed artifacts.".into());
        }
    }
    lines.push(format!("Safe checked claim: {safe_claim}"));
    if let Some(action) = demo_check.next_actions.first() {
        let command = action
            .command
            .as_ref()
            .map(|command| format!(" Run `{command}`."))
            .unwrap_or_default();
        lines.push(format!("Next safe step: {}.{}", action.title, command));
    }
    lines.push(
        "I am not claiming live Studio apply, publishing, upload, playtest success, rollback readiness, or production readiness unless those have separate artifacts."
            .into(),
    );
    lines.join("\n\n")
}

fn build_demo_learn_report(
    options: &DemoLearnOptions,
    learn_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<DemoLearnReport> {
    let reply_path = options.run_dir.join("demo-reply.json");
    let reply_markdown_path = (!options.no_markdown).then(|| options.run_dir.join("demo-reply.md"));
    let reply_options = DemoReplyOptions {
        run_dir: options.run_dir.clone(),
        out: Some(reply_path.clone()),
        markdown: reply_markdown_path.clone(),
        no_markdown: options.no_markdown,
        json: false,
    };
    let demo_reply =
        build_demo_reply_report(&reply_options, &reply_path, reply_markdown_path.as_deref())?;
    write_json(reply_path.clone(), &demo_reply)?;
    if let Some(path) = reply_markdown_path {
        write_demo_reply_markdown(path, &demo_reply)?;
    }

    let response_value = read_json_if_exists(&options.run_dir.join("demo-response.json"))?;
    let messages = response_value
        .as_ref()
        .map(|value| string_array_field(value, "messages"))
        .unwrap_or_default();
    let route = demo_reply.route.clone();
    let mut artifacts = demo_reply.artifacts.clone();
    artifacts.insert("demoLearn".into(), learn_path.to_string_lossy().to_string());
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "demoLearnMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    let mut creator_signals = build_demo_learn_signals(&options.run_dir, &route, &messages);
    let mut learned_preferences = build_demo_learn_preferences(&route, &messages);
    let mut constraints = build_demo_learn_constraints(&route, &messages);
    let mut follow_up_themes = build_demo_learn_themes(&route, &messages);
    if route == "approvalGate" {
        learned_preferences.push(
            "Creator responded positively to the demonstrated direction, but this is not live apply approval."
                .into(),
        );
    }
    if route == "decisionOrNewWow" {
        constraints.push(
            "Creator redirected the demo direction; update future wow planning before continuing."
                .into(),
        );
    }
    learned_preferences.sort();
    learned_preferences.dedup();
    constraints.sort();
    constraints.dedup();
    follow_up_themes.sort();
    follow_up_themes.dedup();
    creator_signals.sort_by(|left, right| left.id.cmp(&right.id));

    let mut blockers = Vec::new();
    if response_value.is_none() || messages.is_empty() {
        blockers
            .push("demo-learn needs demo-response.json with at least one creator message".into());
    }
    let mut warnings = demo_reply.warnings.clone();
    if demo_reply.status != "readyToSend" {
        warnings.push(format!(
            "demo-reply status is {}; learning is guidance only until reply blockers are resolved",
            demo_reply.status
        ));
    }
    warnings.sort();
    warnings.dedup();
    let status = if !blockers.is_empty() {
        "blocked"
    } else if creator_signals.is_empty() {
        "needsReview"
    } else {
        "ready"
    };
    let root = options
        .run_dir
        .parent()
        .map(Path::to_path_buf)
        .unwrap_or_else(|| PathBuf::from(".rs\\autopilot\\runs"));
    let root_arg = command_arg(root.to_string_lossy().as_ref());
    let recommended_memory_actions = vec![
        "Review learned preferences before changing future wow candidates.".into(),
        "Record durable creator decisions separately when the signal is a constraint or rejection."
            .into(),
        "Refresh project memory, game bible, and playbook before a fresh AI session continues."
            .into(),
    ];
    let mut next_actions = vec![
        coach_action(
            3,
            "Consolidate remembered context",
            Some(format!(
                "rs autopilot remember {} --root {root_arg} --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref())
            )),
            "Refresh demo learning, creator preferences, project memory, game bible, and playbook in one receipt.",
            false,
            false,
        ),
        coach_action(
            4,
            "Refresh creator preferences",
            Some(format!(
                "rs autopilot preferences --root {root_arg} --format json"
            )),
            "Fold repeated creator feedback themes into cross-run planning guidance.",
            false,
            false,
        ),
        coach_action(
            5,
            "Refresh project memory",
            Some(format!(
                "rs autopilot memory --root {root_arg} --format json"
            )),
            "Make the post-demo learning visible to future AI sessions.",
            false,
            false,
        ),
        coach_action(
            6,
            "Refresh AI playbook",
            Some(format!(
                "rs autopilot playbook --root {root_arg} --format json"
            )),
            "Update the model-facing operating habits after the demo conversation.",
            false,
            false,
        ),
    ];
    if let Some(first_constraint) = constraints.first() {
        next_actions.push(coach_action(
            2,
            "Record durable creator decision",
            Some(format!(
                "rs autopilot decision {} --note {} --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref()),
                command_arg(first_constraint)
            )),
            "Constraints and redirections should be preserved in decisions.json before future planning.",
            false,
            false,
        ));
    }
    dedup_next_actions(&mut next_actions);
    let safe_to_say = vec![
        "Demo learning summarized local post-demo artifacts and did not mutate Studio.".into(),
        "Creator reaction signals are planning guidance until recorded or implemented by a later run.".into(),
    ];
    let do_not_say = vec![
        "Do not claim demo-learn updated persistent creator preferences by itself.".into(),
        "Do not claim feedback was implemented, approved, applied, playtested, published, or production-ready from demo-learn.".into(),
    ];
    let agent_brief = format!(
        "Demo learning is {status}: route `{route}` produced {} signal(s), {} learned preference(s), and {} constraint(s). Use it to update future planning, not as proof of implementation.",
        creator_signals.len(),
        learned_preferences.len(),
        constraints.len()
    );

    Ok(DemoLearnReport {
        schema_version: "rs.autopilot.demo-learn.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        learn_path: learn_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status: status.into(),
        route,
        demo_check_status: demo_reply.demo_check_status.clone(),
        signal_count: creator_signals.len(),
        creator_signals,
        learned_preferences,
        constraints,
        follow_up_themes,
        recommended_memory_actions,
        safe_to_say,
        do_not_say,
        artifacts,
        blockers,
        warnings,
        next_actions,
        agent_brief,
        demo_reply,
    })
}

fn build_demo_learn_signals(
    run_dir: &Path,
    route: &str,
    messages: &[String],
) -> Vec<DemoLearnSignal> {
    let mut signals = Vec::new();
    for (index, message) in messages.iter().enumerate() {
        let (category, hits) = feedback_category_for_note(message);
        let kind = match route {
            "feedbackPatch" => format!("feedback:{category}"),
            "approvalGate" => "approvalGate".into(),
            "decisionOrNewWow" => "redirection".into(),
            "checkedResponse" => "question".into(),
            _ => "postDemo".into(),
        };
        let title = match route {
            "feedbackPatch" => format!("Creator feedback: {category}"),
            "approvalGate" => "Creator liked the demo direction".into(),
            "decisionOrNewWow" => "Creator redirected the demo direction".into(),
            "checkedResponse" => "Creator asked for a checked reply".into(),
            _ => "Creator post-demo signal".into(),
        };
        let summary = format!("`{}` was routed as `{route}`.", redact_text(message));
        signals.push(DemoLearnSignal {
            id: format!("demo-signal-{:02}", index + 1),
            kind,
            title,
            summary,
            evidence: vec![
                run_dir
                    .join("demo-response.json")
                    .to_string_lossy()
                    .to_string(),
                run_dir
                    .join("demo-check.json")
                    .to_string_lossy()
                    .to_string(),
            ],
            confidence: if hits > 0 { 0.82 } else { 0.64 },
            next_command: Some(format!(
                "rs autopilot demo-learn {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        });
    }
    signals
}

fn build_demo_learn_preferences(route: &str, messages: &[String]) -> Vec<String> {
    messages
        .iter()
        .filter_map(|message| {
            let (category, hits) = feedback_category_for_note(message);
            if route == "feedbackPatch" && hits > 0 {
                Some(format!(
                    "Creator cares about `{category}` polish in demo follow-up: {}",
                    redact_text(message)
                ))
            } else if route == "checkedResponse" {
                Some(format!(
                    "Creator expects evidence-backed answers after demos: {}",
                    redact_text(message)
                ))
            } else {
                None
            }
        })
        .collect()
}

fn build_demo_learn_constraints(route: &str, messages: &[String]) -> Vec<String> {
    messages
        .iter()
        .filter_map(|message| {
            let lower = message.to_ascii_lowercase();
            let constraint_like = text_contains_any(
                &lower,
                &[
                    "don't", "do not", "instead", "avoid", "keep", "must", "not this",
                ],
            );
            if route == "decisionOrNewWow" || constraint_like {
                Some(format!(
                    "Post-demo constraint signal: {}",
                    redact_text(message)
                ))
            } else {
                None
            }
        })
        .collect()
}

fn build_demo_learn_themes(route: &str, messages: &[String]) -> Vec<String> {
    let mut themes = Vec::new();
    for message in messages {
        let (category, hits) = feedback_category_for_note(message);
        if hits > 0 {
            themes.push(category);
        }
    }
    if route == "approvalGate" {
        themes.push("approval-boundary".into());
    }
    if route == "decisionOrNewWow" {
        themes.push("direction-change".into());
    }
    if route == "checkedResponse" {
        themes.push("evidence-backed-answer".into());
    }
    themes
}

fn build_remember_report(
    options: &RememberOptions,
    remember_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<RememberReport> {
    let context_dir = remember_context_dir(&options.root);
    std::fs::create_dir_all(&context_dir)?;
    let write_markdown = markdown_path.is_some();

    let demo_learn_path = options.run_dir.join("demo-learn.json");
    let demo_learn_markdown_path = options.run_dir.join("demo-learn.md");
    let demo_learn_markdown = write_markdown.then_some(demo_learn_markdown_path.as_path());
    let demo_learn_options = DemoLearnOptions {
        run_dir: options.run_dir.clone(),
        out: Some(demo_learn_path.clone()),
        markdown: write_markdown.then_some(demo_learn_markdown_path.clone()),
        no_markdown: !write_markdown,
        json: false,
    };
    let demo_learn =
        build_demo_learn_report(&demo_learn_options, &demo_learn_path, demo_learn_markdown)?;
    write_json(demo_learn_path.clone(), &demo_learn)?;
    if write_markdown {
        write_demo_learn_markdown(demo_learn_markdown_path.clone(), &demo_learn)?;
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;
    refresh_project_run_bundles_if_possible(&options.root)?;

    let memory_path = context_dir.join("project-memory.json");
    let memory_markdown_path = context_dir.join("project-memory.md");
    let memory_markdown = write_markdown.then_some(memory_markdown_path.as_path());
    let memory = build_memory_report(&options.root, options.limit, &memory_path, memory_markdown)?;
    write_json(memory_path.clone(), &memory)?;
    if write_markdown {
        write_memory_markdown(memory_markdown_path.clone(), &memory)?;
    }

    let preferences_path = context_dir.join("creator-preferences.json");
    let preferences_markdown_path = context_dir.join("creator-preferences.md");
    let preferences_markdown = write_markdown.then_some(preferences_markdown_path.as_path());
    let preferences = build_preferences_report(
        &options.root,
        options.limit,
        &preferences_path,
        preferences_markdown,
    )?;
    write_json(preferences_path.clone(), &preferences)?;
    if write_markdown {
        write_preferences_markdown(preferences_markdown_path.clone(), &preferences)?;
    }

    let game_bible_path = context_dir.join("game-bible.json");
    let game_bible_markdown_path = context_dir.join("game-bible.md");
    let game_bible_markdown = write_markdown.then_some(game_bible_markdown_path.as_path());
    let game_bible = build_game_bible_report(
        &options.root,
        options.limit,
        &game_bible_path,
        game_bible_markdown,
    )?;
    write_json(game_bible_path.clone(), &game_bible)?;
    if write_markdown {
        write_game_bible_markdown(game_bible_markdown_path.clone(), &game_bible)?;
    }

    let playbook_path = context_dir.join("ai-playbook.json");
    let playbook_markdown_path = context_dir.join("ai-playbook.md");
    let playbook_markdown = write_markdown.then_some(playbook_markdown_path.as_path());
    let playbook = build_playbook_report(
        &options.root,
        options.limit,
        &playbook_path,
        playbook_markdown,
    )?;
    write_json(playbook_path.clone(), &playbook)?;
    if write_markdown {
        write_playbook_markdown(playbook_markdown_path.clone(), &playbook)?;
    }

    let mut artifacts = BTreeMap::from([
        (
            "remember".into(),
            remember_path.to_string_lossy().to_string(),
        ),
        ("demoLearn".into(), demo_learn.learn_path.clone()),
        ("memory".into(), memory.memory_path.clone()),
        (
            "creatorPreferences".into(),
            preferences.preferences_path.clone(),
        ),
        ("gameBible".into(), game_bible.game_bible_path.clone()),
        ("aiPlaybook".into(), playbook.playbook_path.clone()),
    ]);
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "rememberMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    if let Some(path) = &demo_learn.markdown_path {
        artifacts.insert("demoLearnMarkdown".into(), path.clone());
    }
    if write_markdown {
        artifacts.insert(
            "memoryMarkdown".into(),
            memory_markdown_path.to_string_lossy().to_string(),
        );
        artifacts.insert(
            "creatorPreferencesMarkdown".into(),
            preferences_markdown_path.to_string_lossy().to_string(),
        );
        artifacts.insert(
            "gameBibleMarkdown".into(),
            game_bible_markdown_path.to_string_lossy().to_string(),
        );
        artifacts.insert(
            "aiPlaybookMarkdown".into(),
            playbook_markdown_path.to_string_lossy().to_string(),
        );
    }

    let memory_markdown_string =
        write_markdown.then(|| memory_markdown_path.to_string_lossy().to_string());
    let preferences_markdown_string =
        write_markdown.then(|| preferences_markdown_path.to_string_lossy().to_string());
    let game_bible_markdown_string =
        write_markdown.then(|| game_bible_markdown_path.to_string_lossy().to_string());
    let playbook_markdown_string =
        write_markdown.then(|| playbook_markdown_path.to_string_lossy().to_string());
    let consolidated_artifacts = vec![
        remember_artifact(
            "demoLearn",
            "Demo Learning",
            &demo_learn.learn_path,
            demo_learn.markdown_path.as_deref(),
            &demo_learn.status,
            "Fresh post-demo taste, constraint, and follow-up signals.",
        ),
        remember_artifact(
            "memory",
            "Project Memory",
            &memory.memory_path,
            memory_markdown_string.as_deref(),
            if memory.returned == 0 {
                "needsRuns"
            } else {
                "ready"
            },
            "Cross-run summary and active run continuity.",
        ),
        remember_artifact(
            "creatorPreferences",
            "Creator Preferences",
            &preferences.preferences_path,
            preferences_markdown_string.as_deref(),
            &preferences.status,
            "Durable taste, constraints, rejections, and feedback themes.",
        ),
        remember_artifact(
            "gameBible",
            "Game Bible",
            &game_bible.game_bible_path,
            game_bible_markdown_string.as_deref(),
            &game_bible.status,
            "Project canon, player promise, systems, and continuity rules.",
        ),
        remember_artifact(
            "aiPlaybook",
            "AI Playbook",
            &playbook.playbook_path,
            playbook_markdown_string.as_deref(),
            &playbook.status,
            "Model-facing operating habits, guardrails, and next workflow.",
        ),
    ];

    let demo_learning_missing_response = !demo_learn.blockers.is_empty()
        && demo_learn
            .blockers
            .iter()
            .all(|blocker| blocker.contains("demo-response.json"));
    let mut blockers = Vec::new();
    if !demo_learning_missing_response {
        blockers.extend(
            demo_learn
                .blockers
                .iter()
                .map(|blocker| format!("demo-learn: {blocker}")),
        );
    }
    blockers.extend(
        memory
            .blockers
            .iter()
            .map(|blocker| format!("memory: {blocker}")),
    );
    blockers.extend(
        preferences
            .blockers
            .iter()
            .map(|blocker| format!("preferences: {blocker}")),
    );
    blockers.extend(
        game_bible
            .blockers
            .iter()
            .map(|blocker| format!("game-bible: {blocker}")),
    );
    blockers.extend(
        playbook
            .blockers
            .iter()
            .map(|blocker| format!("playbook: {blocker}")),
    );

    let mut warnings = merge_many_sorted(vec![
        demo_learn
            .warnings
            .iter()
            .map(|warning| format!("demo-learn: {warning}"))
            .collect(),
        memory
            .warnings
            .iter()
            .map(|warning| format!("memory: {warning}"))
            .collect(),
        preferences
            .warnings
            .iter()
            .map(|warning| format!("preferences: {warning}"))
            .collect(),
        game_bible
            .warnings
            .iter()
            .map(|warning| format!("game-bible: {warning}"))
            .collect(),
        playbook
            .warnings
            .iter()
            .map(|warning| format!("playbook: {warning}"))
            .collect(),
    ]);
    warnings.push(
        "remember consolidates guidance artifacts only; it does not mutate Studio or implement feedback."
            .into(),
    );
    if demo_learning_missing_response {
        warnings.push(
            "demo-learn: no post-demo response exists yet; remember refreshed baseline context without demo taste signals"
                .into(),
        );
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let mut memory_actions = demo_learn.recommended_memory_actions.clone();
    memory_actions.extend([
        "Refreshed project-memory.json for cross-run continuity.".into(),
        "Refreshed creator-preferences.json so demo learning can guide future planning.".into(),
        "Refreshed game-bible.json so canon can absorb current preferences and memory.".into(),
        "Refreshed ai-playbook.json so the next AI session inherits the operating context.".into(),
    ]);
    memory_actions.sort();
    memory_actions.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else if demo_learn.status != "ready" && !demo_learning_missing_response {
        "needsDemoLearning"
    } else if playbook.status == "ready" {
        if demo_learning_missing_response {
            "readyWithWarnings"
        } else {
            "ready"
        }
    } else {
        "readyWithWarnings"
    }
    .to_string();
    let safe_to_say = if blockers.is_empty() && demo_learning_missing_response {
        vec![
            "Remember refreshed project memory, preferences, game bible, and AI playbook without post-demo learning because no demo response exists yet.".into(),
        ]
    } else if blockers.is_empty() {
        vec![format!(
            "Remember consolidated {} demo signal(s) into refreshed memory, preferences, game bible, and AI playbook artifacts.",
            demo_learn.signal_count
        )]
    } else {
        vec!["Remember wrote a consolidation receipt, but blockers must be resolved before using it as current AI context.".into()]
    };
    let do_not_say = vec![
        "Do not claim remember implemented creator feedback or changed Studio.".into(),
        "Do not claim remember proves live apply, playtest success, rollback readiness, publish readiness, or production readiness.".into(),
        "Do not treat remembered preferences, canon, or playbook guidance as creator approval.".into(),
    ];
    let root_arg = command_arg(options.root.to_string_lossy().as_ref());
    let run_arg = command_arg(options.run_dir.to_string_lossy().as_ref());
    let mut next_actions = vec![
        coach_action(
            1,
            "Launch next AI best-friend packet",
            Some(format!(
                "rs autopilot best-friend {run_arg} --root {root_arg} --limit {} --format json",
                options.limit
            )),
            "Turn refreshed memory, preferences, canon, and playbook context into one checked launch packet for the next AI.",
            false,
            false,
        ),
        coach_action(
            2,
            "Orient next AI with remembered context",
            Some(format!(
                "rs autopilot orient --run-dir {run_arg} --root {root_arg} --limit {} --format json",
                options.limit
            )),
            "Load the refreshed project context before planning, acting, or reporting.",
            false,
            false,
        ),
        coach_action(
            3,
            "Open the refreshed AI playbook",
            Some(format!(
                "rs autopilot playbook --root {root_arg} --limit {} --format json",
                options.limit
            )),
            "Review operating habits and claim boundaries before continuing.",
            false,
            false,
        ),
    ];
    if demo_learn.status != "ready" {
        next_actions.push(coach_action(
            0,
            "Resolve demo learning blockers",
            Some(format!("rs autopilot demo-learn {run_arg} --format json")),
            "Refresh the checked post-demo learning packet before treating preferences as current.",
            false,
            false,
        ));
    }
    dedup_next_actions(&mut next_actions);
    let agent_brief = format!(
        "Remember status {status}: demo learning `{}` with {} signal(s) refreshed project memory, creator preferences, game bible, and AI playbook under {}. Use these as planning context only; the next default continuation is `rs autopilot best-friend`.",
        demo_learn.status,
        demo_learn.signal_count,
        context_dir.to_string_lossy()
    );

    Ok(RememberReport {
        schema_version: "rs.autopilot.remember.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        root: options.root.to_string_lossy().to_string(),
        context_dir: context_dir.to_string_lossy().to_string(),
        remember_path: remember_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        demo_learn_status: demo_learn.status.clone(),
        learned_signal_count: demo_learn.signal_count,
        best_friend_status: None,
        best_friend_path: None,
        best_friend_markdown_path: None,
        consolidated_artifacts,
        memory_actions,
        safe_to_say,
        do_not_say,
        artifacts,
        blockers,
        warnings,
        next_actions,
        agent_brief,
        demo_learn,
    })
}

fn remember_context_dir(root: &Path) -> PathBuf {
    if root.file_name().and_then(|name| name.to_str()) == Some("runs") {
        root.parent()
            .map(Path::to_path_buf)
            .unwrap_or_else(|| root.to_path_buf())
    } else {
        root.to_path_buf()
    }
}

fn remember_artifact(
    id: &str,
    title: &str,
    path: &str,
    markdown_path: Option<&str>,
    status: &str,
    reason: &str,
) -> RememberArtifact {
    RememberArtifact {
        id: id.into(),
        title: title.into(),
        path: path.into(),
        markdown_path: markdown_path.map(str::to_string),
        status: status.into(),
        reason: reason.into(),
    }
}

fn build_navigator_first_safe_action(
    run_dir: Option<&Path>,
    runbook_value: Option<&Value>,
    fallback: Option<&CoachAction>,
) -> Option<CoachAction> {
    if let Some(step) = runbook_value
        .and_then(|value| value.get("safePrefix"))
        .and_then(Value::as_array)
        .and_then(|steps| steps.first())
    {
        if let Some(command) = step.get("command").and_then(Value::as_str) {
            return Some(coach_action(
                1,
                "Execute first runbook safe-prefix step",
                Some(command.to_string()),
                "Run exactly one reviewed offline step, then refresh navigator before continuing.",
                false,
                false,
            ));
        }
    }
    if let Some(action) = fallback {
        if !action.requires_live_studio && !action.mutates_studio {
            return Some(action.clone());
        }
    }
    if let Some(run_dir) = run_dir {
        return Some(coach_action(
            1,
            "Refresh execution runbook",
            Some(format!(
                "rs autopilot runbook --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Rebuild the safe prefix before choosing a command.",
            false,
            false,
        ));
    }
    None
}

fn build_navigator_situation(
    artifacts: &BTreeMap<String, String>,
    orientation: &OrientReport,
    runbook_value: Option<&Value>,
    flight_value: Option<&Value>,
) -> Vec<NavigatorSignal> {
    let mut signals = vec![NavigatorSignal {
        id: "orientation".into(),
        title: "Orientation".into(),
        status: orientation.status.clone(),
        verdict: Some(orientation.session_mode.clone()),
        summary: orientation.agent_brief.clone(),
        path: Some(orientation.orientation_path.clone()),
    }];
    for (id, title) in [
        ("runbook", "Execution Runbook"),
        ("flightRecorder", "Flight Recorder"),
        ("commandGuard", "Command Guard"),
        ("proof", "Proof Ledger"),
        ("acceptance", "Acceptance Scorecard"),
        ("privacy", "Privacy Scan"),
    ] {
        if let Some(path) = artifacts.get(id) {
            let value = if id == "runbook" {
                runbook_value.cloned()
            } else if id == "flightRecorder" {
                flight_value.cloned()
            } else {
                read_json_if_exists(Path::new(path)).ok().flatten()
            };
            signals.push(navigator_signal_from_value(id, title, path, value.as_ref()));
        }
    }
    signals
}

fn navigator_signal_from_value(
    id: &str,
    title: &str,
    path: &str,
    value: Option<&Value>,
) -> NavigatorSignal {
    NavigatorSignal {
        id: id.into(),
        title: title.into(),
        status: value
            .and_then(|value| string_field(value, "status"))
            .unwrap_or_else(|| "present".into()),
        verdict: value.and_then(|value| string_field(value, "verdict")),
        summary: value
            .and_then(|value| string_field(value, "agentBrief"))
            .or_else(|| value.and_then(|value| string_field(value, "summary")))
            .unwrap_or_else(|| format!("{title} artifact is present.")),
        path: Some(path.into()),
    }
}

fn build_navigator_stop_conditions(runbook_value: Option<&Value>) -> Vec<String> {
    let mut conditions = runbook_value
        .and_then(|value| value.get("stopConditions"))
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(Value::as_str)
                .map(str::to_string)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    conditions.extend([
        "Stop after one safe action and refresh navigator before the next action.".to_string(),
        "Stop before live Studio, apply, publish, upload, or setup commands unless approval and readiness artifacts are current.".to_string(),
        "Stop before creator-facing claims that are not present in safeToSay or proof artifacts.".to_string(),
    ]);
    conditions.sort();
    conditions.dedup();
    conditions
}

fn build_navigator_agent_brief(
    status: &str,
    next_command: Option<&str>,
    first_safe_action: Option<&CoachAction>,
    situation: &[NavigatorSignal],
) -> String {
    match status {
        "readyToAct" => format!(
            "Navigator is ready. Read the required items, run one safe action (`{}`), then refresh navigator before reporting or continuing.",
            first_safe_action
                .and_then(|action| action.command.as_deref())
                .or(next_command)
                .unwrap_or("<missing>")
        ),
        "readyWithGates" => format!(
            "Navigator found the next command but it crosses a gate. Read {} situation signal(s), then complete approval/readiness/proof before live or mutating work.",
            situation.len()
        ),
        "needsRun" => {
            "Navigator needs a run. Start from the orientation next command before claiming project progress.".into()
        }
        "blocked" => {
            "Navigator is blocked. Resolve blockers from orientation, runbook, or flight-recorder before acting or reporting success.".into()
        }
        _ => "Navigator is ready for handoff. Read the card, proof, and recorder before responding.".into(),
    }
}

fn build_advance_report(
    options: &AdvanceOptions,
    advance_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<AdvanceReport> {
    if !options.run_dir.is_dir() {
        return Err(AppError::Other(format!(
            "autopilot advance run directory does not exist: {}",
            options.run_dir.display()
        )));
    }
    let before_path = options.run_dir.join("advance-navigator-before.json");
    let before_nav = build_navigator_report(
        &NavigatorOptions {
            prompt: None,
            run_dir: Some(options.run_dir.clone()),
            root: options.root.clone(),
            limit: options.limit,
            out: Some(before_path.clone()),
            markdown: None,
            no_markdown: true,
            json: false,
        },
        &before_path,
        None,
    )?;
    write_json(before_path.clone(), &before_nav)?;

    let selected_action = before_nav.first_safe_action.clone();
    let selected_command = selected_action
        .as_ref()
        .and_then(|action| action.command.clone());
    let mut selected_inner_command = None;
    let mut blockers = Vec::new();
    let mut warnings = before_nav.warnings.clone();
    let mut act_report = None;
    let mut executed = false;

    if before_nav.status == "blocked" {
        blockers.push("navigator is blocked; advance will not execute a safe action".into());
    }
    let parsed_inner = selected_command
        .as_deref()
        .and_then(extract_act_wrapper_inner_command);
    if selected_command.is_none() {
        blockers.push("navigator did not provide a first safe action command".into());
    } else if parsed_inner.is_none() {
        blockers.push(
            "navigator first safe action is not an `rs autopilot act --command ...` wrapper".into(),
        );
    }
    if let Some(inner) = parsed_inner {
        if let Some(reason) = act_refusal_reason(&inner) {
            blockers.push(format!("navigator inner action refused by act: {reason}"));
        } else {
            selected_inner_command = Some(inner.clone());
            if options.dry_run {
                warnings.push("advance dry-run selected the action without executing it".into());
            } else {
                let act_path = options.run_dir.join("act.json");
                let act_markdown_path =
                    (!options.no_markdown).then(|| options.run_dir.join("act.md"));
                let act_options = ActOptions {
                    run_dir: options.run_dir.clone(),
                    command: Some(inner),
                    source: "navigator".into(),
                    root: options.root.clone(),
                    limit: options.limit,
                    dry_run: false,
                    out: Some(act_path.clone()),
                    markdown: act_markdown_path.clone(),
                    no_markdown: options.no_markdown,
                    json: false,
                };
                let report =
                    build_act_report(&act_options, &act_path, act_markdown_path.as_deref())?;
                write_json(act_path.clone(), &report)?;
                if let Some(path) = act_markdown_path {
                    write_act_markdown(path, &report)?;
                }
                executed = report.executed && report.status == "executed";
                if !executed {
                    blockers.extend(
                        report
                            .blockers
                            .iter()
                            .map(|blocker| format!("act: {blocker}")),
                    );
                }
                act_report = Some(report);
            }
        }
    }

    let after_path = options.run_dir.join("navigator.json");
    let after_markdown_path = (!options.no_markdown).then(|| options.run_dir.join("navigator.md"));
    let after_nav = build_navigator_report(
        &NavigatorOptions {
            prompt: None,
            run_dir: Some(options.run_dir.clone()),
            root: options.root.clone(),
            limit: options.limit,
            out: Some(after_path.clone()),
            markdown: after_markdown_path.clone(),
            no_markdown: options.no_markdown,
            json: false,
        },
        &after_path,
        after_markdown_path.as_deref(),
    )?;
    write_json(after_path.clone(), &after_nav)?;
    if let Some(path) = after_markdown_path {
        write_navigator_markdown(path, &after_nav)?;
    }

    let status = if !blockers.is_empty() {
        if act_report.as_ref().is_some_and(|report| report.executed) {
            "failed"
        } else {
            "blocked"
        }
    } else if options.dry_run {
        "dryRun"
    } else if executed {
        "advanced"
    } else {
        "blocked"
    }
    .to_string();
    let verdict = match status.as_str() {
        "advanced" => "navigatorSafeActionExecuted",
        "dryRun" => "navigatorSafeActionSelected",
        "blocked" => "navigatorActionBlocked",
        _ => "navigatorActionFailed",
    }
    .to_string();

    warnings.sort();
    warnings.dedup();
    blockers.sort();
    blockers.dedup();
    let mut artifacts = collect_planner_run_artifacts(Some(&options.run_dir));
    artifacts.insert("advance".into(), advance_path.to_string_lossy().to_string());
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "advanceMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    artifacts.insert(
        "beforeNavigator".into(),
        before_path.to_string_lossy().to_string(),
    );
    artifacts.insert("navigator".into(), after_path.to_string_lossy().to_string());
    let act_status = act_report.as_ref().map(|report| report.status.clone());
    let act_path = act_report.as_ref().map(|report| report.act_path.clone());
    let safe_to_say = if executed {
        vec![
            "Autopilot advance executed one navigator-selected safe offline act action.".into(),
            "Advance refreshed the navigator after the action.".into(),
        ]
    } else if options.dry_run {
        vec!["Autopilot advance selected one navigator safe action without executing it.".into()]
    } else {
        vec!["Autopilot advance did not execute an action.".into()]
    };
    let do_not_say = vec![
        "Do not claim advance applied, published, playtested, uploaded, or mutated Studio.".into(),
        "Do not claim completion until proof, acceptance, and claim-check support the exact wording.".into(),
        "Do not execute more than one step from an advance receipt without refreshing navigator.".into(),
    ];
    let next_actions = build_advance_next_actions(&options.run_dir, &status, &after_nav);
    let agent_brief = build_advance_agent_brief(&status, selected_inner_command.as_deref());

    Ok(AdvanceReport {
        schema_version: "rs.autopilot.advance.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        advance_path: advance_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict,
        dry_run: options.dry_run,
        before_navigator_path: before_path.to_string_lossy().to_string(),
        after_navigator_path: after_path.to_string_lossy().to_string(),
        selected_action,
        selected_command,
        selected_inner_command,
        act_status,
        act_path,
        executed,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        artifacts,
        next_actions,
        agent_brief,
    })
}

fn extract_act_wrapper_inner_command(command: &str) -> Option<String> {
    let tokens = split_act_command_words(command);
    if !tokens
        .windows(2)
        .any(|window| window[0] == "autopilot" && window[1] == "act")
    {
        return None;
    }
    option_values(&tokens, "--command")
        .into_iter()
        .next()
        .map(|value| value.trim().to_string())
        .filter(|value| !value.is_empty())
}

fn build_advance_next_actions(
    run_dir: &Path,
    status: &str,
    after_nav: &NavigatorReport,
) -> Vec<CoachAction> {
    let run_arg = command_arg(run_dir.to_string_lossy().as_ref());
    match status {
        "advanced" => vec![
            coach_action(
                1,
                "Read refreshed navigator",
                Some(format!("rs autopilot navigator --run-dir {run_arg} --format json")),
                "Use the refreshed operating card before taking another action or reporting progress.",
                false,
                false,
            ),
            coach_action(
                2,
                "Refresh proof before reporting",
                Some(format!("rs autopilot proof {run_arg} --format json")),
                "Make creator-facing claims from proof after the advanced step.",
                false,
                false,
            ),
        ],
        "dryRun" => after_nav
            .first_safe_action
            .clone()
            .into_iter()
            .collect::<Vec<_>>(),
        _ => vec![coach_action(
            1,
            "Diagnose advance blocker",
            Some(format!("rs autopilot diagnose {run_arg} --format json")),
            "Advance could not execute the navigator action; diagnose before continuing.",
            false,
            false,
        )],
    }
}

fn build_advance_agent_brief(status: &str, selected_inner_command: Option<&str>) -> String {
    match status {
        "advanced" => format!(
            "Advance executed one safe offline action through act: `{}`. Read the refreshed navigator before doing anything else.",
            selected_inner_command.unwrap_or("<unknown>")
        ),
        "dryRun" => format!(
            "Advance dry-run selected `{}` but did not execute it.",
            selected_inner_command.unwrap_or("<unknown>")
        ),
        "blocked" => {
            "Advance did not execute because navigator lacked a safe act-wrapped action or a safety gate blocked it.".into()
        }
        _ => "Advance attempted the navigator action but it failed; inspect advance and act receipts.".into(),
    }
}

fn build_diagnosis_report(
    options: &DiagnoseOptions,
    diagnosis_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<DiagnosisReport> {
    if !options.run_dir.is_dir() {
        return Err(AppError::Other(format!(
            "autopilot diagnose run directory does not exist: {}",
            options.run_dir.display()
        )));
    }

    let input_command = options
        .command
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(redact_text);
    let input_result = options
        .result
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(redact_text);
    let input_errors = options
        .errors
        .iter()
        .map(|value| value.trim())
        .filter(|value| !value.is_empty())
        .map(redact_text)
        .collect::<Vec<_>>();
    let input_evidence = options
        .evidence
        .iter()
        .map(|value| value.trim())
        .filter(|value| !value.is_empty())
        .map(redact_text)
        .collect::<Vec<_>>();

    let mut incidents = Vec::new();
    if diagnosis_input_indicates_failure(input_result.as_deref(), &input_errors) {
        let mut evidence = input_evidence.clone();
        if let Some(result) = &input_result {
            evidence.push(format!("result: {result}"));
        }
        evidence.extend(
            input_errors
                .iter()
                .take(5)
                .map(|error| format!("error: {error}")),
        );
        add_diagnosis_incident(
            &mut incidents,
            "blocker",
            "command-failed",
            "input",
            input_command
                .as_ref()
                .map(|command| format!("Command reported a failing result: {command}"))
                .unwrap_or_else(|| "A reported command or tool result failed.".into()),
            evidence,
            vec![
                build_diagnosis_journal_command(
                    &options.run_dir,
                    input_command.as_deref(),
                    input_result.as_deref(),
                    &input_errors,
                    &input_evidence,
                ),
                format!(
                    "rs autopilot cycle {} --format json",
                    command_arg(options.run_dir.to_string_lossy().as_ref())
                ),
            ],
        );
    }

    let cycle_path = options.run_dir.join("cycle.json");
    let work_order_path = options.run_dir.join("work-order.json");
    let work_check_path = options.run_dir.join("work-check.json");
    let claim_check_path = options.run_dir.join("claim-check.json");
    let journal_path = options.run_dir.join("journal.json");
    let playtest_path = options.run_dir.join("playtest-result.json");
    let alignment_path = options.run_dir.join("alignment.json");
    let privacy_path = options.run_dir.join("privacy.json");
    let bundle_path = options.run_dir.join("bundle.json");

    let cycle_value = read_json_if_exists(&cycle_path)?;
    let work_order_value = read_json_if_exists(&work_order_path)?;
    let work_check_value = read_json_if_exists(&work_check_path)?;
    let claim_check_value = read_json_if_exists(&claim_check_path)?;
    let journal_value = read_json_if_exists(&journal_path)?;
    let playtest_value = read_json_if_exists(&playtest_path)?;
    let alignment_value = read_json_if_exists(&alignment_path)?;
    let privacy_value = read_json_if_exists(&privacy_path)?;

    let selected_command = diagnosis_selected_command(
        cycle_value.as_ref(),
        work_check_value.as_ref(),
        work_order_value.as_ref(),
    );
    let run = command_arg(options.run_dir.to_string_lossy().as_ref());

    if let Some(value) = &cycle_value {
        diagnose_cycle_value(&mut incidents, value, &run, selected_command.as_deref());
    } else {
        add_diagnosis_incident(
            &mut incidents,
            "warning",
            "cycle-missing",
            "cycle",
            "No cycle.json exists, so diagnosis cannot use the latest AI-cycle state.",
            vec![cycle_path.to_string_lossy().to_string()],
            vec![format!("rs autopilot cycle {run} --format json")],
        );
    }

    if let Some(value) = &work_check_value {
        diagnose_work_check_value(
            &mut incidents,
            value,
            &run,
            selected_command.as_deref(),
            &work_check_path,
        );
    }
    if let Some(value) = &claim_check_value {
        diagnose_claim_check_value(&mut incidents, value, &run, &claim_check_path);
    }
    if let Some(value) = &journal_value {
        diagnose_journal_value(&mut incidents, value, &run, &journal_path);
    }
    if let Some(value) = &playtest_value {
        diagnose_playtest_value(&mut incidents, value, &run, &playtest_path);
    }
    if let Some(value) = &alignment_value {
        diagnose_status_artifact(
            &mut incidents,
            value,
            "decision-drift",
            "alignment",
            "alignment.json is blocked; creator decisions must be reconciled before continuing.",
            &alignment_path,
            vec![format!("rs autopilot align {run} --format json")],
        );
    }
    if let Some(value) = &privacy_value {
        diagnose_status_artifact(
            &mut incidents,
            value,
            "privacy-blocked",
            "privacy",
            "privacy.json is blocked; redact or remove sensitive evidence before handoff.",
            &privacy_path,
            vec![format!("rs autopilot privacy {run} --format json")],
        );
    }
    if bundle_path.exists() {
        match verify_bundle_report(&bundle_path, Some(&options.run_dir)) {
            Ok(report) if !report.ok => add_diagnosis_incident(
                &mut incidents,
                "blocker",
                "bundle-drift",
                "bundle",
                "bundle.json no longer matches the run artifacts.",
                diagnosis_bundle_evidence(&report),
                vec![
                    format!("rs autopilot bundle {run} --format json"),
                    format!("rs autopilot verify-bundle --run-dir {run} --format json"),
                ],
            ),
            Ok(report) if !report.extra.is_empty() => add_diagnosis_incident(
                &mut incidents,
                "warning",
                "bundle-stale",
                "bundle",
                "bundle.json is valid but does not list every current companion artifact.",
                report
                    .extra
                    .iter()
                    .take(8)
                    .map(|path| format!("extra: {path}"))
                    .collect(),
                vec![format!("rs autopilot bundle {run} --format json")],
            ),
            Ok(_) => {}
            Err(error) => add_diagnosis_incident(
                &mut incidents,
                "blocker",
                "bundle-unreadable",
                "bundle",
                "bundle.json could not be verified.",
                vec![format!("error: {error}")],
                vec![format!("rs autopilot bundle {run} --format json")],
            ),
        }
    }

    dedup_diagnosis_incidents(&mut incidents);
    let blocker_count = incidents
        .iter()
        .filter(|incident| incident.severity == "blocker")
        .count();
    let warning_count = incidents
        .iter()
        .filter(|incident| incident.severity == "warning")
        .count();
    let status = if blocker_count > 0 {
        "blocked"
    } else if warning_count > 0 {
        "needsReview"
    } else {
        "clear"
    };
    let verdict = match status {
        "clear" => "noDiagnosisNeeded",
        "needsReview" => "reviewRecommended",
        _ => "repairRequired",
    };
    let safe_to_say = if incidents.is_empty() {
        vec!["No offline diagnosis incidents were found for this run.".into()]
    } else {
        vec![format!(
            "Autopilot diagnosis found {} incident(s) to resolve before continuing.",
            incidents.len()
        )]
    };
    let do_not_say = vec![
        "Do not claim diagnosis fixed anything; it only classified evidence and recovery routes."
            .into(),
        "Do not claim live Studio, apply, playtest, rollback, or publish success from diagnosis alone."
            .into(),
        "Do not report creator-facing completion until claim-check or response artifacts support the exact wording."
            .into(),
    ];
    let blockers = incidents
        .iter()
        .filter(|incident| incident.severity == "blocker")
        .map(|incident| incident.summary.clone())
        .collect::<Vec<_>>();
    let warnings = incidents
        .iter()
        .filter(|incident| incident.severity != "blocker")
        .map(|incident| incident.summary.clone())
        .collect::<Vec<_>>();
    let mut artifacts = collect_planner_run_artifacts(Some(&options.run_dir));
    artifacts.insert(
        "diagnosis".into(),
        diagnosis_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "diagnosisMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    let mut next_actions = build_diagnosis_next_actions(&options.run_dir, &incidents, status);
    dedup_next_actions(&mut next_actions);
    let agent_brief = build_diagnosis_agent_brief(status, &incidents);

    Ok(DiagnosisReport {
        schema_version: "rs.autopilot.diagnosis.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        diagnosis_path: diagnosis_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status: status.into(),
        verdict: verdict.into(),
        input_command,
        input_result,
        input_errors,
        input_evidence,
        incident_count: incidents.len(),
        incidents,
        safe_to_say,
        do_not_say,
        artifacts,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn diagnosis_input_indicates_failure(result: Option<&str>, errors: &[String]) -> bool {
    !errors.is_empty()
        || result.is_some_and(|value| {
            let lower = value.to_ascii_lowercase();
            [
                "fail",
                "blocked",
                "error",
                "timeout",
                "timed out",
                "panic",
                "crash",
                "denied",
                "missing",
                "not connected",
            ]
            .iter()
            .any(|needle| lower.contains(needle))
        })
}

fn build_diagnosis_journal_command(
    run_dir: &Path,
    command: Option<&str>,
    result: Option<&str>,
    errors: &[String],
    evidence: &[String],
) -> String {
    let run = command_arg(run_dir.to_string_lossy().as_ref());
    let mut parts = vec![format!("rs autopilot journal {run}")];
    if let Some(command) = command {
        parts.push(format!("--command \"{}\"", shell_display_arg(command)));
    }
    if let Some(result) = result {
        parts.push(format!("--result \"{}\"", shell_display_arg(result)));
    } else if let Some(error) = errors.first() {
        parts.push(format!("--result \"{}\"", shell_display_arg(error)));
    }
    for item in evidence.iter().take(3) {
        parts.push(format!("--evidence \"{}\"", shell_display_arg(item)));
    }
    if command.is_none() && result.is_none() && errors.is_empty() {
        parts.push("--entry \"Record the diagnosis context\"".into());
    }
    parts.push("--format json".into());
    parts.join(" ")
}

fn diagnosis_selected_command(
    cycle: Option<&Value>,
    work_check: Option<&Value>,
    work_order: Option<&Value>,
) -> Option<String> {
    cycle
        .and_then(|value| string_field(value, "selectedCommand"))
        .or_else(|| work_check.and_then(|value| string_field(value, "selectedCommand")))
        .or_else(|| {
            work_order.and_then(|value| {
                value
                    .get("opportunity")
                    .and_then(|opportunity| opportunity.get("command"))
                    .and_then(Value::as_str)
                    .map(str::to_string)
                    .or_else(|| selected_work_order_step_command(value))
            })
        })
}

fn diagnose_cycle_value(
    incidents: &mut Vec<DiagnosisIncident>,
    value: &Value,
    run: &str,
    selected_command: Option<&str>,
) {
    match string_field(value, "status").as_deref() {
        Some("executeWorkOrder") => {
            let command = selected_command
                .map(str::to_string)
                .unwrap_or_else(|| format!("rs autopilot work-order --run-dir {run} --format json"));
            add_diagnosis_incident(
                incidents,
                "blocker",
                "selected-command-not-run",
                "cycle",
                "cycle.json selected an offline command that still needs to be run.",
                vec!["cycle.json".into()],
                vec![command, format!("rs autopilot cycle {run} --format json")],
            );
        }
        Some("recordManualEvidence") => add_diagnosis_incident(
            incidents,
            "blocker",
            "manual-evidence-required",
            "cycle",
            "cycle.json is waiting for manual evidence to be journaled.",
            vec!["cycle.json".into(), "work-check.json".into()],
            vec![
                format!(
                    "rs autopilot journal {run} --entry \"Reviewed manual evidence\" --evidence \"<artifact or stdout>\" --format json"
                ),
                format!("rs autopilot cycle {run} --format json"),
            ],
        ),
        Some("rewriteClaim") => add_diagnosis_incident(
            incidents,
            "blocker",
            "unsupported-claim",
            "cycle",
            "cycle.json found creator-facing wording that needs rewrite before reporting.",
            vec!["cycle.json".into(), "claim-check.json".into()],
            vec![format!(
                "rs autopilot claim-check {run} --claim \"<rewritten evidence-backed claim>\" --format json"
            )],
        ),
        Some("selectWorkOrder") => add_diagnosis_incident(
            incidents,
            "warning",
            "work-order-missing",
            "cycle",
            "cycle.json needs a work order before execution evidence can be checked.",
            vec!["cycle.json".into()],
            vec![format!("rs autopilot work-order --run-dir {run} --format json")],
        ),
        Some("readyToReport") => {}
        Some(status) if status != "clear" => add_diagnosis_incident(
            incidents,
            "warning",
            "cycle-paused",
            "cycle",
            format!("cycle.json is paused at status {status}."),
            vec!["cycle.json".into()],
            vec![format!("rs autopilot cycle {run} --format json")],
        ),
        _ => {}
    }
}

fn diagnose_work_check_value(
    incidents: &mut Vec<DiagnosisIncident>,
    value: &Value,
    run: &str,
    selected_command: Option<&str>,
    work_check_path: &Path,
) {
    let status = string_field(value, "status").unwrap_or_else(|| "unknown".into());
    let mut evidence = vec![work_check_path.to_string_lossy().to_string()];
    evidence.extend(
        string_array_field(value, "missingArtifacts")
            .into_iter()
            .map(|artifact| format!("missing: {artifact}")),
    );
    evidence.extend(
        string_array_field(value, "manualEvidence")
            .into_iter()
            .map(|artifact| format!("manual: {artifact}")),
    );
    let mut commands = Vec::new();
    if let Some(command) = selected_command {
        commands.push(command.to_string());
    }
    commands.push(format!("rs autopilot work-check {run} --format json"));
    match status.as_str() {
        "needsWorkOrder" => add_diagnosis_incident(
            incidents,
            "blocker",
            "work-order-missing",
            "work-check",
            "work-check.json cannot audit execution because work-order.json is missing.",
            evidence,
            vec![format!("rs autopilot work-order --run-dir {run} --format json")],
        ),
        "needsEvidence" => add_diagnosis_incident(
            incidents,
            "blocker",
            "missing-work-order-evidence",
            "work-check",
            "work-check.json found missing expected artifacts for the selected work order.",
            evidence,
            commands,
        ),
        "needsManualEvidence" => add_diagnosis_incident(
            incidents,
            "blocker",
            "manual-evidence-required",
            "work-check",
            "work-check.json requires evidence that cannot be verified as files.",
            evidence,
            vec![
                format!(
                    "rs autopilot journal {run} --entry \"Reviewed manual evidence\" --evidence \"<artifact or stdout>\" --format json"
                ),
                format!("rs autopilot work-check {run} --format json"),
            ],
        ),
        "blocked" => add_diagnosis_incident(
            incidents,
            "blocker",
            "work-check-blocked",
            "work-check",
            "work-check.json is blocked; resolve its listed blockers before continuing.",
            merge_many_sorted(vec![evidence, string_array_field(value, "blockers")]),
            commands,
        ),
        _ => {}
    }
}

fn diagnose_claim_check_value(
    incidents: &mut Vec<DiagnosisIncident>,
    value: &Value,
    run: &str,
    claim_check_path: &Path,
) {
    let status = string_field(value, "status").unwrap_or_else(|| "unknown".into());
    if matches!(status.as_str(), "blocked" | "needsRewrite" | "needsClaims") {
        add_diagnosis_incident(
            incidents,
            "blocker",
            "unsupported-claim",
            "claim-check",
            format!("claim-check.json is {status}; creator-facing wording is not ready."),
            merge_many_sorted(vec![
                vec![claim_check_path.to_string_lossy().to_string()],
                string_array_field(value, "blockers"),
                string_array_field(value, "warnings"),
            ]),
            vec![format!(
                "rs autopilot claim-check {run} --claim \"<evidence-backed claim>\" --format json"
            )],
        );
    }
}

fn diagnose_journal_value(
    incidents: &mut Vec<DiagnosisIncident>,
    value: &Value,
    run: &str,
    journal_path: &Path,
) {
    let Some(entries) = value.get("entries").and_then(Value::as_array) else {
        return;
    };
    for entry in entries.iter().filter(|entry| {
        string_field(entry, "kind")
            .as_deref()
            .is_some_and(|kind| kind == "result")
    }) {
        let Some(text) = string_field(entry, "text") else {
            continue;
        };
        if diagnosis_input_indicates_failure(Some(&text), &[]) {
            add_diagnosis_incident(
                incidents,
                "warning",
                "journaled-failure",
                "journal",
                "journal.json records a failed or blocked command result.",
                vec![journal_path.to_string_lossy().to_string(), text],
                vec![
                    format!("rs autopilot diagnose {run} --format json"),
                    format!("rs autopilot cycle {run} --format json"),
                ],
            );
            break;
        }
    }
}

fn diagnose_playtest_value(
    incidents: &mut Vec<DiagnosisIncident>,
    value: &Value,
    run: &str,
    playtest_path: &Path,
) {
    let Some(result) = string_field(value, "result") else {
        return;
    };
    if matches!(
        result.as_str(),
        "failed" | "blocked" | "inconclusive" | "timeout" | "timedOut"
    ) {
        add_diagnosis_incident(
            incidents,
            "blocker",
            "live-evidence-failure",
            "playtest",
            format!("playtest-result.json recorded {result} live evidence."),
            merge_many_sorted(vec![
                vec![playtest_path.to_string_lossy().to_string()],
                string_array_field(value, "blockers"),
                string_array_field(value, "warnings"),
                string_array_field(value, "notes"),
            ]),
            vec![
                format!("rs autopilot evidence-review {run} --format json"),
                format!("rs autopilot repair-plan {run} --format json"),
            ],
        );
    }
}

fn diagnose_status_artifact(
    incidents: &mut Vec<DiagnosisIncident>,
    value: &Value,
    category: &str,
    source: &str,
    summary: &str,
    path: &Path,
    commands: Vec<String>,
) {
    let status = string_field(value, "status").unwrap_or_else(|| "unknown".into());
    if matches!(status.as_str(), "blocked" | "failed" | "needsReview") {
        add_diagnosis_incident(
            incidents,
            "blocker",
            category,
            source,
            summary,
            merge_many_sorted(vec![
                vec![path.to_string_lossy().to_string()],
                string_array_field(value, "blockers"),
                string_array_field(value, "warnings"),
            ]),
            commands,
        );
    }
}

fn diagnosis_bundle_evidence(report: &BundleVerifyReport) -> Vec<String> {
    let mut evidence = vec![report.bundle_path.clone()];
    evidence.extend(
        report
            .missing
            .iter()
            .take(8)
            .map(|path| format!("missing: {path}")),
    );
    evidence.extend(
        report
            .mismatched
            .iter()
            .take(8)
            .map(|item| format!("drifted: {}", item.path)),
    );
    evidence
}

fn add_diagnosis_incident(
    incidents: &mut Vec<DiagnosisIncident>,
    severity: &str,
    category: &str,
    source: &str,
    summary: impl Into<String>,
    mut evidence: Vec<String>,
    mut commands: Vec<String>,
) {
    evidence.retain(|value| !value.trim().is_empty());
    evidence.sort();
    evidence.dedup();
    commands.retain(|value| !value.trim().is_empty());
    commands.dedup();
    let id = format!("DIAG-{:03}", incidents.len() + 1);
    incidents.push(DiagnosisIncident {
        id,
        severity: severity.into(),
        category: category.into(),
        source: source.into(),
        summary: summary.into(),
        evidence,
        commands,
    });
}

fn dedup_diagnosis_incidents(incidents: &mut Vec<DiagnosisIncident>) {
    incidents.sort_by(|left, right| {
        severity_rank(&left.severity)
            .cmp(&severity_rank(&right.severity))
            .then(left.category.cmp(&right.category))
            .then(left.source.cmp(&right.source))
            .then(left.summary.cmp(&right.summary))
    });
    let mut seen = BTreeSet::new();
    incidents.retain(|incident| {
        let key = format!(
            "{}\n{}\n{}",
            incident.severity, incident.category, incident.summary
        );
        seen.insert(key)
    });
    for (index, incident) in incidents.iter_mut().enumerate() {
        incident.id = format!("DIAG-{:03}", index + 1);
    }
}

fn build_diagnosis_next_actions(
    run_dir: &Path,
    incidents: &[DiagnosisIncident],
    status: &str,
) -> Vec<CoachAction> {
    let run = command_arg(run_dir.to_string_lossy().as_ref());
    let mut actions = Vec::new();
    for (index, incident) in incidents.iter().enumerate() {
        if let Some(command) = incident.commands.first() {
            let (requires_live_studio, mutates_studio) = diagnosis_command_flags(command);
            actions.push(coach_action(
                (index as u8).saturating_add(1),
                &diagnosis_action_title(incident),
                Some(command.clone()),
                &incident.summary,
                requires_live_studio,
                mutates_studio,
            ));
        }
    }
    if status == "clear" {
        actions.push(coach_action(
            1,
            "Continue AI cycle",
            Some(format!("rs autopilot cycle {run} --format json")),
            "No diagnosis incident is blocking the next offline cycle.",
            false,
            false,
        ));
    }
    actions.push(coach_action(
        98,
        "Refresh diagnosis",
        Some(format!("rs autopilot diagnose {run} --format json")),
        "Regenerate diagnosis after resolving an incident or recording evidence.",
        false,
        false,
    ));
    actions
}

fn diagnosis_action_title(incident: &DiagnosisIncident) -> String {
    match incident.category.as_str() {
        "command-failed" => "Record failed command and rerun cycle",
        "selected-command-not-run" => "Run selected work-order command",
        "missing-work-order-evidence" => "Create missing work-order evidence",
        "manual-evidence-required" => "Record manual evidence",
        "unsupported-claim" => "Rewrite unsupported claim",
        "bundle-drift" | "bundle-stale" => "Refresh bundle",
        "live-evidence-failure" => "Review failed live evidence",
        "decision-drift" => "Refresh decision alignment",
        "privacy-blocked" => "Resolve privacy blocker",
        _ => "Resolve diagnosis incident",
    }
    .into()
}

fn diagnosis_command_flags(command: &str) -> (bool, bool) {
    let lower = command.to_ascii_lowercase();
    let requires_live_studio = lower.contains(" autopilot apply ")
        || lower.contains(" autopilot live-gate ")
        || lower.contains(" autopilot ready ")
        || lower.contains(" rs run ");
    let mutates_studio = lower.contains(" autopilot apply ") || lower.contains(" rs run ");
    (requires_live_studio, mutates_studio)
}

fn build_diagnosis_agent_brief(status: &str, incidents: &[DiagnosisIncident]) -> String {
    match status {
        "clear" => {
            "Diagnosis is clear: no offline incidents were found. Continue with cycle or the next checked action.".into()
        }
        "needsReview" => format!(
            "Diagnosis found {} warning incident(s). Review them before handing off or reporting.",
            incidents.len()
        ),
        _ => format!(
            "Diagnosis is blocked: {} incident(s) need repair before the AI should continue or report.",
            incidents.len()
        ),
    }
}

fn build_act_report(
    options: &ActOptions,
    act_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<ActReport> {
    if !options.run_dir.is_dir() {
        return Err(AppError::Other(format!(
            "autopilot act run directory does not exist: {}",
            options.run_dir.display()
        )));
    }
    let selection = select_act_command(options)?;
    let selected_command = selection
        .command
        .as_ref()
        .map(|command| redact_text(command));
    let command_kind = selection.command.as_deref().and_then(act_command_kind);
    let expected_artifacts = selection
        .command
        .as_deref()
        .map(expected_artifacts_for_command)
        .unwrap_or_default();
    let mut steps = Vec::new();
    let mut blockers = Vec::new();
    let warnings = selection.warnings;
    let mut executed = false;

    if selection.command.is_none() {
        blockers.push("no safe offline Autopilot action was available to execute".into());
    } else if let Some(command) = &selection.command {
        if let Some(reason) = act_refusal_reason(command) {
            blockers.push(reason.clone());
            steps.push(act_step(
                "ACT-010",
                "Safety gate",
                "blocked",
                reason,
                Some(redact_text(command)),
                Vec::new(),
                None,
            ));
        } else if options.dry_run {
            steps.push(act_step(
                "ACT-010",
                "Dry-run selected action",
                "dryRun",
                "Selected safe offline command without executing it.",
                Some(redact_text(command)),
                expected_artifacts.clone(),
                None,
            ));
        } else {
            match execute_act_command(options, command) {
                Ok(execution) => {
                    executed = true;
                    steps.extend(execution.steps);
                }
                Err(err) => {
                    blockers.push(format!("selected action failed: {err}"));
                    steps.push(act_step(
                        "ACT-010",
                        "Execute selected action",
                        "failed",
                        "The selected safe action returned an error.",
                        Some(redact_text(command)),
                        Vec::new(),
                        Some(err.to_string()),
                    ));
                }
            }
        }
    }

    let present_artifacts =
        classify_work_check_expected_artifacts(&options.run_dir, &expected_artifacts)
            .map(|(present, _missing, _manual)| present)
            .unwrap_or_default();
    let mut artifacts = collect_planner_run_artifacts(Some(&options.run_dir));
    artifacts.insert("act".into(), act_path.to_string_lossy().to_string());
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "actMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    let status = if !blockers.is_empty() {
        if executed {
            "failed"
        } else {
            "blocked"
        }
    } else if options.dry_run {
        "dryRun"
    } else if executed {
        "executed"
    } else {
        "blocked"
    };
    let verdict = match status {
        "executed" => "safeOfflineActionExecuted",
        "dryRun" => "safeOfflineActionSelected",
        "blocked" => "noSafeActionExecuted",
        _ => "safeActionFailed",
    };
    let safe_to_say = match status {
        "executed" => vec![
            "Autopilot act executed one whitelisted offline CLI action and refreshed loop evidence."
                .into(),
        ],
        "dryRun" => {
            vec!["Autopilot act selected one safe offline action without executing it.".into()]
        }
        _ => vec!["Autopilot act did not execute a safe offline action.".into()],
    };
    let do_not_say = vec![
        "Do not claim live Studio mutation, apply success, playtest success, rollback readiness, publish readiness, or production readiness from act alone.".into(),
        "Do not claim arbitrary shell commands were executed; act only runs whitelisted offline Autopilot actions through internal handlers.".into(),
        "Do not report completion until cycle, work-check, claim-check, or response artifacts support the exact creator-facing wording.".into(),
    ];
    let mut next_actions = build_act_next_actions(
        &options.run_dir,
        status,
        selection.command.as_deref(),
        command_kind.as_deref(),
    );
    dedup_next_actions(&mut next_actions);
    let agent_brief = build_act_agent_brief(status, command_kind.as_deref());

    Ok(ActReport {
        schema_version: "rs.autopilot.act.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        act_path: act_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status: status.into(),
        verdict: verdict.into(),
        source: selection.source,
        selected_command,
        command_kind,
        dry_run: options.dry_run,
        executed,
        steps,
        expected_artifacts,
        present_artifacts,
        safe_to_say,
        do_not_say,
        artifacts,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn select_act_command(options: &ActOptions) -> AppResult<ActSelection> {
    if let Some(command) = options
        .command
        .as_deref()
        .map(str::trim)
        .filter(|command| !command.is_empty())
    {
        return Ok(ActSelection {
            source: "explicit".into(),
            command: Some(command.to_string()),
            warnings: Vec::new(),
        });
    }
    let source = options.source.trim().to_ascii_lowercase();
    let mut warnings = Vec::new();
    let sources: Vec<&str> = match source.as_str() {
        "auto" => vec!["diagnosis", "cycle", "work-order", "agenda"],
        "diagnosis" | "cycle" | "work-order" | "workorder" | "agenda" => vec![source.as_str()],
        other => {
            warnings.push(format!(
                "unknown act source `{other}`; falling back to auto source selection"
            ));
            vec!["diagnosis", "cycle", "work-order"]
        }
    };
    for source in sources {
        match source {
            "diagnosis" => {
                if let Some(value) = read_json_if_exists(&options.run_dir.join("diagnosis.json"))? {
                    let status = string_field(&value, "status").unwrap_or_default();
                    if status != "clear" {
                        if let Some(command) = first_next_action_command(&value) {
                            return Ok(ActSelection {
                                source: "diagnosis".into(),
                                command: Some(command),
                                warnings,
                            });
                        }
                    }
                }
            }
            "cycle" => {
                if let Some(value) = read_json_if_exists(&options.run_dir.join("cycle.json"))? {
                    if let Some(command) = first_next_action_command(&value)
                        .or_else(|| string_field(&value, "selectedCommand"))
                    {
                        return Ok(ActSelection {
                            source: "cycle".into(),
                            command: Some(command),
                            warnings,
                        });
                    }
                }
            }
            "work-order" | "workorder" => {
                if let Some(value) = read_json_if_exists(&options.run_dir.join("work-order.json"))?
                {
                    if let Some(command) = diagnosis_selected_command(None, None, Some(&value)) {
                        return Ok(ActSelection {
                            source: "work-order".into(),
                            command: Some(command),
                            warnings,
                        });
                    }
                }
            }
            "agenda" => {
                if let Some(value) = read_json_if_exists(&options.run_dir.join("agenda.json"))? {
                    if let Some(command) = first_agenda_command(&value) {
                        return Ok(ActSelection {
                            source: "agenda".into(),
                            command: Some(command),
                            warnings,
                        });
                    }
                }
            }
            _ => {}
        }
    }
    Ok(ActSelection {
        source: options.source.clone(),
        command: Some(format!(
            "rs autopilot cycle {} --format json",
            command_arg(options.run_dir.to_string_lossy().as_ref())
        )),
        warnings,
    })
}

fn first_next_action_command(value: &Value) -> Option<String> {
    value
        .get("nextActions")
        .and_then(Value::as_array)?
        .iter()
        .filter_map(|action| action.get("command").and_then(Value::as_str))
        .map(str::trim)
        .filter(|command| !command.is_empty())
        .find(|command| act_command_kind(command).is_some())
        .map(str::to_string)
}

fn first_agenda_command(value: &Value) -> Option<String> {
    value
        .get("agenda")
        .and_then(Value::as_array)?
        .iter()
        .filter_map(|item| item.get("command").and_then(Value::as_str))
        .map(str::trim)
        .filter(|command| !command.is_empty())
        .find(|command| act_command_kind(command).is_some())
        .map(str::to_string)
}

fn act_refusal_reason(command: &str) -> Option<String> {
    let lower = command.to_ascii_lowercase();
    if act_command_kind(command).is_none() {
        return Some("act only executes whitelisted `rs autopilot ...` commands".into());
    }
    for needle in [
        " autopilot apply ",
        " autopilot live-gate ",
        " autopilot ready ",
        " autopilot setup ",
        " autopilot publish-review ",
        " install-plugin",
        " doctor --fix",
        " bridge ",
        " smoke ",
        " upload",
        " rs run ",
    ] {
        if lower.contains(needle) {
            return Some(format!(
                "refused unsafe or live-dependent command containing `{}`",
                needle.trim()
            ));
        }
    }
    None
}

fn act_command_kind(command: &str) -> Option<String> {
    let tokens = split_act_command_words(command);
    tokens
        .windows(2)
        .find(|window| window[0] == "autopilot")
        .and_then(|window| {
            let kind = window[1].as_str();
            if is_safe_act_kind(kind) {
                Some(kind.to_string())
            } else {
                None
            }
        })
}

