fn execute_act_command(options: &ActOptions, command: &str) -> AppResult<ActExecution> {
    let kind = act_command_kind(command)
        .ok_or_else(|| AppError::Other("act could not identify a safe autopilot command".into()))?
        .to_string();
    let mut steps = Vec::new();
    let mut artifacts = execute_act_primary_command(options, command, &kind)?;
    steps.push(act_step(
        "ACT-010",
        "Execute selected offline action",
        "executed",
        format!("Executed whitelisted autopilot `{kind}` action through internal handlers."),
        Some(redact_text(command)),
        artifacts.clone(),
        None,
    ));
    if should_act_refresh_cycle(&kind) {
        let cycle_path = options.run_dir.join("cycle.json");
        let cycle_markdown_path = options.run_dir.join("cycle.md");
        let cycle_options = CycleOptions {
            run_dir: options.run_dir.clone(),
            prompt: None,
            root: options.root.clone(),
            limit: options.limit,
            out: Some(cycle_path.clone()),
            markdown: Some(cycle_markdown_path.clone()),
            no_markdown: false,
            json: false,
        };
        let cycle_report =
            build_cycle_report(&cycle_options, &cycle_path, Some(&cycle_markdown_path))?;
        write_json(cycle_path.clone(), &cycle_report)?;
        write_cycle_markdown(cycle_markdown_path.clone(), &cycle_report)?;
        artifacts.push(cycle_path.to_string_lossy().to_string());
        artifacts.push(cycle_markdown_path.to_string_lossy().to_string());
        steps.push(act_step(
            "ACT-020",
            "Refresh AI cycle",
            &cycle_report.status,
            "Refreshed cycle after the selected action.",
            Some(format!(
                "rs autopilot cycle {} --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref())
            )),
            vec![
                cycle_report.cycle_path.clone(),
                cycle_report.markdown_path.clone().unwrap_or_default(),
            ],
            None,
        ));
        refresh_run_bundle_if_possible(&options.run_dir)?;
        let diagnosis_path = options.run_dir.join("diagnosis.json");
        let diagnosis_markdown_path = options.run_dir.join("diagnosis.md");
        let diagnosis_options = DiagnoseOptions {
            run_dir: options.run_dir.clone(),
            command: Some(command.to_string()),
            result: Some(format!("act executed {kind}")),
            errors: Vec::new(),
            evidence: artifacts.clone(),
            out: Some(diagnosis_path.clone()),
            markdown: Some(diagnosis_markdown_path.clone()),
            no_markdown: false,
            json: false,
        };
        let diagnosis_report = build_diagnosis_report(
            &diagnosis_options,
            &diagnosis_path,
            Some(&diagnosis_markdown_path),
        )?;
        write_json(diagnosis_path.clone(), &diagnosis_report)?;
        write_diagnosis_markdown(diagnosis_markdown_path.clone(), &diagnosis_report)?;
        steps.push(act_step(
            "ACT-030",
            "Refresh diagnosis",
            &diagnosis_report.status,
            "Refreshed diagnosis after the selected action.",
            Some(format!(
                "rs autopilot diagnose {} --format json",
                command_arg(options.run_dir.to_string_lossy().as_ref())
            )),
            vec![
                diagnosis_report.diagnosis_path.clone(),
                diagnosis_report.markdown_path.clone().unwrap_or_default(),
            ],
            None,
        ));
    }
    refresh_run_bundle_if_possible(&options.run_dir)?;
    Ok(ActExecution { steps })
}

