fn act_run_promise_loop(options: &ActOptions, command: &str) -> AppResult<Vec<String>> {
    let tokens = split_act_command_words(command);
    let prompt = act_prompt_after_run(&tokens, "promise-loop").or_else(|| {
        read_plan(&options.run_dir.join("plan.json"))
            .ok()
            .map(|plan| plan.request.prompt)
    });
    let prompt_text = prompt.clone().ok_or_else(|| {
        AppError::Other("autopilot act could not resolve a prompt for promise-loop".into())
    })?;
    let source_plan_path = options.run_dir.join("plan.json");
    let source_plan = read_plan(&source_plan_path)?;
    let session_dir = option_path(&tokens, "--out")
        .unwrap_or_else(|| default_promise_loop_dir(&options.run_dir, &prompt_text));
    let out = session_dir.join("promise-loop.json");
    let markdown = session_dir.join("promise-loop.md");
    let loop_options = PromiseLoopOptions {
        port: 7878,
        run_dir: options.run_dir.clone(),
        prompt,
        out: Some(session_dir.clone()),
        markdown: Some(markdown.clone()),
        no_markdown: false,
        max_steps: option_usize(&tokens, "--max-steps").unwrap_or(4),
        max_recipes: option_usize(&tokens, "--max-recipes").unwrap_or(1),
        smoke: option_values(&tokens, "--smoke").into_iter().next(),
        dry_run: has_flag(&tokens, "--dry-run"),
        json: false,
    };
    let report = build_promise_loop_report(
        &loop_options,
        &source_plan,
        &source_plan_path,
        &prompt_text,
        &session_dir,
        &out,
        Some(&markdown),
    )?;
    write_json(out.clone(), &report)?;
    write_promise_loop_markdown(markdown.clone(), &report)?;
    let mut paths = paths_to_strings(vec![out, markdown]);
    paths.extend(report.artifacts.values().cloned());
    paths.sort();
    paths.dedup();
    Ok(paths)
}

