fn split_act_command_words(command: &str) -> Vec<String> {
    let mut words = Vec::new();
    let mut current = String::new();
    let mut in_quotes = false;
    let mut quote_char = '\0';
    let mut escaped = false;
    for ch in command.chars() {
        if escaped {
            if ch == quote_char || ch == '\\' {
                current.push(ch);
            } else {
                current.push('\\');
                current.push(ch);
            }
            escaped = false;
            continue;
        }
        if ch == '\\' && in_quotes {
            escaped = true;
            continue;
        }
        if in_quotes {
            if ch == quote_char {
                in_quotes = false;
            } else {
                current.push(ch);
            }
            continue;
        }
        if ch == '"' || ch == '\'' {
            in_quotes = true;
            quote_char = ch;
        } else if ch.is_whitespace() {
            if !current.is_empty() {
                words.push(std::mem::take(&mut current));
            }
        } else {
            current.push(ch);
        }
    }
    if escaped {
        current.push('\\');
    }
    if !current.is_empty() {
        words.push(current);
    }
    words
}

fn act_positionals_after_kind(tokens: &[String], kind: &str) -> Vec<String> {
    let Some(start) = tokens
        .windows(2)
        .position(|window| window[0] == "autopilot" && window[1] == kind)
        .map(|index| index + 2)
    else {
        return Vec::new();
    };
    let mut values = Vec::new();
    let mut index = start;
    while index < tokens.len() {
        let token = &tokens[index];
        if token.starts_with("--") {
            index += if tokens
                .get(index + 1)
                .is_some_and(|value| !value.starts_with("--"))
            {
                2
            } else {
                1
            };
            continue;
        }
        values.push(token.clone());
        index += 1;
    }
    values
}

fn act_prompt_after_run(tokens: &[String], kind: &str) -> Option<String> {
    let positionals = act_positionals_after_kind(tokens, kind);
    (positionals.len() > 1).then(|| positionals[1..].join(" "))
}

fn has_flag(tokens: &[String], name: &str) -> bool {
    tokens.iter().any(|token| token == name)
}

fn option_usize(tokens: &[String], name: &str) -> Option<usize> {
    option_values(tokens, name)
        .into_iter()
        .next()
        .and_then(|value| value.parse::<usize>().ok())
}

fn option_path(tokens: &[String], name: &str) -> Option<PathBuf> {
    option_values(tokens, name)
        .into_iter()
        .next()
        .map(PathBuf::from)
}

fn option_values(tokens: &[String], name: &str) -> Vec<String> {
    let mut values = Vec::new();
    let mut index = 0;
    while index < tokens.len() {
        if tokens[index] == name {
            if let Some(value) = tokens.get(index + 1) {
                values.push(value.clone());
                index += 2;
                continue;
            }
        }
        index += 1;
    }
    values
}

fn paths_to_strings(paths: Vec<PathBuf>) -> Vec<String> {
    paths
        .into_iter()
        .map(|path| path.to_string_lossy().to_string())
        .collect()
}

fn act_step(
    id: &str,
    title: &str,
    status: &str,
    summary: impl Into<String>,
    command: Option<String>,
    artifacts: Vec<String>,
    error: Option<String>,
) -> ActStep {
    ActStep {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        summary: summary.into(),
        command,
        artifacts: artifacts
            .into_iter()
            .filter(|artifact| !artifact.trim().is_empty())
            .collect(),
        error,
    }
}

fn build_act_next_actions(
    run_dir: &Path,
    status: &str,
    selected_command: Option<&str>,
    command_kind: Option<&str>,
) -> Vec<CoachAction> {
    let run = command_arg(run_dir.to_string_lossy().as_ref());
    let mut actions = Vec::new();
    match status {
        "executed" => actions.push(coach_action(
            1,
            "Inspect refreshed cycle",
            Some(format!("rs autopilot cycle {run} --format json")),
            "The action ran; use the refreshed cycle before reporting or choosing another action.",
            false,
            false,
        )),
        "dryRun" => {
            if let Some(command) = selected_command {
                let (requires_live_studio, mutates_studio) = diagnosis_command_flags(command);
                actions.push(coach_action(
                    1,
                    "Execute selected safe action",
                    Some(command.to_string()),
                    "Dry-run selected this command but did not execute it.",
                    requires_live_studio,
                    mutates_studio,
                ));
            }
        }
        _ => actions.push(coach_action(
            1,
            "Diagnose blocked action",
            Some(format!("rs autopilot diagnose {run} --format json")),
            "Action execution was blocked or failed; refresh diagnosis before continuing.",
            false,
            false,
        )),
    }
    if command_kind != Some("diagnose") {
        actions.push(coach_action(
            9,
            "Refresh diagnosis",
            Some(format!("rs autopilot diagnose {run} --format json")),
            "Regenerate the failure router after this action.",
            false,
            false,
        ));
    }
    actions
}

fn build_act_agent_brief(status: &str, command_kind: Option<&str>) -> String {
    match status {
        "executed" => format!(
            "Act executed one safe offline `{}` action and refreshed loop evidence. Read cycle/diagnosis before reporting.",
            command_kind.unwrap_or("autopilot")
        ),
        "dryRun" => format!(
            "Act selected a safe offline `{}` action but did not execute it.",
            command_kind.unwrap_or("autopilot")
        ),
        "failed" => "Act attempted a whitelisted offline action but it failed. Use diagnosis and act blockers before retrying.".into(),
        _ => "Act refused to execute because no safe offline command was available or the command crossed a live boundary.".into(),
    }
}

fn build_loop_report(
    options: &LoopOptions,
    loop_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<LoopReport> {
    if !options.run_dir.is_dir() {
        return Err(AppError::Other(format!(
            "autopilot loop run directory does not exist: {}",
            options.run_dir.display()
        )));
    }
    let max_steps = options.max_steps.max(1);
    let mut iterations = Vec::new();
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let mut status = "maxStepsReached".to_string();
    let mut final_cycle_status = None;
    let mut final_cycle_verdict = None;

    for index in 1..=max_steps {
        let cycle_path = options.run_dir.join("cycle.json");
        let cycle_markdown_path = options.run_dir.join("cycle.md");
        let cycle_options = CycleOptions {
            run_dir: options.run_dir.clone(),
            prompt: None,
            root: options.root.clone(),
            limit: options.limit,
            out: Some(cycle_path.clone()),
            markdown: Some(cycle_markdown_path.clone()),
            no_markdown: false,
            json: false,
        };
        let cycle_report =
            build_cycle_report(&cycle_options, &cycle_path, Some(&cycle_markdown_path))?;
        write_json(cycle_path.clone(), &cycle_report)?;
        write_cycle_markdown(cycle_markdown_path.clone(), &cycle_report)?;
        refresh_run_bundle_if_possible(&options.run_dir)?;
        final_cycle_status = Some(cycle_report.status.clone());
        final_cycle_verdict = Some(cycle_report.verdict.clone());

        if cycle_report.status == "readyToReport" {
            status = "readyToReport".into();
            iterations.push(loop_iteration(
                index,
                &cycle_report,
                None,
                "Cycle is already ready to report; no act step was needed.",
            ));
            break;
        }

        let act_path = options.run_dir.join("act.json");
        let act_markdown_path = options.run_dir.join("act.md");
        let act_options = ActOptions {
            run_dir: options.run_dir.clone(),
            command: None,
            source: "cycle".into(),
            root: options.root.clone(),
            limit: options.limit,
            dry_run: options.dry_run,
            out: Some(act_path.clone()),
            markdown: Some(act_markdown_path.clone()),
            no_markdown: false,
            json: false,
        };
        let act_report = build_act_report(&act_options, &act_path, Some(&act_markdown_path))?;
        write_json(act_path.clone(), &act_report)?;
        write_act_markdown(act_markdown_path.clone(), &act_report)?;
        refresh_run_bundle_if_possible(&options.run_dir)?;
        iterations.push(loop_iteration(
            index,
            &cycle_report,
            Some(&act_report),
            if options.dry_run {
                "Dry-run selected the next safe action and stopped."
            } else {
                "Executed one safe offline action and refreshed loop evidence."
            },
        ));
        warnings.extend(act_report.warnings.clone());
        if options.dry_run {
            status = "dryRun".into();
            break;
        }
        if act_report.status != "executed" {
            status = "blocked".into();
            blockers.extend(act_report.blockers.clone());
            break;
        }
    }

    if status == "maxStepsReached" {
        blockers.push(format!(
            "loop reached max_steps={} before cycle became readyToReport",
            max_steps
        ));
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    let verdict = match status.as_str() {
        "readyToReport" => "safeResponseReady",
        "dryRun" => "selectedSafeAction",
        "blocked" => "safeLoopBlocked",
        _ => "stepLimitReached",
    };
    let safe_to_say = match status.as_str() {
        "readyToReport" => {
            vec![
                "Autopilot loop advanced offline evidence until the run was ready to report."
                    .into(),
            ]
        }
        "dryRun" => vec![
            "Autopilot loop selected the next safe offline action without executing it.".into(),
        ],
        _ => vec!["Autopilot loop stopped before a report-ready state.".into()],
    };
    let do_not_say = vec![
        "Do not claim live Studio mutation, apply success, playtest success, rollback readiness, publish readiness, or production readiness from loop alone.".into(),
        "Do not claim the loop executed arbitrary shell commands; it only uses whitelisted offline Autopilot handlers.".into(),
        "Do not report completion unless response.json is readyToSend and claim-check supports the exact wording.".into(),
    ];
    let mut artifacts = collect_planner_run_artifacts(Some(&options.run_dir));
    artifacts.insert("loop".into(), loop_path.to_string_lossy().to_string());
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "loopMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }
    let mut next_actions = build_loop_next_actions(&options.run_dir, &status);
    dedup_next_actions(&mut next_actions);
    let agent_brief = build_loop_agent_brief(
        &status,
        final_cycle_status.as_deref(),
        final_cycle_verdict.as_deref(),
        iterations.len(),
    );

    Ok(LoopReport {
        schema_version: "rs.autopilot.loop.v1".into(),
        generated_at: now_stamp(),
        run_dir: options.run_dir.to_string_lossy().to_string(),
        loop_path: loop_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict: verdict.into(),
        max_steps,
        iteration_count: iterations.len(),
        dry_run: options.dry_run,
        iterations,
        safe_to_say,
        do_not_say,
        artifacts,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn loop_iteration(
    index: usize,
    cycle: &CycleReport,
    act: Option<&ActReport>,
    summary: &str,
) -> LoopIteration {
    let mut artifacts = vec![cycle.cycle_path.clone()];
    if let Some(markdown) = &cycle.markdown_path {
        artifacts.push(markdown.clone());
    }
    if let Some(act) = act {
        artifacts.push(act.act_path.clone());
        if let Some(markdown) = &act.markdown_path {
            artifacts.push(markdown.clone());
        }
    }
    LoopIteration {
        id: format!("LOOP-{index:03}"),
        cycle_status: cycle.status.clone(),
        cycle_verdict: cycle.verdict.clone(),
        act_status: act.map(|report| report.status.clone()),
        act_verdict: act.map(|report| report.verdict.clone()),
        command_kind: act.and_then(|report| report.command_kind.clone()),
        selected_command: act.and_then(|report| report.selected_command.clone()),
        summary: summary.into(),
        artifacts,
    }
}

fn build_loop_next_actions(run_dir: &Path, status: &str) -> Vec<CoachAction> {
    let run = command_arg(run_dir.to_string_lossy().as_ref());
    match status {
        "readyToReport" => vec![coach_action(
            1,
            "Read checked response",
            Some(format!("rs autopilot respond {run} --format json")),
            "The loop ended at readyToReport; use checked response wording before updating the creator.",
            false,
            false,
        )],
        "dryRun" => vec![coach_action(
            1,
            "Run one safe action",
            Some(format!("rs autopilot act {run} --format json")),
            "Dry-run stopped before execution; run act to perform one whitelisted offline action.",
            false,
            false,
        )],
        _ => vec![coach_action(
            1,
            "Diagnose loop blocker",
            Some(format!("rs autopilot diagnose {run} --format json")),
            "The loop stopped before report-ready state; refresh diagnosis before continuing.",
            false,
            false,
        )],
    }
}

fn build_loop_agent_brief(
    status: &str,
    cycle_status: Option<&str>,
    cycle_verdict: Option<&str>,
    iteration_count: usize,
) -> String {
    match status {
        "readyToReport" => format!(
            "Loop reached readyToReport after {iteration_count} iteration(s). Use response.json and claim-check evidence for creator-facing wording."
        ),
        "dryRun" => "Loop dry-run selected the next safe offline action and stopped before execution.".into(),
        "blocked" => format!(
            "Loop is blocked after {iteration_count} iteration(s). Last cycle status: {}; verdict: {}.",
            cycle_status.unwrap_or("unknown"),
            cycle_verdict.unwrap_or("unknown")
        ),
        _ => format!(
            "Loop reached its step limit after {iteration_count} iteration(s). Last cycle status: {}; verdict: {}.",
            cycle_status.unwrap_or("unknown"),
            cycle_verdict.unwrap_or("unknown")
        ),
    }
}

fn build_roadmap_report(
    prompt: Option<&str>,
    root: &Path,
    limit: usize,
    roadmap_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<RoadmapReport> {
    let memory_path = roadmap_path.with_file_name("project-memory.json");
    let memory = build_memory_report(root, limit, &memory_path, None)?;
    let next_path = roadmap_path.with_file_name("next.json");
    let next = build_next_report(prompt, None, root, limit, &next_path, None)?;
    let active_run = memory.active_run.clone();
    let mut backlog = Vec::new();
    let mut warnings = merge_many_sorted(vec![memory.warnings.clone(), next.warnings.clone()]);
    let technical_blockers = memory
        .blockers
        .iter()
        .filter(|blocker| !blocker.starts_with("gameplay:"))
        .cloned()
        .collect::<Vec<_>>();
    let mut blockers = if next.status == "blocked" {
        merge_many_sorted(vec![next.blockers.clone(), technical_blockers])
    } else {
        warnings = merge_many_sorted(vec![
            warnings,
            memory.blockers.clone(),
            next.blockers.clone(),
        ]);
        Vec::new()
    };

    backlog.push(roadmap_item_from_action(
        "RM-001",
        phase_for_next_decision(&next.decision),
        next.recommendation.clone(),
    ));

    if let Some(active_run) = &active_run {
        if let Some(gap) = memory
            .gameplay_gaps
            .iter()
            .find(|gap| gap.severity == "blocker" && gap.command.is_some())
            .or_else(|| {
                memory
                    .gameplay_gaps
                    .iter()
                    .find(|gap| gap.severity == "warning" && gap.command.is_some())
            })
        {
            backlog.push(roadmap_item(
                "RM-010",
                "Patch highest-priority gameplay gap",
                10,
                "improve",
                gap.suggested_recipe.clone(),
                gap.command.clone(),
                &gap.message,
                gap.command
                    .as_deref()
                    .map(expected_artifacts_for_command)
                    .unwrap_or_default(),
                false,
                false,
            ));
        }
        backlog.push(roadmap_item(
            "RM-020",
            "Refresh active run certification",
            20,
            "stabilize",
            None,
            Some(format!(
                "rs autopilot certify {} --format json",
                active_run.run_dir
            )),
            "Keep go/no-go evidence current before handoff, sequencing, or live apply.",
            vec!["certification.json".into(), "certification.md".into()],
            false,
            false,
        ));
        if active_run.bundle_ok.is_some() {
            backlog.push(roadmap_item(
                "RM-021",
                "Verify active run bundle",
                21,
                "stabilize",
                None,
                Some(format!(
                    "rs autopilot verify-bundle --run-dir {} --format json",
                    active_run.run_dir
                )),
                "Prove the handoff bundle still matches local run artifacts.",
                vec!["bundle verification JSON".into()],
                false,
                false,
            ));
        } else {
            backlog.push(roadmap_item(
                "RM-021",
                "Create active run handoff",
                21,
                "stabilize",
                None,
                Some(format!(
                    "rs autopilot handoff {} --format json",
                    active_run.run_dir
                )),
                "Create or refresh the bundle and handoff packet before another agent resumes.",
                vec![
                    "handoff.json".into(),
                    "handoff.md".into(),
                    "bundle.json".into(),
                ],
                false,
                false,
            ));
        }
    }

    if let Some(prompt) = prompt.map(str::trim).filter(|prompt| !prompt.is_empty()) {
        let recipes = compose_prompt_recipes(prompt).unwrap_or_default();
        if recipes.is_empty() {
            backlog.push(roadmap_item(
                "RM-030",
                "Prepare custom planner packet",
                30,
                "build",
                None,
                Some(format!(
                    "rs autopilot planner-pack \"{}\" --format json",
                    shell_display_arg(prompt)
                )),
                "The prompt needs model planning; create a bounded planner packet instead of free-form mutation.",
                vec!["planner-pack.json".into(), "planner-pack.md".into()],
                false,
                false,
            ));
        } else {
            backlog.push(roadmap_item(
                "RM-030",
                "Plan requested feature stack",
                30,
                "build",
                Some(recipes.join(",")),
                Some(format!(
                    "rs autopilot compose \"{}\" --recipe {} --out .rs\\autopilot\\runs\\{} --format json",
                    shell_display_arg(prompt),
                    recipes.join(","),
                    slug(prompt)
                )),
                "Turn the creator request into a reviewable, non-mutating feature stack.",
                vec![
                    "request.json".into(),
                    "plan.json".into(),
                    "preview.json".into(),
                    "generated/".into(),
                ],
                false,
                false,
            ));
        }
    } else if active_run.is_none() {
        backlog.push(roadmap_item(
            "RM-030",
            "Draft starter-game architecture",
            30,
            "build",
            None,
            Some(
                "rs autopilot architect \"Create a complete Roblox starter game\" --format json"
                    .into(),
            ),
            "No prompt or active run exists; start with architecture before any live mutation.",
            vec!["architect.json".into(), "architect.md".into()],
            false,
            false,
        ));
    }

    backlog.push(roadmap_item(
        "RM-080",
        "Check live readiness before mutation",
        80,
        "live",
        None,
        Some("rs autopilot ready --timeout 90 --format json".into()),
        "Live bridge, Studio selection, protocol, and capability checks must pass before preview/apply.",
        vec!["readiness JSON stdout".into()],
        true,
        false,
    ));
    if let Some(active_run) = &active_run {
        backlog.push(roadmap_item(
            "RM-081",
            "Prepare live playtest checklist",
            81,
            "live",
            None,
            Some(format!(
                "rs autopilot playtest --run-dir {} --format json",
                active_run.run_dir
            )),
            "Convert the current feature stack into concrete Studio play-mode proof steps.",
            vec!["playtest-plan.json".into(), "playtest-plan.md".into()],
            false,
            false,
        ));
    }
    backlog.push(roadmap_item(
        "RM-090",
        "Refresh project memory",
        90,
        "continuity",
        None,
        Some(format!(
            "rs autopilot memory --root {} --limit {} --format json",
            root.to_string_lossy(),
            limit
        )),
        "Record the latest run state, recipes, gameplay gaps, blockers, and next actions.",
        vec!["project-memory.json".into(), "project-memory.md".into()],
        false,
        false,
    ));
    backlog.push(roadmap_item(
        "RM-091",
        "Refresh next-move packet",
        91,
        "continuity",
        None,
        Some(format!(
            "rs autopilot next{} --root {} --limit {} --format json",
            prompt
                .map(|text| format!(" \"{}\"", shell_display_arg(text)))
                .unwrap_or_default(),
            root.to_string_lossy(),
            limit
        )),
        "Keep the single recommended next move synchronized after roadmap work changes artifacts.",
        vec!["next.json".into(), "next.md".into()],
        false,
        false,
    ));

    dedup_roadmap_items(&mut backlog);
    let milestones = build_roadmap_milestones(&backlog, active_run.as_ref());
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    let status = if !blockers.is_empty() {
        "blocked"
    } else if active_run.is_some() {
        "readyToExecute"
    } else {
        "needsKickoff"
    }
    .to_string();
    let next_actions = roadmap_next_actions(&backlog, roadmap_path, root, limit, prompt);
    let agent_brief = build_roadmap_agent_brief(&status, prompt, active_run.as_ref(), &backlog);

    Ok(RoadmapReport {
        schema_version: "rs.autopilot.roadmap.v1".into(),
        generated_at: now_stamp(),
        roadmap_path: roadmap_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: root.to_string_lossy().to_string(),
        prompt: prompt.map(str::to_string),
        status,
        horizon: "next 3-5 agent moves".into(),
        active_run,
        milestones,
        backlog,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn roadmap_item_from_action(id: &str, phase: &str, action: CoachAction) -> RoadmapItem {
    let expected_artifacts = action
        .command
        .as_deref()
        .map(expected_artifacts_for_command)
        .unwrap_or_default();
    roadmap_item(
        id,
        &action.title,
        action.priority,
        phase,
        None,
        action.command,
        &action.reason,
        expected_artifacts,
        action.requires_live_studio,
        action.mutates_studio,
    )
}

fn roadmap_item(
    id: &str,
    title: &str,
    priority: u8,
    phase: &str,
    recipe: Option<String>,
    command: Option<String>,
    reason: &str,
    expected_artifacts: Vec<String>,
    requires_live_studio: bool,
    mutates_studio: bool,
) -> RoadmapItem {
    RoadmapItem {
        id: id.into(),
        title: title.into(),
        priority,
        phase: phase.into(),
        recipe,
        command,
        reason: reason.into(),
        expected_artifacts,
        requires_live_studio,
        mutates_studio,
    }
}

fn phase_for_next_decision(decision: &str) -> &'static str {
    match decision {
        "startOfflineKickoff" | "continueRun" => "build",
        "alignCreatorDecisions" | "resolveDecisionDrift" => "coordination",
        "satisfyCreatorPromise" => "fulfillment",
        "iterateGameplay" | "critiqueGameplay" => "improve",
        "rehearseLiveDemo" => "approval",
        "checkLiveReadiness" => "live",
        "resolveRunBlockers" | "certifyRun" | "refreshHandoff" => "stabilize",
        "inspectAppliedRun" => "continuity",
        _ => "stabilize",
    }
}

