fn dedup_roadmap_items(items: &mut Vec<RoadmapItem>) {
    items.sort_by(|left, right| {
        left.priority
            .cmp(&right.priority)
            .then(left.phase.cmp(&right.phase))
            .then(left.title.cmp(&right.title))
    });
    let mut seen = BTreeSet::new();
    items.retain(|item| {
        let key = format!("{}\n{}", item.title, item.command.as_deref().unwrap_or(""));
        seen.insert(key)
    });
}

fn build_roadmap_milestones(
    backlog: &[RoadmapItem],
    active_run: Option<&RunIndexEntry>,
) -> Vec<RoadmapMilestone> {
    let specs = [
        (
            "M1",
            "Stabilize Current Evidence",
            "stabilize",
            "Make the active run trustworthy enough for handoff or continuation.",
            vec![
                "bundle and certification artifacts are current",
                "technical blockers are resolved before mutation",
            ],
        ),
        (
            "M2",
            "Improve Playability",
            "improve",
            "Close gameplay gaps before spending a live Studio apply.",
            vec![
                "gameplay critique is refreshed",
                "candidate reaches playableSlice or needsCustomPlan is explicit",
            ],
        ),
        (
            "M3",
            "Build Next Feature",
            "build",
            "Create the next reviewable offline feature stack.",
            vec![
                "plan and preview artifacts exist",
                "generated sources are available for source audit",
            ],
        ),
        (
            "M4",
            "Live Proof",
            "live",
            "Move toward Studio only after offline evidence is clean.",
            vec![
                "ready passes for the selected Studio session",
                "playtest checklist exists before claiming gameplay success",
            ],
        ),
        (
            "M5",
            "Continuity Handoff",
            "continuity",
            "Leave durable state for the next AI session.",
            vec![
                "project memory is refreshed",
                "next move packet is refreshed",
            ],
        ),
    ];
    specs
        .into_iter()
        .filter_map(|(id, title, phase, objective, exit_criteria)| {
            let backlog_ids = backlog
                .iter()
                .filter(|item| item.phase == phase)
                .map(|item| item.id.clone())
                .collect::<Vec<_>>();
            if backlog_ids.is_empty() {
                return None;
            }
            let status = if id == "M1" && active_run.is_some()
                || id == "M2" && backlog.iter().any(|item| item.phase == "improve")
                || id == "M3" && active_run.is_none()
            {
                "active"
            } else {
                "pending"
            };
            Some(RoadmapMilestone {
                id: id.into(),
                title: title.into(),
                status: status.into(),
                objective: objective.into(),
                backlog_ids,
                exit_criteria: exit_criteria.into_iter().map(str::to_string).collect(),
            })
        })
        .collect()
}

fn roadmap_next_actions(
    backlog: &[RoadmapItem],
    roadmap_path: &Path,
    root: &Path,
    limit: usize,
    prompt: Option<&str>,
) -> Vec<CoachAction> {
    let mut actions = Vec::new();
    if let Some(first) = backlog.first() {
        actions.push(CoachAction {
            priority: 1,
            title: first.title.clone(),
            command: first.command.clone(),
            reason: first.reason.clone(),
            requires_live_studio: first.requires_live_studio,
            mutates_studio: first.mutates_studio,
        });
    }
    actions.push(CoachAction {
        priority: 9,
        title: "Refresh roadmap".into(),
        command: Some(format!(
            "rs autopilot roadmap{} --root {} --limit {} --out {} --format json",
            prompt
                .map(|text| format!(" \"{}\"", shell_display_arg(text)))
                .unwrap_or_default(),
            root.to_string_lossy(),
            limit,
            roadmap_path.to_string_lossy()
        )),
        reason: "Regenerate the roadmap after any backlog command creates or changes artifacts."
            .into(),
        requires_live_studio: false,
        mutates_studio: false,
    });
    actions
}

fn build_roadmap_agent_brief(
    status: &str,
    prompt: Option<&str>,
    active_run: Option<&RunIndexEntry>,
    backlog: &[RoadmapItem],
) -> String {
    let lead = backlog
        .first()
        .map(|item| item.title.as_str())
        .unwrap_or("No backlog item");
    if let Some(active_run) = active_run {
        format!(
            "Roadmap status {status}; continue from '{}' with {} backlog item(s). First move: {lead}.",
            active_run.plan_id,
            backlog.len()
        )
    } else if let Some(prompt) = prompt {
        format!(
            "Roadmap status {status}; no active run exists, so use the prompt '{}' to start offline. First move: {lead}.",
            prompt
        )
    } else {
        format!("Roadmap status {status}; no active run or prompt exists. First move: {lead}.")
    }
}

fn build_judgment_report(
    run_dir: &Path,
    judgment_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<JudgmentReport> {
    let run = build_run_index_entry(run_dir)?;
    let certification_path = run_dir.join("certification.json");
    let gameplay_path = run_dir.join("gameplay-critique.json");
    let bundle_path = run_dir.join("bundle.json");
    let playtest_path = run_dir.join("playtest-plan.json");
    let playtest_result_path = run_dir.join("playtest-result.json");
    let report_path = run_dir.join("report.md");
    let roadmap_path = run_dir.join("roadmap.json");
    let next_path = run_dir.join("next.json");

    let certification_memory = read_memory_certification(run_dir)?;
    let live_apply_evidence = read_live_apply_evidence(run_dir)?;
    let certification_verdict = if certification_path.exists() {
        read_json_file(&certification_path)?
            .get("verdict")
            .and_then(Value::as_str)
            .map(str::to_string)
    } else {
        None
    };
    let gameplay_memory = read_memory_gameplay(run_dir)?;
    let playtest_result_memory = read_memory_playtest_result(run_dir)?;
    let bundle_verification = if bundle_path.exists() {
        Some(verify_bundle_report(&bundle_path, Some(run_dir))?)
    } else {
        None
    };

    let mut artifacts = BTreeMap::new();
    for (name, path, role) in [
        ("plan", run_dir.join("plan.json"), "required plan contract"),
        (
            "preview",
            run_dir.join("preview.json"),
            "offline dry-run and integrity seal",
        ),
        (
            "generated",
            run_dir.join("generated"),
            "materialized generated Luau",
        ),
        (
            "sourceAudit",
            run_dir.join("source-audit.json"),
            "generated Luau safety scan",
        ),
        (
            "bundle",
            bundle_path.clone(),
            "hashed handoff artifact manifest",
        ),
        (
            "handoff",
            run_dir.join("handoff.json"),
            "agent continuity packet",
        ),
        (
            "certification",
            certification_path.clone(),
            "deterministic go/no-go gates",
        ),
        (
            "gameplayCritique",
            gameplay_path.clone(),
            "playability design verdict",
        ),
        (
            "playtestPlan",
            playtest_path.clone(),
            "live play-mode proof checklist",
        ),
        (
            "playtestResult",
            playtest_result_path.clone(),
            "recorded live playtest proof",
        ),
        (
            "report",
            report_path.clone(),
            "durable apply/report summary",
        ),
        (
            "roadmap",
            roadmap_path.clone(),
            "multi-step execution backlog",
        ),
        ("next", next_path.clone(), "single next-move packet"),
    ] {
        artifacts.insert(
            name.into(),
            JudgmentArtifact {
                path: path.to_string_lossy().to_string(),
                exists: path.exists(),
                role: role.into(),
            },
        );
    }

    let gameplay_blockers = gameplay_memory
        .blockers
        .iter()
        .map(|blocker| format!("gameplay: {blocker}"))
        .collect::<Vec<_>>();
    let mut blockers = merge_many_sorted(vec![
        run.blockers.clone(),
        certification_memory.blockers.clone(),
        bundle_verification
            .as_ref()
            .map(|bundle| bundle.blockers.clone())
            .unwrap_or_default()
            .into_iter()
            .map(|blocker| format!("bundle: {blocker}"))
            .collect(),
    ]);
    let mut warnings = merge_many_sorted(vec![
        run.warnings.clone(),
        certification_memory.warnings.clone(),
        gameplay_memory
            .warnings
            .iter()
            .map(|warning| format!("gameplay: {warning}"))
            .collect(),
        playtest_result_memory
            .warnings
            .iter()
            .map(|warning| format!("playtest result: {warning}"))
            .collect(),
    ]);
    blockers.extend(
        playtest_result_memory
            .blockers
            .iter()
            .map(|blocker| format!("playtest result: {blocker}")),
    );
    let mut missing_artifacts = Vec::new();
    for (name, artifact) in &artifacts {
        if !artifact.exists {
            missing_artifacts.push(format!("{name}: {}", artifact.path));
        }
    }
    if !certification_path.exists() {
        warnings.push(
            "certification.json is missing; run `rs autopilot certify` before live apply".into(),
        );
    }
    if !gameplay_path.exists() {
        warnings.push("gameplay-critique.json is missing; run `rs autopilot critique` before judging playability".into());
    }
    if !playtest_path.exists() {
        warnings.push("playtest-plan.json is missing; create a live proof checklist before claiming gameplay success".into());
    }
    if !playtest_result_path.exists() {
        warnings.push("playtest-result.json is missing; record live playtest evidence before claiming demo readiness".into());
    }
    if bundle_path.exists() {
        if let Some(bundle) = &bundle_verification {
            if !bundle.ok {
                blockers.push(
                    "bundle verification failed; refresh handoff before trusting artifacts".into(),
                );
            }
        }
    } else {
        warnings.push(
            "bundle.json is missing; run `rs autopilot handoff` before handoff or apply".into(),
        );
    }

    let playable = gameplay_memory.verdict.as_deref() == Some("playableSlice");
    let live_apply_verified = certification_memory.applied == Some(true);
    let bundle_ok = bundle_verification.as_ref().is_some_and(|bundle| bundle.ok);
    let playtest_proof = playtest_result_memory.production_proof == Some(true);
    let playtest_needs_repair = playtest_result_memory.exists
        && (playtest_result_memory.accepted != Some(true)
            || playtest_result_memory.result.as_deref() != Some("passed"));
    let rollback_verified = live_apply_evidence.rollback_verified;
    let production_ready = playable
        && live_apply_verified
        && rollback_verified
        && bundle_ok
        && playtest_proof
        && blockers.is_empty();
    if !live_apply_verified {
        warnings
            .push("live apply has not been verified; judgment cannot be production-ready".into());
    }
    if live_apply_verified && !rollback_verified {
        let detail = live_apply_evidence
            .rollback_artifact
            .as_deref()
            .unwrap_or("missing rollbackArtifact");
        warnings.push(format!(
            "rollback evidence is not verified ({detail}); judgment cannot be production-ready"
        ));
    }
    if playtest_result_memory.exists {
        if playtest_result_memory.accepted != Some(true) {
            blockers.push("playtest result is present but not accepted".into());
        } else if playtest_result_memory.result.as_deref() != Some("passed") {
            blockers.push(format!(
                "playtest result is {}; improve or investigate before demo readiness",
                playtest_result_memory
                    .result
                    .as_deref()
                    .unwrap_or("unknown")
            ));
        } else if !playtest_proof {
            warnings
                .push("playtest result is passed but not eligible as production proof yet".into());
        }
    } else {
        warnings.push(
            "live playtest result evidence is not recorded; judgment cannot be production-ready"
                .into(),
        );
    }

    let (status, verdict, score) = if production_ready {
        ("productionReady", "demoReady", 100)
    } else if !blockers.is_empty() {
        ("blocked", "blocked", 0)
    } else if !playable {
        ("needsImprovement", "needsGameplayWork", 35)
    } else if certification_memory.ready_to_apply != Some(true)
        && certification_memory.applied != Some(true)
    {
        ("needsCertification", "needsGoNoGoEvidence", 55)
    } else if !bundle_ok {
        ("needsHandoff", "needsTrustedBundle", 60)
    } else if live_apply_verified && !rollback_verified {
        ("appliedNeedsLiveProof", "needsRollbackEvidence", 82)
    } else if live_apply_verified && !playtest_proof {
        ("appliedNeedsPlaytestEvidence", "appliedNeedsLiveProof", 82)
    } else if live_apply_verified {
        ("appliedNeedsPlaytestEvidence", "appliedNeedsLiveProof", 82)
    } else {
        ("readyForLive", "readyForLiveApply", 75)
    };
    if !playable {
        blockers.extend(gameplay_blockers);
    }

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    missing_artifacts.sort();
    missing_artifacts.dedup();

    let next_actions = build_judgment_next_actions(
        run_dir,
        status,
        playable,
        bundle_ok,
        certification_path.exists(),
        playtest_path.exists(),
        playtest_proof,
        playtest_needs_repair,
    );
    let certification = JudgmentCertification {
        path: certification_path.to_string_lossy().to_string(),
        exists: certification_path.exists(),
        verdict: certification_verdict,
        ready_to_apply: certification_memory.ready_to_apply,
        safe_to_handoff: certification_memory.safe_to_handoff,
        applied: certification_memory.applied,
    };
    let gameplay = JudgmentGameplay {
        path: gameplay_path.to_string_lossy().to_string(),
        exists: gameplay_path.exists(),
        verdict: gameplay_memory.verdict,
        score: gameplay_memory.score,
        gap_count: gameplay_memory.gaps.len(),
    };
    let bundle = JudgmentBundle {
        path: bundle_path.to_string_lossy().to_string(),
        exists: bundle_path.exists(),
        ok: bundle_verification.as_ref().map(|bundle| bundle.ok),
        verified: bundle_verification.as_ref().map(|bundle| bundle.verified),
        artifact_count: bundle_verification
            .as_ref()
            .map(|bundle| bundle.artifact_count),
    };
    let playtest_result = JudgmentPlaytestResult {
        path: playtest_result_path.to_string_lossy().to_string(),
        exists: playtest_result_memory.exists,
        result: playtest_result_memory.result,
        accepted: playtest_result_memory.accepted,
        production_proof: playtest_result_memory.production_proof,
        evidence_count: playtest_result_memory.evidence_count,
    };
    let agent_brief = build_judgment_agent_brief(status, verdict, &run.plan_id, score);

    Ok(JudgmentReport {
        schema_version: "rs.autopilot.judgment.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        judgment_path: judgment_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status: status.into(),
        verdict: verdict.into(),
        score,
        production_ready,
        live_apply_verified,
        rollback_verified,
        playable,
        certification,
        gameplay,
        bundle,
        playtest_result,
        artifacts,
        blockers,
        warnings,
        missing_artifacts,
        next_actions,
        agent_brief,
    })
}

fn build_judgment_next_actions(
    run_dir: &Path,
    status: &str,
    playable: bool,
    bundle_ok: bool,
    has_certification: bool,
    has_playtest_plan: bool,
    has_playtest_proof: bool,
    playtest_needs_repair: bool,
) -> Vec<CoachAction> {
    let run_text = run_dir.to_string_lossy();
    let mut actions = Vec::new();
    match status {
        "blocked" if playtest_needs_repair => actions.push(coach_action(
            1,
            "Plan repairs from playtest evidence",
            Some(format!("rs autopilot repair-plan {run_text} --format json")),
            "The blocking evidence came from live playtest results; convert it into a repair packet.",
            false,
            false,
        )),
        "blocked" => actions.push(coach_action(
            1,
            "Refresh handoff and resolve blockers",
            Some(format!("rs autopilot handoff {run_text} --format json")),
            "The run has blocking evidence; refresh handoff before any mutation.",
            false,
            false,
        )),
        "needsImprovement" => actions.push(coach_action(
            1,
            "Iterate toward a playable slice",
            Some(format!(
                "rs autopilot iterate --run-dir {run_text} --max-steps 3 --max-recipes 2 --format json"
            )),
            "Gameplay is not yet judged playable; improve offline before live apply.",
            false,
            false,
        )),
        "needsCertification" => actions.push(coach_action(
            1,
            "Certify the run",
            Some(format!("rs autopilot certify {run_text} --format json")),
            "Create fresh deterministic go/no-go evidence.",
            false,
            false,
        )),
        "needsHandoff" => actions.push(coach_action(
            1,
            "Refresh trusted handoff bundle",
            Some(format!("rs autopilot handoff {run_text} --format json")),
            "The run needs a verified bundle before another agent can trust it.",
            false,
            false,
        )),
        "readyForLive" => {
            actions.push(coach_action(
                1,
                "Prepare live demo rehearsal",
                Some(format!("rs autopilot rehearsal {run_text} --format json")),
                "Turn approval, readiness, apply, proof, and closeout into one non-mutating runbook before live work.",
                false,
                false,
            ));
            actions.push(coach_action(
                2,
                "Check live Studio readiness",
                Some("rs autopilot ready --timeout 90 --format json".into()),
                "Offline evidence is clean enough to approach live Studio, but readiness must pass first.",
                true,
                false,
            ));
            actions.push(coach_action(
                3,
                "Apply after explicit approval",
                Some(format!(
                    "rs autopilot apply --plan {} --yes --rollback-on-error --validate",
                    run_dir.join("plan.json").to_string_lossy()
                )),
                "Keep live mutation behind explicit approval, rollback, and validation.",
                true,
                true,
            ));
        }
        "appliedNeedsPlaytestEvidence" => actions.push(coach_action(
            1,
            "Run the live playtest checklist",
            Some(format!(
                "rs autopilot record-playtest {run_text} --result passed --evidence <evidence>"
            )),
            "The run applied, but gameplay success still needs live play evidence.",
            false,
            false,
        )),
        "appliedNeedsLiveProof" => actions.push(coach_action(
            1,
            "Refresh apply and rollback evidence",
            Some(format!("rs autopilot report {run_text}")),
            "The run applied, but rollback evidence is missing or unverifiable.",
            false,
            false,
        )),
        "productionReady" => actions.push(coach_action(
            1,
            "Keep judgment current",
            Some(format!("rs autopilot judge {run_text} --format json")),
            "The run has live proof; refresh judgment after any artifact or Studio change.",
            false,
            false,
        )),
        _ => {}
    }
    if playable && !has_playtest_plan {
        actions.push(coach_action(
            3,
            "Create playtest checklist",
            Some(format!(
                "rs autopilot playtest --run-dir {run_text} --format json"
            )),
            "Playable slices need concrete live proof steps before success is claimed.",
            false,
            false,
        ));
    }
    if !has_certification {
        actions.push(coach_action(
            4,
            "Create certification packet",
            Some(format!("rs autopilot certify {run_text} --format json")),
            "Certification records deterministic go/no-go gates.",
            false,
            false,
        ));
    }
    if !bundle_ok {
        actions.push(coach_action(
            5,
            "Refresh bundle and handoff",
            Some(format!("rs autopilot handoff {run_text} --format json")),
            "A verified bundle is required for trusted continuation.",
            false,
            false,
        ));
    }
    if playable && !has_playtest_proof {
        actions.push(coach_action(
            6,
            "Record live playtest evidence",
            Some(format!(
                "rs autopilot record-playtest {run_text} --result passed --evidence <evidence>"
            )),
            "A playable run needs recorded live proof before any production-ready claim.",
            false,
            false,
        ));
    }
    if status != "productionReady" {
        actions.push(coach_action(
            9,
            "Refresh judgment",
            Some(format!("rs autopilot judge {run_text} --format json")),
            "Regenerate the verdict after any artifact or live-state change.",
            false,
            false,
        ));
    }
    dedup_next_actions(&mut actions);
    actions
}

fn build_judgment_agent_brief(status: &str, verdict: &str, plan_id: &str, score: u8) -> String {
    match status {
        "productionReady" => format!(
            "Run '{plan_id}' is {verdict} with score {score}. Live apply, rollback, gameplay, bundle, and playtest proof are recorded."
        ),
        "readyForLive" => format!(
            "Run '{plan_id}' is {verdict} with score {score}. It is not production-ready; run live readiness, approved apply, validation, and playtest evidence next."
        ),
        "appliedNeedsLiveProof" => format!(
            "Run '{plan_id}' applied but still needs verified rollback evidence before any demo-ready claim."
        ),
        "appliedNeedsPlaytestEvidence" => format!(
            "Run '{plan_id}' applied but still needs playtest evidence before any demo-ready claim."
        ),
        "needsImprovement" => format!(
            "Run '{plan_id}' is not playable enough yet. Iterate offline before live Studio mutation."
        ),
        "blocked" => {
            format!("Run '{plan_id}' is blocked. Resolve listed blockers before live Studio mutation.")
        }
        _ => format!("Run '{plan_id}' judgment is {verdict}. Follow next actions in order."),
    }
}

fn resolve_critique_paths(options: &CritiqueOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot critique requires --run-dir or --plan".into(),
        )),
    }
}

fn build_gameplay_critique_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    critique_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<GameplayCritiqueReport> {
    let explain = build_explain_report(plan_path, plan);
    let recipes = recipes_for_run(run_dir, plan)?;
    let signals = GameplaySignals::from_run(run_dir, plan, &recipes);
    let dimensions = gameplay_critique_dimensions(&signals, run_dir, &plan.request.prompt);
    let strengths = dimensions
        .iter()
        .filter(|dimension| dimension.status == "pass")
        .map(|dimension| format!("{}: {}", dimension.title, dimension.evidence.join("; ")))
        .collect::<Vec<_>>();
    let mut gaps = gameplay_gaps_for_dimensions(&dimensions, run_dir, &plan.request.prompt);
    let mut blockers = explain.blockers.clone();
    let mut warnings = explain.warnings.clone();

    if dimensions
        .iter()
        .any(|dimension| dimension.id == "core-loop" && dimension.status != "pass")
    {
        blockers.push(
            "planned slice has no clear repeatable player loop; add a core-loop recipe before live apply"
                .into(),
        );
    }
    if dimensions
        .iter()
        .any(|dimension| dimension.id == "interaction" && dimension.status == "missing")
    {
        blockers.push(
            "planned slice has no obvious player interaction surface such as touch, prompt, tool, UI button, or teleport"
                .into(),
        );
    }
    if dimensions
        .iter()
        .any(|dimension| dimension.id == "verification" && dimension.status == "missing")
    {
        warnings.push(
            "planned slice lacks verification operations; add validate, deps, publishCheck, or smoke before handoff"
                .into(),
        );
    }

    let score = average_dimension_score(&dimensions);
    let weak_core_loop = dimensions
        .iter()
        .any(|dimension| dimension.id == "core-loop" && dimension.status != "pass");
    let missing_interaction = dimensions
        .iter()
        .any(|dimension| dimension.id == "interaction" && dimension.status == "missing");
    let verdict = if !explain.blockers.is_empty() {
        "blocked"
    } else if weak_core_loop || missing_interaction {
        "needsGameplayLoop"
    } else if score >= 78
        && dimensions
            .iter()
            .all(|dimension| dimension.status != "missing")
    {
        "playableSlice"
    } else if score >= 58 {
        "needsPolish"
    } else {
        "needsGameplayLoop"
    }
    .to_string();

    if gaps.is_empty() && verdict == "playableSlice" {
        gaps.push(GameplayCritiqueGap {
            severity: "info".into(),
            category: "next-loop".into(),
            message: "Slice covers the main gameplay dimensions; next work should tune balance, UX copy, art, and live playtest feedback.".into(),
            suggested_recipe: None,
            command: Some("rs autopilot ready --timeout 90 --format json".into()),
        });
    }

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    gaps.sort_by(|left, right| {
        critique_severity_rank(&left.severity)
            .cmp(&critique_severity_rank(&right.severity))
            .then(left.category.cmp(&right.category))
    });

    let mut next_actions = Vec::new();
    if verdict != "playableSlice" {
        if let Some(gap) = gaps.iter().find(|gap| gap.command.is_some()) {
            next_actions.push(CoachAction {
                priority: 1,
                title: "Patch the weakest gameplay gap".into(),
                command: gap.command.clone(),
                reason: gap.message.clone(),
                requires_live_studio: false,
                mutates_studio: false,
            });
        }
    }
    next_actions.push(CoachAction {
        priority: 2,
        title: "Refresh certification after critique".into(),
        command: Some(format!(
            "rs autopilot certify {} --format json",
            run_dir.to_string_lossy()
        )),
        reason:
            "Certification remains the go/no-go gate after any plan or generated-source change."
                .into(),
        requires_live_studio: false,
        mutates_studio: false,
    });
    if verdict == "playableSlice" {
        next_actions.push(CoachAction {
            priority: 3,
            title: "Check live Studio readiness".into(),
            command: Some("rs autopilot ready --timeout 90 --format json".into()),
            reason: "The slice is design-complete enough to move toward live preview/apply once Studio is available."
                .into(),
            requires_live_studio: true,
            mutates_studio: false,
        });
    }
    next_actions.push(CoachAction {
        priority: 8,
        title: "Update project memory with design state".into(),
        command: Some("rs autopilot memory --root .rs\\autopilot\\runs --format json".into()),
        reason:
            "Project memory should record the active run and its design gaps for the next AI agent."
                .into(),
        requires_live_studio: false,
        mutates_studio: false,
    });

    let agent_brief = build_gameplay_critique_agent_brief(
        &plan.request.prompt,
        &verdict,
        score,
        &dimensions,
        &gaps,
    );

    Ok(GameplayCritiqueReport {
        schema_version: "rs.autopilot.gameplay-critique.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        critique_path: critique_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        verdict,
        score,
        recipes,
        strengths,
        dimensions,
        gaps,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

#[derive(Debug)]
struct GameplaySignals {
    recipes: BTreeSet<String>,
    operation_kinds: BTreeSet<String>,
    created_paths: Vec<String>,
    source_blob: String,
    has_server_script: bool,
    has_client_script: bool,
    has_ui_path: bool,
}

impl GameplaySignals {
    fn from_run(run_dir: &Path, plan: &AutopilotPlan, recipes: &[String]) -> Self {
        let operation_kinds = plan
            .operations
            .iter()
            .map(|operation| operation.kind.clone())
            .collect::<BTreeSet<_>>();
        let generated_files = generated_files_for_plan(plan);
        let created_paths = created_paths_for_plan(plan);
        let mut source_blob = String::new();
        source_blob.push_str(&plan.request.prompt);
        source_blob.push('\n');
        source_blob.push_str(&created_paths.join("\n"));
        source_blob.push('\n');
        source_blob.push_str(&generated_files.join("\n"));
        source_blob.push('\n');
        source_blob.push_str(
            &operation_kinds
                .iter()
                .cloned()
                .collect::<Vec<_>>()
                .join("\n"),
        );

        let mut source_bytes = 0usize;
        for source_path in &generated_files {
            if source_bytes >= 256 * 1024 {
                break;
            }
            if let Ok(path) = safe_join(run_dir, source_path) {
                if let Ok(source) = std::fs::read_to_string(path) {
                    let remaining = 256 * 1024 - source_bytes;
                    let snippet = source.chars().take(remaining).collect::<String>();
                    source_bytes += snippet.len();
                    source_blob.push('\n');
                    source_blob.push_str(&snippet);
                }
            }
        }

        let lower_files = generated_files
            .iter()
            .map(|path| path.to_ascii_lowercase())
            .collect::<Vec<_>>();
        let lower_paths = created_paths
            .iter()
            .map(|path| path.to_ascii_lowercase())
            .collect::<Vec<_>>();
        Self {
            recipes: recipes.iter().cloned().collect(),
            operation_kinds,
            created_paths,
            has_server_script: lower_files.iter().any(|path| path.contains("server.lua")),
            has_client_script: lower_files.iter().any(|path| path.contains("client.lua")),
            has_ui_path: lower_paths
                .iter()
                .any(|path| path.contains("startergui") || path.contains("gui")),
            source_blob: source_blob.to_ascii_lowercase(),
        }
    }

    fn has_recipe(&self, names: &[&str]) -> bool {
        names.iter().any(|name| self.recipes.contains(*name))
    }

    fn has_kind(&self, names: &[&str]) -> bool {
        names
            .iter()
            .any(|name| self.operation_kinds.contains(*name))
    }

    fn contains_any(&self, needles: &[&str]) -> bool {
        needles
            .iter()
            .any(|needle| self.source_blob.contains(&needle.to_ascii_lowercase()))
    }
}

fn gameplay_critique_dimensions(
    signals: &GameplaySignals,
    run_dir: &Path,
    prompt: &str,
) -> Vec<GameplayCritiqueDimension> {
    let mut dimensions = Vec::new();
    dimensions.push(critique_dimension(
        "core-loop",
        "Repeatable Core Loop",
        if signals.has_recipe(&[
            "tycoonCore",
            "roundManager",
            "obbyCheckpoint",
            "enemyEncounter",
        ]) || signals.contains_any(&[
            "dropper",
            "collector",
            "checkpoint",
            "enemy",
            "round",
            "questserver",
            "daily quest",
            "objective",
        ]) {
            "pass"
        } else if signals.has_recipe(&["collectibleCoin", "starterShop", "questSystem"]) {
            "partial"
        } else {
            "missing"
        },
        vec![
            "tycoon, round, obby, enemy, daily quest, or objective loop evidence".into(),
            recipe_evidence(
                signals,
                &[
                    "tycoonCore",
                    "roundManager",
                    "obbyCheckpoint",
                    "enemyEncounter",
                ],
            ),
        ],
        vec!["No repeatable activity loop was found.".into()],
        "Add a recipe that creates a repeatable play pattern before adding more support systems.",
        Some("tycoonCore"),
        run_dir,
        prompt,
    ));
    dimensions.push(critique_dimension(
        "interaction",
        "Player Interaction",
        if signals.has_recipe(&[
            "collectibleCoin",
            "obbyCheckpoint",
            "toolSystem",
            "enemyEncounter",
            "npcInteraction",
            "tycoonCore",
            "lobbyTeleport",
        ]) || signals.contains_any(&[
            "proximityprompt",
            ".touched",
            "activated:",
            "mousebutton1click",
            "teleport",
        ]) {
            "pass"
        } else if signals.has_ui_path || signals.has_client_script {
            "partial"
        } else {
            "missing"
        },
        vec![
            "touch, prompt, tool, UI button, teleport, or enemy interaction evidence".into(),
            recipe_evidence(signals, &["collectibleCoin", "toolSystem", "enemyEncounter", "npcInteraction"]),
        ],
        vec!["The plan may create systems, but it does not show how a player touches or triggers them.".into()],
        "Add an interaction surface such as collectibles, prompts, tools, enemies, or teleport pads.",
        Some("collectibleCoin"),
        run_dir,
        prompt,
    ));
    dimensions.push(critique_dimension(
        "rewards-economy",
        "Rewards And Economy",
        if signals.has_recipe(&[
            "starterShop",
            "collectibleCoin",
            "tycoonCore",
            "saveDataScaffold",
            "inventorySystem",
            "enemyEncounter",
            "questSystem",
        ]) || signals.contains_any(&["leaderstats", "coins", "cash", "reward", "purchase"])
        {
            "pass"
        } else {
            "missing"
        },
        vec![
            "coins, cash, reward, purchase, inventory, or leaderstats evidence".into(),
            recipe_evidence(
                signals,
                &[
                    "starterShop",
                    "collectibleCoin",
                    "tycoonCore",
                    "saveDataScaffold",
                ],
            ),
        ],
        vec!["No reward currency, unlock, shop, or player profile scaffold was found.".into()],
        "Add rewards that connect player action to visible progression.",
        Some("collectibleCoin"),
        run_dir,
        prompt,
    ));
    dimensions.push(critique_dimension(
        "progression",
        "Progression And Persistence",
        if signals.has_recipe(&[
            "saveDataScaffold",
            "questSystem",
            "obbyCheckpoint",
            "tycoonCore",
            "inventorySystem",
        ]) || signals.contains_any(&[
            "datastore",
            "checkpoint",
            "questserver",
            "daily quest",
            "objective",
            "upgrade",
            "profile",
        ])
        {
            "pass"
        } else if signals.has_recipe(&["roundManager", "enemyEncounter"]) {
            "partial"
        } else {
            "missing"
        },
        vec![
            "save data, checkpoints, quest server, objectives, upgrades, inventory, or profile evidence".into(),
            recipe_evidence(
                signals,
                &[
                    "saveDataScaffold",
                    "questSystem",
                    "obbyCheckpoint",
                    "tycoonCore",
                ],
            ),
        ],
        vec![
            "The slice has no durable sense of progress across play sessions or objectives.".into(),
        ],
        "Add save data, quests, checkpoints, or upgrades so the player can build toward something.",
        Some("saveDataScaffold"),
        run_dir,
        prompt,
    ));
    dimensions.push(critique_dimension(
        "feedback-ui",
        "Feedback And UI",
        if signals.has_ui_path
            || signals.has_client_script
            || signals.has_recipe(&[
                "starterShop",
                "questSystem",
                "inventorySystem",
                "adminPanel",
                "obbyCheckpoint",
                "tycoonCore",
                "enemyEncounter",
                "npcInteraction",
            ])
            || signals.contains_any(&["textlabel", "screengui", "remoteevent"])
        {
            "pass"
        } else if signals.has_kind(&["createInstance", "upsertScript"]) {
            "partial"
        } else {
            "missing"
        },
        vec![
            "StarterGui, LocalScript, ScreenGui, TextLabel, or RemoteEvent evidence".into(),
            format!("client script: {}", signals.has_client_script),
        ],
        vec![
            "The player may not see feedback for progress, purchases, objectives, or errors."
                .into(),
        ],
        "Add HUD or feedback UI for state changes the player should notice.",
        Some("questSystem"),
        run_dir,
        prompt,
    ));
    dimensions.push(critique_dimension(
        "onboarding-navigation",
        "Onboarding And Navigation",
        if signals.has_recipe(&[
            "lobbyTeleport",
            "npcInteraction",
            "obbyCheckpoint",
            "tycoonCore",
        ]) || signals.contains_any(&["guide", "lobby", "spawn", "teleport", "checkpoint"])
        {
            "pass"
        } else if signals
            .created_paths
            .iter()
            .any(|path| path.to_ascii_lowercase().contains("workspace"))
        {
            "partial"
        } else {
            "missing"
        },
        vec![
            "guide NPC, lobby, spawn, teleport, checkpoint, or map marker evidence".into(),
            recipe_evidence(
                signals,
                &["lobbyTeleport", "npcInteraction", "obbyCheckpoint"],
            ),
        ],
        vec!["The plan does not clearly guide a new player to the next action.".into()],
        "Add a guide NPC, lobby teleport, checkpoint path, or visible starting objective.",
        Some("npcInteraction"),
        run_dir,
        prompt,
    ));
    dimensions.push(critique_dimension(
        "server-authority",
        "Server Authority And Multiplayer Safety",
        if signals.has_server_script
            && (signals.contains_any(&["onserverevent", "players.playeradded", "leaderstats"])
                || signals.has_kind(&["validate", "publishCheck", "deps"])) {
            "pass"
        } else if signals.has_server_script {
            "partial"
        } else {
            "missing"
        },
        vec![
            "server script plus remotes, player-added, leaderstats, validate, deps, or publishCheck evidence".into(),
            format!("server script: {}", signals.has_server_script),
        ],
        vec!["The slice does not show enough server-side authority for multiplayer state.".into()],
        "Keep gameplay rewards and permissions server-owned, then validate dependency and publish readiness.",
        None,
        run_dir,
        prompt,
    ));
    dimensions.push(critique_dimension(
        "verification",
        "Verification Gates",
        if signals.has_kind(&["validate", "deps", "publishCheck", "smoke"])
            && run_dir.join("source-audit.json").exists()
            && run_dir.join("certification.json").exists() {
            "pass"
        } else if signals.has_kind(&["validate", "deps", "publishCheck", "smoke"]) {
            "partial"
        } else {
            "missing"
        },
        vec![
            "validate, deps, publishCheck, smoke, source-audit, and certification evidence".into(),
            format!(
                "source audit: {}, certification: {}",
                run_dir.join("source-audit.json").exists(),
                run_dir.join("certification.json").exists()
            ),
        ],
        vec!["The plan lacks enough proof gates for an AI handoff or live apply decision.".into()],
        "Run source audit and certification, and include validate/deps/publishCheck/smoke operations.",
        None,
        run_dir,
        prompt,
    ));
    dimensions.push(critique_dimension(
        "continuity",
        "Agent Continuity",
        if run_dir.join("bundle.json").exists()
            && run_dir.join("handoff.json").exists()
            && run_dir.join("preview.json").exists()
        {
            "pass"
        } else if run_dir.join("preview.json").exists() || run_dir.join("report.md").exists() {
            "partial"
        } else {
            "missing"
        },
        vec![
            "preview, bundle, handoff, report, and project-memory evidence".into(),
            format!(
                "bundle: {}, handoff: {}, preview: {}",
                run_dir.join("bundle.json").exists(),
                run_dir.join("handoff.json").exists(),
                run_dir.join("preview.json").exists()
            ),
        ],
        vec!["The next AI agent may not have enough durable state to resume safely.".into()],
        "Create a bundle, handoff packet, and memory refresh after every meaningful run.",
        None,
        run_dir,
        prompt,
    ));
    dimensions
}

fn critique_dimension(
    id: &str,
    title: &str,
    status: &str,
    evidence: Vec<String>,
    missing: Vec<String>,
    recommendation: &str,
    suggested_recipe: Option<&str>,
    run_dir: &Path,
    prompt: &str,
) -> GameplayCritiqueDimension {
    let score = match status {
        "pass" => 100,
        "partial" => 55,
        _ => 0,
    };
    let command = if status == "pass" {
        None
    } else {
        suggested_recipe.map(|recipe| {
            format!(
                " Suggested patch: `{}`",
                gameplay_patch_command(run_dir, prompt, recipe)
            )
        })
    };
    let recommendation = match command {
        Some(command) => format!("{recommendation}{command}"),
        None => recommendation.to_string(),
    };
    GameplayCritiqueDimension {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        score,
        evidence: evidence
            .into_iter()
            .filter(|item| !item.trim().is_empty())
            .collect(),
        missing: if status == "pass" {
            Vec::new()
        } else {
            missing
        },
        recommendation,
    }
}

fn gameplay_gaps_for_dimensions(
    dimensions: &[GameplayCritiqueDimension],
    run_dir: &Path,
    prompt: &str,
) -> Vec<GameplayCritiqueGap> {
    let mut gaps = Vec::new();
    for dimension in dimensions {
        if dimension.status == "pass" {
            continue;
        }
        let (severity, recipe) = match dimension.id.as_str() {
            "core-loop" => ("blocker", Some("tycoonCore")),
            "interaction" => ("blocker", Some("collectibleCoin")),
            "rewards-economy" => ("warning", Some("collectibleCoin")),
            "progression" => ("warning", Some("saveDataScaffold")),
            "feedback-ui" => ("warning", Some("questSystem")),
            "onboarding-navigation" => ("warning", Some("npcInteraction")),
            _ => ("info", None),
        };
        gaps.push(GameplayCritiqueGap {
            severity: severity.into(),
            category: dimension.id.clone(),
            message: dimension
                .missing
                .first()
                .cloned()
                .unwrap_or_else(|| format!("{} needs more evidence.", dimension.title)),
            suggested_recipe: recipe.map(str::to_string),
            command: recipe.map(|recipe| gameplay_patch_command(run_dir, prompt, recipe)),
        });
    }
    gaps
}

fn gameplay_patch_command(run_dir: &Path, prompt: &str, recipe: &str) -> String {
    let out = format!("{}-{}", run_dir.to_string_lossy(), slug(recipe));
    format!(
        "rs autopilot compose \"{}\" --recipe {} --out {} --format json",
        shell_display_arg(prompt),
        recipe,
        out
    )
}

fn recipe_evidence(signals: &GameplaySignals, recipes: &[&str]) -> String {
    let matched = recipes
        .iter()
        .filter(|recipe| signals.recipes.contains(**recipe))
        .copied()
        .collect::<Vec<_>>();
    if matched.is_empty() {
        String::new()
    } else {
        format!("matched recipes: {}", matched.join(", "))
    }
}

fn average_dimension_score(dimensions: &[GameplayCritiqueDimension]) -> u8 {
    if dimensions.is_empty() {
        return 0;
    }
    let total = dimensions
        .iter()
        .map(|dimension| u16::from(dimension.score))
        .sum::<u16>();
    ((total + (dimensions.len() as u16 / 2)) / dimensions.len() as u16) as u8
}

fn critique_severity_rank(severity: &str) -> u8 {
    match severity {
        "blocker" => 0,
        "warning" => 1,
        "info" => 2,
        _ => 3,
    }
}

fn build_gameplay_critique_agent_brief(
    prompt: &str,
    verdict: &str,
    score: u8,
    dimensions: &[GameplayCritiqueDimension],
    gaps: &[GameplayCritiqueGap],
) -> String {
    let weak_dimensions = dimensions
        .iter()
        .filter(|dimension| dimension.status != "pass")
        .map(|dimension| format!("{}={}", dimension.id, dimension.status))
        .collect::<Vec<_>>();
    let next_gap = gaps
        .iter()
        .find(|gap| gap.severity == "blocker")
        .or_else(|| gaps.iter().find(|gap| gap.severity == "warning"))
        .or_else(|| {
            if verdict == "playableSlice" {
                None
            } else {
                gaps.first()
            }
        });
    if let Some(gap) = next_gap {
        format!(
            "Critique '{}' as verdict '{}' with score {}. Weak dimensions: [{}]. Fix '{}' first: {}",
            prompt,
            verdict,
            score,
            weak_dimensions.join(", "),
            gap.category,
            gap.message
        )
    } else {
        format!(
            "Critique '{}' as verdict '{}' with score {}. The planned slice covers the major gameplay dimensions; move toward live readiness and playtest evidence.",
            prompt, verdict, score
        )
    }
}

fn resolve_playtest_paths(options: &PlaytestOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot playtest requires --run-dir or --plan".into(),
        )),
    }
}

fn resolve_simulate_paths(options: &SimulateOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot simulate requires --run-dir or --plan".into(),
        )),
    }
}

fn build_simulation_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    simulation_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<SimulationReport> {
    let explain = build_explain_report(plan_path, plan);
    let recipes = recipes_for_run(run_dir, plan)?;
    let signals = GameplaySignals::from_run(run_dir, plan, &recipes);
    let mut beats = simulation_beats(&signals, run_dir);
    let mut blockers = explain.blockers.clone();
    let mut warnings = explain.warnings.clone();

    for beat in &beats {
        match beat.status.as_str() {
            "fail" => blockers.push(format!("{}: {}", beat.title, beat.missing.join("; "))),
            "partial" => warnings.push(format!(
                "{} is only partially proven by static artifacts",
                beat.title
            )),
            _ => {}
        }
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    beats.sort_by_key(|beat| beat.order);

    let score = average_simulation_score(&beats);
    let status = if !blockers.is_empty() {
        "needsGameplayPatch"
    } else if beats.iter().all(|beat| beat.status == "pass") {
        "dryPlayable"
    } else {
        "needsPlaytestFocus"
    }
    .to_string();
    let verdict = match status.as_str() {
        "dryPlayable" => "staticPlayerJourneyPass",
        "needsPlaytestFocus" => "staticPlayerJourneyPartial",
        _ => "staticPlayerJourneyBlocked",
    }
    .to_string();

    let mut next_actions = Vec::new();
    if !blockers.is_empty() {
        next_actions.push(coach_action(
            1,
            "Patch missing player journey evidence",
            Some(format!(
                "rs autopilot improve --run-dir {} --max-recipes 2 --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "The static player journey has blockers; create a reviewable patch before live apply.",
            false,
            false,
        ));
    }
    next_actions.push(coach_action(
        2,
        "Create live playtest checklist",
        Some(format!(
            "rs autopilot playtest --run-dir {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Static simulation cannot prove runtime behavior; convert the journey into live evidence steps.",
        false,
        false,
    ));
    next_actions.push(coach_action(
        3,
        "Refresh certification",
        Some(format!(
            "rs autopilot certify {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Certification should include the latest static playability signal before live approval.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);

    let agent_brief = build_simulation_agent_brief(&plan.request.prompt, &status, score, &beats);
    Ok(SimulationReport {
        schema_version: "rs.autopilot.simulation.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        simulation_path: simulation_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        verdict,
        score,
        recipes,
        beats,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn simulation_beats(signals: &GameplaySignals, run_dir: &Path) -> Vec<SimulationBeat> {
    vec![
        simulation_beat(
            1,
            "arrival",
            "Player Arrival",
            if signals.has_recipe(&["lobbyTeleport", "npcInteraction", "obbyCheckpoint", "tycoonCore"])
                || signals.contains_any(&["spawn", "guide", "lobby", "checkpoint", "teleport"])
            {
                "pass"
            } else if signals
                .created_paths
                .iter()
                .any(|path| path.to_ascii_lowercase().contains("workspace"))
            {
                "partial"
            } else {
                "fail"
            },
            "Join the place and find the first intended activity.",
            "A spawn, guide, lobby, checkpoint, tycoon base, or teleport directs the player.",
            vec![
                recipe_evidence(signals, &["lobbyTeleport", "npcInteraction", "obbyCheckpoint", "tycoonCore"]),
                "path/source search for spawn, guide, lobby, checkpoint, or teleport".into(),
            ],
            vec!["No clear first-player navigation or starting affordance was found.".into()],
        ),
        simulation_beat(
            2,
            "interaction",
            "First Interaction",
            if signals.has_recipe(&[
                "collectibleCoin",
                "obbyCheckpoint",
                "toolSystem",
                "enemyEncounter",
                "npcInteraction",
                "tycoonCore",
                "lobbyTeleport",
            ]) || signals.contains_any(&[
                "proximityprompt",
                ".touched",
                "activated:",
                "mousebutton1click",
                "teleport",
            ]) {
                "pass"
            } else if signals.has_ui_path || signals.has_client_script {
                "partial"
            } else {
                "fail"
            },
            "Trigger the first gameplay verb.",
            "The plan exposes a touch, prompt, tool, UI button, teleport, enemy, or collector interaction.",
            vec![
                recipe_evidence(signals, &["collectibleCoin", "toolSystem", "enemyEncounter", "npcInteraction", "tycoonCore"]),
                "source search for prompt, touch, activated, click, or teleport handlers".into(),
            ],
            vec!["No concrete player input or trigger path was found.".into()],
        ),
        simulation_beat(
            3,
            "reward",
            "Reward Feedback",
            if signals.has_recipe(&[
                "starterShop",
                "collectibleCoin",
                "tycoonCore",
                "saveDataScaffold",
                "inventorySystem",
                "enemyEncounter",
                "questSystem",
            ]) || signals.contains_any(&["leaderstats", "coins", "cash", "reward", "purchase"]) {
                "pass"
            } else {
                "fail"
            },
            "Complete the first action and see a reward or state change.",
            "Currency, reward text, inventory, quest progress, shop purchase, or leaderstats feedback exists.",
            vec![
                recipe_evidence(signals, &["starterShop", "collectibleCoin", "tycoonCore", "saveDataScaffold"]),
                "source search for coins, cash, reward, purchase, or leaderstats".into(),
            ],
            vec!["No visible reward, currency, unlock, or state feedback was found.".into()],
        ),
        simulation_beat(
            4,
            "progression",
            "Progression Hook",
            if signals.has_recipe(&[
                "saveDataScaffold",
                "questSystem",
                "obbyCheckpoint",
                "tycoonCore",
                "inventorySystem",
            ]) || signals.contains_any(&[
                "datastore",
                "checkpoint",
                "questserver",
                "daily quest",
                "objective",
                "upgrade",
                "profile",
            ]) {
                "pass"
            } else if signals.has_recipe(&["roundManager", "enemyEncounter"]) {
                "partial"
            } else {
                "fail"
            },
            "Repeat the loop and advance toward a longer-term goal.",
            "The plan includes saves, quests, checkpoints, upgrades, inventory, rounds, or objectives.",
            vec![
                recipe_evidence(signals, &["saveDataScaffold", "questSystem", "obbyCheckpoint", "tycoonCore"]),
                "source search for datastore, checkpoint, objective, upgrade, or profile".into(),
            ],
            vec!["No durable progression or repeatable objective hook was found.".into()],
        ),
        simulation_beat(
            5,
            "feedback",
            "UI And Feedback",
            if signals.has_ui_path
                || signals.has_client_script
                || signals.has_recipe(&[
                    "starterShop",
                    "questSystem",
                    "inventorySystem",
                    "adminPanel",
                    "obbyCheckpoint",
                    "tycoonCore",
                    "enemyEncounter",
                    "npcInteraction",
                ])
                || signals.contains_any(&["textlabel", "screengui", "remoteevent"])
            {
                "pass"
            } else if signals.has_kind(&["createInstance", "upsertScript"]) {
                "partial"
            } else {
                "fail"
            },
            "Observe clear feedback for progress, purchases, objectives, or errors.",
            "StarterGui, LocalScript, ScreenGui, TextLabel, RemoteEvent, or recipe UI evidence exists.",
            vec![
                recipe_evidence(signals, &["starterShop", "questSystem", "inventorySystem", "adminPanel"]),
                format!("client script: {}, ui path: {}", signals.has_client_script, signals.has_ui_path),
            ],
            vec!["No player-facing feedback surface was found.".into()],
        ),
        simulation_beat(
            6,
            "authority",
            "Server Authority",
            if signals.has_server_script
                && (signals.contains_any(&["onserverevent", "players.playeradded", "leaderstats"])
                    || signals.has_kind(&["validate", "publishCheck", "deps"]))
            {
                "pass"
            } else if signals.has_server_script {
                "partial"
            } else {
                "fail"
            },
            "Run the loop in a multiplayer-safe way.",
            "Server-side scripts own rewards, remotes, player-added state, leaderstats, or validation gates.",
            vec![
                format!("server script: {}", signals.has_server_script),
                "source search for OnServerEvent, PlayerAdded, leaderstats, validate, deps, or publishCheck".into(),
            ],
            vec!["No clear server-authoritative gameplay path was found.".into()],
        ),
        simulation_beat(
            7,
            "verification",
            "Evidence Handoff",
            if signals.has_kind(&["validate", "deps", "publishCheck", "smoke"])
                && run_dir.join("source-audit.json").exists()
                && run_dir.join("preview.json").exists()
            {
                "pass"
            } else if signals.has_kind(&["validate", "deps", "publishCheck", "smoke"])
                || run_dir.join("preview.json").exists()
            {
                "partial"
            } else {
                "fail"
            },
            "Hand the dry-run to another AI or the creator for live proof.",
            "Preview, source audit, and validation/dependency/publish/smoke gates exist.",
            vec![
                format!(
                    "preview: {}, source audit: {}",
                    run_dir.join("preview.json").exists(),
                    run_dir.join("source-audit.json").exists()
                ),
                "operation search for validate, deps, publishCheck, or smoke".into(),
            ],
            vec!["No complete evidence chain exists for another agent to trust this dry-run.".into()],
        ),
    ]
}

fn simulation_beat(
    order: u8,
    id: &str,
    title: &str,
    status: &str,
    player_action: &str,
    expected_signal: &str,
    evidence: Vec<String>,
    missing: Vec<String>,
) -> SimulationBeat {
    SimulationBeat {
        order,
        id: id.into(),
        title: title.into(),
        status: status.into(),
        player_action: player_action.into(),
        expected_signal: expected_signal.into(),
        evidence: evidence
            .into_iter()
            .filter(|item| !item.trim().is_empty())
            .collect(),
        missing: if status == "pass" {
            Vec::new()
        } else {
            missing
        },
    }
}

fn average_simulation_score(beats: &[SimulationBeat]) -> u8 {
    if beats.is_empty() {
        return 0;
    }
    let total = beats
        .iter()
        .map(|beat| match beat.status.as_str() {
            "pass" => 100u16,
            "partial" => 60,
            _ => 0,
        })
        .sum::<u16>();
    ((total + (beats.len() as u16 / 2)) / beats.len() as u16) as u8
}

fn build_simulation_agent_brief(
    prompt: &str,
    status: &str,
    score: u8,
    beats: &[SimulationBeat],
) -> String {
    let weak = beats
        .iter()
        .filter(|beat| beat.status != "pass")
        .map(|beat| format!("{}={}", beat.id, beat.status))
        .collect::<Vec<_>>();
    if weak.is_empty() {
        format!(
            "Static player-journey simulation for '{}' is {} with score {}. Move toward live playtest evidence before claiming runtime success.",
            prompt, status, score
        )
    } else {
        format!(
            "Static player-journey simulation for '{}' is {} with score {}. Patch or verify weak beats first: [{}].",
            prompt,
            status,
            score,
            weak.join(", ")
        )
    }
}

fn resolve_graph_paths(options: &GraphOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot graph requires --run-dir or --plan".into(),
        )),
    }
}

fn build_feature_graph_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    graph_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<FeatureGraphReport> {
    let recipes = recipes_for_run(run_dir, plan)?;
    let mut nodes = BTreeMap::<String, FeatureGraphNode>::new();
    let mut edges = Vec::<FeatureGraphEdge>::new();
    insert_feature_node(
        &mut nodes,
        "plan".into(),
        "plan",
        &plan.id,
        None,
        None,
        vec![format!("prompt={}", plan.request.prompt)],
    );

    for recipe in &recipes {
        let id = format!("recipe:{recipe}");
        insert_feature_node(
            &mut nodes,
            id.clone(),
            "recipe",
            recipe,
            None,
            Some(recipe.clone()),
            vec!["inferred from request/manifest/generated source paths".into()],
        );
        edges.push(FeatureGraphEdge {
            from: "plan".into(),
            to: id,
            kind: "containsRecipe".into(),
            evidence: "recipe inference".into(),
        });
    }

    for operation in &plan.operations {
        let target_path = operation_feature_path(operation);
        let Some(target_path) = target_path else {
            if is_composition_verifier(&operation.kind) {
                let verifier_id = format!("verifier:{}", operation.kind);
                insert_feature_node(
                    &mut nodes,
                    verifier_id.clone(),
                    "verifier",
                    &operation.kind,
                    None,
                    None,
                    vec![format!("operation {}", operation.id)],
                );
                edges.push(FeatureGraphEdge {
                    from: "plan".into(),
                    to: verifier_id,
                    kind: "verifies".into(),
                    evidence: operation.id.clone(),
                });
            }
            continue;
        };
        let kind = operation_feature_kind(operation);
        let node_id = format!("path:{target_path}");
        let recipe = operation
            .source_path
            .as_deref()
            .and_then(recipe_from_generated_path);
        insert_feature_node(
            &mut nodes,
            node_id.clone(),
            kind,
            operation
                .name
                .as_deref()
                .or(operation.class_name.as_deref())
                .unwrap_or(&operation.kind),
            Some(target_path.clone()),
            recipe.clone(),
            vec![format!("{} {}", operation.id, operation.kind)],
        );
        edges.push(FeatureGraphEdge {
            from: recipe
                .as_ref()
                .map(|recipe| format!("recipe:{recipe}"))
                .filter(|id| nodes.contains_key(id))
                .unwrap_or_else(|| "plan".into()),
            to: node_id.clone(),
            kind: "createsOrUpdates".into(),
            evidence: operation.id.clone(),
        });
        if let Some(parent) = &operation.parent_path {
            let parent_id = format!("path:{parent}");
            if nodes.contains_key(&parent_id) {
                edges.push(FeatureGraphEdge {
                    from: parent_id,
                    to: node_id.clone(),
                    kind: "parentChild".into(),
                    evidence: operation.id.clone(),
                });
            }
        }
        if let Some(source_path) = &operation.source_path {
            let source_id = format!("source:{source_path}");
            let source_recipe = recipe_from_generated_path(source_path);
            insert_feature_node(
                &mut nodes,
                source_id.clone(),
                "generatedSource",
                source_path,
                Some(source_path.clone()),
                source_recipe.clone(),
                vec![format!("referenced by {}", operation.id)],
            );
            if let Some(recipe) = source_recipe {
                let recipe_id = format!("recipe:{recipe}");
                if nodes.contains_key(&recipe_id) {
                    edges.push(FeatureGraphEdge {
                        from: recipe_id,
                        to: source_id.clone(),
                        kind: "generatesSource".into(),
                        evidence: source_path.clone(),
                    });
                }
            }
            edges.push(FeatureGraphEdge {
                from: source_id,
                to: node_id,
                kind: "writesScript".into(),
                evidence: operation.id.clone(),
            });
        }
    }

    let remote_nodes = nodes
        .values()
        .filter(|node| node.kind == "remote")
        .cloned()
        .collect::<Vec<_>>();
    let source_nodes = nodes
        .values()
        .filter(|node| node.kind == "generatedSource")
        .cloned()
        .collect::<Vec<_>>();
    for remote in &remote_nodes {
        let Some(remote_name) = remote.path.as_deref().and_then(last_path_segment) else {
            continue;
        };
        for source in &source_nodes {
            let Some(source_path) = &source.path else {
                continue;
            };
            if source_mentions(run_dir, source_path, remote_name) {
                edges.push(FeatureGraphEdge {
                    from: source.id.clone(),
                    to: remote.id.clone(),
                    kind: "usesRemote".into(),
                    evidence: format!("{source_path} mentions {remote_name}"),
                });
            }
        }
    }

    let mut warnings = Vec::new();
    for remote in &remote_nodes {
        let referenced = edges
            .iter()
            .any(|edge| edge.to == remote.id && edge.kind == "usesRemote");
        if !referenced {
            warnings.push(format!(
                "remote {} has no generated-source reference in the static graph",
                remote.path.as_deref().unwrap_or(&remote.label)
            ));
        }
    }
    if source_nodes.is_empty() {
        warnings.push("feature graph has no generated source nodes".into());
    }
    warnings.sort();
    warnings.dedup();
    let blockers = if nodes.len() <= 1 {
        vec!["feature graph has no plan operations to connect".into()]
    } else {
        Vec::new()
    };
    let status = if !blockers.is_empty() {
        "blocked"
    } else if warnings.is_empty() {
        "connected"
    } else {
        "needsReview"
    }
    .to_string();

    edges.sort_by(|left, right| {
        left.from
            .cmp(&right.from)
            .then(left.to.cmp(&right.to))
            .then(left.kind.cmp(&right.kind))
    });
    edges.dedup_by(|left, right| {
        left.from == right.from && left.to == right.to && left.kind == right.kind
    });
    let mut nodes = nodes.into_values().collect::<Vec<_>>();
    nodes.sort_by(|left, right| left.id.cmp(&right.id));
    let next_actions = vec![
        coach_action(
            1,
            "Simulate the connected player journey",
            Some(format!(
                "rs autopilot simulate --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Use the graph to drive the static player-journey check before live apply.",
            false,
            false,
        ),
        coach_action(
            2,
            "Refresh planner pack with graph context",
            Some(format!(
                "rs autopilot planner-pack --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Give the next AI model a compact system graph instead of raw operations only.",
            false,
            false,
        ),
    ];
    let agent_brief = format!(
        "Feature graph for '{}' is {} with {} node(s), {} edge(s), and {} warning(s). Use it to understand recipes, scripts, remotes, UI, and verification before editing.",
        plan.request.prompt,
        status,
        nodes.len(),
        edges.len(),
        warnings.len()
    );
    Ok(FeatureGraphReport {
        schema_version: "rs.autopilot.feature-graph.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        graph_path: graph_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        recipes,
        node_count: nodes.len(),
        edge_count: edges.len(),
        nodes,
        edges,
        warnings,
        blockers,
        next_actions,
        agent_brief,
    })
}

fn insert_feature_node(
    nodes: &mut BTreeMap<String, FeatureGraphNode>,
    id: String,
    kind: &str,
    label: &str,
    path: Option<String>,
    recipe: Option<String>,
    evidence: Vec<String>,
) {
    nodes
        .entry(id.clone())
        .and_modify(|node| {
            for item in &evidence {
                if !node.evidence.contains(item) {
                    node.evidence.push(item.clone());
                }
            }
            if node.recipe.is_none() {
                node.recipe = recipe.clone();
            }
        })
        .or_insert_with(|| FeatureGraphNode {
            id,
            kind: kind.into(),
            label: label.into(),
            path,
            recipe,
            evidence,
        });
}

fn operation_feature_path(operation: &AutopilotOperation) -> Option<String> {
    operation.path.clone().or_else(|| {
        operation
            .parent_path
            .as_ref()
            .zip(operation.name.as_ref())
            .map(|(parent, name)| format!("{parent}.{name}"))
    })
}

fn operation_feature_kind(operation: &AutopilotOperation) -> &'static str {
    match (
        operation.kind.as_str(),
        operation.class_name.as_deref().unwrap_or_default(),
    ) {
        ("upsertScript", _) => "script",
        (_, "RemoteEvent" | "RemoteFunction") => "remote",
        (_, class)
            if class.contains("Gui") || class.contains("Button") || class.contains("Label") =>
        {
            "ui"
        }
        (_, "Script" | "LocalScript" | "ModuleScript") => "script",
        _ if operation
            .path
            .as_deref()
            .is_some_and(|path| path.contains("StarterGui")) =>
        {
            "ui"
        }
        _ => "instance",
    }
}

fn recipe_from_generated_path(path: &str) -> Option<String> {
    let normalized = path.replace('\\', "/");
    let mut parts = normalized.split('/');
    match (parts.next(), parts.next()) {
        (Some("generated"), Some(recipe_slug)) => recipe_name_from_slug(recipe_slug),
        _ => None,
    }
}

fn recipe_name_from_slug(value: &str) -> Option<String> {
    recipe_catalog()
        .recipes
        .into_iter()
        .find(|recipe| slug(&recipe.name) == value)
        .map(|recipe| recipe.name)
}

fn last_path_segment(path: &str) -> Option<&str> {
    path.rsplit('.').next().filter(|value| !value.is_empty())
}

fn source_mentions(run_dir: &Path, source_path: &str, needle: &str) -> bool {
    safe_join(run_dir, source_path)
        .ok()
        .and_then(|path| std::fs::read_to_string(path).ok())
        .is_some_and(|source| source.contains(needle))
}

fn resolve_balance_paths(options: &BalanceOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot balance requires --run-dir or --plan".into(),
        )),
    }
}

fn build_balance_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    balance_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<BalanceReport> {
    let mut evidence = collect_balance_evidence(run_dir, plan);
    if evidence.currency.is_none() {
        evidence.currency = infer_currency_from_prompt(&plan.request.prompt);
    }
    let currency_name = evidence.currency.clone().unwrap_or_else(|| "Coins".into());
    let mut findings = Vec::new();
    let mut loops = Vec::new();
    let starter_balance = evidence.starter_balance;
    let mut rewards = evidence.rewards.clone();
    let mut prices = evidence.prices.clone();
    rewards.sort_by_key(|value| value.value);
    prices.sort_by_key(|value| value.value);

    if rewards.is_empty() && prices.is_empty() {
        findings.push(balance_finding(
            "warning",
            "no-economy",
            "No numeric rewards or prices were found in generated artifacts.",
            evidence.sources.clone(),
            Some(format!(
                "rs autopilot tune \"{}\" --out {} --format json",
                shell_display_arg(&plan.request.prompt),
                command_arg(
                    run_dir
                        .join("tuned.autopilot-compose.json")
                        .to_string_lossy()
                        .as_ref()
                )
            )),
        ));
    } else if rewards.is_empty() {
        findings.push(balance_finding(
            "blocker",
            "prices-without-rewards",
            "Prices exist, but no reward source was found for players to earn the currency.",
            prices.iter().map(balance_value_evidence).collect(),
            Some(format!(
                "rs autopilot improve --run-dir {} --recipe collectibleCoin --max-recipes 1 --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ));
    } else if prices.is_empty() {
        findings.push(balance_finding(
            "warning",
            "rewards-without-spend",
            "Rewards exist, but no spend or upgrade target was found.",
            rewards.iter().map(balance_value_evidence).collect(),
            Some(format!(
                "rs autopilot improve --run-dir {} --recipe starterShop --max-recipes 1 --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ));
    }

    if let (Some(reward), Some(price)) = (
        rewards.iter().max_by_key(|value| value.value),
        prices.first(),
    ) {
        let actions = div_ceil(price.value, reward.value.max(1));
        let status = if actions <= 1 {
            "tooFast"
        } else if actions <= 8 {
            "healthy"
        } else if actions <= 20 {
            "slow"
        } else {
            "blocked"
        };
        loops.push(BalanceLoop {
            id: "first-purchase".into(),
            currency: currency_name.clone(),
            status: status.into(),
            summary: format!(
                "First price {} can be reached in about {} reward action(s) at reward {}.",
                price.value, actions, reward.value
            ),
            reward_value: Some(reward.value),
            price_value: Some(price.value),
            actions_to_afford: Some(actions),
            evidence: vec![
                balance_value_evidence(reward),
                balance_value_evidence(price),
            ],
        });
        match status {
            "tooFast" => findings.push(balance_finding(
                "warning",
                "too-fast-first-purchase",
                "The first spend target is affordable after one reward action; progression may feel flat.",
                vec![format!("actionsToAfford={actions}")],
                None,
            )),
            "slow" => findings.push(balance_finding(
                "warning",
                "slow-first-purchase",
                "The first spend target may take many reward actions; consider lowering prices or raising early rewards.",
                vec![format!("actionsToAfford={actions}")],
                None,
            )),
            "blocked" => findings.push(balance_finding(
                "blocker",
                "blocked-first-purchase",
                "The first spend target appears too expensive for the available reward loop.",
                vec![format!("actionsToAfford={actions}")],
                None,
            )),
            _ => {}
        }
    }

    if let (Some(balance), Some(price)) = (starter_balance, prices.first()) {
        if balance >= price.value {
            findings.push(balance_finding(
                "info",
                "starter-affordability",
                "Starter balance can afford the first shop item immediately.",
                vec![format!(
                    "starterBalance={balance}, firstPrice={}",
                    price.value
                )],
                None,
            ));
        }
    }

    let blockers = findings
        .iter()
        .filter(|finding| finding.severity == "blocker")
        .map(|finding| finding.message.clone())
        .collect::<Vec<_>>();
    let warnings = findings
        .iter()
        .filter(|finding| finding.severity == "warning")
        .map(|finding| finding.message.clone())
        .collect::<Vec<_>>();
    let status = if !blockers.is_empty() {
        "blocked"
    } else if !warnings.is_empty() {
        "needsTuningReview"
    } else if loops.iter().any(|item| item.status == "healthy") {
        "balanced"
    } else {
        "needsEconomyEvidence"
    }
    .to_string();
    let score = balance_score(&status, &findings, &loops);
    let currencies = vec![BalanceCurrency {
        name: currency_name.clone(),
        sources: evidence.sources.clone(),
        rewards,
        prices,
        starter_balance,
    }];
    let next_actions = vec![
        coach_action(
            1,
            "Review economy balance",
            None,
            "Confirm reward pacing, first purchase timing, and upgrade costs match the creator's intended difficulty.",
            false,
            false,
        ),
        coach_action(
            2,
            "Retune recipe manifest",
            Some(format!(
                "rs autopilot tune \"{}\" --out {} --format json",
                shell_display_arg(&plan.request.prompt),
                command_arg(run_dir.join("tuned.autopilot-compose.json").to_string_lossy().as_ref())
            )),
            "Use tuning when prices, rewards, or currency names need adjustment before composing again.",
            false,
            false,
        ),
        coach_action(
            3,
            "Simulate player journey",
            Some(format!(
                "rs autopilot simulate --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Balance should be checked alongside the static player-journey loop.",
            false,
            false,
        ),
    ];
    let agent_brief = format!(
        "Balance check for '{}' is {} with score {}. Currency '{}' has {} reward value(s), {} price value(s), and {} finding(s).",
        plan.request.prompt,
        status,
        score,
        currency_name,
        currencies[0].rewards.len(),
        currencies[0].prices.len(),
        findings.len()
    );

    Ok(BalanceReport {
        schema_version: "rs.autopilot.balance.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        balance_path: balance_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        score,
        currencies,
        loops,
        findings,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn collect_balance_evidence(run_dir: &Path, plan: &AutopilotPlan) -> BalanceEvidence {
    let mut evidence = BalanceEvidence {
        currency: None,
        rewards: Vec::new(),
        prices: Vec::new(),
        starter_balance: None,
        sources: Vec::new(),
    };
    collect_balance_from_json(&run_dir.join("tune.autopilot-compose.json"), &mut evidence);
    collect_balance_from_json(&run_dir.join("request.json"), &mut evidence);
    for source_path in generated_files_for_plan(plan) {
        if let Ok(path) = safe_join(run_dir, &source_path) {
            if let Ok(source) = std::fs::read_to_string(path) {
                collect_balance_from_source(&source_path, &source, &mut evidence);
            }
        }
    }
    evidence
        .rewards
        .sort_by_key(|value| (value.kind.clone(), value.value));
    evidence.rewards.dedup_by(|left, right| {
        left.kind == right.kind && left.value == right.value && left.source == right.source
    });
    evidence
        .prices
        .sort_by_key(|value| (value.kind.clone(), value.value));
    evidence.prices.dedup_by(|left, right| {
        left.kind == right.kind && left.value == right.value && left.source == right.source
    });
    evidence.sources.sort();
    evidence.sources.dedup();
    evidence
}

fn collect_balance_from_json(path: &Path, evidence: &mut BalanceEvidence) {
    let Ok(value) = read_json_file(path) else {
        return;
    };
    let source = path.to_string_lossy().to_string();
    collect_balance_from_value(&value, &source, evidence);
}

fn collect_balance_from_value(value: &Value, source: &str, evidence: &mut BalanceEvidence) {
    match value {
        Value::Object(map) => {
            if let Some(currency) = map
                .get("currencyName")
                .and_then(Value::as_str)
                .filter(|value| !value.trim().is_empty())
            {
                evidence
                    .currency
                    .get_or_insert_with(|| currency.to_string());
                evidence
                    .sources
                    .push(format!("{source}:currencyName={currency}"));
            }
            for (field, kind) in [
                ("coinValue", BalanceValueKind::Reward),
                ("dropValue", BalanceValueKind::Reward),
                ("reward", BalanceValueKind::Reward),
                ("price", BalanceValueKind::Price),
                ("upgradePrice", BalanceValueKind::Price),
            ] {
                if let Some(value) = map.get(field).and_then(Value::as_u64) {
                    push_balance_number(evidence, kind, field, value as u32, source);
                }
            }
            for item in map.values() {
                collect_balance_from_value(item, source, evidence);
            }
        }
        Value::Array(items) => {
            for item in items {
                collect_balance_from_value(item, source, evidence);
            }
        }
        _ => {}
    }
}

fn collect_balance_from_source(source_path: &str, source: &str, evidence: &mut BalanceEvidence) {
    for line in source.lines() {
        if let Some(currency) = parse_lua_string_assignment(line, "currencyName") {
            evidence.currency.get_or_insert(currency.clone());
            evidence
                .sources
                .push(format!("{source_path}:currencyName={currency}"));
        }
        for (field, kind) in [
            ("coinValue", BalanceValueKind::Reward),
            ("dropValue", BalanceValueKind::Reward),
            ("reward", BalanceValueKind::Reward),
            ("price", BalanceValueKind::Price),
            ("upgradePrice", BalanceValueKind::Price),
        ] {
            if let Some(value) = parse_lua_number_assignment(line, field) {
                push_balance_number(evidence, kind, field, value, source_path);
            }
        }
        if let Some(value) = parse_lua_number_after_token(line, "balances[player.UserId] or") {
            evidence.starter_balance = Some(value);
            push_balance_number(
                evidence,
                BalanceValueKind::StarterBalance,
                "starterBalance",
                value,
                source_path,
            );
        }
    }
}

fn parse_lua_string_assignment(line: &str, field: &str) -> Option<String> {
    let index = line.find(field)?;
    let after = &line[index + field.len()..];
    let quote_index = after.find('"')?;
    let after_quote = &after[quote_index + 1..];
    let end = after_quote.find('"')?;
    Some(after_quote[..end].to_string())
}

fn parse_lua_number_assignment(line: &str, field: &str) -> Option<u32> {
    let index = line.find(field)?;
    let after = &line[index + field.len()..];
    let equals = after.find('=')?;
    parse_first_u32(&after[equals + 1..])
}

fn parse_lua_number_after_token(line: &str, token: &str) -> Option<u32> {
    let index = line.find(token)?;
    let after = &line[index + token.len()..];
    parse_first_u32(after)
}

fn parse_first_u32(value: &str) -> Option<u32> {
    let start = value.find(|ch: char| ch.is_ascii_digit())?;
    let digits = value[start..]
        .chars()
        .take_while(|ch| ch.is_ascii_digit())
        .collect::<String>();
    digits.parse().ok()
}

fn push_balance_number(
    evidence: &mut BalanceEvidence,
    kind: BalanceValueKind,
    field: &str,
    value: u32,
    source: &str,
) {
    let item = BalanceValue {
        kind: match kind {
            BalanceValueKind::Reward => field.into(),
            BalanceValueKind::Price => field.into(),
            BalanceValueKind::StarterBalance => field.into(),
        },
        value,
        source: source.into(),
    };
    match kind {
        BalanceValueKind::Reward => evidence.rewards.push(item),
        BalanceValueKind::Price => evidence.prices.push(item),
        BalanceValueKind::StarterBalance => {
            evidence.starter_balance = Some(value);
            evidence.sources.push(format!("{source}:{field}={value}"));
        }
    }
}

fn infer_currency_from_prompt(prompt: &str) -> Option<String> {
    let lower = prompt.to_ascii_lowercase();
    if lower.contains("candy") || lower.contains("sweet") {
        Some("Sweets".into())
    } else if lower.contains("gem") {
        Some("Gems".into())
    } else if lower.contains("cash") || lower.contains("tycoon") {
        Some("Cash".into())
    } else if lower.contains("coin") || lower.contains("shop") {
        Some("Coins".into())
    } else {
        None
    }
}

fn div_ceil(left: u32, right: u32) -> u32 {
    if right == 0 {
        return left;
    }
    left.div_ceil(right)
}

fn balance_finding(
    severity: &str,
    category: &str,
    message: &str,
    evidence: Vec<String>,
    command: Option<String>,
) -> BalanceFinding {
    BalanceFinding {
        severity: severity.into(),
        category: category.into(),
        message: message.into(),
        evidence,
        command,
    }
}

fn balance_value_evidence(value: &BalanceValue) -> String {
    format!("{}={} ({})", value.kind, value.value, value.source)
}

fn balance_score(status: &str, findings: &[BalanceFinding], loops: &[BalanceLoop]) -> u8 {
    match status {
        "balanced" => 92,
        "needsTuningReview" => 72u8.saturating_sub(
            findings
                .iter()
                .filter(|finding| finding.severity == "warning")
                .count() as u8
                * 8,
        ),
        "blocked" => 35,
        _ if loops.is_empty() => 45,
        _ => 60,
    }
}

fn resolve_impact_paths(options: &ImpactOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot impact requires a run directory or --plan".into(),
        )),
    }
}

fn build_impact_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    impact_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<ImpactReport> {
    let mut group_kinds = BTreeMap::<String, BTreeMap<String, usize>>::new();
    let mut service_paths = BTreeMap::<String, BTreeSet<String>>::new();
    let mut service_scripts = BTreeMap::<String, BTreeSet<String>>::new();
    let mut service_remotes = BTreeMap::<String, BTreeSet<String>>::new();
    let mut service_counts = BTreeMap::<String, usize>::new();
    let mut touched_paths = BTreeSet::<String>::new();
    let mut scripts = Vec::<ImpactScript>::new();
    let mut remotes = Vec::<ImpactRemote>::new();
    let mut findings = Vec::<ImpactFinding>::new();

    for operation in &plan.operations {
        let kind = operation.kind.to_ascii_lowercase();
        let group = operation_group(&kind).to_string();
        *group_kinds
            .entry(group)
            .or_default()
            .entry(operation.kind.clone())
            .or_insert(0) += 1;

        if let Some(path) = impact_operation_path(operation) {
            touched_paths.insert(path.clone());
            if let Some(service) = impact_service_from_path(&path) {
                *service_counts.entry(service.clone()).or_insert(0) += 1;
                service_paths
                    .entry(service.clone())
                    .or_default()
                    .insert(path.clone());
                if is_script_operation(operation) {
                    service_scripts
                        .entry(service.clone())
                        .or_default()
                        .insert(path.clone());
                }
                if is_remote_operation(operation) {
                    service_remotes
                        .entry(service)
                        .or_default()
                        .insert(path.clone());
                }
            }
        }

        if is_script_operation(operation) {
            let path = impact_operation_path(operation)
                .or_else(|| operation.source_path.clone())
                .unwrap_or_else(|| operation.id.clone());
            scripts.push(ImpactScript {
                service: impact_service_from_path(&path),
                path,
                class_name: operation.class_name.clone(),
                source_path: operation.source_path.clone(),
            });
        }

        if is_remote_operation(operation) {
            let path = impact_operation_path(operation).unwrap_or_else(|| operation.id.clone());
            remotes.push(ImpactRemote {
                service: impact_service_from_path(&path),
                path: path.clone(),
                class_name: operation.class_name.clone(),
                evidence: format!("{} creates or updates a remote endpoint", operation.id),
            });
        }
    }

    let generated_sources = generated_files_for_plan(plan);
    let mut cloud_surfaces = collect_impact_cloud_surfaces(run_dir, plan, &generated_sources)?;
    if plan.risk.touches_cloud_assets {
        cloud_surfaces.push(ImpactCloudSurface {
            service: "RobloxAssets".into(),
            source: "plan.risk.touchesCloudAssets".into(),
            reason: "Plan declares cloud asset or upload impact.".into(),
        });
    }
    for operation in &plan.operations {
        if matches!(
            operation.kind.as_str(),
            "uploadAsset" | "importUploaded" | "importAsset" | "packageImport"
        ) {
            cloud_surfaces.push(ImpactCloudSurface {
                service: "RobloxAssets".into(),
                source: operation.id.clone(),
                reason: format!("{} may create or import external assets", operation.kind),
            });
        }
    }
    dedup_impact_cloud_surfaces(&mut cloud_surfaces);

    let has_delete = plan
        .operations
        .iter()
        .any(|operation| operation.kind == "deleteInstance");
    if plan.risk.destructive || has_delete {
        findings.push(impact_finding(
            "warning",
            "destructive-plan",
            "The plan includes destructive risk or delete operations; require explicit creator approval and rollback review.",
            touched_paths.iter().cloned().take(12).collect(),
            Some(format!(
                "rs autopilot approval {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ));
    }
    if !scripts.is_empty() {
        findings.push(impact_finding(
            "warning",
            "scripts-touched",
            "Generated scripts change runtime behavior; review server/client authority before live apply.",
            scripts
                .iter()
                .map(|script| script.path.clone())
                .collect::<Vec<_>>(),
            Some(format!(
                "rs autopilot audit-sources {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ));
    }
    if !remotes.is_empty() {
        findings.push(impact_finding(
            "info",
            "remotes-touched",
            "RemoteEvent or RemoteFunction endpoints are part of the surface area.",
            remotes
                .iter()
                .map(|remote| remote.path.clone())
                .collect::<Vec<_>>(),
            None,
        ));
    }
    if !cloud_surfaces.is_empty() {
        findings.push(impact_finding(
            "warning",
            "cloud-surface",
            "Cloud, persistence, marketplace, HTTP, teleport, or uploaded asset surfaces need extra review.",
            cloud_surfaces
                .iter()
                .map(|surface| format!("{} via {}", surface.service, surface.source))
                .collect::<Vec<_>>(),
            Some(format!(
                "rs autopilot privacy {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ));
    }
    if plan.operations.len() > 25 {
        findings.push(impact_finding(
            "warning",
            "wide-operation-set",
            "The plan touches many operations; review by service before approving a live apply.",
            vec![format!("operationCount={}", plan.operations.len())],
            Some(format!(
                "rs autopilot review-pack {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ));
    }
    for source in &generated_sources {
        if !run_dir.join(source).exists() {
            findings.push(impact_finding(
                "warning",
                "missing-generated-source",
                "A generated source referenced by the plan is missing, so source impact may be incomplete.",
                vec![source.clone()],
                Some(format!(
                    "rs autopilot certify {} --format json",
                    command_arg(run_dir.to_string_lossy().as_ref())
                )),
            ));
        }
    }

    let mut services = service_paths
        .into_iter()
        .map(|(name, paths)| {
            let scripts = service_scripts
                .remove(&name)
                .map(|items| items.into_iter().collect::<Vec<_>>())
                .unwrap_or_default();
            let remotes = service_remotes
                .remove(&name)
                .map(|items| items.into_iter().collect::<Vec<_>>())
                .unwrap_or_default();
            let paths = paths.into_iter().collect::<Vec<_>>();
            ImpactService {
                risk: impact_service_risk(&name, !scripts.is_empty(), !remotes.is_empty()).into(),
                operation_count: service_counts.get(&name).copied().unwrap_or(paths.len()),
                path_count: paths.len(),
                name,
                scripts,
                remotes,
                paths,
            }
        })
        .collect::<Vec<_>>();
    services.sort_by(|left, right| {
        impact_risk_rank(&right.risk)
            .cmp(&impact_risk_rank(&left.risk))
            .then_with(|| left.name.cmp(&right.name))
    });

    let mut operation_groups = group_kinds
        .into_iter()
        .map(|(name, kinds)| ImpactOperationGroup {
            count: kinds.values().sum(),
            risk: impact_group_risk(&name).into(),
            name,
            kinds,
        })
        .collect::<Vec<_>>();
    operation_groups.sort_by(|left, right| {
        impact_risk_rank(&right.risk)
            .cmp(&impact_risk_rank(&left.risk))
            .then_with(|| left.name.cmp(&right.name))
    });

    let destructive = plan.risk.destructive || has_delete;
    let high_script_service = scripts
        .iter()
        .any(|script| script.service.as_deref() == Some("ServerScriptService"));
    let status = if destructive {
        "dangerImpact"
    } else if !cloud_surfaces.is_empty() || high_script_service {
        "highImpact"
    } else if plan.risk.requires_approval || !scripts.is_empty() || !remotes.is_empty() {
        "reviewImpact"
    } else {
        "lowImpact"
    }
    .to_string();
    let rollback_required = plan.operations.iter().any(|operation| {
        matches!(
            operation.kind.as_str(),
            "upsertScript"
                | "createInstance"
                | "setProperties"
                | "deleteInstance"
                | "importImage"
                | "importAsset"
                | "importUploaded"
                | "uploadAsset"
                | "packageImport"
        )
    });
    let requires_creator_approval = plan.risk.requires_approval
        || plan.risk.destructive
        || plan.risk.touches_scripts
        || plan.risk.touches_cloud_assets
        || !scripts.is_empty()
        || !cloud_surfaces.is_empty();
    let mut blockers = findings
        .iter()
        .filter(|finding| finding.severity == "blocker")
        .map(|finding| finding.message.clone())
        .collect::<Vec<_>>();
    blockers.sort();
    blockers.dedup();
    let mut warnings = findings
        .iter()
        .filter(|finding| finding.severity == "warning")
        .map(|finding| finding.message.clone())
        .collect::<Vec<_>>();
    warnings.sort();
    warnings.dedup();
    let mut next_actions = Vec::new();
    next_actions.push(coach_action(
        1,
        "Review impact before approval",
        Some(format!(
            "rs autopilot approval {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Use the blast-radius map to frame the creator approval prompt.",
        false,
        false,
    ));
    next_actions.push(coach_action(
        2,
        "Verify handoff bundle",
        Some(format!(
            "rs autopilot verify-bundle --run-dir {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Impact artifacts are only trustworthy when the bundle hashes still match.",
        false,
        false,
    ));
    if status == "highImpact" || status == "dangerImpact" {
        next_actions.push(coach_action(
            3,
            "Run the live mutation gate",
            Some(format!(
                "rs autopilot live-gate --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "High-impact runs should pass readiness, rollback, privacy, and approval gates before apply.",
            true,
            false,
        ));
    }
    dedup_next_actions(&mut next_actions);
    let agent_brief = format!(
        "Impact for '{}' is {} across {} service(s), {} script(s), {} remote(s), and {} cloud surface(s). Treat this as the blast-radius map before asking for approval or mutating Studio.",
        plan.request.prompt,
        status,
        services.len(),
        scripts.len(),
        remotes.len(),
        cloud_surfaces.len()
    );

    Ok(ImpactReport {
        schema_version: "rs.autopilot.impact.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        impact_path: impact_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        risk_level: plan.risk.level.clone(),
        operation_count: plan.operations.len(),
        mutates_studio: !plan.operations.is_empty(),
        requires_creator_approval,
        rollback_required,
        services,
        operation_groups,
        touched_paths: touched_paths.into_iter().collect(),
        generated_sources,
        scripts,
        remotes,
        cloud_surfaces,
        findings,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn impact_operation_path(operation: &AutopilotOperation) -> Option<String> {
    operation.path.clone().or_else(|| {
        operation
            .parent_path
            .as_ref()
            .zip(operation.name.as_ref())
            .map(|(parent, name)| join_studio_path(parent, name))
            .or_else(|| operation.parent_path.clone())
    })
}

fn is_script_operation(operation: &AutopilotOperation) -> bool {
    operation.kind == "upsertScript"
        || matches!(
            operation.class_name.as_deref(),
            Some("Script" | "LocalScript" | "ModuleScript")
        )
}

fn is_remote_operation(operation: &AutopilotOperation) -> bool {
    matches!(
        operation.class_name.as_deref(),
        Some("RemoteEvent" | "RemoteFunction")
    )
}

fn impact_service_from_path(path: &str) -> Option<String> {
    let normalized = path.strip_prefix("game.").unwrap_or(path);
    normalized
        .split('.')
        .next()
        .filter(|value| !value.trim().is_empty())
        .map(str::to_string)
}

fn impact_service_risk(service: &str, has_scripts: bool, has_remotes: bool) -> &'static str {
    match service {
        "ServerScriptService" | "ServerStorage" => "high",
        "Workspace" | "StarterPlayer" | "StarterPack" => "review",
        "ReplicatedStorage" if has_remotes => "review",
        "StarterGui" if has_scripts => "review",
        _ if has_scripts => "review",
        _ => "low",
    }
}

fn impact_group_risk(group: &str) -> &'static str {
    match group {
        "deletes" => "danger",
        "scripts" => "high",
        "assets" => "review",
        _ => "low",
    }
}

fn impact_risk_rank(risk: &str) -> u8 {
    match risk {
        "danger" => 4,
        "high" => 3,
        "review" => 2,
        "low" => 1,
        _ => 0,
    }
}

fn collect_impact_cloud_surfaces(
    run_dir: &Path,
    _plan: &AutopilotPlan,
    generated_sources: &[String],
) -> AppResult<Vec<ImpactCloudSurface>> {
    let mut surfaces = Vec::new();
    for source_path in generated_sources {
        let path = match safe_join(run_dir, source_path) {
            Ok(path) => path,
            Err(_) => continue,
        };
        let Ok(source) = std::fs::read_to_string(path) else {
            continue;
        };
        for (token, reason) in [
            ("DataStoreService", "persistent player data"),
            ("MemoryStoreService", "cross-server memory"),
            ("MessagingService", "cross-server messaging"),
            ("HttpService", "external HTTP boundary"),
            ("MarketplaceService", "purchase or entitlement boundary"),
            ("TeleportService", "experience transition boundary"),
            ("BadgeService", "player achievement boundary"),
        ] {
            if source.contains(token) {
                surfaces.push(ImpactCloudSurface {
                    service: token.into(),
                    source: source_path.clone(),
                    reason: reason.into(),
                });
            }
        }
    }
    Ok(surfaces)
}

fn dedup_impact_cloud_surfaces(surfaces: &mut Vec<ImpactCloudSurface>) {
    surfaces.sort_by(|left, right| {
        left.service
            .cmp(&right.service)
            .then_with(|| left.source.cmp(&right.source))
    });
    surfaces.dedup_by(|left, right| left.service == right.service && left.source == right.source);
}

fn impact_finding(
    severity: &str,
    category: &str,
    message: &str,
    evidence: Vec<String>,
    command: Option<String>,
) -> ImpactFinding {
    ImpactFinding {
        severity: severity.into(),
        category: category.into(),
        message: message.into(),
        evidence,
        command,
    }
}

fn resolve_contracts_paths(options: &ContractsOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot contracts requires a run directory or --plan".into(),
        )),
    }
}

fn build_contracts_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    contracts_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<ContractsReport> {
    let generated_sources = generated_files_for_plan(plan);
    let source_texts = generated_sources
        .iter()
        .filter_map(|source_path| {
            safe_join(run_dir, source_path)
                .ok()
                .and_then(|path| std::fs::read_to_string(path).ok())
                .map(|source| (source_path.clone(), source))
        })
        .collect::<Vec<_>>();
    let script_targets = plan
        .operations
        .iter()
        .filter(|operation| is_script_operation(operation))
        .filter_map(|operation| {
            operation.source_path.as_ref().map(|source_path| {
                (
                    source_path.clone(),
                    (
                        impact_operation_path(operation),
                        operation.class_name.clone(),
                    ),
                )
            })
        })
        .collect::<BTreeMap<_, _>>();
    let mut scripts = generated_sources
        .iter()
        .map(|source_path| {
            let (script_path, class_name) = script_targets
                .get(source_path)
                .cloned()
                .unwrap_or((None, None));
            (
                source_path.clone(),
                ContractScript {
                    source_path: source_path.clone(),
                    script_path,
                    class_name,
                    remote_refs: Vec::new(),
                    roles: Vec::new(),
                },
            )
        })
        .collect::<BTreeMap<_, _>>();

    let remote_specs = plan
        .operations
        .iter()
        .filter(|operation| is_remote_operation(operation))
        .filter_map(|operation| {
            let path = impact_operation_path(operation)?;
            let name = last_path_segment(&path)?.to_string();
            Some((
                operation.id.clone(),
                name,
                path,
                operation
                    .class_name
                    .clone()
                    .unwrap_or_else(|| "RemoteEvent".into()),
            ))
        })
        .collect::<Vec<_>>();

    let mut contracts = Vec::new();
    let mut findings = Vec::new();
    for (operation_id, name, path, class_name) in remote_specs {
        let mut endpoints = Vec::new();
        for (source_path, source) in &source_texts {
            let Some(endpoint) = contract_endpoint_for_source(
                source_path,
                source,
                &name,
                script_targets.get(source_path),
            ) else {
                continue;
            };
            if let Some(script) = scripts.get_mut(source_path) {
                if !script.remote_refs.contains(&path) {
                    script.remote_refs.push(path.clone());
                }
                for role in endpoint.role.split(',') {
                    let role = role.trim();
                    if !role.is_empty() && !script.roles.iter().any(|existing| existing == role) {
                        script.roles.push(role.to_string());
                    }
                }
            }
            endpoints.push(endpoint);
        }
        let client_call = endpoints
            .iter()
            .any(|endpoint| endpoint.role.contains("clientCall"));
        let server_handler = endpoints
            .iter()
            .any(|endpoint| endpoint.role.contains("serverHandler"));
        let server_emit = endpoints
            .iter()
            .any(|endpoint| endpoint.role.contains("serverEmit"));
        let client_handler = endpoints
            .iter()
            .any(|endpoint| endpoint.role.contains("clientHandler"));
        let mut directions = Vec::new();
        if client_call || server_handler {
            directions.push(if client_call && server_handler {
                "clientToServer"
            } else {
                "clientToServerPartial"
            });
        }
        if server_emit || client_handler {
            directions.push(if server_emit && client_handler {
                "serverToClient"
            } else {
                "serverToClientPartial"
            });
        }
        if directions.is_empty() && !endpoints.is_empty() {
            directions.push("referencedOnly");
        }
        let mut contract_findings = Vec::new();
        if endpoints.is_empty() {
            contract_findings.push(contract_finding(
                "warning",
                "orphan-remote",
                &format!("{path} is declared but no generated source references it."),
                vec![operation_id.clone(), path.clone()],
                Some(format!(
                    "rs autopilot graph --run-dir {} --format json",
                    command_arg(run_dir.to_string_lossy().as_ref())
                )),
            ));
        }
        if client_call && !server_handler {
            contract_findings.push(contract_finding(
                "warning",
                "missing-server-handler",
                &format!("{path} has client calls but no generated server handler."),
                contract_endpoint_sources(&endpoints),
                None,
            ));
        }
        if server_handler && !client_call {
            contract_findings.push(contract_finding(
                "info",
                "server-handler-without-client-call",
                &format!("{path} has a server handler but no generated client call."),
                contract_endpoint_sources(&endpoints),
                None,
            ));
        }
        if server_emit && !client_handler {
            contract_findings.push(contract_finding(
                "warning",
                "missing-client-handler",
                &format!("{path} has server emits but no generated client listener."),
                contract_endpoint_sources(&endpoints),
                None,
            ));
        }
        if client_handler && !server_emit {
            contract_findings.push(contract_finding(
                "info",
                "client-handler-without-server-emit",
                &format!("{path} has a client listener but no generated server emit."),
                contract_endpoint_sources(&endpoints),
                None,
            ));
        }
        if server_handler && !contract_has_argument_guard(&endpoints) {
            contract_findings.push(contract_finding(
                "warning",
                "server-remote-needs-validation-review",
                &format!("{path} server handler has no obvious generated argument guard."),
                contract_endpoint_sources(&endpoints),
                Some(format!(
                    "rs autopilot audit-sources {} --format json",
                    command_arg(run_dir.to_string_lossy().as_ref())
                )),
            ));
        }

        let status = if endpoints.is_empty() {
            "orphan"
        } else if contract_findings
            .iter()
            .any(|finding| finding.severity == "warning" || finding.severity == "blocker")
        {
            "needsReview"
        } else if directions
            .iter()
            .any(|direction| *direction == "clientToServer" || *direction == "serverToClient")
        {
            "complete"
        } else {
            "referenced"
        };
        findings.extend(contract_findings.clone());
        contracts.push(RemoteContract {
            id: operation_id,
            name,
            path: path.clone(),
            class_name,
            service: impact_service_from_path(&path),
            status: status.into(),
            directions: directions.into_iter().map(str::to_string).collect(),
            endpoints,
            findings: contract_findings,
        });
    }

    for script in scripts.values_mut() {
        script.remote_refs.sort();
        script.remote_refs.dedup();
        script.roles.sort();
        script.roles.dedup();
    }
    let mut scripts = scripts.into_values().collect::<Vec<_>>();
    scripts.sort_by(|left, right| left.source_path.cmp(&right.source_path));
    contracts.sort_by(|left, right| left.path.cmp(&right.path));
    findings.sort_by(|left, right| {
        left.severity
            .cmp(&right.severity)
            .then(left.category.cmp(&right.category))
            .then(left.message.cmp(&right.message))
    });
    findings.dedup_by(|left, right| {
        left.severity == right.severity
            && left.category == right.category
            && left.message == right.message
    });
    let mut blockers = findings
        .iter()
        .filter(|finding| finding.severity == "blocker")
        .map(|finding| finding.message.clone())
        .collect::<Vec<_>>();
    blockers.sort();
    blockers.dedup();
    let mut warnings = findings
        .iter()
        .filter(|finding| finding.severity == "warning")
        .map(|finding| finding.message.clone())
        .collect::<Vec<_>>();
    warnings.sort();
    warnings.dedup();
    let complete_contracts = contracts
        .iter()
        .filter(|contract| {
            contract
                .directions
                .iter()
                .any(|direction| direction == "clientToServer" || direction == "serverToClient")
        })
        .count();
    let incomplete_contracts = contracts.len().saturating_sub(complete_contracts);
    let status = if !blockers.is_empty() {
        "blocked"
    } else if contracts.is_empty() {
        "noRemoteContracts"
    } else if !warnings.is_empty() || incomplete_contracts > 0 {
        "needsContractReview"
    } else {
        "contracted"
    }
    .to_string();
    let mut next_actions = Vec::new();
    if status == "needsContractReview" {
        next_actions.push(coach_action(
            1,
            "Patch weak remote contracts",
            Some(format!(
                "rs autopilot improve --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Remote contracts have missing or weak client/server evidence; patch before live apply if the gap is material.",
            false,
            false,
        ));
    }
    next_actions.push(coach_action(
        2,
        "Review feature graph",
        Some(format!(
            "rs autopilot graph --run-dir {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Compare contracts with the feature graph to understand where remotes sit in the feature stack.",
        false,
        false,
    ));
    next_actions.push(coach_action(
        3,
        "Run live gate before apply",
        Some(format!(
            "rs autopilot live-gate --run-dir {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Remote contracts are static evidence only; live mutation still needs approval and readiness.",
        true,
        false,
    ));
    dedup_next_actions(&mut next_actions);
    let agent_brief = format!(
        "Remote contracts for '{}' are {} with {} remote(s), {} complete contract(s), and {} warning(s). Use this as the client/server API map before patching, approval, or live apply.",
        plan.request.prompt,
        status,
        contracts.len(),
        complete_contracts,
        warnings.len()
    );

    Ok(ContractsReport {
        schema_version: "rs.autopilot.contracts.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        contracts_path: contracts_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        remote_count: contracts.len(),
        complete_contracts,
        incomplete_contracts,
        contracts,
        scripts,
        findings,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn contract_endpoint_for_source(
    source_path: &str,
    source: &str,
    remote_name: &str,
    script_target: Option<&(Option<String>, Option<String>)>,
) -> Option<ContractEndpoint> {
    let variables = remote_variable_names(source, remote_name);
    if variables.is_empty() && !source.contains(remote_name) {
        return None;
    }
    let mut roles = BTreeSet::new();
    let mut evidence = BTreeSet::new();
    for variable in &variables {
        if source.contains(&format!("{variable}.OnServerEvent"))
            || source.contains(&format!("{variable}.OnServerInvoke"))
        {
            roles.insert("serverHandler");
            evidence.insert(format!("{variable}.OnServer*"));
        }
        if source.contains(&format!("{variable}.OnClientEvent"))
            || source.contains(&format!("{variable}.OnClientInvoke"))
        {
            roles.insert("clientHandler");
            evidence.insert(format!("{variable}.OnClient*"));
        }
        if source.contains(&format!("{variable}:FireServer"))
            || source.contains(&format!("{variable}:InvokeServer"))
        {
            roles.insert("clientCall");
            evidence.insert(format!("{variable}:*Server"));
        }
        if source.contains(&format!("{variable}:FireClient"))
            || source.contains(&format!("{variable}:FireAllClients"))
            || source.contains(&format!("{variable}:InvokeClient"))
        {
            roles.insert("serverEmit");
            evidence.insert(format!("{variable}:*Client"));
        }
    }
    if roles.is_empty() && source.contains(remote_name) {
        roles.insert("reference");
        evidence.insert(format!("mentions {remote_name}"));
    }
    if contract_source_has_argument_guard(source) {
        evidence.insert("argumentGuardHeuristic".into());
    }
    let role = roles.iter().copied().collect::<Vec<_>>().join(",");
    let direction = contract_direction_for_roles(&roles);
    let (script_path, script_class) = script_target.cloned().unwrap_or((None, None));
    Some(ContractEndpoint {
        source_path: source_path.into(),
        script_path,
        script_class,
        role,
        direction,
        evidence: evidence.into_iter().collect(),
    })
}

fn remote_variable_names(source: &str, remote_name: &str) -> BTreeSet<String> {
    let mut variables = BTreeSet::new();
    for line in source.lines() {
        if !(line.contains(&format!("WaitForChild(\"{remote_name}\")"))
            || line.contains(&format!("WaitForChild('{remote_name}')")))
        {
            continue;
        }
        if let Some(variable) = lua_assignment_lhs_variable(line) {
            variables.insert(variable);
        }
    }
    variables
}

fn lua_assignment_lhs_variable(line: &str) -> Option<String> {
    let left = line.split('=').next()?.trim();
    let left = left.strip_prefix("local ").unwrap_or(left).trim();
    left.split(|ch: char| !ch.is_ascii_alphanumeric() && ch != '_')
        .filter(|part| !part.is_empty())
        .next_back()
        .map(str::to_string)
}

fn contract_direction_for_roles(roles: &BTreeSet<&'static str>) -> String {
    let client_to_server = roles.contains("clientCall") || roles.contains("serverHandler");
    let server_to_client = roles.contains("serverEmit") || roles.contains("clientHandler");
    match (client_to_server, server_to_client) {
        (true, true) => "bidirectional",
        (true, false) => "clientToServer",
        (false, true) => "serverToClient",
        (false, false) => "reference",
    }
    .into()
}

fn contract_source_has_argument_guard(source: &str) -> bool {
    source.contains("typeof(")
        || source.contains("type(")
        || source.contains("tonumber(")
        || source.contains(":IsA(")
        || source.contains("pcall(")
}

fn contract_has_argument_guard(endpoints: &[ContractEndpoint]) -> bool {
    endpoints.iter().any(|endpoint| {
        endpoint
            .evidence
            .iter()
            .any(|item| item == "argumentGuardHeuristic")
    })
}

fn contract_endpoint_sources(endpoints: &[ContractEndpoint]) -> Vec<String> {
    let mut sources = endpoints
        .iter()
        .map(|endpoint| endpoint.source_path.clone())
        .collect::<Vec<_>>();
    sources.sort();
    sources.dedup();
    sources
}

fn contract_finding(
    severity: &str,
    category: &str,
    message: &str,
    evidence: Vec<String>,
    command: Option<String>,
) -> ContractFinding {
    ContractFinding {
        severity: severity.into(),
        category: category.into(),
        message: message.into(),
        evidence,
        command,
    }
}

fn resolve_authority_paths(options: &AuthorityOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot authority requires a run directory or --plan".into(),
        )),
    }
}

fn build_authority_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    authority_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<AuthorityReport> {
    let generated_sources = generated_files_for_plan(plan);
    let script_targets = plan
        .operations
        .iter()
        .filter(|operation| is_script_operation(operation))
        .filter_map(|operation| {
            operation.source_path.as_ref().map(|source_path| {
                (
                    source_path.clone(),
                    (
                        impact_operation_path(operation),
                        operation.class_name.clone(),
                    ),
                )
            })
        })
        .collect::<BTreeMap<_, _>>();
    let contracts_path = run_dir.join("contracts.json");
    let contracts_report = if contracts_path.exists() {
        read_json_file(&contracts_path)
            .ok()
            .and_then(|value| serde_json::from_value::<ContractsReport>(value).ok())
    } else {
        build_contracts_report(run_dir, plan_path, plan, &contracts_path, None).ok()
    };

    let mut surfaces = Vec::new();
    let mut findings = Vec::new();
    for source_path in &generated_sources {
        let path = match safe_join(run_dir, source_path) {
            Ok(path) => path,
            Err(err) => {
                findings.push(authority_finding(
                    "blocker",
                    "unsafe-source-path",
                    "Generated source path could not be inspected safely.",
                    vec![format!("{source_path}: {err}")],
                    Some(format!(
                        "rs autopilot audit-sources {} --format json",
                        command_arg(run_dir.to_string_lossy().as_ref())
                    )),
                ));
                continue;
            }
        };
        let Ok(source) = std::fs::read_to_string(&path) else {
            findings.push(authority_finding(
                "warning",
                "missing-source",
                "Generated source was referenced by the plan but could not be read for authority audit.",
                vec![source_path.clone()],
                Some(format!(
                    "rs autopilot certify {} --format json",
                    command_arg(run_dir.to_string_lossy().as_ref())
                )),
            ));
            continue;
        };
        let (script_path, class_name) = script_targets
            .get(source_path)
            .cloned()
            .unwrap_or((None, None));
        let side = authority_side(class_name.as_deref());
        let mut signals = authority_signals(&source);
        let mut surface_warnings = Vec::new();
        if side == "client" && authority_source_uses_data_store(&source) {
            findings.push(authority_finding(
                "blocker",
                "client-datastore",
                "Client-side generated source references DataStore APIs.",
                vec![source_path.clone()],
                Some(format!(
                    "rs autopilot audit-sources {} --format json",
                    command_arg(run_dir.to_string_lossy().as_ref())
                )),
            ));
            surface_warnings.push("client-datastore".into());
        }
        if side == "client" && authority_source_writes_player_state(&source) {
            findings.push(authority_finding(
                "warning",
                "client-state-write",
                "Client-side generated source appears to write player state or leaderstats.",
                vec![source_path.clone()],
                Some(format!(
                    "rs autopilot contracts {} --format json",
                    command_arg(run_dir.to_string_lossy().as_ref())
                )),
            ));
            surface_warnings.push("client-state-write".into());
        }
        if side == "client" && source.contains("_G.rsSetProfileValue") {
            findings.push(authority_finding(
                "warning",
                "client-profile-mutation",
                "Client source references the generated profile mutation helper.",
                vec![source_path.clone()],
                None,
            ));
            surface_warnings.push("client-profile-mutation".into());
        }
        if side == "server" && source.contains("game.CreatorId") {
            signals.push("creatorAdminGate".into());
        }
        signals.sort();
        signals.dedup();
        surfaces.push(AuthoritySurface {
            source_path: source_path.clone(),
            script_path,
            class_name,
            side: side.into(),
            signals,
            warnings: surface_warnings,
        });
    }

    if let Some(contracts) = &contracts_report {
        for finding in &contracts.findings {
            if finding.category == "server-remote-needs-validation-review" {
                findings.push(authority_finding(
                    "warning",
                    "remote-validation-review",
                    &finding.message,
                    finding.evidence.clone(),
                    Some(format!(
                        "rs autopilot contracts {} --format json",
                        command_arg(run_dir.to_string_lossy().as_ref())
                    )),
                ));
            }
            if finding.category == "missing-server-handler"
                || finding.category == "missing-client-handler"
                || finding.category == "orphan-remote"
            {
                findings.push(authority_finding(
                    "warning",
                    "one-sided-remote-contract",
                    &finding.message,
                    finding.evidence.clone(),
                    Some(format!(
                        "rs autopilot contracts {} --format json",
                        command_arg(run_dir.to_string_lossy().as_ref())
                    )),
                ));
            }
        }
    }
    findings.sort_by(|left, right| {
        left.severity
            .cmp(&right.severity)
            .then(left.category.cmp(&right.category))
            .then(left.message.cmp(&right.message))
    });
    findings.dedup_by(|left, right| {
        left.severity == right.severity
            && left.category == right.category
            && left.message == right.message
    });
    let mut blockers = findings
        .iter()
        .filter(|finding| finding.severity == "blocker")
        .map(|finding| finding.message.clone())
        .collect::<Vec<_>>();
    blockers.sort();
    blockers.dedup();
    let mut warnings = findings
        .iter()
        .filter(|finding| finding.severity == "warning")
        .map(|finding| finding.message.clone())
        .collect::<Vec<_>>();
    warnings.sort();
    warnings.dedup();
    let checks = build_authority_checks(run_dir, &surfaces, contracts_report.as_ref(), &findings);
    let status = if !blockers.is_empty() {
        "blocked"
    } else if !warnings.is_empty() {
        "needsAuthorityReview"
    } else {
        "serverAuthoritative"
    }
    .to_string();
    let score = authority_score(&checks, &findings);
    let mut next_actions = Vec::new();
    if !blockers.is_empty() || !warnings.is_empty() {
        next_actions.push(coach_action(
            1,
            "Review authority findings",
            Some(format!(
                "rs autopilot contracts {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Authority warnings usually come from weak or one-sided remotes; inspect the contract map before live apply.",
            false,
            false,
        ));
    }
    next_actions.push(coach_action(
        2,
        "Refresh source audit",
        Some(format!(
            "rs autopilot audit-sources {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Pair authority review with the generated Luau safety audit.",
        false,
        false,
    ));
    next_actions.push(coach_action(
        3,
        "Run live gate",
        Some(format!(
            "rs autopilot live-gate --run-dir {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Static authority evidence does not replace live readiness and creator approval.",
        true,
        false,
    ));
    dedup_next_actions(&mut next_actions);
    let agent_brief = format!(
        "Authority audit for '{}' is {} with score {}, {} blocker(s), and {} warning(s). Treat this as the exploit-surface review before approval or live apply.",
        plan.request.prompt,
        status,
        score,
        blockers.len(),
        warnings.len()
    );

    Ok(AuthorityReport {
        schema_version: "rs.autopilot.authority.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        authority_path: authority_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        score,
        checks,
        surfaces,
        findings,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn authority_side(class_name: Option<&str>) -> &'static str {
    match class_name {
        Some("LocalScript") => "client",
        Some("ModuleScript") => "shared",
        Some("Script") => "server",
        _ => "unknown",
    }
}

fn authority_signals(source: &str) -> Vec<String> {
    let mut signals = Vec::new();
    for (needle, signal) in [
        ("DataStoreService", "dataStore"),
        ("leaderstats", "leaderstats"),
        (":FireServer", "clientRemoteCall"),
        (":InvokeServer", "clientRemoteCall"),
        ("OnServerEvent", "serverRemoteHandler"),
        ("OnServerInvoke", "serverRemoteHandler"),
        (":FireClient", "serverRemoteEmit"),
        (":FireAllClients", "serverRemoteEmit"),
        ("OnClientEvent", "clientRemoteListener"),
        ("_G.rsSetProfileValue", "profileMutation"),
        ("game.CreatorId", "creatorGate"),
    ] {
        if source.contains(needle) {
            signals.push(signal.into());
        }
    }
    signals
}

fn authority_source_uses_data_store(source: &str) -> bool {
    source.contains("DataStoreService")
        || source.contains(":GetAsync")
        || source.contains(":SetAsync")
        || source.contains(":UpdateAsync")
}

fn authority_source_writes_player_state(source: &str) -> bool {
    (source.contains("leaderstats") || source.contains("Coins") || source.contains("Cash"))
        && (source.contains(".Value =")
            || source.contains(".Value +=")
            || source.contains(".Value -="))
}

fn build_authority_checks(
    run_dir: &Path,
    surfaces: &[AuthoritySurface],
    contracts: Option<&ContractsReport>,
    findings: &[AuthorityFinding],
) -> Vec<AuthorityCheck> {
    let client_datastore = findings
        .iter()
        .any(|finding| finding.category == "client-datastore");
    let client_state_write = findings
        .iter()
        .any(|finding| finding.category == "client-state-write");
    let remote_contract_warning = findings.iter().any(|finding| {
        finding.category == "remote-validation-review"
            || finding.category == "one-sided-remote-contract"
    });
    let server_scripts = surfaces
        .iter()
        .filter(|surface| surface.side == "server")
        .count();
    let client_scripts = surfaces
        .iter()
        .filter(|surface| surface.side == "client")
        .count();
    vec![
        authority_check(
            "datastore-server-only",
            "Persistent data stays server-side",
            if client_datastore { "fail" } else { "pass" },
            if client_datastore {
                "Client source references DataStore APIs.".into()
            } else {
                "No client-side DataStore access found in generated sources.".into()
            },
            surfaces
                .iter()
                .filter(|surface| surface.signals.iter().any(|signal| signal == "dataStore"))
                .map(|surface| surface.source_path.clone())
                .collect(),
            Some(format!(
                "rs autopilot audit-sources {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
        authority_check(
            "client-state-writes",
            "Client scripts do not own authoritative player state",
            if client_state_write { "warn" } else { "pass" },
            if client_state_write {
                "Client source appears to write player state or leaderstats.".into()
            } else {
                "No generated client-side leaderstats or currency writes found.".into()
            },
            surfaces
                .iter()
                .filter(|surface| {
                    surface
                        .warnings
                        .iter()
                        .any(|item| item == "client-state-write")
                })
                .map(|surface| surface.source_path.clone())
                .collect(),
            None,
        ),
        authority_check(
            "remote-contract-validation",
            "Remote contracts have reviewable server authority",
            if remote_contract_warning {
                "warn"
            } else if contracts.is_some_and(|contracts| contracts.remote_count == 0) {
                "skip"
            } else {
                "pass"
            },
            if remote_contract_warning {
                "Remote contracts need validation or one-sided wiring review.".into()
            } else {
                "Remote contract wiring has no authority warnings.".into()
            },
            findings
                .iter()
                .filter(|finding| {
                    finding.category == "remote-validation-review"
                        || finding.category == "one-sided-remote-contract"
                })
                .flat_map(|finding| finding.evidence.clone())
                .collect(),
            Some(format!(
                "rs autopilot contracts {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
        authority_check(
            "server-runtime-owner",
            "Server scripts own runtime gameplay decisions",
            if server_scripts > 0 || client_scripts == 0 {
                "pass"
            } else {
                "warn"
            },
            format!("{server_scripts} server script(s), {client_scripts} client script(s)"),
            surfaces
                .iter()
                .filter(|surface| surface.side == "server")
                .map(|surface| surface.source_path.clone())
                .collect(),
            None,
        ),
    ]
}

fn authority_check(
    id: &str,
    title: &str,
    status: &str,
    summary: String,
    evidence: Vec<String>,
    command: Option<String>,
) -> AuthorityCheck {
    AuthorityCheck {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        summary,
        evidence,
        command,
    }
}

fn authority_score(checks: &[AuthorityCheck], findings: &[AuthorityFinding]) -> u8 {
    if findings.iter().any(|finding| finding.severity == "blocker") {
        return 30;
    }
    let total = checks
        .iter()
        .map(|check| match check.status.as_str() {
            "pass" => 100u32,
            "skip" => 80,
            "warn" => 65,
            "fail" => 0,
            _ => 50,
        })
        .sum::<u32>();
    let base = if checks.is_empty() {
        0
    } else {
        (total / checks.len() as u32) as u8
    };
    base.saturating_sub(
        findings
            .iter()
            .filter(|finding| finding.severity == "warning")
            .count() as u8
            * 3,
    )
}

fn authority_finding(
    severity: &str,
    category: &str,
    message: &str,
    evidence: Vec<String>,
    command: Option<String>,
) -> AuthorityFinding {
    AuthorityFinding {
        severity: severity.into(),
        category: category.into(),
        message: message.into(),
        evidence,
        command,
    }
}

fn resolve_ux_paths(options: &UxOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot ux requires a run directory or --plan".into(),
        )),
    }
}

fn build_ux_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    ux_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<UxReport> {
    let generated_sources = generated_files_for_plan(plan);
    let mut source_texts = BTreeMap::new();
    let mut findings = Vec::new();
    for source_path in &generated_sources {
        match safe_join(run_dir, source_path) {
            Ok(path) => match std::fs::read_to_string(path) {
                Ok(source) => {
                    source_texts.insert(source_path.clone(), source);
                }
                Err(_) => findings.push(ux_finding(
                    "warning",
                    "missing-source",
                    "Generated source could not be read for UX audit.",
                    vec![source_path.clone()],
                    Some(format!(
                        "rs autopilot refresh {} --format json",
                        command_arg(run_dir.to_string_lossy().as_ref())
                    )),
                )),
            },
            Err(err) => findings.push(ux_finding(
                "blocker",
                "unsafe-source-path",
                "Generated source path could not be inspected safely.",
                vec![format!("{source_path}: {err}")],
                None,
            )),
        }
    }

    let script_targets = plan
        .operations
        .iter()
        .filter(|operation| is_script_operation(operation))
        .filter_map(|operation| {
            operation.source_path.as_ref().map(|source_path| {
                (
                    impact_operation_path(operation).unwrap_or_else(|| source_path.clone()),
                    source_path.clone(),
                )
            })
        })
        .collect::<BTreeMap<_, _>>();

    let mut surfaces = Vec::new();
    for operation in &plan.operations {
        if !is_ux_surface_operation(operation) {
            continue;
        }
        let path = impact_operation_path(operation)
            .or_else(|| operation.path.clone())
            .unwrap_or_else(|| operation.id.clone());
        let class_name = operation
            .class_name
            .clone()
            .unwrap_or_else(|| "Unknown".into());
        let role = ux_role_for_class(&class_name, &path);
        let mut properties = ux_property_names(operation);
        let mut evidence = ux_operation_evidence(operation);
        let mut warnings = Vec::new();
        if ux_is_text_surface(&class_name) && !operation.properties.contains_key("TextScaled") {
            warnings.push("text-scaled-not-declared".into());
        }
        if ux_is_interactive_surface(&class_name) && ux_surface_text(operation).is_none() {
            warnings.push("interactive-control-without-text".into());
        }
        if let Some(text) = ux_surface_text(operation) {
            evidence.push(format!("text:{text}"));
        }
        properties.sort();
        properties.dedup();
        evidence.sort();
        evidence.dedup();
        warnings.sort();
        warnings.dedup();
        surfaces.push(UxSurface {
            source_path: script_targets.get(&path).cloned(),
            path,
            class_name,
            name: operation.name.clone(),
            role,
            properties,
            evidence,
            warnings,
        });
    }
    surfaces.sort_by(|left, right| left.path.cmp(&right.path));

    let ui_surface_count = surfaces
        .iter()
        .filter(|surface| surface.role != "script")
        .count();
    let interactive_control_count = surfaces
        .iter()
        .filter(|surface| surface.role == "control" || surface.role == "worldPrompt")
        .count();
    let feedback_signal_count = ux_feedback_signal_count(&source_texts, &surfaces);
    let interactive_handlers = ux_interactive_handler_evidence(&source_texts);
    let onboarding_copy = ux_onboarding_copy(&surfaces);
    let readable_text = surfaces.iter().filter(|surface| {
        surface
            .properties
            .iter()
            .any(|property| property == "TextScaled")
            || surface
                .properties
                .iter()
                .any(|property| property == "TextSize")
    });
    let readable_text_count = readable_text.count();
    let text_surface_count = surfaces
        .iter()
        .filter(|surface| ux_is_text_surface(&surface.class_name))
        .count();

    if ui_surface_count == 0 {
        findings.push(ux_finding(
            "warning",
            "missing-ui-surface",
            "No generated UI or world prompt surface was found.",
            vec![plan_path.to_string_lossy().to_string()],
            Some(format!(
                "rs autopilot critique --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ));
    }
    if interactive_control_count > 0 && interactive_handlers.is_empty() {
        findings.push(ux_finding(
            "warning",
            "unwired-player-control",
            "Generated player controls have no obvious client or prompt interaction handler.",
            surfaces
                .iter()
                .filter(|surface| surface.role == "control" || surface.role == "worldPrompt")
                .map(|surface| surface.path.clone())
                .collect(),
            Some(format!(
                "rs autopilot graph --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ));
    }
    if feedback_signal_count == 0 {
        findings.push(ux_finding(
            "warning",
            "missing-feedback-loop",
            "No generated UI feedback signal or status text update was found.",
            generated_sources.clone(),
            Some(format!(
                "rs autopilot simulate --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ));
    }
    if ui_surface_count > 0 && onboarding_copy.is_empty() {
        findings.push(ux_finding(
            "warning",
            "missing-onboarding-copy",
            "Generated UI has no obvious player-facing action or goal copy.",
            surfaces
                .iter()
                .map(|surface| surface.path.clone())
                .collect(),
            None,
        ));
    }

    findings.sort_by(|left, right| {
        left.severity
            .cmp(&right.severity)
            .then(left.category.cmp(&right.category))
            .then(left.message.cmp(&right.message))
    });
    findings.dedup_by(|left, right| {
        left.severity == right.severity
            && left.category == right.category
            && left.message == right.message
    });

    let checks = vec![
        ux_check(
            "ui-surface-present",
            "Player-facing surface exists",
            if ui_surface_count > 0 { "pass" } else { "warn" },
            format!("{ui_surface_count} UI or prompt surface(s) detected"),
            surfaces.iter().map(|surface| surface.path.clone()).collect(),
            None,
        ),
        ux_check(
            "player-action-affordance",
            "Player actions are visible and wired",
            if interactive_control_count == 0 {
                "warn"
            } else if interactive_handlers.is_empty() {
                "warn"
            } else {
                "pass"
            },
            format!(
                "{} control surface(s), {} interaction handler signal(s)",
                interactive_control_count,
                interactive_handlers.len()
            ),
            interactive_handlers.clone(),
            Some(format!(
                "rs autopilot graph --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
        ux_check(
            "feedback-loop",
            "Player receives visible feedback",
            if feedback_signal_count > 0 { "pass" } else { "warn" },
            format!("{feedback_signal_count} feedback signal(s) detected"),
            ux_feedback_evidence(&source_texts, &surfaces),
            Some(format!(
                "rs autopilot playtest --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
        ux_check(
            "onboarding-copy",
            "UI explains the next action",
            if onboarding_copy.is_empty() {
                "warn"
            } else {
                "pass"
            },
            format!("{} player-facing copy item(s)", onboarding_copy.len()),
            onboarding_copy,
            None,
        ),
        ux_check(
            "readability",
            "Text has readable sizing evidence",
            if text_surface_count == 0 {
                "skip"
            } else if readable_text_count > 0 {
                "pass"
            } else {
                "warn"
            },
            format!("{readable_text_count}/{text_surface_count} text surface(s) declare scaling or size"),
            surfaces
                .iter()
                .filter(|surface| ux_is_text_surface(&surface.class_name))
                .map(|surface| surface.path.clone())
                .collect(),
            None,
        ),
    ];

    let mut blockers = findings
        .iter()
        .filter(|finding| finding.severity == "blocker")
        .map(|finding| finding.message.clone())
        .collect::<Vec<_>>();
    blockers.sort();
    blockers.dedup();
    let mut warnings = findings
        .iter()
        .filter(|finding| finding.severity == "warning")
        .map(|finding| finding.message.clone())
        .collect::<Vec<_>>();
    warnings.extend(surfaces.iter().flat_map(|surface| {
        surface
            .warnings
            .iter()
            .map(|warning| format!("{}: {}", surface.path, warning))
            .collect::<Vec<_>>()
    }));
    warnings.sort();
    warnings.dedup();

    let score = ux_score(&checks, &findings);
    let status = if !blockers.is_empty() {
        "blocked"
    } else if !warnings.is_empty() || score < 85 {
        "needsUxReview"
    } else {
        "playerReadable"
    }
    .to_string();
    let mut next_actions = Vec::new();
    if status == "needsUxReview" {
        next_actions.push(coach_action(
            1,
            "Patch player-facing UX gaps",
            Some(format!(
                "rs autopilot improve --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "UX warnings mean players may not see the next action or receive clear feedback.",
            false,
            false,
        ));
    }
    next_actions.push(coach_action(
        2,
        "Run live playtest checklist",
        Some(format!(
            "rs autopilot playtest --run-dir {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Static UX evidence should be confirmed with Play Solo observations after approved apply.",
        false,
        false,
    ));
    next_actions.push(coach_action(
        3,
        "Refresh static player journey",
        Some(format!(
            "rs autopilot simulate --run-dir {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "UX evidence and player-journey evidence should agree before asking for approval.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);
    let agent_brief = format!(
        "UX audit for '{}' is {} with score {}, {} UI surface(s), {} control(s), and {} feedback signal(s). Use this before claiming the slice is understandable to a player.",
        plan.request.prompt,
        status,
        score,
        ui_surface_count,
        interactive_control_count,
        feedback_signal_count
    );

    Ok(UxReport {
        schema_version: "rs.autopilot.ux.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        ux_path: ux_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        score,
        ui_surface_count,
        interactive_control_count,
        feedback_signal_count,
        checks,
        surfaces,
        findings,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn is_ux_surface_operation(operation: &AutopilotOperation) -> bool {
    let class_name = operation.class_name.as_deref().unwrap_or_default();
    matches!(
        class_name,
        "ScreenGui"
            | "SurfaceGui"
            | "BillboardGui"
            | "Frame"
            | "TextLabel"
            | "TextButton"
            | "TextBox"
            | "ImageButton"
            | "ImageLabel"
            | "ProximityPrompt"
    ) || operation
        .parent_path
        .as_deref()
        .is_some_and(|path| path.contains("StarterGui"))
        || operation
            .path
            .as_deref()
            .is_some_and(|path| path.contains("StarterGui"))
}

fn ux_role_for_class(class_name: &str, path: &str) -> String {
    match class_name {
        "ScreenGui" | "SurfaceGui" | "BillboardGui" => "root",
        "Frame" => "panel",
        "TextButton" | "ImageButton" => "control",
        "TextBox" => "input",
        "TextLabel" | "ImageLabel" => "feedback",
        "ProximityPrompt" => "worldPrompt",
        "LocalScript" | "Script" | "ModuleScript" => "script",
        _ if path.contains("StarterGui") => "ui",
        _ => "surface",
    }
    .into()
}

fn ux_property_names(operation: &AutopilotOperation) -> Vec<String> {
    let mut properties = operation.properties.keys().cloned().collect::<Vec<_>>();
    properties.sort();
    properties
}

fn ux_operation_evidence(operation: &AutopilotOperation) -> Vec<String> {
    let mut evidence = Vec::new();
    if let Some(path) = impact_operation_path(operation) {
        evidence.push(path);
    }
    if let Some(class_name) = &operation.class_name {
        evidence.push(format!("class:{class_name}"));
    }
    for key in ["Text", "ActionText", "ObjectText", "TextScaled", "TextSize"] {
        if operation.properties.contains_key(key) {
            evidence.push(format!("property:{key}"));
        }
    }
    evidence
}

fn ux_surface_text(operation: &AutopilotOperation) -> Option<String> {
    for key in ["Text", "ActionText", "ObjectText"] {
        let Some(value) = operation.properties.get(key) else {
            continue;
        };
        if let Some(text) = value.as_str() {
            let text = text.trim();
            if !text.is_empty() {
                return Some(text.chars().take(80).collect());
            }
        }
    }
    None
}

fn ux_is_text_surface(class_name: &str) -> bool {
    matches!(class_name, "TextLabel" | "TextButton" | "TextBox")
}

fn ux_is_interactive_surface(class_name: &str) -> bool {
    matches!(
        class_name,
        "TextButton" | "ImageButton" | "TextBox" | "ProximityPrompt"
    )
}

fn ux_interactive_handler_evidence(source_texts: &BTreeMap<String, String>) -> Vec<String> {
    let mut evidence = Vec::new();
    for (source_path, source) in source_texts {
        for needle in [
            ".Activated:Connect",
            ".MouseButton1Click:Connect",
            ".MouseButton1Down:Connect",
            ".Triggered:Connect",
            "UserInputService",
        ] {
            if source.contains(needle) {
                evidence.push(format!("{source_path}:{needle}"));
            }
        }
    }
    evidence.sort();
    evidence.dedup();
    evidence
}

fn ux_feedback_signal_count(
    source_texts: &BTreeMap<String, String>,
    surfaces: &[UxSurface],
) -> usize {
    ux_feedback_evidence(source_texts, surfaces).len()
}

fn ux_feedback_evidence(
    source_texts: &BTreeMap<String, String>,
    surfaces: &[UxSurface],
) -> Vec<String> {
    let mut evidence = surfaces
        .iter()
        .filter(|surface| surface.role == "feedback")
        .map(|surface| surface.path.clone())
        .collect::<Vec<_>>();
    for (source_path, source) in source_texts {
        for needle in [
            ".Text =",
            ".Visible =",
            "OnClientEvent",
            ":FireClient",
            ":FireAllClients",
            "statusLabel",
            "feedback",
        ] {
            if source.contains(needle) {
                evidence.push(format!("{source_path}:{needle}"));
            }
        }
    }
    evidence.sort();
    evidence.dedup();
    evidence
}

fn ux_onboarding_copy(surfaces: &[UxSurface]) -> Vec<String> {
    let mut copy = Vec::new();
    for surface in surfaces {
        for evidence in &surface.evidence {
            let Some(text) = evidence.strip_prefix("text:") else {
                continue;
            };
            let lower = text.to_ascii_lowercase();
            if [
                "buy", "claim", "upgrade", "stage", "quest", "attack", "talk", "find", "coins",
                "cash", "ready", "press", "equip",
            ]
            .iter()
            .any(|needle| lower.contains(needle))
            {
                copy.push(format!("{}:{text}", surface.path));
            }
        }
    }
    copy.sort();
    copy.dedup();
    copy
}

fn ux_check(
    id: &str,
    title: &str,
    status: &str,
    summary: String,
    evidence: Vec<String>,
    command: Option<String>,
) -> UxCheck {
    UxCheck {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        summary,
        evidence,
        command,
    }
}

fn ux_score(checks: &[UxCheck], findings: &[UxFinding]) -> u8 {
    if findings.iter().any(|finding| finding.severity == "blocker") {
        return 35;
    }
    let total = checks
        .iter()
        .map(|check| match check.status.as_str() {
            "pass" => 100u32,
            "skip" => 80,
            "warn" => 60,
            "fail" => 0,
            _ => 50,
        })
        .sum::<u32>();
    let base = if checks.is_empty() {
        0
    } else {
        (total / checks.len() as u32) as u8
    };
    base.saturating_sub(
        findings
            .iter()
            .filter(|finding| finding.severity == "warning")
            .count() as u8
            * 4,
    )
}

fn ux_finding(
    severity: &str,
    category: &str,
    message: &str,
    evidence: Vec<String>,
    command: Option<String>,
) -> UxFinding {
    UxFinding {
        severity: severity.into(),
        category: category.into(),
        message: message.into(),
        evidence,
        command,
    }
}

fn resolve_copy_deck_paths(options: &CopyDeckOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot copy-deck requires a run directory or --plan".into(),
        )),
    }
}

fn build_copy_deck_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    copy_deck_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<CopyDeckReport> {
    let mut entries = Vec::new();
    let mut findings = Vec::new();
    for operation in &plan.operations {
        let path = impact_operation_path(operation).or_else(|| operation.path.clone());
        for key in ["Text", "ActionText", "ObjectText", "PlaceholderText"] {
            let Some(value) = operation.properties.get(key) else {
                continue;
            };
            let Some(text) = value
                .as_str()
                .map(str::trim)
                .filter(|text| !text.is_empty())
            else {
                continue;
            };
            entries.push(copy_deck_entry(
                text,
                copy_role_for_property(key, operation.class_name.as_deref()),
                "planProperty",
                None,
                path.clone(),
                operation.class_name.clone(),
                false,
            ));
        }
    }

    for source_path in generated_files_for_plan(plan) {
        let source = match safe_join(run_dir, &source_path) {
            Ok(path) => match std::fs::read_to_string(path) {
                Ok(source) => source,
                Err(_) => {
                    findings.push(copy_deck_finding(
                        "warning",
                        "missing-source",
                        "Generated source could not be read for copy extraction.",
                        vec![source_path.clone()],
                        Some(format!(
                            "rs autopilot refresh {} --format json",
                            command_arg(run_dir.to_string_lossy().as_ref())
                        )),
                    ));
                    continue;
                }
            },
            Err(err) => {
                findings.push(copy_deck_finding(
                    "blocker",
                    "unsafe-source-path",
                    "Generated source path could not be inspected safely.",
                    vec![format!("{source_path}: {err}")],
                    None,
                ));
                continue;
            }
        };
        for (line_number, line) in source.lines().enumerate() {
            if !copy_line_is_player_facing(line) {
                continue;
            }
            for text in quoted_lua_strings(line) {
                if !copy_string_is_player_facing(&text) {
                    continue;
                }
                entries.push(copy_deck_entry(
                    &text,
                    copy_role_for_source_line(line),
                    "generatedSource",
                    Some(format!("{}:{}", source_path, line_number + 1)),
                    None,
                    None,
                    copy_line_is_dynamic(line),
                ));
            }
        }
    }

    entries.sort_by(|left, right| {
        left.role
            .cmp(&right.role)
            .then(left.text.cmp(&right.text))
            .then(left.source_path.cmp(&right.source_path))
    });
    entries.dedup_by(|left, right| {
        left.text == right.text
            && left.role == right.role
            && left.source_path == right.source_path
            && left.studio_path == right.studio_path
    });
    for (index, entry) in entries.iter_mut().enumerate() {
        entry.id = format!("copy-{:03}", index + 1);
    }

    if entries.is_empty() {
        findings.push(copy_deck_finding(
            "warning",
            "missing-player-copy",
            "No generated player-facing copy was found.",
            vec![plan_path.to_string_lossy().to_string()],
            Some(format!(
                "rs autopilot ux {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ));
    }
    let placeholder = entries
        .iter()
        .filter(|entry| {
            let lower = entry.text.to_ascii_lowercase();
            lower.contains("todo") || lower.contains("placeholder") || lower.contains("lorem")
        })
        .map(|entry| entry.text.clone())
        .collect::<Vec<_>>();
    if !placeholder.is_empty() {
        findings.push(copy_deck_finding(
            "blocker",
            "placeholder-copy",
            "Generated player-facing copy contains placeholder text.",
            placeholder,
            None,
        ));
    }
    let long = entries
        .iter()
        .filter(|entry| entry.text.chars().count() > 80)
        .map(|entry| entry.text.clone())
        .collect::<Vec<_>>();
    if !long.is_empty() {
        findings.push(copy_deck_finding(
            "warning",
            "long-copy",
            "Some generated copy may be too long for compact Roblox UI surfaces.",
            long,
            None,
        ));
    }
    let feedback_count = entries
        .iter()
        .filter(|entry| entry.role == "feedback" || entry.role == "status")
        .count();
    if !entries.is_empty() && feedback_count == 0 {
        findings.push(copy_deck_finding(
            "warning",
            "missing-feedback-copy",
            "Generated copy has no obvious status or feedback line.",
            entries
                .iter()
                .map(|entry| entry.text.clone())
                .take(8)
                .collect(),
            Some(format!(
                "rs autopilot ux {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ));
    }
    findings.sort_by(|left, right| {
        left.severity
            .cmp(&right.severity)
            .then(left.category.cmp(&right.category))
            .then(left.message.cmp(&right.message))
    });
    findings.dedup_by(|left, right| {
        left.severity == right.severity
            && left.category == right.category
            && left.message == right.message
    });

    let mut blockers = findings
        .iter()
        .filter(|finding| finding.severity == "blocker")
        .map(|finding| finding.message.clone())
        .collect::<Vec<_>>();
    blockers.sort();
    blockers.dedup();
    let mut warnings = findings
        .iter()
        .filter(|finding| finding.severity == "warning")
        .map(|finding| finding.message.clone())
        .collect::<Vec<_>>();
    warnings.sort();
    warnings.dedup();

    let surface_count = entries
        .iter()
        .filter_map(|entry| entry.studio_path.clone())
        .collect::<BTreeSet<_>>()
        .len();
    let dynamic_string_count = entries.iter().filter(|entry| entry.dynamic).count();
    let status = if !blockers.is_empty() {
        "blocked"
    } else if !warnings.is_empty() {
        "needsCopyReview"
    } else {
        "copyReady"
    }
    .to_string();
    let mut next_actions = Vec::new();
    if status != "copyReady" {
        next_actions.push(coach_action(
            1,
            "Review generated copy",
            Some(format!(
                "rs autopilot copy-deck {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Copy warnings should be resolved before claiming the player-facing experience is polished.",
            false,
            false,
        ));
    }
    next_actions.push(coach_action(
        2,
        "Check player UX",
        Some(format!(
            "rs autopilot ux {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "The copy deck should agree with the affordance and feedback audit.",
        false,
        false,
    ));
    next_actions.push(coach_action(
        3,
        "Run playtest checklist",
        Some(format!(
            "rs autopilot playtest --run-dir {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Static copy should be confirmed during live Play Solo after approved apply.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);
    let agent_brief = format!(
        "Copy deck for '{}' is {} with {} string(s), {} surface(s), and {} dynamic string(s). Use this to review UI text, feedback, and localization readiness before live apply.",
        plan.request.prompt,
        status,
        entries.len(),
        surface_count,
        dynamic_string_count
    );

    Ok(CopyDeckReport {
        schema_version: "rs.autopilot.copy-deck.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        copy_deck_path: copy_deck_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        string_count: entries.len(),
        surface_count,
        dynamic_string_count,
        entries,
        findings,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn copy_deck_entry(
    text: &str,
    role: &str,
    source: &str,
    source_path: Option<String>,
    studio_path: Option<String>,
    class_name: Option<String>,
    dynamic: bool,
) -> CopyDeckEntry {
    let mut notes = Vec::new();
    if dynamic {
        notes.push("dynamic".into());
    }
    if text.contains('%') || text.contains('{') {
        notes.push("formatted".into());
    }
    let localization_ready = !dynamic && !text.contains("..") && !text.contains("string.format");
    CopyDeckEntry {
        id: String::new(),
        text: text.trim().chars().take(160).collect(),
        role: role.into(),
        source: source.into(),
        source_path,
        studio_path,
        class_name,
        dynamic,
        localization_ready,
        notes,
    }
}

fn copy_role_for_property(property: &str, class_name: Option<&str>) -> &'static str {
    match (property, class_name.unwrap_or_default()) {
        ("ActionText", _) | ("ObjectText", _) => "prompt",
        ("PlaceholderText", _) => "inputHint",
        ("Text", "TextButton") | ("Text", "ImageButton") => "button",
        ("Text", "TextLabel") => "label",
        ("Text", "TextBox") => "input",
        ("Text", _) => "copy",
        _ => "copy",
    }
}

fn copy_role_for_source_line(line: &str) -> &'static str {
    let lower = line.to_ascii_lowercase();
    if lower.contains("status")
        || lower.contains("message")
        || lower.contains("feedback")
        || lower.contains("ok and")
        || lower.contains("not enough")
        || lower.contains("bought")
    {
        "feedback"
    } else if lower.contains("button.text")
        || lower.contains("claim.text")
        || lower.contains("run.text")
    {
        "button"
    } else if lower.contains("label.text") || lower.contains("title.text") {
        "label"
    } else {
        "copy"
    }
}

fn copy_line_is_player_facing(line: &str) -> bool {
    let lower = line.to_ascii_lowercase();
    lower.contains(".text")
        || lower.contains("actiontext")
        || lower.contains("objecttext")
        || lower.contains("placeholdertext")
        || lower.contains("message")
        || lower.contains("feedback")
}

fn copy_string_is_player_facing(text: &str) -> bool {
    let trimmed = text.trim();
    if trimmed.len() < 2 {
        return false;
    }
    let lower = trimmed.to_ascii_lowercase();
    ![
        "players",
        "replicatedstorage",
        "workspace",
        "serverscriptservice",
        "startergui",
        "panel",
    ]
    .iter()
    .any(|needle| lower == *needle)
}

fn copy_line_is_dynamic(line: &str) -> bool {
    line.contains("string.format") || line.contains("..") || line.contains("tostring(")
}

fn quoted_lua_strings(line: &str) -> Vec<String> {
    let mut strings = Vec::new();
    let mut quote = None;
    let mut start = 0usize;
    let mut escaped = false;
    for (index, ch) in line.char_indices() {
        if escaped {
            escaped = false;
            continue;
        }
        if ch == '\\' {
            escaped = true;
            continue;
        }
        match quote {
            Some(active) if ch == active => {
                strings.push(line[start..index].to_string());
                quote = None;
            }
            None if ch == '"' || ch == '\'' => {
                quote = Some(ch);
                start = index + ch.len_utf8();
            }
            _ => {}
        }
    }
    strings
}

fn copy_deck_finding(
    severity: &str,
    category: &str,
    message: &str,
    evidence: Vec<String>,
    command: Option<String>,
) -> CopyDeckFinding {
    CopyDeckFinding {
        severity: severity.into(),
        category: category.into(),
        message: message.into(),
        evidence,
        command,
    }
}

#[derive(Default)]
struct PerformanceSourceStats {
    source_line_count: usize,
    loop_count: usize,
    wait_call_count: usize,
    remote_reference_count: usize,
    datastore_reference_count: usize,
    task_spawn_count: usize,
    evidence: Vec<String>,
}

fn resolve_performance_paths(options: &PerformanceOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot performance requires a run directory or --plan".into(),
        )),
    }
}

fn build_performance_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    performance_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<PerformanceReport> {
    let generated_sources = generated_files_for_plan(plan);
    let instance_count = plan
        .operations
        .iter()
        .filter(|operation| operation.class_name.is_some())
        .count();
    let script_count = plan
        .operations
        .iter()
        .filter(|operation| {
            operation.source_path.is_some()
                || matches!(
                    operation.class_name.as_deref(),
                    Some("Script" | "LocalScript" | "ModuleScript")
                )
        })
        .count();
    let mut stats = PerformanceSourceStats::default();
    let mut findings = Vec::new();
    for source_path in &generated_sources {
        match safe_join(run_dir, source_path) {
            Ok(path) => match std::fs::read_to_string(path) {
                Ok(source) => collect_performance_source_stats(source_path, &source, &mut stats),
                Err(_) => findings.push(performance_finding(
                    "warning",
                    "missing-source",
                    "Generated source could not be read for performance analysis.",
                    vec![source_path.clone()],
                    Some(format!(
                        "rs autopilot refresh {} --format json",
                        command_arg(run_dir.to_string_lossy().as_ref())
                    )),
                )),
            },
            Err(err) => findings.push(performance_finding(
                "blocker",
                "unsafe-source-path",
                "Generated source path could not be inspected safely.",
                vec![format!("{source_path}: {err}")],
                None,
            )),
        }
    }

    let mut metrics = vec![
        performance_metric(
            "instance-count",
            "Planned instance delta",
            instance_count,
            120,
            vec![format!("operations={}", plan.operations.len())],
        ),
        performance_metric(
            "script-count",
            "Generated script count",
            script_count,
            8,
            generated_sources.clone(),
        ),
        performance_metric(
            "source-lines",
            "Generated source size",
            stats.source_line_count,
            900,
            stats.evidence.iter().take(8).cloned().collect(),
        ),
        performance_metric(
            "loops",
            "Loop and frame-step patterns",
            stats.loop_count,
            12,
            stats.evidence.iter().take(8).cloned().collect(),
        ),
        performance_metric(
            "wait-calls",
            "Yield and delay calls",
            stats.wait_call_count,
            12,
            stats.evidence.iter().take(8).cloned().collect(),
        ),
        performance_metric(
            "remote-references",
            "Remote traffic references",
            stats.remote_reference_count,
            30,
            stats.evidence.iter().take(8).cloned().collect(),
        ),
    ];
    metrics.push(PerformanceMetric {
        id: "datastore-references".into(),
        title: "Persistence references".into(),
        value: stats.datastore_reference_count,
        budget: 0,
        status: if stats.datastore_reference_count == 0 {
            "pass".into()
        } else {
            "warn".into()
        },
        summary: if stats.datastore_reference_count == 0 {
            "no generated DataStore references found".into()
        } else {
            format!(
                "{} DataStore reference(s) require live-place and budget review",
                stats.datastore_reference_count
            )
        },
        evidence: stats.evidence.iter().take(8).cloned().collect(),
    });

    if stats.task_spawn_count > 8 {
        findings.push(performance_finding(
            "warning",
            "async-fanout",
            "Generated source uses many async spawn/defer patterns.",
            vec![format!("taskSpawnCount={}", stats.task_spawn_count)],
            None,
        ));
    }

    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    for metric in &metrics {
        match metric.status.as_str() {
            "fail" => blockers.push(metric.summary.clone()),
            "warn" => warnings.push(metric.summary.clone()),
            _ => {}
        }
    }
    for finding in &findings {
        match finding.severity.as_str() {
            "blocker" => blockers.push(finding.message.clone()),
            "warning" => warnings.push(finding.message.clone()),
            _ => {}
        }
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else if !warnings.is_empty() {
        "needsPerformanceReview"
    } else {
        "performanceReady"
    }
    .to_string();
    let score = performance_score(&metrics, &findings);
    let mut next_actions = Vec::new();
    if status != "performanceReady" {
        next_actions.push(coach_action(
            1,
            "Review performance budget",
            Some(format!(
                "rs autopilot performance {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Performance warnings should be reviewed before claiming the slice is lightweight.",
            false,
            false,
        ));
    }
    next_actions.push(coach_action(
        2,
        "Refresh offline packet",
        Some(format!(
            "rs autopilot refresh {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Refresh bundle, certification, trace, and planner context after performance changes.",
        false,
        false,
    ));
    next_actions.push(coach_action(
        3,
        "Validate live behavior",
        Some(format!(
            "rs autopilot playtest --run-dir {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Static performance signals still need live Play Solo observation after approved apply.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);

    let agent_brief = format!(
        "Performance audit for '{}' is {} with score {}. It estimates {} instance(s), {} script(s), {} generated source line(s), {} loop/frame pattern(s), and {} remote reference(s).",
        plan.request.prompt,
        status,
        score,
        instance_count,
        script_count,
        stats.source_line_count,
        stats.loop_count,
        stats.remote_reference_count
    );

    Ok(PerformanceReport {
        schema_version: "rs.autopilot.performance.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        performance_path: performance_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        score,
        operation_count: plan.operations.len(),
        instance_count,
        script_count,
        generated_source_count: generated_sources.len(),
        source_line_count: stats.source_line_count,
        loop_count: stats.loop_count,
        wait_call_count: stats.wait_call_count,
        remote_reference_count: stats.remote_reference_count,
        datastore_reference_count: stats.datastore_reference_count,
        metrics,
        findings,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn collect_performance_source_stats(
    source_path: &str,
    source: &str,
    stats: &mut PerformanceSourceStats,
) {
    let line_count = source.lines().count();
    stats.source_line_count += line_count;
    stats
        .evidence
        .push(format!("{source_path}:lines={line_count}"));
    for (line_number, line) in source.lines().enumerate() {
        let trimmed = line.trim();
        let lower = trimmed.to_ascii_lowercase();
        if lower.starts_with("while ")
            || (lower.starts_with("for ") && lower.contains(" do"))
            || lower.contains("runservice")
            || lower.contains(".heartbeat")
            || lower.contains(".stepped")
            || lower.contains(".renderstepped")
        {
            stats.loop_count += 1;
            stats
                .evidence
                .push(format!("{source_path}:{} loop/frame", line_number + 1));
        }
        if lower.contains("task.wait(") || lower.contains("wait(") || lower.contains("task.delay(")
        {
            stats.wait_call_count += 1;
        }
        if lower.contains("task.spawn(")
            || lower.contains("task.defer(")
            || lower.contains("spawn(")
        {
            stats.task_spawn_count += 1;
        }
        if lower.contains("fireserver")
            || lower.contains("fireclient")
            || lower.contains("fireallclients")
            || lower.contains("invokeserver")
            || lower.contains("invokeclient")
            || lower.contains("remoteevent")
            || lower.contains("remotefunction")
        {
            stats.remote_reference_count += 1;
        }
        if lower.contains("datastoreservice") || lower.contains("getdatastore") {
            stats.datastore_reference_count += 1;
        }
    }
}

fn performance_metric(
    id: &str,
    title: &str,
    value: usize,
    budget: usize,
    evidence: Vec<String>,
) -> PerformanceMetric {
    let status = if value > budget.saturating_mul(2) {
        "fail"
    } else if value > budget {
        "warn"
    } else {
        "pass"
    };
    let summary = match status {
        "pass" => format!("{value} within budget {budget}"),
        "warn" => format!("{value} exceeds review budget {budget}"),
        _ => format!("{value} exceeds hard budget {}", budget.saturating_mul(2)),
    };
    PerformanceMetric {
        id: id.into(),
        title: title.into(),
        value,
        budget,
        status: status.into(),
        summary,
        evidence,
    }
}

fn performance_finding(
    severity: &str,
    category: &str,
    message: &str,
    evidence: Vec<String>,
    command: Option<String>,
) -> PerformanceFinding {
    PerformanceFinding {
        severity: severity.into(),
        category: category.into(),
        message: message.into(),
        evidence,
        command,
    }
}

fn performance_score(metrics: &[PerformanceMetric], findings: &[PerformanceFinding]) -> u8 {
    if metrics.is_empty() {
        return 0;
    }
    let total = metrics
        .iter()
        .map(|metric| match metric.status.as_str() {
            "pass" => 100u32,
            "warn" => 70,
            "fail" => 0,
            _ => 50,
        })
        .sum::<u32>();
    let base = (total / metrics.len() as u32) as u8;
    let penalty = findings
        .iter()
        .map(|finding| match finding.severity.as_str() {
            "blocker" => 20u8,
            "warning" => 6,
            _ => 0,
        })
        .sum::<u8>();
    base.saturating_sub(penalty)
}

#[derive(Default)]
struct AccessibilitySourceSignals {
    activated_handlers: usize,
    touch_handlers: usize,
    prompt_references: usize,
    mouse_only_handlers: usize,
    motion_patterns: usize,
    evidence: Vec<String>,
}

fn resolve_accessibility_paths(options: &AccessibilityOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot accessibility requires a run directory or --plan".into(),
        )),
    }
}

fn build_accessibility_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    accessibility_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<AccessibilityReport> {
    let mut background_by_path = BTreeMap::new();
    for operation in &plan.operations {
        let Some(path) = impact_operation_path(operation).or_else(|| operation.path.clone()) else {
            continue;
        };
        if let Some(color) = operation
            .properties
            .get("BackgroundColor3")
            .and_then(color3_components)
        {
            background_by_path.insert(path, color);
        }
    }

    let mut surfaces = Vec::new();
    let mut findings = Vec::new();
    for operation in &plan.operations {
        let class_name = operation.class_name.as_deref().unwrap_or_default();
        if !accessibility_is_ui_surface(class_name) {
            continue;
        }
        let path = impact_operation_path(operation)
            .or_else(|| operation.path.clone())
            .unwrap_or_else(|| operation.id.clone());
        let role = accessibility_role_for_class(class_name).to_string();
        let text = ux_surface_text(operation);
        let text_scaled = operation
            .properties
            .get("TextScaled")
            .and_then(Value::as_bool)
            .unwrap_or(false);
        let text_size = operation.properties.get("TextSize").and_then(Value::as_u64);
        let min_touch_px = operation
            .properties
            .get("Size")
            .and_then(udim2_min_touch_px);
        let text_color = operation
            .properties
            .get("TextColor3")
            .and_then(color3_components);
        let background_color = operation
            .properties
            .get("BackgroundColor3")
            .and_then(color3_components)
            .or_else(|| nearest_background_color(&path, &background_by_path));
        let contrast_ratio = text_color
            .zip(background_color)
            .map(|(text, background)| round_contrast(color_contrast_ratio(text, background)));
        let mut warnings = Vec::new();
        if accessibility_is_text_surface(class_name)
            && !text_scaled
            && text_size.map_or(true, |size| size < 18)
        {
            warnings.push("text is not scaled and has no large TextSize evidence".into());
        }
        if accessibility_is_interactive_surface(class_name)
            && class_name != "ProximityPrompt"
            && min_touch_px.map_or(true, |px| px < 44)
        {
            warnings.push("interactive target may be smaller than 44px".into());
        }
        if let Some(ratio) = contrast_ratio {
            if ratio < 4.5 {
                warnings.push(format!("contrast ratio {ratio:.2} is below 4.5"));
            }
        } else if accessibility_is_text_surface(class_name) {
            warnings.push("contrast could not be computed from plan colors".into());
        }
        surfaces.push(AccessibilitySurface {
            path,
            class_name: class_name.into(),
            role,
            text,
            text_scaled,
            text_size,
            min_touch_px,
            contrast_ratio,
            warnings,
        });
    }
    surfaces.sort_by(|left, right| left.path.cmp(&right.path));

    let signals = collect_accessibility_source_signals(run_dir, plan, &mut findings);
    let ui_surface_count = surfaces.len();
    let text_surface_count = surfaces
        .iter()
        .filter(|surface| accessibility_is_text_surface(&surface.class_name))
        .count();
    let interactive_control_count = surfaces
        .iter()
        .filter(|surface| accessibility_is_interactive_surface(&surface.class_name))
        .count();
    let scalable_text_count = surfaces
        .iter()
        .filter(|surface| {
            accessibility_is_text_surface(&surface.class_name)
                && (surface.text_scaled || surface.text_size.is_some_and(|size| size >= 18))
        })
        .count();
    let touch_target_count = surfaces
        .iter()
        .filter(|surface| {
            accessibility_is_interactive_surface(&surface.class_name)
                && (surface.class_name == "ProximityPrompt"
                    || surface.min_touch_px.is_some_and(|px| px >= 44))
        })
        .count();
    let contrast_pair_count = surfaces
        .iter()
        .filter(|surface| surface.contrast_ratio.is_some())
        .count();

    let text_warnings = surfaces
        .iter()
        .filter(|surface| {
            accessibility_is_text_surface(&surface.class_name)
                && surface
                    .warnings
                    .iter()
                    .any(|warning| warning.contains("text is not scaled"))
        })
        .map(|surface| surface.path.clone())
        .collect::<Vec<_>>();
    if !text_warnings.is_empty() {
        findings.push(accessibility_finding(
            "warning",
            "text-scaling",
            "Some text surfaces lack scalable or large text evidence.",
            text_warnings,
            None,
        ));
    }
    let touch_warnings = surfaces
        .iter()
        .filter(|surface| {
            accessibility_is_interactive_surface(&surface.class_name)
                && surface
                    .warnings
                    .iter()
                    .any(|warning| warning.contains("44px"))
        })
        .map(|surface| surface.path.clone())
        .collect::<Vec<_>>();
    if !touch_warnings.is_empty() {
        findings.push(accessibility_finding(
            "warning",
            "touch-target-size",
            "Some interactive controls may be too small for touch input.",
            touch_warnings,
            None,
        ));
    }
    let contrast_warnings = surfaces
        .iter()
        .filter(|surface| {
            surface
                .warnings
                .iter()
                .any(|warning| warning.contains("contrast"))
        })
        .map(|surface| surface.path.clone())
        .collect::<Vec<_>>();
    if !contrast_warnings.is_empty() {
        findings.push(accessibility_finding(
            "warning",
            "contrast",
            "Some text surfaces lack strong color contrast evidence.",
            contrast_warnings,
            None,
        ));
    }
    if signals.mouse_only_handlers > 0 {
        findings.push(accessibility_finding(
            "warning",
            "mouse-only-input",
            "Generated source references mouse-only handlers.",
            vec![format!("mouseOnlyHandlers={}", signals.mouse_only_handlers)],
            None,
        ));
    }
    if signals.motion_patterns > 0 {
        findings.push(accessibility_finding(
            "warning",
            "motion-review",
            "Generated source uses motion/camera/frame-step patterns that need live comfort review.",
            vec![format!("motionPatterns={}", signals.motion_patterns)],
            Some(format!(
                "rs autopilot playtest --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ));
    }

    let checks = vec![
        accessibility_check(
            "scalable-text",
            "Text is scalable",
            if text_surface_count == 0 {
                "warn"
            } else if scalable_text_count == text_surface_count {
                "pass"
            } else {
                "warn"
            },
            if text_surface_count == 0 {
                "No generated text surfaces were found.".into()
            } else {
                format!("{scalable_text_count}/{text_surface_count} text surface(s) scale or use large text")
            },
            surfaces
                .iter()
                .filter(|surface| accessibility_is_text_surface(&surface.class_name))
                .map(|surface| surface.path.clone())
                .collect(),
            None,
        ),
        accessibility_check(
            "touch-targets",
            "Interactive targets are touch sized",
            if interactive_control_count == 0 {
                "warn"
            } else if touch_target_count == interactive_control_count {
                "pass"
            } else {
                "warn"
            },
            if interactive_control_count == 0 {
                "No generated interactive controls were found.".into()
            } else {
                format!("{touch_target_count}/{interactive_control_count} interactive control(s) have touch-sized evidence")
            },
            surfaces
                .iter()
                .filter(|surface| accessibility_is_interactive_surface(&surface.class_name))
                .map(|surface| surface.path.clone())
                .collect(),
            None,
        ),
        accessibility_check(
            "contrast",
            "Text has readable contrast",
            if contrast_pair_count == 0 {
                "warn"
            } else if surfaces.iter().any(|surface| {
                accessibility_is_text_surface(&surface.class_name)
                    && surface.contrast_ratio.is_some_and(|ratio| ratio < 4.5)
            }) {
                "warn"
            } else {
                "pass"
            },
            if contrast_pair_count == 0 {
                "No text/background color pairs could be computed.".into()
            } else {
                format!("{contrast_pair_count} text/background contrast pair(s) computed")
            },
            surfaces
                .iter()
                .filter_map(|surface| {
                    surface
                        .contrast_ratio
                        .map(|ratio| format!("{}={ratio:.2}", surface.path))
                })
                .collect(),
            None,
        ),
        accessibility_check(
            "input-affordance",
            "Generated input paths are modality friendly",
            if signals.mouse_only_handlers > 0 {
                "warn"
            } else if interactive_control_count > 0
                || signals.activated_handlers > 0
                || signals.touch_handlers > 0
                || signals.prompt_references > 0
            {
                "pass"
            } else {
                "warn"
            },
            format!(
                "activated={}, touched={}, prompts={}, mouseOnly={}",
                signals.activated_handlers,
                signals.touch_handlers,
                signals.prompt_references,
                signals.mouse_only_handlers
            ),
            signals.evidence.clone(),
            None,
        ),
        accessibility_check(
            "motion-safety",
            "Motion-sensitive patterns are bounded",
            if signals.motion_patterns == 0 {
                "pass"
            } else {
                "warn"
            },
            if signals.motion_patterns == 0 {
                "No generated frame-step, camera, or TweenService patterns were found.".into()
            } else {
                format!(
                    "{} motion-sensitive source pattern(s) need live review",
                    signals.motion_patterns
                )
            },
            signals.evidence,
            None,
        ),
    ];

    findings.sort_by(|left, right| {
        left.severity
            .cmp(&right.severity)
            .then(left.category.cmp(&right.category))
    });
    findings.dedup_by(|left, right| {
        left.severity == right.severity
            && left.category == right.category
            && left.message == right.message
    });
    let mut blockers = findings
        .iter()
        .filter(|finding| finding.severity == "blocker")
        .map(|finding| finding.message.clone())
        .collect::<Vec<_>>();
    blockers.sort();
    blockers.dedup();
    let mut warnings = findings
        .iter()
        .filter(|finding| finding.severity == "warning")
        .map(|finding| finding.message.clone())
        .chain(
            checks
                .iter()
                .filter(|check| check.status == "warn")
                .map(|check| check.summary.clone()),
        )
        .collect::<Vec<_>>();
    warnings.sort();
    warnings.dedup();
    let score = accessibility_score(&checks, &findings);
    let status = if !blockers.is_empty() {
        "blocked"
    } else if !warnings.is_empty() {
        "needsAccessibilityReview"
    } else {
        "accessibilityReady"
    }
    .to_string();
    let mut next_actions = Vec::new();
    if status != "accessibilityReady" {
        next_actions.push(coach_action(
            1,
            "Review accessibility audit",
            Some(format!(
                "rs autopilot accessibility {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Accessibility warnings should be reviewed before claiming the generated UI is inclusive.",
            false,
            false,
        ));
    }
    next_actions.push(coach_action(
        2,
        "Review player UX",
        Some(format!(
            "rs autopilot ux {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Accessibility should agree with the player-facing affordance audit.",
        false,
        false,
    ));
    next_actions.push(coach_action(
        3,
        "Run live playtest checklist",
        Some(format!(
            "rs autopilot playtest --run-dir {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Static accessibility signals still need live device and Play Solo observation after approved apply.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);
    let agent_brief = format!(
        "Accessibility audit for '{}' is {} with score {}. It found {} UI surface(s), {} text surface(s), {} interactive control(s), {} scalable text surface(s), and {} touch-sized control(s).",
        plan.request.prompt,
        status,
        score,
        ui_surface_count,
        text_surface_count,
        interactive_control_count,
        scalable_text_count,
        touch_target_count
    );

    Ok(AccessibilityReport {
        schema_version: "rs.autopilot.accessibility.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        accessibility_path: accessibility_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        score,
        ui_surface_count,
        text_surface_count,
        interactive_control_count,
        scalable_text_count,
        touch_target_count,
        contrast_pair_count,
        checks,
        surfaces,
        findings,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn collect_accessibility_source_signals(
    run_dir: &Path,
    plan: &AutopilotPlan,
    findings: &mut Vec<AccessibilityFinding>,
) -> AccessibilitySourceSignals {
    let mut signals = AccessibilitySourceSignals::default();
    for source_path in generated_files_for_plan(plan) {
        let source = match safe_join(run_dir, &source_path) {
            Ok(path) => match std::fs::read_to_string(path) {
                Ok(source) => source,
                Err(_) => {
                    findings.push(accessibility_finding(
                        "warning",
                        "missing-source",
                        "Generated source could not be read for accessibility input analysis.",
                        vec![source_path.clone()],
                        Some(format!(
                            "rs autopilot refresh {} --format json",
                            command_arg(run_dir.to_string_lossy().as_ref())
                        )),
                    ));
                    continue;
                }
            },
            Err(err) => {
                findings.push(accessibility_finding(
                    "blocker",
                    "unsafe-source-path",
                    "Generated source path could not be inspected safely.",
                    vec![format!("{source_path}: {err}")],
                    None,
                ));
                continue;
            }
        };
        for (line_number, line) in source.lines().enumerate() {
            let lower = line.to_ascii_lowercase();
            if lower.contains(".activated:connect") {
                signals.activated_handlers += 1;
                signals
                    .evidence
                    .push(format!("{source_path}:{} Activated", line_number + 1));
            }
            if lower.contains(".touched:connect") {
                signals.touch_handlers += 1;
                signals
                    .evidence
                    .push(format!("{source_path}:{} Touched", line_number + 1));
            }
            if lower.contains("proximityprompt") || lower.contains("actiontext") {
                signals.prompt_references += 1;
            }
            if lower.contains("mousebutton1click") || lower.contains("mousebutton1down") {
                signals.mouse_only_handlers += 1;
                signals
                    .evidence
                    .push(format!("{source_path}:{} mouse-only", line_number + 1));
            }
            if lower.contains("tweenservice")
                || lower.contains("renderstepped")
                || lower.contains(".heartbeat")
                || lower.contains("currentcamera")
            {
                signals.motion_patterns += 1;
                signals
                    .evidence
                    .push(format!("{source_path}:{} motion", line_number + 1));
            }
        }
    }
    signals.evidence.sort();
    signals.evidence.dedup();
    signals
}

fn accessibility_is_ui_surface(class_name: &str) -> bool {
    matches!(
        class_name,
        "ScreenGui"
            | "Frame"
            | "TextLabel"
            | "TextButton"
            | "TextBox"
            | "ImageLabel"
            | "ImageButton"
            | "ProximityPrompt"
    )
}

fn accessibility_is_text_surface(class_name: &str) -> bool {
    matches!(
        class_name,
        "TextLabel" | "TextButton" | "TextBox" | "ProximityPrompt"
    )
}

fn accessibility_is_interactive_surface(class_name: &str) -> bool {
    matches!(
        class_name,
        "TextButton" | "ImageButton" | "TextBox" | "ProximityPrompt"
    )
}

fn accessibility_role_for_class(class_name: &str) -> &'static str {
    match class_name {
        "TextButton" | "ImageButton" => "control",
        "TextBox" => "input",
        "ProximityPrompt" => "worldPrompt",
        "TextLabel" | "ImageLabel" => "feedback",
        "Frame" => "container",
        "ScreenGui" => "screen",
        _ => "surface",
    }
}

fn color3_components(value: &Value) -> Option<(f64, f64, f64)> {
    let items = value.as_array()?;
    if items.first()?.as_str()? != "Color3" || items.len() < 4 {
        return None;
    }
    Some((
        items.get(1)?.as_f64()?,
        items.get(2)?.as_f64()?,
        items.get(3)?.as_f64()?,
    ))
}

fn udim2_min_touch_px(value: &Value) -> Option<i64> {
    let items = value.as_array()?;
    if items.first()?.as_str()? != "UDim2" || items.len() < 5 {
        return None;
    }
    let candidates = [items.get(2)?.as_i64()?, items.get(4)?.as_i64()?]
        .into_iter()
        .filter(|value| *value > 0)
        .collect::<Vec<_>>();
    candidates.into_iter().min()
}

fn nearest_background_color(
    path: &str,
    colors: &BTreeMap<String, (f64, f64, f64)>,
) -> Option<(f64, f64, f64)> {
    let mut current = Some(path);
    while let Some(candidate) = current {
        if let Some(color) = colors.get(candidate) {
            return Some(*color);
        }
        current = candidate.rsplit_once('.').map(|(parent, _)| parent);
    }
    None
}

fn color_contrast_ratio(foreground: (f64, f64, f64), background: (f64, f64, f64)) -> f64 {
    let fg = relative_luminance(foreground);
    let bg = relative_luminance(background);
    let (light, dark) = if fg >= bg { (fg, bg) } else { (bg, fg) };
    (light + 0.05) / (dark + 0.05)
}

fn relative_luminance((r, g, b): (f64, f64, f64)) -> f64 {
    fn channel(value: f64) -> f64 {
        if value <= 0.03928 {
            value / 12.92
        } else {
            ((value + 0.055) / 1.055).powf(2.4)
        }
    }
    0.2126 * channel(r) + 0.7152 * channel(g) + 0.0722 * channel(b)
}

fn round_contrast(value: f64) -> f64 {
    (value * 100.0).round() / 100.0
}

fn accessibility_check(
    id: &str,
    title: &str,
    status: &str,
    summary: String,
    evidence: Vec<String>,
    command: Option<String>,
) -> AccessibilityCheck {
    AccessibilityCheck {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        summary,
        evidence,
        command,
    }
}

fn accessibility_finding(
    severity: &str,
    category: &str,
    message: &str,
    evidence: Vec<String>,
    command: Option<String>,
) -> AccessibilityFinding {
    AccessibilityFinding {
        severity: severity.into(),
        category: category.into(),
        message: message.into(),
        evidence,
        command,
    }
}

fn accessibility_score(checks: &[AccessibilityCheck], findings: &[AccessibilityFinding]) -> u8 {
    if checks.is_empty() {
        return 0;
    }
    let total = checks
        .iter()
        .map(|check| match check.status.as_str() {
            "pass" => 100u32,
            "warn" => 70,
            "fail" => 0,
            _ => 50,
        })
        .sum::<u32>();
    let base = (total / checks.len() as u32) as u8;
    let penalty = findings
        .iter()
        .map(|finding| match finding.severity.as_str() {
            "blocker" => 20u8,
            "warning" => 4,
            _ => 0,
        })
        .sum::<u8>();
    base.saturating_sub(penalty)
}

fn resolve_policy_paths(options: &PolicyOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot policy requires a run directory or --plan".into(),
        )),
    }
}

fn build_policy_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    policy_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<PolicyReport> {
    let mut signals = Vec::new();
    let mut findings = Vec::new();
    collect_policy_plan_signals(plan, &mut signals);
    for source_path in generated_files_for_plan(plan) {
        match safe_join(run_dir, &source_path) {
            Ok(path) => match std::fs::read_to_string(path) {
                Ok(source) => collect_policy_source_signals(&source_path, &source, &mut signals),
                Err(_) => findings.push(policy_finding(
                    "warning",
                    "missing-source",
                    "Generated source could not be read for policy analysis.",
                    vec![source_path.clone()],
                    Some(format!(
                        "rs autopilot refresh {} --format json",
                        command_arg(run_dir.to_string_lossy().as_ref())
                    )),
                )),
            },
            Err(err) => findings.push(policy_finding(
                "blocker",
                "unsafe-source-path",
                "Generated source path could not be inspected safely.",
                vec![format!("{source_path}: {err}")],
                None,
            )),
        }
    }
    signals.sort_by(|left, right| {
        left.category
            .cmp(&right.category)
            .then(left.source_path.cmp(&right.source_path))
            .then(left.studio_path.cmp(&right.studio_path))
            .then(left.summary.cmp(&right.summary))
    });
    signals.dedup_by(|left, right| {
        left.category == right.category
            && left.source_path == right.source_path
            && left.studio_path == right.studio_path
            && left.summary == right.summary
    });
    for (index, signal) in signals.iter_mut().enumerate() {
        signal.id = format!("policy-{:03}", index + 1);
    }

    let off_platform = policy_signals_for(&signals, "off-platform-link");
    if !off_platform.is_empty() {
        findings.push(policy_finding(
            "blocker",
            "off-platform-link",
            "Generated content appears to reference off-platform links or social destinations.",
            off_platform,
            None,
        ));
    }
    let privacy = policy_signals_for(&signals, "personal-data-request");
    if !privacy.is_empty() {
        findings.push(policy_finding(
            "blocker",
            "personal-data-request",
            "Generated content appears to request personal information.",
            privacy,
            None,
        ));
    }
    for (category, message) in [
        (
            "purchase",
            "Generated content touches purchases or entitlements and needs creator policy review.",
        ),
        (
            "persistence",
            "Generated content touches persistence and needs data policy review.",
        ),
        (
            "teleport",
            "Generated content touches teleports and needs destination review.",
        ),
        (
            "external-http",
            "Generated content touches external HTTP and needs security and policy review.",
        ),
        (
            "chat-user-content",
            "Generated content touches chat or user content and needs moderation review.",
        ),
        (
            "randomized-reward",
            "Generated content appears to combine random rewards with economy or purchase language.",
        ),
    ] {
        let evidence = policy_signals_for(&signals, category);
        if !evidence.is_empty() {
            findings.push(policy_finding("warning", category, message, evidence, None));
        }
    }
    findings.sort_by(|left, right| {
        left.severity
            .cmp(&right.severity)
            .then(left.category.cmp(&right.category))
    });
    findings.dedup_by(|left, right| {
        left.severity == right.severity
            && left.category == right.category
            && left.message == right.message
    });

    let checks = build_policy_checks(&signals, run_dir);
    let mut blockers = findings
        .iter()
        .filter(|finding| finding.severity == "blocker")
        .map(|finding| finding.message.clone())
        .collect::<Vec<_>>();
    blockers.sort();
    blockers.dedup();
    let mut warnings = findings
        .iter()
        .filter(|finding| finding.severity == "warning")
        .map(|finding| finding.message.clone())
        .chain(
            checks
                .iter()
                .filter(|check| check.status == "warn")
                .map(|check| check.summary.clone()),
        )
        .collect::<Vec<_>>();
    warnings.sort();
    warnings.dedup();
    let status = if !blockers.is_empty() {
        "blocked"
    } else if !warnings.is_empty() {
        "needsPolicyReview"
    } else {
        "policyReady"
    }
    .to_string();
    let review_required_count = signals
        .iter()
        .filter(|signal| signal.severity != "info")
        .count();
    let mut next_actions = Vec::new();
    if status != "policyReady" {
        next_actions.push(coach_action(
            1,
            "Review policy signals",
            Some(format!(
                "rs autopilot policy {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Policy-sensitive surfaces should be reviewed before asking for live apply or user-facing claims.",
            false,
            false,
        ));
    }
    next_actions.push(coach_action(
        2,
        "Refresh source audit",
        Some(format!(
            "rs autopilot audit-sources {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Source audit should agree with policy-sensitive generated code findings.",
        false,
        false,
    ));
    next_actions.push(coach_action(
        3,
        "Refresh approval packet",
        Some(format!(
            "rs autopilot approval {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Creator approval should include policy-sensitive surfaces before live mutation.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);
    let agent_brief = format!(
        "Policy audit for '{}' is {} with {} signal(s), {} review-required signal(s), {} blocker(s), and {} warning(s).",
        plan.request.prompt,
        status,
        signals.len(),
        review_required_count,
        blockers.len(),
        warnings.len()
    );

    Ok(PolicyReport {
        schema_version: "rs.autopilot.policy.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        policy_path: policy_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        signal_count: signals.len(),
        review_required_count,
        checks,
        signals,
        findings,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn collect_policy_plan_signals(plan: &AutopilotPlan, signals: &mut Vec<PolicySignal>) {
    for operation in &plan.operations {
        let studio_path = impact_operation_path(operation).or_else(|| operation.path.clone());
        for (key, value) in &operation.properties {
            if let Some(text) = value.as_str() {
                policy_scan_text(
                    text,
                    "planProperty",
                    None,
                    studio_path.clone(),
                    Some(format!("{key}={text}")),
                    signals,
                );
            }
        }
        if let Some(path) = &studio_path {
            policy_scan_text(
                path,
                "planPath",
                None,
                Some(path.clone()),
                Some(path.clone()),
                signals,
            );
        }
    }
}

fn collect_policy_source_signals(source_path: &str, source: &str, signals: &mut Vec<PolicySignal>) {
    for (line_number, line) in source.lines().enumerate() {
        let evidence = format!("{source_path}:{}: {}", line_number + 1, line.trim());
        policy_scan_text(
            line,
            "generatedSource",
            Some(format!("{}:{}", source_path, line_number + 1)),
            None,
            Some(evidence),
            signals,
        );
    }
}

fn policy_scan_text(
    text: &str,
    source: &str,
    source_path: Option<String>,
    studio_path: Option<String>,
    evidence: Option<String>,
    signals: &mut Vec<PolicySignal>,
) {
    let lower = text.to_ascii_lowercase();
    let evidence = evidence.unwrap_or_else(|| text.trim().to_string());
    let mut push = |category: &str, severity: &str, summary: &str| {
        signals.push(PolicySignal {
            id: String::new(),
            category: category.into(),
            severity: severity.into(),
            source: source.into(),
            source_path: source_path.clone(),
            studio_path: studio_path.clone(),
            summary: summary.into(),
            evidence: vec![evidence.clone()],
        });
    };
    if [
        "discord.gg",
        "discord.com",
        "youtube.com",
        "youtu.be",
        "tiktok.com",
        "twitter.com",
        "x.com/",
        "http://",
        "https://",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
    {
        push(
            "off-platform-link",
            "blocker",
            "off-platform link or URL reference",
        );
    }
    if [
        "email",
        "password",
        "phone number",
        "birthdate",
        "birthday",
        "real name",
        "address",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
    {
        push(
            "personal-data-request",
            "blocker",
            "personal data request language",
        );
    }
    if [
        "marketplaceservice",
        "promptproductpurchase",
        "promptgamepasspurchase",
        "processreceipt",
        "userownsgamepassasync",
        "developerproduct",
        "gamepass",
        "robux",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
    {
        push("purchase", "warning", "purchase or entitlement surface");
    }
    if [
        "datastoreservice",
        "getdatastore",
        "setasync",
        "updateasync",
        "getasync",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
    {
        push("persistence", "warning", "persistent player data surface");
    }
    if [
        "teleportservice",
        "teleportasync",
        "teleporttoplaceserver",
        "reserveserver",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
    {
        push("teleport", "warning", "teleport or destination surface");
    }
    if [
        "httpservice",
        "requestasync",
        "postasync",
        "jsondecode",
        "jsonencode",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
    {
        push(
            "external-http",
            "warning",
            "external HTTP or serialization surface",
        );
    }
    if [
        "textchatservice",
        "chatservice",
        "filterstringasync",
        "broadcastmessage",
        "player.chatted",
        "displayname",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
    {
        push(
            "chat-user-content",
            "warning",
            "chat or user content surface",
        );
    }
    if (lower.contains("math.random") || lower.contains("random.new"))
        && [
            "reward", "loot", "crate", "spin", "purchase", "robux", "gamepass",
        ]
        .iter()
        .any(|needle| lower.contains(needle))
    {
        push(
            "randomized-reward",
            "warning",
            "randomized reward or chance surface",
        );
    }
}

fn build_policy_checks(signals: &[PolicySignal], run_dir: &Path) -> Vec<PolicyCheck> {
    vec![
        policy_check_for_categories(
            "off-platform-links",
            "No off-platform links",
            signals,
            &["off-platform-link"],
            Some("blocker"),
            "No generated off-platform link signals were found.",
            Some(format!(
                "rs autopilot policy {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
        policy_check_for_categories(
            "personal-data",
            "No personal data requests",
            signals,
            &["personal-data-request"],
            Some("blocker"),
            "No generated personal data request signals were found.",
            Some(format!(
                "rs autopilot privacy {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        ),
        policy_check_for_categories(
            "monetization",
            "Purchases and random rewards are reviewable",
            signals,
            &["purchase", "randomized-reward"],
            None,
            "No generated purchase or randomized reward signals were found.",
            None,
        ),
        policy_check_for_categories(
            "data-and-networking",
            "Data, teleport, and network surfaces are reviewable",
            signals,
            &["persistence", "teleport", "external-http"],
            None,
            "No generated persistence, teleport, or external HTTP signals were found.",
            None,
        ),
        policy_check_for_categories(
            "chat-user-content",
            "Chat and user content are reviewable",
            signals,
            &["chat-user-content"],
            None,
            "No generated chat or user-content signals were found.",
            None,
        ),
    ]
}

fn policy_check_for_categories(
    id: &str,
    title: &str,
    signals: &[PolicySignal],
    categories: &[&str],
    fail_severity: Option<&str>,
    pass_summary: &str,
    command: Option<String>,
) -> PolicyCheck {
    let matched = signals
        .iter()
        .filter(|signal| categories.contains(&signal.category.as_str()))
        .collect::<Vec<_>>();
    let status = if matched
        .iter()
        .any(|signal| fail_severity.is_some_and(|severity| signal.severity == severity))
    {
        "fail"
    } else if matched.is_empty() {
        "pass"
    } else {
        "warn"
    };
    let summary = if matched.is_empty() {
        pass_summary.into()
    } else {
        format!("{} policy-sensitive signal(s) found", matched.len())
    };
    PolicyCheck {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        summary,
        evidence: matched
            .iter()
            .flat_map(|signal| signal.evidence.clone())
            .take(12)
            .collect(),
        command,
    }
}

fn policy_signals_for(signals: &[PolicySignal], category: &str) -> Vec<String> {
    signals
        .iter()
        .filter(|signal| signal.category == category)
        .flat_map(|signal| signal.evidence.clone())
        .take(12)
        .collect()
}

fn policy_finding(
    severity: &str,
    category: &str,
    message: &str,
    evidence: Vec<String>,
    command: Option<String>,
) -> PolicyFinding {
    PolicyFinding {
        severity: severity.into(),
        category: category.into(),
        message: message.into(),
        evidence,
        command,
    }
}

fn resolve_style_guide_paths(options: &StyleGuideOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot style-guide requires a run directory or --plan".into(),
        )),
    }
}

fn build_style_guide_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    style_guide_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<StyleGuideReport> {
    let recipes = recipes_for_run(run_dir, plan).unwrap_or_default();
    let theme = infer_style_theme(&plan.request.prompt, &recipes);
    let genre = infer_style_genre(&plan.request.prompt, &recipes);
    let tone = infer_style_tone(&plan.request.prompt, &recipes);
    let palette = style_palette_for_theme(&theme);
    let visual_rules = style_visual_rules(&theme, &genre);
    let ui_rules = style_ui_rules(&theme);
    let copy_rules = style_copy_rules(&tone);
    let audio_rules = style_audio_rules(&theme, &genre);
    let asset_prompts = style_asset_prompts(&theme, &genre, &tone, plan);
    let mut warnings = Vec::new();
    if recipes.is_empty() {
        warnings.push(
            "no recipe evidence was found; style guide is inferred from prompt and plan text"
                .into(),
        );
    }
    if plan.request.prompt.trim().len() < 8 {
        warnings.push("creator prompt is short; style guide may need manual direction".into());
    }
    warnings.sort();
    warnings.dedup();
    let blockers = Vec::new();
    let status = "styleGuideReady".to_string();
    let mut next_actions = vec![
        coach_action(
            1,
            "Review style guide",
            Some(format!(
                "rs autopilot style-guide {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Use the style guide as the stable creative contract before generating assets or copy.",
            false,
            false,
        ),
        coach_action(
            2,
            "Generate asset brief from style",
            Some(format!(
                "rs autopilot asset-brief {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Asset requests should follow the palette, shape language, and tone defined here.",
            false,
            false,
        ),
        coach_action(
            9,
            "Refresh offline packet",
            Some(format!(
                "rs autopilot refresh {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Refresh derived artifacts after style, copy, or asset direction changes.",
            false,
            false,
        ),
    ];
    dedup_next_actions(&mut next_actions);
    let agent_brief = format!(
        "Style guide for '{}' is {}. Theme '{}', genre '{}', tone '{}', {} palette color(s), {} visual rule(s), and {} asset prompt(s) should guide future UI, asset, audio, VFX, and thumbnail work.",
        plan.request.prompt,
        status,
        theme,
        genre,
        tone,
        palette.len(),
        visual_rules.len(),
        asset_prompts.len()
    );

    Ok(StyleGuideReport {
        schema_version: "rs.autopilot.style-guide.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        style_guide_path: style_guide_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        theme,
        genre,
        tone,
        palette,
        visual_rules,
        ui_rules,
        copy_rules,
        audio_rules,
        asset_prompts,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn infer_style_theme(prompt: &str, recipes: &[String]) -> String {
    let lower = prompt.to_ascii_lowercase();
    if lower.contains("candy") || lower.contains("sweet") || lower.contains("dessert") {
        "Candy Arcade".into()
    } else if lower.contains("space") || lower.contains("sci-fi") || lower.contains("laser") {
        "Neon Space".into()
    } else if lower.contains("obby") || recipes.iter().any(|recipe| recipe == "obbyCheckpoint") {
        "Bright Obby".into()
    } else if lower.contains("enemy")
        || lower.contains("battle")
        || recipes.iter().any(|recipe| recipe == "enemyEncounter")
    {
        "Training Arena".into()
    } else if lower.contains("quest")
        || lower.contains("adventure")
        || recipes.iter().any(|recipe| recipe == "questSystem")
    {
        "Adventure Hub".into()
    } else if lower.contains("tycoon") || recipes.iter().any(|recipe| recipe == "tycoonCore") {
        "Friendly Tycoon".into()
    } else {
        "Clean Roblox Prototype".into()
    }
}

fn infer_style_genre(prompt: &str, recipes: &[String]) -> String {
    let lower = prompt.to_ascii_lowercase();
    if lower.contains("tycoon") || recipes.iter().any(|recipe| recipe == "tycoonCore") {
        "tycoon"
    } else if lower.contains("obby") || recipes.iter().any(|recipe| recipe == "obbyCheckpoint") {
        "obby"
    } else if recipes.iter().any(|recipe| recipe == "enemyEncounter") {
        "combat-training"
    } else if recipes.iter().any(|recipe| recipe == "questSystem") {
        "quest-adventure"
    } else {
        "starter-game"
    }
    .into()
}

fn infer_style_tone(prompt: &str, recipes: &[String]) -> String {
    let lower = prompt.to_ascii_lowercase();
    if lower.contains("scary") || lower.contains("horror") {
        "tense but still readable for Roblox players"
    } else if lower.contains("candy") || lower.contains("cute") || lower.contains("pet") {
        "playful, bright, and encouraging"
    } else if recipes.iter().any(|recipe| recipe == "enemyEncounter") {
        "energetic, clear, and challenge-forward"
    } else {
        "friendly, direct, and action-oriented"
    }
    .into()
}

