fn build_social_proof_checks(
    run_dir: &Path,
    loops: &[SocialLoop],
    invite_moments: &[SocialInviteMoment],
) -> Vec<SocialProofCheck> {
    let mut checks = Vec::new();
    for item in loops {
        checks.push(social_proof_check(
            &format!("proof-{}", item.id),
            &format!("Proof: {}", item.title),
            "screenshot-or-note",
            &item.proof_requirement,
            &format!(
                "rs autopilot record-playtest {} --result passed --evidence \"{} social proof captured\" --scenario {}=passed",
                command_arg(run_dir.to_string_lossy().as_ref()),
                item.title,
                item.id
            ),
        ));
    }
    for item in invite_moments {
        checks.push(social_proof_check(
            &format!("copy-{}", item.id),
            &format!("Review Copy: {}", item.title),
            "manual-review",
            &format!(
                "Confirm optional social copy is clear and policy-safe: {}",
                item.suggested_copy
            ),
            &format!(
                "rs autopilot policy {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ));
    }
    checks.sort_by(|left, right| left.id.cmp(&right.id));
    checks.dedup_by(|left, right| left.id == right.id);
    checks
}

fn social_proof_check(
    id: &str,
    title: &str,
    capture_type: &str,
    expected: &str,
    suggested_command: &str,
) -> SocialProofCheck {
    SocialProofCheck {
        id: id.into(),
        title: title.into(),
        capture_type: capture_type.into(),
        expected: expected.into(),
        suggested_command: suggested_command.into(),
    }
}

fn build_social_policy_guardrails() -> Vec<String> {
    vec![
        "Do not auto-invite, spam chat, or pressure players to bring friends for core progress."
            .into(),
        "Do not use off-platform links, off-platform contact prompts, or personal data in social loops."
            .into(),
        "Keep every first-session objective and first reward playable solo unless the creator explicitly approves a co-op-only design."
            .into(),
        "Do not claim viral growth, friend invites, group membership, badges, or leaderboard behavior is live until implemented and proven in Studio."
            .into(),
        "Use optional, in-experience social copy that explains value without manipulating failure, scarcity, or purchase pressure."
            .into(),
    ]
}

fn resolve_liveops_paths(options: &LiveopsOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot liveops requires a run directory or --plan".into(),
        )),
    }
}

fn build_liveops_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    liveops_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<LiveopsReport> {
    let recipes = recipes_for_run(run_dir, plan).unwrap_or_default();
    let telemetry = read_json_if_exists(&run_dir.join("telemetry.json"))?;
    let social = read_json_if_exists(&run_dir.join("social.json"))?;
    let monetization = read_json_if_exists(&run_dir.join("monetization.json"))?;
    let showcase = read_json_if_exists(&run_dir.join("showcase.json"))?;
    let policy = read_json_if_exists(&run_dir.join("policy.json"))?;
    let asset_brief = read_json_if_exists(&run_dir.join("asset-brief.json"))?;

    let updates = build_liveops_updates(&recipes);
    let events = build_liveops_events(&recipes, social.is_some());
    let experiments =
        build_liveops_experiments(&recipes, telemetry.is_some(), monetization.is_some());
    let proof_gates = build_liveops_proof_gates(
        run_dir,
        telemetry.is_some(),
        social.is_some(),
        showcase.is_some(),
        policy.is_some(),
        asset_brief.is_some(),
    );
    let mut warnings = Vec::new();
    if telemetry.is_none() {
        warnings.push("telemetry.json is missing; liveops measurement gates are inferred.".into());
    }
    if social.is_none() {
        warnings.push(
            "social.json is missing; community hooks are inferred without the social contract."
                .into(),
        );
    }
    if monetization.is_none() {
        warnings.push(
            "monetization.json is missing; commerce-sensitive update boundaries are inferred."
                .into(),
        );
    }
    if showcase.is_none() {
        warnings.push("showcase.json is missing; update announcement shots are inferred.".into());
    }
    if policy.is_none() {
        warnings.push("policy.json is missing; live event safety review is inferred.".into());
    }
    if asset_brief.is_none() {
        warnings.push("asset-brief.json is missing; content drop asset needs are inferred.".into());
    }
    warnings.sort();
    warnings.dedup();

    let blockers = Vec::new();
    let status = if updates.is_empty() {
        "needsLiveopsReview"
    } else {
        "liveopsReady"
    }
    .to_string();
    let mut next_actions = vec![
        coach_action(
            1,
            "Review live operations plan",
            Some(format!(
                "rs autopilot liveops {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Use the liveops plan before planning updates, events, retention beats, or publish-facing claims.",
            false,
            false,
        ),
        coach_action(
            2,
            "Refresh evidence kit",
            Some(format!(
                "rs autopilot evidence {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Every update beat needs evidence before an AI claims it is live, tested, or ready to promote.",
            false,
            false,
        ),
        coach_action(
            3,
            "Check live mutation gate",
            Some(format!(
                "rs autopilot live-gate {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Liveops changes still require approval, readiness, rollback, and bundle verification before Studio mutation.",
            false,
            false,
        ),
        coach_action(
            9,
            "Refresh offline packet",
            Some(format!(
                "rs autopilot refresh {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Regenerate liveops guidance after recipe, telemetry, social, monetization, showcase, or asset changes.",
            false,
            false,
        ),
    ];
    dedup_next_actions(&mut next_actions);
    let operating_rules = build_liveops_operating_rules();
    let agent_brief = format!(
        "Liveops plan for '{}' is {} with {} update(s), {} event hook(s), and {} experiment(s). Treat it as an operations contract, not proof that updates, events, analytics, publishing, or monetization are live.",
        plan.request.prompt,
        status,
        updates.len(),
        events.len(),
        experiments.len()
    );
    Ok(LiveopsReport {
        schema_version: "rs.autopilot.liveops.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        liveops_path: liveops_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        update_count: updates.len(),
        event_count: events.len(),
        experiment_count: experiments.len(),
        proof_gate_count: proof_gates.len(),
        updates,
        events,
        experiments,
        proof_gates,
        operating_rules,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn build_liveops_updates(recipes: &[String]) -> Vec<LiveopsUpdate> {
    let mut updates = vec![liveops_update(
        "day-0-proof-lock",
        "Day 0 Proof Lock",
        "pre-launch",
        Vec::new(),
        "Freeze the reviewed bundle, source audit, certification, rollback, and first playtest proof before any publish or promotion claim.",
        vec!["bundle.json", "certification.json", "proof.json", "rollback.json"],
        "Treat every missing live artifact as a blocker for release claims.",
        "Bundle verification, approval, live readiness, apply result, rollback, and playtest evidence are all recorded.",
    )];
    if recipes.iter().any(|recipe| recipe == "tycoonCore") {
        updates.push(liveops_update(
            "week-1-tycoon-upgrade-drop",
            "Week 1 Tycoon Upgrade Drop",
            "weekly",
            vec!["tycoonCore"],
            "Give returning players one clearly previewed upgrade target after the first session loop is proven.",
            vec!["balance.json", "telemetry.json", "showcase.json", "asset-brief.json"],
            "Review economy pacing so the update does not erase existing progress or pressure purchases.",
            "Record upgrade purchase, reward feedback, and rollback-ready apply evidence before calling the drop live.",
        ));
    }
    if recipes.iter().any(|recipe| recipe == "obbyCheckpoint") {
        updates.push(liveops_update(
            "weekend-checkpoint-challenge",
            "Weekend Checkpoint Challenge",
            "event",
            vec!["obbyCheckpoint"],
            "Offer a short replayable checkpoint goal that players can understand in one screen.",
            vec![
                "world-blueprint.json",
                "onboarding.json",
                "social.json",
                "showcase.json",
            ],
            "Keep retries free and avoid exclusive rewards until policy and proof are reviewed.",
            "Capture checkpoint completion, retry flow, and optional social race evidence.",
        ));
    }
    if recipes.iter().any(|recipe| recipe == "collectibleCoin") {
        updates.push(liveops_update(
            "rotating-coin-route",
            "Rotating Coin Route",
            "weekly",
            vec!["collectibleCoin"],
            "Refresh a visible pickup route without changing the promised first reward.",
            vec!["world-blueprint.json", "balance.json", "telemetry.json"],
            "Verify respawn timing and currency totals before changing live reward values.",
            "Record pickup route, reward value, and no-regression proof for the original first-session path.",
        ));
    }
    if recipes
        .iter()
        .any(|recipe| recipe == "questSystem" || recipe == "npcInteraction")
    {
        updates.push(liveops_update(
            "npc-chapter-update",
            "NPC Chapter Update",
            "biweekly",
            vec!["questSystem", "npcInteraction"],
            "Add one readable objective beat that extends the existing guide or quest loop.",
            vec!["copy-deck.json", "policy.json", "playtest-plan.json"],
            "Review new dialogue for personal-data, off-platform, and misleading reward claims.",
            "Record NPC prompt, objective completion, reward feedback, and revised copy review.",
        ));
    }
    if recipes.iter().any(|recipe| recipe == "enemyEncounter") {
        updates.push(liveops_update(
            "encounter-balance-patch",
            "Encounter Balance Patch",
            "weekly",
            vec!["enemyEncounter"],
            "Tune one encounter variable after proof shows players can complete the baseline loop.",
            vec!["balance.json", "performance.json", "authority.json", "telemetry.json"],
            "Review server authority and performance before increasing enemy pressure.",
            "Record solo completion, reward feedback, and no exploit-sensitive client authority changes.",
        ));
    }
    if recipes.iter().any(|recipe| recipe == "starterShop") {
        updates.push(liveops_update(
            "shop-refresh-review",
            "Shop Refresh Review",
            "monthly",
            vec!["starterShop"],
            "Refresh visible shop presentation only after free progress and pricing boundaries are reviewed.",
            vec!["monetization.json", "policy.json", "copy-deck.json", "asset-brief.json"],
            "Do not add live commerce IDs or paid-only progress through liveops planning.",
            "Record free preview, reviewed copy, product ID configuration evidence, and receipt handling before any commerce claim.",
        ));
    }
    updates.sort_by(|left, right| left.id.cmp(&right.id));
    updates.dedup_by(|left, right| left.id == right.id);
    updates
}

