fn build_liveops_experiments(
    recipes: &[String],
    has_telemetry: bool,
    has_monetization: bool,
) -> Vec<LiveopsExperiment> {
    let mut experiments = vec![liveops_experiment(
        "first-session-copy",
        "First Session Copy Tune",
        "Clearer prompts should increase first-action completion without adding pressure.",
        "FirstActionCompleted or onboarding proof check completion.",
        "Do not change rewards, pricing, or required friends while copy is being tested.",
        "Stop if completion drops, confusion notes increase, or policy/copy review fails.",
    )];
    if has_telemetry
        || recipes
            .iter()
            .any(|recipe| recipe == "tycoonCore" || recipe == "collectibleCoin")
    {
        experiments.push(liveops_experiment(
            "reward-pacing",
            "Reward Pacing Tune",
            "A small pacing adjustment can improve return intent without breaking the economy.",
            "FirstRewardEarned, TycoonUpgradePurchased, or CollectiblePickedUp timing.",
            "Keep first reward free and do not reduce already-promised progression.",
            "Stop if first-session completion, balance status, or player-readable proof regresses.",
        ));
    }
    if recipes.iter().any(|recipe| recipe == "obbyCheckpoint") {
        experiments.push(liveops_experiment(
            "checkpoint-friction",
            "Checkpoint Friction Tune",
            "A shorter retry loop should improve challenge completion without making the obby trivial.",
            "CheckpointReached and retry count.",
            "Do not punish failure or hide the free retry path.",
            "Stop if frustration notes, accessibility warnings, or completion failures increase.",
        ));
    }
    if has_monetization || recipes.iter().any(|recipe| recipe == "starterShop") {
        experiments.push(liveops_experiment(
            "shop-surface-copy",
            "Shop Surface Copy Review",
            "Better preview copy should improve understanding before any purchase consideration.",
            "ShopOpened, itemPreviewed, and free item interaction.",
            "No live product IDs, randomized paid rewards, pressure copy, or tutorial paywalls.",
            "Stop unless monetization, policy, and playtest proof all remain clean.",
        ));
    }
    experiments.sort_by(|left, right| left.id.cmp(&right.id));
    experiments.dedup_by(|left, right| left.id == right.id);
    experiments
}

fn liveops_experiment(
    id: &str,
    title: &str,
    hypothesis: &str,
    signal: &str,
    guardrail: &str,
    stop_condition: &str,
) -> LiveopsExperiment {
    LiveopsExperiment {
        id: id.into(),
        title: title.into(),
        hypothesis: hypothesis.into(),
        signal: signal.into(),
        guardrail: guardrail.into(),
        stop_condition: stop_condition.into(),
    }
}

fn build_liveops_proof_gates(
    run_dir: &Path,
    has_telemetry: bool,
    has_social: bool,
    has_showcase: bool,
    has_policy: bool,
    has_asset_brief: bool,
) -> Vec<LiveopsProofGate> {
    let evidence_path = run_dir.join("evidence-kit.json");
    let approval_path = run_dir.join("approval.json");
    let rollback_path = run_dir.join("rollback.json");
    let bundle_path = run_dir.join("bundle.json");
    let mut gates = vec![
        liveops_proof_gate(
            "bundle-current",
            "Bundle Current",
            vec![bundle_path.to_string_lossy().to_string()],
            if bundle_path.exists() {
                Vec::new()
            } else {
                vec!["bundle.json".into()]
            },
            format!(
                "rs autopilot verify-bundle --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ),
        liveops_proof_gate(
            "telemetry-defined",
            "Telemetry Defined",
            vec![run_dir.join("telemetry.json").to_string_lossy().to_string()],
            if has_telemetry {
                Vec::new()
            } else {
                vec!["telemetry.json".into()]
            },
            format!(
                "rs autopilot telemetry {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ),
        liveops_proof_gate(
            "policy-reviewed",
            "Policy Reviewed",
            vec![run_dir.join("policy.json").to_string_lossy().to_string()],
            if has_policy {
                Vec::new()
            } else {
                vec!["policy.json".into()]
            },
            format!(
                "rs autopilot policy {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ),
        liveops_proof_gate(
            "evidence-kit-ready",
            "Evidence Kit Ready",
            vec![evidence_path.to_string_lossy().to_string()],
            if evidence_path.exists() {
                Vec::new()
            } else {
                vec!["evidence-kit.json".into()]
            },
            format!(
                "rs autopilot evidence {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ),
        liveops_proof_gate(
            "approval-ready",
            "Approval Ready",
            vec![approval_path.to_string_lossy().to_string()],
            if approval_path.exists() {
                Vec::new()
            } else {
                vec!["approval.json".into()]
            },
            format!(
                "rs autopilot approval {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ),
        liveops_proof_gate(
            "rollback-ready",
            "Rollback Ready",
            vec![rollback_path.to_string_lossy().to_string()],
            if rollback_path.exists() {
                Vec::new()
            } else {
                vec!["rollback.json".into()]
            },
            format!(
                "rs autopilot rollback {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ),
    ];
    if has_social {
        gates.push(liveops_proof_gate(
            "social-safe",
            "Social Safe",
            vec![run_dir.join("social.json").to_string_lossy().to_string()],
            Vec::new(),
            format!(
                "rs autopilot social {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ));
    }
    if has_showcase {
        gates.push(liveops_proof_gate(
            "showcase-ready",
            "Showcase Ready",
            vec![run_dir.join("showcase.json").to_string_lossy().to_string()],
            Vec::new(),
            format!(
                "rs autopilot showcase {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ));
    }
    if has_asset_brief {
        gates.push(liveops_proof_gate(
            "asset-brief-ready",
            "Asset Brief Ready",
            vec![run_dir
                .join("asset-brief.json")
                .to_string_lossy()
                .to_string()],
            Vec::new(),
            format!(
                "rs autopilot asset-brief {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ));
    }
    gates.sort_by(|left, right| left.id.cmp(&right.id));
    gates
}

fn liveops_proof_gate(
    id: &str,
    title: &str,
    evidence: Vec<String>,
    missing: Vec<String>,
    suggested_command: String,
) -> LiveopsProofGate {
    LiveopsProofGate {
        id: id.into(),
        title: title.into(),
        status: if missing.is_empty() { "pass" } else { "warn" }.into(),
        evidence,
        missing,
        suggested_command,
    }
}

fn build_liveops_operating_rules() -> Vec<String> {
    vec![
        "Do not claim an update, event, badge, leaderboard, shop refresh, or content drop is live until Studio apply, rollback, bundle verification, and playtest proof exist.".into(),
        "Do not use scarcity, failure, friend pressure, or paid-only progress as liveops retention tactics.".into(),
        "Keep the first-session promise stable; live updates must not remove the proven solo path, first reward, or rollback option.".into(),
        "Treat every event reward, economy change, social prompt, and commerce surface as policy-review-required before promotion.".into(),
        "Refresh telemetry, proof, acceptance, privacy, and closeout artifacts after every liveops patch before summarizing results to the creator.".into(),
    ]
}

fn resolve_persistence_paths(options: &PersistenceOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot persistence requires a run directory or --plan".into(),
        )),
    }
}

fn build_persistence_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    persistence_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<PersistenceReport> {
    let recipes = recipes_for_run(run_dir, plan).unwrap_or_default();
    let telemetry = read_json_if_exists(&run_dir.join("telemetry.json"))?;
    let policy = read_json_if_exists(&run_dir.join("policy.json"))?;
    let authority = read_json_if_exists(&run_dir.join("authority.json"))?;
    let balance = read_json_if_exists(&run_dir.join("balance.json"))?;
    let live_apply = read_json_if_exists(&run_dir.join("apply.json"))?;
    let datastore_source = plan_uses_datastore(run_dir, plan);
    let data_models = build_persistence_data_models(&recipes, datastore_source);
    let data_flows = build_persistence_data_flows(&recipes, datastore_source);
    let migrations = build_persistence_migrations(&recipes);
    let proof_checks = build_persistence_proof_checks(
        run_dir,
        telemetry.is_some(),
        policy.is_some(),
        authority.is_some(),
        balance.is_some(),
        live_apply.is_some(),
        datastore_source,
    );
    let mut warnings = Vec::new();
    if !datastore_source && !recipes.iter().any(|recipe| recipe == "saveDataScaffold") {
        warnings.push("No saveDataScaffold recipe or DataStore source was found; persistence remains a design contract until implemented.".into());
    }
    if telemetry.is_none() {
        warnings.push("telemetry.json is missing; save/load measurement is inferred.".into());
    }
    if policy.is_none() {
        warnings.push("policy.json is missing; data safety review is inferred.".into());
    }
    if authority.is_none() {
        warnings.push(
            "authority.json is missing; server-authoritative save review is inferred.".into(),
        );
    }
    if balance.is_none() {
        warnings.push("balance.json is missing; persisted economy fields are inferred.".into());
    }
    warnings.sort();
    warnings.dedup();
    let blockers = Vec::new();
    let status = if data_models.is_empty() {
        "needsPersistenceReview"
    } else if datastore_source {
        "persistenceReady"
    } else {
        "persistencePlanned"
    }
    .to_string();
    let mut next_actions = vec![
        coach_action(
            1,
            "Review persistence contract",
            Some(format!(
                "rs autopilot persistence {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Use the persistence contract before claiming save data, player progress, entitlements, or migrations are implemented.",
            false,
            false,
        ),
        coach_action(
            2,
            "Refresh source audit",
            Some(format!(
                "rs autopilot audit-sources {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Generated DataStore code needs the same safety scan as all other generated Luau.",
            false,
            false,
        ),
        coach_action(
            3,
            "Refresh live proof kit",
            Some(format!(
                "rs autopilot evidence {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Save/load claims need Play Solo or live Studio evidence, not just a schema contract.",
            false,
            false,
        ),
        coach_action(
            9,
            "Refresh offline packet",
            Some(format!(
                "rs autopilot refresh {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Regenerate persistence guidance after changing recipes, generated scripts, economy, policy, authority, or telemetry.",
            false,
            false,
        ),
    ];
    dedup_next_actions(&mut next_actions);
    let safety_guardrails = build_persistence_guardrails();
    let agent_brief = format!(
        "Persistence plan for '{}' is {} with {} data model(s), {} flow(s), and {} proof check(s). Do not claim player data is saved until implementation, API-services readiness, live apply, reload proof, and rollback evidence exist.",
        plan.request.prompt,
        status,
        data_models.len(),
        data_flows.len(),
        proof_checks.len()
    );
    Ok(PersistenceReport {
        schema_version: "rs.autopilot.persistence.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        persistence_path: persistence_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        data_model_count: data_models.len(),
        data_flow_count: data_flows.len(),
        migration_count: migrations.len(),
        proof_check_count: proof_checks.len(),
        data_models,
        data_flows,
        migrations,
        proof_checks,
        safety_guardrails,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn plan_uses_datastore(run_dir: &Path, plan: &AutopilotPlan) -> bool {
    if recipes_for_run(run_dir, plan)
        .unwrap_or_default()
        .iter()
        .any(|recipe| recipe == "saveDataScaffold")
    {
        return true;
    }
    generated_files_for_plan(plan)
        .into_iter()
        .any(|source_path| {
            safe_join(run_dir, &source_path)
                .ok()
                .and_then(|path| std::fs::read_to_string(path).ok())
                .is_some_and(|source| source.contains("DataStoreService"))
        })
}

fn build_persistence_data_models(
    recipes: &[String],
    datastore_source: bool,
) -> Vec<PersistenceDataModel> {
    let mut models = Vec::new();
    let needs_profile = datastore_source
        || recipes.iter().any(|recipe| {
            matches!(
                recipe.as_str(),
                "saveDataScaffold"
                    | "tycoonCore"
                    | "collectibleCoin"
                    | "starterShop"
                    | "questSystem"
                    | "inventorySystem"
                    | "toolSystem"
            )
        });
    if needs_profile {
        models.push(persistence_data_model(
            "player-profile",
            "Player Profile",
            vec!["saveDataScaffold"],
            if datastore_source {
                "DataStore"
            } else {
                "planned DataStore"
            },
            "userId",
            vec![
                "schemaVersion",
                "currency",
                "inventory",
                "ownedUpgrades",
                "questProgress",
                "lastSeenAt",
            ],
            "{schemaVersion=1,currency=0,inventory={},ownedUpgrades={},questProgress={}}",
            "Preserve earned progression and restore the player loop after reconnect.",
        ));
    }
    if recipes.iter().any(|recipe| recipe == "tycoonCore") {
        models.push(persistence_data_model(
            "tycoon-progress",
            "Tycoon Progress",
            vec!["tycoonCore"],
            if datastore_source {
                "profile field"
            } else {
                "planned profile field"
            },
            "userId:tycoon",
            vec!["cash", "ownedDroppers", "ownedUpgrades", "plotTheme"],
            "{cash=0,ownedDroppers={},ownedUpgrades={},plotTheme=nil}",
            "Avoid making players rebuild the same tycoon progress every session.",
        ));
    }
    if recipes.iter().any(|recipe| recipe == "collectibleCoin") {
        models.push(persistence_data_model(
            "collection-progress",
            "Collection Progress",
            vec!["collectibleCoin"],
            "profile field",
            "userId:collection",
            vec!["currency", "lifetimeCollected", "routeCompletions"],
            "{currency=0,lifetimeCollected=0,routeCompletions={}}",
            "Track earned currency and optional route mastery without storing personal data.",
        ));
    }
    if recipes.iter().any(|recipe| recipe == "starterShop") {
        models.push(persistence_data_model(
            "shop-state",
            "Shop State",
            vec!["starterShop"],
            "profile field",
            "userId:shop",
            vec!["ownedItems", "equippedItem", "previewedItems"],
            "{ownedItems={},equippedItem=nil,previewedItems={}}",
            "Persist owned/equipped items while keeping commerce IDs and receipts in explicit review.",
        ));
    }
    if recipes
        .iter()
        .any(|recipe| recipe == "questSystem" || recipe == "npcInteraction")
    {
        models.push(persistence_data_model(
            "quest-progress",
            "Quest Progress",
            vec!["questSystem", "npcInteraction"],
            "profile field",
            "userId:quests",
            vec!["activeQuestId", "objectives", "claimedRewards"],
            "{activeQuestId=nil,objectives={},claimedRewards={}}",
            "Resume readable objectives without granting duplicate rewards.",
        ));
    }
    models.sort_by(|left, right| left.id.cmp(&right.id));
    models.dedup_by(|left, right| left.id == right.id);
    models
}

fn persistence_data_model(
    id: &str,
    title: &str,
    recipe_sources: Vec<&str>,
    store_kind: &str,
    key_scope: &str,
    fields: Vec<&str>,
    default_value: &str,
    retention_reason: &str,
) -> PersistenceDataModel {
    PersistenceDataModel {
        id: id.into(),
        title: title.into(),
        recipe_sources: recipe_sources.into_iter().map(str::to_string).collect(),
        store_kind: store_kind.into(),
        key_scope: key_scope.into(),
        fields: fields.into_iter().map(str::to_string).collect(),
        default_value: default_value.into(),
        retention_reason: retention_reason.into(),
    }
}

fn build_persistence_data_flows(
    recipes: &[String],
    datastore_source: bool,
) -> Vec<PersistenceDataFlow> {
    let mut flows = vec![
        persistence_data_flow(
            "load-on-join",
            "Load On Join",
            "PlayerAdded after server authority initializes.",
            if datastore_source {
                "Read through DataStoreService with schemaVersion defaults."
            } else {
                "Planned only until saveDataScaffold or custom DataStore code exists."
            },
            "Use defaults, warn the player in UI only if gameplay would otherwise corrupt state, and never overwrite existing data with empty defaults after a failed read.",
            "ProfileLoadAttempted and ProfileLoadSucceeded or ProfileLoadFailed.",
        ),
        persistence_data_flow(
            "autosave",
            "Autosave",
            "Bounded interval after meaningful progress changes.",
            "Write only server-authoritative fields and debounce repeat writes.",
            "Queue retry with backoff; do not spam DataStore budgets or block the first-session loop.",
            "ProfileAutosaveAttempted and ProfileAutosaveSucceeded or ProfileAutosaveFailed.",
        ),
        persistence_data_flow(
            "save-on-leave",
            "Save On Leave",
            "PlayerRemoving and server shutdown.",
            "Persist the latest validated profile snapshot.",
            "If final save fails, preserve session log evidence and avoid claiming save success.",
            "ProfileSaveOnLeaveAttempted and ProfileSaveOnLeaveSucceeded.",
        ),
        persistence_data_flow(
            "migration-on-load",
            "Migration On Load",
            "After profile read and before gameplay state is exposed.",
            "Migrate from older schemaVersion to current schemaVersion in memory before writeback.",
            "Keep old fields until proof confirms migrated profiles can load and rollback guidance exists.",
            "ProfileMigrated with fromVersion and toVersion.",
        ),
    ];
    if recipes.iter().any(|recipe| recipe == "starterShop") {
        flows.push(persistence_data_flow(
            "entitlement-save",
            "Entitlement Save",
            "After server-validated shop grant or receipt handling.",
            "Persist owned item state only after the server confirms the grant.",
            "Do not invent product IDs, receipt success, or marketplace state in persistence.",
            "ShopEntitlementGranted and ProfileSaveQueued.",
        ));
    }
    flows.sort_by(|left, right| left.id.cmp(&right.id));
    flows
}

fn persistence_data_flow(
    id: &str,
    title: &str,
    trigger: &str,
    write_policy: &str,
    failure_policy: &str,
    telemetry_signal: &str,
) -> PersistenceDataFlow {
    PersistenceDataFlow {
        id: id.into(),
        title: title.into(),
        trigger: trigger.into(),
        write_policy: write_policy.into(),
        failure_policy: failure_policy.into(),
        telemetry_signal: telemetry_signal.into(),
    }
}

fn build_persistence_migrations(recipes: &[String]) -> Vec<PersistenceMigration> {
    let mut migrations = vec![persistence_migration(
        "schema-v1",
        "Initial Schema",
        "none",
        "1",
        "Create defaults for missing fields and record schemaVersion=1 before gameplay reads.",
        "Rollback by restoring the pre-apply package or leaving older profiles untouched until reviewed.",
    )];
    if recipes.iter().any(|recipe| recipe == "tycoonCore") {
        migrations.push(persistence_migration(
            "tycoon-upgrade-fields",
            "Tycoon Upgrade Fields",
            "1",
            "2",
            "Backfill ownedDroppers and ownedUpgrades as empty tables for existing player profiles.",
            "Keep cash values unchanged and block migration claims until a reload proof exists.",
        ));
    }
    if recipes.iter().any(|recipe| recipe == "starterShop") {
        migrations.push(persistence_migration(
            "shop-state-fields",
            "Shop State Fields",
            "1",
            "2",
            "Backfill ownedItems, equippedItem, and previewedItems without granting paid entitlements.",
            "Do not delete legacy ownership fields until entitlement proof and receipt review are complete.",
        ));
    }
    migrations.sort_by(|left, right| left.id.cmp(&right.id));
    migrations.dedup_by(|left, right| left.id == right.id);
    migrations
}

fn persistence_migration(
    id: &str,
    title: &str,
    from_version: &str,
    to_version: &str,
    strategy: &str,
    rollback_note: &str,
) -> PersistenceMigration {
    PersistenceMigration {
        id: id.into(),
        title: title.into(),
        from_version: from_version.into(),
        to_version: to_version.into(),
        strategy: strategy.into(),
        rollback_note: rollback_note.into(),
    }
}

fn build_persistence_proof_checks(
    run_dir: &Path,
    has_telemetry: bool,
    has_policy: bool,
    has_authority: bool,
    has_balance: bool,
    has_live_apply: bool,
    datastore_source: bool,
) -> Vec<PersistenceProofCheck> {
    let mut checks = vec![
        persistence_proof_check(
            "datastore-implementation",
            "DataStore Implementation Exists",
            datastore_source,
            "Generated or adopted source includes reviewed DataStoreService usage, or persistence is clearly marked planned-only.",
            vec![run_dir.join("source-audit.json").to_string_lossy().to_string()],
            (!datastore_source).then(|| "saveDataScaffold or reviewed DataStore source".into()),
            format!(
                "rs autopilot audit-sources {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ),
        persistence_proof_check(
            "telemetry",
            "Telemetry Covers Save/Load",
            has_telemetry,
            "Telemetry defines anonymous profile load, save, migration, and failure signals.",
            vec![run_dir.join("telemetry.json").to_string_lossy().to_string()],
            (!has_telemetry).then(|| "telemetry.json".into()),
            format!(
                "rs autopilot telemetry {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ),
        persistence_proof_check(
            "policy",
            "Policy Review Exists",
            has_policy,
            "Policy review covers personal data, persistence, HTTP, commerce, and off-platform risks.",
            vec![run_dir.join("policy.json").to_string_lossy().to_string()],
            (!has_policy).then(|| "policy.json".into()),
            format!(
                "rs autopilot policy {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ),
        persistence_proof_check(
            "authority",
            "Server Authority Reviewed",
            has_authority,
            "Server authority review confirms clients cannot write persisted state directly.",
            vec![run_dir.join("authority.json").to_string_lossy().to_string()],
            (!has_authority).then(|| "authority.json".into()),
            format!(
                "rs autopilot authority {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ),
        persistence_proof_check(
            "balance",
            "Persisted Economy Reviewed",
            has_balance,
            "Balance review covers persisted currencies, rewards, prices, and first-purchase pacing.",
            vec![run_dir.join("balance.json").to_string_lossy().to_string()],
            (!has_balance).then(|| "balance.json".into()),
            format!(
                "rs autopilot balance {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ),
        persistence_proof_check(
            "live-reload-proof",
            "Live Reload Proof",
            has_live_apply,
            "After approved apply, a player earns progress, leaves/rejoins or reloads, and the same progress is restored.",
            vec![run_dir.join("apply.json").to_string_lossy().to_string()],
            (!has_live_apply).then(|| "approved apply and reload playtest evidence".into()),
            format!(
                "rs autopilot record-playtest {} --result passed --evidence \"save/load proof captured\" --scenario persistence=passed",
                command_arg(run_dir.to_string_lossy().as_ref())
            ),
        ),
    ];
    checks.sort_by(|left, right| left.id.cmp(&right.id));
    checks
}

fn persistence_proof_check(
    id: &str,
    title: &str,
    pass: bool,
    expected: &str,
    evidence: Vec<String>,
    missing: Option<String>,
    suggested_command: String,
) -> PersistenceProofCheck {
    PersistenceProofCheck {
        id: id.into(),
        title: title.into(),
        status: if pass { "pass" } else { "warn" }.into(),
        expected: expected.into(),
        evidence,
        missing: missing.into_iter().collect(),
        suggested_command,
    }
}

fn build_persistence_guardrails() -> Vec<String> {
    vec![
        "Do not claim progress saves until DataStore code, API services readiness, approved apply, reload proof, and rollback evidence exist.".into(),
        "Never overwrite existing player data with empty defaults after a failed read or migration.".into(),
        "Only the server may mutate persisted currency, inventory, quest progress, entitlements, or tycoon upgrades.".into(),
        "Do not store chat text, personal data, secrets, off-platform contact information, or raw analytics payloads in player profiles.".into(),
        "Keep schemaVersion, migration strategy, fallback defaults, retry behavior, and data-loss messaging explicit before live apply.".into(),
    ]
}

fn resolve_asset_brief_paths(options: &AssetBriefOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot asset-brief requires a run directory or --plan".into(),
        )),
    }
}

fn build_asset_brief_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    asset_brief_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<AssetBriefReport> {
    let mut requests = Vec::new();
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let recipes = recipes_for_run(run_dir, plan).unwrap_or_default();

    collect_asset_recipe_requests(run_dir, plan, &recipes, &mut requests);
    collect_asset_operation_requests(plan, &mut requests);
    collect_asset_source_requests(run_dir, plan, &mut requests, &mut blockers, &mut warnings);
    collect_asset_prompt_requests(plan, &mut requests);
    let creative_context = asset_creative_context(run_dir, plan, &recipes);
    if !creative_context.is_empty() {
        for request in &mut requests {
            request.prompt = format!("{} {}", request.prompt, creative_context);
        }
    }

    requests.sort_by(|left, right| {
        asset_priority_rank(&left.priority)
            .cmp(&asset_priority_rank(&right.priority))
            .then(left.kind.cmp(&right.kind))
            .then(left.name.cmp(&right.name))
            .then(left.source.cmp(&right.source))
    });
    requests.dedup_by(|left, right| {
        left.kind == right.kind
            && left.name == right.name
            && left.source == right.source
            && left.studio_path == right.studio_path
            && left.source_path == right.source_path
    });
    for (index, request) in requests.iter_mut().enumerate() {
        request.id = format!("asset-{:03}", index + 1);
    }

    let groups = build_asset_brief_groups(&requests);
    let high_priority_count = requests
        .iter()
        .filter(|request| request.priority == "high")
        .count();
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    let status = if !blockers.is_empty() {
        "blocked"
    } else if requests.is_empty() {
        "noAssetNeedsFound"
    } else {
        "assetBriefReady"
    }
    .to_string();

    let mut next_actions = Vec::new();
    if !requests.is_empty() {
        next_actions.push(coach_action(
            1,
            "Review asset production brief",
            Some(format!(
                "rs autopilot asset-brief {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
            "Use the asset brief as the art, audio, and VFX shopping list before live review.",
            false,
            false,
        ));
        next_actions.push(coach_action(
            2,
            "Import approved local assets",
            Some("rs import-image --file .\\assets\\icon.png --to StarterGui --kind image".into()),
            "The generated requests include concrete import/upload command templates for each asset kind.",
            true,
            true,
        ));
    }
    next_actions.push(coach_action(
        9,
        "Refresh bundle after asset decisions",
        Some(format!(
            "rs autopilot refresh {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Refresh derived packets after assets, thumbnails, or UI art are added to the run.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);

    let agent_brief = format!(
        "Asset brief for '{}' is {} with {} request(s), {} high-priority request(s), and {} asset group(s). Use it to coordinate UI images, models, audio, VFX, and import/upload work before claiming the slice feels production-ready.",
        plan.request.prompt,
        status,
        requests.len(),
        high_priority_count,
        groups.len()
    );

    Ok(AssetBriefReport {
        schema_version: "rs.autopilot.asset-brief.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        asset_brief_path: asset_brief_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        request_count: requests.len(),
        high_priority_count,
        groups,
        requests,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn collect_asset_recipe_requests(
    run_dir: &Path,
    plan: &AutopilotPlan,
    recipes: &[String],
    requests: &mut Vec<AssetBriefRequest>,
) {
    for recipe in recipes {
        match recipe.as_str() {
            "starterShop" => {
                push_asset_request(
                    requests,
                    asset_request(
                        "ui-image",
                        "high",
                        "Shop Button Icon",
                        "Player-facing shop entry point and item tiles.",
                        "recipe:starterShop",
                        None,
                        None,
                        plan,
                    ),
                );
                push_asset_request(
                    requests,
                    asset_request(
                        "audio",
                        "medium",
                        "Purchase Confirm Sound",
                        "Clear feedback when a shop purchase succeeds or fails.",
                        "recipe:starterShop",
                        None,
                        None,
                        plan,
                    ),
                );
            }
            "collectibleCoin" => {
                push_asset_request(
                    requests,
                    asset_request(
                        "3d-model",
                        "high",
                        "Collectible Coin",
                        "Readable pickup object that players can spot quickly.",
                        "recipe:collectibleCoin",
                        None,
                        None,
                        plan,
                    ),
                );
                push_asset_request(
                    requests,
                    asset_request(
                        "audio",
                        "medium",
                        "Coin Pickup Chime",
                        "Short reward cue for successful collection.",
                        "recipe:collectibleCoin",
                        None,
                        None,
                        plan,
                    ),
                );
            }
            "tycoonCore" => {
                push_asset_request(
                    requests,
                    asset_request(
                        "3d-model",
                        "high",
                        "Tycoon Dropper Kit",
                        "Dropper, conveyor, collector, and upgrade button silhouettes.",
                        "recipe:tycoonCore",
                        None,
                        None,
                        plan,
                    ),
                );
                push_asset_request(
                    requests,
                    asset_request(
                        "vfx-material",
                        "medium",
                        "Dropper Production Burst",
                        "Subtle visual feedback when the tycoon produces cash.",
                        "recipe:tycoonCore",
                        None,
                        None,
                        plan,
                    ),
                );
            }
            "obbyCheckpoint" => {
                push_asset_request(
                    requests,
                    asset_request(
                        "3d-model",
                        "high",
                        "Checkpoint And Finish Pads",
                        "Distinct checkpoint, reset, and finish-state props.",
                        "recipe:obbyCheckpoint",
                        None,
                        None,
                        plan,
                    ),
                );
                push_asset_request(
                    requests,
                    asset_request(
                        "audio",
                        "medium",
                        "Checkpoint Chime",
                        "Positive cue when checkpoint progress is saved.",
                        "recipe:obbyCheckpoint",
                        None,
                        None,
                        plan,
                    ),
                );
            }
            "enemyEncounter" => {
                push_asset_request(
                    requests,
                    asset_request(
                        "3d-model",
                        "high",
                        "Training Enemy",
                        "Readable enemy body with hit/defeat states.",
                        "recipe:enemyEncounter",
                        None,
                        None,
                        plan,
                    ),
                );
                push_asset_request(
                    requests,
                    asset_request(
                        "vfx-material",
                        "medium",
                        "Hit Flash",
                        "Small impact effect that confirms attacks landed.",
                        "recipe:enemyEncounter",
                        None,
                        None,
                        plan,
                    ),
                );
            }
            "npcInteraction" => {
                push_asset_request(
                    requests,
                    asset_request(
                        "3d-model",
                        "high",
                        "Guide NPC",
                        "Friendly guide character near the first objective.",
                        "recipe:npcInteraction",
                        None,
                        None,
                        plan,
                    ),
                );
                push_asset_request(
                    requests,
                    asset_request(
                        "ui-image",
                        "medium",
                        "Dialogue Portrait",
                        "Portrait or icon that anchors dialogue UI.",
                        "recipe:npcInteraction",
                        None,
                        None,
                        plan,
                    ),
                );
            }
            "questSystem" => push_asset_request(
                requests,
                asset_request(
                    "ui-image",
                    "medium",
                    "Quest Tracker Icons",
                    "Small objective and reward icons for quest UI.",
                    "recipe:questSystem",
                    None,
                    None,
                    plan,
                ),
            ),
            "inventorySystem" | "toolSystem" => push_asset_request(
                requests,
                asset_request(
                    "ui-image",
                    "medium",
                    "Inventory Item Icons",
                    "Readable item icons for inventory and equip surfaces.",
                    &format!("recipe:{recipe}"),
                    None,
                    None,
                    plan,
                ),
            ),
            "lobbyTeleport" => push_asset_request(
                requests,
                asset_request(
                    "vfx-material",
                    "medium",
                    "Teleport Portal Effect",
                    "Clear portal/arrival effect for lobby and arena pads.",
                    "recipe:lobbyTeleport",
                    None,
                    None,
                    plan,
                ),
            ),
            "roundManager" => push_asset_request(
                requests,
                asset_request(
                    "audio",
                    "medium",
                    "Round Countdown Cue",
                    "Short countdown/start/end cues for round state transitions.",
                    "recipe:roundManager",
                    None,
                    None,
                    plan,
                ),
            ),
            "adminPanel" | "saveDataScaffold" => push_asset_request(
                requests,
                asset_request(
                    "ui-image",
                    "low",
                    &format!("{} Status Icon", title_case_words(recipe)),
                    "Utility icon for status, admin, or persistence feedback.",
                    &format!("recipe:{recipe}"),
                    None,
                    None,
                    plan,
                ),
            ),
            _ => {}
        }
    }

    if recipes.iter().any(|recipe| {
        matches!(
            recipe.as_str(),
            "starterShop" | "collectibleCoin" | "tycoonCore" | "enemyEncounter"
        )
    }) {
        push_asset_request(
            requests,
            asset_request(
                "thumbnail",
                "low",
                "Experience Thumbnail",
                "Marketing image that shows the generated core loop clearly.",
                "recipe-stack",
                None,
                None,
                plan,
            ),
        );
    }

    if recipes.is_empty() && !run_dir.join("request.json").exists() {
        push_asset_request(
            requests,
            asset_request(
                "ui-image",
                "low",
                "Feature Icon",
                "Generic icon for reviewing the generated feature before custom art exists.",
                "plan",
                None,
                None,
                plan,
            ),
        );
    }
}

fn collect_asset_operation_requests(plan: &AutopilotPlan, requests: &mut Vec<AssetBriefRequest>) {
    for operation in &plan.operations {
        let studio_path = impact_operation_path(operation);
        let class_name = operation.class_name.as_deref().unwrap_or("");
        let name = operation
            .name
            .as_deref()
            .or_else(|| {
                studio_path
                    .as_deref()
                    .and_then(|path| path.rsplit('.').next())
            })
            .unwrap_or("Generated Surface");
        let mut haystack = vec![
            class_name.to_string(),
            name.to_string(),
            studio_path.clone().unwrap_or_default(),
            operation.kind.clone(),
        ];
        for value in operation.properties.values() {
            if let Some(text) = value.as_str() {
                haystack.push(text.to_string());
            }
        }
        let lower = haystack.join(" ").to_ascii_lowercase();

        if matches!(
            class_name,
            "ImageButton"
                | "ImageLabel"
                | "TextButton"
                | "TextLabel"
                | "ScreenGui"
                | "BillboardGui"
        ) || lower.contains("icon")
            || lower.contains("button")
            || lower.contains("dialogue")
            || lower.contains("quest")
        {
            push_asset_request(
                requests,
                asset_request(
                    "ui-image",
                    if matches!(class_name, "ImageButton" | "TextButton") {
                        "high"
                    } else {
                        "medium"
                    },
                    &format!("{} UI Art", title_case_words(name)),
                    "UI polish for generated player-facing surfaces.",
                    "plan-operation",
                    studio_path.clone(),
                    operation.source_path.clone(),
                    plan,
                ),
            );
        }

        if matches!(class_name, "Part" | "Model" | "MeshPart" | "Tool")
            && [
                "coin",
                "dropper",
                "collector",
                "conveyor",
                "upgrade",
                "checkpoint",
                "enemy",
                "npc",
                "portal",
                "teleport",
                "shop",
                "tool",
            ]
            .iter()
            .any(|needle| lower.contains(needle))
        {
            push_asset_request(
                requests,
                asset_request(
                    "3d-model",
                    "high",
                    &format!("{} Model", title_case_words(name)),
                    "Replace primitive gameplay parts with readable Roblox-ready props.",
                    "plan-operation",
                    studio_path.clone(),
                    operation.source_path.clone(),
                    plan,
                ),
            );
        }

        if class_name == "Sound"
            || operation.asset_kind.as_deref() == Some("audio")
            || lower.contains("sound")
            || lower.contains("chime")
        {
            push_asset_request(
                requests,
                asset_request(
                    "audio",
                    "medium",
                    &format!("{} Cue", title_case_words(name)),
                    "Player feedback sound for the generated interaction.",
                    "plan-operation",
                    studio_path.clone(),
                    operation.source_path.clone(),
                    plan,
                ),
            );
        }

        if matches!(
            class_name,
            "ParticleEmitter" | "Trail" | "Beam" | "Highlight"
        ) || lower.contains("spark")
            || lower.contains("confetti")
            || lower.contains("burst")
            || lower.contains("portal")
        {
            push_asset_request(
                requests,
                asset_request(
                    "vfx-material",
                    "medium",
                    &format!("{} Effect", title_case_words(name)),
                    "Visual feedback material or texture for moment-to-moment clarity.",
                    "plan-operation",
                    studio_path.clone(),
                    operation.source_path.clone(),
                    plan,
                ),
            );
        }
    }
}

fn collect_asset_source_requests(
    run_dir: &Path,
    plan: &AutopilotPlan,
    requests: &mut Vec<AssetBriefRequest>,
    blockers: &mut Vec<String>,
    warnings: &mut Vec<String>,
) {
    for source_path in generated_files_for_plan(plan) {
        match safe_join(run_dir, &source_path) {
            Ok(path) => match std::fs::read_to_string(path) {
                Ok(source) => asset_scan_text(&source, Some(source_path), plan, requests),
                Err(_) => warnings.push(format!(
                    "generated source could not be read for asset direction: {source_path}"
                )),
            },
            Err(err) => blockers.push(format!(
                "generated source path could not be inspected for asset direction: {source_path}: {err}"
            )),
        }
    }
}

fn collect_asset_prompt_requests(plan: &AutopilotPlan, requests: &mut Vec<AssetBriefRequest>) {
    asset_scan_text(&plan.request.prompt, None, plan, requests);
}

fn asset_creative_context(run_dir: &Path, plan: &AutopilotPlan, recipes: &[String]) -> String {
    let style_path = run_dir.join("style-guide.json");
    let style_value = read_json_file(&style_path).ok();
    let theme = style_value
        .as_ref()
        .and_then(|value| value.get("theme"))
        .and_then(Value::as_str)
        .map(str::to_string)
        .unwrap_or_else(|| infer_style_theme(&plan.request.prompt, recipes));
    let tone = style_value
        .as_ref()
        .and_then(|value| value.get("tone"))
        .and_then(Value::as_str)
        .map(str::to_string)
        .unwrap_or_else(|| infer_style_tone(&plan.request.prompt, recipes));
    let mut zones = read_json_file(&run_dir.join("world-blueprint.json"))
        .ok()
        .and_then(|value| {
            value.get("zones").and_then(Value::as_array).map(|zones| {
                zones
                    .iter()
                    .filter_map(|zone| zone.get("name").and_then(Value::as_str))
                    .take(5)
                    .map(str::to_string)
                    .collect::<Vec<_>>()
            })
        })
        .unwrap_or_else(|| {
            build_world_zones(plan, recipes)
                .into_iter()
                .take(5)
                .map(|zone| zone.name)
                .collect()
        });
    zones.sort();
    zones.dedup();
    let zone_clause = if zones.is_empty() {
        "Anchor assets to the primary playable space.".to_string()
    } else {
        format!("Anchor assets to these world zones: {}.", zones.join(", "))
    };
    format!("Follow style theme '{theme}' with a {tone} tone. {zone_clause}")
}

fn asset_scan_text(
    text: &str,
    source_path: Option<String>,
    plan: &AutopilotPlan,
    requests: &mut Vec<AssetBriefRequest>,
) {
    let lower = text.to_ascii_lowercase();
    let source = source_path
        .as_deref()
        .map(|path| format!("generated-source:{path}"))
        .unwrap_or_else(|| "prompt".into());

    for (needle, kind, name, purpose, priority) in [
        (
            "coin",
            "3d-model",
            "Collectible Coin",
            "Readable pickup or currency prop.",
            "high",
        ),
        (
            "dropper",
            "3d-model",
            "Dropper Machine",
            "Readable tycoon production prop.",
            "high",
        ),
        (
            "enemy",
            "3d-model",
            "Enemy Character",
            "Readable opponent silhouette.",
            "high",
        ),
        (
            "npc",
            "3d-model",
            "Guide NPC",
            "Friendly guide character.",
            "high",
        ),
        (
            "shop",
            "ui-image",
            "Shop Icon Set",
            "Shop entry and item art.",
            "high",
        ),
        (
            "quest",
            "ui-image",
            "Quest Icon Set",
            "Quest objective and reward art.",
            "medium",
        ),
        (
            "checkpoint",
            "audio",
            "Checkpoint Chime",
            "Positive progress feedback cue.",
            "medium",
        ),
        (
            "sound",
            "audio",
            "Interaction Sound Pack",
            "Short reward, error, click, and success cues.",
            "medium",
        ),
        (
            "particle",
            "vfx-material",
            "Particle Texture Pack",
            "Transparent VFX textures for generated feedback.",
            "medium",
        ),
        (
            "thumbnail",
            "thumbnail",
            "Experience Thumbnail",
            "Marketing image for creator review or publish prep.",
            "low",
        ),
    ] {
        if lower.contains(needle) {
            push_asset_request(
                requests,
                asset_request(
                    kind,
                    priority,
                    name,
                    purpose,
                    &source,
                    None,
                    source_path.clone(),
                    plan,
                ),
            );
        }
    }
}

fn asset_request(
    kind: &str,
    priority: &str,
    name: &str,
    purpose: &str,
    source: &str,
    studio_path: Option<String>,
    source_path: Option<String>,
    plan: &AutopilotPlan,
) -> AssetBriefRequest {
    AssetBriefRequest {
        id: String::new(),
        kind: kind.into(),
        priority: priority.into(),
        name: name.into(),
        purpose: purpose.into(),
        source: source.into(),
        studio_path,
        source_path,
        prompt: asset_generation_prompt(kind, name, purpose, plan),
        acceptance: asset_acceptance(kind),
        suggested_commands: asset_suggested_commands(kind, name, plan),
    }
}

fn push_asset_request(requests: &mut Vec<AssetBriefRequest>, request: AssetBriefRequest) {
    requests.push(request);
}

fn asset_generation_prompt(kind: &str, name: &str, purpose: &str, plan: &AutopilotPlan) -> String {
    match kind {
        "ui-image" => format!(
            "Create transparent PNG UI art for Roblox named '{name}'. Purpose: {purpose} Match this game request: {}. Keep it readable at 64px and avoid text baked into the image.",
            plan.request.prompt
        ),
        "3d-model" => format!(
            "Create a Roblox-ready low-poly 3D asset named '{name}'. Purpose: {purpose} Match this game request: {}. Favor simple silhouettes, clean pivots, and low material count.",
            plan.request.prompt
        ),
        "audio" => format!(
            "Create a short Roblox-ready sound cue named '{name}'. Purpose: {purpose} Match this game request: {}. Keep it under two seconds unless it is ambience.",
            plan.request.prompt
        ),
        "vfx-material" => format!(
            "Create a Roblox-friendly VFX texture or material direction named '{name}'. Purpose: {purpose} Match this game request: {}. Keep the effect clear, lightweight, and non-obscuring.",
            plan.request.prompt
        ),
        "thumbnail" => format!(
            "Create a Roblox experience thumbnail concept named '{name}'. Purpose: {purpose} Show the actual generated core loop from this request: {}.",
            plan.request.prompt
        ),
        _ => format!(
            "Create a Roblox-ready asset named '{name}'. Purpose: {purpose} Match this game request: {}.",
            plan.request.prompt
        ),
    }
}

fn asset_acceptance(kind: &str) -> Vec<String> {
    match kind {
        "ui-image" => vec![
            "PNG has transparent background when appropriate.".into(),
            "Reads clearly at small UI sizes.".into(),
            "Avoids baked-in text so copy can be localized.".into(),
        ],
        "3d-model" => vec![
            "Low-poly silhouette is recognizable from gameplay camera distance.".into(),
            "Pivot, scale, and collision are easy to place in Studio.".into(),
            "Material count stays low enough for Roblox mobile play.".into(),
        ],
        "audio" => vec![
            "Cue is short, non-clipping, and not fatiguing when repeated.".into(),
            "Looping audio has no obvious click at the seam.".into(),
            "Filename and Roblox asset ID are recorded before import.".into(),
        ],
        "vfx-material" => vec![
            "Effect improves feedback without hiding gameplay.".into(),
            "Texture has transparent edges when used in particles.".into(),
            "Effect can be disabled or toned down for accessibility review.".into(),
        ],
        "thumbnail" => vec![
            "Thumbnail shows the real game loop, not only atmosphere.".into(),
            "Composition remains readable at Roblox discovery sizes.".into(),
            "Does not promise content that the run does not generate.".into(),
        ],
        _ => vec!["Asset is named, reviewed, and imported through an explicit command.".into()],
    }
}

fn asset_suggested_commands(kind: &str, name: &str, plan: &AutopilotPlan) -> Vec<String> {
    let slug_name = slug(name);
    let studio_arg = plan
        .request
        .studio
        .as_ref()
        .map(|studio| format!(" --studio {}", command_arg(studio)))
        .unwrap_or_default();
    match kind {
        "ui-image" => vec![format!(
            "rs import-image{studio_arg} --file .\\assets\\{slug_name}.png --to StarterGui --kind image --name {}",
            command_arg(name)
        )],
        "3d-model" => vec![format!(
            "rs import-asset{studio_arg} --file .\\assets\\{slug_name}.glb --to Workspace --name {}",
            command_arg(name)
        )],
        "audio" => vec![format!(
            "rs import-audio{studio_arg} --file .\\audio\\{slug_name}.wav --asset-id rbxassetid://<asset-id> --to SoundService --name {}",
            command_arg(name)
        )],
        "vfx-material" => vec![
            format!(
                "rs import-image{studio_arg} --file .\\assets\\{slug_name}-particle.png --to ReplicatedStorage --kind image --name {}",
                command_arg(name)
            )
        ],
        "thumbnail" => vec![format!(
            "rs upload image .\\marketing\\{slug_name}.png --profile <profile> --wait"
        )],
        _ => vec![format!(
            "rs import-asset{studio_arg} --file .\\assets\\{slug_name}.glb --to Workspace --name {}",
            command_arg(name)
        )],
    }
}

fn build_asset_brief_groups(requests: &[AssetBriefRequest]) -> Vec<AssetBriefGroup> {
    let mut counts: BTreeMap<String, (usize, usize)> = BTreeMap::new();
    for request in requests {
        let entry = counts.entry(request.kind.clone()).or_insert((0, 0));
        entry.0 += 1;
        if request.priority == "high" {
            entry.1 += 1;
        }
    }
    counts
        .into_iter()
        .map(|(kind, (count, high_priority_count))| AssetBriefGroup {
            summary: format!("{count} {kind} request(s), {high_priority_count} high priority"),
            kind,
            count,
            high_priority_count,
        })
        .collect()
}

fn asset_priority_rank(priority: &str) -> u8 {
    match priority {
        "high" => 0,
        "medium" => 1,
        "low" => 2,
        _ => 3,
    }
}

fn title_case_words(value: &str) -> String {
    value
        .split(|ch: char| !ch.is_ascii_alphanumeric())
        .filter(|part| !part.is_empty())
        .map(|part| {
            let mut chars = part.chars();
            match chars.next() {
                Some(first) => format!(
                    "{}{}",
                    first.to_ascii_uppercase(),
                    chars.as_str().to_ascii_lowercase()
                ),
                None => String::new(),
            }
        })
        .collect::<Vec<_>>()
        .join(" ")
}

fn resolve_improve_paths(options: &ImproveOptions) -> AppResult<(PathBuf, PathBuf)> {
    match (&options.run_dir, &options.plan) {
        (Some(run_dir), Some(plan)) => Ok((run_dir.clone(), plan.clone())),
        (Some(run_dir), None) => Ok((run_dir.clone(), run_dir.join("plan.json"))),
        (None, Some(plan)) => Ok((
            plan.parent()
                .map(Path::to_path_buf)
                .unwrap_or_else(|| PathBuf::from(".")),
            plan.clone(),
        )),
        (None, None) => Err(AppError::Other(
            "autopilot improve requires --run-dir or --plan".into(),
        )),
    }
}

fn select_improvement_recipes(
    source_recipes: &[String],
    gaps: &[GameplayCritiqueGap],
    requested_recipes: &[String],
    max_recipes: usize,
) -> AppResult<(Vec<ImproveRecipePatch>, Vec<String>)> {
    let existing = source_recipes.iter().cloned().collect::<BTreeSet<_>>();
    let mut selected = Vec::new();
    let mut seen = BTreeSet::new();
    let mut skipped = Vec::new();

    if !requested_recipes.is_empty() {
        for requested in requested_recipes {
            let recipe = normalize_recipe(requested)?;
            if existing.contains(&recipe) {
                skipped.push(format!(
                    "recipe {recipe} was already present in the source run"
                ));
                continue;
            }
            if !seen.insert(recipe.clone()) {
                skipped.push(format!("recipe {recipe} was requested more than once"));
                continue;
            }
            if selected.len() >= max_recipes {
                skipped.push(format!(
                    "recipe {recipe} exceeded --max-recipes {max_recipes}"
                ));
                continue;
            }
            selected.push(ImproveRecipePatch {
                recipe,
                category: "manual".into(),
                severity: "info".into(),
                reason: "requested with --recipe".into(),
            });
        }
        return Ok((selected, skipped));
    }

    for gap in gaps
        .iter()
        .filter(|gap| gap.severity == "blocker" || gap.severity == "warning")
    {
        let Some(recipe) = &gap.suggested_recipe else {
            skipped.push(format!("{} has no deterministic recipe", gap.category));
            continue;
        };
        let recipe = normalize_recipe(recipe)?;
        if existing.contains(&recipe) {
            skipped.push(format!(
                "{} suggested {recipe}, but it was already present",
                gap.category
            ));
            continue;
        }
        if !seen.insert(recipe.clone()) {
            skipped.push(format!(
                "{} suggested duplicate recipe {recipe}",
                gap.category
            ));
            continue;
        }
        if selected.len() >= max_recipes {
            skipped.push(format!(
                "{} suggested {recipe}, but --max-recipes {max_recipes} was reached",
                gap.category
            ));
            continue;
        }
        selected.push(ImproveRecipePatch {
            recipe,
            category: gap.category.clone(),
            severity: gap.severity.clone(),
            reason: gap.message.clone(),
        });
    }

    Ok((selected, skipped))
}

fn default_improvement_run_dir(source_run_dir: &Path, patches: &[ImproveRecipePatch]) -> PathBuf {
    let suffix = patches
        .iter()
        .map(|patch| slug(&patch.recipe))
        .collect::<Vec<_>>()
        .join("-");
    let source_name = source_run_dir
        .file_name()
        .map(|name| name.to_string_lossy().to_string())
        .filter(|name| !name.trim().is_empty())
        .unwrap_or_else(|| "autopilot-run".into());
    source_run_dir.with_file_name(format!("{source_name}-improve-{suffix}"))
}

