fn build_noop_improve_report(
    report_path: &Path,
    markdown_path: Option<&Path>,
    source_run_dir: &Path,
    source_plan_path: &Path,
    source_plan: &AutopilotPlan,
    source_critique: &GameplayCritiqueReport,
    skipped_gaps: Vec<String>,
) -> ImproveReport {
    let playable = source_critique.verdict == "playableSlice";
    let status = if playable {
        "alreadyPlayable"
    } else {
        "noDeterministicPatch"
    }
    .to_string();
    let mut blockers = Vec::new();
    if !playable {
        blockers.push(
            "no deterministic improvement recipe remained after filtering critique gaps".into(),
        );
    }
    let mut artifacts = BTreeMap::new();
    artifacts.insert(
        "sourcePlan".into(),
        source_plan_path.to_string_lossy().to_string(),
    );
    artifacts.insert(
        "sourceCritique".into(),
        source_run_dir
            .join("gameplay-critique.json")
            .to_string_lossy()
            .to_string(),
    );

    let mut next_actions = Vec::new();
    if playable {
        next_actions.push(CoachAction {
            priority: 1,
            title: "Move to live readiness".into(),
            command: Some("rs autopilot ready --timeout 90 --format json".into()),
            reason:
                "The source run already covers the core gameplay dimensions; live evidence is next."
                    .into(),
            requires_live_studio: true,
            mutates_studio: false,
        });
    } else {
        next_actions.push(CoachAction {
            priority: 1,
            title: "Ask an AI planner for a custom patch".into(),
            command: Some(format!(
                "rs autopilot planner-pack --run-dir {} --format json",
                source_run_dir.to_string_lossy()
            )),
            reason: "The deterministic recipe catalog could not cover the remaining critique gaps."
                .into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
    }

    ImproveReport {
        schema_version: "rs.autopilot.improve.v1".into(),
        generated_at: now_stamp(),
        improvement_path: report_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        source_run_dir: source_run_dir.to_string_lossy().to_string(),
        source_plan_path: source_plan_path.to_string_lossy().to_string(),
        source_plan_id: source_plan.id.clone(),
        source_prompt: source_plan.request.prompt.clone(),
        source_verdict: source_critique.verdict.clone(),
        source_score: source_critique.score,
        improved_run_dir: None,
        improved_plan_path: None,
        improved_plan_id: None,
        improved_verdict: None,
        improved_score: None,
        score_delta: None,
        status,
        selected_recipes: Vec::new(),
        skipped_gaps,
        artifacts,
        blockers,
        warnings: source_critique.warnings.clone(),
        next_actions,
        agent_brief: format!(
            "Improve '{}' found no deterministic patch. Source verdict is '{}' with score {}.",
            source_plan.request.prompt, source_critique.verdict, source_critique.score
        ),
    }
}

fn build_patched_improve_report(
    report_path: &Path,
    markdown_path: Option<&Path>,
    source_run_dir: &Path,
    source_plan_path: &Path,
    source_plan: &AutopilotPlan,
    source_critique: &GameplayCritiqueReport,
    improved_run_dir: &Path,
    improved_plan_path: &Path,
    improved_plan: &AutopilotPlan,
    improved_critique: &GameplayCritiqueReport,
    selected_recipes: Vec<ImproveRecipePatch>,
    skipped_gaps: Vec<String>,
) -> ImproveReport {
    let score_delta = i16::from(improved_critique.score) - i16::from(source_critique.score);
    let status = if !improved_critique.blockers.is_empty() {
        "patchedWithBlockers"
    } else if improved_critique.verdict == "playableSlice" {
        "readyToPlaytest"
    } else {
        "patchedNeedsIteration"
    }
    .to_string();

    let mut artifacts = BTreeMap::new();
    artifacts.insert(
        "sourcePlan".into(),
        source_plan_path.to_string_lossy().to_string(),
    );
    artifacts.insert(
        "sourceCritique".into(),
        source_run_dir
            .join("gameplay-critique.json")
            .to_string_lossy()
            .to_string(),
    );
    artifacts.insert(
        "improvedPlan".into(),
        improved_plan_path.to_string_lossy().to_string(),
    );
    artifacts.insert(
        "improvedPreview".into(),
        improved_run_dir
            .join("preview.json")
            .to_string_lossy()
            .to_string(),
    );
    artifacts.insert(
        "improvedHandoff".into(),
        improved_run_dir
            .join("handoff.json")
            .to_string_lossy()
            .to_string(),
    );
    artifacts.insert(
        "improvedCertification".into(),
        improved_run_dir
            .join("certification.json")
            .to_string_lossy()
            .to_string(),
    );
    artifacts.insert(
        "improvedCritique".into(),
        improved_run_dir
            .join("gameplay-critique.json")
            .to_string_lossy()
            .to_string(),
    );
    artifacts.insert(
        "improvedPlaytest".into(),
        improved_run_dir
            .join("playtest-plan.json")
            .to_string_lossy()
            .to_string(),
    );

    let mut next_actions = Vec::new();
    next_actions.push(CoachAction {
        priority: 1,
        title: "Review the improved patch run".into(),
        command: Some(format!(
            "rs autopilot handoff {} --format json",
            improved_run_dir.to_string_lossy()
        )),
        reason: "Inspect the generated patch artifacts before live Studio mutation.".into(),
        requires_live_studio: false,
        mutates_studio: false,
    });
    next_actions.push(CoachAction {
        priority: 2,
        title: "Verify the improved bundle".into(),
        command: Some(format!(
            "rs autopilot verify-bundle --run-dir {} --format json",
            improved_run_dir.to_string_lossy()
        )),
        reason: "Prove the patch run artifacts have not drifted before handoff or apply.".into(),
        requires_live_studio: false,
        mutates_studio: false,
    });
    if improved_critique.verdict == "playableSlice" {
        next_actions.push(CoachAction {
            priority: 3,
            title: "Check live readiness for the improved run".into(),
            command: Some("rs autopilot ready --timeout 90 --format json".into()),
            reason: "The improved run is design-complete enough to move toward live apply.".into(),
            requires_live_studio: true,
            mutates_studio: false,
        });
        next_actions.push(CoachAction {
            priority: 4,
            title: "Apply the improved patch after approval".into(),
            command: Some(format!(
                "rs autopilot apply --plan {} --yes --rollback-on-error --validate",
                improved_plan_path.to_string_lossy()
            )),
            reason: "Apply only after readiness passes and the user approves Studio mutation."
                .into(),
            requires_live_studio: true,
            mutates_studio: true,
        });
    } else {
        next_actions.push(CoachAction {
            priority: 3,
            title: "Iterate on the improved run".into(),
            command: Some(format!(
                "rs autopilot improve --run-dir {} --format json",
                improved_run_dir.to_string_lossy()
            )),
            reason: "The patch improved the plan but more gameplay gaps remain.".into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
    }

    let recipe_list = selected_recipes
        .iter()
        .map(|patch| patch.recipe.as_str())
        .collect::<Vec<_>>()
        .join(", ");
    ImproveReport {
        schema_version: "rs.autopilot.improve.v1".into(),
        generated_at: now_stamp(),
        improvement_path: report_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        source_run_dir: source_run_dir.to_string_lossy().to_string(),
        source_plan_path: source_plan_path.to_string_lossy().to_string(),
        source_plan_id: source_plan.id.clone(),
        source_prompt: source_plan.request.prompt.clone(),
        source_verdict: source_critique.verdict.clone(),
        source_score: source_critique.score,
        improved_run_dir: Some(improved_run_dir.to_string_lossy().to_string()),
        improved_plan_path: Some(improved_plan_path.to_string_lossy().to_string()),
        improved_plan_id: Some(improved_plan.id.clone()),
        improved_verdict: Some(improved_critique.verdict.clone()),
        improved_score: Some(improved_critique.score),
        score_delta: Some(score_delta),
        status,
        selected_recipes,
        skipped_gaps,
        artifacts,
        blockers: improved_critique.blockers.clone(),
        warnings: improved_critique.warnings.clone(),
        next_actions,
        agent_brief: format!(
            "Improved '{}' by adding [{}]. Score moved from {} ({}) to {} ({}).",
            source_plan.request.prompt,
            recipe_list,
            source_critique.score,
            source_critique.verdict,
            improved_critique.score,
            improved_critique.verdict
        ),
    }
}

fn build_compare_report(
    base_run: &Path,
    candidate_run: &Path,
    comparison_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<CompareReport> {
    let base = build_run_comparison_snapshot(base_run)?;
    let candidate = build_run_comparison_snapshot(candidate_run)?;
    let score_delta = i16::from(candidate.gameplay_score) - i16::from(base.gameplay_score);
    let added_recipes = sorted_difference(&candidate.recipes, &base.recipes);
    let removed_recipes = sorted_difference(&base.recipes, &candidate.recipes);
    let added_paths = sorted_difference(&candidate.created_paths, &base.created_paths);
    let removed_paths = sorted_difference(&base.created_paths, &candidate.created_paths);
    let added_generated_files =
        sorted_difference(&candidate.generated_files, &base.generated_files);
    let removed_generated_files =
        sorted_difference(&base.generated_files, &candidate.generated_files);

    let candidate_blocked = !candidate.blockers.is_empty() || candidate.bundle_ok == Some(false);
    let base_blocked = !base.blockers.is_empty() || base.bundle_ok == Some(false);
    let verdict = if candidate_blocked && !base_blocked {
        "baseSafer"
    } else if !candidate_blocked && (score_delta > 0 || base_blocked) {
        "candidateImproved"
    } else if !candidate_blocked && candidate.gameplay_verdict == "playableSlice" {
        "candidateReady"
    } else if score_delta < 0 {
        "baseStronger"
    } else {
        "noClearWinner"
    }
    .to_string();
    let status = if verdict == "candidateImproved" || verdict == "candidateReady" {
        "candidatePreferred"
    } else if verdict == "baseSafer" || verdict == "baseStronger" {
        "basePreferred"
    } else {
        "reviewNeeded"
    }
    .to_string();

    let mut blockers = Vec::new();
    if candidate_blocked {
        blockers.push("candidate run has blockers or bundle drift".into());
    }
    blockers.extend(
        candidate
            .blockers
            .iter()
            .map(|blocker| format!("candidate: {blocker}")),
    );
    let mut warnings = Vec::new();
    warnings.extend(
        base.warnings
            .iter()
            .map(|warning| format!("base: {warning}")),
    );
    warnings.extend(
        candidate
            .warnings
            .iter()
            .map(|warning| format!("candidate: {warning}")),
    );
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let mut next_actions = Vec::new();
    if status == "candidatePreferred" {
        next_actions.push(CoachAction {
            priority: 1,
            title: "Review candidate handoff".into(),
            command: Some(format!(
                "rs autopilot handoff {} --format json",
                candidate_run.to_string_lossy()
            )),
            reason: "The candidate is the stronger continuation; review its handoff before live mutation.".into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
        next_actions.push(CoachAction {
            priority: 2,
            title: "Verify candidate bundle".into(),
            command: Some(format!(
                "rs autopilot verify-bundle --run-dir {} --format json",
                candidate_run.to_string_lossy()
            )),
            reason: "Confirm the preferred run artifacts still match their bundle manifest.".into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
        next_actions.push(CoachAction {
            priority: 3,
            title: "Check live readiness".into(),
            command: Some("rs autopilot ready --timeout 90 --format json".into()),
            reason: "Live apply still requires a connected Studio session and compatible plugin."
                .into(),
            requires_live_studio: true,
            mutates_studio: false,
        });
    } else {
        next_actions.push(CoachAction {
            priority: 1,
            title: "Improve the baseline again".into(),
            command: Some(format!(
                "rs autopilot improve --run-dir {} --format json",
                base_run.to_string_lossy()
            )),
            reason: "The candidate is not clearly better, so keep iterating offline before apply."
                .into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
    }

    let agent_brief = format!(
        "Compared base '{}' score {} ({}) with candidate '{}' score {} ({}). Verdict: {}.",
        base.plan_id,
        base.gameplay_score,
        base.gameplay_verdict,
        candidate.plan_id,
        candidate.gameplay_score,
        candidate.gameplay_verdict,
        verdict
    );

    Ok(CompareReport {
        schema_version: "rs.autopilot.compare.v1".into(),
        generated_at: now_stamp(),
        comparison_path: comparison_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict,
        base,
        candidate,
        score_delta,
        added_recipes,
        removed_recipes,
        added_paths,
        removed_paths,
        added_generated_files,
        removed_generated_files,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn build_run_comparison_snapshot(run_dir: &Path) -> AppResult<RunComparisonSnapshot> {
    let plan_path = run_dir.join("plan.json");
    let plan = read_plan(&plan_path)?;
    let critique_path = run_dir.join("gameplay-critique.json");
    let critique =
        build_gameplay_critique_report(run_dir, &plan_path, &plan, &critique_path, None)?;
    let bundle_ok = if run_dir.join("bundle.json").exists() {
        Some(verify_bundle_report(&run_dir.join("bundle.json"), Some(run_dir))?.ok)
    } else {
        None
    };
    Ok(RunComparisonSnapshot {
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        operation_count: plan.operations.len(),
        operation_counts: operation_counts_for_plan(&plan),
        recipes: recipes_for_run(run_dir, &plan)?,
        created_paths: created_paths_for_plan(&plan),
        generated_files: generated_files_for_plan(&plan),
        gameplay_verdict: critique.verdict,
        gameplay_score: critique.score,
        certification_verdict: read_certification_verdict(run_dir)?,
        bundle_ok,
        blockers: critique.blockers,
        warnings: critique.warnings,
    })
}

fn read_certification_verdict(run_dir: &Path) -> AppResult<Option<String>> {
    let path = run_dir.join("certification.json");
    if !path.exists() {
        return Ok(None);
    }
    let value = read_json_file(&path)?;
    Ok(value
        .get("verdict")
        .and_then(Value::as_str)
        .map(str::to_string))
}

fn sorted_difference(left: &[String], right: &[String]) -> Vec<String> {
    let right = right.iter().map(String::as_str).collect::<BTreeSet<_>>();
    let mut difference = left
        .iter()
        .filter(|item| !right.contains(item.as_str()))
        .cloned()
        .collect::<Vec<_>>();
    difference.sort();
    difference.dedup();
    difference
}

fn build_iterate_report(
    port: u16,
    source_run_dir: &Path,
    session_dir: &Path,
    iteration_path: &Path,
    markdown_path: Option<&Path>,
    max_steps: usize,
    max_recipes: usize,
    smoke: Option<&str>,
) -> AppResult<IterateReport> {
    std::fs::create_dir_all(session_dir)?;
    let mut current_run_dir = source_run_dir.to_path_buf();
    let mut steps = Vec::new();
    let mut status = "maxStepsReached".to_string();
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();

    for order in 1..=max_steps {
        let current_plan_path = current_run_dir.join("plan.json");
        let current_plan = read_plan(&current_plan_path)?;
        let current_critique_path = current_run_dir.join("gameplay-critique.json");
        let current_critique_markdown_path = current_run_dir.join("gameplay-critique.md");
        let current_critique = build_gameplay_critique_report(
            &current_run_dir,
            &current_plan_path,
            &current_plan,
            &current_critique_path,
            Some(&current_critique_markdown_path),
        )?;
        write_json(current_critique_path, &current_critique)?;
        write_gameplay_critique_markdown(current_critique_markdown_path, &current_critique)?;
        warnings.extend(current_critique.warnings.clone());
        if current_critique.verdict == "playableSlice" {
            status = if order == 1 {
                "alreadyPlayable".into()
            } else {
                "readyToPlaytest".into()
            };
            steps.push(IterateStepReport {
                order,
                input_run_dir: current_run_dir.to_string_lossy().to_string(),
                input_verdict: current_critique.verdict,
                input_score: current_critique.score,
                candidate_run_dir: None,
                candidate_verdict: None,
                candidate_score: None,
                score_delta: None,
                selected_recipes: Vec::new(),
                skipped_gaps: Vec::new(),
                comparison_path: None,
                decision: "stopPlayable".into(),
                blockers: Vec::new(),
                warnings: Vec::new(),
            });
            break;
        }

        let current_recipes = recipes_for_run(&current_run_dir, &current_plan)?;
        let (selected_recipes, skipped_gaps) =
            select_improvement_recipes(&current_recipes, &current_critique.gaps, &[], max_recipes)?;
        if selected_recipes.is_empty() {
            status = "needsCustomPlan".into();
            blockers.push(
                "deterministic iteration could not select another recipe patch from critique gaps"
                    .into(),
            );
            steps.push(IterateStepReport {
                order,
                input_run_dir: current_run_dir.to_string_lossy().to_string(),
                input_verdict: current_critique.verdict,
                input_score: current_critique.score,
                candidate_run_dir: None,
                candidate_verdict: None,
                candidate_score: None,
                score_delta: None,
                selected_recipes,
                skipped_gaps,
                comparison_path: None,
                decision: "needsCustomPlan".into(),
                blockers: blockers.clone(),
                warnings: current_critique.warnings,
            });
            break;
        }

        let candidate_run_dir = session_dir.join(format!(
            "step-{order:02}-{}",
            selected_recipes
                .iter()
                .map(|patch| slug(&patch.recipe))
                .collect::<Vec<_>>()
                .join("-")
        ));
        let patch_prompt = format!(
            "{}; iterate gameplay with {}",
            current_plan.request.prompt,
            selected_recipes
                .iter()
                .map(|patch| patch.recipe.as_str())
                .collect::<Vec<_>>()
                .join(", ")
        );
        let compose_options = ComposeOptions {
            port,
            prompt: Some(patch_prompt),
            studio: current_plan.request.studio.clone(),
            scope: current_plan.request.scope.clone(),
            out: Some(candidate_run_dir.clone()),
            preset: None,
            recipes: selected_recipes
                .iter()
                .map(|patch| patch.recipe.clone())
                .collect(),
            from_manifest: None,
            smoke: smoke.map(str::to_string),
            json: false,
        };
        let (candidate_run_dir, candidate_plan, _preview) =
            write_compose_artifacts(&compose_options)?;
        let candidate_plan_path = candidate_run_dir.join("plan.json");
        let candidate_critique = write_full_offline_run_packet(
            &candidate_run_dir,
            &candidate_plan_path,
            &candidate_plan,
        )?;
        let comparison_path = candidate_run_dir.join("comparison.json");
        let comparison_markdown_path = candidate_run_dir.join("comparison.md");
        let comparison = build_compare_report(
            &current_run_dir,
            &candidate_run_dir,
            &comparison_path,
            Some(&comparison_markdown_path),
        )?;
        write_json(comparison_path.clone(), &comparison)?;
        write_compare_markdown(comparison_markdown_path, &comparison)?;
        let candidate_preferred = comparison.status == "candidatePreferred";
        let decision = if candidate_preferred {
            current_run_dir = candidate_run_dir.clone();
            if candidate_critique.verdict == "playableSlice" {
                status = "readyToPlaytest".into();
                "acceptedPlayable"
            } else {
                "acceptedContinue"
            }
        } else {
            status = "noImprovement".into();
            "rejectedCandidate"
        }
        .to_string();
        steps.push(IterateStepReport {
            order,
            input_run_dir: comparison.base.run_dir.clone(),
            input_verdict: comparison.base.gameplay_verdict.clone(),
            input_score: comparison.base.gameplay_score,
            candidate_run_dir: Some(candidate_run_dir.to_string_lossy().to_string()),
            candidate_verdict: Some(comparison.candidate.gameplay_verdict.clone()),
            candidate_score: Some(comparison.candidate.gameplay_score),
            score_delta: Some(comparison.score_delta),
            selected_recipes,
            skipped_gaps,
            comparison_path: Some(comparison_path.to_string_lossy().to_string()),
            decision: decision.clone(),
            blockers: comparison.blockers.clone(),
            warnings: comparison.warnings.clone(),
        });
        warnings.extend(comparison.warnings);
        blockers.extend(comparison.blockers);
        if decision == "acceptedPlayable" || decision == "rejectedCandidate" {
            break;
        }
    }

    let final_snapshot = build_run_comparison_snapshot(&current_run_dir)?;
    blockers.extend(final_snapshot.blockers.clone());
    warnings.extend(final_snapshot.warnings.clone());
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();
    if status == "maxStepsReached" && final_snapshot.gameplay_verdict == "playableSlice" {
        status = "readyToPlaytest".into();
    }

    let mut next_actions = Vec::new();
    if final_snapshot.gameplay_verdict == "playableSlice" && blockers.is_empty() {
        next_actions.push(CoachAction {
            priority: 1,
            title: "Review final candidate handoff".into(),
            command: Some(format!(
                "rs autopilot handoff {} --format json",
                current_run_dir.to_string_lossy()
            )),
            reason:
                "The iteration found a playable candidate; review its handoff before live mutation."
                    .into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
        next_actions.push(CoachAction {
            priority: 2,
            title: "Verify final candidate bundle".into(),
            command: Some(format!(
                "rs autopilot verify-bundle --run-dir {} --format json",
                current_run_dir.to_string_lossy()
            )),
            reason: "Confirm the selected candidate artifacts still match their bundle manifest."
                .into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
        next_actions.push(CoachAction {
            priority: 3,
            title: "Check live readiness".into(),
            command: Some("rs autopilot ready --timeout 90 --format json".into()),
            reason: "Live apply still requires a connected Studio session and compatible plugin."
                .into(),
            requires_live_studio: true,
            mutates_studio: false,
        });
    } else {
        next_actions.push(CoachAction {
            priority: 1,
            title: "Generate a custom planner packet".into(),
            command: Some(format!(
                "rs autopilot planner-pack --run-dir {} --format json",
                current_run_dir.to_string_lossy()
            )),
            reason:
                "Deterministic iteration did not reach a clean playable slice; ask a bounded AI planner for a custom patch."
                    .into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
    }

    let agent_brief = format!(
        "Iterated '{}' for {} step(s). Final run '{}' scored {} with verdict '{}'. Status: {}.",
        source_run_dir.to_string_lossy(),
        steps.len(),
        current_run_dir.to_string_lossy(),
        final_snapshot.gameplay_score,
        final_snapshot.gameplay_verdict,
        status
    );

    Ok(IterateReport {
        schema_version: "rs.autopilot.iterate.v1".into(),
        generated_at: now_stamp(),
        iteration_path: iteration_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        source_run_dir: source_run_dir.to_string_lossy().to_string(),
        session_dir: session_dir.to_string_lossy().to_string(),
        final_run_dir: current_run_dir.to_string_lossy().to_string(),
        status,
        max_steps,
        step_count: steps.len(),
        final_verdict: final_snapshot.gameplay_verdict,
        final_score: final_snapshot.gameplay_score,
        steps,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn default_iteration_dir(source_run_dir: &Path) -> PathBuf {
    let source_name = source_run_dir
        .file_name()
        .map(|name| name.to_string_lossy().to_string())
        .filter(|name| !name.trim().is_empty())
        .unwrap_or_else(|| "autopilot-run".into());
    source_run_dir.with_file_name(format!("{source_name}-iteration"))
}

fn build_sequence_report(
    run_dirs: &[PathBuf],
    sequence_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<SequenceReport> {
    let mut steps = Vec::new();
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    let mut all_recipes = Vec::new();
    let mut all_created_paths = Vec::new();
    let mut all_generated_files = Vec::new();

    for (index, run_dir) in run_dirs.iter().enumerate() {
        let snapshot = build_run_comparison_snapshot(run_dir)?;
        all_recipes.extend(snapshot.recipes.clone());
        all_created_paths.extend(snapshot.created_paths.clone());
        all_generated_files.extend(snapshot.generated_files.clone());
        if snapshot.bundle_ok == Some(false) {
            blockers.push(format!(
                "step {} bundle verification failed for {}",
                index + 1,
                run_dir.to_string_lossy()
            ));
        } else if snapshot.bundle_ok.is_none() {
            warnings.push(format!(
                "step {} has no bundle.json; run `rs autopilot bundle {}` before handoff",
                index + 1,
                run_dir.to_string_lossy()
            ));
        }
        warnings.extend(
            snapshot
                .blockers
                .iter()
                .map(|blocker| format!("step {} gameplay: {blocker}", index + 1)),
        );
        warnings.extend(
            snapshot
                .warnings
                .iter()
                .map(|warning| format!("step {}: {warning}", index + 1)),
        );
        let plan_path = run_dir.join("plan.json");
        let smoke_arg = read_plan(&plan_path)
            .map(|plan| apply_smoke_arg_for_plan(&plan))
            .unwrap_or_default();
        let apply_command = format!(
            "rs autopilot apply --plan {} --yes --rollback-on-error --validate{smoke_arg}",
            plan_path.to_string_lossy()
        );
        steps.push(SequenceStepReport {
            order: index + 1,
            run_dir: snapshot.run_dir,
            plan_path: snapshot.plan_path,
            plan_id: snapshot.plan_id,
            prompt: snapshot.prompt,
            operation_count: snapshot.operation_count,
            recipes: snapshot.recipes,
            gameplay_verdict: snapshot.gameplay_verdict,
            gameplay_score: snapshot.gameplay_score,
            certification_verdict: snapshot.certification_verdict,
            bundle_ok: snapshot.bundle_ok,
            apply_command,
            blockers: snapshot.blockers,
            warnings: snapshot.warnings,
        });
    }

    all_recipes.sort();
    all_recipes.dedup();
    all_created_paths.sort();
    all_created_paths.dedup();
    all_generated_files.sort();
    all_generated_files.dedup();
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let status = if blockers.is_empty() {
        "readyToReviewSequence"
    } else {
        "blocked"
    }
    .to_string();
    let mut next_actions = Vec::new();
    for step in &steps {
        next_actions.push(CoachAction {
            priority: step.order as u8,
            title: format!("Verify step {} bundle", step.order),
            command: Some(format!(
                "rs autopilot verify-bundle --run-dir {} --format json",
                step.run_dir
            )),
            reason: "Verify this run's artifacts before applying the sequence.".into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
    }
    next_actions.push(CoachAction {
        priority: (steps.len() + 1).min(u8::MAX as usize) as u8,
        title: "Check live readiness".into(),
        command: Some("rs autopilot ready --timeout 90 --format json".into()),
        reason: "The ordered sequence still requires a connected Studio session before mutation."
            .into(),
        requires_live_studio: true,
        mutates_studio: false,
    });
    for step in &steps {
        next_actions.push(CoachAction {
            priority: (steps.len() + 1 + step.order).min(u8::MAX as usize) as u8,
            title: format!("Apply sequence step {}", step.order),
            command: Some(step.apply_command.clone()),
            reason: "Apply sequence steps in order after readiness passes and the user approves."
                .into(),
            requires_live_studio: true,
            mutates_studio: true,
        });
    }

    let agent_brief = format!(
        "Sequence {} run(s) in order. Status: {}. Recipes: [{}].",
        steps.len(),
        status,
        all_recipes.join(", ")
    );
    Ok(SequenceReport {
        schema_version: "rs.autopilot.sequence.v1".into(),
        generated_at: now_stamp(),
        sequence_path: sequence_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        run_count: steps.len(),
        steps,
        recipes: all_recipes,
        created_paths: all_created_paths,
        generated_files: all_generated_files,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn build_playtest_plan_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    playtest_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<PlaytestPlanReport> {
    let explain = build_explain_report(plan_path, plan);
    let certification = read_memory_certification(run_dir)?;
    let recipes = recipes_for_run(run_dir, plan)?;
    let mut blockers = explain.blockers.clone();
    let mut warnings = explain.warnings.clone();
    if recipes.is_empty() {
        warnings.push(
            "no recipe evidence found; generated playtest falls back to generic plan checks".into(),
        );
    }
    if !run_dir.join("gameplay-critique.json").exists() {
        warnings.push(
            "gameplay-critique.json is missing; run critique before playtest planning".into(),
        );
    }
    let scenarios = build_playtest_scenarios(run_dir, plan, &recipes, certification.applied);
    let status = if !blockers.is_empty() {
        "blocked"
    } else if certification.applied == Some(true) {
        "readyToPlaytest"
    } else {
        "needsLiveApply"
    }
    .to_string();

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let mut next_actions = Vec::new();
    next_actions.push(CoachAction {
        priority: 1,
        title: "Check live Studio readiness".into(),
        command: Some("rs autopilot ready --timeout 90 --format json".into()),
        reason: "Playtest scenarios require a connected Studio session with the Autopilot plugin."
            .into(),
        requires_live_studio: true,
        mutates_studio: false,
    });
    if certification.applied != Some(true) {
        next_actions.push(CoachAction {
            priority: 2,
            title: "Apply before playtest".into(),
            command: Some(format!(
                "rs autopilot apply --plan {} --yes --rollback-on-error --validate",
                plan_path.to_string_lossy()
            )),
            reason:
                "The run has not recorded a successful apply, so live gameplay scenarios are not yet runnable."
                    .into(),
            requires_live_studio: true,
            mutates_studio: true,
        });
    }
    next_actions.push(CoachAction {
        priority: 7,
        title: "Refresh certification after playtest".into(),
        command: Some(format!(
            "rs autopilot certify {} --format json",
            run_dir.to_string_lossy()
        )),
        reason: "Record the post-playtest go/no-go state after live evidence exists.".into(),
        requires_live_studio: false,
        mutates_studio: false,
    });

    let agent_brief = format!(
        "Playtest '{}' with {} scenario(s). Status is '{}'. Run readiness and apply gates before manual or automated Studio checks.",
        plan.request.prompt,
        scenarios.len(),
        status
    );

    Ok(PlaytestPlanReport {
        schema_version: "rs.autopilot.playtest-plan.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        playtest_path: playtest_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        recipes,
        scenario_count: scenarios.len(),
        scenarios,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn build_evidence_kit_report(
    run_dir: &Path,
    kit_path: &Path,
    markdown_path: Option<&Path>,
    evidence_root: &Path,
    create_dirs: bool,
) -> AppResult<EvidenceKitReport> {
    let plan_path = run_dir.join("plan.json");
    let plan = read_plan(&plan_path)?;
    let playtest_plan_path = run_dir.join("playtest-plan.json");
    let playtest_markdown_path = run_dir.join("playtest-plan.md");
    let playtest_markdown = markdown_path
        .is_some()
        .then_some(playtest_markdown_path.as_path());
    let playtest = build_playtest_plan_report(
        run_dir,
        &plan_path,
        &plan,
        &playtest_plan_path,
        playtest_markdown,
    )?;
    write_json(playtest_plan_path.clone(), &playtest)?;
    if markdown_path.is_some() {
        write_playtest_plan_markdown(playtest_markdown_path, &playtest)?;
    }

    let folders = BTreeMap::from([
        (
            "screenshots".into(),
            evidence_root
                .join("screenshots")
                .to_string_lossy()
                .to_string(),
        ),
        (
            "logs".into(),
            evidence_root.join("logs").to_string_lossy().to_string(),
        ),
        (
            "notes".into(),
            evidence_root.join("notes").to_string_lossy().to_string(),
        ),
        (
            "exports".into(),
            evidence_root.join("exports").to_string_lossy().to_string(),
        ),
    ]);
    if create_dirs {
        for folder in folders.values() {
            std::fs::create_dir_all(folder)?;
        }
    }

    let requirements = build_evidence_requirements(&playtest, &folders);
    let record_commands = build_evidence_record_commands(run_dir, &playtest, &requirements);
    let certification = read_memory_certification(run_dir)?;
    let mut blockers = playtest.blockers.clone();
    let mut warnings = playtest.warnings.clone();
    if requirements.is_empty() {
        blockers.push("no playtest evidence requirements could be generated".into());
    }
    if certification.applied != Some(true) {
        warnings.push(
            "live apply proof is not recorded; collect evidence only after ready/apply succeeds"
                .into(),
        );
    }
    if !create_dirs {
        warnings
            .push("evidence directories were not created because --no-create-dirs was used".into());
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else if certification.applied == Some(true) {
        "readyToCollect"
    } else {
        "needsLiveApply"
    }
    .to_string();
    let mut next_actions = Vec::new();
    next_actions.push(coach_action(
        1,
        "Check live Studio readiness",
        Some("rs autopilot ready --timeout 90 --format json".into()),
        "Evidence collection starts only after the bridge and plugin are reachable.",
        true,
        false,
    ));
    if certification.applied != Some(true) {
        next_actions.push(coach_action(
            2,
            "Apply before collecting proof",
            Some(format!(
                "rs autopilot apply --plan {} --yes --rollback-on-error --validate",
                plan_path.to_string_lossy()
            )),
            "The evidence checklist proves live behavior after the approved plan is applied.",
            true,
            true,
        ));
    }
    if let Some(command) = record_commands.first() {
        next_actions.push(coach_action(
            6,
            "Record live playtest evidence",
            Some(command.clone()),
            "Use this after filling the evidence files or replacing placeholders with observed proof.",
            false,
            false,
        ));
    }
    next_actions.push(coach_action(
        7,
        "Refresh run judgment",
        Some(format!(
            "rs autopilot judge {} --format json",
            run_dir.to_string_lossy()
        )),
        "Judgment consumes the recorded playtest result together with certification, rollback, and bundle evidence.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);

    let agent_brief = format!(
        "Evidence kit for '{}' has {} requirement(s) across {} scenario(s). Fill the suggested files, then run record-playtest; do not claim demo readiness from this kit alone.",
        plan.request.prompt,
        requirements.len(),
        playtest.scenario_count
    );

    Ok(EvidenceKitReport {
        schema_version: "rs.autopilot.evidence-kit.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        playtest_plan_path: playtest_plan_path.to_string_lossy().to_string(),
        kit_path: kit_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        evidence_root: evidence_root.to_string_lossy().to_string(),
        status,
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        directories_created: create_dirs,
        folders,
        scenario_count: playtest.scenario_count,
        requirements,
        record_commands,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn build_evidence_requirements(
    playtest: &PlaytestPlanReport,
    folders: &BTreeMap<String, String>,
) -> Vec<EvidenceRequirement> {
    let mut requirements = Vec::new();
    for scenario in &playtest.scenarios {
        let expected_items = if scenario.expected_evidence.is_empty() {
            vec![format!("Observed result for {}", scenario.title)]
        } else {
            scenario.expected_evidence.clone()
        };
        for (index, expected) in expected_items.iter().enumerate() {
            let capture_type = classify_evidence_capture(expected);
            let suggested_path =
                suggested_evidence_path(folders, &scenario.id, index + 1, &capture_type);
            requirements.push(EvidenceRequirement {
                id: format!("{}-{:02}", scenario.id, index + 1),
                scenario_id: scenario.id.clone(),
                title: scenario.title.clone(),
                capture_type,
                expected: expected.clone(),
                record_argument: suggested_path.clone(),
                suggested_path,
            });
        }
    }
    requirements
}

fn classify_evidence_capture(expected: &str) -> String {
    let lower = expected.to_ascii_lowercase();
    if lower.contains("screenshot")
        || lower.contains("visible")
        || lower.contains("ui")
        || lower.contains("appears")
        || lower.contains("shows")
    {
        "screenshot".into()
    } else if lower.contains("log")
        || lower.contains("output")
        || lower.contains("console")
        || lower.contains("error")
    {
        "log".into()
    } else {
        "note".into()
    }
}

fn suggested_evidence_path(
    folders: &BTreeMap<String, String>,
    scenario_id: &str,
    index: usize,
    capture_type: &str,
) -> String {
    let (folder_key, extension) = match capture_type {
        "screenshot" => ("screenshots", "png"),
        "log" => ("logs", "txt"),
        _ => ("notes", "txt"),
    };
    let folder = folders
        .get(folder_key)
        .or_else(|| folders.get("notes"))
        .cloned()
        .unwrap_or_else(|| "evidence".into());
    PathBuf::from(folder)
        .join(format!("{}-{:02}.{extension}", slug(scenario_id), index))
        .to_string_lossy()
        .to_string()
}

fn build_evidence_record_commands(
    run_dir: &Path,
    playtest: &PlaytestPlanReport,
    requirements: &[EvidenceRequirement],
) -> Vec<String> {
    if requirements.is_empty() {
        return Vec::new();
    }
    let evidence_args = requirements
        .iter()
        .take(4)
        .map(|item| format!("--evidence {}", command_arg(&item.record_argument)))
        .collect::<Vec<_>>()
        .join(" ");
    let scenario_args = playtest
        .scenarios
        .iter()
        .map(|scenario| format!("--scenario {}=passed", command_arg(&scenario.id)))
        .collect::<Vec<_>>()
        .join(" ");
    vec![format!(
        "rs autopilot record-playtest {} --result passed {evidence_args} {scenario_args}",
        command_arg(run_dir.to_string_lossy().as_ref())
    )]
}

fn build_playtest_result_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    options: &RecordPlaytestOptions,
    result_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<PlaytestResultReport> {
    let result = normalize_playtest_result(&options.result)?;
    let scenario_results = parse_playtest_result_scenarios(&options.scenarios)?;
    let certification = read_memory_certification(run_dir)?;
    let live_apply_verified = certification.applied == Some(true);
    let playtest_plan_path = run_dir.join("playtest-plan.json");
    let evidence = options
        .evidence
        .iter()
        .map(|item| item.trim().to_string())
        .filter(|item| !item.is_empty())
        .collect::<Vec<_>>();
    let notes = options
        .notes
        .iter()
        .map(|item| item.trim().to_string())
        .filter(|item| !item.is_empty())
        .collect::<Vec<_>>();

    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if result == "passed" && evidence.is_empty() {
        blockers.push("passed playtest results require at least one --evidence item".into());
    }
    if result == "passed" && !live_apply_verified {
        blockers.push(
            "passed playtest results require certification.json to record applied=true".into(),
        );
    }
    if !playtest_plan_path.exists() {
        warnings.push(
            "playtest-plan.json is missing; this result is not tied to a generated checklist"
                .into(),
        );
    }
    if certification.ready_to_apply != Some(true) && certification.applied != Some(true) {
        warnings.push(
            "certification does not record readyToApply or applied; refresh certification before demo claims"
                .into(),
        );
    }
    if result != "passed" && evidence.is_empty() && notes.is_empty() {
        warnings.push(
            "recorded non-passing playtest result has no evidence or notes for the next agent"
                .into(),
        );
    }

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let accepted = blockers.is_empty();
    let production_proof = accepted && result == "passed" && live_apply_verified;
    let status = if !accepted {
        "blocked"
    } else {
        result.as_str()
    }
    .to_string();
    let next_actions =
        build_playtest_result_next_actions(run_dir, &result, accepted, live_apply_verified);
    let agent_brief = if production_proof {
        format!(
            "Live playtest evidence for '{}' is recorded as passed. Refresh judgment before any demo-ready claim.",
            plan.request.prompt
        )
    } else if result == "passed" {
        format!(
            "Playtest evidence for '{}' is blocked because live apply proof is incomplete.",
            plan.request.prompt
        )
    } else {
        format!(
            "Live playtest for '{}' is recorded as {}. Improve or investigate before a demo-ready claim.",
            plan.request.prompt, result
        )
    };

    Ok(PlaytestResultReport {
        schema_version: "rs.autopilot.playtest-result.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        playtest_plan_path: playtest_plan_path.to_string_lossy().to_string(),
        result_path: result_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        status,
        result,
        accepted,
        live_apply_verified,
        production_proof,
        evidence,
        notes,
        scenario_results,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn build_playtest_result_next_actions(
    run_dir: &Path,
    result: &str,
    accepted: bool,
    live_apply_verified: bool,
) -> Vec<CoachAction> {
    let run_text = run_dir.to_string_lossy();
    let mut actions = Vec::new();
    if !live_apply_verified {
        actions.push(coach_action(
            1,
            "Refresh certification after live apply",
            Some(format!("rs autopilot certify {run_text} --format json")),
            "A playtest pass only counts after certification records a successful apply.",
            false,
            false,
        ));
    }
    if accepted && result == "passed" {
        actions.push(coach_action(
            2,
            "Refresh run judgment",
            Some(format!("rs autopilot judge {run_text} --format json")),
            "Judgment combines live apply, rollback, bundle, gameplay, and playtest evidence.",
            false,
            false,
        ));
    } else if result != "passed" {
        actions.push(coach_action(
            2,
            "Plan repairs from failed playtest evidence",
            Some(format!("rs autopilot repair-plan {run_text} --format json")),
            "Non-passing playtest evidence should become a structured repair packet before the next patch run.",
            false,
            false,
        ));
    }
    actions.push(coach_action(
        9,
        "Record another playtest result",
        Some(format!(
            "rs autopilot record-playtest {run_text} --result passed --evidence <evidence>"
        )),
        "Use this only after running the live checklist and preserving observed evidence.",
        false,
        false,
    ));
    dedup_next_actions(&mut actions);
    actions
}

fn build_evidence_review_report(
    run_dir: &Path,
    review_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<EvidenceReviewReport> {
    let plan_path = run_dir.join("plan.json");
    let plan = read_plan(&plan_path)?;
    let playtest_plan_path = run_dir.join("playtest-plan.json");
    let playtest_result_path = run_dir.join("playtest-result.json");
    let evidence_kit_path = run_dir.join("evidence-kit.json");
    let repair_plan_path = run_dir.join("repair-plan.json");

    let scenarios = read_playtest_scenario_memory(&playtest_plan_path)?;
    let result = if playtest_result_path.exists() {
        Some(read_playtest_result_memory(&playtest_result_path)?)
    } else {
        None
    };
    let recipes = recipes_for_run(run_dir, &plan)?;

    let scenario_reviews = build_evidence_scenario_reviews(run_dir, &scenarios, result.as_ref());
    let observations = build_evidence_observations(
        &playtest_plan_path,
        &playtest_result_path,
        &evidence_kit_path,
        result.as_ref(),
    );
    let hypotheses = build_evidence_hypotheses(run_dir, &plan, result.as_ref(), &recipes);

    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if scenarios.is_empty() {
        warnings.push(
            "playtest-plan.json is missing or has no scenarios; run `rs autopilot playtest` first"
                .into(),
        );
    }
    if !evidence_kit_path.exists() {
        warnings.push(
            "evidence-kit.json is missing; run `rs autopilot evidence` to create suggested evidence paths"
                .into(),
        );
    }
    match &result {
        Some(result) => {
            blockers.extend(
                result
                    .blockers
                    .iter()
                    .map(|blocker| format!("playtest result: {blocker}")),
            );
            warnings.extend(
                result
                    .warnings
                    .iter()
                    .map(|warning| format!("playtest result: {warning}")),
            );
            if result.result.as_deref() == Some("passed") && result.production_proof != Some(true) {
                warnings.push(
                    "playtest passed but is not production proof until live apply evidence is verified"
                        .into(),
                );
            }
            if result
                .result
                .as_deref()
                .is_some_and(|value| value != "passed")
                && hypotheses.is_empty()
            {
                blockers
                    .push("non-passing playtest result has no actionable repair hypothesis".into());
            }
        }
        None => blockers.push(
            "playtest-result.json is missing; record live observations before reviewing evidence"
                .into(),
        ),
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let result_value = result.as_ref().and_then(|result| result.result.clone());
    let accepted = result.as_ref().and_then(|result| result.accepted);
    let production_proof = result.as_ref().and_then(|result| result.production_proof);
    let status = evidence_review_status(result.as_ref(), &blockers, &hypotheses);
    let claim_boundaries = build_evidence_claim_boundaries(result.as_ref());
    let safe_to_say = build_evidence_safe_to_say(&status, result.as_ref(), hypotheses.len());
    let do_not_say = build_evidence_do_not_say(result.as_ref());
    let next_actions = build_evidence_review_next_actions(run_dir, &status, result.as_ref());
    let agent_brief =
        build_evidence_review_agent_brief(&status, &plan.request.prompt, hypotheses.len());

    Ok(EvidenceReviewReport {
        schema_version: "rs.autopilot.evidence-review.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        playtest_plan_path: playtest_plan_path.to_string_lossy().to_string(),
        playtest_result_path: playtest_result_path.to_string_lossy().to_string(),
        evidence_kit_path: evidence_kit_path.to_string_lossy().to_string(),
        repair_plan_path: repair_plan_path.to_string_lossy().to_string(),
        review_path: review_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id,
        prompt: plan.request.prompt,
        status,
        result: result_value,
        accepted,
        production_proof,
        scenario_count: scenarios.len(),
        reviewed_scenario_count: scenario_reviews
            .iter()
            .filter(|scenario| scenario.result.is_some())
            .count(),
        observation_count: observations.len(),
        hypothesis_count: hypotheses.len(),
        scenarios: scenario_reviews,
        observations,
        hypotheses,
        claim_boundaries,
        safe_to_say,
        do_not_say,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn read_playtest_scenario_memory(path: &Path) -> AppResult<Vec<PlaytestScenarioMemory>> {
    if !path.exists() {
        return Ok(Vec::new());
    }
    let value = read_json_file(path)?;
    let mut scenarios = value
        .get("scenarios")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(|item| {
                    Some(PlaytestScenarioMemory {
                        id: string_field(item, "id")?,
                        title: string_field(item, "title").unwrap_or_else(|| {
                            string_field(item, "id").unwrap_or_else(|| "scenario".into())
                        }),
                        recipe: string_field(item, "recipe"),
                        expected_evidence: string_array_field(item, "expectedEvidence"),
                    })
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    scenarios.sort_by(|left, right| left.id.cmp(&right.id));
    Ok(scenarios)
}

fn build_evidence_scenario_reviews(
    run_dir: &Path,
    scenarios: &[PlaytestScenarioMemory],
    result: Option<&PlaytestResultMemory>,
) -> Vec<EvidenceScenarioReview> {
    let mut reviews = Vec::new();
    let mut result_by_id = BTreeMap::new();
    if let Some(result) = result {
        for scenario in &result.scenario_results {
            result_by_id.insert(scenario.id.clone(), scenario.result.clone());
        }
    }
    for scenario in scenarios {
        let scenario_result = result_by_id.get(&scenario.id).cloned();
        reviews.push(evidence_scenario_review(
            run_dir,
            scenario,
            scenario_result,
            result,
        ));
    }
    if let Some(result) = result {
        for scenario in &result.scenario_results {
            if !scenarios.iter().any(|item| item.id == scenario.id) {
                let memory = PlaytestScenarioMemory {
                    id: scenario.id.clone(),
                    title: format!("Recorded scenario {}", scenario.id),
                    recipe: None,
                    expected_evidence: Vec::new(),
                };
                reviews.push(evidence_scenario_review(
                    run_dir,
                    &memory,
                    Some(scenario.result.clone()),
                    Some(result),
                ));
            }
        }
    }
    reviews.sort_by(|left, right| left.id.cmp(&right.id));
    reviews
}

fn evidence_scenario_review(
    run_dir: &Path,
    scenario: &PlaytestScenarioMemory,
    scenario_result: Option<String>,
    result: Option<&PlaytestResultMemory>,
) -> EvidenceScenarioReview {
    let matched_evidence = result
        .map(|result| matched_evidence_for_scenario(&scenario.id, &result.evidence))
        .unwrap_or_default();
    let status = match scenario_result.as_deref() {
        Some("passed") => "passed",
        Some("failed") => "failed",
        Some("blocked") => "blocked",
        Some("inconclusive") => "inconclusive",
        Some(_) => "review",
        None => "unrecorded",
    }
    .to_string();
    let interpretation = match status.as_str() {
        "passed" => "Scenario has a recorded pass. Keep the evidence path with the run and refresh judgment before making demo claims.".into(),
        "failed" => "Scenario failed in live play evidence. Convert the observation into a repair plan before patching.".into(),
        "blocked" => "Scenario was blocked. Resolve the blocker or collect more specific evidence before claiming readiness.".into(),
        "inconclusive" => "Scenario evidence is inconclusive. Re-run the checklist or attach clearer notes/screenshots/logs.".into(),
        _ => "Scenario has no recorded result yet. Record live evidence before using it as proof.".into(),
    };
    let next_command = match status.as_str() {
        "passed" => Some(format!(
            "rs autopilot judge {} --format json",
            run_dir.to_string_lossy()
        )),
        "failed" | "blocked" => Some(format!(
            "rs autopilot repair-plan {} --format json",
            run_dir.to_string_lossy()
        )),
        _ => Some(format!(
            "rs autopilot record-playtest {} --result inconclusive --scenario {}=inconclusive --evidence <evidence>",
            run_dir.to_string_lossy(),
            command_arg(&scenario.id)
        )),
    };
    EvidenceScenarioReview {
        id: scenario.id.clone(),
        title: scenario.title.clone(),
        recipe: scenario.recipe.clone(),
        expected_evidence: scenario.expected_evidence.clone(),
        result: scenario_result,
        status,
        matched_evidence,
        interpretation,
        next_command,
    }
}

fn matched_evidence_for_scenario(scenario_id: &str, evidence: &[String]) -> Vec<String> {
    let needle = scenario_id.to_ascii_lowercase();
    let matches = evidence
        .iter()
        .filter(|item| item.to_ascii_lowercase().contains(&needle))
        .cloned()
        .collect::<Vec<_>>();
    if matches.is_empty() && evidence.len() <= 4 {
        evidence.to_vec()
    } else {
        matches
    }
}

fn build_evidence_observations(
    playtest_plan_path: &Path,
    playtest_result_path: &Path,
    evidence_kit_path: &Path,
    result: Option<&PlaytestResultMemory>,
) -> Vec<EvidenceObservation> {
    let mut observations = Vec::new();
    if !playtest_plan_path.exists() {
        observations.push(evidence_observation(
            observations.len() + 1,
            "playtest-plan",
            "warn",
            "No playtest checklist was found for these observations.",
            Vec::new(),
        ));
    }
    if !evidence_kit_path.exists() {
        observations.push(evidence_observation(
            observations.len() + 1,
            "evidence-kit",
            "warn",
            "No evidence kit was found, so suggested screenshot/log/note paths may be missing.",
            Vec::new(),
        ));
    }
    let Some(result) = result else {
        observations.push(evidence_observation(
            observations.len() + 1,
            "playtest-result",
            "blocker",
            "No playtest result has been recorded yet.",
            vec![playtest_result_path.to_string_lossy().to_string()],
        ));
        return observations;
    };

    if let Some(result_value) = &result.result {
        let severity = if result_value == "passed" {
            "info"
        } else {
            "blocker"
        };
        observations.push(evidence_observation(
            observations.len() + 1,
            "playtest-result",
            severity,
            &format!("Overall live playtest result is `{result_value}`."),
            result.evidence.clone(),
        ));
    }
    for scenario in &result.scenario_results {
        if scenario.result != "passed" {
            observations.push(evidence_observation(
                observations.len() + 1,
                "scenario-result",
                "blocker",
                &format!("Scenario `{}` recorded `{}`.", scenario.id, scenario.result),
                matched_evidence_for_scenario(&scenario.id, &result.evidence),
            ));
        }
    }
    for note in &result.notes {
        let severity = if evidence_text_sounds_blocking(note) {
            "blocker"
        } else {
            "info"
        };
        observations.push(evidence_observation(
            observations.len() + 1,
            "note",
            severity,
            note,
            Vec::new(),
        ));
    }
    for blocker in &result.blockers {
        observations.push(evidence_observation(
            observations.len() + 1,
            "playtest-result",
            "blocker",
            blocker,
            Vec::new(),
        ));
    }
    for warning in &result.warnings {
        observations.push(evidence_observation(
            observations.len() + 1,
            "playtest-result",
            "warn",
            warning,
            Vec::new(),
        ));
    }
    observations
}

fn evidence_observation(
    index: usize,
    source: &str,
    severity: &str,
    message: &str,
    evidence: Vec<String>,
) -> EvidenceObservation {
    EvidenceObservation {
        id: format!("observation-{index:02}"),
        source: source.into(),
        severity: severity.into(),
        message: message.into(),
        evidence,
    }
}

fn evidence_text_sounds_blocking(text: &str) -> bool {
    let lower = text.to_ascii_lowercase();
    [
        "failed", "error", "blocked", "not ", "missing", "stuck", "no ", "did not", "doesn't",
        "cannot", "can't",
    ]
    .iter()
    .any(|needle| lower.contains(needle))
}

fn build_evidence_hypotheses(
    run_dir: &Path,
    plan: &AutopilotPlan,
    result: Option<&PlaytestResultMemory>,
    recipes: &[String],
) -> Vec<EvidenceHypothesis> {
    let Some(result) = result else {
        return Vec::new();
    };
    if result.result.as_deref() == Some("passed") {
        return Vec::new();
    }
    build_repair_incidents(run_dir, plan, result, recipes)
        .into_iter()
        .map(|incident| EvidenceHypothesis {
            id: incident.id,
            category: incident.category,
            confidence: if incident.requires_custom_plan {
                "medium".into()
            } else {
                "high".into()
            },
            summary: incident.summary,
            suggested_recipes: incident.suggested_recipes,
            commands: incident.commands,
        })
        .collect()
}

fn evidence_review_status(
    result: Option<&PlaytestResultMemory>,
    blockers: &[String],
    hypotheses: &[EvidenceHypothesis],
) -> String {
    if result.is_none() {
        "needsPlaytestResult"
    } else if !blockers.is_empty() {
        "blocked"
    } else {
        let result = result.expect("checked above");
        match result.result.as_deref() {
            Some("passed") if result.production_proof == Some(true) => "verified",
            Some("passed") => "needsLiveProof",
            Some("failed") | Some("blocked") if !hypotheses.is_empty() => "readyForRepair",
            Some("failed") | Some("blocked") => "needsRepairTriage",
            Some("inconclusive") => "needsMoreEvidence",
            _ => "needsMoreEvidence",
        }
    }
    .into()
}

fn build_evidence_claim_boundaries(result: Option<&PlaytestResultMemory>) -> Vec<String> {
    let mut boundaries = vec![
        "Do not claim a live playtest passed unless playtest-result.json is accepted and records result=passed.".into(),
        "Do not claim production readiness unless judgment, rollback, bundle, apply, and playtest proof all agree.".into(),
        "Use failed or blocked evidence as repair input, not as permission to mutate Studio.".into(),
    ];
    if result.and_then(|result| result.production_proof) != Some(true) {
        boundaries.push(
            "Recorded evidence is not production proof yet; keep user-facing claims limited to what the artifact says.".into(),
        );
    }
    boundaries
}

fn build_evidence_safe_to_say(
    status: &str,
    result: Option<&PlaytestResultMemory>,
    hypothesis_count: usize,
) -> Vec<String> {
    match status {
        "verified" => vec![
            "Live playtest evidence is recorded as passing for this run.".into(),
            "Refresh judgment or health before making a final demo-ready statement.".into(),
        ],
        "readyForRepair" => vec![format!(
            "Live evidence found {} repair hypothesis(es) for the next patch.",
            hypothesis_count
        )],
        "needsLiveProof" => vec![
            "A playtest pass was recorded, but it is not production proof until live apply evidence is verified.".into(),
        ],
        "needsPlaytestResult" => vec![
            "The run has no recorded live playtest result yet.".into(),
        ],
        _ => vec![format!(
            "Evidence review status is `{status}` with result `{}`.",
            result
                .and_then(|result| result.result.as_deref())
                .unwrap_or("missing")
        )],
    }
}

fn build_evidence_do_not_say(result: Option<&PlaytestResultMemory>) -> Vec<String> {
    let mut claims = Vec::new();
    if result.is_none() {
        claims.push("Do not say the generated game was playtested.".into());
    }
    if result.and_then(|result| result.production_proof) != Some(true) {
        claims.push(
            "Do not say the run is production-ready or demo-ready from this evidence alone.".into(),
        );
    }
    if result
        .and_then(|result| result.result.as_deref())
        .is_some_and(|value| value != "passed")
    {
        claims.push(
            "Do not say live gameplay passed; report the failed or blocked evidence plainly."
                .into(),
        );
    }
    claims
}

fn build_evidence_review_next_actions(
    run_dir: &Path,
    status: &str,
    result: Option<&PlaytestResultMemory>,
) -> Vec<CoachAction> {
    let run_text = run_dir.to_string_lossy();
    let mut actions = Vec::new();
    match status {
        "needsPlaytestResult" => actions.push(coach_action(
            1,
            "Record live playtest evidence",
            Some(format!(
                "rs autopilot record-playtest {run_text} --result failed --evidence <evidence>"
            )),
            "Evidence review needs a concrete playtest-result.json before it can diagnose outcomes.",
            false,
            false,
        )),
        "readyForRepair" | "needsRepairTriage" | "blocked"
            if result
                .and_then(|result| result.result.as_deref())
                .is_some_and(|value| value != "passed") =>
        {
            actions.push(coach_action(
                1,
                "Plan repairs from evidence",
                Some(format!("rs autopilot repair-plan {run_text} --format json")),
                "Turn the failed or blocked live evidence into a structured repair packet.",
                false,
                false,
            ));
            actions.push(coach_action(
                2,
                "Prepare AI planner context",
                Some(format!(
                    "rs autopilot planner-pack \"Repair live playtest evidence\" --run-dir {run_text} --format json"
                )),
                "Use evidence-review and repair-plan context before asking a model for a strict patch plan.",
                false,
                false,
            ));
        }
        "needsMoreEvidence" => actions.push(coach_action(
            1,
            "Collect clearer evidence",
            Some(format!("rs autopilot evidence {run_text} --format json")),
            "The current result is inconclusive; refresh the evidence kit and record clearer observations.",
            false,
            false,
        )),
        "needsLiveProof" => actions.push(coach_action(
            1,
            "Refresh certification after live apply",
            Some(format!("rs autopilot certify {run_text} --format json")),
            "The pass cannot become production proof until apply evidence is present and certified.",
            false,
            false,
        )),
        "verified" => {
            actions.push(coach_action(
                1,
                "Refresh judgment",
                Some(format!("rs autopilot judge {run_text} --format json")),
                "Convert accepted live evidence into the run readiness verdict.",
                false,
                false,
            ));
            actions.push(coach_action(
                2,
                "Check applied health",
                Some(format!("rs autopilot health {run_text} --format json")),
                "Health still requires apply, validation, smoke, rollback, proof, and playtest evidence together.",
                false,
                false,
            ));
        }
        _ => {}
    }
    actions.push(coach_action(
        9,
        "Refresh evidence review",
        Some(format!(
            "rs autopilot evidence-review {run_text} --format json"
        )),
        "Regenerate after new evidence, repair plans, apply proof, or judgment changes.",
        false,
        false,
    ));
    dedup_next_actions(&mut actions);
    actions
}

fn build_evidence_review_agent_brief(
    status: &str,
    prompt: &str,
    hypothesis_count: usize,
) -> String {
    match status {
        "verified" => format!(
            "Live evidence for '{prompt}' is accepted and proof-bearing. Refresh judgment/health before a final claim."
        ),
        "readyForRepair" => format!(
            "Live evidence for '{prompt}' produced {hypothesis_count} repair hypothesis(es). Create or refresh repair-plan before patching."
        ),
        "needsLiveProof" => format!(
            "Evidence for '{prompt}' recorded a pass, but live apply proof is incomplete."
        ),
        "needsPlaytestResult" => {
            format!("'{prompt}' needs recorded playtest evidence before diagnosis.")
        }
        _ => format!("Evidence review for '{prompt}' is {status}; follow next actions in order."),
    }
}

fn normalize_playtest_result(value: &str) -> AppResult<String> {
    let normalized = value.trim().to_ascii_lowercase();
    match normalized.as_str() {
        "pass" | "passed" | "ok" | "success" | "successful" => Ok("passed".into()),
        "fail" | "failed" | "failure" => Ok("failed".into()),
        "block" | "blocked" => Ok("blocked".into()),
        "inconclusive" | "unknown" | "mixed" => Ok("inconclusive".into()),
        other => Err(AppError::Other(format!(
            "unsupported playtest result '{other}'; use passed, failed, blocked, or inconclusive"
        ))),
    }
}

fn parse_playtest_result_scenarios(items: &[String]) -> AppResult<Vec<PlaytestResultScenario>> {
    let mut results = Vec::new();
    for item in items {
        let (id, result) = item.split_once('=').ok_or_else(|| {
            AppError::Other(format!(
                "scenario result '{item}' must use the form scenario-id=result"
            ))
        })?;
        let id = id.trim();
        if id.is_empty() {
            return Err(AppError::Other("scenario result id cannot be empty".into()));
        }
        results.push(PlaytestResultScenario {
            id: id.to_string(),
            result: normalize_playtest_result(result)?,
        });
    }
    results.sort_by(|left, right| left.id.cmp(&right.id));
    results.dedup_by(|left, right| left.id == right.id);
    Ok(results)
}

fn build_health_report(
    run_dir: &Path,
    health_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<HealthReport> {
    let mandatory_smoke_suites = vec!["regression".to_string()];
    let plan_path = run_dir.join("plan.json");
    let apply_path = run_dir.join("apply.json");
    let validation_after_path = run_dir.join("validation-after.json");
    let smoke_path = run_dir.join("smoke-regression.json");
    let proof_path = run_dir.join("proof.json");
    let proof_markdown_path = run_dir.join("proof.md");
    let judgment_path = run_dir.join("judgment.json");
    let judgment_markdown_path = run_dir.join("judgment.md");
    let rollback_path = run_dir.join("rollback.json");
    let rollback_markdown_path = run_dir.join("rollback.md");
    let playtest_result_path = run_dir.join("playtest-result.json");

    let mut artifacts = BTreeMap::from([
        ("health".into(), health_path.to_string_lossy().to_string()),
        ("runDir".into(), run_dir.to_string_lossy().to_string()),
        ("plan".into(), plan_path.to_string_lossy().to_string()),
        ("apply".into(), apply_path.to_string_lossy().to_string()),
        (
            "validationAfter".into(),
            validation_after_path.to_string_lossy().to_string(),
        ),
        (
            "smokeRegression".into(),
            smoke_path.to_string_lossy().to_string(),
        ),
        ("proof".into(), proof_path.to_string_lossy().to_string()),
        (
            "judgment".into(),
            judgment_path.to_string_lossy().to_string(),
        ),
        (
            "rollback".into(),
            rollback_path.to_string_lossy().to_string(),
        ),
        (
            "playtestResult".into(),
            playtest_result_path.to_string_lossy().to_string(),
        ),
    ]);
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "healthMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    let mut checks = Vec::new();
    checks.push(health_check(
        "run-dir",
        "Run Directory",
        if run_dir.exists() { "pass" } else { "fail" },
        if run_dir.exists() {
            "run directory exists".into()
        } else {
            format!(
                "run directory does not exist: {}",
                run_dir.to_string_lossy()
            )
        },
        Some(run_dir.to_string_lossy().to_string()),
        (!run_dir.exists())
            .then(|| "rs autopilot start \"<creator request>\" --format json".into()),
    ));

    checks.push(health_check(
        "plan",
        "Plan",
        if plan_path.exists() { "pass" } else { "fail" },
        if plan_path.exists() {
            "plan.json exists".into()
        } else {
            "plan.json is missing".into()
        },
        Some(plan_path.to_string_lossy().to_string()),
        (!plan_path.exists()).then(|| {
            format!(
                "rs autopilot kickoff \"<creator request>\" --out {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )
        }),
    ));

    let apply_value = read_json_if_exists(&apply_path)?;
    let apply_status = apply_value
        .as_ref()
        .and_then(|value| string_field(value, "status"));
    let apply_refused = apply_value
        .as_ref()
        .and_then(|value| value.get("refused"))
        .and_then(Value::as_u64)
        .unwrap_or(0);
    let apply_error = apply_value
        .as_ref()
        .and_then(|value| string_field(value, "error"))
        .filter(|value| !value.trim().is_empty());
    let apply_ok =
        apply_status.as_deref() == Some("applied") && apply_refused == 0 && apply_error.is_none();
    checks.push(health_check(
        "apply",
        "Apply Result",
        if apply_ok {
            "pass"
        } else if apply_value.is_some() {
            "fail"
        } else {
            "missing"
        },
        if apply_value.is_some() {
            format!(
                "apply status={}, refused={}, error={}",
                apply_status.as_deref().unwrap_or("<missing>"),
                apply_refused,
                apply_error.as_deref().unwrap_or("<none>")
            )
        } else {
            "apply.json is missing".into()
        },
        Some(apply_path.to_string_lossy().to_string()),
        (!apply_ok).then(|| {
            format!(
                "rs autopilot apply --plan {} --yes --rollback-on-error --validate --smoke regression --format json",
                command_arg(plan_path.to_string_lossy().as_ref())
            )
        }),
    ));

    let validation_value = apply_value
        .as_ref()
        .and_then(|value| value.get("validationAfter"))
        .filter(|value| !value.is_null())
        .cloned()
        .or_else(|| read_json_if_exists(&validation_after_path).ok().flatten());
    let validation_failures = validation_value
        .as_ref()
        .and_then(|value| value.get("summary"))
        .and_then(|summary| summary.get("fail"))
        .and_then(Value::as_u64);
    let validation_ok = validation_failures == Some(0);
    checks.push(health_check(
        "validation-after",
        "Validation After Apply",
        if validation_ok {
            "pass"
        } else if validation_value.is_some() {
            "fail"
        } else {
            "missing"
        },
        if let Some(failures) = validation_failures {
            format!("validation failures after apply: {failures}")
        } else {
            "validation-after evidence is missing".into()
        },
        Some(validation_after_path.to_string_lossy().to_string()),
        (!validation_ok).then(|| {
            format!(
                "rs autopilot apply --plan {} --yes --rollback-on-error --validate --smoke regression --format json",
                command_arg(plan_path.to_string_lossy().as_ref())
            )
        }),
    ));

    let smoke = find_health_smoke_evidence(run_dir, apply_value.as_ref(), "regression")?;
    checks.push(health_check(
        "smoke-regression",
        "Mandatory Regression Smoke",
        smoke
            .as_ref()
            .map(|(_, ok, _)| if *ok { "pass" } else { "fail" })
            .unwrap_or("missing"),
        smoke
            .as_ref()
            .map(|(artifact, ok, summary)| {
                format!(
                    "regression smoke {} from {} ({summary})",
                    if *ok { "passed" } else { "failed" },
                    artifact
                )
            })
            .unwrap_or_else(|| "regression smoke evidence is missing".into()),
        smoke
            .as_ref()
            .map(|(artifact, _, _)| artifact.clone())
            .or_else(|| Some(smoke_path.to_string_lossy().to_string())),
        smoke.as_ref().is_none_or(|(_, ok, _)| !*ok).then(|| {
            let studio_arg = apply_value
                .as_ref()
                .and_then(|value| string_field(value, "studio"))
                .map(|studio| format!(" --studio {}", command_arg(&studio)))
                .unwrap_or_default();
            format!(
                "rs smoke regression{studio_arg} --out {} --upload-mock",
                command_arg(smoke_path.to_string_lossy().as_ref())
            )
        }),
    ));

    let mut proof = None;
    let mut judgment = None;
    let mut rollback = None;
    if run_dir.exists() {
        let proof_report = build_proof_report(run_dir, &proof_path, Some(&proof_markdown_path))?;
        write_json(proof_path.clone(), &proof_report)?;
        write_proof_markdown(proof_markdown_path.clone(), &proof_report)?;
        proof = Some(proof_report);

        if plan_path.exists() {
            let judgment_report =
                build_judgment_report(run_dir, &judgment_path, Some(&judgment_markdown_path))?;
            write_json(judgment_path.clone(), &judgment_report)?;
            write_judgment_markdown(judgment_markdown_path.clone(), &judgment_report)?;
            judgment = Some(judgment_report);
        }

        let rollback_report =
            build_rollback_report(run_dir, &rollback_path, Some(&rollback_markdown_path))?;
        write_json(rollback_path.clone(), &rollback_report)?;
        write_rollback_markdown(rollback_markdown_path.clone(), &rollback_report)?;
        rollback = Some(rollback_report);
    }

    let rollback_ok = rollback
        .as_ref()
        .is_some_and(|report| report.rollback_artifact_exists);
    checks.push(health_check(
        "rollback-artifact",
        "Rollback Artifact",
        if rollback_ok {
            "pass"
        } else if rollback.as_ref().is_some_and(|report| report.apply_exists) {
            "fail"
        } else {
            "missing"
        },
        rollback
            .as_ref()
            .map(|report| {
                format!(
                    "rollback status={}, artifactExists={}, automaticRestore={}",
                    report.status,
                    report.rollback_artifact_exists,
                    report.automatic_restore_available
                )
            })
            .unwrap_or_else(|| "rollback evidence is missing".into()),
        Some(rollback_path.to_string_lossy().to_string()),
        (!rollback_ok).then(|| {
            format!(
                "rs autopilot apply --plan {} --yes --rollback-on-error --validate --smoke regression --format json",
                command_arg(plan_path.to_string_lossy().as_ref())
            )
        }),
    ));

    let playtest = read_memory_playtest_result(run_dir)?;
    let playtest_ok = playtest.production_proof == Some(true);
    checks.push(health_check(
        "playtest-result",
        "Live Playtest Result",
        if playtest_ok {
            "pass"
        } else if playtest.exists {
            "fail"
        } else {
            "missing"
        },
        if playtest.exists {
            format!(
                "result={:?}, accepted={:?}, productionProof={:?}, evidenceCount={}",
                playtest.result,
                playtest.accepted,
                playtest.production_proof,
                playtest.evidence_count
            )
        } else {
            "playtest-result.json is missing".into()
        },
        Some(playtest_result_path.to_string_lossy().to_string()),
        (!playtest_ok).then(|| {
            format!(
                "rs autopilot record-playtest {} --result passed --evidence <evidence>",
                command_arg(run_dir.to_string_lossy().as_ref())
            )
        }),
    ));

    let proof_ok = proof.as_ref().is_some_and(|report| report.production_ready);
    checks.push(health_check(
        "proof-ledger",
        "Proof Ledger",
        if proof_ok {
            "pass"
        } else if proof
            .as_ref()
            .is_some_and(|report| !report.blockers.is_empty())
        {
            "fail"
        } else {
            "pending"
        },
        proof
            .as_ref()
            .map(|report| {
                format!(
                    "proof status={}, productionReady={}, missingProof={}",
                    report.status,
                    report.production_ready,
                    report.missing_proof.len()
                )
            })
            .unwrap_or_else(|| "proof ledger was not generated".into()),
        Some(proof_path.to_string_lossy().to_string()),
        (!proof_ok).then(|| {
            format!(
                "rs autopilot proof {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )
        }),
    ));

    if let Some(rollback) = &rollback {
        if rollback.rollback_artifact_exists && !rollback.automatic_restore_available {
            checks.push(health_check(
                "rollback-restore",
                "Automatic Rollback Restore",
                "warn",
                "rollback artifact exists, but automatic restore needs manual review for this scope"
                    .into(),
                Some(rollback.rollback_path.clone()),
                Some(format!(
                    "rs autopilot rollback {} --format json",
                    command_arg(run_dir.to_string_lossy().as_ref())
                )),
            ));
        }
    }

    let mut blockers = Vec::new();
    for check in &checks {
        if matches!(check.status.as_str(), "fail" | "missing" | "pending") {
            blockers.push(format!("{}: {}", check.id, check.summary));
        }
    }
    let mut warnings = Vec::new();
    warnings.extend(
        checks
            .iter()
            .filter(|check| check.status == "warn")
            .map(|check| format!("{}: {}", check.id, check.summary)),
    );
    if let Some(proof) = &proof {
        warnings.extend(proof.warnings.clone());
    }
    if let Some(judgment) = &judgment {
        warnings.extend(judgment.warnings.clone());
    }
    if let Some(rollback) = &rollback {
        warnings.extend(rollback.warnings.clone());
    }
    warnings.extend(playtest.warnings);
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let applied_and_healthy = blockers.is_empty()
        && checks
            .iter()
            .filter(|check| check.status != "warn")
            .all(|check| check.status == "pass");
    let status = if applied_and_healthy {
        "appliedAndHealthy"
    } else if !run_dir.exists() || !plan_path.exists() {
        "blocked"
    } else if !apply_ok {
        "needsApply"
    } else {
        "needsHealthProof"
    }
    .to_string();
    let verdict = match status.as_str() {
        "appliedAndHealthy" => "healthy",
        "needsApply" => "notApplied",
        "blocked" => "blocked",
        _ => "missingHealthProof",
    }
    .to_string();

    let mut safe_to_say = Vec::new();
    if apply_ok {
        safe_to_say.push(
            "The run has an apply.json recorded as applied with no refused operations.".into(),
        );
    }
    if applied_and_healthy {
        safe_to_say.push("The run is applied-and-healthy: apply, validation, regression smoke, rollback, playtest, and proof all pass.".into());
    }
    if let Some(proof) = &proof {
        safe_to_say.extend(proof.claim_ready.clone());
    }
    safe_to_say.sort();
    safe_to_say.dedup();

    let mut do_not_say = vec![
        "The run is applied-and-healthy unless health.status is appliedAndHealthy.".into(),
        "Regression smoke passed unless the smoke-regression health check passes.".into(),
        "Live playtest proof exists unless the playtest-result health check passes.".into(),
    ];
    if let Some(proof) = &proof {
        do_not_say.extend(proof.do_not_claim.clone());
    }
    do_not_say.sort();
    do_not_say.dedup();

    let mut next_actions = Vec::new();
    for check in checks
        .iter()
        .filter(|check| check.status != "pass" && check.status != "warn")
    {
        if let Some(command) = &check.next_command {
            next_actions.push(coach_action(
                3,
                &format!("Resolve {}", check.title),
                Some(command.clone()),
                &check.summary,
                command.contains(" ready")
                    || command.contains(" apply")
                    || command.contains(" smoke"),
                command.contains(" apply"),
            ));
        }
    }
    next_actions.push(coach_action(
        9,
        "Refresh health gate",
        Some(format!(
            "rs autopilot health {} --format json",
            command_arg(run_dir.to_string_lossy().as_ref())
        )),
        "Regenerate health.json after apply, validation, smoke, rollback, proof, or playtest evidence changes.",
        false,
        false,
    ));
    dedup_next_actions(&mut next_actions);

    let agent_brief = if applied_and_healthy {
        "Health gate passes. The AI may call this run applied-and-healthy while citing health.json, proof.json, rollback.json, and playtest-result.json.".into()
    } else if apply_ok {
        "Health gate does not pass yet. The run applied, but the AI must collect missing validation, regression smoke, rollback, proof, or playtest evidence before calling it healthy.".into()
    } else {
        "Health gate is blocked before or at apply. Do not claim live mutation or health until apply and all health checks pass.".into()
    };

    Ok(HealthReport {
        schema_version: "rs.autopilot.health.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        health_path: health_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        status,
        verdict,
        applied_and_healthy,
        mandatory_smoke_suites,
        checks,
        artifacts,
        blockers,
        warnings,
        safe_to_say,
        do_not_say,
        next_actions,
        agent_brief,
    })
}

fn health_check(
    id: &str,
    title: &str,
    status: &str,
    summary: String,
    artifact: Option<String>,
    next_command: Option<String>,
) -> HealthCheck {
    HealthCheck {
        id: id.into(),
        title: title.into(),
        status: status.into(),
        summary,
        artifact,
        next_command,
    }
}

fn find_health_smoke_evidence(
    run_dir: &Path,
    apply: Option<&Value>,
    mandatory_suite: &str,
) -> AppResult<Option<(String, bool, String)>> {
    if let Some(smoke) = apply.and_then(|value| value.get("smoke")) {
        let suite = smoke.get("suite").and_then(Value::as_str).unwrap_or("");
        if suite == mandatory_suite {
            let ok = smoke.get("ok").and_then(Value::as_bool).unwrap_or(false);
            let artifact = smoke
                .get("artifact")
                .and_then(Value::as_str)
                .map(str::to_string)
                .unwrap_or_else(|| {
                    run_dir
                        .join("smoke-regression.json")
                        .to_string_lossy()
                        .to_string()
                });
            let summary = smoke
                .get("error")
                .and_then(Value::as_str)
                .filter(|value| !value.trim().is_empty())
                .map(str::to_string)
                .unwrap_or_else(|| "apply smoke field".into());
            return Ok(Some((artifact, ok, summary)));
        }
    }

    let canonical = run_dir.join("smoke-regression.json");
    if canonical.exists() {
        return smoke_report_from_path(&canonical);
    }
    if run_dir.exists() {
        for entry in std::fs::read_dir(run_dir)? {
            let entry = entry?;
            let path = entry.path();
            let Some(name) = path.file_name().and_then(|name| name.to_str()) else {
                continue;
            };
            if name.starts_with("smoke-regression-") && name.ends_with(".json") {
                if let Some(report) = smoke_report_from_path(&path)? {
                    return Ok(Some(report));
                }
            }
        }
    }
    Ok(None)
}

fn smoke_report_from_path(path: &Path) -> AppResult<Option<(String, bool, String)>> {
    let value = read_json_file(path)?;
    let ok = value.get("ok").and_then(Value::as_bool).unwrap_or(false);
    let step_count = value
        .get("steps")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0);
    let failed = value
        .get("steps")
        .and_then(Value::as_array)
        .map(|steps| {
            steps
                .iter()
                .filter(|step| step.get("ok").and_then(Value::as_bool) == Some(false))
                .count()
        })
        .unwrap_or(0);
    Ok(Some((
        path.to_string_lossy().to_string(),
        ok,
        format!("{step_count} step(s), {failed} failed"),
    )))
}

fn build_repair_plan_report(
    run_dir: &Path,
    repair_plan_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<RepairPlanReport> {
    let plan_path = run_dir.join("plan.json");
    let plan = read_plan(&plan_path)?;
    let playtest_result_path = run_dir.join("playtest-result.json");
    let playtest = if playtest_result_path.exists() {
        Some(read_playtest_result_memory(&playtest_result_path)?)
    } else {
        None
    };
    let mut blockers = Vec::new();
    let mut warnings = Vec::new();
    if !playtest_result_path.exists() {
        blockers.push(
            "playtest-result.json is missing; record live evidence before repair planning".into(),
        );
    }
    if !run_dir.join("playtest-plan.json").exists() {
        warnings
            .push("playtest-plan.json is missing; repair plan has less scenario context".into());
    }
    let current_recipes = recipes_for_run(run_dir, &plan)?;
    let incidents = playtest
        .as_ref()
        .map(|result| build_repair_incidents(run_dir, &plan, result, &current_recipes))
        .unwrap_or_default();
    let result = playtest.as_ref().and_then(|result| result.result.clone());
    let has_passing_proof = playtest
        .as_ref()
        .is_some_and(|result| result.production_proof == Some(true));
    let has_failed_result = playtest.as_ref().is_some_and(|result| {
        result.result.as_deref() != Some("passed") || result.accepted != Some(true)
    });
    if let Some(result) = &playtest {
        blockers.extend(result.blockers.iter().cloned());
        warnings.extend(result.warnings.iter().cloned());
        if result.result.as_deref() == Some("passed") && result.accepted == Some(true) {
            warnings.push("playtest already passed; repair planning is informational only".into());
        }
    }
    if has_failed_result && incidents.is_empty() {
        blockers.push(
            "playtest result is non-passing but no repair incidents could be inferred".into(),
        );
    }

    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() && playtest.is_none() {
        "needsPlaytestResult"
    } else if !blockers.is_empty() {
        "blocked"
    } else if has_passing_proof {
        "noRepairNeeded"
    } else {
        "needsRepair"
    }
    .to_string();
    let planner_prompt = build_repair_planner_prompt(&plan, playtest.as_ref(), &incidents);
    let next_actions = build_repair_plan_next_actions(run_dir, &status, !incidents.is_empty());
    let agent_brief = build_repair_plan_agent_brief(&status, &plan.request.prompt, incidents.len());

    Ok(RepairPlanReport {
        schema_version: "rs.autopilot.repair-plan.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        playtest_result_path: playtest_result_path.to_string_lossy().to_string(),
        repair_plan_path: repair_plan_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id,
        prompt: plan.request.prompt,
        status,
        result,
        incident_count: incidents.len(),
        incidents,
        planner_prompt,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn read_playtest_result_memory(path: &Path) -> AppResult<PlaytestResultMemory> {
    let value = read_json_file(path)?;
    let scenario_results = value
        .get("scenarioResults")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(|item| {
                    Some(PlaytestResultScenario {
                        id: item.get("id")?.as_str()?.to_string(),
                        result: item.get("result")?.as_str()?.to_string(),
                    })
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    Ok(PlaytestResultMemory {
        result: value
            .get("result")
            .and_then(Value::as_str)
            .map(str::to_string),
        accepted: value.get("accepted").and_then(Value::as_bool),
        production_proof: value.get("productionProof").and_then(Value::as_bool),
        evidence: string_array_field(&value, "evidence"),
        notes: string_array_field(&value, "notes"),
        scenario_results,
        blockers: string_array_field(&value, "blockers"),
        warnings: string_array_field(&value, "warnings"),
    })
}

fn build_repair_incidents(
    run_dir: &Path,
    plan: &AutopilotPlan,
    result: &PlaytestResultMemory,
    current_recipes: &[String],
) -> Vec<RepairIncident> {
    let mut incidents = Vec::new();
    for scenario in &result.scenario_results {
        if scenario.result == "passed" {
            continue;
        }
        let summary = format!(
            "Scenario '{}' recorded result '{}'",
            scenario.id, scenario.result
        );
        incidents.push(build_repair_incident(
            run_dir,
            plan,
            incidents.len() + 1,
            Some(scenario.id.clone()),
            &summary,
            &scenario.result,
            &result.evidence,
            current_recipes,
        ));
    }
    if incidents.is_empty()
        && result
            .result
            .as_deref()
            .is_some_and(|value| value != "passed")
    {
        let summary = result
            .notes
            .first()
            .or_else(|| result.evidence.first())
            .cloned()
            .unwrap_or_else(|| "Recorded playtest result did not pass".into());
        incidents.push(build_repair_incident(
            run_dir,
            plan,
            1,
            None,
            &summary,
            result.result.as_deref().unwrap_or("failed"),
            &result.evidence,
            current_recipes,
        ));
    }
    incidents
}

fn build_repair_incident(
    run_dir: &Path,
    plan: &AutopilotPlan,
    index: usize,
    scenario: Option<String>,
    summary: &str,
    severity: &str,
    evidence: &[String],
    current_recipes: &[String],
) -> RepairIncident {
    let classification = classify_repair_incident(scenario.as_deref(), summary, evidence);
    let run_text = run_dir.to_string_lossy();
    let prompt = format!(
        "Repair failed Roblox playtest for '{}': {}",
        plan.request.prompt, summary
    );
    let mut commands = vec![format!(
        "rs autopilot planner-pack \"{}\" --run-dir {} --format json",
        shell_display_arg(&prompt),
        run_text
    )];
    let missing_recipes = classification
        .recipes
        .iter()
        .filter(|recipe| !current_recipes.iter().any(|current| current == *recipe))
        .cloned()
        .collect::<Vec<_>>();
    if !missing_recipes.is_empty() {
        commands.push(format!(
            "rs autopilot improve --run-dir {} --recipe {} --format json",
            run_text,
            missing_recipes.join(",")
        ));
    }
    commands.push(format!(
        "rs autopilot audit-sources {} --format json",
        run_text
    ));
    commands.push(format!("rs autopilot certify {} --format json", run_text));
    let requires_custom_plan = missing_recipes.is_empty();
    RepairIncident {
        id: format!("repair-{index:02}"),
        severity: severity.into(),
        category: classification.category,
        scenario,
        summary: summary.into(),
        evidence: evidence.to_vec(),
        suggested_recipes: classification.recipes,
        commands,
        requires_custom_plan,
    }
}

fn classify_repair_incident(
    scenario: Option<&str>,
    summary: &str,
    evidence: &[String],
) -> RepairClassification {
    let mut text = String::new();
    if let Some(scenario) = scenario {
        text.push_str(scenario);
        text.push(' ');
    }
    text.push_str(summary);
    for item in evidence {
        text.push(' ');
        text.push_str(item);
    }
    let text = text.to_ascii_lowercase();
    let (category, recipes): (&str, Vec<&str>) = if text.contains("startershop")
        || text.contains("starter-shop")
        || text.contains("shop")
        || text.contains("purchase")
        || text.contains("buy")
    {
        ("shop-loop", vec!["starterShop"])
    } else if text.contains("tycoon")
        || text.contains("cash")
        || text.contains("dropper")
        || text.contains("upgrade")
    {
        ("core-loop", vec!["tycoonCore"])
    } else if text.contains("quest") || text.contains("claim") {
        ("quest-loop", vec!["questSystem"])
    } else if text.contains("inventory") || text.contains("equip") {
        ("inventory-loop", vec!["inventorySystem"])
    } else if text.contains("save") || text.contains("datastore") || text.contains("leaderstats") {
        ("progression-save", vec!["saveDataScaffold"])
    } else if text.contains("npc") || text.contains("guide") || text.contains("dialogue") {
        ("onboarding", vec!["npcInteraction"])
    } else if text.contains("obby") || text.contains("checkpoint") {
        ("checkpoint-loop", vec!["obbyCheckpoint"])
    } else if text.contains("enemy") || text.contains("combat") {
        ("encounter-loop", vec!["enemyEncounter"])
    } else if text.contains("teleport") || text.contains("lobby") {
        ("navigation", vec!["lobbyTeleport"])
    } else {
        ("custom-repair", Vec::new())
    };
    RepairClassification {
        category: category.into(),
        recipes: recipes.into_iter().map(str::to_string).collect(),
    }
}

fn build_repair_planner_prompt(
    plan: &AutopilotPlan,
    playtest: Option<&PlaytestResultMemory>,
    incidents: &[RepairIncident],
) -> String {
    let mut prompt = String::new();
    prompt.push_str(&format!(
        "Repair this Roblox Autopilot run without weakening safety. Original prompt: '{}'. ",
        plan.request.prompt
    ));
    if let Some(playtest) = playtest {
        let result = playtest.result.as_deref().unwrap_or("unknown");
        let accepted = playtest
            .accepted
            .map(|value| value.to_string())
            .unwrap_or_else(|| "unknown".into());
        prompt.push_str(&format!(
            "Live playtest result: {result}, accepted: {accepted}. "
        ));
        if !playtest.evidence.is_empty() {
            prompt.push_str("Evidence: ");
            prompt.push_str(&playtest.evidence.join("; "));
            prompt.push_str(". ");
        }
        if !playtest.notes.is_empty() {
            prompt.push_str("Notes: ");
            prompt.push_str(&playtest.notes.join("; "));
            prompt.push_str(". ");
        }
    }
    if !incidents.is_empty() {
        prompt.push_str("Repair incidents: ");
        let summaries = incidents
            .iter()
            .map(|incident| {
                format!(
                    "{}={} ({})",
                    incident.id, incident.category, incident.summary
                )
            })
            .collect::<Vec<_>>();
        prompt.push_str(&summaries.join("; "));
        prompt.push_str(". ");
    }
    prompt.push_str("Return only a strict rs.autopilot.plan.v1 patch plan using supported operations and generated/ source paths.");
    prompt
}

fn build_repair_plan_next_actions(
    run_dir: &Path,
    status: &str,
    has_incidents: bool,
) -> Vec<CoachAction> {
    let run_text = run_dir.to_string_lossy();
    let mut actions = Vec::new();
    match status {
        "needsPlaytestResult" => actions.push(coach_action(
            1,
            "Record playtest evidence",
            Some(format!(
                "rs autopilot record-playtest {run_text} --result failed --evidence <evidence>"
            )),
            "Repair planning needs concrete live evidence or notes.",
            false,
            false,
        )),
        "noRepairNeeded" => actions.push(coach_action(
            1,
            "Refresh judgment",
            Some(format!("rs autopilot judge {run_text} --format json")),
            "The playtest passed; refresh the readiness verdict.",
            false,
            false,
        )),
        _ if has_incidents => {
            actions.push(coach_action(
                1,
                "Create AI repair planner pack",
                Some(format!(
                    "rs autopilot planner-pack \"Repair failed playtest\" --run-dir {run_text} --format json"
                )),
                "Use the repair incidents and planner prompt as model context for a strict patch plan.",
                false,
                false,
            ));
            actions.push(coach_action(
                2,
                "Adopt the reviewed repair plan",
                Some("rs autopilot adopt-plan --plan <ai-plan.json> --source-root <repair-source-root> --out <repair-run> --format json".into()),
                "Adopt only strict validated model output, then audit and certify the repair run.",
                false,
                false,
            ));
        }
        _ => {}
    }
    actions.push(coach_action(
        9,
        "Refresh repair plan",
        Some(format!("rs autopilot repair-plan {run_text} --format json")),
        "Regenerate after new evidence, adopted plans, or certification changes.",
        false,
        false,
    ));
    dedup_next_actions(&mut actions);
    actions
}

fn build_repair_plan_agent_brief(status: &str, prompt: &str, incident_count: usize) -> String {
    match status {
        "needsRepair" => format!(
            "Repair '{prompt}' from {incident_count} failed playtest incident(s). Start with the planner prompt and adopt only strict patch output."
        ),
        "noRepairNeeded" => {
            format!("'{prompt}' has passing playtest proof; no repair plan is needed.")
        }
        "needsPlaytestResult" => {
            format!("'{prompt}' needs playtest evidence before repair planning.")
        }
        _ => format!("Repair plan for '{prompt}' is {status}; resolve blockers first."),
    }
}

fn build_playtest_scenarios(
    run_dir: &Path,
    plan: &AutopilotPlan,
    recipes: &[String],
    applied: Option<bool>,
) -> Vec<PlaytestScenario> {
    let mut scenarios = Vec::new();
    scenarios.push(PlaytestScenario {
        id: "autopilot-readiness".into(),
        title: "Autopilot Live Readiness".into(),
        recipe: None,
        goal: "Prove the bridge, Studio session, plugin protocol, and generated artifacts are ready before touching gameplay.".into(),
        setup: vec![
            "Open the target Roblox place in Studio.".into(),
            "Start the local bridge if readiness reports it is unreachable.".into(),
            "Keep the Autopilot run folder available for plan, preview, report, and rollback evidence.".into(),
        ],
        steps: vec![
            PlaytestStep {
                order: 1,
                action: "Run `rs autopilot ready --timeout 90 --format json`.".into(),
                expected: "The report selects one Studio session and has no blockers.".into(),
            },
            PlaytestStep {
                order: 2,
                action: "Run `rs autopilot verify-bundle --run-dir <run-dir> --format json`.".into(),
                expected: "The bundle reports `ok: true` with no missing or drifted artifacts.".into(),
            },
        ],
        expected_evidence: vec![
            "ready JSON report".into(),
            "bundle verification JSON report".into(),
        ],
        commands: vec![
            "rs autopilot ready --timeout 90 --format json".into(),
            format!(
                "rs autopilot verify-bundle --run-dir {} --format json",
                run_dir.to_string_lossy()
            ),
        ],
        requires_live_studio: true,
        mutates_studio: false,
    });

    if applied != Some(true) {
        scenarios.push(PlaytestScenario {
            id: "autopilot-apply-gate".into(),
            title: "Approved Apply Gate".into(),
            recipe: None,
            goal: "Apply the reviewed plan only after readiness passes and the user approves mutation.".into(),
            setup: vec!["Review `preview.json`, `report.md`, generated Luau, and rollback expectations.".into()],
            steps: vec![PlaytestStep {
                order: 1,
                action: "Run the generated apply command with `--yes --rollback-on-error --validate`.".into(),
                expected: "Apply records changed paths, validation status, and rollback evidence or an explicit rollback gap.".into(),
            }],
            expected_evidence: vec!["apply.json or apply summary".into(), "updated certification".into()],
            commands: vec![format!(
                "rs autopilot apply --plan {} --yes --rollback-on-error --validate",
                run_dir.join("plan.json").to_string_lossy()
            )],
            requires_live_studio: true,
            mutates_studio: true,
        });
    }

    let mut seen = BTreeSet::new();
    for recipe in recipes {
        if seen.insert(recipe.clone()) {
            scenarios.push(recipe_playtest_scenario(recipe, run_dir));
        }
    }
    if recipes.is_empty() {
        scenarios.push(generic_plan_playtest_scenario(run_dir, plan));
    }
    scenarios
}

fn recipe_playtest_scenario(recipe: &str, run_dir: &Path) -> PlaytestScenario {
    let (title, goal, steps, evidence) = match recipe {
        "starterShop" => (
            "Starter Shop Purchase Loop",
            "Verify the shop UI opens, loads catalog data, and sends purchases through server validation.",
            vec![
                ("Start play mode and open the generated Shop UI.", "The panel renders item data and a buy control without client errors."),
                ("Click the first buy button.", "The client fires the purchase remote and the server accepts or rejects based on currency."),
                ("Inspect leaderstats or server output.", "Currency or denial feedback changes are visible and server-owned."),
            ],
            vec!["Shop UI screenshot", "purchase result", "validation after apply"],
        ),
        "collectibleCoin" => (
            "Collectible Coin Reward Loop",
            "Verify a player can collect a coin and receive a server-side reward.",
            vec![
                ("Start play mode near a spawned coin.", "The coin is visible and reachable."),
                ("Touch or walk through the coin.", "The coin is consumed or debounced and the player reward changes."),
                ("Wait for respawn behavior if configured.", "The coin does not duplicate rewards during debounce."),
            ],
            vec!["before/after currency value", "coin state after touch"],
        ),
        "tycoonCore" => (
            "Tycoon Dropper And Upgrade Loop",
            "Verify the dropper, collector, cash, and upgrade path form a repeatable tycoon loop.",
            vec![
                ("Start play mode at the tycoon base.", "Dropper/collector parts are visible in Workspace."),
                ("Collect generated cash.", "Leaderstats or tycoon UI reflects cash gain."),
                ("Buy an upgrade.", "Cash decreases and the upgrade changes production or state."),
            ],
            vec!["cash before/after", "upgrade state", "tycoon UI feedback"],
        ),
        "saveDataScaffold" => (
            "Save Data Profile Smoke",
            "Verify profile defaults and leaderstats initialize without claiming persistence unless live DataStore is enabled.",
            vec![
                ("Start play mode with one player.", "leaderstats and profile defaults appear."),
                ("Trigger a reward from another scenario.", "The profile value changes server-side."),
                ("Review DataStore mode in generated config.", "The test records whether persistence is in memory or live DataStore mode."),
            ],
            vec!["leaderstats screenshot", "SaveConfig mode"],
        ),
        "adminPanel" => (
            "Admin Panel Permission Check",
            "Verify creator-only controls are visible and server-validated.",
            vec![
                ("Start play mode as the expected creator/admin account.", "Admin UI is visible only for the authorized player."),
                ("Send an announce command.", "All clients see the announcement or expected feedback."),
                ("Try from an unauthorized test account when available.", "Server refuses the command."),
            ],
            vec!["authorized result", "unauthorized refusal if tested"],
        ),
        "questSystem" => (
            "Quest Objective And Claim Loop",
            "Verify quest progress can update and claim rewards once requirements are met.",
            vec![
                ("Start play mode and view the quest UI.", "A quest objective and progress value are visible."),
                ("Perform the linked objective action.", "Progress changes through server state."),
                ("Claim the quest.", "Reward is granted once and repeat claims are refused."),
            ],
            vec!["quest progress before/after", "claim result"],
        ),
        "inventorySystem" => (
            "Inventory Equip Loop",
            "Verify starter inventory data appears and equip requests are server-owned.",
            vec![
                ("Start play mode and open inventory UI.", "Starter items render without client errors."),
                ("Equip an item.", "The server accepts a valid item and rejects unknown item ids."),
            ],
            vec!["inventory UI screenshot", "equip result"],
        ),
        "roundManager" => (
            "Round State Loop",
            "Verify intermission and active-round transitions update clients.",
            vec![
                ("Start play mode and wait through intermission.", "Round state appears in UI or remotes."),
                ("Enter the arena marker.", "The player is included in the active round state."),
            ],
            vec!["state transition timestamps", "round UI state"],
        ),
        "lobbyTeleport" => (
            "Lobby Teleport Pads",
            "Verify lobby and arena pads move the player with debounce.",
            vec![
                ("Touch the lobby pad.", "The character moves to the arena pad target."),
                ("Touch the return pad.", "The character returns without rapid-repeat jitter."),
            ],
            vec!["start/end positions", "debounce behavior"],
        ),
        "obbyCheckpoint" => (
            "Obby Checkpoint Progress",
            "Verify checkpoint touch, fall reset, and finish feedback.",
            vec![
                ("Touch checkpoint 1.", "Checkpoint progress updates."),
                ("Fall or reset after checkpoint.", "The player returns to the last checkpoint."),
                ("Reach the finish pad.", "Completion feedback is visible."),
            ],
            vec!["checkpoint value", "finish feedback"],
        ),
        "toolSystem" => (
            "Tool Equip And Activate",
            "Verify the generated tool equips and activation feedback debounces.",
            vec![
                ("Start play mode and equip the tool.", "The Tool moves to the character and remains welded."),
                ("Activate the tool repeatedly.", "Feedback fires and cooldown prevents spam."),
            ],
            vec!["tool equipped state", "cooldown feedback"],
        ),
        "enemyEncounter" => (
            "Enemy Encounter Reward",
            "Verify the training enemy can be engaged, defeated, rewarded, and respawned.",
            vec![
                ("Start play mode near the enemy.", "Enemy model and attack prompt are visible."),
                ("Trigger the attack prompt until defeat.", "Enemy health/progress changes and reward is granted."),
                ("Wait for respawn.", "Enemy returns without duplicate reward spam."),
            ],
            vec!["enemy state before/after", "reward value", "respawn evidence"],
        ),
        "npcInteraction" => (
            "Guide NPC Dialogue",
            "Verify the NPC prompt opens dialogue and guides the next player action.",
            vec![
                ("Start play mode near the guide NPC.", "ProximityPrompt is visible."),
                ("Interact with the prompt.", "Dialogue UI appears with clear next-step text."),
            ],
            vec!["dialogue screenshot", "prompt interaction"],
        ),
        _ => (
            "Generated Feature Smoke",
            "Verify generated instances and scripts work without client/server errors.",
            vec![
                ("Start play mode.", "No generated script errors appear."),
                ("Interact with the generated feature.", "The feature produces visible state or feedback."),
            ],
            vec!["Studio output", "feature screenshot"],
        ),
    };
    PlaytestScenario {
        id: format!("recipe-{}", slug(recipe)),
        title: title.into(),
        recipe: Some(recipe.into()),
        goal: goal.into(),
        setup: vec![
            "Run live readiness first.".into(),
            "Apply the Autopilot plan if certification does not already record an apply.".into(),
        ],
        steps: steps
            .into_iter()
            .enumerate()
            .map(|(index, (action, expected))| PlaytestStep {
                order: (index + 1) as u8,
                action: action.into(),
                expected: expected.into(),
            })
            .collect(),
        expected_evidence: evidence.into_iter().map(str::to_string).collect(),
        commands: vec![
            format!("rs autopilot ready --timeout 90 --format json"),
            format!(
                "rs autopilot certify {} --format json",
                run_dir.to_string_lossy()
            ),
        ],
        requires_live_studio: true,
        mutates_studio: false,
    }
}

fn generic_plan_playtest_scenario(run_dir: &Path, plan: &AutopilotPlan) -> PlaytestScenario {
    PlaytestScenario {
        id: "generic-plan-smoke".into(),
        title: "Generic Plan Smoke".into(),
        recipe: None,
        goal: "Verify the planned operations create visible state and do not introduce validation failures.".into(),
        setup: vec![
            "Review generated source files and preview before live apply.".into(),
            "Run readiness and apply only with explicit approval.".into(),
        ],
        steps: vec![
            PlaytestStep {
                order: 1,
                action: format!("Inspect {} planned operation(s).", plan.operations.len()),
                expected: "Every operation is expected, scoped, and owned or explicitly approved.".into(),
            },
            PlaytestStep {
                order: 2,
                action: "Apply the plan in Studio and run validation.".into(),
                expected: "Validation reports no fail diagnostics for the touched scope.".into(),
            },
        ],
        expected_evidence: vec!["preview.json".into(), "validation result".into()],
        commands: vec![
            format!(
                "rs autopilot preview --plan {} --format json",
                run_dir.join("plan.json").to_string_lossy()
            ),
            format!(
                "rs autopilot certify {} --format json",
                run_dir.to_string_lossy()
            ),
        ],
        requires_live_studio: true,
        mutates_studio: false,
    }
}

#[derive(Default)]
struct MemoryCertification {
    ready_to_apply: Option<bool>,
    safe_to_handoff: Option<bool>,
    applied: Option<bool>,
    blockers: Vec<String>,
    warnings: Vec<String>,
}

#[derive(Default)]
struct MemoryGameplay {
    verdict: Option<String>,
    score: Option<u8>,
    gaps: Vec<MemoryGameplayGap>,
    blockers: Vec<String>,
    warnings: Vec<String>,
}

#[derive(Default)]
struct MemoryPlaytestResult {
    exists: bool,
    result: Option<String>,
    accepted: Option<bool>,
    production_proof: Option<bool>,
    evidence_count: usize,
    blockers: Vec<String>,
    warnings: Vec<String>,
}

#[derive(Default)]
struct LiveApplyEvidence {
    rollback_verified: bool,
    rollback_artifact: Option<String>,
}

fn read_memory_certification(run_dir: &Path) -> AppResult<MemoryCertification> {
    let path = run_dir.join("certification.json");
    if !path.exists() {
        return Ok(MemoryCertification::default());
    }
    let value = read_json_file(&path)?;
    Ok(MemoryCertification {
        ready_to_apply: value.get("readyToApply").and_then(Value::as_bool),
        safe_to_handoff: value.get("safeToHandoff").and_then(Value::as_bool),
        applied: value.get("applied").and_then(Value::as_bool),
        blockers: string_array_field(&value, "blockers"),
        warnings: string_array_field(&value, "warnings"),
    })
}

fn read_memory_gameplay(run_dir: &Path) -> AppResult<MemoryGameplay> {
    let path = run_dir.join("gameplay-critique.json");
    if !path.exists() {
        return Ok(MemoryGameplay::default());
    }
    let value = read_json_file(&path)?;
    let verdict = value
        .get("verdict")
        .and_then(Value::as_str)
        .map(str::to_string);
    let score = value
        .get("score")
        .and_then(Value::as_u64)
        .and_then(|score| u8::try_from(score).ok());
    let gaps = value
        .get("gaps")
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .map(|gap| MemoryGameplayGap {
                    run_dir: run_dir.to_string_lossy().to_string(),
                    severity: gap
                        .get("severity")
                        .and_then(Value::as_str)
                        .unwrap_or("info")
                        .to_string(),
                    category: gap
                        .get("category")
                        .and_then(Value::as_str)
                        .unwrap_or("unknown")
                        .to_string(),
                    message: gap
                        .get("message")
                        .and_then(Value::as_str)
                        .unwrap_or("gameplay critique gap")
                        .to_string(),
                    suggested_recipe: gap
                        .get("suggestedRecipe")
                        .and_then(Value::as_str)
                        .map(str::to_string),
                    command: gap
                        .get("command")
                        .and_then(Value::as_str)
                        .map(str::to_string),
                })
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();
    Ok(MemoryGameplay {
        verdict,
        score,
        gaps,
        blockers: string_array_field(&value, "blockers"),
        warnings: string_array_field(&value, "warnings")
            .into_iter()
            .filter(|warning| {
                !warning.starts_with("plan risk ") && !warning.starts_with("plan writes scripts")
            })
            .collect(),
    })
}

fn read_memory_playtest_result(run_dir: &Path) -> AppResult<MemoryPlaytestResult> {
    let path = run_dir.join("playtest-result.json");
    if !path.exists() {
        return Ok(MemoryPlaytestResult::default());
    }
    let value = read_json_file(&path)?;
    let evidence_count = value
        .get("evidence")
        .and_then(Value::as_array)
        .map(Vec::len)
        .unwrap_or(0);
    Ok(MemoryPlaytestResult {
        exists: true,
        result: value
            .get("result")
            .and_then(Value::as_str)
            .map(str::to_string),
        accepted: value.get("accepted").and_then(Value::as_bool),
        production_proof: value.get("productionProof").and_then(Value::as_bool),
        evidence_count,
        blockers: string_array_field(&value, "blockers"),
        warnings: string_array_field(&value, "warnings"),
    })
}

fn read_live_apply_evidence(run_dir: &Path) -> AppResult<LiveApplyEvidence> {
    let apply_path = run_dir.join("apply.json");
    if !apply_path.exists() {
        return Ok(LiveApplyEvidence::default());
    }
    let value = read_json_file(&apply_path)?;
    let rollback_artifact = value
        .get("rollbackArtifact")
        .and_then(Value::as_str)
        .filter(|value| !value.trim().is_empty())
        .map(str::to_string);
    let rollback_verified = rollback_artifact.as_ref().is_some_and(|artifact| {
        let artifact_path = PathBuf::from(artifact);
        if artifact_path.exists() {
            true
        } else {
            run_dir.join(artifact).exists()
        }
    });
    Ok(LiveApplyEvidence {
        rollback_verified,
        rollback_artifact,
    })
}

fn string_array_field(value: &Value, field: &str) -> Vec<String> {
    value
        .get(field)
        .and_then(Value::as_array)
        .map(|items| {
            items
                .iter()
                .filter_map(Value::as_str)
                .map(str::to_string)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default()
}

fn coach_actions_field(value: &Value, field: &str) -> Vec<CoachAction> {
    value
        .get(field)
        .cloned()
        .and_then(|actions| serde_json::from_value(actions).ok())
        .unwrap_or_default()
}

fn operation_counts_for_plan(plan: &AutopilotPlan) -> BTreeMap<String, usize> {
    let mut counts = BTreeMap::new();
    for operation in &plan.operations {
        *counts.entry(operation.kind.clone()).or_insert(0) += 1;
    }
    counts
}

fn created_paths_for_plan(plan: &AutopilotPlan) -> Vec<String> {
    let mut paths = Vec::new();
    for operation in &plan.operations {
        if let Some(path) = &operation.path {
            paths.push(path.clone());
        } else if let (Some(parent), Some(name)) = (&operation.parent_path, &operation.name) {
            paths.push(format!("{parent}.{name}"));
        }
    }
    paths.sort();
    paths.dedup();
    paths
}

fn generated_files_for_plan(plan: &AutopilotPlan) -> Vec<String> {
    let mut files = plan
        .operations
        .iter()
        .filter_map(|operation| operation.source_path.clone())
        .collect::<Vec<_>>();
    files.sort();
    files.dedup();
    files
}

fn recipes_for_run(run_dir: &Path, plan: &AutopilotPlan) -> AppResult<Vec<String>> {
    let request_path = run_dir.join("request.json");
    let mut recipes = Vec::new();
    if request_path.exists() {
        let request = read_json_file(&request_path)?;
        if let Some(items) = request.get("recipes").and_then(Value::as_array) {
            recipes.extend(
                items
                    .iter()
                    .filter_map(Value::as_str)
                    .map(str::to_string)
                    .collect::<Vec<_>>(),
            );
        }
    }
    let catalog = recipe_catalog();
    for source_path in generated_files_for_plan(plan) {
        let normalized = source_path.replace('\\', "/");
        if let Some(namespace) = normalized.split('/').nth(1) {
            if let Some(recipe) = catalog
                .recipes
                .iter()
                .find(|recipe| slug(&recipe.name) == namespace)
            {
                recipes.push(recipe.name.clone());
            }
        }
        if let Some(recipe) = catalog.recipes.iter().find(|recipe| {
            recipe
                .generated_files
                .iter()
                .any(|file| file.replace('\\', "/") == normalized)
        }) {
            recipes.push(recipe.name.clone());
        }
    }
    recipes.sort();
    recipes.dedup();
    Ok(recipes)
}

fn merge_many_sorted(items: Vec<Vec<String>>) -> Vec<String> {
    let mut merged = Vec::new();
    for item in items {
        merged.extend(item);
    }
    merged.sort();
    merged.dedup();
    merged
}

fn build_memory_agent_brief(
    active_run: Option<&RunIndexEntry>,
    run_count: usize,
    created_paths: &[String],
    blockers: &[String],
    gameplay_verdicts: &BTreeMap<String, usize>,
    gameplay_gaps: &[MemoryGameplayGap],
) -> String {
    let gameplay_blockers = gameplay_gaps
        .iter()
        .filter(|gap| gap.severity == "blocker")
        .count();
    if !blockers.is_empty() {
        if gameplay_blockers > 0 {
            return format!(
                "Project memory has {} blocker(s), including {} gameplay blocker(s). Patch gameplay gaps before live Studio mutation.",
                blockers.len(),
                gameplay_blockers
            );
        }
        return format!(
            "Project memory has {} blocker(s). Resolve the active run before mutating Studio.",
            blockers.len()
        );
    }
    if let Some(active_run) = active_run {
        let verdicts = if gameplay_verdicts.is_empty() {
            "no gameplay verdicts".to_string()
        } else {
            gameplay_verdicts
                .iter()
                .map(|(verdict, count)| format!("{verdict}:{count}"))
                .collect::<Vec<_>>()
                .join(", ")
        };
        return format!(
            "Project memory covers {run_count} run(s), {} known created path(s), and gameplay verdicts [{}]. Continue from '{}' ({}) unless the user gives a new goal.",
            created_paths.len(),
            verdicts,
            active_run.plan_id,
            active_run.run_dir
        );
    }
    "Project memory has no Autopilot runs yet. Start with architect or kickoff before live Studio mutation.".into()
}

fn select_active_run(runs: &[RunIndexEntry]) -> Option<&RunIndexEntry> {
    runs.iter()
        .find(|run| run.status == "blocked")
        .or_else(|| runs.iter().find(|run| run.status == "readyToApply"))
        .or_else(|| runs.first())
}

fn build_mission_recommendations(prompt: Option<&str>) -> Vec<MissionRecommendation> {
    let Some(prompt) = prompt else {
        return Vec::new();
    };
    let recipes = compose_prompt_recipes(prompt).unwrap_or_default();
    let catalog = recipe_catalog();
    recipes
        .into_iter()
        .filter_map(|recipe| {
            let info = catalog.recipes.iter().find(|info| info.name == recipe)?;
            Some(MissionRecommendation {
                recipe: recipe.clone(),
                summary: info.summary.clone(),
                reason: mission_recommendation_reason(prompt, info),
                command: format!(
                    "rs autopilot plan \"{}\" --recipe {} --out .rs\\autopilot\\runs\\{}",
                    shell_display_arg(prompt),
                    recipe,
                    slug(prompt)
                ),
            })
        })
        .collect()
}

fn mission_recommendation_reason(prompt: &str, info: &RecipeInfo) -> String {
    let lower = prompt.to_ascii_lowercase();
    let matched = info
        .prompt_hints
        .iter()
        .filter(|hint| lower.contains(&hint.to_ascii_lowercase()))
        .cloned()
        .collect::<Vec<_>>();
    if matched.is_empty() {
        "Included by the selected recipe stack as supporting infrastructure".into()
    } else {
        format!("Prompt matched recipe hints: {}", matched.join(", "))
    }
}

fn build_mission_agent_brief(
    status: &str,
    prompt: Option<&str>,
    active_run: Option<&RunIndexEntry>,
    blockers: &[String],
) -> String {
    if !blockers.is_empty() {
        return format!(
            "Mission is blocked. Start with the listed blockers before running any mutating Studio command. {}",
            active_run
                .map(|run| format!("Active run: {}.", run.run_dir))
                .unwrap_or_else(|| "No active run was selected.".into())
        );
    }
    if let Some(active_run) = active_run {
        return format!(
            "Mission is {status}. Continue from run '{}' ({}) and keep all mutation behind preview, explicit approval, rollback, and validation.",
            active_run.plan_id, active_run.run_dir
        );
    }
    if let Some(prompt) = prompt {
        format!(
            "Mission needs a plan for the prompt '{}'. Use the recommended compose command to create reviewable artifacts before contacting Studio.",
            prompt
        )
    } else {
        "Mission needs a plan. The recommended ambitious default is a full starter-game compose run with smoke verification.".into()
    }
}

fn build_architect_report(
    prompt: &str,
    root: &Path,
    limit: usize,
    architecture_path: &Path,
    markdown_path: Option<&Path>,
    smoke: Option<&str>,
) -> AppResult<ArchitectReport> {
    let recipes = compose_prompt_recipes(prompt)?;
    let intent = architect_intent(prompt, &recipes);
    let recipe_stack = build_architect_recipe_stack(prompt, &recipes);
    let mut warnings = Vec::new();
    let mut blockers = Vec::new();
    let active_run = if root.exists() {
        let runs_report = build_runs_report(root, limit)?;
        for blocker in runs_report.blockers {
            warnings.push(format!("run index warning: {blocker}"));
        }
        select_active_run(&runs_report.runs).cloned()
    } else {
        warnings.push(format!(
            "run root does not exist yet: {}; the first compose command will create artifacts",
            root.display()
        ));
        None
    };
    if let Some(active_run) = &active_run {
        if active_run.status == "blocked" {
            warnings.push(format!(
                "active run '{}' is blocked; resolve it before applying another live plan",
                active_run.run_dir
            ));
        }
    }

    let run_dir = PathBuf::from(".rs")
        .join("autopilot")
        .join("runs")
        .join(slug(prompt));
    let run_dir_display = run_dir.to_string_lossy().to_string();
    let manifest_path = PathBuf::from(".rs")
        .join("autopilot")
        .join("manifests")
        .join(format!("{}.autopilot-compose.json", slug(prompt)));
    let manifest_display = manifest_path.to_string_lossy().to_string();
    let prompt_arg = shell_display_arg(prompt);
    let recipe_arg = recipes.join(",");
    let smoke_arg = smoke
        .map(|suite| format!(" --smoke {}", shell_display_arg(suite)))
        .unwrap_or_default();
    let tune_command = format!(
        "rs autopilot tune \"{prompt_arg}\" --recipe {recipe_arg}{smoke_arg} --out {manifest_display} --format json"
    );
    let compose_command = format!(
        "rs autopilot compose --from-manifest {manifest_display} --out {run_dir_display} --format json"
    );
    let phases = build_architect_phases(
        &recipes,
        &run_dir_display,
        &manifest_display,
        tune_command,
        compose_command,
        smoke,
    );
    let mut next_actions = Vec::new();
    let mut next_priority = 1u8;
    if let Some(active_run) = &active_run {
        if active_run.status == "blocked" {
            next_actions.push(CoachAction {
                priority: next_priority,
                title: "Resolve active blocked run".into(),
                command: Some(format!(
                    "rs autopilot handoff {} --format json",
                    active_run.run_dir
                )),
                reason:
                    "A prior run is blocked; refresh its handoff before adding more live changes."
                        .into(),
                requires_live_studio: false,
                mutates_studio: false,
            });
            next_priority += 1;
        }
    }
    if let Some(phase) = phases
        .iter()
        .find(|phase| phase.name == "Tune Recipe Manifest")
    {
        next_actions.push(CoachAction {
            priority: next_priority,
            title: "Tune the recipe manifest".into(),
            command: phase.command.clone(),
            reason:
                "Turns creator intent into explicit recipe names, economy values, and item knobs before compose."
                    .into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
        next_priority += 1;
    }
    if let Some(phase) = phases
        .iter()
        .find(|phase| phase.name == "Compose Reviewable Plan")
    {
        next_actions.push(CoachAction {
            priority: next_priority,
            title: "Compose the staged plan".into(),
            command: phase.command.clone(),
            reason:
                "Creates deterministic plan, preview, generated source, and report artifacts without mutating Studio."
                    .into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
        next_priority += 1;
    }
    next_actions.push(CoachAction {
        priority: next_priority,
        title: "Check live readiness".into(),
        command: Some("rs autopilot ready --timeout 90 --format json".into()),
        reason: "Confirms bridge, target Studio, plugin protocol, and Autopilot capabilities before preview/apply."
            .into(),
        requires_live_studio: true,
        mutates_studio: false,
    });
    next_priority += 1;
    next_actions.push(CoachAction {
        priority: next_priority,
        title: "Certify before handoff or apply".into(),
        command: Some(format!(
            "rs autopilot certify {} --format json",
            run_dir_display
        )),
        reason: "Produces a deterministic go/no-go packet after compose, handoff, or preview artifacts exist."
            .into(),
        requires_live_studio: false,
        mutates_studio: false,
    });
    next_actions.sort_by(|left, right| {
        left.priority
            .cmp(&right.priority)
            .then_with(|| left.title.cmp(&right.title))
    });
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let agent_brief = build_architect_agent_brief(prompt, &intent, &recipes, &warnings);
    Ok(ArchitectReport {
        schema_version: "rs.autopilot.architect.v1".into(),
        generated_at: now_stamp(),
        architecture_path: architecture_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        root: root.to_string_lossy().to_string(),
        prompt: prompt.to_string(),
        intent,
        recipe_stack,
        phases,
        active_run,
        blockers,
        warnings,
        next_actions,
        agent_brief,
    })
}

fn architect_intent(prompt: &str, recipes: &[String]) -> ArchitectIntent {
    let lower = prompt.to_ascii_lowercase();
    if recipes.iter().any(|recipe| recipe == "tycoonCore") {
        return ArchitectIntent {
            genre: "Tycoon / factory prototype".into(),
            core_loop:
                "Drop resources, collect cash, buy upgrades, persist progress, and expose admin-safe iteration controls."
                    .into(),
            player_promise:
                "Players can immediately understand how to earn, upgrade, and return later with visible progress."
                    .into(),
            recommended_preset: Some("tycoonPrototype".into()),
            confidence: "high".into(),
        };
    }
    if recipes.iter().any(|recipe| recipe == "enemyEncounter")
        || recipes.iter().any(|recipe| recipe == "obbyCheckpoint")
    {
        return ArchitectIntent {
            genre: "Adventure challenge hub".into(),
            core_loop:
                "Spawn in a hub, talk to an NPC, complete movement/combat objectives, earn rewards, and track quest progress."
                    .into(),
            player_promise:
                "Players get a playable challenge route with clear goals, feedback, rewards, and a reason to keep going."
                    .into(),
            recommended_preset: Some("adventureHub".into()),
            confidence: "high".into(),
        };
    }
    if lower.contains("round") || recipes.iter().any(|recipe| recipe == "roundManager") {
        return ArchitectIntent {
            genre: "Round-based multiplayer prototype".into(),
            core_loop:
                "Move players through lobby, intermission, active round, rewards, and reset states with visible status feedback."
                    .into(),
            player_promise:
                "Players always know what phase the game is in and what to do next."
                    .into(),
            recommended_preset: Some("fullStarterGame".into()),
            confidence: "medium".into(),
        };
    }
    ArchitectIntent {
        genre: "Complete starter-game vertical slice".into(),
        core_loop:
            "Collect, progress, shop, equip, interact, and save through a coherent set of reusable Roblox systems."
                .into(),
        player_promise:
            "Players enter a place that already has goals, rewards, UI feedback, and persistence scaffolding."
                .into(),
        recommended_preset: Some("fullStarterGame".into()),
        confidence: "medium".into(),
    }
}

fn build_architect_recipe_stack(prompt: &str, recipes: &[String]) -> Vec<ArchitectRecipe> {
    let catalog = recipe_catalog();
    recipes
        .iter()
        .filter_map(|recipe| {
            let info = catalog.recipes.iter().find(|info| &info.name == recipe)?;
            Some(ArchitectRecipe {
                recipe: recipe.clone(),
                summary: info.summary.clone(),
                role: architect_recipe_role(recipe).into(),
                creates: info.creates.clone(),
                generated_files: info.generated_files.clone(),
                reason: mission_recommendation_reason(prompt, info),
            })
        })
        .collect()
}

fn architect_recipe_role(recipe: &str) -> &'static str {
    match recipe {
        "saveDataScaffold" | "adminPanel" => "foundation",
        "tycoonCore" | "roundManager" | "obbyCheckpoint" | "enemyEncounter" => "core-loop",
        "collectibleCoin" | "starterShop" | "inventorySystem" => "economy",
        "questSystem" | "npcInteraction" | "lobbyTeleport" | "toolSystem" => "engagement",
        _ => "support",
    }
}

fn build_architect_phases(
    recipes: &[String],
    run_dir: &str,
    manifest_path: &str,
    tune_command: String,
    compose_command: String,
    smoke: Option<&str>,
) -> Vec<ArchitectPhase> {
    let mut phases = Vec::new();
    let foundation = recipes_by_role(recipes, "foundation");
    let core_loop = recipes_by_role(recipes, "core-loop");
    let economy = recipes_by_role(recipes, "economy");
    let engagement = recipes_by_role(recipes, "engagement");
    phases.push(ArchitectPhase {
        order: 1,
        name: "Frame The Game Slice".into(),
        goal: "Convert the creator prompt into a concrete genre, loop, recipe stack, and safety envelope."
            .into(),
        recipes: recipes.to_vec(),
        command: None,
        validation_gates: vec![
            "No Studio mutation".into(),
            "Recipe stack is deterministic and supported".into(),
            "All follow-up commands preserve preview before apply".into(),
        ],
        exit_criteria: vec![
            "Intent, player promise, and implementation stack are written to architect.json and architect.md."
                .into(),
        ],
        requires_live_studio: false,
        mutates_studio: false,
    });
    phases.push(ArchitectPhase {
        order: 2,
        name: "Tune Recipe Manifest".into(),
        goal: "Convert the recipe stack into explicit creator-specific names, economy values, and item knobs before planning."
            .into(),
        recipes: recipes.to_vec(),
        command: Some(tune_command),
        validation_gates: vec![
            "Manifest kind is autopilotCompose".into(),
            "Each recipe entry has an explicit kind and reviewed tuning knobs".into(),
            "No Studio mutation".into(),
        ],
        exit_criteria: vec![
            format!("{manifest_path} exists"),
            "Manifest has recipe objects rather than only generic recipe names".into(),
        ],
        requires_live_studio: false,
        mutates_studio: false,
    });
    phases.push(ArchitectPhase {
        order: 3,
        name: "Compose Reviewable Plan".into(),
        goal: "Generate one namespaced plan with scripts, instances, verification operations, and preview integrity."
            .into(),
        recipes: recipes.to_vec(),
        command: Some(compose_command),
        validation_gates: vec![
            "plan.json validates against rs.autopilot.plan.v1".into(),
            "preview.json includes an integrity seal".into(),
            "report.md lists operation counts and generated files".into(),
        ],
        exit_criteria: vec![
            format!("{run_dir}\\plan.json exists"),
            format!("{run_dir}\\preview.json exists"),
            format!("{run_dir}\\report.md exists"),
        ],
        requires_live_studio: false,
        mutates_studio: false,
    });
    phases.push(ArchitectPhase {
        order: 4,
        name: "Review Foundation And Core Loop".into(),
        goal: "Make the implementation easy for another AI or human to inspect before Studio is touched."
            .into(),
        recipes: foundation
            .iter()
            .chain(core_loop.iter())
            .chain(economy.iter())
            .cloned()
            .collect(),
        command: Some(format!(
            "rs autopilot explain --plan {run_dir}\\plan.json --format json"
        )),
        validation_gates: vec![
            "No validation blockers".into(),
            "Script-generating recipes are visible in generated/".into(),
            "Danger/refused operations are absent".into(),
        ],
        exit_criteria: vec![
            "explain output reports valid=true".into(),
            "recommended next commands do not skip preview or approval".into(),
        ],
        requires_live_studio: false,
        mutates_studio: false,
    });
    phases.push(ArchitectPhase {
        order: 5,
        name: "Seal Handoff Packet".into(),
        goal: "Hash every artifact so another AI can resume from evidence instead of trusting chat context."
            .into(),
        recipes: engagement,
        command: Some(format!("rs autopilot handoff {run_dir} --format json")),
        validation_gates: vec![
            "bundle.json verifies artifact hashes".into(),
            "handoff.json has no blockers".into(),
            "handoff.md contains the agent brief and safe next actions".into(),
        ],
        exit_criteria: vec![
            "safeToHandoff is true in certification or handoff status is readyToApply".into(),
        ],
        requires_live_studio: false,
        mutates_studio: false,
    });
    phases.push(ArchitectPhase {
        order: 6,
        name: "Check Live Readiness".into(),
        goal: "Confirm the bridge, selected Studio, plugin protocol, and Autopilot capabilities before live work."
            .into(),
        recipes: Vec::new(),
        command: Some("rs autopilot ready --timeout 90 --format json".into()),
        validation_gates: vec![
            "ready.ok is true".into(),
            "protocolVersion matches the CLI expectation".into(),
            "applyPlan, upsertFiles, validate, snapshot, deps, and autopilotReview are available".into(),
        ],
        exit_criteria: vec!["A specific Studio session is selected and ready.".into()],
        requires_live_studio: true,
        mutates_studio: false,
    });
    phases.push(ArchitectPhase {
        order: 7,
        name: "Live Preview".into(),
        goal:
            "Ask Studio to check preconditions and dry-run supported operations without mutation."
                .into(),
        recipes: Vec::new(),
        command: Some(format!(
            "rs autopilot preview --plan {run_dir}\\plan.json --live --format json"
        )),
        validation_gates: vec![
            "preconditions all pass".into(),
            "live dry-run reports refused=0".into(),
            "Studio review panel receives the preview state".into(),
        ],
        exit_criteria: vec!["preview.safeToPreview is true after live checks.".into()],
        requires_live_studio: true,
        mutates_studio: false,
    });
    let apply_smoke_arg = smoke
        .map(|suite| format!(" --smoke {}", shell_display_arg(suite)))
        .unwrap_or_default();
    phases.push(ArchitectPhase {
        order: 8,
        name: "Apply With Rollback".into(),
        goal: "Mutate Studio only after approval, with rollback capture, validation, and optional smoke evidence."
            .into(),
        recipes: Vec::new(),
        command: Some(format!(
            "rs autopilot apply --plan {run_dir}\\plan.json --yes --rollback-on-error --validate{apply_smoke_arg} --format json"
        )),
        validation_gates: vec![
            "rollback artifact is written before mutation".into(),
            "validation-after.json has zero fail diagnostics for touched scope".into(),
            "apply.json records changed paths and warnings".into(),
        ],
        exit_criteria: vec![
            "apply status is applied".into(),
            "report.md names rollback, validation, and changed paths".into(),
        ],
        requires_live_studio: true,
        mutates_studio: true,
    });
    phases.push(ArchitectPhase {
        order: 9,
        name: "Certify And Continue".into(),
        goal: "Convert the run into a go/no-go packet and refresh mission continuity for the next agent turn."
            .into(),
        recipes: Vec::new(),
        command: Some(format!(
            "rs autopilot certify {run_dir} --format json"
        )),
        validation_gates: vec![
            "certification gates are pass or explicitly warning-only".into(),
            "mission packet points to the next continuation command".into(),
        ],
        exit_criteria: vec![
            "certification.json and certification.md exist".into(),
            "rs autopilot mission can select the active continuation point".into(),
        ],
        requires_live_studio: false,
        mutates_studio: false,
    });
    phases
}

fn recipes_by_role(recipes: &[String], role: &str) -> Vec<String> {
    recipes
        .iter()
        .filter(|recipe| architect_recipe_role(recipe) == role)
        .cloned()
        .collect()
}

fn build_architect_agent_brief(
    prompt: &str,
    intent: &ArchitectIntent,
    recipes: &[String],
    warnings: &[String],
) -> String {
    let warning_clause = if warnings.is_empty() {
        "No existing run warnings were found.".to_string()
    } else {
        format!(
            "{} warning(s) must be read before live preview or apply.",
            warnings.len()
        )
    };
    format!(
        "Build '{}' as a {}. Use recipes [{}] to deliver this player promise: {} Keep all work in the staged Autopilot flow: tune, compose, explain, handoff, ready, live preview, apply with rollback, then certify. {}",
        prompt,
        intent.genre,
        recipes.join(", "),
        intent.player_promise,
        warning_clause
    )
}

fn build_kickoff_report(
    prompt: &str,
    run_dir: &Path,
    architecture_path: &Path,
    architecture_markdown_path: &Path,
    tune_manifest_path: &Path,
    tune_markdown_path: &Path,
    tune: TuneReport,
    handoff_path: &Path,
    certification_path: &Path,
    planner_pack_path: &Path,
    planner_pack_markdown_path: &Path,
    simulation_path: &Path,
    simulation_markdown_path: &Path,
    feature_graph_path: &Path,
    feature_graph_markdown_path: &Path,
    balance_path: &Path,
    balance_markdown_path: &Path,
    impact_path: &Path,
    impact_markdown_path: &Path,
    contracts_path: &Path,
    contracts_markdown_path: &Path,
    authority_path: &Path,
    authority_markdown_path: &Path,
    ux_path: &Path,
    ux_markdown_path: &Path,
    copy_deck_path: &Path,
    copy_deck_markdown_path: &Path,
    performance_path: &Path,
    performance_markdown_path: &Path,
    accessibility_path: &Path,
    accessibility_markdown_path: &Path,
    policy_path: &Path,
    policy_markdown_path: &Path,
    style_guide_path: &Path,
    style_guide_markdown_path: &Path,
    world_blueprint_path: &Path,
    world_blueprint_markdown_path: &Path,
    onboarding_path: &Path,
    onboarding_markdown_path: &Path,
    showcase_path: &Path,
    showcase_markdown_path: &Path,
    telemetry_path: &Path,
    telemetry_markdown_path: &Path,
    monetization_path: &Path,
    monetization_markdown_path: &Path,
    social_path: &Path,
    social_markdown_path: &Path,
    liveops_path: &Path,
    liveops_markdown_path: &Path,
    persistence_path: &Path,
    persistence_markdown_path: &Path,
    asset_brief_path: &Path,
    asset_brief_markdown_path: &Path,
    trace_path: &Path,
    trace_markdown_path: &Path,
    gameplay_critique_path: &Path,
    gameplay_critique_markdown_path: &Path,
    playtest_plan_path: &Path,
    playtest_plan_markdown_path: &Path,
    memory_path: &Path,
    memory_markdown_path: &Path,
    architect: ArchitectReport,
    handoff: HandoffReport,
    certification: CertificationReport,
    simulation: SimulationReport,
    feature_graph: FeatureGraphReport,
    balance: BalanceReport,
    impact: ImpactReport,
    contracts: ContractsReport,
    authority: AuthorityReport,
    ux: UxReport,
    copy_deck: CopyDeckReport,
    performance: PerformanceReport,
    accessibility: AccessibilityReport,
    policy: PolicyReport,
    style_guide: StyleGuideReport,
    world_blueprint: WorldBlueprintReport,
    onboarding: OnboardingReport,
    showcase: ShowcaseReport,
    telemetry: TelemetryReport,
    monetization: MonetizationReport,
    social: SocialReport,
    liveops: LiveopsReport,
    persistence: PersistenceReport,
    asset_brief: AssetBriefReport,
    trace: TraceReport,
    gameplay_critique: GameplayCritiqueReport,
    playtest_plan: PlaytestPlanReport,
    memory: MemoryReport,
) -> KickoffReport {
    let mut blockers = architect.blockers;
    blockers.extend(handoff.blockers);
    blockers.extend(certification.blockers.clone());
    blockers.extend(simulation.blockers.clone());
    blockers.extend(feature_graph.blockers.clone());
    blockers.extend(balance.blockers.clone());
    blockers.extend(impact.blockers.clone());
    blockers.extend(contracts.blockers.clone());
    blockers.extend(authority.blockers.clone());
    blockers.extend(ux.blockers.clone());
    blockers.extend(copy_deck.blockers.clone());
    blockers.extend(performance.blockers.clone());
    blockers.extend(accessibility.blockers.clone());
    blockers.extend(policy.blockers.clone());
    blockers.extend(style_guide.blockers.clone());
    blockers.extend(world_blueprint.blockers.clone());
    blockers.extend(onboarding.blockers.clone());
    blockers.extend(showcase.blockers.clone());
    blockers.extend(telemetry.blockers.clone());
    blockers.extend(monetization.blockers.clone());
    blockers.extend(social.blockers.clone());
    blockers.extend(liveops.blockers.clone());
    blockers.extend(persistence.blockers.clone());
    blockers.extend(asset_brief.blockers.clone());
    blockers.extend(trace.blockers.clone());
    blockers.extend(gameplay_critique.blockers.clone());
    blockers.extend(playtest_plan.blockers.clone());
    blockers.extend(memory.blockers.clone());
    blockers.sort();
    blockers.dedup();

    let mut warnings = architect.warnings;
    warnings.extend(tune.warnings);
    warnings.extend(handoff.warnings);
    warnings.extend(certification.warnings.clone());
    warnings.extend(simulation.warnings.clone());
    warnings.extend(feature_graph.warnings.clone());
    warnings.extend(balance.warnings.clone());
    warnings.extend(impact.warnings.clone());
    warnings.extend(contracts.warnings.clone());
    warnings.extend(authority.warnings.clone());
    warnings.extend(ux.warnings.clone());
    warnings.extend(copy_deck.warnings.clone());
    warnings.extend(performance.warnings.clone());
    warnings.extend(accessibility.warnings.clone());
    warnings.extend(policy.warnings.clone());
    warnings.extend(style_guide.warnings.clone());
    warnings.extend(world_blueprint.warnings.clone());
    warnings.extend(onboarding.warnings.clone());
    warnings.extend(showcase.warnings.clone());
    warnings.extend(telemetry.warnings.clone());
    warnings.extend(monetization.warnings.clone());
    warnings.extend(social.warnings.clone());
    warnings.extend(liveops.warnings.clone());
    warnings.extend(persistence.warnings.clone());
    warnings.extend(asset_brief.warnings.clone());
    warnings.extend(trace.warnings.clone());
    warnings.extend(gameplay_critique.warnings.clone());
    warnings.extend(playtest_plan.warnings.clone());
    warnings.extend(memory.warnings.clone());
    warnings.sort();
    warnings.dedup();

    let status = if !blockers.is_empty() {
        "blocked"
    } else if certification.ready_to_apply {
        "readyToApply"
    } else if certification.applied {
        "applied"
    } else {
        certification.verdict.as_str()
    }
    .to_string();

    let mut next_actions = certification.next_actions;
    if next_actions.is_empty() {
        next_actions = handoff.next_actions;
    }
    if gameplay_critique.verdict != "playableSlice" {
        for action in gameplay_critique.next_actions {
            if !action.mutates_studio
                && !next_actions
                    .iter()
                    .any(|existing| existing.command == action.command)
            {
                next_actions.push(action);
            }
        }
        next_actions.sort_by_key(|action| action.priority);
    }
    if !blockers.is_empty() {
        next_actions.retain(|action| !action.mutates_studio);
    }

    KickoffReport {
        schema_version: "rs.autopilot.kickoff.v1".into(),
        generated_at: now_stamp(),
        prompt: prompt.to_string(),
        run_dir: run_dir.to_string_lossy().to_string(),
        status,
        ready_to_apply: certification.ready_to_apply,
        safe_to_handoff: certification.safe_to_handoff,
        architecture_path: architecture_path.to_string_lossy().to_string(),
        architecture_markdown_path: architecture_markdown_path.to_string_lossy().to_string(),
        tune_manifest_path: tune_manifest_path.to_string_lossy().to_string(),
        tune_markdown_path: tune_markdown_path.to_string_lossy().to_string(),
        plan_path: run_dir.join("plan.json").to_string_lossy().to_string(),
        preview_path: run_dir.join("preview.json").to_string_lossy().to_string(),
        handoff_path: handoff_path.to_string_lossy().to_string(),
        certification_path: certification_path.to_string_lossy().to_string(),
        planner_pack_path: planner_pack_path.to_string_lossy().to_string(),
        planner_pack_markdown_path: planner_pack_markdown_path.to_string_lossy().to_string(),
        simulation_path: simulation_path.to_string_lossy().to_string(),
        simulation_markdown_path: simulation_markdown_path.to_string_lossy().to_string(),
        feature_graph_path: feature_graph_path.to_string_lossy().to_string(),
        feature_graph_markdown_path: feature_graph_markdown_path.to_string_lossy().to_string(),
        balance_path: balance_path.to_string_lossy().to_string(),
        balance_markdown_path: balance_markdown_path.to_string_lossy().to_string(),
        impact_path: impact_path.to_string_lossy().to_string(),
        impact_markdown_path: impact_markdown_path.to_string_lossy().to_string(),
        contracts_path: contracts_path.to_string_lossy().to_string(),
        contracts_markdown_path: contracts_markdown_path.to_string_lossy().to_string(),
        authority_path: authority_path.to_string_lossy().to_string(),
        authority_markdown_path: authority_markdown_path.to_string_lossy().to_string(),
        ux_path: ux_path.to_string_lossy().to_string(),
        ux_markdown_path: ux_markdown_path.to_string_lossy().to_string(),
        copy_deck_path: copy_deck_path.to_string_lossy().to_string(),
        copy_deck_markdown_path: copy_deck_markdown_path.to_string_lossy().to_string(),
        performance_path: performance_path.to_string_lossy().to_string(),
        performance_markdown_path: performance_markdown_path.to_string_lossy().to_string(),
        accessibility_path: accessibility_path.to_string_lossy().to_string(),
        accessibility_markdown_path: accessibility_markdown_path.to_string_lossy().to_string(),
        policy_path: policy_path.to_string_lossy().to_string(),
        policy_markdown_path: policy_markdown_path.to_string_lossy().to_string(),
        style_guide_path: style_guide_path.to_string_lossy().to_string(),
        style_guide_markdown_path: style_guide_markdown_path.to_string_lossy().to_string(),
        world_blueprint_path: world_blueprint_path.to_string_lossy().to_string(),
        world_blueprint_markdown_path: world_blueprint_markdown_path.to_string_lossy().to_string(),
        onboarding_path: onboarding_path.to_string_lossy().to_string(),
        onboarding_markdown_path: onboarding_markdown_path.to_string_lossy().to_string(),
        showcase_path: showcase_path.to_string_lossy().to_string(),
        showcase_markdown_path: showcase_markdown_path.to_string_lossy().to_string(),
        telemetry_path: telemetry_path.to_string_lossy().to_string(),
        telemetry_markdown_path: telemetry_markdown_path.to_string_lossy().to_string(),
        monetization_path: monetization_path.to_string_lossy().to_string(),
        monetization_markdown_path: monetization_markdown_path.to_string_lossy().to_string(),
        social_path: social_path.to_string_lossy().to_string(),
        social_markdown_path: social_markdown_path.to_string_lossy().to_string(),
        liveops_path: liveops_path.to_string_lossy().to_string(),
        liveops_markdown_path: liveops_markdown_path.to_string_lossy().to_string(),
        persistence_path: persistence_path.to_string_lossy().to_string(),
        persistence_markdown_path: persistence_markdown_path.to_string_lossy().to_string(),
        asset_brief_path: asset_brief_path.to_string_lossy().to_string(),
        asset_brief_markdown_path: asset_brief_markdown_path.to_string_lossy().to_string(),
        trace_path: trace_path.to_string_lossy().to_string(),
        trace_markdown_path: trace_markdown_path.to_string_lossy().to_string(),
        gameplay_critique_path: gameplay_critique_path.to_string_lossy().to_string(),
        gameplay_critique_markdown_path: gameplay_critique_markdown_path
            .to_string_lossy()
            .to_string(),
        playtest_plan_path: playtest_plan_path.to_string_lossy().to_string(),
        playtest_plan_markdown_path: playtest_plan_markdown_path.to_string_lossy().to_string(),
        memory_path: memory_path.to_string_lossy().to_string(),
        memory_markdown_path: memory_markdown_path.to_string_lossy().to_string(),
        blockers,
        warnings,
        next_actions,
    }
}

fn build_source_audit_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
) -> AppResult<SourceAuditReport> {
    let mut source_paths = plan
        .operations
        .iter()
        .filter_map(|operation| operation.source_path.clone())
        .collect::<Vec<_>>();
    source_paths.sort();
    source_paths.dedup();

    let mut findings = Vec::new();
    let mut scanned_bytes = 0u64;
    for source_path in &source_paths {
        let path = match safe_join(run_dir, source_path) {
            Ok(path) => path,
            Err(err) => {
                push_source_finding(
                    &mut findings,
                    SourceFindingSeverity::Blocker,
                    "unsafe-source-path",
                    source_path,
                    0,
                    "Generated source path escapes the run directory.",
                    &err.to_string(),
                );
                continue;
            }
        };
        if !path.exists() {
            push_source_finding(
                &mut findings,
                SourceFindingSeverity::Blocker,
                "missing-source",
                source_path,
                0,
                "Generated source file is missing.",
                &path.to_string_lossy(),
            );
            continue;
        }
        let source = std::fs::read_to_string(&path)?;
        scanned_bytes += source.len() as u64;
        audit_luau_source(source_path, &source, &mut findings);
    }
    findings.sort_by(|left, right| {
        severity_rank(&left.severity)
            .cmp(&severity_rank(&right.severity))
            .then_with(|| left.path.cmp(&right.path))
            .then_with(|| left.line.cmp(&right.line))
            .then_with(|| left.rule.cmp(&right.rule))
    });
    let blockers = findings
        .iter()
        .filter(|finding| finding.severity == "blocker")
        .map(format_source_finding)
        .collect::<Vec<_>>();
    let warnings = findings
        .iter()
        .filter(|finding| finding.severity == "warning")
        .map(format_source_finding)
        .collect::<Vec<_>>();
    Ok(SourceAuditReport {
        schema_version: "rs.autopilot.source-audit.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        plan_path: plan_path.to_string_lossy().to_string(),
        ok: blockers.is_empty(),
        generated_file_count: source_paths.len(),
        scanned_bytes,
        findings,
        blockers,
        warnings,
    })
}

fn build_planner_pack_report(
    prompt: Option<&str>,
    run_dir: Option<&Path>,
    context_path: Option<&Path>,
    planner_pack_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<PlannerPackReport> {
    let inferred_prompt = resolve_planner_prompt(prompt, run_dir)?;
    let prompt = redact_text(&inferred_prompt);
    let mut warnings = Vec::new();
    if prompt != inferred_prompt {
        warnings.push("Secret-like text in the planner prompt was redacted.".into());
    }
    if let Some(run_dir) = run_dir {
        if !run_dir.exists() {
            return Err(AppError::Other(format!(
                "autopilot planner-pack run directory does not exist: {}",
                run_dir.display()
            )));
        }
        if !run_dir.is_dir() {
            return Err(AppError::Other(format!(
                "autopilot planner-pack run directory is not a directory: {}",
                run_dir.display()
            )));
        }
    }
    let context_path = context_path
        .map(Path::to_path_buf)
        .or_else(|| run_dir.map(|run_dir| run_dir.join("context.json")));
    let context = match &context_path {
        Some(path) if path.exists() => redact_json(&read_json_file(path)?),
        Some(path) => {
            warnings.push(format!("Context path was not found: {}", path.display()));
            json!({
                "status": "missing",
                "path": path.to_string_lossy(),
                "note": "Run `rs autopilot context` for live Studio context or use `rs autopilot kickoff` for offline planning artifacts."
            })
        }
        None => {
            warnings.push(
                "No context path or run directory was provided; planner pack contains only static contracts."
                    .into(),
            );
            json!({
                "status": "notProvided",
                "note": "No context path or run directory was provided."
            })
        }
    };
    let run_artifacts = collect_planner_run_artifacts(run_dir);
    let artifact_context = collect_planner_artifact_context(run_dir)?;
    if run_dir.is_some() && artifact_context.is_empty() {
        warnings.push("Run directory has no recognized Autopilot JSON artifacts.".into());
    }
    let output_contract = PlannerOutputContract {
        accepted_schema_version: PLAN_SCHEMA_VERSION.into(),
        required_top_level_fields: vec![
            "schemaVersion".into(),
            "id".into(),
            "createdAt".into(),
            "request".into(),
            "risk".into(),
            "preconditions".into(),
            "operations".into(),
            "artifacts".into(),
        ],
        rejected_outputs: vec![
            "Any response that is not strict JSON.".into(),
            "Any operation kind outside operationKinds.".into(),
            "Any generated Luau containing dynamic execution, direct HTTP, external numeric require, debug/env introspection, or secrets.".into(),
            "Any plan with destructive operations unless risk.level is danger and the user explicitly requested that risk.".into(),
            "Any claim that Studio was changed, uploaded, validated live, or published.".into(),
        ],
        post_generation_checks: vec![
            "rs autopilot explain --plan <plan.json> --format json".into(),
            "rs autopilot preview --plan <plan.json> --format json".into(),
            "rs autopilot audit-sources <run-dir> --format json".into(),
            "rs autopilot certify <run-dir> --format json".into(),
        ],
    };
    let safety_rules = planner_safety_rules();
    let agent_instructions = planner_agent_instructions();
    let operation_kinds = supported_operation_kinds();
    let recipe_catalog = recipe_catalog();
    let plan_schema_example = planner_plan_schema_example(&prompt);
    let expected_model_output = planner_expected_model_output(&plan_schema_example);
    let recommended_validation_commands = planner_validation_commands(run_dir);
    let model_prompt =
        render_model_prompt(&prompt, &safety_rules, &operation_kinds, &output_contract);
    Ok(PlannerPackReport {
        schema_version: "rs.autopilot.planner-pack.v1".into(),
        generated_at: now_stamp(),
        planner_pack_path: planner_pack_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        prompt,
        run_dir: run_dir.map(|path| path.to_string_lossy().to_string()),
        context_path: context_path.map(|path| path.to_string_lossy().to_string()),
        model_task: "Return exactly one strict rs.autopilot.plan.v1 JSON object. Do not mutate Studio, do not include prose outside JSON, and do not invent unsupported operation kinds.".into(),
        output_contract,
        safety_rules,
        agent_instructions,
        operation_kinds,
        recipe_catalog,
        plan_schema_example,
        expected_model_output,
        context,
        artifact_context,
        run_artifacts,
        blockers: Vec::new(),
        warnings,
        recommended_validation_commands,
        model_prompt,
    })
}

fn resolve_planner_prompt(prompt: Option<&str>, run_dir: Option<&Path>) -> AppResult<String> {
    if let Some(prompt) = prompt.filter(|prompt| !prompt.trim().is_empty()) {
        return Ok(prompt.trim().to_string());
    }
    if let Some(run_dir) = run_dir {
        let plan_path = run_dir.join("plan.json");
        if plan_path.exists() {
            let plan = read_plan(&plan_path)?;
            return Ok(plan.request.prompt);
        }
        let architect_path = run_dir.join("architect.json");
        if architect_path.exists() {
            if let Some(prompt) = read_json_file(&architect_path)?
                .get("prompt")
                .and_then(Value::as_str)
            {
                return Ok(prompt.to_string());
            }
        }
        let request_path = run_dir.join("request.json");
        if request_path.exists() {
            if let Some(prompt) = read_json_file(&request_path)?
                .get("prompt")
                .and_then(Value::as_str)
            {
                return Ok(prompt.to_string());
            }
        }
    }
    Ok("Create a safe, reviewable Roblox gameplay feature plan".into())
}

