fn planner_validation_commands(run_dir: Option<&Path>) -> Vec<String> {
    let plan_path = run_dir
        .map(|run_dir| run_dir.join("plan.json").to_string_lossy().to_string())
        .unwrap_or_else(|| "<run-dir>\\plan.json".into());
    let run_dir = run_dir
        .map(|run_dir| run_dir.to_string_lossy().to_string())
        .unwrap_or_else(|| "<run-dir>".into());
    vec![
        format!("rs autopilot explain --plan {plan_path} --format json"),
        format!("rs autopilot preview --plan {plan_path} --format json"),
        format!("rs autopilot audit-sources {run_dir} --format json"),
        format!("rs autopilot handoff {run_dir} --format json"),
        format!("rs autopilot certify {run_dir} --format json"),
    ]
}

fn render_model_prompt(
    prompt: &str,
    safety_rules: &[String],
    operation_kinds: &[String],
    output_contract: &PlannerOutputContract,
) -> String {
    let mut out = String::new();
    out.push_str("You are generating an rs Autopilot plan for Roblox Studio.\n");
    out.push_str("Return exactly one strict JSON object and no prose outside JSON.\n\n");
    out.push_str("Creator request:\n");
    out.push_str(prompt);
    out.push_str("\n\nAccepted schema: ");
    out.push_str(&output_contract.accepted_schema_version);
    out.push_str("\nSupported operation kinds:\n");
    for kind in operation_kinds {
        out.push_str("- ");
        out.push_str(kind);
        out.push('\n');
    }
    out.push_str("\nSafety rules:\n");
    for rule in safety_rules {
        out.push_str("- ");
        out.push_str(rule);
        out.push('\n');
    }
    out.push_str("\nThe plan will be rejected unless it validates with rs autopilot explain, preview, audit-sources, and certify.\n");
    out
}

fn audit_luau_source(path: &str, source: &str, findings: &mut Vec<SourceAuditFinding>) {
    let lines = source.lines().collect::<Vec<_>>();
    for (index, line) in lines.iter().enumerate() {
        let line_number = index + 1;
        let lower = line.to_ascii_lowercase();
        let compact = lower.split_whitespace().collect::<String>();
        if lower.contains("loadstring") {
            push_source_finding(
                findings,
                SourceFindingSeverity::Blocker,
                "dynamic-code-execution",
                path,
                line_number,
                "Generated scripts must not execute dynamic Luau strings.",
                line,
            );
        }
        if lower.contains("getfenv") || lower.contains("setfenv") || lower.contains("debug.") {
            push_source_finding(
                findings,
                SourceFindingSeverity::Blocker,
                "runtime-introspection",
                path,
                line_number,
                "Generated scripts must not use environment or debug-library introspection.",
                line,
            );
        }
        if compact.contains("getservice(\"httpservice\")") || compact.contains("httpservice:") {
            push_source_finding(
                findings,
                SourceFindingSeverity::Blocker,
                "network-call",
                path,
                line_number,
                "Generated Studio gameplay scripts must not make direct HTTP calls.",
                line,
            );
        }
        if numeric_require_target(line).is_some() {
            push_source_finding(
                findings,
                SourceFindingSeverity::Blocker,
                "external-module-require",
                path,
                line_number,
                "Generated scripts must not require external numeric module assets.",
                line,
            );
        }
        if contains_secret_marker(&lower) {
            push_source_finding(
                findings,
                SourceFindingSeverity::Blocker,
                "secret-marker",
                path,
                line_number,
                "Generated scripts must not contain secret, token, key, or password markers.",
                line,
            );
        }
        if compact.contains("getservice(\"datastoreservice\")") {
            push_source_finding(
                findings,
                SourceFindingSeverity::Warning,
                "datastore-permission",
                path,
                line_number,
                "DataStore usage requires published-place/API-services readiness before live validation.",
                line,
            );
        }
        if compact.contains("getservice(\"marketplaceservice\")") {
            push_source_finding(
                findings,
                SourceFindingSeverity::Warning,
                "marketplace-permission",
                path,
                line_number,
                "Marketplace operations require product IDs and live monetization review.",
                line,
            );
        }
        if compact.contains("getservice(\"teleportservice\")") {
            push_source_finding(
                findings,
                SourceFindingSeverity::Warning,
                "teleport-permission",
                path,
                line_number,
                "Teleport operations require destination place review.",
                line,
            );
        }
        if lower.contains("_g.") {
            push_source_finding(
                findings,
                SourceFindingSeverity::Info,
                "global-hook",
                path,
                line_number,
                "Script uses an _G integration hook; verify cooperating systems are present.",
                line,
            );
        }
        if lower.contains("while true do") && !loop_window_has_wait(&lines, index) {
            push_source_finding(
                findings,
                SourceFindingSeverity::Blocker,
                "unbounded-loop",
                path,
                line_number,
                "Unbounded loops must yield with task.wait or wait.",
                line,
            );
        }
    }
}

fn loop_window_has_wait(lines: &[&str], start: usize) -> bool {
    lines.iter().skip(start).take(12).any(|line| {
        let lower = line.to_ascii_lowercase();
        lower.contains("task.wait") || lower.contains("wait(")
    })
}

fn numeric_require_target(line: &str) -> Option<String> {
    let lower = line.to_ascii_lowercase();
    let start = lower.find("require(")?;
    let mut chars = line[start + "require(".len()..].chars();
    let first = chars.find(|ch| !ch.is_whitespace())?;
    if first.is_ascii_digit() {
        Some(first.to_string())
    } else {
        None
    }
}

fn contains_secret_marker(lower_line: &str) -> bool {
    [
        "api_key",
        "apikey",
        "roblox_api_key",
        "access_token",
        "auth_token",
        "secret",
        "password",
    ]
    .iter()
    .any(|marker| lower_line.contains(marker))
}

fn push_source_finding(
    findings: &mut Vec<SourceAuditFinding>,
    severity: SourceFindingSeverity,
    rule: &str,
    path: &str,
    line: usize,
    message: &str,
    evidence: &str,
) {
    findings.push(SourceAuditFinding {
        severity: severity.as_str().into(),
        rule: rule.into(),
        path: path.into(),
        line,
        message: message.into(),
        evidence: evidence.trim().chars().take(180).collect(),
    });
}

fn format_source_finding(finding: &SourceAuditFinding) -> String {
    format!(
        "{}:{} {}: {}",
        finding.path, finding.line, finding.rule, finding.message
    )
}

fn severity_rank(severity: &str) -> u8 {
    match severity {
        "blocker" => 0,
        "warning" => 1,
        "info" => 2,
        _ => 3,
    }
}

fn shell_display_arg(value: &str) -> String {
    value.replace('"', "\\\"")
}

fn build_certification_report(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
    certification_path: &Path,
    markdown_path: Option<&Path>,
) -> AppResult<CertificationReport> {
    let coach = build_coach_report(run_dir, plan_path, plan);
    let mut gates = Vec::new();
    gates.push(certify_plan_gate(plan));
    gates.push(certify_generated_sources_gate(run_dir, plan));
    gates.push(certify_source_audit_gate(run_dir, plan_path, plan));
    gates.push(certify_preview_gate(run_dir, plan));
    gates.push(certify_preview_integrity_gate(run_dir, plan, run_dir));
    gates.push(certify_simulation_gate(run_dir, plan_path, plan));
    gates.push(certify_balance_gate(run_dir, plan_path, plan));
    gates.push(certify_trace_gate(run_dir, plan_path, plan));
    gates.push(certify_impact_gate(run_dir, plan_path, plan));
    gates.push(certify_contracts_gate(run_dir, plan_path, plan));
    gates.push(certify_authority_gate(run_dir, plan_path, plan));
    gates.push(certify_ux_gate(run_dir, plan_path, plan));
    gates.push(certify_copy_deck_gate(run_dir, plan_path, plan));
    gates.push(certify_performance_gate(run_dir, plan_path, plan));
    gates.push(certify_accessibility_gate(run_dir, plan_path, plan));
    gates.push(certify_policy_gate(run_dir, plan_path, plan));
    gates.push(certify_style_guide_gate(run_dir, plan_path, plan));
    gates.push(certify_world_blueprint_gate(run_dir, plan_path, plan));
    gates.push(certify_onboarding_gate(run_dir, plan_path, plan));
    gates.push(certify_showcase_gate(run_dir, plan_path, plan));
    gates.push(certify_telemetry_gate(run_dir, plan_path, plan));
    gates.push(certify_monetization_gate(run_dir, plan_path, plan));
    gates.push(certify_social_gate(run_dir, plan_path, plan));
    gates.push(certify_liveops_gate(run_dir, plan_path, plan));
    gates.push(certify_persistence_gate(run_dir, plan_path, plan));
    gates.push(certify_asset_brief_gate(run_dir, plan_path, plan));
    gates.push(certify_bundle_gate(run_dir)?);
    gates.push(certify_handoff_gate(run_dir)?);
    gates.push(certify_apply_gate(run_dir)?);
    gates.push(certify_live_readiness_gate(plan));

    let mut blockers = coach.blockers.clone();
    let mut warnings = coach.warnings.clone();
    for gate in &gates {
        match gate.status.as_str() {
            "fail" => blockers.push(format!("{}: {}", gate.name, gate.message)),
            "warn" => warnings.push(format!("{}: {}", gate.name, gate.message)),
            _ => {}
        }
    }
    blockers.sort();
    blockers.dedup();
    warnings.sort();
    warnings.dedup();

    let applied = gates.iter().any(|gate| {
        gate.name == "apply result"
            && gate.status == "pass"
            && gate.message.contains("applied successfully")
    });
    let bundle_pass = gate_status(&gates, "bundle verification") == Some("pass");
    let preview_pass = gate_status(&gates, "preview safety") == Some("pass");
    let integrity_ok = matches!(
        gate_status(&gates, "preview integrity"),
        Some("pass") | Some("warn")
    );
    let ready_to_apply =
        blockers.is_empty() && preview_pass && integrity_ok && bundle_pass && !applied;
    let safe_to_handoff = blockers.is_empty() && bundle_pass;
    let verdict = if !blockers.is_empty() {
        "fail"
    } else if !warnings.is_empty() {
        "warn"
    } else {
        "pass"
    }
    .to_string();

    let mut next_actions = Vec::new();
    if !blockers.is_empty() {
        next_actions.push(CoachAction {
            priority: 1,
            title: "Resolve certification blockers".into(),
            command: Some(format!(
                "rs autopilot handoff {} --format json",
                run_dir.to_string_lossy()
            )),
            reason:
                "Certification failed; refresh handoff and resolve failed gates before mutation."
                    .into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
    } else if ready_to_apply {
        let smoke_arg = apply_smoke_arg_for_plan(plan);
        next_actions.push(CoachAction {
            priority: 1,
            title: "Check live readiness".into(),
            command: Some("rs autopilot ready --timeout 90 --format json".into()),
            reason: "Certification is clean enough to proceed to live readiness before mutation."
                .into(),
            requires_live_studio: true,
            mutates_studio: false,
        });
        next_actions.push(CoachAction {
            priority: 2,
            title: "Apply with rollback and validation".into(),
            command: Some(format!(
                "rs autopilot apply --plan {} --yes --rollback-on-error --validate{smoke_arg}",
                plan_path.to_string_lossy()
            )),
            reason: "Keep the certified run behind explicit approval, rollback, and validation."
                .into(),
            requires_live_studio: true,
            mutates_studio: true,
        });
    } else if applied {
        next_actions.push(CoachAction {
            priority: 1,
            title: "Read the certified run report".into(),
            command: Some(format!("rs autopilot report {}", run_dir.to_string_lossy())),
            reason: "The run has already applied; inspect the durable report and changed paths."
                .into(),
            requires_live_studio: false,
            mutates_studio: false,
        });
    }
    next_actions.push(CoachAction {
        priority: 9,
        title: "Refresh certification".into(),
        command: Some(format!(
            "rs autopilot certify {} --format json",
            run_dir.to_string_lossy()
        )),
        reason: "Regenerate the go/no-go packet after fixing blockers or applying the run.".into(),
        requires_live_studio: false,
        mutates_studio: false,
    });
    if !blockers.is_empty() {
        next_actions.retain(|action| !action.mutates_studio);
    }

    let mut artifacts = coach.artifacts.clone();
    artifacts.insert(
        "certification".into(),
        certification_path.to_string_lossy().to_string(),
    );
    if let Some(markdown_path) = markdown_path {
        artifacts.insert(
            "certificationMarkdown".into(),
            markdown_path.to_string_lossy().to_string(),
        );
    }

    Ok(CertificationReport {
        schema_version: "rs.autopilot.certification.v1".into(),
        generated_at: now_stamp(),
        run_dir: run_dir.to_string_lossy().to_string(),
        certification_path: certification_path.to_string_lossy().to_string(),
        markdown_path: markdown_path.map(|path| path.to_string_lossy().to_string()),
        plan_id: plan.id.clone(),
        prompt: plan.request.prompt.clone(),
        verdict,
        ready_to_apply,
        safe_to_handoff,
        applied,
        gates,
        blockers,
        warnings,
        artifacts,
        next_actions,
    })
}

fn certify_plan_gate(plan: &AutopilotPlan) -> CertificationGate {
    match validate_plan(plan) {
        Ok(()) => CertificationGate {
            name: "plan schema".into(),
            status: "pass".into(),
            severity: "blocker".into(),
            message: format!("plan {} is structurally valid", plan.id),
            evidence: vec![format!("operations={}", plan.operations.len())],
            next_command: None,
        },
        Err(err) => CertificationGate {
            name: "plan schema".into(),
            status: "fail".into(),
            severity: "blocker".into(),
            message: err.to_string(),
            evidence: Vec::new(),
            next_command: None,
        },
    }
}

fn certify_generated_sources_gate(run_dir: &Path, plan: &AutopilotPlan) -> CertificationGate {
    let mut sources = Vec::new();
    let mut missing = Vec::new();
    for operation in &plan.operations {
        if let Some(source_path) = &operation.source_path {
            sources.push(source_path.clone());
            match safe_join(run_dir, source_path) {
                Ok(path) if path.exists() => {}
                Ok(path) => missing.push(path.to_string_lossy().to_string()),
                Err(err) => missing.push(err.to_string()),
            }
        }
    }
    sources.sort();
    sources.dedup();
    missing.sort();
    missing.dedup();
    if sources.is_empty() {
        CertificationGate {
            name: "generated sources".into(),
            status: "skip".into(),
            severity: "info".into(),
            message: "plan does not reference generated source files".into(),
            evidence: Vec::new(),
            next_command: None,
        }
    } else if missing.is_empty() {
        CertificationGate {
            name: "generated sources".into(),
            status: "pass".into(),
            severity: "blocker".into(),
            message: format!("{} generated source file(s) are present", sources.len()),
            evidence: sources,
            next_command: None,
        }
    } else {
        CertificationGate {
            name: "generated sources".into(),
            status: "fail".into(),
            severity: "blocker".into(),
            message: format!("{} generated source file(s) are missing", missing.len()),
            evidence: missing,
            next_command: Some(format!(
                "rs autopilot plan \"{}\" --out {}",
                shell_display_arg(&plan.request.prompt),
                run_dir.to_string_lossy()
            )),
        }
    }
}

fn certify_source_audit_gate(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
) -> CertificationGate {
    match build_source_audit_report(run_dir, plan_path, plan) {
        Ok(report) if report.ok => CertificationGate {
            name: "source audit".into(),
            status: if report.warnings.is_empty() {
                "pass".into()
            } else {
                "warn".into()
            },
            severity: if report.warnings.is_empty() {
                "blocker".into()
            } else {
                "warning".into()
            },
            message: if report.warnings.is_empty() {
                format!(
                    "{} generated source file(s) passed offline safety audit",
                    report.generated_file_count
                )
            } else {
                format!(
                    "{} generated source file(s) passed with {} warning(s)",
                    report.generated_file_count,
                    report.warnings.len()
                )
            },
            evidence: report
                .findings
                .iter()
                .map(|finding| {
                    format!(
                        "{}:{} {} {}",
                        finding.path, finding.line, finding.severity, finding.rule
                    )
                })
                .take(20)
                .collect(),
            next_command: Some(format!(
                "rs autopilot audit-sources {} --format json",
                run_dir.to_string_lossy()
            )),
        },
        Ok(report) => CertificationGate {
            name: "source audit".into(),
            status: "fail".into(),
            severity: "blocker".into(),
            message: format!(
                "generated source audit found {} blocker(s)",
                report.blockers.len()
            ),
            evidence: report.blockers,
            next_command: Some(format!(
                "rs autopilot audit-sources {} --format json",
                run_dir.to_string_lossy()
            )),
        },
        Err(err) => CertificationGate {
            name: "source audit".into(),
            status: "fail".into(),
            severity: "blocker".into(),
            message: err.to_string(),
            evidence: vec![plan_path.to_string_lossy().to_string()],
            next_command: None,
        },
    }
}

fn certify_preview_gate(run_dir: &Path, _plan: &AutopilotPlan) -> CertificationGate {
    let preview_path = run_dir.join("preview.json");
    if !preview_path.exists() {
        return CertificationGate {
            name: "preview safety".into(),
            status: "fail".into(),
            severity: "blocker".into(),
            message: "preview.json is missing".into(),
            evidence: vec![preview_path.to_string_lossy().to_string()],
            next_command: Some(format!(
                "rs autopilot preview --plan {}",
                run_dir.join("plan.json").to_string_lossy()
            )),
        };
    }
    match read_json_file(&preview_path) {
        Ok(preview) => {
            let safe = preview
                .get("safeToPreview")
                .and_then(Value::as_bool)
                .unwrap_or(false);
            let failed_preconditions = preview
                .get("preconditions")
                .and_then(Value::as_array)
                .map(|items| {
                    items
                        .iter()
                        .filter(|item| {
                            item.get("status")
                                .and_then(Value::as_str)
                                .is_some_and(|status| status == "fail")
                        })
                        .count()
                })
                .unwrap_or(0);
            if safe && failed_preconditions == 0 {
                CertificationGate {
                    name: "preview safety".into(),
                    status: "pass".into(),
                    severity: "blocker".into(),
                    message: "preview is safe and has no failed preconditions".into(),
                    evidence: vec![preview_path.to_string_lossy().to_string()],
                    next_command: None,
                }
            } else {
                CertificationGate {
                    name: "preview safety".into(),
                    status: "fail".into(),
                    severity: "blocker".into(),
                    message: format!(
                        "preview is not safe or has failed preconditions (failed={failed_preconditions})"
                    ),
                    evidence: vec![preview_path.to_string_lossy().to_string()],
                    next_command: Some(format!(
                        "rs autopilot preview --plan {} --live",
                        run_dir.join("plan.json").to_string_lossy()
                    )),
                }
            }
        }
        Err(err) => CertificationGate {
            name: "preview safety".into(),
            status: "fail".into(),
            severity: "blocker".into(),
            message: err.to_string(),
            evidence: vec![preview_path.to_string_lossy().to_string()],
            next_command: None,
        },
    }
}

