fn certify_simulation_gate(
    run_dir: &Path,
    plan_path: &Path,
    plan: &AutopilotPlan,
) -> CertificationGate {
    let simulation_path = run_dir.join("simulation.json");
    let report = if simulation_path.exists() {
        read_json_file(&simulation_path)
            .ok()
            .and_then(|value| serde_json::from_value::<SimulationReportValue>(value).ok())
    } else {
        build_simulation_report(run_dir, plan_path, plan, &simulation_path, None)
            .ok()
            .map(SimulationReportValue::from)
    };
    let Some(report) = report else {
        return CertificationGate {
            name: "playability simulation".into(),
            status: "warn".into(),
            severity: "warning".into(),
            message: "static player-journey simulation could not be evaluated".into(),
            evidence: vec![simulation_path.to_string_lossy().to_string()],
            next_command: Some(format!(
                "rs autopilot simulate --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        };
    };
    if report.status == "dryPlayable" {
        CertificationGate {
            name: "playability simulation".into(),
            status: "pass".into(),
            severity: "warning".into(),
            message: format!(
                "static player journey is dry-playable with score {}",
                report.score
            ),
            evidence: vec![simulation_path.to_string_lossy().to_string()],
            next_command: Some(format!(
                "rs autopilot simulate --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        }
    } else {
        CertificationGate {
            name: "playability simulation".into(),
            status: "warn".into(),
            severity: "warning".into(),
            message: format!(
                "static player journey is {} with score {}; live apply should wait for review of weak beats",
                report.status, report.score
            ),
            evidence: report
                .blockers
                .into_iter()
                .chain(report.warnings)
                .take(10)
                .collect(),
            next_command: Some(format!(
                "rs autopilot simulate --run-dir {} --format json",
                command_arg(run_dir.to_string_lossy().as_ref())
            )),
        }
    }
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct SimulationReportValue {
    status: String,
    score: u8,
    #[serde(default)]
    blockers: Vec<String>,
    #[serde(default)]
    warnings: Vec<String>,
}

impl From<SimulationReport> for SimulationReportValue {
    fn from(report: SimulationReport) -> Self {
        Self {
            status: report.status,
            score: report.score,
            blockers: report.blockers,
            warnings: report.warnings,
        }
    }
}

