fn build_save_data_scaffold_plan(
    options: &PlanOptions,
    manifest_value: Option<&Value>,
    prompt: &str,
) -> AppResult<AutopilotPlan> {
    let manifest = manifest_value
        .cloned()
        .map(serde_json::from_value::<NamedFeatureManifest>)
        .transpose()?;
    let name = manifest
        .and_then(|value| value.name)
        .unwrap_or_else(|| "PlayerData".to_string());
    let id = format!("autopilot-{}-{}", now_unix_seconds(), slug(&name));
    let mut operations = Vec::new();
    push_create(
        &mut operations,
        "op-001",
        "ReplicatedStorage",
        "Folder",
        &name,
    );
    push_create(
        &mut operations,
        "op-002",
        &format!("ReplicatedStorage.{name}"),
        "RemoteFunction",
        "GetProfile",
    );
    push_create(
        &mut operations,
        "op-003",
        &format!("ReplicatedStorage.{name}"),
        "RemoteEvent",
        "ProfileChanged",
    );
    operations.push(upsert_script_operation(
        "op-004",
        &format!("ReplicatedStorage.{name}.SaveConfig"),
        "ModuleScript",
        "generated/SaveConfig.module.lua",
    ));
    operations.push(upsert_script_operation(
        "op-005",
        "ServerScriptService.SaveDataServer",
        "Script",
        "generated/SaveDataServer.server.lua",
    ));
    operations.push(validation_operation(
        "op-006",
        &options.scope,
        &["refs", "duplicates"],
    ));
    operations.push(verifier_operation("op-007", "deps", &options.scope));
    operations.push(verifier_operation("op-008", "publishCheck", &options.scope));

    let mut plan = AutopilotPlan {
        schema_version: PLAN_SCHEMA_VERSION.into(),
        id,
        created_at: now_stamp(),
        request: AutopilotRequest {
            prompt: prompt.to_string(),
            scope: options.scope.clone(),
            studio: options.studio.clone(),
        },
        risk: AutopilotRisk {
            level: "review".into(),
            requires_approval: true,
            destructive: false,
            touches_scripts: true,
            touches_cloud_assets: false,
        },
        preconditions: vec![
            precondition("pathExists", "ReplicatedStorage"),
            precondition("pathExists", "ServerScriptService"),
        ],
        operations,
        artifacts: AutopilotArtifacts {
            generated_files_root: "generated".into(),
            report: "report.md".into(),
        },
    };
    plan.set_generated_source(
        "generated/SaveConfig.module.lua",
        "return {\n    dataStoreEnabled = false,\n    storeName = \"PlayerData_v1\",\n    defaults = {\n        Coins = 0,\n        Level = 1,\n    },\n}\n".into(),
    );
    plan.set_generated_source(
        "generated/SaveDataServer.server.lua",
        format!(
            "local DataStoreService = game:GetService(\"DataStoreService\")\nlocal Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n\nlocal folder = ReplicatedStorage:WaitForChild({:?})\nlocal config = require(folder:WaitForChild(\"SaveConfig\"))\nlocal getProfile = folder:WaitForChild(\"GetProfile\")\nlocal changed = folder:WaitForChild(\"ProfileChanged\")\nlocal profiles = {{}}\nlocal store = config.dataStoreEnabled and DataStoreService:GetDataStore(config.storeName) or nil\n\nlocal function copyDefaults()\n    local data = {{}}\n    for key, value in pairs(config.defaults) do\n        data[key] = value\n    end\n    return data\nend\n\nlocal function ensureLeaderstats(player, data)\n    local stats = player:FindFirstChild(\"leaderstats\") or Instance.new(\"Folder\")\n    stats.Name = \"leaderstats\"\n    stats.Parent = player\n    for key, value in pairs(data) do\n        if typeof(value) == \"number\" then\n            local stat = stats:FindFirstChild(key) or Instance.new(\"IntValue\")\n            stat.Name = key\n            stat.Value = value\n            stat.Parent = stats\n        end\n    end\nend\n\nlocal function loadProfile(player)\n    local data = copyDefaults()\n    if store then\n        local ok, saved = pcall(function()\n            return store:GetAsync(tostring(player.UserId))\n        end)\n        if ok and type(saved) == \"table\" then\n            for key, value in pairs(saved) do\n                data[key] = value\n            end\n        end\n    end\n    profiles[player.UserId] = data\n    ensureLeaderstats(player, data)\n    changed:FireClient(player, data)\nend\n\nlocal function saveProfile(player)\n    local data = profiles[player.UserId]\n    if store and data then\n        pcall(function()\n            store:SetAsync(tostring(player.UserId), data)\n        end)\n    end\n    profiles[player.UserId] = nil\nend\n\nPlayers.PlayerAdded:Connect(loadProfile)\nPlayers.PlayerRemoving:Connect(saveProfile)\ngetProfile.OnServerInvoke = function(player)\n    return profiles[player.UserId] or copyDefaults()\nend\n\n_G.rsSetProfileValue = function(player, key, value)\n    profiles[player.UserId] = profiles[player.UserId] or copyDefaults()\n    profiles[player.UserId][key] = value\n    ensureLeaderstats(player, profiles[player.UserId])\n    changed:FireClient(player, profiles[player.UserId])\nend\n",
            name
        ),
    );
    Ok(plan)
}

trait WithGeneratedSources {
    fn with_shop_sources(self, name: &str, currency_name: &str, items: &[ShopItem]) -> Self;
    fn with_coin_sources(self, name: &str, currency_name: &str, coin_value: u32) -> Self;
}

impl WithGeneratedSources for AutopilotPlan {
    fn with_shop_sources(mut self, name: &str, currency_name: &str, items: &[ShopItem]) -> Self {
        let item_rows = items
            .iter()
            .map(|item| {
                format!(
                    "    {{ id = {:?}, displayName = {:?}, price = {} }},",
                    item.id, item.display_name, item.price
                )
            })
            .collect::<Vec<_>>()
            .join("\n");
        self.set_generated_source(
            "generated/ShopConfig.module.lua",
            format!(
                "local ShopConfig = {{}}\n\nShopConfig.currencyName = {:?}\nShopConfig.items = {{\n{}\n}}\n\nreturn ShopConfig\n",
                currency_name, item_rows
            ),
        );
        self.set_generated_source(
            "generated/ShopServer.server.lua",
            format!(
                "local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\n\nlocal shopFolder = ReplicatedStorage:WaitForChild({:?})\nlocal config = require(shopFolder:WaitForChild(\"ShopConfig\"))\nlocal purchaseRequested = shopFolder:WaitForChild(\"PurchaseRequested\")\nlocal getCatalog = shopFolder:WaitForChild(\"GetCatalog\")\n\nlocal balances = {{}}\n\nlocal function balanceFor(player)\n    balances[player.UserId] = balances[player.UserId] or 500\n    return balances[player.UserId]\nend\n\ngetCatalog.OnServerInvoke = function(player)\n    return {{ currencyName = config.currencyName, balance = balanceFor(player), items = config.items }}\nend\n\npurchaseRequested.OnServerEvent:Connect(function(player, itemId)\n    for _, item in ipairs(config.items) do\n        if item.id == itemId then\n            local balance = balanceFor(player)\n            if balance >= item.price then\n                balances[player.UserId] = balance - item.price\n                purchaseRequested:FireClient(player, true, itemId, balances[player.UserId])\n            else\n                purchaseRequested:FireClient(player, false, itemId, balance)\n            end\n            return\n        end\n    end\n    purchaseRequested:FireClient(player, false, tostring(itemId), balanceFor(player))\nend)\n",
                name
            ),
        );
        self.set_generated_source(
            "generated/ShopClient.client.lua",
            format!(
                "local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Players = game:GetService(\"Players\")\n\nlocal player = Players.LocalPlayer\nlocal gui = script.Parent\nlocal panel = gui:WaitForChild(\"Panel\")\nlocal button = panel:WaitForChild(\"BuyFirstItem\")\nlocal title = panel:WaitForChild(\"Title\")\nlocal shopFolder = ReplicatedStorage:WaitForChild({:?})\nlocal getCatalog = shopFolder:WaitForChild(\"GetCatalog\")\nlocal purchaseRequested = shopFolder:WaitForChild(\"PurchaseRequested\")\n\nlocal catalog = getCatalog:InvokeServer()\nlocal firstItem = catalog.items[1]\nif firstItem then\n    title.Text = string.format(\"%s - %d %s\", firstItem.displayName, firstItem.price, catalog.currencyName)\n    button.Text = \"Buy\"\nend\n\nbutton.Activated:Connect(function()\n    if firstItem then\n        purchaseRequested:FireServer(firstItem.id)\n    end\nend)\n\npurchaseRequested.OnClientEvent:Connect(function(ok, _itemId, balance)\n    button.Text = ok and (\"Bought - \" .. tostring(balance) .. \" left\") or \"Not enough\"\n    task.delay(1.2, function()\n        if button.Parent then\n            button.Text = \"Buy\"\n        end\n    end)\nend)\n\nplayer.CharacterAdded:Connect(function()\n    gui.Enabled = true\nend)\n",
                name
            ),
        );
        self
    }

    fn with_coin_sources(mut self, name: &str, currency_name: &str, coin_value: u32) -> Self {
        self.set_generated_source(
            "generated/CoinConfig.module.lua",
            format!(
                "return {{\n    currencyName = {:?},\n    coinValue = {},\n    respawnSeconds = 8,\n}}\n",
                currency_name, coin_value
            ),
        );
        self.set_generated_source(
            "generated/CoinServer.server.lua",
            format!(
                "local Players = game:GetService(\"Players\")\nlocal ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Workspace = game:GetService(\"Workspace\")\n\nlocal coinFolder = ReplicatedStorage:WaitForChild({:?})\nlocal config = require(coinFolder:WaitForChild(\"CoinConfig\"))\nlocal coinCollected = coinFolder:WaitForChild(\"CoinCollected\")\nlocal spawns = Workspace:WaitForChild(\"CoinSpawns\")\nlocal balances = {{}}\n\nlocal function award(player)\n    balances[player.UserId] = (balances[player.UserId] or 0) + config.coinValue\n    coinCollected:FireClient(player, balances[player.UserId])\nend\n\nfor _, coin in ipairs(spawns:GetChildren()) do\n    if coin:IsA(\"BasePart\") then\n        coin.Touched:Connect(function(hit)\n            local character = hit.Parent\n            local player = character and Players:GetPlayerFromCharacter(character)\n            if not player or coin:GetAttribute(\"Collected\") then\n                return\n            end\n            coin:SetAttribute(\"Collected\", true)\n            coin.Transparency = 1\n            coin.CanTouch = false\n            award(player)\n            task.delay(config.respawnSeconds, function()\n                if coin.Parent then\n                    coin:SetAttribute(\"Collected\", false)\n                    coin.Transparency = 0\n                    coin.CanTouch = true\n                end\n            end)\n        end)\n    end\nend\n",
                name
            ),
        );
        self
    }
}

impl AutopilotPlan {
    fn set_generated_source(&mut self, path: &str, source: String) {
        for operation in &mut self.operations {
            if operation.source_path.as_deref() == Some(path) {
                operation
                    .attributes
                    .insert("rsGeneratedSource".into(), Value::String(source.clone()));
            }
        }
    }
}

fn write_generated_files(plan: &AutopilotPlan, run_dir: &Path) -> AppResult<()> {
    for operation in &plan.operations {
        if let (Some(source_path), Some(Value::String(source))) = (
            operation.source_path.as_ref(),
            operation.attributes.get("rsGeneratedSource"),
        ) {
            let target = safe_join(run_dir, source_path)?;
            if let Some(parent) = target.parent() {
                std::fs::create_dir_all(parent)?;
            }
            std::fs::write(target, source)?;
        }
    }
    Ok(())
}

fn strip_generated_sources(mut plan: AutopilotPlan) -> AutopilotPlan {
    for operation in &mut plan.operations {
        operation.attributes.remove("rsGeneratedSource");
    }
    plan
}

fn read_plan(path: &Path) -> AppResult<AutopilotPlan> {
    serde_json::from_str(&std::fs::read_to_string(path)?).map_err(AppError::from)
}

fn validate_plan(plan: &AutopilotPlan) -> AppResult<()> {
    if plan.schema_version != PLAN_SCHEMA_VERSION {
        return Err(AppError::Other(format!(
            "unsupported autopilot plan schema '{}'",
            plan.schema_version
        )));
    }
    if plan.id.trim().is_empty() {
        return Err(AppError::Other("autopilot plan id is empty".into()));
    }
    if plan.request.scope.trim().is_empty() {
        return Err(AppError::Other("autopilot request scope is empty".into()));
    }
    if !matches!(
        plan.risk.level.as_str(),
        "safe" | "review" | "danger" | "refused"
    ) {
        return Err(AppError::Other(format!(
            "unsupported autopilot risk level '{}'",
            plan.risk.level
        )));
    }
    let mut ids = BTreeSet::new();
    let mut destructive_operations = Vec::new();
    for operation in &plan.operations {
        if operation.id.trim().is_empty() {
            return Err(AppError::Other("autopilot operation id is empty".into()));
        }
        if !ids.insert(operation.id.clone()) {
            return Err(AppError::Other(format!(
                "duplicate autopilot operation id '{}'",
                operation.id
            )));
        }
        validate_operation(operation)?;
        if operation.kind == "deleteInstance" {
            destructive_operations.push(operation.id.clone());
        }
    }
    if !destructive_operations.is_empty() {
        if plan.risk.level != "danger" || !plan.risk.destructive || !plan.risk.requires_approval {
            return Err(AppError::Other(format!(
                "deleteInstance operations require risk.level=danger, destructive=true, and requiresApproval=true: {}",
                destructive_operations.join(", ")
            )));
        }
    }
    Ok(())
}

fn validate_operation(operation: &AutopilotOperation) -> AppResult<()> {
    match operation.kind.as_str() {
        "createInstance" => {
            require_field(operation.parent_path.as_ref(), operation, "parentPath")?;
            require_field(operation.class_name.as_ref(), operation, "className")?;
            require_field(operation.name.as_ref(), operation, "name")?;
        }
        "setProperty" => {
            require_field(operation.path.as_ref(), operation, "path")?;
            if operation.properties.is_empty() {
                return Err(AppError::Other(format!(
                    "{} setProperty requires properties",
                    operation.id
                )));
            }
        }
        "setAttribute" => {
            require_field(operation.path.as_ref(), operation, "path")?;
            if operation.attributes.is_empty() {
                return Err(AppError::Other(format!(
                    "{} setAttribute requires attributes",
                    operation.id
                )));
            }
        }
        "setTags" => {
            require_field(operation.path.as_ref(), operation, "path")?;
        }
        "deleteInstance" => {
            require_field(operation.path.as_ref(), operation, "path")?;
        }
        "upsertScript" => {
            require_field(operation.path.as_ref(), operation, "path")?;
            require_field(operation.class_name.as_ref(), operation, "className")?;
            require_field(operation.source_path.as_ref(), operation, "sourcePath")?;
            if !matches!(
                operation.class_name.as_deref(),
                Some("Script" | "LocalScript" | "ModuleScript")
            ) {
                return Err(AppError::Other(format!(
                    "{} upsertScript className must be Script, LocalScript, or ModuleScript",
                    operation.id
                )));
            }
        }
        "validate" | "snapshot" | "repairTool" | "deps" | "publishCheck" => {
            require_field(operation.path.as_ref(), operation, "path")?;
        }
        "importImage" | "importAsset" => {
            if operation.file.is_none() {
                return Err(AppError::Other(format!(
                    "{} {} operation missing file",
                    operation.id, operation.kind
                )));
            }
        }
        "importUploaded" => {
            if operation.asset_id.is_none() {
                return Err(AppError::Other(format!(
                    "{} importUploaded operation missing assetId",
                    operation.id
                )));
            }
        }
        "uploadAsset" => {
            if operation.file.is_none() {
                return Err(AppError::Other(format!(
                    "{} uploadAsset operation missing file",
                    operation.id
                )));
            }
            upload_kind(operation)?;
        }
        "packageImport" => {
            if operation.file.is_none() {
                return Err(AppError::Other(format!(
                    "{} packageImport operation missing file",
                    operation.id
                )));
            }
        }
        "smoke" => {}
        other => {
            return Err(AppError::Other(format!(
                "unsupported autopilot operation kind '{other}' in {}",
                operation.id
            )))
        }
    }
    Ok(())
}

fn require_field(
    value: Option<&String>,
    operation: &AutopilotOperation,
    field: &str,
) -> AppResult<()> {
    if value.is_some_and(|value| !value.trim().is_empty()) {
        Ok(())
    } else {
        Err(AppError::Other(format!(
            "{} {} operation missing {field}",
            operation.id, operation.kind
        )))
    }
}

fn prompt_from_options(options: &PlanOptions, manifest: Option<&Value>) -> AppResult<String> {
    if let Some(prompt) = &options.prompt {
        if !prompt.trim().is_empty() {
            return Ok(prompt.trim().to_string());
        }
    }
    if let Some(manifest) = manifest {
        return Ok(format!(
            "Generate {} feature from manifest",
            manifest
                .get("kind")
                .and_then(Value::as_str)
                .unwrap_or("autopilot")
        ));
    }
    if let Some(recipe) = &options.recipe {
        return Ok(format!("Generate {recipe} feature"));
    }
    Err(AppError::Other(
        "autopilot plan requires a prompt, --recipe, or --from-manifest".into(),
    ))
}

fn compose_prompt(
    options: &ComposeOptions,
    manifest: Option<&ComposeManifest>,
) -> AppResult<String> {
    if let Some(prompt) = &options.prompt {
        if !prompt.trim().is_empty() {
            return Ok(prompt.trim().to_string());
        }
    }
    if let Some(prompt) = manifest.and_then(|manifest| manifest.prompt.as_ref()) {
        if !prompt.trim().is_empty() {
            return Ok(prompt.trim().to_string());
        }
    }
    if let Some(preset) = options
        .preset
        .as_ref()
        .or_else(|| manifest.and_then(|manifest| manifest.preset.as_ref()))
    {
        return Ok(format!("Compose {preset} Autopilot feature stack"));
    }
    if !options.recipes.is_empty() {
        return Ok(format!(
            "Compose Autopilot feature stack: {}",
            options.recipes.join(", ")
        ));
    }
    if let Some(manifest) = manifest {
        if !manifest.recipes.is_empty() {
            return Ok(format!(
                "Compose Autopilot feature stack: {}",
                manifest
                    .recipes
                    .iter()
                    .map(compose_recipe_label)
                    .collect::<Vec<_>>()
                    .join(", ")
            ));
        }
    }
    Err(AppError::Other(
        "autopilot compose requires a prompt, --preset, --recipe, or --from-manifest".into(),
    ))
}

fn compose_recipe_label(value: &Value) -> String {
    value
        .as_str()
        .map(str::to_string)
        .or_else(|| {
            value
                .as_object()
                .and_then(|object| object.get("kind").or_else(|| object.get("recipe")))
                .and_then(Value::as_str)
                .map(str::to_string)
        })
        .unwrap_or_else(|| "recipe".into())
}

fn resolve_tune_recipes(options: &TuneOptions, prompt: &str) -> AppResult<Vec<String>> {
    let mut recipes = Vec::new();
    if let Some(preset) = &options.preset {
        recipes.extend(compose_preset_recipes(preset)?);
    }
    for recipe in &options.recipes {
        recipes.push(normalize_recipe(recipe)?);
    }
    if recipes.is_empty() {
        recipes.extend(compose_prompt_recipes(prompt)?);
    }
    Ok(dedup_recipe_names(recipes))
}

#[cfg(test)]
fn resolve_compose_recipes(
    options: &ComposeOptions,
    manifest: Option<&ComposeManifest>,
    prompt: &str,
) -> AppResult<Vec<String>> {
    Ok(
        resolve_compose_recipe_entries(options, manifest, None, prompt)?
            .into_iter()
            .map(|entry| entry.recipe)
            .collect(),
    )
}

fn resolve_compose_recipe_entries(
    options: &ComposeOptions,
    manifest: Option<&ComposeManifest>,
    manifest_value: Option<&Value>,
    prompt: &str,
) -> AppResult<Vec<ResolvedComposeRecipe>> {
    let mut recipes = Vec::new();
    if let Some(preset) = options
        .preset
        .as_ref()
        .or_else(|| manifest.and_then(|manifest| manifest.preset.as_ref()))
    {
        recipes.extend(
            compose_preset_recipes(preset)?
                .into_iter()
                .map(|recipe| resolved_compose_recipe(recipe, "preset", None)),
        );
    }
    if let Some(kind) = manifest.and_then(|manifest| manifest.kind.as_ref()) {
        if kind != "autopilotCompose" {
            if let Ok(preset_recipes) = compose_preset_recipes(kind) {
                recipes.extend(
                    preset_recipes
                        .into_iter()
                        .map(|recipe| resolved_compose_recipe(recipe, "manifest-preset", None)),
                );
            } else {
                recipes.push(resolved_compose_recipe(
                    normalize_recipe(kind)?,
                    "manifest-kind",
                    manifest_value.cloned(),
                ));
            }
        }
    }
    if let Some(manifest) = manifest {
        for recipe in &manifest.recipes {
            recipes.push(resolve_compose_manifest_recipe(recipe)?);
        }
    }
    for recipe in &options.recipes {
        recipes.push(resolved_compose_recipe(
            normalize_recipe(recipe)?,
            "cli",
            None,
        ));
    }
    if recipes.is_empty() {
        recipes.extend(
            compose_prompt_recipes(prompt)?
                .into_iter()
                .map(|recipe| resolved_compose_recipe(recipe, "prompt", None)),
        );
    }

    let deduped = dedup_resolved_recipes(recipes);
    if deduped.is_empty() {
        return Err(AppError::Other(
            "autopilot compose could not resolve any recipes".into(),
        ));
    }
    Ok(deduped)
}

fn resolved_compose_recipe(
    recipe: String,
    source: &str,
    manifest: Option<Value>,
) -> ResolvedComposeRecipe {
    ResolvedComposeRecipe {
        recipe,
        source: source.into(),
        manifest,
    }
}

fn resolve_compose_manifest_recipe(value: &Value) -> AppResult<ResolvedComposeRecipe> {
    if let Some(recipe) = value.as_str() {
        return Ok(resolved_compose_recipe(
            normalize_recipe(recipe)?,
            "manifest",
            None,
        ));
    }
    let Some(object) = value.as_object() else {
        return Err(AppError::Other(
            "autopilot compose manifest recipes must be strings or objects".into(),
        ));
    };
    let recipe = object
        .get("kind")
        .or_else(|| object.get("recipe"))
        .and_then(Value::as_str)
        .ok_or_else(|| {
            AppError::Other("autopilot compose recipe object requires kind or recipe".into())
        })
        .and_then(normalize_recipe)?;
    let mut manifest = value.clone();
    if let Some(object) = manifest.as_object_mut() {
        object.insert("kind".into(), Value::String(recipe.clone()));
    }
    Ok(resolved_compose_recipe(recipe, "manifest", Some(manifest)))
}

fn dedup_recipe_names(recipes: Vec<String>) -> Vec<String> {
    let mut deduped = Vec::new();
    let mut seen = BTreeSet::new();
    for recipe in recipes {
        if seen.insert(recipe.clone()) {
            deduped.push(recipe);
        }
    }
    deduped
}

fn dedup_resolved_recipes(recipes: Vec<ResolvedComposeRecipe>) -> Vec<ResolvedComposeRecipe> {
    let mut deduped = Vec::new();
    let mut positions = BTreeMap::new();
    for recipe in recipes {
        if let Some(index) = positions.get(&recipe.recipe).copied() {
            if recipe.manifest.is_some() {
                deduped[index] = recipe;
            }
        } else {
            positions.insert(recipe.recipe.clone(), deduped.len());
            deduped.push(recipe);
        }
    }
    deduped
}

fn tune_recipe(recipe: &str, prompt: &str) -> AppResult<TunedRecipe> {
    let theme = tune_theme(prompt);
    let lower = prompt.to_ascii_lowercase();
    let mut knobs = Vec::new();
    let manifest = match recipe {
        "starterShop" => {
            let items = tuned_shop_items(&lower);
            knobs.push(tune_knob(
                "name",
                json!(format!("{}Shop", theme.prefix)),
                "Names the generated shop namespace from the prompt theme.",
            ));
            knobs.push(tune_knob(
                "currencyName",
                json!(theme.currency_name.clone()),
                "Keeps shop prices aligned with the selected economy currency.",
            ));
            knobs.push(tune_knob(
                "items",
                json!(items),
                "Creates a small first-session catalog that matches the requested loop.",
            ));
            json!({
                "kind": recipe,
                "name": format!("{}Shop", theme.prefix),
                "currencyName": theme.currency_name,
                "items": knobs.last().map(|knob| knob.value.clone()).unwrap_or_else(|| json!([]))
            })
        }
        "collectibleCoin" => {
            let coin_value = tuned_coin_value(&lower);
            knobs.push(tune_knob(
                "name",
                json!(format!("{}Coins", theme.prefix)),
                "Names the collectible currency folder from the prompt theme.",
            ));
            knobs.push(tune_knob(
                "currencyName",
                json!(theme.currency_name.clone()),
                "Uses the same currency label as the broader economy.",
            ));
            knobs.push(tune_knob(
                "coinValue",
                json!(coin_value),
                "Sets a deterministic pickup reward based on the requested pacing.",
            ));
            json!({
                "kind": recipe,
                "name": format!("{}Coins", theme.prefix),
                "currencyName": theme.currency_name,
                "coinValue": coin_value
            })
        }
        "tycoonCore" => {
            let (drop_value, upgrade_price) = tuned_tycoon_economy(&lower);
            knobs.push(tune_knob(
                "name",
                json!(format!("{}Tycoon", theme.prefix)),
                "Names the generated tycoon base from the prompt theme.",
            ));
            knobs.push(tune_knob(
                "currencyName",
                json!(theme.currency_name.clone()),
                "Uses a currency label that fits the requested genre.",
            ));
            knobs.push(tune_knob(
                "dropValue",
                json!(drop_value),
                "Controls how much the starter dropper awards per cycle.",
            ));
            knobs.push(tune_knob(
                "upgradePrice",
                json!(upgrade_price),
                "Controls the first upgrade target for early progression.",
            ));
            json!({
                "kind": recipe,
                "name": format!("{}Tycoon", theme.prefix),
                "currencyName": theme.currency_name,
                "dropValue": drop_value,
                "upgradePrice": upgrade_price
            })
        }
        "questSystem" => named_tune_manifest(recipe, format!("{}Quests", theme.prefix), &mut knobs),
        "roundManager" => named_tune_manifest(recipe, format!("{}Round", theme.prefix), &mut knobs),
        "inventorySystem" => {
            named_tune_manifest(recipe, format!("{}Inventory", theme.prefix), &mut knobs)
        }
        "adminPanel" => named_tune_manifest(recipe, "CreatorAdmin".into(), &mut knobs),
        "lobbyTeleport" => {
            named_tune_manifest(recipe, format!("{}Teleports", theme.prefix), &mut knobs)
        }
        "obbyCheckpoint" => {
            named_tune_manifest(recipe, format!("{}Obby", theme.prefix), &mut knobs)
        }
        "toolSystem" => named_tune_manifest(recipe, format!("{}Blaster", theme.prefix), &mut knobs),
        "enemyEncounter" => {
            named_tune_manifest(recipe, format!("{}Slime", theme.prefix), &mut knobs)
        }
        "npcInteraction" => {
            named_tune_manifest(recipe, format!("{}Guide", theme.prefix), &mut knobs)
        }
        "saveDataScaffold" => {
            named_tune_manifest(recipe, format!("{}PlayerData", theme.prefix), &mut knobs)
        }
        other => {
            return Err(AppError::Other(format!(
                "unsupported autopilot recipe '{other}'"
            )))
        }
    };
    Ok(TunedRecipe {
        recipe: recipe.into(),
        role: architect_recipe_role(recipe).into(),
        reason:
            "Selected for the requested build stack and converted into explicit manifest knobs."
                .into(),
        manifest,
        knobs,
    })
}

#[derive(Debug, Clone)]
struct TuneTheme {
    prefix: String,
    currency_name: String,
}

fn tune_theme(prompt: &str) -> TuneTheme {
    let lower = prompt.to_ascii_lowercase();
    let prefix = if contains_any_text(&lower, &["candy", "sweet", "sweets"]) {
        "Candy"
    } else if contains_any_text(&lower, &["space", "galaxy", "star", "planet"]) {
        "Space"
    } else if contains_any_text(&lower, &["pirate", "island", "treasure"]) {
        "Pirate"
    } else if contains_any_text(&lower, &["ninja", "dojo", "samurai"]) {
        "Ninja"
    } else if contains_any_text(&lower, &["pet", "pets", "animal"]) {
        "Pet"
    } else if contains_any_text(&lower, &["obby", "parkour", "checkpoint"]) {
        "Obby"
    } else if contains_any_text(&lower, &["combat", "enemy", "arena"]) {
        "Arena"
    } else {
        "Starter"
    };
    let currency_name = if lower.contains("gem") {
        "Gems"
    } else if lower.contains("gold") {
        "Gold"
    } else if lower.contains("ticket") {
        "Tickets"
    } else if lower.contains("cash") {
        "Cash"
    } else if contains_any_text(&lower, &["candy", "sweet", "sweets"]) {
        "Sweets"
    } else if contains_any_text(&lower, &["space", "galaxy", "star", "planet"]) {
        "Stardust"
    } else if contains_any_text(&lower, &["pirate", "treasure"]) {
        "Doubloons"
    } else if lower.contains("tycoon") || lower.contains("factory") {
        "Cash"
    } else {
        "Coins"
    };
    TuneTheme {
        prefix: prefix.into(),
        currency_name: currency_name.into(),
    }
}

fn named_tune_manifest(recipe: &str, name: String, knobs: &mut Vec<TuneKnob>) -> Value {
    knobs.push(tune_knob(
        "name",
        json!(name.clone()),
        "Names the generated feature namespace from the prompt theme.",
    ));
    json!({
        "kind": recipe,
        "name": name
    })
}

fn tuned_shop_items(prompt: &str) -> Vec<Value> {
    if contains_any_text(prompt, &["combat", "enemy", "arena", "weapon", "blaster"]) {
        vec![
            json!({"id": "training_blaster", "displayName": "Training Blaster", "price": 150}),
            json!({"id": "shield_boost", "displayName": "Shield Boost", "price": 225}),
        ]
    } else if contains_any_text(prompt, &["tycoon", "factory", "dropper"]) {
        vec![
            json!({"id": "dropper_boost", "displayName": "Dropper Boost", "price": 100}),
            json!({"id": "collector_magnet", "displayName": "Collector Magnet", "price": 250}),
        ]
    } else if contains_any_text(prompt, &["obby", "parkour", "checkpoint", "speed"]) {
        vec![
            json!({"id": "speed_coil", "displayName": "Speed Coil", "price": 75}),
            json!({"id": "jump_boost", "displayName": "Jump Boost", "price": 125}),
        ]
    } else {
        vec![
            json!({"id": "speed_boost", "displayName": "Speed Boost", "price": 100}),
            json!({"id": "double_jump", "displayName": "Double Jump", "price": 250}),
        ]
    }
}

fn tuned_coin_value(prompt: &str) -> u32 {
    if contains_any_text(prompt, &["premium", "rare", "gem", "gold"]) {
        5
    } else if contains_any_text(prompt, &["fast", "quick", "casual"]) {
        2
    } else {
        1
    }
}

fn tuned_tycoon_economy(prompt: &str) -> (u32, u32) {
    if contains_any_text(prompt, &["easy", "fast", "quick", "casual"]) {
        (20, 75)
    } else if contains_any_text(prompt, &["hard", "grind", "grindy"]) {
        (5, 150)
    } else if contains_any_text(prompt, &["premium", "rich", "rare"]) {
        (25, 250)
    } else {
        (10, 100)
    }
}

fn tune_knob(name: &str, value: Value, reason: &str) -> TuneKnob {
    TuneKnob {
        name: name.into(),
        value,
        reason: reason.into(),
    }
}

fn contains_any_text(text: &str, terms: &[&str]) -> bool {
    terms.iter().any(|term| text.contains(term))
}

fn compose_preset_recipes(preset: &str) -> AppResult<Vec<String>> {
    let recipes = match preset.trim().to_ascii_lowercase().as_str() {
        "fullstartergame" | "full-starter-game" | "starter-game" | "complete-game"
        | "vertical-slice" => vec![
            "starterShop",
            "collectibleCoin",
            "questSystem",
            "roundManager",
            "inventorySystem",
            "lobbyTeleport",
            "obbyCheckpoint",
            "toolSystem",
            "enemyEncounter",
            "npcInteraction",
            "saveDataScaffold",
        ],
        "monetizedprototype" | "monetized-prototype" | "economy" => vec![
            "starterShop",
            "collectibleCoin",
            "inventorySystem",
            "saveDataScaffold",
        ],
        "adventurehub" | "adventure-hub" | "hub" => vec![
            "npcInteraction",
            "questSystem",
            "lobbyTeleport",
            "obbyCheckpoint",
            "toolSystem",
            "enemyEncounter",
        ],
        "tycoonprototype" | "tycoon-prototype" | "tycoon" | "factory" => vec![
            "tycoonCore",
            "starterShop",
            "saveDataScaffold",
            "adminPanel",
        ],
        "systemsbackbone" | "systems-backbone" | "backbone" => {
            vec!["saveDataScaffold", "inventorySystem", "adminPanel"]
        }
        other => {
            return Err(AppError::Other(format!(
                "unsupported autopilot compose preset '{other}'"
            )))
        }
    };
    Ok(recipes.into_iter().map(str::to_string).collect())
}

fn compose_prompt_recipes(prompt: &str) -> AppResult<Vec<String>> {
    let lower = prompt.to_ascii_lowercase();
    if lower.contains("tycoon") || lower.contains("dropper") || lower.contains("factory") {
        return compose_preset_recipes("tycoonPrototype");
    }
    if lower.contains("full starter")
        || lower.contains("starter game")
        || lower.contains("complete game")
        || lower.contains("vertical slice")
        || lower.contains("prototype")
        || lower.contains("game loop")
    {
        return compose_preset_recipes("fullStarterGame");
    }

    let mut recipes = Vec::new();
    if lower.contains("shop") || lower.contains("store") || lower.contains("purchase") {
        recipes.push("starterShop".to_string());
    }
    if lower.contains("coin") || lower.contains("collectible") {
        recipes.push("collectibleCoin".to_string());
    }
    if lower.contains("quest") || lower.contains("objective") || lower.contains("mission") {
        recipes.push("questSystem".to_string());
    }
    if lower.contains("round") || lower.contains("match") || lower.contains("intermission") {
        recipes.push("roundManager".to_string());
    }
    if lower.contains("inventory") || lower.contains("backpack") || lower.contains("items") {
        recipes.push("inventorySystem".to_string());
    }
    if lower.contains("admin") || lower.contains("moderator") || lower.contains("command panel") {
        recipes.push("adminPanel".to_string());
    }
    if lower.contains("teleport") || lower.contains("lobby") || lower.contains("spawn pad") {
        recipes.push("lobbyTeleport".to_string());
    }
    if lower.contains("obby")
        || lower.contains("obstacle")
        || lower.contains("checkpoint")
        || lower.contains("parkour")
        || lower.contains("course")
    {
        recipes.push("obbyCheckpoint".to_string());
    }
    if lower.contains("tycoon")
        || lower.contains("dropper")
        || lower.contains("collector")
        || lower.contains("factory")
    {
        recipes.push("tycoonCore".to_string());
    }
    if lower.contains("tool")
        || lower.contains("weapon")
        || lower.contains("blaster")
        || lower.contains("equip")
    {
        recipes.push("toolSystem".to_string());
    }
    if lower.contains("enemy")
        || lower.contains("enemies")
        || lower.contains("combat")
        || lower.contains("monster")
        || lower.contains("slime")
    {
        recipes.push("enemyEncounter".to_string());
    }
    if lower.contains("npc")
        || lower.contains("dialog")
        || lower.contains("dialogue")
        || lower.contains("proximity")
    {
        recipes.push("npcInteraction".to_string());
    }
    if lower.contains("save")
        || lower.contains("datastore")
        || lower.contains("data store")
        || lower.contains("leaderstats")
    {
        recipes.push("saveDataScaffold".to_string());
    }
    if recipes.is_empty() {
        compose_preset_recipes("fullStarterGame")
    } else {
        Ok(recipes)
    }
}

