fn render_mission_markdown(report: &MissionReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Mission\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Root: `{}`\n", report.root));
    out.push_str(&format!("- Runs indexed: {}\n", report.run_count));
    out.push_str(&format!("- Generated: `{}`\n", report.generated_at));
    if let Some(prompt) = &report.prompt {
        out.push_str(&format!("- Prompt: {}\n", prompt));
    }
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push('\n');
    if let Some(active_run) = &report.active_run {
        out.push_str("\n## Active Run\n\n");
        out.push_str(&format!("- Run: `{}`\n", active_run.run_dir));
        out.push_str(&format!("- Plan: `{}`\n", active_run.plan_id));
        out.push_str(&format!("- Status: `{}`\n", active_run.status));
        out.push_str(&format!("- Operations: {}\n", active_run.operation_count));
        if let (Some(ok), Some(verified), Some(count)) = (
            active_run.bundle_ok,
            active_run.bundle_verified,
            active_run.bundle_artifact_count,
        ) {
            out.push_str(&format!(
                "- Bundle: `{}` ({}/{})\n",
                if ok { "PASS" } else { "FAIL" },
                verified,
                count
            ));
        }
    }
    if !report.blockers.is_empty() {
        out.push_str("\n## Blockers\n\n");
        for blocker in &report.blockers {
            out.push_str(&format!("- {blocker}\n"));
        }
    }
    if !report.warnings.is_empty() {
        out.push_str("\n## Warnings\n\n");
        for warning in &report.warnings {
            out.push_str(&format!("- {warning}\n"));
        }
    }
    if !report.recommendations.is_empty() {
        out.push_str("\n## Recipe Recommendations\n\n");
        for recommendation in &report.recommendations {
            out.push_str(&format!(
                "- `{}`: {}\n  `{}`\n",
                recommendation.recipe, recommendation.summary, recommendation.command
            ));
        }
    }
    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n\n", action.priority, action.title));
        out.push_str(&format!("   {}\n", action.reason));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push('\n');
    }
    out.push_str("\n## Indexed Runs\n\n");
    for run in &report.runs {
        out.push_str(&format!(
            "- `{}` `{}` `{}`\n",
            run.status, run.plan_id, run.run_dir
        ));
    }
    out
}

fn write_memory_markdown(path: PathBuf, report: &MemoryReport) -> AppResult<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, render_memory_markdown(report))?;
    Ok(())
}

fn render_memory_markdown(report: &MemoryReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Project Memory\n\n");
    out.push_str(&format!("- Root: `{}`\n", report.root));
    out.push_str(&format!("- Runs indexed: {}\n", report.run_count));
    out.push_str(&format!("- Returned: {}\n", report.returned));
    out.push_str(&format!("- Generated: `{}`\n", report.generated_at));
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push('\n');
    if let Some(active_run) = &report.active_run {
        out.push_str("\n## Active Run\n\n");
        out.push_str(&format!("- Run: `{}`\n", active_run.run_dir));
        out.push_str(&format!("- Plan: `{}`\n", active_run.plan_id));
        out.push_str(&format!("- Status: `{}`\n", active_run.status));
        if let Some(command) = &active_run.next_command {
            out.push_str(&format!("- Next: `{command}`\n"));
        }
    }
    if !report.recipes.is_empty() {
        out.push_str("\n## Recipe Memory\n\n");
        for recipe in &report.recipes {
            out.push_str(&format!("- `{recipe}`\n"));
        }
    }
    if !report.gameplay_verdicts.is_empty() || !report.gameplay_gaps.is_empty() {
        out.push_str("\n## Gameplay Memory\n\n");
        if !report.gameplay_verdicts.is_empty() {
            out.push_str("Verdicts:\n");
            for (verdict, count) in &report.gameplay_verdicts {
                out.push_str(&format!("- `{verdict}`: {count}\n"));
            }
        }
        if !report.gameplay_gaps.is_empty() {
            out.push_str("\nGaps:\n");
            for gap in &report.gameplay_gaps {
                out.push_str(&format!(
                    "- `{}` `{}` `{}`: {}\n",
                    gap.severity, gap.category, gap.run_dir, gap.message
                ));
                if let Some(recipe) = &gap.suggested_recipe {
                    out.push_str(&format!("  - Suggested recipe: `{recipe}`\n"));
                }
                if let Some(command) = &gap.command {
                    out.push_str(&format!("  - Command: `{command}`\n"));
                }
            }
        }
    }
    if !report.created_paths.is_empty() {
        out.push_str("\n## Known Created Paths\n\n");
        for path in &report.created_paths {
            out.push_str(&format!("- `{path}`\n"));
        }
    }
    if !report.generated_files.is_empty() {
        out.push_str("\n## Generated Files\n\n");
        for path in &report.generated_files {
            out.push_str(&format!("- `{path}`\n"));
        }
    }
    if !report.blockers.is_empty() {
        out.push_str("\n## Blockers\n\n");
        for blocker in &report.blockers {
            out.push_str(&format!("- {blocker}\n"));
        }
    }
    if !report.warnings.is_empty() {
        out.push_str("\n## Warnings\n\n");
        for warning in &report.warnings {
            out.push_str(&format!("- {warning}\n"));
        }
    }
    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n\n", action.priority, action.title));
        out.push_str(&format!("   {}\n", action.reason));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push('\n');
    }
    out.push_str("\n## Run Summaries\n\n");
    for run in &report.run_summaries {
        let gameplay = match (&run.gameplay_verdict, run.gameplay_score) {
            (Some(verdict), Some(score)) => format!(" gameplay:{verdict}/{score}"),
            (Some(verdict), None) => format!(" gameplay:{verdict}"),
            _ => String::new(),
        };
        out.push_str(&format!(
            "- `{}` `{}` `{}` operations:{} generated:{}{}\n",
            run.status,
            run.plan_id,
            run.run_dir,
            run.operation_count,
            run.generated_files.len(),
            gameplay
        ));
    }
    out
}

