fn render_capability_atlas_markdown(report: &CapabilityAtlasReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Capability Atlas\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Root: `{}`\n", report.root));
    out.push_str(&format!("- Recipes: {}\n", report.recipes.len()));
    out.push_str(&format!("- Workflows: {}\n", report.workflows.len()));
    out.push_str(&format!("- Commands: {}\n", report.commands.len()));
    out.push_str(&format!(
        "- Safe act handlers: {}\n",
        report.safe_act_kinds.len()
    ));
    out.push_str(&format!("- Generated: `{}`\n", report.generated_at));
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push('\n');

    out.push_str("\n## Workflows\n\n");
    for workflow in &report.workflows {
        out.push_str(&format!("### {}\n\n", workflow.title));
        out.push_str(&format!("{}\n\n", workflow.when_to_use));
        out.push_str(&format!("- First command: `{}`\n", workflow.first_command));
        out.push_str(&format!("- Boundary: {}\n", workflow.safety_boundary));
        if !workflow.proof_artifacts.is_empty() {
            out.push_str("- Proof artifacts:\n");
            for artifact in &workflow.proof_artifacts {
                out.push_str(&format!("  - `{artifact}`\n"));
            }
        }
        if !workflow.follow_up_commands.is_empty() {
            out.push_str("- Follow-up commands:\n");
            for command in &workflow.follow_up_commands {
                out.push_str(&format!("  - `{command}`\n"));
            }
        }
        out.push('\n');
    }

    out.push_str("\n## Recipes\n\n");
    for recipe in &report.recipes {
        out.push_str(&format!("### `{}`\n\n", recipe.name));
        out.push_str(&format!("{}\n\n", recipe.summary));
        out.push_str(&format!("- Risk: `{}`\n", recipe.risk));
        out.push_str(&format!("- Aliases: `{}`\n", recipe.aliases.join("`, `")));
        out.push_str(&format!("- Creates: `{}`\n", recipe.creates.join("`, `")));
        out.push_str("- Use:\n");
        for command in &recipe.use_commands {
            out.push_str(&format!("  - `{command}`\n"));
        }
        out.push('\n');
    }

    out.push_str("\n## Key Commands\n\n");
    for command in &report.commands {
        out.push_str(&format!("### `{}`\n\n", command.command));
        out.push_str(&format!("{}\n\n", command.purpose));
        out.push_str(&format!("- Phase: `{}`\n", command.phase));
        out.push_str(&format!(
            "- Requires live Studio: `{}`\n",
            command.requires_live_studio
        ));
        out.push_str(&format!("- Mutates Studio: `{}`\n", command.mutates_studio));
        out.push_str(&format!("- Act supported: `{}`\n", command.act_supported));
        if !command.writes.is_empty() {
            out.push_str("- Writes:\n");
            for artifact in &command.writes {
                out.push_str(&format!("  - `{artifact}`\n"));
            }
        }
        out.push('\n');
    }

    out.push_str("\n## Safety Boundaries\n\n");
    for boundary in &report.safety_boundaries {
        out.push_str(&format!("- {boundary}\n"));
    }

    out.push_str("\n## Live Plugin Capabilities\n\n");
    for capability in &report.live_required_capabilities {
        out.push_str(&format!("- `{capability}`\n"));
    }

    out.push_str("\n## Supported Operation Kinds\n\n");
    for kind in &report.operation_kinds {
        out.push_str(&format!("- `{kind}`\n"));
    }

    out.push_str("\n## Examples\n\n");
    for example in &report.examples {
        out.push_str(&format!("### {}\n\n", example.title));
        out.push_str(&format!("- Prompt: {}\n", example.prompt));
        out.push_str(&format!("- Command: `{}`\n", example.command));
        out.push_str(&format!("- Why: {}\n", example.why));
        if !example.expected_artifacts.is_empty() {
            out.push_str("- Expected artifacts:\n");
            for artifact in &example.expected_artifacts {
                out.push_str(&format!("  - `{artifact}`\n"));
            }
        }
        out.push('\n');
    }

    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n\n", action.priority, action.title));
        out.push_str(&format!("   {}\n", action.reason));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push('\n');
    }
    out
}

fn print_capability_atlas_summary(report: &CapabilityAtlasReport) {
    println!("Autopilot capability atlas: {}", report.status);
    println!("Atlas: {}", report.atlas_path);
    if let Some(markdown) = &report.markdown_path {
        println!("Markdown: {markdown}");
    }
    println!(
        "Recipes: {} | Workflows: {} | Commands: {} | Safe act handlers: {}",
        report.recipes.len(),
        report.workflows.len(),
        report.commands.len(),
        report.safe_act_kinds.len()
    );
    println!("{}", report.agent_brief);
    if let Some(action) = report.next_actions.first() {
        println!("Next: {}", action.title);
        if let Some(command) = &action.command {
            println!("  {command}");
        }
    }
}

