fn render_intake_markdown(report: &IntakeReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Intake\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Confidence: `{}`\n", report.confidence));
    out.push_str(&format!("- Root: `{}`\n", report.root));
    out.push_str(&format!("- Generated: `{}`\n", report.generated_at));
    if let Some(prompt) = &report.prompt {
        out.push_str(&format!("- Prompt: {}\n", prompt));
    }
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push('\n');
    if let Some(intent) = &report.intent {
        out.push_str("\n## Interpreted Intent\n\n");
        out.push_str(&format!("- Genre: {}\n", intent.genre));
        out.push_str(&format!("- Core loop: {}\n", intent.core_loop));
        out.push_str(&format!("- Player promise: {}\n", intent.player_promise));
        if let Some(preset) = &intent.recommended_preset {
            out.push_str(&format!("- Recommended preset: `{preset}`\n"));
        }
    }
    if !report.recipe_stack.is_empty() {
        out.push_str("\n## Recipe Stack\n\n");
        for recipe in &report.recipe_stack {
            out.push_str(&format!(
                "- `{}` `{}`: {}\n",
                recipe.role, recipe.recipe, recipe.summary
            ));
            out.push_str(&format!("  - Reason: {}\n", recipe.reason));
        }
    }
    if !report.assumptions.is_empty() {
        out.push_str("\n## Assumptions\n\n");
        for assumption in &report.assumptions {
            out.push_str(&format!("- {assumption}\n"));
        }
    }
    if !report.clarifying_questions.is_empty() {
        out.push_str("\n## Clarifying Questions\n\n");
        for question in &report.clarifying_questions {
            out.push_str(&format!(
                "- `{}`: {}{}\n",
                question.id,
                question.question,
                if question.blocks_offline_planning {
                    " _(blocks offline planning)_"
                } else {
                    ""
                }
            ));
            out.push_str(&format!("  - Reason: {}\n", question.reason));
        }
    }
    if !report.acceptance_criteria.is_empty() {
        out.push_str("\n## Acceptance Criteria\n\n");
        for criterion in &report.acceptance_criteria {
            out.push_str(&format!("- {criterion}\n"));
        }
    }
    if !report.blockers.is_empty() {
        out.push_str("\n## Blockers\n\n");
        for blocker in &report.blockers {
            out.push_str(&format!("- {blocker}\n"));
        }
    }
    if !report.warnings.is_empty() {
        out.push_str("\n## Warnings\n\n");
        for warning in &report.warnings {
            out.push_str(&format!("- {warning}\n"));
        }
    }
    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n\n", action.priority, action.title));
        out.push_str(&format!("   {}\n", action.reason));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push('\n');
    }
    out
}

