fn write_runbook_markdown(path: PathBuf, report: &RunbookReport) -> AppResult<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, render_runbook_markdown(report))?;
    Ok(())
}

fn render_runbook_markdown(report: &RunbookReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Execution Runbook\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Verdict: `{}`\n", report.verdict));
    out.push_str(&format!(
        "- Safe prefix executable: `{}`\n",
        report.safe_to_run_prefix
    ));
    out.push_str(&format!(
        "- Safe prefix / gated suffix / unsupported: {} / {} / {}\n",
        report.safe_prefix_count, report.gated_suffix_count, report.unsupported_count
    ));
    if let Some(run_dir) = &report.run_dir {
        out.push_str(&format!("- Run: `{run_dir}`\n"));
    }
    if let Some(prompt) = &report.prompt {
        out.push_str(&format!("- Prompt: `{prompt}`\n"));
    }
    out.push_str(&format!(
        "- Command guard: `{}`\n",
        report.command_guard_path
    ));
    out.push_str(&format!("- Generated: `{}`\n", report.generated_at));
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push('\n');

    if !report.safe_prefix.is_empty() {
        out.push_str("\n## Safe Offline Prefix\n\n");
        for step in &report.safe_prefix {
            render_runbook_step_markdown(&mut out, step);
        }
    }
    if !report.gated_suffix.is_empty() {
        out.push_str("\n## Gated Suffix\n\n");
        for step in &report.gated_suffix {
            render_runbook_step_markdown(&mut out, step);
        }
    }
    if !report.stop_conditions.is_empty() {
        out.push_str("\n## Stop Conditions\n\n");
        for condition in &report.stop_conditions {
            out.push_str(&format!("- {condition}\n"));
        }
    }
    if !report.expected_artifacts.is_empty() {
        out.push_str("\n## Expected Artifacts\n\n");
        for artifact in &report.expected_artifacts {
            out.push_str(&format!("- `{artifact}`\n"));
        }
    }
    for (title, items) in [
        ("Safe To Say", &report.safe_to_say),
        ("Do Not Say", &report.do_not_say),
        ("Blockers", &report.blockers),
        ("Warnings", &report.warnings),
    ] {
        if !items.is_empty() {
            out.push_str(&format!("\n## {title}\n\n"));
            for item in items {
                out.push_str(&format!("- {item}\n"));
            }
        }
    }
    if !report.artifacts.is_empty() {
        out.push_str("\n## Artifacts\n\n");
        for (name, path) in &report.artifacts {
            out.push_str(&format!("- `{name}`: `{path}`\n"));
        }
    }
    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n\n", action.priority, action.title));
        out.push_str(&format!("   {}\n", action.reason));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push('\n');
    }
    out
}

fn render_runbook_step_markdown(out: &mut String, step: &RunbookStep) {
    out.push_str(&format!("### {}. {}\n\n", step.order, step.title));
    out.push_str(&format!("- Phase: `{}`\n", step.phase));
    out.push_str(&format!("- Command: `{}`\n", step.command));
    if step.command != step.source_command {
        out.push_str(&format!("- Source command: `{}`\n", step.source_command));
    }
    if let Some(kind) = &step.command_kind {
        out.push_str(&format!("- Command kind: `{kind}`\n"));
    }
    out.push_str(&format!("- Verdict: `{}`\n", step.verdict));
    out.push_str(&format!("- Reason: {}\n", step.reason));
    out.push_str(&format!("- Act supported: `{}`\n", step.act_supported));
    out.push_str(&format!(
        "- Requires live Studio: `{}`\n",
        step.requires_live_studio
    ));
    out.push_str(&format!("- Mutates Studio: `{}`\n", step.mutates_studio));
    if !step.expected_artifacts.is_empty() {
        out.push_str("- Expected artifacts:\n");
        for artifact in &step.expected_artifacts {
            out.push_str(&format!("  - `{artifact}`\n"));
        }
    }
    if !step.stop_if.is_empty() {
        out.push_str("- Stop if:\n");
        for condition in &step.stop_if {
            out.push_str(&format!("  - {condition}\n"));
        }
    }
    if !step.done_when.is_empty() {
        out.push_str("- Done when:\n");
        for condition in &step.done_when {
            out.push_str(&format!("  - {condition}\n"));
        }
    }
    out.push('\n');
}

fn print_runbook_summary(report: &RunbookReport) {
    println!("Autopilot runbook: {}", report.status);
    println!("Verdict: {}", report.verdict);
    println!("JSON: {}", report.runbook_path);
    if let Some(markdown) = &report.markdown_path {
        println!("Markdown: {markdown}");
    }
    println!("Command guard: {}", report.command_guard_path);
    println!(
        "Safe prefix: {} | Gated suffix: {} | Unsupported: {}",
        report.safe_prefix_count, report.gated_suffix_count, report.unsupported_count
    );
    for step in report.safe_prefix.iter().take(5) {
        println!("  - safe {} [{}]: {}", step.order, step.phase, step.command);
    }
    for step in report.gated_suffix.iter().take(5) {
        println!(
            "  - gated {} [{}]: {}",
            step.order, step.phase, step.source_command
        );
    }
    if let Some(action) = report.next_actions.first() {
        println!("\nNext: {}", action.title);
        if let Some(command) = &action.command {
            println!("{command}");
        }
    }
}

