fn render_flight_recorder_markdown(report: &FlightRecorderReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Flight Recorder\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Verdict: `{}`\n", report.verdict));
    out.push_str(&format!("- Run: `{}`\n", report.run_dir));
    out.push_str(&format!("- Events: {}\n", report.event_count));
    out.push_str(&format!("- Commands: {}\n", report.command_count));
    out.push_str(&format!("- Evidence: {}\n", report.evidence_count));
    out.push_str(&format!("- Blocker sources: {}\n", report.blocker_count));
    out.push_str(&format!("- Generated: `{}`\n", report.generated_at));
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push('\n');

    if !report.events.is_empty() {
        out.push_str("\n## Events\n\n");
        for event in &report.events {
            out.push_str(&format!(
                "- {}. `{}` [{}] `{}`",
                event.order, event.artifact, event.phase, event.status
            ));
            if let Some(verdict) = &event.verdict {
                out.push_str(&format!(" `{verdict}`"));
            }
            out.push_str(&format!(" - {}\n", event.summary));
        }
    }
    if !report.commands.is_empty() {
        out.push_str("\n## Recorded Commands\n\n");
        for command in &report.commands {
            out.push_str(&format!("### {}. `{}`\n\n", command.order, command.command));
            out.push_str(&format!("- Source: `{}`\n", command.source_artifact));
            if let Some(kind) = &command.command_kind {
                out.push_str(&format!("- Command kind: `{kind}`\n"));
            }
            out.push_str(&format!("- Verdict: `{}`\n", command.verdict));
            out.push_str(&format!("- Act supported: `{}`\n", command.act_supported));
            out.push_str(&format!(
                "- Requires live Studio: `{}`\n",
                command.requires_live_studio
            ));
            out.push_str(&format!("- Mutates Studio: `{}`\n", command.mutates_studio));
            if !command.expected_artifacts.is_empty() {
                out.push_str("- Expected artifacts:\n");
                for artifact in &command.expected_artifacts {
                    out.push_str(&format!("  - `{artifact}`\n"));
                }
            }
            out.push('\n');
        }
    }
    if !report.evidence.is_empty() {
        out.push_str("\n## Evidence\n\n");
        for item in &report.evidence {
            out.push_str(&format!(
                "- `{}`: status `{}`, blockers {}, safe claims {}, forbidden claims {}\n",
                item.artifact,
                item.status,
                item.blocker_count,
                item.safe_claim_count,
                item.forbidden_claim_count
            ));
        }
    }
    for (title, items) in [
        ("Safe To Say", &report.safe_to_say),
        ("Do Not Say", &report.do_not_say),
        ("Blockers", &report.blockers),
        ("Warnings", &report.warnings),
    ] {
        if !items.is_empty() {
            out.push_str(&format!("\n## {title}\n\n"));
            for item in items {
                out.push_str(&format!("- {item}\n"));
            }
        }
    }
    if !report.artifacts.is_empty() {
        out.push_str("\n## Artifacts\n\n");
        for (name, path) in &report.artifacts {
            out.push_str(&format!("- `{name}`: `{path}`\n"));
        }
    }
    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n\n", action.priority, action.title));
        out.push_str(&format!("   {}\n", action.reason));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push('\n');
    }
    out
}

