fn render_best_friend_loop_markdown(report: &BestFriendLoopReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Best Friend Loop\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Verdict: `{}`\n", report.verdict));
    out.push_str(&format!("- Dry run: `{}`\n", report.dry_run));
    out.push_str(&format!(
        "- Executed steps: `{}/{}`\n",
        report.executed_steps, report.max_steps
    ));
    out.push_str(&format!("- Stopped reason: `{}`\n", report.stopped_reason));
    out.push_str(&format!(
        "- Current best-friend: `{}`\n",
        report.current_best_friend_path
    ));
    out.push_str(&format!("- Run: `{}`\n", report.run_dir));
    out.push_str(&format!("- Generated: `{}`\n", report.generated_at));

    out.push_str("\n## Steps\n\n");
    for step in &report.steps {
        out.push_str(&format!(
            "### {}. `{}` `{}`\n\n",
            step.order, step.status, step.verdict
        ));
        out.push_str(&format!("- Preview: `{}`\n", step.preview_path));
        if let Some(path) = &step.first_turn_path {
            out.push_str(&format!("- First turn: `{path}`\n"));
        }
        if let Some(path) = &step.act_path {
            out.push_str(&format!("- Act: `{path}`\n"));
        }
        if let Some(command) = &step.protected_command {
            out.push_str(&format!("- Protected command: `{command}`\n"));
        }
        if let Some(command) = &step.selected_inner_command {
            out.push_str(&format!("- Inner command: `{command}`\n"));
        }
        out.push_str(&format!("- Executed: `{}`\n", step.executed));
        if !step.blockers.is_empty() {
            out.push_str("- Blockers:\n");
            for blocker in &step.blockers {
                out.push_str(&format!("  - {blocker}\n"));
            }
        }
        if !step.warnings.is_empty() {
            out.push_str("- Warnings:\n");
            for warning in step.warnings.iter().take(12) {
                out.push_str(&format!("  - {warning}\n"));
            }
        }
        out.push('\n');
    }

    for (title, items) in [
        ("Safe To Say", &report.safe_to_say),
        ("Do Not Say", &report.do_not_say),
        ("Blockers", &report.blockers),
        ("Warnings", &report.warnings),
    ] {
        if !items.is_empty() {
            out.push_str(&format!("\n## {title}\n\n"));
            for item in items.iter().take(16) {
                out.push_str(&format!("- {item}\n"));
            }
        }
    }

    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push('\n');

    if !report.next_actions.is_empty() {
        out.push_str("\n## Next Actions\n\n");
        for action in &report.next_actions {
            out.push_str(&format!("{}. {}\n\n", action.priority, action.title));
            out.push_str(&format!("   {}\n", action.reason));
            if let Some(command) = &action.command {
                out.push_str(&format!("   `{command}`\n"));
            }
            out.push('\n');
        }
    }
    if !report.artifacts.is_empty() {
        out.push_str("\n## Artifacts\n\n");
        for (name, path) in &report.artifacts {
            out.push_str(&format!("- `{name}`: `{path}`\n"));
        }
    }
    out
}

