fn write_squad_review_markdown(path: PathBuf, report: &SquadReviewReport) -> AppResult<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, render_squad_review_markdown(report))?;
    Ok(())
}

fn render_squad_review_markdown(report: &SquadReviewReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Squad Review\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Verdict: `{}`\n", report.verdict));
    out.push_str(&format!("- Run: `{}`\n", report.run_dir));
    out.push_str(&format!("- Squad pack: `{}`\n", report.squad_pack_path));
    out.push_str(&format!(
        "- Assignments: `{}` total, `{}` complete, `{}` blocked, `{}` conflict(s)\n",
        report.assignment_count,
        report.complete_assignments,
        report.blocked_assignments,
        report.conflict_count
    ));
    out.push_str(&format!("- Generated: `{}`\n", report.generated_at));

    out.push_str("\n## Integration Prompt\n\n");
    out.push_str("```text\n");
    out.push_str(&report.integration_prompt);
    out.push_str("\n```\n");

    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push('\n');

    if !report.assignments.is_empty() {
        out.push_str("\n## Assignment Review\n\n");
        for assignment in &report.assignments {
            out.push_str(&format!(
                "### {} {} `{}`\n\n",
                assignment.id, assignment.title, assignment.review_status
            ));
            out.push_str(&format!("- Role: `{}`\n", assignment.role));
            if let Some(command) = &assignment.primary_command {
                out.push_str(&format!("- Primary command: `{command}`\n"));
            }
            out.push_str(&format!(
                "- Journal recorded: `{}`\n",
                assignment
                    .journal_recorded
                    .map(|value| value.to_string())
                    .unwrap_or_else(|| "missing".into())
            ));
            out.push_str(&format!(
                "- Artifacts: `{}` present, `{}` missing, `{}` manual\n",
                assignment.present_artifacts.len(),
                assignment.missing_artifacts.len(),
                assignment.manual_evidence.len()
            ));
            if !assignment.missing_artifacts.is_empty() {
                out.push_str("- Missing artifacts:\n");
                for artifact in &assignment.missing_artifacts {
                    out.push_str(&format!("  - `{artifact}`\n"));
                }
            }
            if let Some(command) = &assignment.next_command {
                out.push_str(&format!("- Next command: `{command}`\n"));
            }
        }
    }

    if !report.conflicts.is_empty() {
        out.push_str("\n## Conflicts\n\n");
        for conflict in &report.conflicts {
            out.push_str(&format!(
                "- `{}` {} `{}`: {}\n",
                conflict.id, conflict.kind, conflict.artifact, conflict.summary
            ));
        }
    }

    for (title, items) in [
        ("Safe To Say", &report.safe_to_say),
        ("Do Not Say", &report.do_not_say),
        ("Blockers", &report.blockers),
        ("Warnings", &report.warnings),
    ] {
        if !items.is_empty() {
            out.push_str(&format!("\n## {title}\n\n"));
            for item in items {
                out.push_str(&format!("- {item}\n"));
            }
        }
    }

    if !report.artifacts.is_empty() {
        out.push_str("\n## Artifacts\n\n");
        for (name, path) in &report.artifacts {
            out.push_str(&format!("- `{name}`: `{path}`\n"));
        }
    }

    if !report.next_actions.is_empty() {
        out.push_str("\n## Next Actions\n\n");
        for action in &report.next_actions {
            out.push_str(&format!("{}. {}\n\n", action.priority, action.title));
            out.push_str(&format!("   {}\n", action.reason));
            if let Some(command) = &action.command {
                out.push_str(&format!("   `{command}`\n"));
            }
            out.push('\n');
        }
    }
    out
}

