fn render_creator_demo_markdown(report: &CreatorDemoReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Creator Demo\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Verdict: `{}`\n", report.verdict));
    out.push_str(&format!("- Demo: `{}`\n", report.demo_title));
    out.push_str(&format!("- Dry run: `{}`\n", report.dry_run));
    out.push_str(&format!("- Source run: `{}`\n", report.run_dir));
    if let Some(recommended) = &report.recommended_run_dir {
        out.push_str(&format!("- Recommended run: `{recommended}`\n"));
    }
    out.push_str(&format!("- Generated: `{}`\n", report.generated_at));

    if let Some(message) = &report.creator_message {
        out.push_str("\n## Creator Message\n\n");
        out.push_str(message);
        out.push('\n');
    }

    if !report.talk_track.is_empty() {
        out.push_str("\n## Talk Track\n\n");
        for beat in &report.talk_track {
            out.push_str(&format!("### {} {}\n\n", beat.id, beat.title));
            out.push_str(&format!("{}\n", beat.script));
            out.push_str(&format!("- Source: `{}`\n", beat.source));
            if !beat.evidence.is_empty() {
                out.push_str("- Evidence:\n");
                for item in &beat.evidence {
                    out.push_str(&format!("  - `{item}`\n"));
                }
            }
            out.push('\n');
        }
    }

    if !report.proof_table.is_empty() {
        out.push_str("\n## Proof Table\n\n");
        for proof in &report.proof_table {
            out.push_str(&format!(
                "- `{}` `{}`: {}\n",
                proof.id, proof.status, proof.claim
            ));
            if !proof.evidence.is_empty() {
                out.push_str("  - Evidence:\n");
                for item in &proof.evidence {
                    out.push_str(&format!("    - `{item}`\n"));
                }
            }
            if !proof.missing.is_empty() {
                out.push_str("  - Missing:\n");
                for item in &proof.missing {
                    out.push_str(&format!("    - {item}\n"));
                }
            }
            if let Some(command) = &proof.next_command {
                out.push_str(&format!("  - Next: `{command}`\n"));
            }
        }
    }

    if !report.approval_boundary.is_empty() {
        out.push_str("\n## Approval Boundary\n\n");
        for item in &report.approval_boundary {
            out.push_str(&format!("- {item}\n"));
        }
    }

    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push('\n');

    for (title, items) in [
        ("Safe To Say", &report.safe_to_say),
        ("Do Not Say", &report.do_not_say),
        ("Blockers", &report.blockers),
        ("Warnings", &report.warnings),
    ] {
        if !items.is_empty() {
            out.push_str(&format!("\n## {title}\n\n"));
            for item in items {
                out.push_str(&format!("- {item}\n"));
            }
        }
    }

    if !report.artifacts.is_empty() {
        out.push_str("\n## Artifacts\n\n");
        for (name, path) in &report.artifacts {
            out.push_str(&format!("- `{name}`: `{path}`\n"));
        }
    }

    if !report.next_actions.is_empty() {
        out.push_str("\n## Next Actions\n\n");
        for action in &report.next_actions {
            out.push_str(&format!("{}. {}\n\n", action.priority, action.title));
            out.push_str(&format!("   {}\n", action.reason));
            if let Some(command) = &action.command {
                out.push_str(&format!("   `{command}`\n"));
            }
            out.push('\n');
        }
    }
    out
}

