fn render_act_markdown(report: &ActReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Act\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Verdict: `{}`\n", report.verdict));
    out.push_str(&format!("- Run: `{}`\n", report.run_dir));
    out.push_str(&format!("- Source: `{}`\n", report.source));
    out.push_str(&format!("- Dry run: `{}`\n", report.dry_run));
    out.push_str(&format!("- Executed: `{}`\n", report.executed));
    out.push_str(&format!("- Generated: `{}`\n", report.generated_at));
    if let Some(command) = &report.selected_command {
        out.push_str(&format!("- Selected command: `{command}`\n"));
    }
    if let Some(kind) = &report.command_kind {
        out.push_str(&format!("- Command kind: `{kind}`\n"));
    }
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push('\n');

    if !report.steps.is_empty() {
        out.push_str("\n## Steps\n\n");
        for step in &report.steps {
            out.push_str(&format!(
                "### {}. {} `{}`\n\n",
                step.id, step.title, step.status
            ));
            out.push_str(&format!("{}\n", step.summary));
            if let Some(command) = &step.command {
                out.push_str(&format!("- Command: `{command}`\n"));
            }
            if !step.artifacts.is_empty() {
                out.push_str("- Artifacts:\n");
                for artifact in &step.artifacts {
                    out.push_str(&format!("  - `{artifact}`\n"));
                }
            }
            if let Some(error) = &step.error {
                out.push_str(&format!("- Error: `{error}`\n"));
            }
            out.push('\n');
        }
    }
    if !report.expected_artifacts.is_empty() {
        out.push_str("\n## Expected Artifacts\n\n");
        for artifact in &report.expected_artifacts {
            out.push_str(&format!("- `{artifact}`\n"));
        }
    }
    if !report.present_artifacts.is_empty() {
        out.push_str("\n## Present Artifacts\n\n");
        for artifact in &report.present_artifacts {
            out.push_str(&format!("- `{artifact}`\n"));
        }
    }
    if !report.safe_to_say.is_empty() {
        out.push_str("\n## Safe To Say\n\n");
        for claim in &report.safe_to_say {
            out.push_str(&format!("- {claim}\n"));
        }
    }
    if !report.do_not_say.is_empty() {
        out.push_str("\n## Do Not Say\n\n");
        for claim in &report.do_not_say {
            out.push_str(&format!("- {claim}\n"));
        }
    }
    if !report.blockers.is_empty() {
        out.push_str("\n## Blockers\n\n");
        for blocker in &report.blockers {
            out.push_str(&format!("- {blocker}\n"));
        }
    }
    if !report.warnings.is_empty() {
        out.push_str("\n## Warnings\n\n");
        for warning in &report.warnings {
            out.push_str(&format!("- {warning}\n"));
        }
    }
    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n\n", action.priority, action.title));
        out.push_str(&format!("   {}\n", action.reason));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push('\n');
    }
    out
}

