fn render_contracts_markdown(report: &ContractsReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Remote Contracts\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Remotes: `{}`\n", report.remote_count));
    out.push_str(&format!(
        "- Complete contracts: `{}`\n",
        report.complete_contracts
    ));
    out.push_str(&format!(
        "- Incomplete contracts: `{}`\n",
        report.incomplete_contracts
    ));
    out.push_str(&format!("- Run: `{}`\n", report.run_dir));
    out.push_str(&format!("- Plan: `{}`\n", report.plan_path));
    out.push_str(&format!("- Generated: `{}`\n", report.generated_at));
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push('\n');

    if !report.contracts.is_empty() {
        out.push_str("\n## Contracts\n\n");
        for contract in &report.contracts {
            out.push_str(&format!(
                "### `{}` `{}`\n\n",
                contract.status, contract.path
            ));
            out.push_str(&format!("- Class: `{}`\n", contract.class_name));
            if !contract.directions.is_empty() {
                out.push_str(&format!(
                    "- Directions: `{}`\n",
                    contract.directions.join("`, `")
                ));
            }
            if !contract.endpoints.is_empty() {
                out.push_str("- Endpoints:\n");
                for endpoint in &contract.endpoints {
                    out.push_str(&format!(
                        "  - `{}` `{}` from `{}`\n",
                        endpoint.direction, endpoint.role, endpoint.source_path
                    ));
                    if !endpoint.evidence.is_empty() {
                        out.push_str(&format!(
                            "    - Evidence: `{}`\n",
                            endpoint.evidence.join("`, `")
                        ));
                    }
                }
            }
            if !contract.findings.is_empty() {
                out.push_str("- Findings:\n");
                for finding in &contract.findings {
                    out.push_str(&format!(
                        "  - `{}` `{}`: {}\n",
                        finding.severity, finding.category, finding.message
                    ));
                }
            }
            out.push('\n');
        }
    }

    if !report.scripts.is_empty() {
        out.push_str("\n## Scripts\n\n");
        for script in &report.scripts {
            if script.remote_refs.is_empty() {
                continue;
            }
            out.push_str(&format!("- `{}`", script.source_path));
            if let Some(path) = &script.script_path {
                out.push_str(&format!(" -> `{path}`"));
            }
            if !script.roles.is_empty() {
                out.push_str(&format!(" roles `{}`", script.roles.join("`, `")));
            }
            out.push('\n');
        }
    }

    if !report.findings.is_empty() {
        out.push_str("\n## Findings\n\n");
        for finding in &report.findings {
            out.push_str(&format!(
                "- `{}` `{}`: {}\n",
                finding.severity, finding.category, finding.message
            ));
            for evidence in &finding.evidence {
                out.push_str(&format!("  - Evidence: {evidence}\n"));
            }
            if let Some(command) = &finding.command {
                out.push_str(&format!("  - Command: `{command}`\n"));
            }
        }
    }

    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n\n", action.priority, action.title));
        out.push_str(&format!("   {}\n", action.reason));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push('\n');
    }
    out
}

