fn write_copy_deck_markdown(path: PathBuf, report: &CopyDeckReport) -> AppResult<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, render_copy_deck_markdown(report))?;
    Ok(())
}

fn render_copy_deck_markdown(report: &CopyDeckReport) -> String {
    let mut out = String::new();
    out.push_str("# Autopilot Copy Deck\n\n");
    out.push_str(&format!("- Status: `{}`\n", report.status));
    out.push_str(&format!("- Strings: `{}`\n", report.string_count));
    out.push_str(&format!("- Surfaces: `{}`\n", report.surface_count));
    out.push_str(&format!(
        "- Dynamic strings: `{}`\n",
        report.dynamic_string_count
    ));
    out.push_str(&format!("- Run: `{}`\n", report.run_dir));
    out.push_str(&format!("- Plan: `{}`\n", report.plan_path));
    out.push_str(&format!("- Generated: `{}`\n", report.generated_at));
    out.push_str("\n## Agent Brief\n\n");
    out.push_str(&report.agent_brief);
    out.push('\n');

    if !report.blockers.is_empty() {
        out.push_str("\n## Blockers\n\n");
        for blocker in &report.blockers {
            out.push_str(&format!("- {blocker}\n"));
        }
    }
    if !report.warnings.is_empty() {
        out.push_str("\n## Warnings\n\n");
        for warning in &report.warnings {
            out.push_str(&format!("- {warning}\n"));
        }
    }

    if !report.entries.is_empty() {
        out.push_str("\n## Copy Entries\n\n");
        out.push_str("| ID | Role | Text | Source |\n");
        out.push_str("| --- | --- | --- | --- |\n");
        for entry in &report.entries {
            let source = entry
                .studio_path
                .as_deref()
                .or(entry.source_path.as_deref())
                .unwrap_or("");
            let dynamic = if entry.dynamic { " dynamic" } else { "" };
            out.push_str(&format!(
                "| `{}` | `{}` | {} | `{}`{} |\n",
                entry.id,
                entry.role,
                markdown_table_cell(&entry.text),
                source,
                dynamic
            ));
        }
    }

    if !report.findings.is_empty() {
        out.push_str("\n## Findings\n\n");
        for finding in &report.findings {
            out.push_str(&format!(
                "- `{}` `{}`: {}\n",
                finding.severity, finding.category, finding.message
            ));
            for evidence in &finding.evidence {
                out.push_str(&format!("  - Evidence: {evidence}\n"));
            }
            if let Some(command) = &finding.command {
                out.push_str(&format!("  - Command: `{command}`\n"));
            }
        }
    }

    out.push_str("\n## Next Actions\n\n");
    for action in &report.next_actions {
        out.push_str(&format!("{}. {}\n\n", action.priority, action.title));
        out.push_str(&format!("   {}\n", action.reason));
        if let Some(command) = &action.command {
            out.push_str(&format!("   `{command}`\n"));
        }
        out.push('\n');
    }
    out
}

fn markdown_table_cell(value: &str) -> String {
    value.replace('|', "\\|").replace('\n', " ")
}

