fn read_json_file(path: &Path) -> AppResult<Value> {
    serde_json::from_str(&std::fs::read_to_string(path)?).map_err(AppError::from)
}

fn read_json_if_exists(path: &Path) -> AppResult<Option<Value>> {
    if path.exists() {
        read_json_file(path).map(Some)
    } else {
        Ok(None)
    }
}

fn write_json<T: Serialize>(path: PathBuf, value: &T) -> AppResult<()> {
    if let Some(parent) = path.parent() {
        std::fs::create_dir_all(parent)?;
    }
    std::fs::write(path, serde_json::to_string_pretty(value)?)?;
    Ok(())
}

fn default_run_dir(recipe: &str, prompt: &str) -> PathBuf {
    PathBuf::from(".rs")
        .join("autopilot")
        .join("runs")
        .join(format!(
            "{}-{}-{}",
            now_unix_seconds(),
            slug(recipe),
            slug(prompt)
        ))
}

fn default_tune_manifest_path(prompt: &str) -> PathBuf {
    PathBuf::from(".rs")
        .join("autopilot")
        .join("manifests")
        .join(format!(
            "{}-{}.autopilot-compose.json",
            now_unix_seconds(),
            slug(prompt)
        ))
}

fn now_unix_seconds() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map(|duration| duration.as_secs())
        .unwrap_or(0)
}

fn now_stamp() -> String {
    format!("unix:{}", now_unix_seconds())
}

fn slug(value: &str) -> String {
    let mut out = String::new();
    for ch in value.chars() {
        if ch.is_ascii_alphanumeric() {
            out.push(ch.to_ascii_lowercase());
        } else if !out.ends_with('-') {
            out.push('-');
        }
    }
    let trimmed = out.trim_matches('-');
    if trimmed.is_empty() {
        "run".into()
    } else {
        trimmed.chars().take(48).collect()
    }
}

fn vector3(x: f64, y: f64, z: f64) -> Value {
    json!(["Vector3", x, y, z])
}

fn color3(r: f64, g: f64, b: f64) -> Value {
    json!(["Color3", r, g, b])
}

fn udim2(x_scale: f64, x_offset: i64, y_scale: f64, y_offset: i64) -> Value {
    json!(["UDim2", x_scale, x_offset, y_scale, y_offset])
}

fn enum_value(enum_type: &str, enum_item: &str) -> Value {
    json!(["Enum", enum_type, enum_item])
}

fn to_lower_set(values: &[String]) -> BTreeSet<String> {
    values
        .iter()
        .flat_map(|value| value.split(','))
        .map(|value| value.trim().to_ascii_lowercase())
        .filter(|value| !value.is_empty())
        .collect()
}

fn operation_allowed(
    operation: &AutopilotOperation,
    only: &BTreeSet<String>,
    exclude: &BTreeSet<String>,
) -> bool {
    let kind = operation.kind.to_ascii_lowercase();
    if !only.is_empty() && !only.contains(&kind) && !only.contains(operation_group(&kind)) {
        return false;
    }
    if exclude.contains(&kind) || exclude.contains(operation_group(&kind)) {
        return false;
    }
    true
}

fn operation_group(kind: &str) -> &'static str {
    match kind {
        "upsertscript" => "scripts",
        "importimage" | "importasset" | "importuploaded" | "uploadasset" => "assets",
        "deleteinstance" => "deletes",
        _ => "ops",
    }
}

fn has_operation(plan: &AutopilotPlan, kind: &str) -> bool {
    plan.operations
        .iter()
        .any(|operation| operation.kind == kind)
}

fn join_studio_path(parent: &str, name: &str) -> String {
    if parent == "game" || parent == "." || parent.is_empty() {
        name.to_string()
    } else {
        format!("{parent}.{name}")
    }
}

fn relative_to_scope(scope: &str, path: &str) -> String {
    if scope == "game" || scope == "DataModel" {
        path.to_string()
    } else if path == scope {
        ".".into()
    } else if let Some(rest) = path.strip_prefix(&format!("{scope}.")) {
        rest.to_string()
    } else {
        path.to_string()
    }
}

fn split_parent_name(path: &str) -> AppResult<(String, String)> {
    let (parent, name) = path.rsplit_once('.').ok_or_else(|| {
        AppError::Other(format!(
            "Studio path '{path}' must include parent and child name"
        ))
    })?;
    Ok((parent.to_string(), name.to_string()))
}

fn script_file_name(name: &str, class_name: &str) -> String {
    let suffix = match class_name {
        "Script" => ".server.lua",
        "LocalScript" => ".client.lua",
        "ModuleScript" => ".module.lua",
        _ => ".lua",
    };
    format!("{name}{suffix}")
}

fn safe_join(root: &Path, relative: &str) -> AppResult<PathBuf> {
    let path = Path::new(relative);
    if path.is_absolute() {
        return Err(AppError::Other(format!(
            "autopilot artifact path must be relative: {relative}"
        )));
    }
    let mut out = root.to_path_buf();
    for component in path.components() {
        match component {
            std::path::Component::Normal(part) => out.push(part),
            std::path::Component::CurDir => {}
            _ => {
                return Err(AppError::Other(format!(
                    "autopilot artifact path escapes run directory: {relative}"
                )))
            }
        }
    }
    Ok(out)
}

fn redact_json(value: &Value) -> Value {
    match value {
        Value::String(text) => {
            let lower = text.to_ascii_lowercase();
            if lower.contains("api_key")
                || lower.contains("apikey")
                || lower.contains("token")
                || lower.contains("secret")
                || lower.contains("roblox_api_key")
            {
                Value::String("<redacted>".into())
            } else {
                Value::String(text.clone())
            }
        }
        Value::Array(values) => Value::Array(values.iter().map(redact_json).collect()),
        Value::Object(map) => Value::Object(
            map.iter()
                .map(|(key, value)| {
                    let lower = key.to_ascii_lowercase();
                    if lower.contains("api_key")
                        || lower.contains("apikey")
                        || lower.contains("token")
                        || lower.contains("secret")
                    {
                        (key.clone(), Value::String("<redacted>".into()))
                    } else {
                        (key.clone(), redact_json(value))
                    }
                })
                .collect(),
        ),
        _ => value.clone(),
    }
}

fn redact_text(text: &str) -> String {
    match redact_json(&Value::String(text.to_string())) {
        Value::String(value) => value,
        _ => "<redacted>".into(),
    }
}

