    fn write_applied_playable_run(name: &str, include_health_evidence: bool) -> PathBuf {
        let source_run = PathBuf::from("target").join(format!("{name}-source"));
        let patch_run = PathBuf::from("target").join(format!("{name}-patch"));
        let _ = std::fs::remove_dir_all(&source_run);
        let _ = std::fs::remove_dir_all(&patch_run);
        write_bundle_fixture(&source_run);
        improve(ImproveOptions {
            port: 7878,
            run_dir: Some(source_run),
            plan: None,
            out: Some(patch_run.clone()),
            markdown: None,
            no_markdown: true,
            recipes: vec!["tycoonCore".into()],
            max_recipes: 1,
            smoke: Some("regression".into()),
            json: false,
        })
        .unwrap();

        let plan = read_plan(&patch_run.join("plan.json")).unwrap();
        let rollback_path = patch_run.join("rollback-snapshot.json");
        write_json(rollback_path.clone(), &json!({"ok": true})).unwrap();
        let smoke_path = patch_run.join("smoke-regression.json");
        let validation_after = if include_health_evidence {
            json!({
                "path": "game",
                "summary": {"fail": 0, "warn": 0, "info": 0},
                "diagnostics": [],
                "warnings": []
            })
        } else {
            Value::Null
        };
        let smoke = if include_health_evidence {
            write_json(
                smoke_path.clone(),
                &json!({
                    "ok": true,
                    "steps": [
                        {"name": "validate", "ok": true, "durationMs": 1}
                    ]
                }),
            )
            .unwrap();
            json!({
                "suite": "regression",
                "ok": true,
                "artifact": smoke_path.to_string_lossy().to_string(),
                "error": null
            })
        } else {
            Value::Null
        };
        write_json(
            patch_run.join("apply.json"),
            &json!({
                "status": "applied",
                "planId": plan.id,
                "studio": null,
                "scope": "game",
                "applied": 3,
                "skipped": 0,
                "refused": 0,
                "changedPaths": ["Workspace.Tycoon"],
                "warnings": [],
                "rollbackArtifact": rollback_path.to_string_lossy().to_string(),
                "rollbackRestore": null,
                "validationAfter": validation_after,
                "smoke": smoke,
                "error": null
            }),
        )
        .unwrap();
        certify(CertifyOptions {
            run_dir: patch_run.clone(),
            out: None,
            markdown: None,
            no_markdown: true,
            json: false,
        })
        .unwrap();
        record_playtest(RecordPlaytestOptions {
            run_dir: patch_run.clone(),
            result: "passed".into(),
            evidence: vec!["cash increased, upgrade purchased, no Studio output errors".into()],
            notes: vec!["Play Solo completed tycoon loop".into()],
            scenarios: vec!["tycoonCore=passed".into()],
            out: None,
            markdown: None,
            no_markdown: true,
            json: false,
        })
        .unwrap();
        patch_run
    }

