    #[test]
    fn delete_instance_lowering_requires_force_and_writes_deleted_change() {
        let plan = minimal_delete_plan();
        let only = BTreeSet::new();
        let exclude = BTreeSet::new();

        let err = build_fix_plan_for_apply(&plan, &only, &exclude, false).unwrap_err();
        assert!(err.to_string().contains("requires --force"));

        let fix_plan = build_fix_plan_for_apply(&plan, &only, &exclude, true).unwrap();
        assert_eq!(fix_plan.changes.len(), 1);
        assert_eq!(fix_plan.changes[0]["kind"], "deleted");
        assert_eq!(fix_plan.changes[0]["path"], "OldFolder");
        assert_eq!(fix_plan.operations[0]["action"], "delete");
    }

