    #[test]
    fn redacts_secretish_values() {
        let value = json!({
            "apiKey": "abc",
            "nested": {"token": "def"},
            "prompt": "normal"
        });
        let redacted = redact_json(&value);
        assert_eq!(redacted["apiKey"], "<redacted>");
        assert_eq!(redacted["nested"]["token"], "<redacted>");
        assert_eq!(redacted["prompt"], "normal");
        assert!(looks_like_private_token("sk-testvalue"));
        assert!(!looks_like_private_token(
            "rs autopilot task-pack <run-dir> --format json"
        ));
    }

