    #[test]
    fn expanded_game_recipes_produce_valid_scripted_plans() {
        let options = PlanOptions {
            port: 7878,
            prompt: None,
            studio: None,
            scope: "game".into(),
            out: None,
            max_read_depth: 3,
            include_scripts: false,
            include_assets: false,
            recipe: None,
            from_manifest: None,
            json: false,
        };
        let inventory =
            build_inventory_system_plan(&options, Some(&json!({"name": "Inventory"})), "inventory")
                .unwrap();
        let admin =
            build_admin_panel_plan(&options, Some(&json!({"name": "Admin"})), "admin").unwrap();
        let teleport = build_lobby_teleport_plan(
            &options,
            Some(&json!({"name": "LobbyTeleports"})),
            "teleport",
        )
        .unwrap();
        let obby =
            build_obby_checkpoint_plan(&options, Some(&json!({"name": "ObbyCourse"})), "obby")
                .unwrap();
        let tycoon = build_tycoon_core_plan(
            &options,
            Some(&json!({"name": "TycoonBase", "currencyName": "Cash"})),
            "tycoon",
        )
        .unwrap();
        let tool =
            build_tool_system_plan(&options, Some(&json!({"name": "TrainingBlaster"})), "tool")
                .unwrap();
        let enemy =
            build_enemy_encounter_plan(&options, Some(&json!({"name": "TrainingSlime"})), "enemy")
                .unwrap();
        let npc =
            build_npc_interaction_plan(&options, Some(&json!({"name": "Guide"})), "npc").unwrap();
        let save = build_save_data_scaffold_plan(
            &options,
            Some(&json!({"name": "PlayerData"})),
            "save data",
        )
        .unwrap();

        for plan in [
            &inventory, &admin, &teleport, &obby, &tycoon, &tool, &enemy, &npc, &save,
        ] {
            validate_plan(plan).unwrap();
            assert!(plan.operations.iter().any(|op| op.kind == "upsertScript"));
            assert!(plan.operations.iter().any(|op| op.kind == "validate"));
            assert!(plan.operations.iter().any(|op| op.kind == "publishCheck"));
        }
        assert!(obby
            .operations
            .iter()
            .any(|op| op.path.as_deref() == Some("ServerScriptService.ObbyCheckpointServer")));
        assert!(tycoon
            .operations
            .iter()
            .any(|op| op.path.as_deref() == Some("ServerScriptService.TycoonServer")));
        assert!(enemy
            .operations
            .iter()
            .any(|op| op.path.as_deref() == Some("ServerScriptService.EnemyEncounterServer")));
    }

    #[test]
    fn compose_full_starter_game_builds_one_valid_plan() {
        let options = ComposeOptions {
            port: 7878,
            prompt: Some("build a full starter game loop".into()),
            studio: None,
            scope: "game".into(),
            out: None,
            preset: Some("fullStarterGame".into()),
            recipes: Vec::new(),
            from_manifest: None,
            smoke: Some("regression".into()),
            json: false,
        };
        let recipes =
            resolve_compose_recipes(&options, None, options.prompt.as_deref().unwrap()).unwrap();
        assert!(recipes.contains(&"starterShop".to_string()));
        assert!(recipes.contains(&"saveDataScaffold".to_string()));
        assert!(recipes.contains(&"obbyCheckpoint".to_string()));
        assert!(recipes.contains(&"enemyEncounter".to_string()));

        let plan = build_composite_plan(
            &options,
            options.prompt.as_deref().unwrap(),
            &recipes,
            options.smoke.as_deref(),
        )
        .unwrap();
        validate_plan(&plan).unwrap();

        let ids = plan
            .operations
            .iter()
            .map(|operation| operation.id.as_str())
            .collect::<BTreeSet<_>>();
        assert_eq!(ids.len(), plan.operations.len());
        assert_eq!(
            plan.operations
                .iter()
                .filter(|operation| operation.kind == "validate")
                .count(),
            1
        );
        assert!(plan.operations.iter().any(|operation| {
            operation.source_path.as_deref() == Some("generated/startershop/ShopServer.server.lua")
        }));
        assert!(plan
            .operations
            .iter()
            .any(|operation| operation.kind == "smoke"));

        let tycoon_options = ComposeOptions {
            preset: Some("tycoonPrototype".into()),
            ..options
        };
        let tycoon_recipes = resolve_compose_recipes(
            &tycoon_options,
            None,
            tycoon_options.prompt.as_deref().unwrap(),
        )
        .unwrap();
        assert_eq!(tycoon_recipes[0], "tycoonCore");
        assert!(tycoon_recipes.contains(&"saveDataScaffold".to_string()));
    }

    #[test]
    fn compose_manifest_recipe_objects_drive_per_recipe_tuning() {
        let manifest_value = json!({
            "kind": "autopilotCompose",
            "prompt": "make a candy tycoon",
            "recipes": [
                {
                    "kind": "tycoonCore",
                    "name": "CandyFactory",
                    "currencyName": "Sweets",
                    "dropValue": 25,
                    "upgradePrice": 75
                },
                {
                    "kind": "starterShop",
                    "name": "CandyShop",
                    "currencyName": "Sweets",
                    "items": [
                        {"id": "sugar_rush", "displayName": "Sugar Rush", "price": 50}
                    ]
                }
            ],
            "smoke": "regression"
        });
        let manifest: ComposeManifest = serde_json::from_value(manifest_value.clone()).unwrap();
        let options = ComposeOptions {
            port: 7878,
            prompt: None,
            studio: None,
            scope: "game".into(),
            out: None,
            preset: None,
            recipes: Vec::new(),
            from_manifest: None,
            smoke: None,
            json: false,
        };
        let prompt = compose_prompt(&options, Some(&manifest)).unwrap();
        let entries = resolve_compose_recipe_entries(
            &options,
            Some(&manifest),
            Some(&manifest_value),
            &prompt,
        )
        .unwrap();
        assert_eq!(entries.len(), 2);
        let plan = build_composite_plan_from_entries(
            &options,
            &prompt,
            &entries,
            manifest.smoke.as_deref(),
        )
        .unwrap();
        validate_plan(&plan).unwrap();

        assert!(plan.operations.iter().any(|operation| {
            operation.parent_path.as_deref() == Some("Workspace")
                && operation.name.as_deref() == Some("CandyFactory")
        }));
        let tycoon_config = plan
            .operations
            .iter()
            .find(|operation| {
                operation.source_path.as_deref()
                    == Some("generated/tycooncore/TycoonConfig.module.lua")
            })
            .and_then(|operation| operation.attributes.get("rsGeneratedSource"))
            .and_then(Value::as_str)
            .unwrap();
        assert!(tycoon_config.contains("Sweets"));
        assert!(tycoon_config.contains("dropValue = 25"));
        assert!(tycoon_config.contains("upgradePrice = 75"));
        let shop_config = plan
            .operations
            .iter()
            .find(|operation| {
                operation.source_path.as_deref()
                    == Some("generated/startershop/ShopConfig.module.lua")
            })
            .and_then(|operation| operation.attributes.get("rsGeneratedSource"))
            .and_then(Value::as_str)
            .unwrap();
        assert!(shop_config.contains("Sugar Rush"));
        assert!(shop_config.contains("Sweets"));
    }

