    #[test]
    fn preview_integrity_rejects_modified_generated_files() {
        let run_dir = PathBuf::from("target").join("autopilot-preview-integrity-test");
        let _ = std::fs::remove_dir_all(&run_dir);
        std::fs::create_dir_all(&run_dir).unwrap();
        let plan = build_starter_shop_plan(
            &PlanOptions {
                port: 7878,
                prompt: Some("shop".into()),
                studio: None,
                scope: "game".into(),
                out: Some(run_dir.clone()),
                max_read_depth: 3,
                include_scripts: false,
                include_assets: false,
                recipe: None,
                from_manifest: None,
                json: false,
            },
            None,
            "shop",
        )
        .unwrap();
        write_generated_files(&plan, &run_dir).unwrap();
        let plan = strip_generated_sources(plan);
        write_json(run_dir.join("plan.json"), &plan).unwrap();
        let mut preview = build_preview(&plan);
        attach_preview_integrity(&mut preview, &plan, &run_dir).unwrap();
        write_json(run_dir.join("preview.json"), &preview).unwrap();

        assert!(verify_preview_integrity(&run_dir, &plan, &run_dir)
            .unwrap()
            .is_empty());
        std::fs::write(
            run_dir.join("generated").join("ShopServer.server.lua"),
            "-- changed after preview\n",
        )
        .unwrap();
        let err = verify_preview_integrity(&run_dir, &plan, &run_dir).unwrap_err();
        assert!(err.to_string().contains("generated files changed"));
    }

