    #[test]
    fn reconcile_matches_context_paths_and_refreshes_bundle() {
        let run_dir = PathBuf::from("target").join("autopilot-reconcile-aligned-test");
        let _ = std::fs::remove_dir_all(&run_dir);
        let (plan, bundle_path) = write_bundle_fixture(&run_dir);
        let planned_paths = created_paths_for_plan(&plan);
        let context_path = run_dir.join("context").join("context.json");
        let out = run_dir.join("reconcile.json");
        let markdown = run_dir.join("reconcile.md");
        write_json(
            context_path.clone(),
            &json!({
                "schemaVersion": "rs.agentContext.v1",
                "studio": "Demo Place",
                "path": "game",
                "snapshot": {
                    "rootPath": "game",
                    "paths": planned_paths,
                    "topSubtrees": []
                },
                "validation": {"diagnostics": []},
                "deps": {"scripts": [], "remotes": [], "dependencies": [], "unownedInstances": []}
            }),
        )
        .unwrap();

        reconcile(ReconcileOptions {
            run_dir: run_dir.clone(),
            survey: None,
            context: Some(context_path),
            out: Some(out.clone()),
            markdown: Some(markdown.clone()),
            no_markdown: false,
            json: false,
        })
        .unwrap();

        let value = read_json_file(&out).unwrap();
        assert_eq!(value["schemaVersion"], "rs.autopilot.reconcile.v1");
        assert_eq!(value["status"], "aligned");
        assert_eq!(
            value["matchedPathCount"].as_u64().unwrap(),
            created_paths_for_plan(&plan).len() as u64
        );
        assert!(value["missingPaths"].as_array().unwrap().is_empty());
        assert!(value["nextActions"]
            .as_array()
            .unwrap()
            .iter()
            .any(|action| action["command"]
                .as_str()
                .is_some_and(|command| command.contains("autopilot evidence"))));
        let markdown_text = std::fs::read_to_string(markdown).unwrap();
        assert!(markdown_text.contains("# Autopilot Reconciliation"));
        assert!(markdown_text.contains("Path Match"));
        let verification = verify_bundle_report(&bundle_path, Some(&run_dir)).unwrap();
        assert!(verification.ok);
        assert!(!verification
            .extra
            .iter()
            .any(|path| path.contains("reconcile")));
    }

