    #[test]
    fn live_gate_requires_live_ready_even_after_approval() {
        let root = PathBuf::from("target").join("autopilot-live-gate-tycoon-test");
        let run_dir = root.join("tycoon");
        let _ = std::fs::remove_dir_all(&root);
        start(StartOptions {
            port: 7878,
            prompt: Some("make a tycoon with shop and saves".into()),
            studio: None,
            scope: "game".into(),
            root: root.clone(),
            run_dir: Some(run_dir.clone()),
            limit: 5,
            assume: false,
            smoke: Some("regression".into()),
            out: Some(root.join("start.json")),
            markdown: None,
            no_markdown: true,
            json: false,
        })
        .unwrap();
        let out = run_dir.join("live-gate.json");
        let markdown = run_dir.join("live-gate.md");

        live_gate(LiveGateOptions {
            port: 7878,
            run_dir: Some(run_dir.clone()),
            session: None,
            studio: None,
            approved: true,
            skip_ready: true,
            timeout_secs: 2,
            poll_ms: 100,
            required_capabilities: Vec::new(),
            out: Some(out.clone()),
            markdown: Some(markdown.clone()),
            no_markdown: false,
            json: false,
        })
        .unwrap();

        let value = read_json_file(&out).unwrap();
        assert_eq!(value["schemaVersion"], "rs.autopilot.live-gate.v1");
        assert_eq!(value["status"], "needsLiveReadiness");
        assert_eq!(value["approved"], true);
        assert_eq!(value["readyOk"], Value::Null);
        assert_eq!(value["approvalStatus"], "readyForApproval");
        assert_eq!(value["privacyStatus"], "pass");
        assert_eq!(value["bundleOk"], true);
        assert!(value["checks"]
            .as_array()
            .unwrap()
            .iter()
            .any(|check| check["id"] == "live-readiness" && check["status"] == "skipped"));
        assert!(value["nextActions"]
            .as_array()
            .unwrap()
            .iter()
            .any(|action| action["command"]
                .as_str()
                .is_some_and(|command| command.contains("autopilot ready"))));
        let markdown_text = std::fs::read_to_string(markdown).unwrap();
        assert!(markdown_text.contains("# Autopilot Live Gate"));
        assert!(markdown_text.contains("Live Studio Readiness"));
    }

    #[test]
    fn rehearsal_builds_non_mutating_live_demo_runbook() {
        let root = PathBuf::from("target").join("autopilot-rehearsal-tycoon-test");
        let run_dir = root.join("tycoon");
        let _ = std::fs::remove_dir_all(&root);
        start(StartOptions {
            port: 7878,
            prompt: Some("make a tycoon with shop and saves".into()),
            studio: Some("Demo Place".into()),
            scope: "game".into(),
            root: root.clone(),
            run_dir: Some(run_dir.clone()),
            limit: 5,
            assume: false,
            smoke: Some("regression".into()),
            out: Some(root.join("start.json")),
            markdown: None,
            no_markdown: true,
            json: false,
        })
        .unwrap();
        let out = run_dir.join("rehearsal.json");
        let markdown = run_dir.join("rehearsal.md");

        rehearsal(RehearsalOptions {
            run_dir: run_dir.clone(),
            out: Some(out.clone()),
            markdown: Some(markdown.clone()),
            no_markdown: false,
            json: false,
        })
        .unwrap();

        let value = read_json_file(&out).unwrap();
        assert_eq!(value["schemaVersion"], "rs.autopilot.rehearsal.v1");
        assert_eq!(value["status"], "readyForApproval");
        assert_eq!(value["mutatesStudio"], false);
        assert!(value["runbookSteps"]
            .as_array()
            .unwrap()
            .iter()
            .any(|step| {
                step["phase"] == "apply"
                    && step["mutatesStudio"] == true
                    && step["command"]
                        .as_str()
                        .is_some_and(|command| command.contains("rs autopilot apply"))
            }));
        assert!(value["runbookSteps"]
            .as_array()
            .unwrap()
            .iter()
            .any(|step| {
                step["phase"] == "gate"
                    && step["command"].as_str().is_some_and(|command| {
                        command.contains("live-gate") && command.contains("--approved")
                    })
            }));
        assert!(value["doNotSay"]
            .as_array()
            .unwrap()
            .iter()
            .any(|claim| claim
                .as_str()
                .is_some_and(|claim| claim.contains("rehearsal applied"))));
        assert!(run_dir.join("showcase.json").exists());
        assert!(run_dir.join("evidence-kit.json").exists());
        assert!(run_dir.join("live-gate.json").exists());
        assert!(run_dir.join("closeout.json").exists());
        assert!(!run_dir.join("apply.json").exists());
        let markdown_text = std::fs::read_to_string(markdown).unwrap();
        assert!(markdown_text.contains("# Autopilot Rehearsal"));
        assert!(markdown_text.contains("Runbook"));
    }

