    #[test]
    fn companion_combines_proposal_and_setup_without_selection() {
        let root = PathBuf::from("target").join("autopilot-companion-tycoon-test");
        let _ = std::fs::remove_dir_all(&root);
        let companion_path = root.join("companion.json");
        let companion_markdown = root.join("companion.md");
        let proposal_path = root.join("companion-proposal.json");
        let proposal_markdown = root.join("companion-proposal.md");
        let setup_path = root.join("companion-setup.json");
        let setup_markdown = root.join("companion-setup.md");
        let options = CompanionOptions {
            port: 7878,
            prompt: Some("make a tycoon with shop and saves".into()),
            studio: Some("Place1".into()),
            scope: "game".into(),
            root: root.clone(),
            max_candidates: 3,
            fix: false,
            timeout_secs: 2,
            poll_ms: 1000,
            out: Some(companion_path.clone()),
            markdown: Some(companion_markdown.clone()),
            no_markdown: false,
            json: false,
        };
        let proposal = build_proposal_report(
            &ProposalOptions {
                prompt: options.prompt.clone(),
                studio: options.studio.clone(),
                scope: options.scope.clone(),
                root: options.root.clone(),
                max_candidates: options.max_candidates,
                out: Some(proposal_path.clone()),
                markdown: Some(proposal_markdown.clone()),
                no_markdown: false,
                json: false,
            },
            &proposal_path,
            Some(&proposal_markdown),
        )
        .unwrap();
        let required = autopilot_required_capabilities();
        let ready = build_ready_report(
            options.studio.as_deref(),
            &required,
            vec![StudioInfo {
                id: "studio-1".into(),
                name: "Place1".into(),
                place_file_path: None,
                protocol_version: None,
                plugin_version: None,
                capabilities: Vec::new(),
                last_heartbeat_ms_ago: 25,
            }],
            10,
        );
        let setup = build_setup_report(
            &SetupOptions {
                port: options.port,
                studio: options.studio.clone(),
                fix: false,
                timeout_secs: options.timeout_secs,
                poll_ms: options.poll_ms,
                required_capabilities: required,
                out: Some(setup_path.clone()),
                markdown: Some(setup_markdown.clone()),
                no_markdown: false,
                json: false,
            },
            &setup_path,
            Some(&setup_markdown),
            ready,
            None,
        );

        let report = build_companion_report_from_parts(
            &options,
            &companion_path,
            Some(&companion_markdown),
            &proposal_path,
            &setup_path,
            proposal,
            setup,
        );

        assert_eq!(report.schema_version, "rs.autopilot.companion.v1");
        assert_eq!(report.status, "readyForCreatorChoiceSetupBlocked");
        assert_eq!(report.recommended_candidate_id.as_deref(), Some("direct"));
        assert!(!report.setup_ready);
        assert!(report.next_actions.iter().any(|action| action
            .command
            .as_deref()
            .is_some_and(|command| command.contains("autopilot select"))));
        assert!(report.next_actions.iter().any(|action| action
            .command
            .as_deref()
            .is_some_and(|command| command.contains("autopilot launch"))));
        assert!(report
            .do_not_say
            .iter()
            .any(|claim| claim.contains("creator selected")));
        let markdown_text = render_companion_markdown(&report);
        assert!(markdown_text.contains("# Autopilot Companion"));
        assert!(markdown_text.contains("Record creator choice"));
    }

