        assert!(value["safeToSay"]
            .as_array()
            .unwrap()
            .iter()
            .any(|claim| claim
                .as_str()
                .is_some_and(|text| text.contains("redacted, bounded context"))));
        assert!(value["doNotSay"]
            .as_array()
            .unwrap()
            .iter()
            .any(|claim| claim
                .as_str()
                .is_some_and(|text| text.contains("model-pack snippets"))));
        assert!(value["nextActions"]
            .as_array()
            .unwrap()
            .iter()
            .any(|action| action["command"]
                .as_str()
                .is_some_and(|command| command.contains("autopilot model-pack"))));
        let serialized = serde_json::to_string(&value).unwrap();
