    #[test]
    fn remember_consolidates_demo_learning_into_project_context() {
        let root = PathBuf::from("target").join("autopilot-remember-test");
        let run_dir = root.join("tycoon");
        let _ = std::fs::remove_dir_all(&root);
        start(StartOptions {
            port: 7878,
            prompt: Some("make a tycoon with shop and saves".into()),
            studio: None,
            scope: "Workspace".into(),
            root: root.clone(),
            run_dir: Some(run_dir.clone()),
            limit: 5,
            assume: false,
            smoke: None,
            out: Some(root.join("start.json")),
            markdown: None,
            no_markdown: true,
            json: false,
        })
        .unwrap();
        demo_loop(DemoLoopOptions {
            messages: vec!["Looks good but make the shop button brighter".into()],
            idea: None,
            run_dir: run_dir.clone(),
            root: root.clone(),
            limit: 5,
            max_ideas: 4,
            max_chars: 16_000,
            dry_run: false,
            out: Some(run_dir.join("demo-loop.json")),
            markdown: None,
            no_markdown: true,
            json: false,
        })
        .unwrap();

        let out = run_dir.join("remember.json");
        let markdown = run_dir.join("remember.md");
        remember(RememberOptions {
            run_dir: run_dir.clone(),
            root: root.clone(),
            limit: 10,
            best_friend: true,
            opportunity: Some("Record AI work journal".into()),
            max_chars: 12_000,
            out: Some(out.clone()),
            markdown: Some(markdown.clone()),
            no_markdown: false,
            json: false,
        })
        .unwrap();

        let value = read_json_file(&out).unwrap();
        assert_eq!(value["schemaVersion"], "rs.autopilot.remember.v1");
        assert!(matches!(
            value["status"].as_str(),
            Some("ready" | "readyWithWarnings")
        ));
        assert_eq!(value["demoLearnStatus"], "ready");
        assert!(value["consolidatedArtifacts"]
            .as_array()
            .unwrap()
            .iter()
            .any(|artifact| artifact["id"] == "aiPlaybook"));
        assert!(root.join("project-memory.json").exists());
        assert!(root.join("creator-preferences.json").exists());
        assert!(root.join("game-bible.json").exists());
        assert!(root.join("ai-playbook.json").exists());
        let preferences_value = read_json_file(&root.join("creator-preferences.json")).unwrap();
        assert!(preferences_value["signals"]
            .as_array()
            .unwrap()
            .iter()
            .any(|signal| signal["kind"] == "demoPreference"
                && signal["text"]
                    .as_str()
                    .is_some_and(|text| text.contains("shop button brighter"))));
        let next_actions = value["nextActions"].as_array().unwrap();
        assert_eq!(
            next_actions[0]["title"],
            "Execute first checked action through act"
        );
        assert!(next_actions[0]["command"].as_str().is_some_and(|command| {
            command.contains("autopilot act") && command.contains("autopilot journal")
        }));
        assert!(next_actions.iter().any(|action| {
            action["title"] == "Launch next AI best-friend packet"
                && action["command"].as_str().is_some_and(|command| {
                    command.contains("autopilot best-friend")
                        && command.contains("--root")
                        && command.contains("--format json")
                })
        }));
        assert!(value["agentBrief"]
            .as_str()
            .is_some_and(|text| text.contains("next default continuation")));
        assert_eq!(value["bestFriendStatus"], "readyForAgentTask");
        assert!(value["bestFriendPath"]
            .as_str()
            .is_some_and(|path| path.ends_with("best-friend.json")));
        assert!(run_dir.join("best-friend.json").exists());
        assert!(run_dir.join("best-friend.md").exists());
        let best_friend_value = read_json_file(&run_dir.join("best-friend.json")).unwrap();
        assert_eq!(
            best_friend_value["schemaVersion"],
            "rs.autopilot.best-friend.v1"
        );
        assert!(best_friend_value["openingReply"]
            .as_str()
            .is_some_and(|text| text.contains("Next checked offline move")));
        let markdown_text = std::fs::read_to_string(markdown).unwrap();
        assert!(markdown_text.contains("# Autopilot Remember"));
        assert!(markdown_text.contains("Launch next AI best-friend packet"));
        assert!(markdown_text.contains("Best-friend packet"));
    }

