    #[test]
    fn review_pack_refreshes_creator_review_artifacts() {
        let root = PathBuf::from("target").join("autopilot-review-pack-tycoon-test");
        let run_dir = root.join("tycoon");
        let _ = std::fs::remove_dir_all(&root);
        start(StartOptions {
            port: 7878,
            prompt: Some("make a tycoon with shop and saves".into()),
            studio: Some("Demo Place".into()),
            scope: "Workspace".into(),
            root: root.clone(),
            run_dir: Some(run_dir.clone()),
            limit: 5,
            assume: false,
            smoke: None,
            out: Some(root.join("start.json")),
            markdown: None,
            no_markdown: true,
            json: false,
        })
        .unwrap();

        let out = run_dir.join("review-pack.json");
        let markdown = run_dir.join("review-pack.md");
        review_pack(ReviewPackOptions {
            run_dir: run_dir.clone(),
            out: Some(out.clone()),
            markdown: Some(markdown.clone()),
            no_markdown: false,
            create_evidence_dirs: true,
            json: false,
        })
        .unwrap();

        let value = read_json_file(&out).unwrap();
        assert_eq!(value["schemaVersion"], "rs.autopilot.review-pack.v1");
        assert_eq!(value["status"], "readyForCreatorReview");
        assert_eq!(value["safeToPresent"], true);
        assert_eq!(value["approvalStatus"], "readyForApproval");
        assert_eq!(value["privacyStatus"], "pass");
        assert_eq!(value["evidenceStatus"], "needsLiveApply");
        assert!(value["artifacts"]["evidenceKit"]
            .as_str()
            .is_some_and(|path| path.ends_with("evidence-kit.json")));
        assert!(value["artifacts"]["capsule"]
            .as_str()
            .is_some_and(|path| path.ends_with("agent-capsule.json")));
        assert!(value["decisions"]
            .as_array()
            .unwrap()
            .iter()
            .any(
                |decision| decision["id"] == "creator-approval" && decision["status"] == "pending"
            ));
        assert!(value["nextActions"]
            .as_array()
            .unwrap()
            .iter()
            .any(|action| action["command"]
                .as_str()
                .is_some_and(|command| command.contains("autopilot review-pack"))));
        let markdown_text = std::fs::read_to_string(markdown).unwrap();
        assert!(markdown_text.contains("# Autopilot Review Pack"));
        assert!(markdown_text.contains("## Decisions"));
        assert!(run_dir.join("evidence-kit.json").exists());
        assert!(run_dir.join("agent-capsule.json").exists());
        assert!(run_dir.join("approval.json").exists());

        let verification =
            verify_bundle_report(&run_dir.join("bundle.json"), Some(&run_dir)).unwrap();
        assert!(verification.ok);
        assert!(!verification
            .extra
            .iter()
            .any(|path| path.contains("review-pack")
                || path.contains("evidence")
                || path.contains("agent-capsule")));
    }

