    #[test]
    fn publish_prep_blocks_release_without_live_proof_but_writes_store_draft() {
        let run_dir = PathBuf::from("target").join("autopilot-publish-prep-live-proof-test");
        let _ = std::fs::remove_dir_all(&run_dir);
        let (plan, bundle_path) = write_bundle_fixture(&run_dir);
        write_publish_prep_hard_gate_artifacts(&run_dir, &plan, &bundle_path);
        let out = run_dir.join("publish-prep.json");
        let markdown = run_dir.join("publish-prep.md");

        publish_prep(PublishPrepOptions {
            run_dir: run_dir.clone(),
            out: Some(out.clone()),
            markdown: Some(markdown.clone()),
            no_markdown: false,
            json: false,
        })
        .unwrap();

        let value = read_json_file(&out).unwrap();
        assert_eq!(value["schemaVersion"], "rs.autopilot.publish-prep.v1");
        assert_eq!(value["status"], "needsLiveProof");
        assert_eq!(value["launchReadiness"], "creatorReviewReady");
        assert_eq!(value["storeTitle"], "Shop");
        assert!(value["storeDescription"]
            .as_str()
            .is_some_and(|text| text.contains("creator review")));
        assert!(value["checklist"]
            .as_array()
            .unwrap()
            .iter()
            .any(|check| check["id"] == "health" && check["status"] == "missing"));
        assert!(value["blockers"]
            .as_array()
            .unwrap()
            .iter()
            .any(|blocker| blocker.as_str().is_some_and(|text| text.contains("health"))));
        let markdown_text = std::fs::read_to_string(markdown).unwrap();
        assert!(markdown_text.contains("# Autopilot Publish Prep"));
        assert!(markdown_text.contains("Store Draft"));

        let verification = verify_bundle_report(&bundle_path, Some(&run_dir)).unwrap();
        assert!(verification.ok);
        assert!(read_json_file(&bundle_path).unwrap()["artifacts"]
            .as_array()
            .unwrap()
            .iter()
            .any(|artifact| artifact["path"] == "publish-prep.json"
                && artifact["kind"] == "publishPrep"));
        assert!(!verification
            .extra
            .iter()
            .any(|path| path.contains("publish-prep")));
    }

