    #[test]
    fn proof_ledger_maps_offline_run_to_missing_live_evidence() {
        let root = PathBuf::from("target").join("autopilot-proof-tycoon-test");
        let run_dir = root.join("tycoon");
        let _ = std::fs::remove_dir_all(&root);
        start(StartOptions {
            port: 7878,
            prompt: Some("make a tycoon with shop and saves".into()),
            studio: None,
            scope: "Workspace".into(),
            root: root.clone(),
            run_dir: Some(run_dir.clone()),
            limit: 5,
            assume: false,
            smoke: None,
            out: Some(root.join("start.json")),
            markdown: None,
            no_markdown: true,
            json: false,
        })
        .unwrap();

        let out = run_dir.join("proof.json");
        let markdown = run_dir.join("proof.md");
        proof(ProofOptions {
            run_dir: run_dir.clone(),
            out: Some(out.clone()),
            markdown: Some(markdown.clone()),
            no_markdown: false,
            json: false,
        })
        .unwrap();

        let value = read_json_file(&out).unwrap();
        assert_eq!(value["schemaVersion"], "rs.autopilot.proof.v1");
        assert_eq!(value["productionReady"], false);
        assert!(value["claimReady"]
            .as_array()
            .unwrap()
            .iter()
            .any(|claim| claim
                .as_str()
                .is_some_and(|text| text.contains("structurally valid"))));
        assert!(value["doNotClaim"]
            .as_array()
            .unwrap()
            .iter()
            .any(|claim| claim
                .as_str()
                .is_some_and(|text| text.contains("production-ready"))));
        assert!(value["evidence"]
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item["id"] == "plan schema" && item["status"] == "pass"));
        assert!(value["evidence"]
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item["id"] == "playtest-result" && item["status"] == "missing"));
        assert!(value["missingProof"]
            .as_array()
            .unwrap()
            .iter()
            .any(|item| item
                .as_str()
                .is_some_and(|text| text.contains("playtest-result"))));
        assert!(markdown.exists());

        let verification =
            verify_bundle_report(&run_dir.join("bundle.json"), Some(&run_dir)).unwrap();
        assert!(verification.ok);
        assert!(!verification.extra.iter().any(|path| path.contains("proof")));
    }

