        assert!(improved_run.join("gameplay-critique.json").exists());
        assert!(improved_run.join("playtest-plan.json").exists());
        assert!(source_run.join("gameplay-critique.json").exists());
        let plan = read_plan(&improved_run.join("plan.json")).unwrap();
        assert!(recipes_for_run(&improved_run, &plan)
            .unwrap()
            .contains(&"tycoonCore".to_string()));
