    #[test]
    fn passed_playtest_result_allows_judgment_production_ready_after_apply_and_rollback() {
        let source_run = PathBuf::from("target").join("autopilot-judge-proof-source-test");
        let patch_run = PathBuf::from("target").join("autopilot-judge-proof-patch-test");
        let _ = std::fs::remove_dir_all(&source_run);
        let _ = std::fs::remove_dir_all(&patch_run);
        write_bundle_fixture(&source_run);
        improve(ImproveOptions {
            port: 7878,
            run_dir: Some(source_run),
            plan: None,
            out: Some(patch_run.clone()),
            markdown: None,
            no_markdown: true,
            recipes: vec!["tycoonCore".into()],
            max_recipes: 1,
            smoke: None,
            json: false,
        })
        .unwrap();

        let plan = read_plan(&patch_run.join("plan.json")).unwrap();
        let rollback_path = patch_run.join("rollback-snapshot.json");
        write_json(rollback_path.clone(), &json!({"ok": true})).unwrap();
        write_json(
            patch_run.join("apply.json"),
            &json!({
                "status": "applied",
                "planId": plan.id,
                "studio": null,
                "scope": "game",
                "applied": 3,
                "skipped": 0,
                "refused": 0,
                "changedPaths": ["Workspace.Tycoon"],
                "warnings": [],
                "rollbackArtifact": rollback_path.to_string_lossy().to_string(),
                "rollbackRestore": null,
                "validationAfter": null,
                "smoke": null,
                "error": null
            }),
        )
        .unwrap();
        certify(CertifyOptions {
            run_dir: patch_run.clone(),
            out: None,
            markdown: None,
            no_markdown: true,
            json: false,
        })
        .unwrap();
        record_playtest(RecordPlaytestOptions {
            run_dir: patch_run.clone(),
            result: "passed".into(),
            evidence: vec!["cash increased, upgrade purchased, no Studio output errors".into()],
            notes: vec!["Play Solo completed tycoon loop".into()],
            scenarios: vec!["tycoonCore=passed".into()],
            out: None,
            markdown: None,
            no_markdown: true,
            json: false,
        })
        .unwrap();
        let out = patch_run.join("judgment.json");
        judge(JudgeOptions {
            run_dir: patch_run.clone(),
            out: Some(out.clone()),
            markdown: None,
            no_markdown: true,
            json: false,
        })
        .unwrap();

        let value = read_json_file(&out).unwrap();
        assert_eq!(value["status"], "productionReady");
        assert_eq!(value["verdict"], "demoReady");
        assert_eq!(value["productionReady"], true);
        assert_eq!(value["liveApplyVerified"], true);
        assert_eq!(value["rollbackVerified"], true);
        assert_eq!(value["playtestResult"]["productionProof"], true);
    }

