    #[test]
    fn health_marks_applied_run_healthy_with_validation_smoke_rollback_and_playtest() {
        let run_dir = write_applied_playable_run("autopilot-health-pass-test", true);
        let out = run_dir.join("health.json");

        health(HealthOptions {
            run_dir: run_dir.clone(),
            out: Some(out.clone()),
            markdown: None,
            no_markdown: true,
            json: false,
        })
        .unwrap();

        let value = read_json_file(&out).unwrap();
        assert_eq!(value["schemaVersion"], "rs.autopilot.health.v1");
        assert_eq!(value["status"], "appliedAndHealthy");
        assert_eq!(value["verdict"], "healthy");
        assert_eq!(value["appliedAndHealthy"], true);
        assert!(value["mandatorySmokeSuites"]
            .as_array()
            .unwrap()
            .iter()
            .any(|suite| suite == "regression"));
        for id in [
            "apply",
            "validation-after",
            "smoke-regression",
            "rollback-artifact",
            "playtest-result",
            "proof-ledger",
        ] {
            assert!(
                value["checks"]
                    .as_array()
                    .unwrap()
                    .iter()
                    .any(|check| { check["id"] == id && check["status"] == "pass" }),
                "missing passing health check {id}"
            );
        }
        assert!(value["safeToSay"]
            .as_array()
            .unwrap()
            .iter()
            .any(|claim| claim
                .as_str()
                .is_some_and(|text| text.contains("applied-and-healthy"))));
        assert!(run_dir.join("proof.json").exists());
        assert!(run_dir.join("judgment.json").exists());
        assert!(run_dir.join("rollback.json").exists());
    }

    #[test]
    fn architect_report_stages_tycoon_prompt_without_live_studio() {
        let root = PathBuf::from("target").join("autopilot-architect-tycoon-test");
        let _ = std::fs::remove_dir_all(&root);
        let report = build_architect_report(
            "make a tycoon with droppers and upgrades",
            &root,
            5,
            &root.join("architect.json"),
            Some(&root.join("architect.md")),
            Some("regression"),
        )
        .unwrap();

        assert_eq!(report.schema_version, "rs.autopilot.architect.v1");
        assert_eq!(
            report.intent.recommended_preset.as_deref(),
            Some("tycoonPrototype")
        );
        assert!(report
            .recipe_stack
            .iter()
            .any(|recipe| recipe.recipe == "tycoonCore" && recipe.role == "core-loop"));
        assert!(report
            .phases
            .iter()
            .any(|phase| phase.name == "Check Live Readiness"
                && phase.requires_live_studio
                && !phase.mutates_studio));
        assert!(report
            .phases
            .iter()
            .any(|phase| phase.name == "Apply With Rollback"
                && phase.requires_live_studio
                && phase.mutates_studio
                && phase
                    .command
                    .as_deref()
                    .is_some_and(|command| command.contains("--smoke regression"))));
        assert!(report.blockers.is_empty());
    }

