    #[test]
    fn certification_marks_clean_handoff_ready_to_apply() {
        let run_dir = PathBuf::from("target").join("autopilot-certify-ready-test");
        write_bundle_fixture(&run_dir);
        handoff(HandoffOptions {
            run_dir: run_dir.clone(),
            out: Some(run_dir.join("handoff.json")),
            markdown: Some(run_dir.join("handoff.md")),
            no_markdown: false,
            json: false,
        })
        .unwrap();
        let certification_path = run_dir.join("certification.json");
        let markdown_path = run_dir.join("certification.md");

        certify(CertifyOptions {
            run_dir: run_dir.clone(),
            out: Some(certification_path.clone()),
            markdown: Some(markdown_path.clone()),
            no_markdown: false,
            json: false,
        })
        .unwrap();

        let value = read_json_file(&certification_path).unwrap();
        assert_eq!(value["schemaVersion"], "rs.autopilot.certification.v1");
        assert_eq!(value["readyToApply"], true);
        assert_eq!(value["safeToHandoff"], true);
        assert_eq!(value["verdict"], "warn");
        assert!(value["gates"]
            .as_array()
            .unwrap()
            .iter()
            .any(|gate| { gate["name"] == "bundle verification" && gate["status"] == "pass" }));
        assert!(value["nextActions"]
            .as_array()
            .unwrap()
            .iter()
            .any(|action| {
                action["mutatesStudio"] == true
                    && action["command"]
                        .as_str()
                        .is_some_and(|command| command.contains("autopilot apply"))
            }));
        let markdown = std::fs::read_to_string(markdown_path).unwrap();
        assert!(markdown.contains("## Gates"));
        assert!(markdown.contains("preview integrity"));
    }

    #[test]
    fn certification_blocks_preview_and_bundle_drift() {
        let run_dir = PathBuf::from("target").join("autopilot-certify-drift-test");
        write_bundle_fixture(&run_dir);
        std::fs::write(
            run_dir.join("generated").join("ShopServer.server.lua"),
            "-- changed after preview\n",
        )
        .unwrap();
        let certification_path = run_dir.join("certification.json");

        certify(CertifyOptions {
            run_dir: run_dir.clone(),
            out: Some(certification_path.clone()),
            markdown: None,
            no_markdown: true,
            json: false,
        })
        .unwrap();

        let value = read_json_file(&certification_path).unwrap();
        assert_eq!(value["verdict"], "fail");
        assert_eq!(value["readyToApply"], false);
        assert!(value["gates"]
            .as_array()
            .unwrap()
            .iter()
            .any(|gate| { gate["name"] == "preview integrity" && gate["status"] == "fail" }));
        assert!(value["gates"]
            .as_array()
            .unwrap()
            .iter()
            .any(|gate| { gate["name"] == "bundle verification" && gate["status"] == "fail" }));
        assert!(value["nextActions"]
            .as_array()
            .unwrap()
            .iter()
            .all(|action| action["mutatesStudio"] == false));
    }

