    fn write_bundle_fixture(run_dir: &Path) -> (AutopilotPlan, PathBuf) {
        let _ = std::fs::remove_dir_all(run_dir);
        std::fs::create_dir_all(run_dir).unwrap();
        let plan = build_starter_shop_plan(
            &PlanOptions {
                port: 7878,
                prompt: Some("shop".into()),
                studio: None,
                scope: "game".into(),
                out: Some(run_dir.to_path_buf()),
                max_read_depth: 3,
                include_scripts: false,
                include_assets: false,
                recipe: None,
                from_manifest: None,
                json: false,
            },
            None,
            "shop",
        )
        .unwrap();
        write_generated_files(&plan, run_dir).unwrap();
        let plan = strip_generated_sources(plan);
        write_json(run_dir.join("request.json"), &json!({"prompt": "shop"})).unwrap();
        write_json(run_dir.join("context.json"), &json!({})).unwrap();
        write_json(run_dir.join("preflight.json"), &json!({})).unwrap();
        write_json(run_dir.join("plan.json"), &plan).unwrap();
        let mut preview = build_preview(&plan);
        attach_preview_integrity(&mut preview, &plan, run_dir).unwrap();
        write_json(run_dir.join("preview.json"), &preview).unwrap();
        std::fs::write(run_dir.join("report.md"), "report").unwrap();
        let bundle_path = run_dir.join("bundle.json");
        let report =
            build_bundle_report(run_dir, &bundle_path, &run_dir.join("plan.json"), &plan).unwrap();
        write_json(bundle_path.clone(), &report).unwrap();
        (plan, bundle_path)
    }

    #[test]
    fn ready_report_requires_protocol_and_capabilities() {
        let required = autopilot_required_capabilities();
        let not_ready = build_ready_report(
            Some("Place1"),
            &required,
            vec![StudioInfo {
                id: "studio-1".into(),
                name: "Place1".into(),
                place_file_path: None,
                protocol_version: None,
                plugin_version: None,
                capabilities: Vec::new(),
                last_heartbeat_ms_ago: 25,
            }],
            10,
        );
        assert!(!not_ready.ok);
        assert_eq!(not_ready.status, "waiting");
        assert!(not_ready
            .selected_studio
            .as_ref()
            .is_some_and(|studio| !studio.ready));

        let ready = build_ready_report(
            None,
            &required,
            vec![StudioInfo {
                id: "studio-2".into(),
                name: "Ready Place".into(),
                place_file_path: None,
                protocol_version: Some(PLUGIN_PROTOCOL_VERSION),
                plugin_version: Some("0.1.0".into()),
                capabilities: required.clone(),
                last_heartbeat_ms_ago: 10,
            }],
            20,
        );
        assert!(ready.ok);
        assert_eq!(ready.status, "ready");
        assert!(ready.blockers.is_empty());
    }

    #[test]
    fn setup_packet_turns_plugin_readiness_into_repair_actions() {
        let required = autopilot_required_capabilities();
        let ready = build_ready_report(
            Some("Place1"),
            &required,
            vec![StudioInfo {
                id: "studio-1".into(),
                name: "Place1".into(),
                place_file_path: None,
                protocol_version: None,
                plugin_version: None,
                capabilities: Vec::new(),
                last_heartbeat_ms_ago: 25,
            }],
            10,
        );
        let options = SetupOptions {
            port: 7878,
            studio: Some("Place1".into()),
            fix: false,
            timeout_secs: 10,
            poll_ms: 1000,
            required_capabilities: Vec::new(),
            out: None,
            markdown: None,
            no_markdown: false,
            json: false,
        };

        let report = build_setup_report(
            &options,
            Path::new("target/setup.json"),
            Some(Path::new("target/setup.md")),
            ready,
            None,
        );

        assert_eq!(report.schema_version, "rs.autopilot.setup.v1");
        assert!(!report.ready_ok);
        assert!(report
            .blockers
            .iter()
            .any(|blocker| blocker.contains("plugin protocol unknown")));
        assert!(report.next_actions.iter().any(|action| action
            .command
            .as_deref()
            .is_some_and(|command| command == "rs install-plugin")));
        assert!(report.next_actions.iter().any(|action| action
            .command
            .as_deref()
            .is_some_and(|command| command.contains("autopilot setup"))));
        assert!(report
            .do_not_say
            .iter()
            .any(|claim| claim.contains("plugin was installed")));
        let markdown = render_setup_markdown(&report);
        assert!(markdown.contains("# Autopilot Setup"));
        assert!(markdown.contains("Install current Studio plugin"));
    }

    #[test]
    fn setup_packet_after_fix_prioritizes_restart_over_reinstall() {
        let required = autopilot_required_capabilities();
        let ready = build_ready_report(
            Some("Place1"),
            &required,
            vec![StudioInfo {
                id: "studio-1".into(),
                name: "Place1".into(),
                place_file_path: None,
                protocol_version: None,
                plugin_version: None,
                capabilities: Vec::new(),
                last_heartbeat_ms_ago: 25,
            }],
            10,
        );
        let options = SetupOptions {
            port: 7878,
            studio: Some("Place1".into()),
            fix: true,
            timeout_secs: 10,
            poll_ms: 1000,
            required_capabilities: Vec::new(),
            out: None,
            markdown: None,
            no_markdown: false,
            json: false,
        };
        let fix_attempt = SetupFixAttempt {
            attempted: true,
            status: "installed".into(),
            built_plugin: Some("plugin/rs-bridge-plugin.rbxmx".into()),
            installed_plugin: Some("Roblox/Plugins/rs-bridge-plugin.rbxmx".into()),
            installed_hash: Some("abc123".into()),
            restart_studios: vec![SetupRestartStudio {
                id: "studio-1".into(),
                name: "Place1".into(),
                protocol_version: None,
                plugin_version: None,
                reason: "plugin bundle was reinstalled".into(),
            }],
            error: None,
        };

        let report = build_setup_report(
            &options,
            Path::new("target/setup.json"),
            Some(Path::new("target/setup.md")),
            ready,
            Some(fix_attempt),
        );

        assert_eq!(report.fix_attempt.as_ref().unwrap().status, "installed");
        assert!(report
            .next_actions
            .iter()
            .any(|action| action.command.is_none() && action.title == "Restart Roblox Studio"));
        assert!(!report.next_actions.iter().any(|action| action
            .command
            .as_deref()
            .is_some_and(|command| command == "rs install-plugin")));
        assert!(report.agent_brief.contains("Restart Studio"));
        let markdown = render_setup_markdown(&report);
        assert!(markdown.contains("Fix Attempt"));
    }

