    #[test]
    fn runbook_splits_safe_prefix_from_gated_suffix() {
        let root = PathBuf::from("target").join("autopilot-runbook-split-test");
        let run_dir = root.join("shop");
        let _ = std::fs::remove_dir_all(&root);
        std::fs::create_dir_all(&run_dir).unwrap();
        let out = run_dir.join("runbook.json");
        let markdown = run_dir.join("runbook.md");

        runbook(RunbookOptions {
            prompt: None,
            run_dir: Some(run_dir.clone()),
            root: root.clone(),
            limit: 10,
            max_steps: 6,
            commands: vec![
                format!("rs autopilot proof {} --format json", run_dir.display()),
                format!(
                    "rs autopilot apply --plan {} --yes --format json",
                    run_dir.join("plan.json").display()
                ),
            ],
            from_file: None,
            out: Some(out.clone()),
            markdown: Some(markdown.clone()),
            no_markdown: false,
            json: false,
        })
        .unwrap();

        let value = read_json_file(&out).unwrap();
        assert_eq!(value["schemaVersion"], "rs.autopilot.runbook.v1");
        assert_eq!(value["status"], "needsApproval");
        assert_eq!(value["safePrefixCount"], 1);
        assert_eq!(value["gatedSuffixCount"], 1);
        assert_eq!(value["unsupportedCount"], 0);
        assert_eq!(value["safeToRunPrefix"], true);
        assert!(value["safePrefix"][0]["command"]
            .as_str()
            .is_some_and(|command| command.contains("autopilot act")));
        assert_eq!(value["gatedSuffix"][0]["commandKind"], "apply");
        assert_eq!(value["gatedSuffix"][0]["mutatesStudio"], true);
        assert_eq!(value["guardSummary"]["status"], "needsApproval");
        assert!(run_dir.join("command-guard.json").exists());
        let markdown_text = std::fs::read_to_string(markdown).unwrap();
        assert!(markdown_text.contains("# Autopilot Execution Runbook"));
        assert!(markdown_text.contains("## Safe Offline Prefix"));
        assert!(markdown_text.contains("## Gated Suffix"));
    }

