    #[test]
    fn explain_report_recommends_apply_when_artifacts_exist() {
        let run_dir = PathBuf::from("target").join("autopilot-explain-test");
        let _ = std::fs::remove_dir_all(&run_dir);
        std::fs::create_dir_all(&run_dir).unwrap();
        let plan = build_starter_shop_plan(
            &PlanOptions {
                port: 7878,
                prompt: Some("shop".into()),
                studio: None,
                scope: "game".into(),
                out: Some(run_dir.clone()),
                max_read_depth: 3,
                include_scripts: false,
                include_assets: false,
                recipe: None,
                from_manifest: None,
                json: false,
            },
            None,
            "shop",
        )
        .unwrap();
        write_generated_files(&plan, &run_dir).unwrap();
        let plan = strip_generated_sources(plan);
        let report = build_explain_report(&run_dir.join("plan.json"), &plan);

        assert!(report.valid);
        assert!(report.blockers.is_empty());
        assert!(report
            .generated_files
            .contains(&"generated/ShopServer.server.lua".to_string()));
        assert!(report
            .recommended_next_commands
            .iter()
            .any(|command| command.contains("autopilot apply")));
    }
